def _loyalty_member_search(conn, q):
    """Member lookup shared by the storefront staff console and the ERP
    loyalty console. Accepts a QR URL (member=PAL:<id>), a raw PAL:<id>,
    an email, or a name. Max 20 results; each carries the live balance
    and tier from the customer kernel ledger."""
    q = (q or "").strip()
    if not q:
        return []
    # Accept a scanned member QR code (full URL with ?member=PAL:<id>),
    # a raw PAL:<user_id>, or email/name.
    qr_member = ""
    if "member=" in q:
        # Extract member=... from a scanned QR URL.
        try:
            qr_member = q.split("member=", 1)[1].split("&")[0].split("#")[0].strip()
        except IndexError:
            qr_member = ""
    pal = qr_member or q
    if pal.upper().startswith("PAL:"):
        try:
            uid = int(pal.split(":", 1)[1])
        except ValueError:
            uid = -1
        rows = conn.execute(
            "SELECT id, email, name FROM users WHERE id = ?", (uid,)
        ).fetchall()
    else:
        like = f"%{q}%"
        rows = conn.execute(
            "SELECT id, email, name FROM users WHERE email LIKE ? OR name LIKE ? LIMIT 20",
            (like, like),
        ).fetchall()
    members = []
    for r in rows:
        lifetime = _lifetime_kernels(conn, r["id"])
        members.append({
            "id": r["id"], "email": r["email"], "name": r["name"],
            "kernels": _kernel_balance(conn, r["id"]),
            "lifetime_kernels": lifetime,
            "tier": _loyalty_tier(conn, lifetime),
            "last_earn_multiplier_x100": _last_earn_multiplier(conn, r["id"]),
        })
    return members


