def _cron_send_due_newsletters():
    """SOP 8.21: send every approved newsletter issue whose scheduled_at
    has passed. Same Resend path as the manual send
    (_mkt_send_newsletter_issue): recipients are resolved at send time
    from the stored segment (SOP 8.20) or the full deduplicated audience,
    minus unsubscribes. An issue whose month has not started yet is
    skipped, never sent early (same 1st-of-month rule as the manual
    send). A failed send is written to the staff audit log
    (marketing.newsletter_send_failed) and the issue stays approved --
    never flipped to sent, never retried silently. One failure never
    blocks the rest of the sweep.
    """
    conn = db()
    now = datetime.now(timezone.utc)
    today = now.date().isoformat()
    due = conn.execute(
        "SELECT * FROM erp_mkt_newsletters WHERE status = 'approved'"
        " AND scheduled_at IS NOT NULL AND scheduled_at <= ?"
        " ORDER BY scheduled_at ASC", (now.isoformat(),)).fetchall()
    sent_issues = []
    sent_emails = 0
    failed = []
    skipped = []
    for row in due:
        issue = dict(row)
        if today < issue["issue_month"] + "-01":
            skipped.append({"id": issue["id"],
                            "reason": "planned send date is %s"
                            % (issue["issue_month"] + "-01")})
            continue
        already = _mkt_newsletter_already_sent(conn, issue)
        if already:
            conn.execute("UPDATE erp_mkt_newsletters SET status = 'sent',"
                         " sent_at = ?, recipient_count = ? WHERE id = ?",
                         (already[0], already[1],
                          issue["id"]))
            conn.commit()
            sent_issues.append({"id": issue["id"],
                                "sent": already[1],
                                "note": "already sent"})
            sent_emails += already[1] or 0
            continue
        try:
            count = _mkt_send_newsletter_issue(
                conn, issue, issue.get("segment_id"))
        except Exception as e:
            _erp_staff_audit(conn, "cron",
                             "marketing.newsletter_send_failed",
                             "newsletter", issue["id"], str(e))
            conn.commit()
            failed.append({"id": issue["id"], "error": str(e)})
            continue
        _erp_staff_audit(conn, "cron", "marketing.newsletter_sent",
                         "newsletter", issue["id"],
                         "%d recipients" % count)
        conn.commit()
        sent_issues.append({"id": issue["id"], "sent": count})
        sent_emails += count
    conn.close()
    return jsonify(ok=True, sent_issues=sent_issues, sent=sent_emails,
                   failed=failed, skipped=skipped)


@app.post("/api/cron/marketing/send")
def cron_marketing_send():
    """Cron: send a pre-defined marketing campaign to the deduplicated audience.

    Header X-Cron-Secret must equal the CRON_SECRET env var.
    Body: {"campaign_key": "<key from SCHEDULED_CAMPAIGNS>"}.
    Each key sends at most once (tracked in marketing_campaigns).
    With no campaign_key, the call instead sends every due scheduled
    newsletter issue (SOP 8.21 -- approved, scheduled_at passed).
    """
    if not CRON_SECRET:
        return jsonify(error="cron is not configured"), 503
    if request.headers.get("X-Cron-Secret", "") != CRON_SECRET:
        return jsonify(error="forbidden"), 403
    data = request.get_json(silent=True) or {}
    key = (data.get("campaign_key") or "").strip()
    if not key:
        return _cron_send_due_newsletters()
    campaign = SCHEDULED_CAMPAIGNS.get(key)
    if not campaign:
        return jsonify(error="unknown campaign_key"), 400
    conn = db()
    already = conn.execute(
        "SELECT id FROM marketing_campaigns WHERE name = ?", (campaign["name"],)).fetchone()
    if already:
        conn.close()
        return jsonify(ok=True, sent=0, note="already sent")
    audience = _marketing_audience(conn)
    sent = 0
    for i in range(0, len(audience), 100):
        chunk = audience[i:i + 100]
        batch = []
        for person in chunk:
            email = person["email"]
            qs = urlencode({"email": email, "token": _unsub_token(email)})
            unsub_url = f"https://pop-a-licious.com/api/marketing/unsubscribe?{qs}"
            batch.append({
                "to": email,
                "subject": campaign["subject"],
                "html": _marketing_email_html(campaign["html_body"], email),
                "unsub_url": unsub_url,
            })
        try:
            _send_marketing_batch(batch)
            sent += len(batch)
        except Exception as e:
            conn.close()
            return jsonify(error=f"send failed after {sent} emails: {e}"), 502
    conn.execute(
        "INSERT INTO marketing_campaigns (name, subject, audience, recipient_count, sent_at)"
        " VALUES (?, ?, 'all', ?, ?)",
        (campaign["name"], campaign["subject"], sent, datetime.now(timezone.utc).isoformat()),
    )
    conn.commit()
    conn.close()
    return jsonify(ok=True, sent=sent, campaign=campaign["name"])


# ---------- Wave 3 commercial 9: automated review-request email (SOP 8.29) ----------
# No new send-tracking table: one request per order ever is enforced by
# review_request_sent_at on the order row (NULL = never sent), and the
# reviews table is checked first -- a customer who already reviewed that
# flavor is never asked again (the marker is still set, so the order is
# never re-scanned). Trigger: 7 days after a paid order. The "after an
# order is marked delivered" trigger is NOT implemented: the ERP holds no
# delivery data -- orders carry a Shippo label + tracking number (shipped,
# not delivered) and paypal_orders carries only status captured/created.
# If delivery scans are ever recorded, the delivered trigger can be added
# here without changing the guards. Wholesale / Faire orders are never
# scanned: only the retail orders / paypal_orders tables are read;
# erp_wholesale_orders and erp_faire_orders are untouched. Suppression
# reuses the newsletter unsubscribe list (marketing_unsubscribes) -- the
# ERP has no separate bounce list. DEFAULT OFF: the toggle lives in
# erp_mkt_review_request_settings (key 'enabled'); absent = off, and the
# founders turn it on. No live cron job is created by this build; the run
# endpoint is code only, for the parent to schedule later.

def _review_request_enabled(conn):
    """The founders' toggle. Absent row = off."""
    row = conn.execute(
        "SELECT value FROM erp_mkt_review_request_settings"
        " WHERE key = 'enabled'").fetchone()
    return bool(row and row["value"] == "1")


def _review_request_slug(flavor_name):
    """Site flavor slug for a canonical flavor name: ASCII-folded,
    lower-cased, non-alphanumerics to '-'. Matches the live site's
    #flavor/<slug> pages for all 25 flavors (Cookie and Cream ->
    cookie-and-cream, Salt and Vinegar -> salt-and-vinegar,
    Cheddar Jalapeño -> cheddar-jalapeno)."""
    ascii_s = unicodedata.normalize(
        "NFKD", str(flavor_name or "")).encode("ascii", "ignore").decode("ascii")
    slug = re.sub(r"[^a-z0-9]+", "-", ascii_s.lower()).strip("-")
    return slug


def _review_request_flavor(items_summary):
    """First flavor in the order summary that matches one of the 25 live
    flavors -> (display name, site slug). Names are matched with
    _promo_bag_key, so the site spellings ('Cookies N' Creme',
    'Salt & Vinegar') match the canonical names. Returns (None, None)
    when nothing matches (merch-only / variety-pack order): the email
    then links the site home page instead of inventing a flavor link."""
    lookup = {_promo_bag_key(f): f for f in FLAVORS}
    for _qty, _name in _erp_parse_summary_flavors(items_summary):
        canon = lookup.get(_promo_bag_key(_name))
        if canon:
            return canon, _review_request_slug(canon)
    return None, None


def _review_request_email_html(name, flavor_name, review_url):
    """Review-request body. The link is the flavor's own review form on
    its site page (SITE_URL/#flavor/<slug>), or the site home page when
    the order had no matchable flavor."""
    flavor_line = (
        "<p>How was your <strong>%s</strong>?</p>" % html.escape(flavor_name)
        if flavor_name
        else "<p>How was your popcorn?</p>")
    return (
        "<html><body style=\"font-family: Arial, sans-serif; line-height: 1.6;\">"
        "<p>Hi %s,</p>"
        "<p>Thanks for your Pop-A-Licious order — we hope every kernel popped just right.</p>"
        "%s"
        "<p>Would you leave a quick review? It takes a minute, and it helps other popcorn lovers find us.</p>"
        "<p><a href=\"%s\" style=\"background:#c0392b;color:#fff;padding:12px 24px;text-decoration:none;border-radius:6px;\">Leave a review</a></p>"
        "<p>Stay delicious,<br><strong>The Pop-A-Licious Team</strong><br>"
        "<em>It\u2019s Not Just Butter &amp; Salt!</em> &#x1F37F;</p>"
        "</body></html>"
        % (html.escape(name) if name else "there", flavor_line, review_url))


def _review_request_run(conn):
    """One sweep over paid retail orders 7+ days old that have never had
    a review request. Returns the counts. A failed send leaves the marker
    NULL so the next run retries it (same pattern as the abandoned-cart
    cron); a send that succeeds sets the marker + audits
    marketing.review_request_sent, so the order is never picked up again.
    An order whose customer already reviewed the flavor gets the marker
    set with no email (counted as already_reviewed, never re-scanned)."""
    if not _review_request_enabled(conn):
        return {"ok": True, "enabled": False, "sent": 0, "skipped": 0,
                "already_reviewed": 0, "failed": [],
                "note": "review requests are off"}
    now = datetime.now(timezone.utc)
    cutoff = (now - timedelta(days=7)).isoformat()
    unsub = {r["email"].lower() for r in conn.execute(
        "SELECT email FROM marketing_unsubscribes")}
    sent = skipped = already = 0
    failed = []
    for source, table, target_type in (
            ("stripe", "orders", "order"),
            ("paypal", "paypal_orders", "paypal_order")):
        where = ("review_request_sent_at IS NULL AND created_at <= ?"
                 " AND email IS NOT NULL AND email != ''")
        if source == "paypal":
            # PayPal rows start as status 'created' until the customer
            # pays; only captured rows are paid orders.
            where += " AND status = 'captured'"
        rows = conn.execute(
            "SELECT * FROM %s WHERE %s ORDER BY created_at ASC LIMIT 200"
            % (table, where), (cutoff,)).fetchall()
        for row in rows:
            email = (row["email"] or "").strip().lower()
            if not email or email in unsub:
                skipped += 1
                continue
            flavor_name, slug = _review_request_flavor(row["items_summary"])
            if slug:
                user = conn.execute(
                    "SELECT id FROM users WHERE lower(email) = ?",
                    (email,)).fetchone()
                if user and conn.execute(
                        "SELECT id FROM reviews WHERE flavor_slug = ?"
                        " AND user_id = ?", (slug, user["id"])).fetchone():
                    conn.execute(
                        "UPDATE %s SET review_request_sent_at = ? WHERE id = ?"
                        % table, (now.isoformat(), row["id"]))
                    already += 1
                    continue
            review_url = ("%s/#flavor/%s" % (SITE_URL, slug)
                          if slug else SITE_URL)
            name = row["customer_name"] if source == "stripe" else ""
            try:
                send_email(
                    email,
                    "How was your Pop-A-Licious popcorn?",
                    _marketing_email_html(
                        _review_request_email_html(name, flavor_name,
                                                   review_url),
                        email))
            except Exception as e:
                failed.append({"source": source, "id": row["id"],
                               "error": str(e)})
                continue
            conn.execute(
                "UPDATE %s SET review_request_sent_at = ? WHERE id = ?"
                % table, (now.isoformat(), row["id"]))
            _erp_staff_audit(conn, "cron", "marketing.review_request_sent",
                             target_type, row["id"], email)
            sent += 1
    conn.commit()
    return {"ok": True, "enabled": True, "sent": sent, "skipped": skipped,
            "already_reviewed": already, "failed": failed}


@app.post("/api/cron/marketing/review-requests")
def cron_marketing_review_requests():
    """Cron: send review-request emails for paid retail orders 7+ days
    old that never had one. Header X-Cron-Secret must equal the
    CRON_SECRET env var (503 when CRON_SECRET is not configured).
    Sends nothing while the founders' toggle is off. No cron job is
    scheduled by this build -- the endpoint is code only."""
    auth_err = _mkt_cron_auth()
    if auth_err is not None:
        return auth_err
    conn = db()
    result = _review_request_run(conn)
    conn.close()
    return jsonify(result)


@app.post("/api/cron/marketing/drips")
def cron_marketing_drips():
    """Cron: send due drip-sequence steps (Dept 8, SOP 8.36, Wave 4
    item 4). Header X-Cron-Secret must equal the CRON_SECRET env var
    (503 when CRON_SECRET is not configured). Each due step sends the
    linked newsletter issue through the existing Resend batch path to
    that enrollee only. Body {"dry_run": true} shows what would send
    and sends nothing. No cron job is scheduled by this build -- the
    endpoint is code only."""
    auth_err = _mkt_cron_auth()
    if auth_err is not None:
        return auth_err
    data = request.get_json(silent=True) or {}
    dry_run = bool(data.get("dry_run")) if isinstance(data, dict) else False
    conn = db()
    result = _mkt_drip_run(conn, dry_run=dry_run)
    conn.close()
    return jsonify(result)


