# ---------- Customer master / CRM (Dept 8 item 2) ----------
# List + detail + staff tags/notes only — no segments, campaigns, or
# pipelines. Retail keying reuses _erp_customer_rows (the Reports
# customers keying, exactly). Loyalty members come from the storefront
# users table (email key; kernels via _kernel_balance /
# _lifetime_kernels / _loyalty_tier). Wholesale accounts come from
# erp_wholesale_accounts. Notes are staff-editable under the existing
# support.write perm; no new perms are invented here.


def _mkt_check_any_read():
    """Allowed when the caller holds any Marketing & Service read perm."""
    for perm in ("instagram.read", "newsletter.read", "support.read"):
        actor, err = _erp_check_perm(perm)
        if actor is not None:
            return actor, None
    return _erp_check_perm("instagram.read")


def _mkt_note_map(conn):
    out = {}
    for r in conn.execute("SELECT * FROM erp_mkt_customer_notes").fetchall():
        try:
            tags = json.loads(r["tags_json"] or "[]")
        except (ValueError, TypeError):
            tags = []
        out[r["customer_key"]] = {
            "tags": tags if isinstance(tags, list) else [],
            "note": r["note"] or "",
            "updated_by": r["updated_by"] or "",
            "updated_at": r["updated_at"] or "",
        }
    return out


def _mkt_loyalty_for_email(conn, email):
    """Loyalty member record for an email, or None (not a member)."""
    if not email:
        return None
    u = conn.execute(
        "SELECT id, email, name FROM users WHERE lower(email) = lower(?)",
        (email,)).fetchone()
    if not u:
        return None
    lifetime = _lifetime_kernels(conn, u["id"])
    return {"user_id": u["id"], "name": u["name"] or "",
            "kernels": _kernel_balance(conn, u["id"]),
            "lifetime_kernels": lifetime,
            "tier": _loyalty_tier(conn, lifetime)}


def _mkt_wholesale_for_email(conn, email):
    if not email:
        return None
    a = conn.execute(
        "SELECT id, name, email FROM erp_wholesale_accounts"
        " WHERE lower(email) = lower(?)", (email,)).fetchone()
    return dict(a) if a else None


def _mkt_enrich_customer(conn, c, notes):
    """Attach notes/tags, loyalty, and wholesale account to a CRM row."""
    c = dict(c)
    c["repeat"] = c["order_count"] >= 2
    n = notes.get(c["key"])
    c["tags"] = n["tags"] if n else []
    c["note"] = n["note"] if n else ""
    c["note_updated_by"] = n["updated_by"] if n else ""
    c["note_updated_at"] = n["updated_at"] if n else ""
    email = c.get("email") or ""
    c["loyalty"] = _mkt_loyalty_for_email(conn, email)
    # Referral program (Dept 8, SOP 8.25): who referred this customer,
    # and how many customers they have referred.
    c["referred_by"] = None
    c["referrals_made"] = 0
    email_l = email.strip().lower()
    if email_l:
        ref = conn.execute(
            "SELECT r.status, u.name AS referrer_name, u.email AS referrer_email"
            " FROM erp_mkt_referrals r"
            " LEFT JOIN users u ON u.id = r.referrer_user_id"
            " WHERE lower(r.referred_email) = lower(?)"
            " ORDER BY r.id ASC LIMIT 1", (email_l,)).fetchone()
        if ref:
            c["referred_by"] = {
                "name": ref["referrer_name"] or "",
                "email": ref["referrer_email"] or "",
                "status": ref["status"]}
        u = conn.execute(
            "SELECT id FROM users WHERE lower(email) = lower(?)",
            (email_l,)).fetchone()
        if u:
            c["referrals_made"] = conn.execute(
                "SELECT COUNT(*) AS n FROM erp_mkt_referrals"
                " WHERE referrer_user_id = ?", (u["id"],)).fetchone()["n"]
    if c["key"].startswith("account:"):
        try:
            aid = int(c["key"].split(":", 1)[1])
        except ValueError:
            aid = -1
        a = conn.execute(
            "SELECT id, name, email FROM erp_wholesale_accounts WHERE id = ?",
            (aid,)).fetchone()
        c["wholesale_account"] = dict(a) if a else None
    else:
        c["wholesale_account"] = _mkt_wholesale_for_email(conn, email)
    return c


def _mkt_crm_rows(conn, df="", dt=""):
    """CRM rows: Reports rows (orders) + wholesale accounts and loyalty
    members with no orders yet (order_count 0, totals 0 — never invented
    orders or spend). Keying matches _erp_customer_rows exactly."""
    rows = _erp_customer_rows(conn, df, dt)
    notes = _mkt_note_map(conn)
    # Wholesale accounts with no orders in the window.
    for a in conn.execute(
            "SELECT id, name, email FROM erp_wholesale_accounts"
            " ORDER BY name").fetchall():
        email = (a["email"] or "").strip().lower()
        key = ("email:" + email) if email else ("account:%d" % a["id"])
        if key in rows:
            continue
        rows[key] = {"key": key, "display": email or a["name"],
                     "email": email, "account_name": a["name"],
                     "order_count": 0, "total_bags": 0,
                     "total_spent_cents": 0, "first_order_at": None,
                     "last_order_at": None}
    # Loyalty members with no orders in the window.
    for u in conn.execute(
            "SELECT id, email, name FROM users ORDER BY email").fetchall():
        email = (u["email"] or "").strip().lower()
        if not email:
            continue
        key = "email:" + email
        if key in rows:
            continue
        rows[key] = {"key": key, "display": email, "email": email,
                     "account_name": "", "order_count": 0, "total_bags": 0,
                     "total_spent_cents": 0, "first_order_at": None,
                     "last_order_at": None}
    out = [_mkt_enrich_customer(conn, c, notes) for c in rows.values()]
    out.sort(key=lambda c: -c["total_spent_cents"])
    return out


def _mkt_crm_row_for_key(conn, key):
    """One enriched CRM row for a customer key, or None."""
    if not key or ":" not in key:
        return None
    kind, rest = key.split(":", 1)
    if kind == "email":
        rows = _mkt_crm_rows(conn)
        return next((c for c in rows if c["key"] == key), None)
    if kind == "account":
        try:
            aid = int(rest)
        except ValueError:
            return None
        a = conn.execute(
            "SELECT * FROM erp_wholesale_accounts WHERE id = ?",
            (aid,)).fetchone()
        if not a:
            return None
        rows = _mkt_crm_rows(conn)
        row = next((c for c in rows if c["key"] == key), None)
        if row:
            return row
        notes = _mkt_note_map(conn)
        return _mkt_enrich_customer(conn, {
            "key": key, "display": a["name"], "email": "",
            "account_name": a["name"], "order_count": 0, "total_bags": 0,
            "total_spent_cents": 0, "first_order_at": None,
            "last_order_at": None}, notes)
    return None


@app.get("/api/erp/marketing/customers")
def mkt_customers_list():
    actor, err = _mkt_check_any_read()
    if err:
        return err
    df, dt = _erp_report_dates(request.args)
    if df is None:
        return jsonify(error="from/to must be YYYY-MM-DD"), 400
    q = (request.args.get("q") or "").strip().lower()
    conn = db()
    rows = _mkt_crm_rows(conn, df, dt)
    conn.close()
    if q:
        rows = [c for c in rows
                if q in (c["display"] or "").lower()
                or q in (c["email"] or "").lower()
                or q in (c["account_name"] or "").lower()
                or any(q in (t or "").lower() for t in (c["tags"] or []))]
    summary = {
        "total_customers": len(rows),
        "repeat_customers": sum(1 for c in rows if c["repeat"]),
        "total_spent_cents": sum(c["total_spent_cents"] for c in rows),
        "wholesale_accounts": sum(
            1 for c in rows if c["wholesale_account"]),
        "loyalty_members": sum(1 for c in rows if c["loyalty"]),
    }
    return jsonify({"from": df, "to": dt, "summary": summary,
                    "customers": rows})


# ---------- Saved segments / lists (Dept 8, SOP 8.20, Wave 3 commercial 1) ----------
# A segment is only an admin-entered name + rule. Membership is
# COMPUTED at read time from the rule over _mkt_crm_rows (the same
# keying as the Customers list); never stored, so it can never go
# stale, and the list member counts and the members list always agree
# because both run the same evaluator over the same rows. Rules
# reference only data the ERP already holds (orders, tags, loyalty
# tier, wholesale flag). No purchased lists, no imported audiences.
# Deleting a segment deletes only the rule, never customers.
_MKT_SEGMENT_RULE_KEYS = ("min_orders", "min_spent_cents", "tag",
                         "loyalty_tier", "wholesale_only")
_MKT_LOYALTY_TIERS = ("Popped", "Buttery", "Golden Kernel")


def _mkt_known_tags(conn):
    """Every tag staff have attached to a customer, lowercased."""
    known = set()
    for r in conn.execute(
            "SELECT tags_json FROM erp_mkt_customer_notes").fetchall():
        try:
            tags = json.loads(r["tags_json"] or "[]")
        except (ValueError, TypeError):
            tags = []
        for t in tags if isinstance(tags, list) else []:
            if isinstance(t, str) and t.strip():
                known.add(t.strip().lower())
    return known


def _mkt_validate_segment_rule(conn, rule):
    """Validate a segment rule dict. Returns (rule, error): the
    normalized rule, or (None, message) for a 400."""
    if not isinstance(rule, dict):
        return None, "rule must be an object"
    for key in rule:
        if key not in _MKT_SEGMENT_RULE_KEYS:
            return None, "unknown rule key: %s" % key
    out = {}
    for key in ("min_orders", "min_spent_cents"):
        if key in rule:
            v = rule[key]
            if isinstance(v, bool) or not isinstance(v, int):
                return None, "%s must be a whole number" % key
            if v < 0:
                return None, "%s must not be negative" % key
            out[key] = v
    if "tag" in rule:
        v = rule["tag"]
        if not isinstance(v, str) or not v.strip():
            return None, "tag must be a non-empty string"
        if v.strip().lower() not in _mkt_known_tags(conn):
            return None, "unknown tag: %s" % v.strip()
        out["tag"] = v.strip()
    if "loyalty_tier" in rule:
        v = rule["loyalty_tier"]
        if v not in _MKT_LOYALTY_TIERS:
            return None, "unknown loyalty tier: %s" % v
        out["loyalty_tier"] = v
    if "wholesale_only" in rule:
        v = rule["wholesale_only"]
        if not isinstance(v, bool):
            return None, "wholesale_only must be true or false"
        out["wholesale_only"] = v
    return out, None


def _mkt_segment_matches(rule, row):
    """True when one enriched CRM row satisfies every clause of a rule."""
    if "min_orders" in rule and (row.get("order_count") or 0) < rule["min_orders"]:
        return False
    if "min_spent_cents" in rule and (row.get("total_spent_cents") or 0) < rule["min_spent_cents"]:
        return False
    if "tag" in rule:
        tags = [str(t).lower() for t in (row.get("tags") or [])]
        if rule["tag"].lower() not in tags:
            return False
    if "loyalty_tier" in rule:
        loyalty = row.get("loyalty") or {}
        if loyalty.get("tier") != rule["loyalty_tier"]:
            return False
    if rule.get("wholesale_only") and not row.get("wholesale_account"):
        return False
    return True


def _mkt_segment_row(row, member_count):
    try:
        rule = json.loads(row["rule_json"] or "{}")
    except (ValueError, TypeError):
        rule = {}
    if not isinstance(rule, dict):
        rule = {}
    return {"id": row["id"], "name": row["name"], "rule": rule,
            "member_count": member_count,
            "created_by": row["created_by"] or "",
            "created_at": row["created_at"] or "",
            "updated_by": row["updated_by"] or "",
            "updated_at": row["updated_at"] or ""}


def _mkt_segment_members(conn, rule, df="", dt=""):
    """The enriched CRM rows matching a rule (all-time by default,
    same window as the Customers list when from/to are given)."""
    return [c for c in _mkt_crm_rows(conn, df, dt)
            if _mkt_segment_matches(rule, c)]


def _mkt_segment_recipients(conn, segment_id):
    """Newsletter recipients for a segment: member emails minus
    unsubscribes, deduplicated. Raises ValueError when the segment
    does not exist."""
    row = conn.execute("SELECT * FROM erp_mkt_segments WHERE id = ?",
                       (segment_id,)).fetchone()
    if not row:
        raise ValueError("segment not found")
    try:
        rule = json.loads(row["rule_json"] or "{}")
    except (ValueError, TypeError):
        rule = {}
    if not isinstance(rule, dict):
        rule = {}
    unsub = {r["email"] for r in conn.execute(
        "SELECT email FROM marketing_unsubscribes")}
    out = {}
    for c in _mkt_segment_members(conn, rule):
        email = (c.get("email") or "").strip().lower()
        if email and email not in unsub:
            out[email] = {"email": email,
                          "name": c.get("account_name") or c.get("display") or ""}
    return [out[k] for k in sorted(out)]


@app.get("/api/erp/marketing/segments")
def mkt_segments_list():
    actor, err = _mkt_check_any_read()
    if err:
        return err
    df, dt = _erp_report_dates(request.args)
    if df is None:
        return jsonify(error="from/to must be YYYY-MM-DD"), 400
    conn = db()
    rows = conn.execute(
        "SELECT * FROM erp_mkt_segments ORDER BY name COLLATE NOCASE").fetchall()
    crm = _mkt_crm_rows(conn, df, dt)
    conn.close()
    segments = []
    for r in rows:
        try:
            rule = json.loads(r["rule_json"] or "{}")
        except (ValueError, TypeError):
            rule = {}
        if not isinstance(rule, dict):
            rule = {}
        segments.append(_mkt_segment_row(
            r, sum(1 for c in crm if _mkt_segment_matches(rule, c))))
    return jsonify(segments=segments, count=len(segments))


@app.post("/api/erp/marketing/segments")
def mkt_segment_create():
    actor, err = _erp_check_perm("newsletter.write")
    if err:
        return err
    data = request.get_json(force=True) or {}
    name = (data.get("name") or "")
    if not isinstance(name, str) or not name.strip():
        return jsonify(error="name is required"), 400
    name = name.strip()
    rule = data.get("rule", {})
    conn = db()
    rule, rerr = _mkt_validate_segment_rule(conn, rule)
    if rerr:
        conn.close()
        return jsonify(error=rerr), 400
    if conn.execute("SELECT id FROM erp_mkt_segments WHERE lower(name) = lower(?)",
                    (name,)).fetchone():
        conn.close()
        return jsonify(error="a segment with that name already exists"), 409
    now = datetime.now(timezone.utc).isoformat()
    try:
        cur = conn.execute(
            "INSERT INTO erp_mkt_segments (name, rule_json, created_by,"
            " created_at, updated_by, updated_at)"
            " VALUES (?, ?, ?, ?, ?, ?)",
            (name, json.dumps(rule), actor, now, actor, now))
    except sqlite3.IntegrityError:
        conn.close()
        return jsonify(error="a segment with that name already exists"), 409
    sid = cur.lastrowid
    _erp_staff_audit(conn, actor, "marketing.segment_created",
                     "segment", sid, name)
    conn.commit()
    conn.close()
    return jsonify(ok=True, segment_id=sid), 201


@app.post("/api/erp/marketing/segments/<int:segment_id>/update")
def mkt_segment_update(segment_id):
    actor, err = _erp_check_perm("newsletter.write")
    if err:
        return err
    data = request.get_json(force=True) or {}
    conn = db()
    row = conn.execute("SELECT * FROM erp_mkt_segments WHERE id = ?",
                       (segment_id,)).fetchone()
    if not row:
        conn.close()
        return jsonify(error="segment not found"), 404
    name = row["name"]
    if "name" in data:
        name = data.get("name") or ""
        if not isinstance(name, str) or not name.strip():
            conn.close()
            return jsonify(error="name is required"), 400
        name = name.strip()
    try:
        rule = json.loads(row["rule_json"] or "{}")
    except (ValueError, TypeError):
        rule = {}
    if not isinstance(rule, dict):
        rule = {}
    if "rule" in data:
        rule, rerr = _mkt_validate_segment_rule(conn, data.get("rule"))
        if rerr:
            conn.close()
            return jsonify(error=rerr), 400
    if name.lower() != row["name"].lower() and conn.execute(
            "SELECT id FROM erp_mkt_segments WHERE lower(name) = lower(?)",
            (name,)).fetchone():
        conn.close()
        return jsonify(error="a segment with that name already exists"), 409
    now = datetime.now(timezone.utc).isoformat()
    try:
        conn.execute("UPDATE erp_mkt_segments SET name = ?, rule_json = ?,"
                     " updated_by = ?, updated_at = ? WHERE id = ?",
                     (name, json.dumps(rule), actor, now, segment_id))
    except sqlite3.IntegrityError:
        conn.close()
        return jsonify(error="a segment with that name already exists"), 409
    _erp_staff_audit(conn, actor, "marketing.segment_updated",
                     "segment", segment_id, name)
    conn.commit()
    conn.close()
    return jsonify(ok=True, segment_id=segment_id)


@app.delete("/api/erp/marketing/segments/<int:segment_id>")
def mkt_segment_delete(segment_id):
    actor, err = _erp_check_perm("newsletter.write")
    if err:
        return err
    conn = db()
    row = conn.execute("SELECT * FROM erp_mkt_segments WHERE id = ?",
                       (segment_id,)).fetchone()
    if not row:
        conn.close()
        return jsonify(error="segment not found"), 404
    # Deleting a segment deletes only the rule, never customers.
    # Newsletter issues addressed to it fall back to the full
    # audience (their segment_id is cleared), so a later send never
    # fails on a missing segment.
    conn.execute("UPDATE erp_mkt_newsletters SET segment_id = NULL"
                 " WHERE segment_id = ?", (segment_id,))
    conn.execute("DELETE FROM erp_mkt_segments WHERE id = ?", (segment_id,))
    _erp_staff_audit(conn, actor, "marketing.segment_deleted",
                     "segment", segment_id, row["name"])
    conn.commit()
    conn.close()
    return jsonify(ok=True, deleted=segment_id)


@app.get("/api/erp/marketing/segments/<int:segment_id>/members")
def mkt_segment_members(segment_id):
    actor, err = _mkt_check_any_read()
    if err:
        return err
    df, dt = _erp_report_dates(request.args)
    if df is None:
        return jsonify(error="from/to must be YYYY-MM-DD"), 400
    q = (request.args.get("q") or "").strip().lower()
    conn = db()
    row = conn.execute("SELECT * FROM erp_mkt_segments WHERE id = ?",
                       (segment_id,)).fetchone()
    if not row:
        conn.close()
        return jsonify(error="segment not found"), 404
    try:
        rule = json.loads(row["rule_json"] or "{}")
    except (ValueError, TypeError):
        rule = {}
    if not isinstance(rule, dict):
        rule = {}
    members = _mkt_segment_members(conn, rule, df, dt)
    conn.close()
    if q:
        members = [c for c in members
                   if q in (c["display"] or "").lower()
                   or q in (c["email"] or "").lower()
                   or q in (c["account_name"] or "").lower()
                   or any(q in (t or "").lower() for t in (c["tags"] or []))]
    summary = {
        "total_customers": len(members),
        "repeat_customers": sum(1 for c in members if c["repeat"]),
        "total_spent_cents": sum(c["total_spent_cents"] for c in members),
        "wholesale_accounts": sum(
            1 for c in members if c["wholesale_account"]),
        "loyalty_members": sum(1 for c in members if c["loyalty"]),
    }
    return jsonify({"from": df, "to": dt, "segment": _mkt_segment_row(row, len(members)),
                    "summary": summary, "customers": members})


# ---------- Multi-channel campaigns (Dept 8, SOP 8.22) ----------
# ONE campaign object grouping channels: email (one newsletter issue),
# instagram (one IG post), sms (placeholder only -- SMS is NOT adopted).
# A campaign never sends anything by itself; it groups and tracks.
# campaign_key is the attribution join: the same key stamped on orders
# at checkout (§3.11 attribution, later item), so it must be unique.
# Writes are admin-only (_require_erp_admin); reads use the existing
# any-read Marketing gate. Deleting a campaign deletes only the
# grouping, never the linked issue or post.
_MKT_CAMPAIGN_STATUSES = ("draft", "active", "done")
_MKT_CAMPAIGN_CHANNELS = ("email", "instagram", "sms")
_MKT_CAMPAIGN_CHANNEL_STATUSES = {
    "email": ("sent", "skipped"),
    "instagram": ("posted", "skipped"),
    "sms": ("not_configured",),
}


def _mkt_campaign_key_ok(key):
    """A campaign_key matches the existing convention (lowercase, like
    xmas2026_blackfriday and newsletter-2026-02): lowercase letters,
    digits, _ or -, starting with a letter or digit, at most 64 chars."""
    return isinstance(key, str) and re.match(
        r"^[a-z0-9][a-z0-9_-]{0,63}$", key) is not None


def _mkt_campaign_channels(conn, campaign_id):
    out = []
    for r in conn.execute(
            "SELECT * FROM erp_mkt_campaign_channels WHERE campaign_id = ?"
            " ORDER BY id", (campaign_id,)).fetchall():
        ch = dict(r)
        ch["ref_label"] = None
        if ch["channel"] == "email" and ch["ref_id"] is not None:
            issue = conn.execute(
                "SELECT issue_month, theme, subject FROM erp_mkt_newsletters"
                " WHERE id = ?", (ch["ref_id"],)).fetchone()
            if issue:
                ch["ref_label"] = "%s — %s" % (
                    issue["issue_month"],
                    issue["subject"] or issue["theme"])
        elif ch["channel"] == "instagram" and ch["ref_id"] is not None:
            post = conn.execute(
                "SELECT kind, caption, promo_date FROM erp_mkt_ig_posts"
                " WHERE id = ?", (ch["ref_id"],)).fetchone()
            if post:
                ch["ref_label"] = "%s — %s" % (
                    post["kind"],
                    ((post["caption"] or "")[:80]
                     or post["promo_date"] or ""))
        out.append(ch)
    return out


def _mkt_campaign_row(conn, r):
    c = dict(r)
    channels = _mkt_campaign_channels(conn, c["id"])
    c["channels"] = channels
    c["channel_summary"] = {ch["channel"]: ch["status"] for ch in channels}
    return c


@app.get("/api/erp/marketing/campaigns")
def mkt_campaigns_list():
    actor, err = _mkt_check_any_read()
    if err:
        return err
    conn = db()
    rows = conn.execute(
        "SELECT * FROM erp_mkt_campaigns ORDER BY id DESC").fetchall()
    campaigns = [_mkt_campaign_row(conn, r) for r in rows]
    conn.close()
    return jsonify(campaigns=campaigns, count=len(campaigns))


@app.post("/api/erp/marketing/campaigns")
def mkt_campaign_create():
    actor, err = _require_erp_admin()
    if err:
        return err
    data = request.get_json(force=True) or {}
    name = data.get("name") or ""
    if not isinstance(name, str) or not name.strip():
        return jsonify(error="name is required"), 400
    name = name.strip()
    key = data.get("campaign_key") or ""
    if not _mkt_campaign_key_ok(key):
        return jsonify(error="campaign_key must be lowercase letters,"
                       " digits, _ or -, starting with a letter or digit,"
                       " at most 64 characters"), 400
    status = data.get("status") or "draft"
    if status not in _MKT_CAMPAIGN_STATUSES:
        return jsonify(error="status must be draft, active, or done"), 400
    notes = data.get("notes") or ""
    if not isinstance(notes, str):
        return jsonify(error="notes must be a string"), 400
    conn = db()
    if conn.execute("SELECT id FROM erp_mkt_campaigns WHERE campaign_key = ?",
                    (key,)).fetchone():
        conn.close()
        return jsonify(error="a campaign with that campaign_key already"
                       " exists"), 409
    now = datetime.now(timezone.utc).isoformat()
    try:
        cur = conn.execute(
            "INSERT INTO erp_mkt_campaigns (name, campaign_key, status,"
            " notes, created_by, created_at, updated_by, updated_at)"
            " VALUES (?, ?, ?, ?, ?, ?, ?, ?)",
            (name, key, status, notes, actor, now, actor, now))
    except sqlite3.IntegrityError:
        conn.close()
        return jsonify(error="a campaign with that campaign_key already"
                       " exists"), 409
    cid = cur.lastrowid
    _erp_staff_audit(conn, actor, "marketing.campaign_created",
                     "campaign", cid, "%s (%s)" % (name, key))
    conn.commit()
    conn.close()
    return jsonify(ok=True, campaign_id=cid), 201


