# ---------------- Surveys / NPS (Dept 8, SOP 8.33, Wave 3 §4.2 item 14) ----------------
# Customer satisfaction surveys and a Net Promoter Score. Reads use
# the existing support.read gate (same as reviews); every write is
# admin-only. NPS is computed at read time from real answers only --
# never stored, never invented: with no answers to the NPS question
# there is no NPS (null), never 0. Nothing here sends email: the
# admin shares the public link; there is no auto-send.
_SURVEY_NPS_MIN_RESPONSES = 30
_SURVEY_QUESTION_TYPES = ("nps", "rating", "text")


def _mkt_survey_public_url(survey):
    return "/survey/" + (survey["public_key"] or "")


def _mkt_survey_nps(conn, survey_id):
    """NPS for one survey, computed from real answers only.

    Returns the counts, the NPS (None with no answers to the NPS
    question -- never 0), the count the NPS was computed from, and
    the total response count. sample_too_small is True below
    _SURVEY_NPS_MIN_RESPONSES answers: the design trigger is ~200
    paying customers, so in practice the flag stays on for a long
    time -- that is the point, not a bug.
    """
    total = conn.execute(
        "SELECT COUNT(*) FROM erp_mkt_survey_responses WHERE survey_id = ?",
        (survey_id,)).fetchone()[0]
    q = conn.execute(
        "SELECT id FROM erp_mkt_survey_questions"
        " WHERE survey_id = ? AND question_type = 'nps'"
        " ORDER BY id LIMIT 1", (survey_id,)).fetchone()
    if not q:
        return {"has_nps_question": False, "nps": None, "promoters": 0,
                "passives": 0, "detractors": 0, "response_count": 0,
                "total_responses": total, "sample_too_small": True}
    vals = [r[0] for r in conn.execute(
        "SELECT a.value_num FROM erp_mkt_survey_answers a"
        " JOIN erp_mkt_survey_responses r ON r.id = a.response_id"
        " WHERE a.question_id = ? AND a.value_num IS NOT NULL",
        (q["id"],)).fetchall()]
    n = len(vals)
    promoters = sum(1 for v in vals if v >= 9)
    passives = sum(1 for v in vals if 7 <= v <= 8)
    detractors = sum(1 for v in vals if v <= 6)
    nps = (round(100.0 * promoters / n - 100.0 * detractors / n, 1)
           if n else None)
    return {"has_nps_question": True, "nps": nps, "promoters": promoters,
            "passives": passives, "detractors": detractors,
            "response_count": n, "total_responses": total,
            "sample_too_small": n < _SURVEY_NPS_MIN_RESPONSES}


def _mkt_survey_dict(conn, row):
    nps = _mkt_survey_nps(conn, row["id"])
    qcount = conn.execute(
        "SELECT COUNT(*) FROM erp_mkt_survey_questions WHERE survey_id = ?",
        (row["id"],)).fetchone()[0]
    return {
        "id": row["id"], "title": row["title"],
        "description": row["description"] or "",
        "active": bool(row["active"]),
        "public_key": row["public_key"],
        "public_url": _mkt_survey_public_url(row),
        "question_count": qcount,
        "response_count": nps["total_responses"],
        "nps": nps,
        "created_by": row["created_by"], "created_at": row["created_at"],
        "updated_by": row["updated_by"], "updated_at": row["updated_at"],
    }


def _mkt_survey_question_dict(row):
    return {
        "id": row["id"], "survey_id": row["survey_id"],
        "question_text": row["question_text"],
        "question_type": row["question_type"],
        "sort_order": row["sort_order"],
        "required": bool(row["required"]),
    }


def _mkt_survey_detail(conn, survey):
    questions = [_mkt_survey_question_dict(r) for r in conn.execute(
        "SELECT * FROM erp_mkt_survey_questions WHERE survey_id = ?"
        " ORDER BY sort_order, id", (survey["id"],)).fetchall()]
    qtext = {q["id"]: q for q in questions}
    responses = []
    for r in conn.execute(
            "SELECT * FROM erp_mkt_survey_responses WHERE survey_id = ?"
            " ORDER BY submitted_at DESC, id DESC",
            (survey["id"],)).fetchall():
        answers = []
        for a in conn.execute(
                "SELECT * FROM erp_mkt_survey_answers WHERE response_id = ?"
                " ORDER BY id", (r["id"],)).fetchall():
            q = qtext.get(a["question_id"])
            answers.append({
                "question_id": a["question_id"],
                "question_text": q["question_text"] if q else "",
                "question_type": q["question_type"] if q else "",
                "value_num": a["value_num"],
                "value_text": a["value_text"] or "",
            })
        responses.append({
            "id": r["id"], "survey_id": r["survey_id"],
            "respondent": r["respondent"] or "",
            "customer_key": r["customer_key"] or "",
            "order_ref": r["order_ref"] or "",
            "submitted_at": r["submitted_at"],
            "answers": answers,
        })
    out = _mkt_survey_dict(conn, survey)
    out["questions"] = questions
    out["responses"] = responses
    return out


def _mkt_survey_validate_create(data):
    title = data.get("title")
    if not isinstance(title, str) or not title.strip():
        return None, "title is required"
    title = title.strip()
    if len(title) > 200:
        return None, "title is too long (max 200 characters)"
    desc = data.get("description", "")
    if not isinstance(desc, str):
        return None, "description must be text"
    if len(desc.strip()) > 2000:
        return None, "description is too long (max 2000 characters)"
    active = data.get("active", True)
    if not isinstance(active, bool):
        return None, "active must be true or false"
    return {"title": title, "description": desc.strip(),
            "active": 1 if active else 0}, None


