@app.post("/api/erp/marketing/surveys")
def mkt_survey_create():
    actor, err = _require_erp_admin()
    if err:
        return err
    data = request.get_json(force=True) or {}
    fields, verr = _mkt_survey_validate_create(data)
    if verr:
        return jsonify(error=verr), 400
    now = datetime.now(timezone.utc).isoformat()
    conn = db()
    key = None
    for _attempt in range(5):
        cand = secrets.token_urlsafe(32)
        if not conn.execute(
                "SELECT id FROM erp_mkt_surveys WHERE public_key = ?",
                (cand,)).fetchone():
            key = cand
            break
    if key is None:
        conn.close()
        return jsonify(error="could not allocate a survey link"), 500
    cur = conn.execute(
        "INSERT INTO erp_mkt_surveys (title, description, active,"
        " public_key, created_by, created_at, updated_by, updated_at)"
        " VALUES (?, ?, ?, ?, ?, ?, ?, ?)",
        (fields["title"], fields["description"], fields["active"], key,
         actor, now, actor, now))
    sid = cur.lastrowid
    _erp_staff_audit(conn, actor, "marketing.survey_created", "survey",
                     sid, fields["title"])
    conn.commit()
    row = conn.execute(
        "SELECT * FROM erp_mkt_surveys WHERE id = ?", (sid,)).fetchone()
    out = _mkt_survey_dict(conn, row)
    conn.close()
    return jsonify(ok=True, survey=out), 201


