@app.post("/api/erp/marketing/surveys/<int:survey_id>/update")
def mkt_survey_update(survey_id):
    actor, err = _require_erp_admin()
    if err:
        return err
    data = request.get_json(force=True) or {}
    conn = db()
    row = conn.execute("SELECT * FROM erp_mkt_surveys WHERE id = ?",
                       (survey_id,)).fetchone()
    if not row:
        conn.close()
        return jsonify(error="survey not found"), 404
    title = row["title"]
    desc = row["description"] or ""
    active = row["active"]
    if "title" in data:
        t = data.get("title")
        if not isinstance(t, str) or not t.strip():
            conn.close()
            return jsonify(error="title is required"), 400
        if len(t.strip()) > 200:
            conn.close()
            return jsonify(
                error="title is too long (max 200 characters)"), 400
        title = t.strip()
    if "description" in data:
        d = data.get("description")
        if not isinstance(d, str) or len(d.strip()) > 2000:
            conn.close()
            return jsonify(
                error="description is too long (max 2000 characters)"), 400
        desc = d.strip()
    if "active" in data:
        a = data.get("active")
        if not isinstance(a, bool):
            conn.close()
            return jsonify(error="active must be true or false"), 400
        active = 1 if a else 0
    now = datetime.now(timezone.utc).isoformat()
    conn.execute(
        "UPDATE erp_mkt_surveys SET title = ?, description = ?,"
        " active = ?, updated_by = ?, updated_at = ? WHERE id = ?",
        (title, desc, active, actor, now, survey_id))
    _erp_staff_audit(conn, actor, "marketing.survey_updated", "survey",
                     survey_id, title)
    conn.commit()
    row = conn.execute("SELECT * FROM erp_mkt_surveys WHERE id = ?",
                       (survey_id,)).fetchone()
    out = _mkt_survey_dict(conn, row)
    conn.close()
    return jsonify(ok=True, survey=out)


