@app.post("/api/erp/settings/itsm/changes/<int:change_id>/update")
def itsm_change_update(change_id):
    actor, err = _require_erp_admin()
    if err:
        return err
    data = request.get_json(force=True) or {}
    fields, verr = _itsm_change_validate(data, partial=True)
    if verr:
        return jsonify(error=verr), 400
    if "status" in data:
        return jsonify(
            error="status moves only through approve, implement, or"
                  " roll back"), 400
    if not fields:
        return jsonify(error="nothing to update"), 400
    conn = db()
    row = conn.execute(
        "SELECT * FROM erp_it_changes WHERE id = ?",
        (change_id,)).fetchone()
    if not row:
        conn.close()
        return jsonify(error="IT change not found"), 404
    if row["status"] not in ("requested", "approved"):
        conn.close()
        return jsonify(
            error="a %s change cannot be edited" % row["status"]), 400
    if "asset_id" in fields:
        asset, aerr = _itsm_check_asset(conn, fields["asset_id"])
        if aerr:
            conn.close()
            return jsonify(error=aerr), 400
        fields["asset_id"] = asset["id"] if asset else None
    sets = []
    vals = []
    for col in ("title", "description", "reason", "risk",
                "planned_date", "planned_window", "asset_id"):
        if col in fields:
            sets.append("%s = ?" % col)
            vals.append(fields[col])
    now = datetime.now(timezone.utc).isoformat()
    sets.append("updated_by = ?")
    vals.append(actor)
    sets.append("updated_at = ?")
    vals.append(now)
    conn.execute("UPDATE erp_it_changes SET %s WHERE id = ?"
                 % ", ".join(sets), vals + [change_id])
    _erp_staff_audit(conn, actor, "settings.itsm_change_updated",
                     "it_change", change_id, row["title"])
    conn.commit()
    row = conn.execute(
        "SELECT * FROM erp_it_changes WHERE id = ?", (change_id,)).fetchone()
    out = _itsm_change_dict(conn, row)
    conn.close()
    return jsonify(ok=True, change=out)


@app.post("/api/erp/settings/itsm/changes/<int:change_id>/approve")
def itsm_change_approve(change_id):
    """Approve a requested change. The approver must be an admin
    OTHER than the requester (the B9 / bill-pay self-approve rule):
    with two admins, the second admin approves; the requester
    approving their own change is a 403, never a silent pass."""
    actor, err = _require_erp_admin()
    if err:
        return err
    conn = db()
    row = conn.execute(
        "SELECT * FROM erp_it_changes WHERE id = ?",
        (change_id,)).fetchone()
    if not row:
        conn.close()
        return jsonify(error="IT change not found"), 404
    if row["status"] != "requested":
        conn.close()
        return jsonify(
            error="only a requested change can be approved"), 400
    if actor == (row["requested_by"] or ""):
        conn.close()
        return jsonify(
            error="you cannot approve your own change"), 403
    now = datetime.now(timezone.utc).isoformat()
    conn.execute(
        "UPDATE erp_it_changes SET status = 'approved',"
        " approved_by = ?, approved_at = ?, updated_by = ?,"
        " updated_at = ? WHERE id = ?",
        (actor, now, actor, now, change_id))
    _erp_staff_audit(conn, actor, "settings.itsm_change_approved",
                     "it_change", change_id, row["title"])
    conn.commit()
    row = conn.execute(
        "SELECT * FROM erp_it_changes WHERE id = ?", (change_id,)).fetchone()
    out = _itsm_change_dict(conn, row)
    conn.close()
    return jsonify(ok=True, change=out)


@app.post("/api/erp/settings/itsm/changes/<int:change_id>/implement")
def itsm_change_implement(change_id):
    """Record that an approved change was implemented. This only
    records what an admin did after the fact -- it applies nothing
    itself, and it cannot run on a change that was never approved."""
    actor, err = _require_erp_admin()
    if err:
        return err
    data = request.get_json(force=True) or {}
    note = data.get("implemented_note")
    if note is not None and (not isinstance(note, str)
                             or len(note.strip()) > _IT_NOTE_MAX):
        return jsonify(
            error="implemented_note is too long (max 2000 characters)"), 400
    conn = db()
    row = conn.execute(
        "SELECT * FROM erp_it_changes WHERE id = ?",
        (change_id,)).fetchone()
    if not row:
        conn.close()
        return jsonify(error="IT change not found"), 404
    if row["status"] != "approved":
        conn.close()
        return jsonify(
            error="only an approved change can be implemented"), 400
    now = datetime.now(timezone.utc).isoformat()
    conn.execute(
        "UPDATE erp_it_changes SET status = 'implemented',"
        " implemented_note = ?, updated_by = ?, updated_at = ?"
        " WHERE id = ?",
        ((note or "").strip() if note is not None
         else (row["implemented_note"] or ""), actor, now, change_id))
    _erp_staff_audit(conn, actor, "settings.itsm_change_implemented",
                     "it_change", change_id, row["title"])
    conn.commit()
    row = conn.execute(
        "SELECT * FROM erp_it_changes WHERE id = ?", (change_id,)).fetchone()
    out = _itsm_change_dict(conn, row)
    conn.close()
    return jsonify(ok=True, change=out)


@app.post("/api/erp/settings/itsm/changes/<int:change_id>/rollback")
def itsm_change_rollback(change_id):
    """Record that an approved or implemented change was rolled back.
    A requested change has nothing to roll back, and a rolled-back
    change stays rolled back -- it is never re-approved."""
    actor, err = _require_erp_admin()
    if err:
        return err
    conn = db()
    row = conn.execute(
        "SELECT * FROM erp_it_changes WHERE id = ?",
        (change_id,)).fetchone()
    if not row:
        conn.close()
        return jsonify(error="IT change not found"), 404
    if row["status"] not in ("approved", "implemented"):
        conn.close()
        return jsonify(
            error="only an approved or implemented change can be"
                  " rolled back"), 400
    now = datetime.now(timezone.utc).isoformat()
    conn.execute(
        "UPDATE erp_it_changes SET status = 'rolled back',"
        " updated_by = ?, updated_at = ? WHERE id = ?",
        (actor, now, change_id))
    _erp_staff_audit(conn, actor, "settings.itsm_change_rolled_back",
                     "it_change", change_id, row["title"])
    conn.commit()
    row = conn.execute(
        "SELECT * FROM erp_it_changes WHERE id = ?", (change_id,)).fetchone()
    out = _itsm_change_dict(conn, row)
    conn.close()
    return jsonify(ok=True, change=out)


@app.delete("/api/erp/settings/itsm/changes/<int:change_id>")
def itsm_change_delete(change_id):
    actor, err = _require_erp_admin()
    if err:
        return err
    conn = db()
    row = conn.execute(
        "SELECT * FROM erp_it_changes WHERE id = ?",
        (change_id,)).fetchone()
    if not row:
        conn.close()
        return jsonify(error="IT change not found"), 404
    conn.execute("DELETE FROM erp_it_changes WHERE id = ?", (change_id,))
    _erp_staff_audit(conn, actor, "settings.itsm_change_deleted",
                     "it_change", change_id, row["title"])
    conn.commit()
    conn.close()
    return jsonify(ok=True, id=change_id, deleted=True)


# ---------------- ERP loyalty console (Dept 8 item 3, Nov 2026) ----------------
# The storefront staff console (#staff-loyalty) stays live until the
# removal step; these ERP-gated endpoints call the same internal ledger
# helpers (_credit_kernels, _debit_kernels, _kernel_balance,
# _loyalty_tier, _credit_staff_kernels) so the money logic stays
# single-sourced. No daily cap exists anywhere in the backend and none
# is invented here; Kernel Catch stays demo-only and is not offered.

def _erp_loyalty_actor_staff_id(conn):
    """Resolve the ERP actor's staff row by exact email match.

    Returns (email, staff_id_or_None). Matt's admin email
    (matt@fudgetopia.net) has no staff row (his is
    matt@pop-a-licious.com): member credit/redeem/signup still work
    with staff_id NULL, and My profile / self-redeem show a note to
    sign in via the Staff tab instead of failing. Never invents a
    staff row or attributes one person's work to another."""
    role = _erp_role()
    email = ""
    if role == "admin":
        user = _current_member()
        email = (user["email"] if user else "") or ""
    elif role == "staff":
        staff = _staff_from_request()
        email = (staff["email"] if staff else "") or ""
    staff_id = None
    if email:
        row = conn.execute(
            "SELECT id FROM staff WHERE LOWER(email) = LOWER(?)", (email,)
        ).fetchone()
        if row:
            staff_id = row["id"]
    return email, staff_id


_ERP_LOYALTY_NO_STAFF_NOTE = (
    "No staff record matches this login email — sign in via the Staff tab "
    "to use your own profile and rewards. Member lookup, credit, and "
    "redeem still work.")


@app.get("/api/erp/loyalty/members")
def erp_loyalty_members():
    """Member lookup for the counter. Same search as
    /api/loyalty/staff/members (QR URL, PAL:<id>, email, name; max 20),
    plus the customer reward tiers/labels so the console paints redeem
    buttons from live values, never hardcoded costs."""
    actor, err = _erp_check_perm("loyalty.read")
    if err:
        return err
    conn = db()
    members = _loyalty_member_search(conn, request.args.get("q") or "")
    catalog = _reward_catalog(conn)
    conn.close()
    return jsonify(
        members=members,
        reward_tiers={k: v["kernels"] for k, v in catalog.items()},
        reward_labels={k: v["label"] for k, v in catalog.items()})


@app.post("/api/erp/loyalty/credit")
def erp_loyalty_credit():
    """Credit Kernels for an in-person sale. Body: {user_id, amount_cents, note?}
    ERP-gated mirror of /api/loyalty/staff/credit ($1,000/sale cap)."""
    actor, err = _erp_check_perm("loyalty.write")
    if err:
        return err
    data = request.get_json(force=True) or {}
    try:
        user_id = int(data.get("user_id") or 0)
        amount_cents = int(data.get("amount_cents") or 0)
    except (TypeError, ValueError):
        return jsonify(error="invalid input"), 400
    if user_id <= 0 or amount_cents <= 0 or amount_cents > 100000:
        return jsonify(error="invalid input"), 400
    kernels = max(amount_cents // 100 * KERNELS_PER_DOLLAR, 0)
    conn = db()
    _, staff_id = _erp_loyalty_actor_staff_id(conn)
    mrow = conn.execute("SELECT active FROM users WHERE id = ?", (user_id,)).fetchone()
    if not mrow:
        conn.close()
        return jsonify(error="member not found"), 404
    if not mrow["active"]:
        conn.close()
        return jsonify(error="member account is deactivated"), 403
    credited = _credit_kernels(conn, user_id, kernels, "in_person",
                               order_ref=(data.get("note") or "")[:120], staff_id=staff_id)
    conn.commit()
    balance = _kernel_balance(conn, user_id)
    conn.close()
    return jsonify(ok=True, kernels_credited=credited, balance=balance)


@app.post("/api/erp/loyalty/redeem-member")
def erp_loyalty_redeem_member():
    """Redeem a reward on a member's behalf in person. Body: {user_id, reward_type}
    ERP-gated mirror of staff_redeem_for_member; free shipping is online only.
    Distinct route name — the /api/loyalty/staff/redeem collision is not repeated."""
    actor, err = _erp_check_perm("loyalty.write")
    if err:
        return err
    data = request.get_json(force=True) or {}
    try:
        user_id = int(data.get("user_id") or 0)
    except (TypeError, ValueError):
        return jsonify(error="invalid input"), 400
    reward_type = (data.get("reward_type") or "").strip()
    if user_id <= 0:
        return jsonify(error="invalid input"), 400
    conn = db()
    tier = _reward_catalog_row(conn, reward_type)
    if not tier:
        conn.close()
        return jsonify(error="invalid input"), 400
    if reward_type == "free_shipping":
        conn.close()
        return jsonify(error="Free shipping rewards are online only and can't be redeemed in person"), 400
    _, staff_id = _erp_loyalty_actor_staff_id(conn)
    mrow = conn.execute("SELECT active FROM users WHERE id = ?", (user_id,)).fetchone()
    if not mrow:
        conn.close()
        return jsonify(error="member not found"), 404
    if not mrow["active"]:
        conn.close()
        return jsonify(error="member account is deactivated"), 403
    code = _new_reward_code()
    if not _debit_kernels(conn, user_id, tier["kernels"], "redemption_in_person",
                          order_ref=code, staff_id=staff_id):
        conn.close()
        return jsonify(error="not enough Kernels"), 402
    conn.execute(
        "INSERT INTO loyalty_rewards (user_id, reward_type, code, kernels_spent, staff_id, created_at)"
        " VALUES (?, ?, ?, ?, ?, ?)",
        (user_id, reward_type, code, tier["kernels"], staff_id,
         datetime.now(timezone.utc).isoformat()),
    )
    conn.commit()
    balance = _kernel_balance(conn, user_id)
    # In person the reward is applied on the spot, so mark it used immediately.
    conn.execute(
        "UPDATE loyalty_rewards SET used = 1, used_at = ? WHERE code = ?",
        (datetime.now(timezone.utc).isoformat(), code),
    )
    conn.commit()
    conn.close()
    return jsonify(ok=True, label=tier["label"], balance=balance)


@app.post("/api/erp/loyalty/signup-member")
def erp_loyalty_signup_member():
    """Staff registers a new customer in person. Body: {name, email, password}
    ERP-gated mirror of /api/loyalty/staff/signup-member; the acting staff
    member earns 1 Kernel when they have a staff row, otherwise no credit
    is invented and staff_kernels comes back null."""
    actor, err = _erp_check_perm("loyalty.write")
    if err:
        return err
    data = request.get_json(force=True) or {}
    name = (data.get("name") or "").strip()
    email = (data.get("email") or "").strip().lower()
    password = data.get("password") or ""
    if not name:
        return jsonify(error="please enter the customer's name"), 400
    if not EMAIL_RE.match(email):
        return jsonify(error="please enter a valid email address"), 400
    if len(password) < 8:
        return jsonify(error="password must be at least 8 characters"), 400
    conn = db()
    _, staff_id = _erp_loyalty_actor_staff_id(conn)
    existing = conn.execute(
        "SELECT id, active FROM users WHERE email = ?", (email,)
    ).fetchone()
    if existing and existing["active"]:
        conn.close()
        return jsonify(error="an account with this email already exists"), 409
    if existing:
        conn.execute("DELETE FROM users WHERE id = ?", (existing["id"],))
    now = datetime.now(timezone.utc).isoformat()
    cur = conn.execute(
        "INSERT INTO users (email, name, password_hash, verified, created_at)"
        " VALUES (?, ?, ?, 0, ?)",
        (email, name, generate_password_hash(password), now),
    )
    user_id = cur.lastrowid
    token = secrets.token_urlsafe(32)
    expires = (datetime.now(timezone.utc) + timedelta(hours=24)).isoformat()
    conn.execute(
        "INSERT INTO verification_tokens (token, user_id, expires_at) VALUES (?, ?, ?)",
        (token, user_id, expires),
    )
    # Customer referral: a referral row an admin created for this email
    # moves invited -> signed_up (SOP 8.25).
    _mkt_link_referral_signup(conn, user_id, email)
    staff_kernels = None
    if staff_id is not None:
        _credit_staff_kernels(conn, staff_id, 1, "member_signup", ref=email)
        conn.commit()
        staff_kernels = conn.execute(
            "SELECT kernels FROM staff WHERE id = ?", (staff_id,)
        ).fetchone()["kernels"]
    else:
        conn.commit()
    conn.close()
    verify_url = f"{SITE_URL}/#verify?token={token}"
    try:
        send_email(email, "Verify your Pop-A-Licious account",
                   f"Hi {name},\n\nPlease verify your account:\n{verify_url}\n")
    except Exception:
        pass
    return jsonify(ok=True, user_id=user_id, staff_kernels=staff_kernels)


