# ---------- Loyalty tiers + reward catalog (Dept 8, SOPs 8.23-8.24) ----------
# Wave 3 commercial 4 (Nov 24, 2026): tier thresholds, earn multipliers,
# birthday bonuses and the reward catalog are admin-editable tables, seeded
# once from the code constants they replaced (tiers 0/300/1000, catalog
# 50/100/150/300). Tiers are computed from lifetime Kernels on every read
# (never stored), so a threshold change re-tiers members on next read.
# Kernels never expire and tiers never auto-downgrade while the tier
# rules are off (SOP 8.32, Wave 3 section 4.2 item 12 -- the rules ship
# off and only an admin enabling one changes that). Same gate as the
# other ERP loyalty endpoints: loyalty.read for reads, loyalty.write
# for writes.
# Tiers + catalog survive a data reset (not in _ERP_RESET_TABLES): they are
# admin-entered program definitions like the other erp_mkt_* tables.


def _loyalty_tier_row_dict(row, member_count=None):
    out = {"id": row["id"], "name": row["name"],
           "min_lifetime_kernels": int(row["min_lifetime_kernels"]),
           "earn_multiplier_x100": int(row["earn_multiplier_x100"]),
           "birthday_bonus_kernels": int(row["birthday_bonus_kernels"]),
           "active": int(row["active"]),
           "created_by": row["created_by"] or "",
           "created_at": row["created_at"] or "",
           "updated_by": row["updated_by"] or "",
           "updated_at": row["updated_at"] or ""}
    if member_count is not None:
        out["member_count"] = member_count
    return out


def _loyalty_reward_row_dict(row):
    return {"id": row["id"], "reward_key": row["reward_key"],
            "label": row["label"], "kernels": int(row["kernels"]),
            "active": int(row["active"]),
            "created_by": row["created_by"] or "",
            "created_at": row["created_at"] or "",
            "updated_by": row["updated_by"] or "",
            "updated_at": row["updated_at"] or ""}


def _loyalty_tier_thresholds_ok(conn, exclude_id, min_kernels):
    """True when the tier ladder stays strictly increasing with the given
    threshold in place of the excluded tier's (None = a new tier)."""
    others = [int(r["min_lifetime_kernels"]) for r in conn.execute(
        "SELECT min_lifetime_kernels FROM erp_loyalty_tiers WHERE id != ?",
        (exclude_id or 0,)).fetchall()]
    return len(set(others + [min_kernels])) == len(others) + 1


def _loyalty_tier_has_base(conn, exclude_id, min_kernels):
    """True when at least one tier still starts at 0 Kernels with the
    given threshold in place -- the base tier must always exist."""
    others = [int(r["min_lifetime_kernels"]) for r in conn.execute(
        "SELECT min_lifetime_kernels FROM erp_loyalty_tiers WHERE id != ?",
        (exclude_id or 0,)).fetchall()]
    return 0 in others + [min_kernels]


def _loyalty_int_field(data, field, minimum=None, maximum=None, default=None):
    """An integer body field (bool is not an integer). When the field is
    absent and a default is given, the default is used. Returns (value, error)."""
    if field not in data or data.get(field) is None:
        if default is not None:
            return default, None
        return None, "%s must be a whole number" % field
    v = data.get(field)
    if isinstance(v, bool) or not isinstance(v, int):
        return None, "%s must be a whole number" % field
    if minimum is not None and v < minimum:
        return None, "%s must be at least %d" % (field, minimum)
    if maximum is not None and v > maximum:
        return None, "%s must be at most %d" % (field, maximum)
    return v, None


def _loyalty_active_field(data, default=1):
    """An active flag: 0/1 (or true/false). Returns (value, error)."""
    active = data.get("active", default)
    if isinstance(active, bool):
        active = 1 if active else 0
    if active not in (0, 1):
        return None, "active must be 0 or 1"
    return active, None


# ---------------- Referral program (Dept 8, SOP 8.25, Wave 3 commercial 5) ----------------
# Customer refer-a-friend. The register is admin-only; reads use the
# existing any-read Marketing gate. No delete endpoint -- referral rows
# are an audit trail. One referral (and one reward) per referred email
# ever; self-referral is refused; a reward needs the referred
# customer's first paid order on file. The reward credits the
# configured Kernels to BOTH referrer and referred via _add_kernels
# (so a member above the base tier earns through their tier
# multiplier, recorded on the transaction -- see SOP 8.25); a blank
# reward setting still records the reward, with 0 Kernels granted.
_MKT_REFERRAL_STATUSES = ("invited", "signed_up", "rewarded")


@app.get("/api/erp/marketing/referrals")
def mkt_referrals_list():
    actor, err = _mkt_check_any_read()
    if err:
        return err
    status = (request.args.get("status") or "").strip()
    if status and status not in _MKT_REFERRAL_STATUSES:
        return jsonify(error="unknown status"), 400
    conn = db()
    counts = {"invited": 0, "signed_up": 0, "rewarded": 0, "total": 0}
    for r in conn.execute(
            "SELECT status, COUNT(*) AS n FROM erp_mkt_referrals"
            " GROUP BY status").fetchall():
        if r["status"] in counts:
            counts[r["status"]] = r["n"]
        counts["total"] += r["n"]
    q = "SELECT * FROM erp_mkt_referrals"
    args = []
    if status:
        q += " WHERE status = ?"
        args.append(status)
    q += " ORDER BY id DESC"
    rows = conn.execute(q, args).fetchall()
    out = [_mkt_referral_dict(conn, r) for r in rows]
    reward = _mkt_referral_reward_kernels(conn)
    conn.close()
    return jsonify(referrals=out, counts=counts, count=len(out),
                   reward_kernels=reward)


@app.post("/api/erp/marketing/referrals")
def mkt_referral_create():
    actor, err = _require_erp_admin()
    if err:
        return err
    data = request.get_json(force=True) or {}
    referred_email = (data.get("referred_email") or "").strip().lower()
    if not EMAIL_RE.match(referred_email):
        return jsonify(error="please enter a valid referred email address"), 400
    referrer_user_id = data.get("referrer_user_id")
    referrer_email = (data.get("referrer_email") or "").strip().lower()
    conn = db()
    referrer = None
    if referrer_user_id is not None:
        try:
            referrer_user_id = int(referrer_user_id)
        except (TypeError, ValueError):
            conn.close()
            return jsonify(error="referrer_user_id must be a whole number"), 400
        referrer = conn.execute(
            "SELECT id, email FROM users WHERE id = ?",
            (referrer_user_id,)).fetchone()
    elif referrer_email:
        if not EMAIL_RE.match(referrer_email):
            conn.close()
            return jsonify(error="please enter a valid referrer email address"), 400
        referrer = conn.execute(
            "SELECT id, email FROM users WHERE lower(email) = lower(?)",
            (referrer_email,)).fetchone()
    if not referrer:
        conn.close()
        return jsonify(error="referrer is not a loyalty member"), 400
    if (referrer["email"] or "").strip().lower() == referred_email:
        conn.close()
        return jsonify(error="you cannot refer yourself"), 400
    if conn.execute(
            "SELECT id FROM erp_mkt_referrals"
            " WHERE lower(referred_email) = lower(?)",
            (referred_email,)).fetchone():
        conn.close()
        return jsonify(error="a referral already exists for this email"), 409
    # The referred customer may already have an account (referred
    # before the row was recorded) -- link it now instead of waiting
    # for a signup that will never come again.
    referred = conn.execute(
        "SELECT id FROM users WHERE lower(email) = lower(?)",
        (referred_email,)).fetchone()
    now = datetime.now(timezone.utc).isoformat()
    try:
        cur = conn.execute(
            "INSERT INTO erp_mkt_referrals (referrer_user_id, referred_email,"
            " referred_user_id, status, created_by, created_at)"
            " VALUES (?, ?, ?, ?, ?, ?)",
            (referrer["id"], referred_email,
             referred["id"] if referred else None,
             "signed_up" if referred else "invited", actor, now))
    except sqlite3.IntegrityError:
        conn.close()
        return jsonify(error="a referral already exists for this email"), 409
    rid = cur.lastrowid
    _erp_staff_audit(conn, actor, "marketing.referral_created",
                     "referral", rid,
                     "%s referred %s" % (referrer["email"], referred_email))
    conn.commit()
    conn.close()
    return jsonify(ok=True, referral_id=rid), 201


@app.post("/api/erp/marketing/referrals/settings")
def mkt_referral_settings_save():
    actor, err = _require_erp_admin()
    if err:
        return err
    data = request.get_json(force=True) or {}
    if "reward_kernels" not in data:
        return jsonify(error="reward_kernels is required"), 400
    v = data.get("reward_kernels")
    if v is None or v == "":
        value = ""
    elif isinstance(v, bool) or not isinstance(v, int) or v < 0:
        return jsonify(error="reward_kernels must be a whole number of 0 or more, or blank"), 400
    else:
        value = str(v)
    conn = db()
    conn.execute(
        "INSERT INTO erp_mkt_referral_settings (key, value) VALUES ('reward_kernels', ?)"
        " ON CONFLICT(key) DO UPDATE SET value = excluded.value",
        (value,))
    _erp_staff_audit(conn, actor, "marketing.referral_settings_updated",
                     "referral_settings", 0,
                     "reward_kernels=%s" % (value or "blank"))
    conn.commit()
    conn.close()
    return jsonify(ok=True,
                   reward_kernels=int(value) if value != "" else None)


@app.post("/api/erp/marketing/referrals/<int:referral_id>/reward")
def mkt_referral_reward(referral_id):
    actor, err = _require_erp_admin()
    if err:
        return err
    conn = db()
    row = conn.execute("SELECT * FROM erp_mkt_referrals WHERE id = ?",
                       (referral_id,)).fetchone()
    if not row:
        conn.close()
        return jsonify(error="referral not found"), 404
    if row["status"] == "rewarded":
        conn.close()
        return jsonify(error="this referral has already been rewarded"), 409
    if conn.execute(
            "SELECT id FROM erp_mkt_referrals"
            " WHERE lower(referred_email) = lower(?) AND status = 'rewarded'"
            " AND id != ?", (row["referred_email"], referral_id)).fetchone():
        conn.close()
        return jsonify(error="this email has already been rewarded"), 409
    if not row["referred_user_id"] or row["status"] == "invited":
        conn.close()
        return jsonify(error="the referred customer has not signed up yet"), 400
    referrer = conn.execute(
        "SELECT id, name, email FROM users WHERE id = ?",
        (row["referrer_user_id"],)).fetchone()
    referred = conn.execute(
        "SELECT id, name, email FROM users WHERE id = ?",
        (row["referred_user_id"],)).fetchone()
    if referrer and referred and \
            (referrer["email"] or "").strip().lower() == (referred["email"] or "").strip().lower():
        conn.close()
        return jsonify(error="you cannot refer yourself"), 400
    if not _mkt_referral_has_paid_order(conn, row["referred_email"]):
        conn.close()
        return jsonify(error="the referred customer has not placed a paid order yet"), 400
    amount = _mkt_referral_reward_kernels(conn)
    per_person = amount if amount is not None else 0
    if per_person > 0 and (not referrer or not referred):
        conn.close()
        return jsonify(error="the referrer or referred member record is missing"), 400
    credited_referrer = 0
    credited_referred = 0
    if per_person > 0:
        credited_referrer = _add_kernels(
            conn, referrer["id"], per_person,
            "Referral reward: referred %s" % row["referred_email"])
        credited_referred = _add_kernels(
            conn, referred["id"], per_person,
            "Referral reward: referred by %s"
            % (referrer["name"] or referrer["email"]))
    now = datetime.now(timezone.utc).isoformat()
    conn.execute(
        "UPDATE erp_mkt_referrals SET status = 'rewarded',"
        " reward_kernels = ?, rewarded_at = ? WHERE id = ?",
        (per_person, now, referral_id))
    _erp_staff_audit(conn, actor, "marketing.referral_rewarded",
                     "referral", referral_id,
                     "%s Kernels each to %s and %s"
                     % (per_person, referrer["email"] if referrer else "?",
                        row["referred_email"]))
    conn.commit()
    conn.close()
    return jsonify(ok=True, referral_id=referral_id, status="rewarded",
                   reward_kernels=per_person,
                   credited_referrer=credited_referrer,
                   credited_referred=credited_referred)


# ---------- Retail customer RMA (Dept 8, SOP 8.27, Wave 3 commercial 7) ----------
# Retail mirror of the wholesale returns (Dept 5, SOP 5.13) --
# deliberately a separate table: wholesale returns carry
# account/credit terms; retail returns carry the replacement-only
# policy. NO REFUNDS, EVER: the table has no money column by design,
# and there is no refund endpoint, no credit note, and no delete
# endpoint -- returns are an audit trail. A return's only resolutions
# are linking the replacement (reshipment) order, which moves it to
# replacement_sent, or closing it with a note. One open return per
# order (a second open return for the same order -> 409). Reads use
# the any-read Marketing gate; writes use support.write (the live
# permission names, confirmed against the permission table -- no new
# permission is invented). A retail replacement recorded here can be
# linked from a complaint via the existing B5 complaint-linkage
# (erp_quality_complaint_links, link_type retail_replacement) -- that
# linkage is NOT rebuilt here, and it carries no return id, so the
# Returns detail cannot resolve linked complaints from it (follow-up:
# give the links table a return id if that view is wanted).

_MKT_RETURN_STATUSES = ("open", "replacement_sent", "closed")


def _mkt_paid_order(conn, source, order_id):
    """The paid retail order for a return, or None. A Stripe `orders`
    row exists only for a captured checkout (demo rows excluded -- a
    demo order was never billed); a PayPal row counts only once
    captured. Wholesale orders are never retail returns."""
    if source == "stripe":
        return conn.execute(
            "SELECT * FROM orders WHERE id = ? AND is_demo = 0",
            (order_id,)).fetchone()
    if source == "paypal":
        return conn.execute(
            "SELECT * FROM paypal_orders WHERE id = ?"
            " AND status = 'captured'", (order_id,)).fetchone()
    return None


def _mkt_return_dict(conn, r):
    """Public shape for one erp_mkt_returns row, with the original
    order and (once linked) the replacement order attached."""
    d = dict(r)
    d["order"] = _erp_order_brief(conn, r["order_source"], r["order_id"])
    if r["replacement_order_source"] and r["replacement_order_id"]:
        d["replacement_order"] = _erp_order_brief(
            conn, r["replacement_order_source"],
            r["replacement_order_id"])
    else:
        d["replacement_order"] = None
    return d


@app.get("/api/erp/marketing/returns")
def mkt_returns_list():
    actor, err = _mkt_check_any_read()
    if err:
        return err
    status = (request.args.get("status") or "").strip()
    if status and status not in _MKT_RETURN_STATUSES:
        return jsonify(error="unknown status"), 400
    q = (request.args.get("q") or "").strip().lower()
    conn = db()
    counts = {"open": 0, "replacement_sent": 0, "closed": 0, "total": 0}
    for r in conn.execute(
            "SELECT status, COUNT(*) AS n FROM erp_mkt_returns"
            " GROUP BY status").fetchall():
        if r["status"] in counts:
            counts[r["status"]] = r["n"]
        counts["total"] += r["n"]
    query = "SELECT * FROM erp_mkt_returns"
    args = []
    if status:
        query += " WHERE status = ?"
        args.append(status)
    query += " ORDER BY id DESC"
    rows = conn.execute(query, args).fetchall()
    out = []
    for r in rows:
        if q and q not in (r["customer_email"] or "").lower() \
                and q not in (r["reason"] or "").lower():
            continue
        out.append(_mkt_return_dict(conn, r))
    conn.close()
    return jsonify(returns=out, counts=counts, count=len(out))


@app.get("/api/erp/marketing/returns/<int:return_id>")
def mkt_return_detail(return_id):
    actor, err = _mkt_check_any_read()
    if err:
        return err
    conn = db()
    row = conn.execute("SELECT * FROM erp_mkt_returns WHERE id = ?",
                       (return_id,)).fetchone()
    if not row:
        conn.close()
        return jsonify(error="return not found"), 404
    out = _mkt_return_dict(conn, row)
    conn.close()
    return jsonify(ret=out)


@app.post("/api/erp/marketing/returns")
def mkt_return_create():
    actor, err = _erp_check_perm("support.write")
    if err:
        return err
    data = request.get_json(force=True) or {}
    order_source = (data.get("order_source") or "").strip().lower()
    if order_source not in ("stripe", "paypal"):
        return jsonify(error="order_source must be stripe or paypal"), 400
    try:
        order_id = int(data.get("order_id"))
    except (TypeError, ValueError):
        return jsonify(error="order_id must be a whole number"), 400
    reason = (data.get("reason") or "").strip()
    if not reason:
        return jsonify(error="reason is required"), 400
    if len(reason) > 2000:
        return jsonify(error="reason must be 2000 characters or fewer"), 400
    conn = db()
    order = _mkt_paid_order(conn, order_source, order_id)
    if not order:
        conn.close()
        return jsonify(error="order not found or not paid"), 400
    email = (data.get("customer_email") or "").strip().lower()
    if not email:
        email = (order["email"] or "").strip().lower()
    if "@" not in email or "." not in email.split("@", 1)[1]:
        conn.close()
        return jsonify(error="a valid customer email is required"), 400
    if conn.execute(
            "SELECT id FROM erp_mkt_returns WHERE order_source = ?"
            " AND order_id = ? AND status = 'open'",
            (order_source, order_id)).fetchone():
        conn.close()
        return jsonify(error="an open return already exists for this"
                       " order"), 409
    now = datetime.now(timezone.utc).isoformat()
    cur = conn.execute(
        "INSERT INTO erp_mkt_returns (order_source, order_id,"
        " customer_email, reason, status, created_by, created_at,"
        " updated_by, updated_at)"
        " VALUES (?, ?, ?, ?, 'open', ?, ?, ?, ?)",
        (order_source, order_id, email, reason, actor, now, actor, now))
    rid = cur.lastrowid
    _erp_staff_audit(conn, actor, "marketing.return_created",
                     "return", rid,
                     "%s order #%d (%s): %s"
                     % (order_source, order_id, email, reason[:120]))
    conn.commit()
    row = conn.execute("SELECT * FROM erp_mkt_returns WHERE id = ?",
                       (rid,)).fetchone()
    out = _mkt_return_dict(conn, row)
    conn.close()
    return jsonify(ok=True, ret=out), 201


@app.post("/api/erp/marketing/returns/<int:return_id>/link-replacement")
def mkt_return_link_replacement(return_id):
    actor, err = _erp_check_perm("support.write")
    if err:
        return err
    data = request.get_json(force=True) or {}
    conn = db()
    row = conn.execute("SELECT * FROM erp_mkt_returns WHERE id = ?",
                       (return_id,)).fetchone()
    if not row:
        conn.close()
        return jsonify(error="return not found"), 404
    if (row["status"] or "") != "open":
        conn.close()
        return jsonify(error="only open returns can link a replacement"
                       " order"), 409
    repl_source = (data.get("replacement_order_source") or "").strip().lower()
    if repl_source not in ("stripe", "paypal"):
        conn.close()
        return jsonify(error="replacement_order_source must be stripe"
                       " or paypal"), 400
    try:
        repl_id = int(data.get("replacement_order_id"))
    except (TypeError, ValueError):
        conn.close()
        return jsonify(error="replacement_order_id must be a whole"
                       " number"), 400
    if repl_source == row["order_source"] and repl_id == row["order_id"]:
        conn.close()
        return jsonify(error="the replacement order cannot be the"
                       " original order"), 400
    if not _mkt_paid_order(conn, repl_source, repl_id):
        conn.close()
        return jsonify(error="replacement order not found or not paid"), 400
    now = datetime.now(timezone.utc).isoformat()
    conn.execute(
        "UPDATE erp_mkt_returns SET status = 'replacement_sent',"
        " replacement_order_source = ?, replacement_order_id = ?,"
        " updated_by = ?, updated_at = ? WHERE id = ?",
        (repl_source, repl_id, actor, now, return_id))
    _erp_staff_audit(conn, actor, "marketing.replacement_linked",
                     "return", return_id,
                     "replacement %s order #%d linked to %s order #%d"
                     % (repl_source, repl_id, row["order_source"],
                        row["order_id"]))
    conn.commit()
    row = conn.execute("SELECT * FROM erp_mkt_returns WHERE id = ?",
                       (return_id,)).fetchone()
    out = _mkt_return_dict(conn, row)
    conn.close()
    return jsonify(ok=True, ret=out)


@app.post("/api/erp/marketing/returns/<int:return_id>/close")
def mkt_return_close(return_id):
    actor, err = _erp_check_perm("support.write")
    if err:
        return err
    data = request.get_json(force=True) or {}
    note = (data.get("note") or "").strip()
    if not note:
        return jsonify(error="a close note is required"), 400
    if len(note) > 2000:
        return jsonify(error="note must be 2000 characters or fewer"), 400
    conn = db()
    row = conn.execute("SELECT * FROM erp_mkt_returns WHERE id = ?",
                       (return_id,)).fetchone()
    if not row:
        conn.close()
        return jsonify(error="return not found"), 404
    if (row["status"] or "") == "closed":
        conn.close()
        return jsonify(error="this return is already closed"), 409
    now = datetime.now(timezone.utc).isoformat()
    conn.execute(
        "UPDATE erp_mkt_returns SET status = 'closed', notes = ?,"
        " updated_by = ?, updated_at = ? WHERE id = ?",
        (note, actor, now, return_id))
    _erp_staff_audit(conn, actor, "marketing.return_closed",
                     "return", return_id,
                     "closed %s order #%d: %s"
                     % (row["order_source"], row["order_id"], note[:120]))
    conn.commit()
    row = conn.execute("SELECT * FROM erp_mkt_returns WHERE id = ?",
                       (return_id,)).fetchone()
    out = _mkt_return_dict(conn, row)
    conn.close()
    return jsonify(ok=True, ret=out)


