    if e:
        return jsonify(error=e), 400
    mult, e = _loyalty_int_field(data, "earn_multiplier_x100", 100, 300, 100)
    if e:
        return jsonify(error=e), 400
    bonus, e = _loyalty_int_field(data, "birthday_bonus_kernels", 0, None, 0)
    if e:
        return jsonify(error=e), 400
    active, e = _loyalty_active_field(data)
    if e:
        return jsonify(error=e), 400
