    if conn.execute("SELECT id FROM erp_loyalty_tiers WHERE lower(name) = lower(?)",
                    (name,)).fetchone():
        conn.close()
        return jsonify(error="a tier with that name already exists"), 409
    if not _loyalty_tier_thresholds_ok(conn, None, min_kernels):
        conn.close()
        return jsonify(error="tier thresholds must be strictly increasing"), 400
    if not _loyalty_tier_has_base(conn, None, min_kernels):
        conn.close()
        return jsonify(error="at least one tier must start at 0 Kernels"), 400
    now = datetime.now(timezone.utc).isoformat()
    try:
        cur = conn.execute(
            "INSERT INTO erp_loyalty_tiers (name, min_lifetime_kernels,"
            " earn_multiplier_x100, birthday_bonus_kernels, active,"
            " created_by, created_at, updated_by, updated_at)"
            " VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)",
            (name, min_kernels, mult, bonus, active, actor, now, actor, now))
    except sqlite3.IntegrityError:
        conn.close()
        return jsonify(error="a tier with that name already exists"), 409
    tid = cur.lastrowid
    _erp_staff_audit(conn, actor, "loyalty.tier_created",
                     "loyalty_tier", tid, name)
    conn.commit()
    conn.close()
    return jsonify(ok=True, tier_id=tid), 201


