    mult = int(row["earn_multiplier_x100"])
    if "earn_multiplier_x100" in data:
        mult, e = _loyalty_int_field(data, "earn_multiplier_x100", 100, 300)
        if e:
            conn.close()
            return jsonify(error=e), 400
    bonus = int(row["birthday_bonus_kernels"])
