@app.post("/api/erp/hr/employees/<int:employee_id>/benefits")
def hr_create_benefit(employee_id):
    """Add a benefit record for an employee (201). Tracking only --
    this does not enroll anyone with a carrier. Since SOP 12.23 the
    row may link a benefit plan (optional plan_id) and the window it
    was enrolled through (optional window_id, needs a plan): the plan
    must be active, the window open, and the employee must pass the
    plan's eligibility rules -- the same checks as /enroll. A
    plan-less row stays possible (tracking outside a plan, as
    before)."""
    actor, err = _require_erp_admin()
    if err:
        return err
    data = request.get_json(force=True) or {}
    fields = _hr_benefit_fields(data)
    if isinstance(fields, tuple):
        return fields
    now = datetime.now(timezone.utc).isoformat()
    conn = db()
    employee = _hr_get_employee(conn, employee_id)
    if not employee:
        conn.close()
        return jsonify(error="employee not found"), 404
    link = _hr_benefit_plan_window_link(conn, employee, data)
    # An error is a (Response, status) pair; a valid link is a pair
    # of ids (either may be None), so the Response check -- not
    # isinstance(tuple) -- tells them apart.
    if isinstance(link, tuple) and hasattr(link[0], "status_code"):
        conn.close()
        return link
    plan_id, window_id = link
    cur = conn.execute(
        "INSERT INTO erp_hr_benefits (employee_id, benefit_type, carrier,"
        " status, monthly_cost_cents, notes, plan_id, window_id,"
        " created_by, created_at, updated_by, updated_at)"
        " VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
        (employee_id, fields["benefit_type"], fields["carrier"],
         fields["status"], fields["monthly_cost_cents"], fields["notes"],
         plan_id, window_id, actor, now, actor, now))
    _erp_staff_audit(conn, actor, "hr.benefit_created", "hr_benefit",
                     cur.lastrowid, "%s for employee #%d (%s)" % (
                         fields["benefit_type"], employee_id,
                         fields["status"]))
    conn.commit()
    row = conn.execute("SELECT * FROM erp_hr_benefits WHERE id = ?",
                       (cur.lastrowid,)).fetchone()
    out = _hr_benefit_dict(row, conn)
    conn.close()
    return jsonify(benefit=out), 201


