@app.post("/api/erp/hr/applicants/<int:applicant_id>/offers")
def hr_create_offer(applicant_id):
    """Create a draft offer (201). The applicant must be at stage
    interview or offer (400 otherwise). pay_cents is whole cents or
    blank (not stated); pay_basis hourly or salary; start_date
    YYYY-MM-DD or blank; terms are stored text, not a generated PDF."""
    actor, err = _require_erp_admin()
    if err:
        return err
    data = request.get_json(force=True) or {}
    conn = db()
    row = _hr_applicant_row(conn, applicant_id)
    if not row:
        conn.close()
        return jsonify(error="applicant not found"), 404
    if row["stage"] not in ("interview", "offer"):
        conn.close()
        return jsonify(error="offers can only be created for an applicant"
                       " at interview or offer stage (currently %s)"
                       % row["stage"]), 400
    requisition_id = data.get("requisition_id")
    if requisition_id not in (None, ""):
        try:
            requisition_id = int(requisition_id)
        except (TypeError, ValueError):
            conn.close()
            return jsonify(error="requisition not found"), 400
        if not _hr_requisition_row(conn, requisition_id):
            conn.close()
            return jsonify(error="requisition not found"), 400
    else:
        requisition_id = None
    pay_cents = _hr_parse_rate(data.get("pay_cents"))
    if pay_cents is False:
        conn.close()
        return jsonify(error="pay_cents must be a whole number of cents,"
                       " 0 or more"), 400
    pay_basis = (data.get("pay_basis") or "").strip()
    if pay_basis not in ("", "hourly", "salary"):
        conn.close()
        return jsonify(error="pay_basis must be hourly or salary"), 400
    start_date = (data.get("start_date") or "").strip()
    if start_date and not _hr_valid_hire_date(start_date):
        conn.close()
        return jsonify(error="start date must be YYYY-MM-DD"), 400
    terms = (data.get("terms") or "").strip()
    if len(terms) > 5000:
        conn.close()
        return jsonify(error="terms must be 5000 characters or fewer"), 400
    now = datetime.now(timezone.utc).isoformat()
    cur = conn.execute(
        "INSERT INTO erp_hr_offers (applicant_id, requisition_id,"
        " pay_cents, pay_basis, start_date, terms, status, sent_at,"
        " decided_at, created_by, created_at, updated_by, updated_at)"
        " VALUES (?, ?, ?, ?, ?, ?, 'draft', '', '', ?, ?, '', '')",
        (applicant_id, requisition_id, pay_cents, pay_basis, start_date,
         terms, actor, now))
    offer_id = cur.lastrowid
    _erp_staff_audit(conn, actor, "hr.offer_created", "hr_offer",
                     offer_id, "created draft offer for %s"
                     % (row["name"] or ""))
    conn.commit()
    payload = _hr_offer_payload(_hr_offer_row(conn, offer_id))
    conn.close()
    return jsonify(payload), 201


@app.post("/api/erp/hr/offers/<int:offer_id>/send")
def hr_send_offer(offer_id):
    """draft -> sent (sets sent_at; moves the applicant to offer
    stage). Refused (409) while another offer for the same applicant
    is already sent or accepted -- only one live offer at a time."""
    actor, err = _require_erp_admin()
    if err:
        return err
    conn = db()
    row = _hr_offer_row(conn, offer_id)
    if not row:
        conn.close()
        return jsonify(error="offer not found"), 404
    if row["status"] != "draft":
        conn.close()
        return jsonify(error="only a draft offer can be sent"
                       " (currently %s)" % row["status"]), 400
    applicant = _hr_applicant_row(conn, row["applicant_id"])
    if not applicant:
        conn.close()
        return jsonify(error="applicant not found"), 404
    if applicant["stage"] in ("hired", "rejected"):
        conn.close()
        return jsonify(error="cannot send an offer to a %s applicant"
                       % applicant["stage"]), 400
    live = conn.execute(
        "SELECT id FROM erp_hr_offers WHERE applicant_id = ?"
        " AND status IN ('sent', 'accepted') AND id != ?",
        (row["applicant_id"], offer_id)).fetchone()
    if live:
        conn.close()
        return jsonify(error="another offer for this applicant is already"
                       " sent or accepted"), 409
    now = datetime.now(timezone.utc).isoformat()
    conn.execute("UPDATE erp_hr_offers SET status = 'sent', sent_at = ?,"
                 " updated_by = ?, updated_at = ? WHERE id = ?",
                 (now, actor, now, offer_id))
    if applicant["stage"] != "offer":
        conn.execute("UPDATE erp_hr_applicants SET stage = 'offer',"
                     " updated_by = ?, updated_at = ? WHERE id = ?",
                     (actor, now, row["applicant_id"]))
    _erp_staff_audit(conn, actor, "hr.offer_sent", "hr_offer", offer_id,
                     "sent offer to %s (applicant moved to offer stage)"
                     % (applicant["name"] or ""))
    conn.commit()
    payload = _hr_offer_payload(_hr_offer_row(conn, offer_id))
    conn.close()
    return jsonify(payload)


@app.post("/api/erp/hr/offers/<int:offer_id>/decide")
def hr_decide_offer(offer_id):
    """sent -> accepted / declined (body decision). Sets decided_at.
    Accepting does NOT hire -- the Hire action still creates the
    employee; the applicant simply stays at offer stage."""
    actor, err = _require_erp_admin()
    if err:
        return err
    data = request.get_json(force=True) or {}
    decision = (data.get("decision") or "").strip()
    if decision not in ("accepted", "declined"):
        return jsonify(error="decision must be accepted or declined"), 400
    conn = db()
    row = _hr_offer_row(conn, offer_id)
    if not row:
        conn.close()
        return jsonify(error="offer not found"), 404
    if row["status"] != "sent":
        conn.close()
        return jsonify(error="only a sent offer can be decided"
                       " (currently %s)" % row["status"]), 400
    now = datetime.now(timezone.utc).isoformat()
    conn.execute("UPDATE erp_hr_offers SET status = ?, decided_at = ?,"
                 " updated_by = ?, updated_at = ? WHERE id = ?",
                 (decision, now, actor, now, offer_id))
    _erp_staff_audit(conn, actor, "hr.offer_decided", "hr_offer", offer_id,
                     "offer %s" % decision)
    conn.commit()
    payload = _hr_offer_payload(_hr_offer_row(conn, offer_id))
    conn.close()
    return jsonify(payload)


@app.post("/api/erp/hr/offers/<int:offer_id>/withdraw")
def hr_withdraw_offer(offer_id):
    """Withdraw an offer (draft or sent -> withdrawn). A decided offer
    cannot be withdrawn."""
    actor, err = _require_erp_admin()
    if err:
        return err
    conn = db()
    row = _hr_offer_row(conn, offer_id)
    if not row:
        conn.close()
        return jsonify(error="offer not found"), 404
    if row["status"] not in ("draft", "sent"):
        conn.close()
        return jsonify(error="only a draft or sent offer can be withdrawn"
                       " (currently %s)" % row["status"]), 400
    now = datetime.now(timezone.utc).isoformat()
    conn.execute("UPDATE erp_hr_offers SET status = 'withdrawn',"
                 " updated_by = ?, updated_at = ? WHERE id = ?",
                 (actor, now, offer_id))
    _erp_staff_audit(conn, actor, "hr.offer_withdrawn", "hr_offer",
                     offer_id, "offer withdrawn")
    conn.commit()
    payload = _hr_offer_payload(_hr_offer_row(conn, offer_id))
    conn.close()
    return jsonify(payload)


# Benefits administration (SOP 12.23, Nov 2026): benefit plans,
# eligibility rules, enrollment windows, plus recording an
# enrollment choice on the existing tracking register. All
# admin-only via _require_erp_admin(). No carrier integration:
# the ERP never talks to a carrier, never sends an enrollment
# file, never confirms coverage. Enrollment choices are records,
# not payments -- nothing here posts to the ledger.
HR_BENEFIT_PLAN_TYPES = ("health", "dental", "vision", "life",
                         "retirement", "other")
HR_BENEFIT_RULE_TYPES = ("scope", "role", "min_days_employed")
HR_ENROLLMENT_WINDOW_STATUSES = ("draft", "open", "closed")


def _hr_benefit_plan_row(conn, plan_id):
    try:
        plan_id = int(plan_id)
    except (TypeError, ValueError):
        return None
    return conn.execute("SELECT * FROM erp_hr_benefit_plans WHERE id = ?",
                        (plan_id,)).fetchone()


def _hr_benefit_window_row(conn, window_id):
    try:
        window_id = int(window_id)
    except (TypeError, ValueError):
        return None
    return conn.execute(
        "SELECT * FROM erp_hr_enrollment_windows WHERE id = ?",
        (window_id,)).fetchone()


def _hr_benefit_rule_row(conn, rule_id):
    try:
        rule_id = int(rule_id)
    except (TypeError, ValueError):
        return None
    return conn.execute(
        "SELECT * FROM erp_hr_benefit_eligibility WHERE id = ?",
        (rule_id,)).fetchone()


def _hr_benefit_rule_text(rule_type, rule_value):
    """Human-readable label for one eligibility rule -- the same
    wording the enrollment refusal names when the rule fails."""
    value = (rule_value or "").strip()
    if rule_type == "scope":
        return "Scope: %s" % ("Corporate" if value == "corporate"
                              else "Store" if value == "store" else value)
    if rule_type == "role":
        return "Role: %s" % value
    if rule_type == "min_days_employed":
        try:
            days = int(value)
        except (TypeError, ValueError):
            days = value
        return "Minimum %s day%s employed" % (
            days, "" if days == 1 else "s")
    return "%s: %s" % (rule_type, value)


def _hr_benefit_eligibility_payload(row):
    return {"id": row["id"], "plan_id": row["plan_id"],
            "rule_type": row["rule_type"],
            "rule_value": row["rule_value"] or "",
            "rule_text": _hr_benefit_rule_text(row["rule_type"],
                                              row["rule_value"] or ""),
            "created_by": row["created_by"] or "",
            "created_at": row["created_at"],
            "updated_by": row["updated_by"] or "",
            "updated_at": row["updated_at"] or ""}


def _hr_benefit_plan_payload(conn, row):
    rules = conn.execute(
        "SELECT * FROM erp_hr_benefit_eligibility WHERE plan_id = ?"
        " ORDER BY id", (row["id"],)).fetchall()
    count = conn.execute(
        "SELECT COUNT(*) FROM erp_hr_benefits WHERE plan_id = ?",
        (row["id"],)).fetchone()[0]
    return {"id": row["id"], "name": row["name"] or "",
            "benefit_type": row["benefit_type"] or "",
            "carrier": row["carrier"] or "",
            "description": row["description"] or "",
            "eligibility_text": row["eligibility_text"] or "",
            "employee_cost_cents": row["employee_cost_cents"],
            "employer_cost_cents": row["employer_cost_cents"],
            # monthly_cost_cents is the employee's monthly share,
            # under the name the plan brief uses.
            "monthly_cost_cents": row["employee_cost_cents"],
            "active": bool(row["active"]),
            "eligibility": [_hr_benefit_eligibility_payload(r)
                            for r in rules],
            "benefit_count": count,
            "created_by": row["created_by"] or "",
            "created_at": row["created_at"],
            "updated_by": row["updated_by"] or "",
            "updated_at": row["updated_at"] or ""}


def _hr_enrollment_window_payload(row):
    return {"id": row["id"], "name": row["name"] or "",
            "start_date": row["start_date"] or "",
            "end_date": row["end_date"] or "",
            # opens_at / closes_at are the same dates, under the
            # names the plan brief uses.
            "opens_at": row["start_date"] or "",
            "closes_at": row["end_date"] or "",
            "status": row["status"],
            "created_by": row["created_by"] or "",
            "created_at": row["created_at"],
            "updated_by": row["updated_by"] or "",
            "updated_at": row["updated_at"] or ""}


def _hr_benefit_plan_fields(data, conn, exclude_id=None, partial=False):
    """Validate plan fields. Returns the cleaned dict, or
    (error_response, status) on a bad value. On create every field
    is validated; on update (partial) only the keys present are
    validated and returned. monthly_cost_cents is accepted as an
    alias for the employee's monthly share."""
    out = {}
    if not partial or "name" in data:
        name = (data.get("name") or "").strip()
        if not name or len(name) > 100:
            return jsonify(error="name must be 1-100 characters"), 400
        dup = conn.execute(
            "SELECT id FROM erp_hr_benefit_plans"
            " WHERE lower(name) = lower(?)", (name,)).fetchone()
        if dup and dup["id"] != exclude_id:
            return jsonify(error="a benefit plan with this name"
                           " already exists"), 400
        out["name"] = name
    if not partial or "benefit_type" in data:
        btype = (data.get("benefit_type") or "").strip()
        if btype not in HR_BENEFIT_PLAN_TYPES:
            return jsonify(error="benefit_type must be one of: "
                           + ", ".join(HR_BENEFIT_PLAN_TYPES)), 400
        out["benefit_type"] = btype
    if not partial or "carrier" in data:
        carrier = (data.get("carrier") or "").strip()
        if not carrier or len(carrier) > 200:
            return jsonify(error="carrier is required, 200 characters"
                           " or fewer"), 400
        out["carrier"] = carrier
    if not partial or "description" in data:
        description = (data.get("description") or "").strip()
        if len(description) > 5000:
            return jsonify(error="description must be 5000 characters"
                           " or fewer"), 400
        out["description"] = description
    if not partial or "eligibility_text" in data:
        eligibility_text = (data.get("eligibility_text") or "").strip()
        if len(eligibility_text) > 5000:
            return jsonify(error="eligibility_text must be 5000"
                           " characters or fewer"), 400
        out["eligibility_text"] = eligibility_text
    if not partial or "employee_cost_cents" in data \
            or "monthly_cost_cents" in data:
        # monthly_cost_cents is the alias for the employee share.
        raw = data.get("monthly_cost_cents")
        if raw is None:
            raw = data.get("employee_cost_cents")
        cost = _hr_parse_rate(raw)
        if cost is False:
            return jsonify(error="employee cost must be a whole number"
                           " of cents, 0 or more"), 400
        out["employee_cost_cents"] = cost
    if not partial or "employer_cost_cents" in data:
        cost = _hr_parse_rate(data.get("employer_cost_cents"))
        if cost is False:
            return jsonify(error="employer cost must be a whole number"
                           " of cents, 0 or more"), 400
        out["employer_cost_cents"] = cost
    return out


def _hr_validate_benefit_rule(rule_type, rule_value):
    """Validate one eligibility rule. Returns (rule_type,
    rule_value, error-or-None)."""
    rule_type = (rule_type or "").strip()
    if rule_type not in HR_BENEFIT_RULE_TYPES:
        return None, None, "rule_type must be one of: " + ", ".join(
            HR_BENEFIT_RULE_TYPES)
    rule_value = (rule_value or "").strip() \
        if isinstance(rule_value, str) else rule_value
    if rule_type == "scope":
        if rule_value not in ("corporate", "store"):
            return None, None, "a scope rule's value must be" \
                " corporate or store"
        return rule_type, rule_value, None
    if rule_type == "role":
        if not isinstance(rule_value, str) or not rule_value \
                or len(rule_value) > 100:
            return None, None, "a role rule's value must be a role" \
                " title or id, 1-100 characters"
        return rule_type, rule_value, None
    # min_days_employed: a whole number of days, 0 or more, stored
    # in canonical integer spelling ("90", never "90.5" or "090").
    if isinstance(rule_value, bool):
        return None, None, "a min_days_employed rule's value must be" \
            " a whole number of days, 0 or more"
    try:
        days = int(rule_value)
    except (TypeError, ValueError):
        return None, None, "a min_days_employed rule's value must be" \
            " a whole number of days, 0 or more"
    if isinstance(rule_value, float) and not rule_value.is_integer():
        return None, None, "a min_days_employed rule's value must be" \
            " a whole number of days, 0 or more"
    if days < 0 or str(rule_value).strip() != str(days):
        return None, None, "a min_days_employed rule's value must be" \
            " a whole number of days, 0 or more"
    return rule_type, str(days), None


def _hr_window_overlap(conn, start_date, end_date, exclude_id=None):
    """Label of another window whose [start, end] intersects this
    one, or None. Same overlap rule as headcount periods: a window
    must close before a new one opens."""
    rows = conn.execute(
        "SELECT id, name, start_date, end_date"
        " FROM erp_hr_enrollment_windows").fetchall()
    for r in rows:
        if exclude_id is not None and r["id"] == exclude_id:
            continue
        if start_date <= (r["end_date"] or "") \
                and end_date >= (r["start_date"] or ""):
            return r["name"]
    return None


def _hr_validate_window_fields(conn, name, start_date, end_date,
                               exclude_id=None):
    """Validate a window's name/dates. Returns (name, start_date,
    end_date, error-or-None)."""
    name = (name or "").strip()
    if not name or len(name) > 100:
        return None, None, None, "name must be 1-100 characters"
    if not start_date or not _hr_valid_hire_date(start_date):
        return None, None, None, "start date must be YYYY-MM-DD"
    if not end_date or not _hr_valid_hire_date(end_date):
        return None, None, None, "end date must be YYYY-MM-DD"
    if start_date > end_date:
        return None, None, None, "start date must be on or before" \
            " end date"
    over = _hr_window_overlap(conn, start_date, end_date, exclude_id)
    if over:
        return None, None, None, "enrollment window overlaps %s" % over
    return name, start_date, end_date, None


def _hr_plan_eligibility_failures(conn, plan_id, employee):
    """Rule labels the employee FAILS for this plan (all rules must
    pass -- AND). Empty means eligible. Eligibility is evaluated
    live from the rules + hire date, never stored per employee."""
    rules = conn.execute(
        "SELECT * FROM erp_hr_benefit_eligibility WHERE plan_id = ?"
        " ORDER BY id", (plan_id,)).fetchall()
    failures = []
    today = datetime.now(timezone.utc).date()
    keys = employee.keys()
    for rule in rules:
        rtype = rule["rule_type"]
        rvalue = (rule["rule_value"] or "").strip()
        if rtype == "scope":
            scope = employee["scope_type"] \
                if "scope_type" in keys else None
            if scope != rvalue:
                failures.append(_hr_benefit_rule_text(rtype, rvalue))
        elif rtype == "role":
            role_id = employee["role_id"] if "role_id" in keys else None
            role_text = (employee["role"] or "").strip().lower()
            ok = False
            if rvalue.isdigit() and role_id is not None \
                    and int(rvalue) == role_id:
                ok = True
            if role_text and role_text == rvalue.lower():
                ok = True
            if not ok:
                failures.append(_hr_benefit_rule_text(rtype, rvalue))
        elif rtype == "min_days_employed":
            hire = (employee["hire_date"] or "").strip()
            ok = False
            try:
                hired = datetime.strptime(hire, "%Y-%m-%d").date()
                ok = (today - hired).days >= int(rvalue)
            except (ValueError, TypeError):
                ok = False
            if not ok:
                failures.append(_hr_benefit_rule_text(rtype, rvalue))
    return failures


def _hr_benefit_plan_window_link(conn, employee, data, require=False):
    """Validate an optional (or, when require=True, mandatory)
    plan_id + window_id pair from a benefit-row body. Returns
    (plan_id, window_id) -- either may be None when not required --
    or (error_response, status). The plan must be active, the
    window open, and the employee must pass the plan's eligibility
    rules (the refusal names the failed rule)."""
    plan_raw = data.get("plan_id")
    window_raw = data.get("window_id")
    if plan_raw in (None, ""):
        if require:
            return jsonify(error="plan_id is required"), 400
        if window_raw not in (None, ""):
            return jsonify(error="window_id requires plan_id"), 400
        return None, None
    plan = _hr_benefit_plan_row(conn, plan_raw)
    if not plan:
        return jsonify(error="plan not found"), 404
    if not plan["active"]:
        return jsonify(error="plan is not active"), 400
    if window_raw in (None, ""):
        if require:
            return jsonify(error="window_id is required"), 400
        window_id = None
    else:
        window = _hr_benefit_window_row(conn, window_raw)
        if not window:
            return jsonify(error="enrollment window not found"), 404
        if window["status"] != "open":
            return jsonify(error="enrollment window is not open"), 400
        window_id = window["id"]
    failures = _hr_plan_eligibility_failures(conn, plan["id"], employee)
    if failures:
        return jsonify(error="employee is not eligible for this plan:"
                       " " + "; ".join(failures)), 400
    return plan["id"], window_id


@app.get("/api/erp/hr/benefit-plans")
def hr_list_benefit_plans():
    """List benefit plans, active first. Starts empty -- nothing is
    seeded."""
    _, err = _require_erp_admin()
    if err:
        return err
    active = (request.args.get("active") or "").strip()
    conn = db()
    if active == "1":
        rows = conn.execute(
            "SELECT * FROM erp_hr_benefit_plans WHERE active = 1"
            " ORDER BY name, id").fetchall()
    elif active == "0":
        rows = conn.execute(
            "SELECT * FROM erp_hr_benefit_plans WHERE active = 0"
            " ORDER BY name, id").fetchall()
    else:
        rows = conn.execute(
            "SELECT * FROM erp_hr_benefit_plans"
            " ORDER BY active DESC, name, id").fetchall()
    out = [_hr_benefit_plan_payload(conn, r) for r in rows]
    conn.close()
    return jsonify(plans=out)


@app.post("/api/erp/hr/benefit-plans")
def hr_create_benefit_plan():
    """Create a benefit plan (201). A plan needs a carrier name --
    no plan without one. Costs are whole cents, 0 or more, or NULL
    (unset)."""
    actor, err = _require_erp_admin()
    if err:
        return err
    data = request.get_json(force=True) or {}
    conn = db()
    fields = _hr_benefit_plan_fields(data, conn)
    if isinstance(fields, tuple):
        conn.close()
        return fields
    now = datetime.now(timezone.utc).isoformat()
    cur = conn.execute(
        "INSERT INTO erp_hr_benefit_plans (name, benefit_type, carrier,"
        " description, eligibility_text, employee_cost_cents,"
        " employer_cost_cents, active, created_by, created_at,"
        " updated_by, updated_at)"
        " VALUES (?, ?, ?, ?, ?, ?, ?, 1, ?, ?, ?, ?)",
        (fields["name"], fields["benefit_type"], fields["carrier"],
         fields["description"], fields["eligibility_text"],
         fields["employee_cost_cents"], fields["employer_cost_cents"],
         actor, now, actor, now))
    _erp_staff_audit(conn, actor, "hr.benefit_plan_created",
                     "hr_benefit_plan", cur.lastrowid,
                     "%s (%s)" % (fields["name"], fields["benefit_type"]))
    conn.commit()
    row = _hr_benefit_plan_row(conn, cur.lastrowid)
    out = _hr_benefit_plan_payload(conn, row)
    conn.close()
    return jsonify(out), 201


