@app.post("/api/erp/hr/benefit-plans/<int:plan_id>/update")
def hr_update_benefit_plan(plan_id):
    """Edit a plan (omitted fields keep their value). Name, type,
    carrier, description, eligibility text, and costs can change;
    active never changes here -- use deactivate/activate."""
    actor, err = _require_erp_admin()
    if err:
        return err
    data = request.get_json(force=True) or {}
    conn = db()
    row = _hr_benefit_plan_row(conn, plan_id)
    if not row:
        conn.close()
        return jsonify(error="plan not found"), 404
    if "active" in data or "status" in data:
        conn.close()
        return jsonify(error="use deactivate/activate to change a"
                       " plan's status"), 400
    fields = _hr_benefit_plan_fields(data, conn, exclude_id=plan_id,
                                     partial=True)
    if isinstance(fields, tuple):
        conn.close()
        return fields
    if not fields:
        conn.close()
        return jsonify(_hr_benefit_plan_payload(conn, row))
    now = datetime.now(timezone.utc).isoformat()
    sets = ", ".join("%s = ?" % k for k in fields)
    params = list(fields.values()) + [actor, now, plan_id]
    conn.execute("UPDATE erp_hr_benefit_plans SET %s, updated_by = ?,"
                 " updated_at = ? WHERE id = ?" % sets, params)
    _erp_staff_audit(conn, actor, "hr.benefit_plan_updated",
                     "hr_benefit_plan", plan_id, "%s" % row["name"])
    conn.commit()
    out = _hr_benefit_plan_payload(conn, _hr_benefit_plan_row(conn,
                                                             plan_id))
    conn.close()
    return jsonify(out)


