@app.delete("/api/erp/hr/benefit-plans/<int:plan_id>")
def hr_delete_benefit_plan(plan_id):
    """Delete a plan permanently. Refused (409) while any benefit
    row references it, or while it still has eligibility rules --
    deletes never cascade silently."""
    actor, err = _require_erp_admin()
    if err:
        return err
    conn = db()
    row = _hr_benefit_plan_row(conn, plan_id)
    if not row:
        conn.close()
        return jsonify(error="plan not found"), 404
    n = conn.execute(
        "SELECT COUNT(*) FROM erp_hr_benefits WHERE plan_id = ?",
        (plan_id,)).fetchone()[0]
    if n:
        conn.close()
        return jsonify(error="cannot delete a plan with %d benefit"
                       " record(s) linked to it" % n), 409
    m = conn.execute(
        "SELECT COUNT(*) FROM erp_hr_benefit_eligibility"
        " WHERE plan_id = ?", (plan_id,)).fetchone()[0]
    if m:
        conn.close()
        return jsonify(error="cannot delete a plan with %d eligibility"
                       " rule(s) -- delete its rules first" % m), 409
    conn.execute("DELETE FROM erp_hr_benefit_plans WHERE id = ?",
                 (plan_id,))
    _erp_staff_audit(conn, actor, "hr.benefit_plan_deleted",
                     "hr_benefit_plan", plan_id, "%s" % row["name"])
    conn.commit()
    conn.close()
    return jsonify(ok=True)


