@app.post("/api/erp/hr/enrollment-windows/<int:window_id>/open")
def hr_open_enrollment_window(window_id):
    """Open a draft window (draft -> open). Refused while another
    window is already open -- a window must close before a new one
    opens."""
    actor, err = _require_erp_admin()
    if err:
        return err
    conn = db()
    row = _hr_benefit_window_row(conn, window_id)
    if not row:
        conn.close()
        return jsonify(error="enrollment window not found"), 404
    if row["status"] != "draft":
        conn.close()
        return jsonify(error="only a draft window can be opened"), 400
    other = conn.execute(
        "SELECT id FROM erp_hr_enrollment_windows"
        " WHERE status = 'open' AND id != ?",
        (window_id,)).fetchone()
    if other:
        conn.close()
        return jsonify(error="another enrollment window is already"
                       " open"), 400
    now = datetime.now(timezone.utc).isoformat()
    conn.execute("UPDATE erp_hr_enrollment_windows SET status = 'open',"
                 " updated_by = ?, updated_at = ? WHERE id = ?",
                 (actor, now, window_id))
    _erp_staff_audit(conn, actor, "hr.enrollment_window_opened",
                     "hr_enrollment_window", window_id,
                     "%s" % row["name"])
    conn.commit()
    out = _hr_enrollment_window_payload(_hr_benefit_window_row(
        conn, window_id))
    conn.close()
    return jsonify(out)


