# Learning paths + catalog (SOP 12.28, Nov 2026). Admin-only via
# _require_erp_admin(), like the rest of HR. Categories are the
# course catalog; a path is an ordered course sequence per role;
# steps are part of the path, so deleting a path deletes its steps
# (the one stated cascade in the HR design -- everything else is
# refused 409 while dependents exist). Progress is computed on
# read from completions, never stored: an expired completion never
# counts, and only required steps count toward done/total. Hosted
# e-learning content is NOT built -- content_url is a link out.
# All three tables start empty and are NOT in _ERP_RESET_TABLES.
def _learning_category_row(conn, category_id):
    try:
        category_id = int(category_id)
    except (TypeError, ValueError):
        return None
    return conn.execute(
        "SELECT * FROM erp_hr_training_categories WHERE id = ?",
        (category_id,)).fetchone()


def _learning_category_dict(row):
    return {"id": row["id"], "name": row["name"],
            "active": bool(row["active"]),
            "created_by": row["created_by"] or "",
            "created_at": row["created_at"],
            "updated_by": row["updated_by"] or "",
            "updated_at": row["updated_at"] or ""}


def _learning_path_row(conn, path_id):
    try:
        path_id = int(path_id)
    except (TypeError, ValueError):
        return None
    return conn.execute(
        "SELECT * FROM erp_hr_learning_paths WHERE id = ?",
        (path_id,)).fetchone()


def _learning_step_row(conn, step_id):
    try:
        step_id = int(step_id)
    except (TypeError, ValueError):
        return None
    return conn.execute(
        "SELECT * FROM erp_hr_learning_path_steps WHERE id = ?",
        (step_id,)).fetchone()


def _learning_path_steps(conn, path_id):
    """Ordered steps for a path, each with its course title."""
    rows = conn.execute(
        "SELECT s.*, c.title AS course_title, c.active AS course_active,"
        " l.title AS lesson_title, l.active AS lesson_active"
        " FROM erp_hr_learning_path_steps s"
        " LEFT JOIN erp_hr_training_courses c ON c.id = s.course_id"
        " LEFT JOIN erp_hr_lessons l ON l.id = s.lesson_id"
        " WHERE s.path_id = ? ORDER BY s.step_order, s.id",
        (path_id,)).fetchall()
    return [{
        "id": r["id"], "path_id": r["path_id"],
        "course_id": r["course_id"],
        "course_title": r["course_title"] or "",
        "course_active": bool(r["course_active"])
        if r["course_active"] is not None else False,
        "lesson_id": (r["lesson_id"] if "lesson_id" in r.keys() else None),
        "lesson_title": r["lesson_title"] or "",
        "lesson_active": bool(r["lesson_active"])
        if r["lesson_active"] is not None else False,
        "step_order": r["step_order"],
        "required": bool(r["required"]),
    } for r in rows]


def _learning_path_payload(conn, row, with_steps=True):
    role_title = ""
    if row["role_id"]:
        role = _hr_role_row(conn, row["role_id"])
        role_title = role["title"] if role else ""
    step_count = conn.execute(
        "SELECT COUNT(*) FROM erp_hr_learning_path_steps WHERE path_id = ?",
        (row["id"],)).fetchone()[0]
    payload = {
        "id": row["id"], "role_id": row["role_id"],
        "role_title": role_title,
        "title": row["title"], "description": row["description"] or "",
        "active": bool(row["active"]), "step_count": int(step_count),
        "created_by": row["created_by"] or "",
        "created_at": row["created_at"],
        "updated_by": row["updated_by"] or "",
        "updated_at": row["updated_at"] or "",
    }
    if with_steps:
        payload["steps"] = _learning_path_steps(conn, row["id"])
    return payload


def _learning_step_state(conn, employee_id, course_id, today):
    """done / expired / not_started for one employee + course:
    any unexpired completion counts; completions that all expired
    read as expired (re-take); none at all is not started."""
    rows = conn.execute(
        "SELECT expiry_date FROM erp_hr_training_completions"
        " WHERE employee_id = ? AND course_id = ?",
        (employee_id, course_id)).fetchall()
    if not rows:
        return "not_started"
    for r in rows:
        expiry = r["expiry_date"] or ""
        if not expiry or expiry >= today:
            return "done"
    return "expired"


def _learning_path_progress(conn, path_row, employee_id):
    """Computed progress for one employee on one path: required
    steps done/total, plus the per-step completion state. Nothing
    is written here -- progress is arithmetic on completions."""
    today = _training_today().isoformat()
    steps = _learning_path_steps(conn, path_row["id"])
    required = [s for s in steps if s["required"]]
    done = 0
    out_steps = []
    for s in steps:
        state = _learning_step_state(conn, employee_id,
                                     s["course_id"], today)
        if s["required"] and state == "done":
            done += 1
        s = dict(s)
        s["state"] = state
        out_steps.append(s)
    role_title = ""
    if path_row["role_id"]:
        role = _hr_role_row(conn, path_row["role_id"])
        role_title = role["title"] if role else ""
    return {
        "path_id": path_row["id"], "title": path_row["title"],
        "role_id": path_row["role_id"], "role_title": role_title,
        "required_done": done, "required_total": len(required),
        "total_steps": len(steps),
        "complete": bool(required) and done == len(required),
        "steps": out_steps,
    }


