@app.post("/api/erp/hr/learning-paths")
def hr_learning_path_create():
    """Add a learning path. Title is required; role_id is optional
    and, when given, must be an active job role."""
    actor, err = _require_erp_admin()
    if err:
        return err
    data = request.get_json(force=True) or {}
    conn = db()
    title = (data.get("title") or "").strip()
    if not title:
        conn.close()
        return jsonify(error="title is required"), 400
    if len(title) > 200:
        conn.close()
        return jsonify(error="title must be 200 characters or fewer"), 400
    description = (data.get("description") or "").strip()
    if len(description) > 5000:
        conn.close()
        return jsonify(error="description must be 5000 characters or fewer"), 400
    role_id = None
    if data.get("role_id") not in (None, ""):
        role = _hr_role_row(conn, data.get("role_id"))
        if not role:
            conn.close()
            return jsonify(error="role not found"), 400
        if not role["active"]:
            conn.close()
            return jsonify(error="role is inactive"), 400
        role_id = role["id"]
    now = datetime.now(timezone.utc).isoformat()
    cur = conn.execute(
        "INSERT INTO erp_hr_learning_paths (role_id, title,"
        " description, active, created_by, created_at, updated_by,"
        " updated_at) VALUES (?, ?, ?, 1, ?, ?, ?, ?)",
        (role_id, title, description, actor, now, actor, now))
    row = _learning_path_row(conn, cur.lastrowid)
    out = _learning_path_payload(conn, row)
    _erp_staff_audit(conn, actor, "hr.learning_path_created",
                     "hr_learning_path", row["id"],
                     "created learning path %s" % title)
    conn.commit()
    conn.close()
    return jsonify(path=out), 201


