@app.post("/api/erp/hr/learning-path-steps/<int:step_id>/update")
def hr_learning_path_step_update(step_id):
    """Change a step's order and/or required flag."""
    actor, err = _require_erp_admin()
    if err:
        return err
    data = request.get_json(force=True) or {}
    conn = db()
    row = _learning_step_row(conn, step_id)
    if not row:
        conn.close()
        return jsonify(error="step not found"), 404
    sets, args, changes = [], [], []
    if "step_order" in data:
        try:
            step_order = int(data.get("step_order"))
        except (TypeError, ValueError):
            conn.close()
            return jsonify(error="step_order must be a whole number"), 400
        if step_order != row["step_order"]:
            sets.append("step_order = ?")
            args.append(step_order)
            changes.append("step_order updated")
    if "required" in data:
        required = 1 if data.get("required") else 0
        if required != (1 if row["required"] else 0):
            sets.append("required = ?")
            args.append(required)
            changes.append("required updated")
    if "lesson_id" in data:
        if data.get("lesson_id") in (None, ""):
            new_lesson = None
        else:
            try:
                new_lesson = int(data.get("lesson_id"))
            except (TypeError, ValueError):
                conn.close()
                return jsonify(error="lesson_id must be a lesson id"), 400
            lesson = conn.execute(
                "SELECT * FROM erp_hr_lessons WHERE id = ?",
                (new_lesson,)).fetchone()
            if not lesson:
                conn.close()
                return jsonify(error="lesson not found"), 404
            if not lesson["active"]:
                conn.close()
                return jsonify(error="lesson is inactive"), 400
        old_lesson = row["lesson_id"] if "lesson_id" in row.keys() else None
        if new_lesson != old_lesson:
            sets.append("lesson_id = ?")
            args.append(new_lesson)
            changes.append("lesson updated")
    if sets:
        args.append(step_id)
        conn.execute("UPDATE erp_hr_learning_path_steps SET %s"
                     " WHERE id = ?" % ", ".join(sets), args)
        _erp_staff_audit(conn, actor, "hr.learning_path_step_updated",
                         "hr_learning_path", row["path_id"],
                         "step #%d: %s" % (step_id, "; ".join(changes)))
        conn.commit()
    out = _learning_path_steps(conn, row["path_id"])
    step = [s for s in out if s["id"] == step_id][0]
    conn.close()
    return jsonify(step=step)


