    conn = db()
    row = _hr_get_goal(conn, goal_id)
    if not row:
        conn.close()
        return jsonify(error="goal not found"), 404
    conn.execute("DELETE FROM erp_hr_goals WHERE id = ?", (goal_id,))
    _erp_staff_audit(conn, actor, "hr.goal_deleted", "hr_goal",
                     goal_id, "deleted goal %r" % (row["title"] or ""))
    conn.commit()
    conn.close()
    return jsonify(ok=True)


