@app.delete("/api/erp/hr/review-cycles/<int:cycle_id>")
def hr_delete_review_cycle(cycle_id):
    """Delete a review cycle, permanently. Refused (409) while any
    review belongs to the cycle -- reviews are the cycle's own
    records -- and refused while any compensation review belongs to
    it (SOP 12.29: a decided comp row can never be deleted, so a
    cycle with a decided comp row cannot be deleted either). Goals
    are NOT deleted with it: they detach (review_cycle_id set NULL)
    and keep showing with a detached badge, so no goal is ever lost
    by deleting a cycle."""
    actor, err = _require_erp_admin()
    if err:
        return err
    conn = db()
    row = _hr_get_review_cycle(conn, cycle_id)
    if not row:
        conn.close()
        return jsonify(error="review cycle not found"), 404
    rcount = conn.execute(
        "SELECT COUNT(*) FROM erp_hr_reviews WHERE cycle_id = ?",
        (cycle_id,)).fetchone()[0]
    if rcount:
        conn.close()
        return jsonify(error="cannot delete a review cycle with %d"
                       " review(s) -- delete the reviews first"
                       % rcount), 409
    ccount = conn.execute(
        "SELECT COUNT(*) FROM erp_hr_comp_reviews WHERE cycle_id = ?",
        (cycle_id,)).fetchone()[0]
    if ccount:
        conn.close()
        return jsonify(error="cannot delete a review cycle with %d"
                       " compensation review(s) -- delete the"
                       " compensation reviews first"
                       % ccount), 409
    gcount = conn.execute(
        "SELECT COUNT(*) FROM erp_hr_goals"
        " WHERE review_cycle_id = ?", (cycle_id,)).fetchone()[0]
    conn.execute("UPDATE erp_hr_goals SET review_cycle_id = NULL,"
                 " updated_by = ?, updated_at = ?"
                 " WHERE review_cycle_id = ?",
                 (actor, datetime.now(timezone.utc).isoformat(),
                  cycle_id))
    conn.execute("DELETE FROM erp_hr_review_cycles WHERE id = ?",
                 (cycle_id,))
    _erp_staff_audit(conn, actor, "hr.review_cycle_deleted",
                     "hr_review_cycle", cycle_id,
                     "deleted review cycle %r; %d goal(s) detached"
                     % (row["name"], gcount))
    conn.commit()
    conn.close()
    return jsonify(ok=True, detached_goals=gcount)


# Compensation review cycles (SOP 12.29, Nov 2026). Admin-only via
# _require_erp_admin(). One comp row per (review cycle, employee):
# the admin-entered current pay and proposed pay for that cycle, a
# pay basis (hourly | salary), a note, and a decision. Pay figures
# are admin-entered only -- this module never reads
# erp_acct_employees and never writes any payroll table: an approved
# change is applied by hand in the payroll employee record
# afterwards, and the row is then marked applied. A row with no
# decision stays pending. Bonus plans live in their own tables
# (SOP 12.32) and equity is NOT built.
# Staff self-service sees nothing of comp reviews -- not even their
# own row: there is no /me entry and no per-employee read for a
# non-admin. Deleting a review cycle is refused (409) while any
# comp row belongs to it -- a decided row can never be deleted, so
# a cycle with a decided comp row cannot be deleted either.
HR_COMP_DECISIONS = ("pending", "approved", "declined", "applied")
HR_COMP_PAY_BASES = ("hourly", "salary")


def _hr_get_comp_review(conn, comp_id):
    try:
        comp_id = int(comp_id)
    except (TypeError, ValueError):
        return None
    return conn.execute("SELECT * FROM erp_hr_comp_reviews WHERE id = ?",
                        (comp_id,)).fetchone()


def _hr_comp_review_payload(conn, row):
    cycle = _hr_get_review_cycle(conn, row["cycle_id"])
    emp = _hr_get_employee(conn, row["employee_id"])
    return {
        "id": row["id"], "cycle_id": row["cycle_id"],
        "cycle_name": (cycle["name"] if cycle else ""),
        "employee_id": row["employee_id"],
        "employee_name": (emp["name"] if emp else ""),
        "current_pay_cents": row["current_pay_cents"],
        "proposed_pay_cents": row["proposed_pay_cents"],
        "pay_basis": row["pay_basis"] or "",
        "decision": row["decision"],
        "decided_by": row["decided_by"] or "",
        "decided_at": row["decided_at"] or "",
        "note": row["note"] or "",
        "notes": row["note"] or "",
        "created_by": row["created_by"] or "",
        "created_at": row["created_at"],
        "updated_by": row["updated_by"] or "",
        "updated_at": row["updated_at"] or "",
    }


def _hr_parse_pay_cents(value):
    """A pay figure in whole cents: an int >= 0, or None for unset.
    Returns the int, None, or False when the value is not a whole
    number of cents. Booleans and floats are rejected -- cents are
    integers, and a dollar figure must be converted by the caller."""
    if value is None or value == "":
        return None
    if isinstance(value, bool):
        return False
    if isinstance(value, int):
        return value if value >= 0 else False
    if isinstance(value, str):
        text = value.strip()
        if not text:
            return None
        try:
            parsed = int(text)
        except (TypeError, ValueError):
            return False
        return parsed if parsed >= 0 else False
    return False


def _hr_comp_review_fields(data, conn, partial=False):
    """Validate comp-review fields. Returns (values, error). On
    create (partial=False) cycle_id and employee_id are required
    and the employee must have a review in the cycle; pay figures
    are admin-entered whole cents (>= 0) or NULL. The "notes" key
    is accepted as an alias for "note"."""
    values = {}
    if not partial or "cycle_id" in data:
        try:
            cycle_id = int(data.get("cycle_id"))
        except (TypeError, ValueError):
            return None, "cycle_id is required"
        cycle = _hr_get_review_cycle(conn, cycle_id)
        if not cycle:
            return None, "review cycle not found"
        values["cycle_id"] = cycle["id"]
    if not partial or "employee_id" in data:
        try:
            employee_id = int(data.get("employee_id"))
        except (TypeError, ValueError):
            return None, "employee_id is required"
        emp = _hr_get_employee(conn, employee_id)
        if not emp:
            return None, "employee not found"
        values["employee_id"] = emp["id"]
    if "current_pay_cents" in data:
        current = _hr_parse_pay_cents(data.get("current_pay_cents"))
        if current is False:
            return None, ("current_pay_cents must be whole cents"
                         " (>= 0) or blank")
        values["current_pay_cents"] = current
    if "proposed_pay_cents" in data:
        proposed = _hr_parse_pay_cents(data.get("proposed_pay_cents"))
        if proposed is False:
            return None, ("proposed_pay_cents must be whole cents"
                         " (>= 0) or blank")
        values["proposed_pay_cents"] = proposed
    if "pay_basis" in data:
        basis = (data.get("pay_basis") or "").strip()
        if basis and basis not in HR_COMP_PAY_BASES:
            return None, "pay_basis must be hourly or salary"
        values["pay_basis"] = basis
    if "note" in data or "notes" in data:
        note = (data.get("note") if "note" in data
                else data.get("notes")) or ""
        note = note.strip()
        if len(note) > 5000:
            return None, "note must be 5000 characters or fewer"
        values["note"] = note
    return values, None


def _hr_create_comp_review(conn, actor, data, cycle_id=None):
    """Shared create path for POST /api/erp/hr/comp-reviews and
    POST /api/erp/hr/review-cycles/<id>/comp. Returns (payload,
    status) or (error_response, status). The employee must have a
    review in the cycle (400 otherwise); one row per (cycle,
    employee) (409 on a second one). Pay is admin-entered only --
    nothing is read from payroll here."""
    data = dict(data)
    if cycle_id is not None:
        data["cycle_id"] = cycle_id
    fields, error = _hr_comp_review_fields(data, conn)
    if error:
        status = 404 if error in ("review cycle not found",
                                   "employee not found") else 400
        return jsonify(error=error), status
    review = conn.execute(
        "SELECT id FROM erp_hr_reviews WHERE cycle_id = ?"
        " AND employee_id = ?",
        (fields["cycle_id"], fields["employee_id"])).fetchone()
    if not review:
        return jsonify(error="this employee has no review in this"
                       " review cycle -- add the review first"), 400
    dup = conn.execute(
        "SELECT id FROM erp_hr_comp_reviews WHERE cycle_id = ?"
        " AND employee_id = ?",
        (fields["cycle_id"], fields["employee_id"])).fetchone()
    if dup:
        return jsonify(error="this employee already has a"
                       " compensation review in this cycle"), 409
    now = datetime.now(timezone.utc).isoformat()
    cur = conn.execute(
        "INSERT INTO erp_hr_comp_reviews (cycle_id, employee_id,"
        " current_pay_cents, proposed_pay_cents, pay_basis,"
        " decision, decided_by, decided_at, note, created_by,"
        " created_at, updated_by, updated_at)"
        " VALUES (?, ?, ?, ?, ?, 'pending', '', '', ?, ?, ?, ?, ?)",
        (fields["cycle_id"], fields["employee_id"],
         fields.get("current_pay_cents"),
         fields.get("proposed_pay_cents"),
         fields.get("pay_basis", ""), fields.get("note", ""),
         actor, now, actor, now))
    comp_id = cur.lastrowid
    _erp_staff_audit(conn, actor, "hr.comp_review_created",
                     "hr_comp_review", comp_id,
                     "compensation review for employee #%d in cycle #%d"
                     % (fields["employee_id"], fields["cycle_id"]))
    conn.commit()
    row = _hr_get_comp_review(conn, comp_id)
    return jsonify(_hr_comp_review_payload(conn, row)), 201


@app.get("/api/erp/hr/comp-reviews")
def hr_list_comp_reviews():
    """Admin list: every compensation review, optionally filtered
    by cycle_id, employee_id and/or decision. Pending first, then
    approved, declined, applied; within a decision by id."""
    _, err = _require_erp_admin()
    if err:
        return err
    conn = db()
    query = "SELECT * FROM erp_hr_comp_reviews WHERE 1 = 1"
    params = []
    for key, col in (("cycle_id", "cycle_id"),
                     ("employee_id", "employee_id"),
                     ("decision", "decision")):
        value = request.args.get(key)
        if value:
            query += " AND %s = ?" % col
            params.append(value)
    query += (" ORDER BY CASE decision WHEN 'pending' THEN 0"
              " WHEN 'approved' THEN 1 WHEN 'declined' THEN 2"
              " WHEN 'applied' THEN 3 ELSE 4 END, id")
    rows = conn.execute(query, params).fetchall()
    out = [_hr_comp_review_payload(conn, r) for r in rows]
    conn.close()
    return jsonify(comp_reviews=out)


@app.post("/api/erp/hr/comp-reviews")
def hr_create_comp_review():
    """Create a compensation review (201). cycle_id + employee_id
    are required; the employee must have a review in the cycle.
    Pay figures are admin-entered whole cents (or blank)."""
    actor, err = _require_erp_admin()
    if err:
        return err
    data = request.get_json(force=True) or {}
    conn = db()
    payload, status = _hr_create_comp_review(conn, actor, data)
    conn.close()
    return payload, status


