@app.post("/api/erp/hr/bonus-plans")
def hr_create_bonus_plan():
    """Create a bonus plan (201). Title is required; basis defaults
    to fixed when omitted. The register starts empty -- nothing is
    seeded."""
    actor, err = _require_erp_admin()
    if err:
        return err
    data = request.get_json(force=True) or {}
    conn = db()
    fields, error = _hr_bonus_plan_fields(data)
    if error:
        conn.close()
        return jsonify(error=error), 400
    now = datetime.now(timezone.utc).isoformat()
    cur = conn.execute(
        "INSERT INTO erp_hr_bonus_plans (title, description, basis,"
        " eligibility, active, created_by, created_at, updated_by,"
        " updated_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)",
        (fields["title"], fields.get("description", ""),
         fields.get("basis", "fixed"), fields.get("eligibility", ""),
         fields.get("active", 1), actor, now, actor, now))
    plan_id = cur.lastrowid
    _erp_staff_audit(conn, actor, "hr.bonus_plan_created",
                     "hr_bonus_plan", plan_id,
                     "bonus plan %r created" % fields["title"])
    conn.commit()
    out = _hr_bonus_plan_payload(conn, _hr_get_bonus_plan(conn, plan_id))
    conn.close()
    return jsonify(out), 201


