@app.post("/api/erp/hr/bonus-plans/<int:plan_id>/update")
def hr_update_bonus_plan(plan_id):
    """Edit a bonus plan (title, description, basis, eligibility,
    active flag). Editing a plan never touches its payouts."""
    actor, err = _require_erp_admin()
    if err:
        return err
    data = request.get_json(force=True) or {}
    conn = db()
    row = _hr_get_bonus_plan(conn, plan_id)
