@app.get("/api/erp/hr/bonus-payouts")
def hr_list_bonus_payouts():
    """Admin list: every bonus payout, optionally filtered by
    plan_id, employee_id and/or status. Planned first, then
    approved, then paid; within a status by id."""
    _, err = _require_erp_admin()
    if err:
        return err
    conn = db()
    query = "SELECT * FROM erp_hr_bonus_payouts WHERE 1 = 1"
    params = []
    for key, col in (("plan_id", "plan_id"),
                     ("employee_id", "employee_id"),
                     ("status", "status")):
        value = request.args.get(key)
        if value:
            query += " AND %s = ?" % col
            params.append(value)
    query += (" ORDER BY CASE status WHEN 'planned' THEN 0"
              " WHEN 'approved' THEN 1 WHEN 'paid' THEN 2"
              " ELSE 3 END, id")
    rows = conn.execute(query, params).fetchall()
    out = [_hr_bonus_payout_payload(conn, r) for r in rows]
    conn.close()
    return jsonify(bonus_payouts=out)


@app.post("/api/erp/hr/bonus-payouts")
def hr_create_bonus_payout():
    """Record a bonus payout (201). plan_id + employee_id +
    amount_cents + period are required; one payout per (plan,
    employee, period) (409 on a second one). The amount is
    admin-entered whole cents and is never computed from any
    salary. Recording a payout on an inactive plan is refused --
    reactivate the plan first."""
    actor, err = _require_erp_admin()
    if err:
        return err
    data = request.get_json(force=True) or {}
    conn = db()
    fields, error = _hr_bonus_payout_fields(data, conn)
    if error:
        status = 404 if error in ("bonus plan not found",
                                  "employee not found") else 400
        conn.close()
        return jsonify(error=error), status
    plan = _hr_get_bonus_plan(conn, fields["plan_id"])
    if not plan["active"]:
        conn.close()
        return jsonify(error="this bonus plan is inactive --"
                       " reactivate the plan before recording"
                       " a payout"), 400
    dup = conn.execute(
        "SELECT id FROM erp_hr_bonus_payouts WHERE plan_id = ?"
        " AND employee_id = ? AND period = ?",
        (fields["plan_id"], fields["employee_id"],
         fields["period"])).fetchone()
    if dup:
        conn.close()
        return jsonify(error="this employee already has a payout"
                       " under this plan for this period"), 409
    now = datetime.now(timezone.utc).isoformat()
    cur = conn.execute(
        "INSERT INTO erp_hr_bonus_payouts (plan_id, employee_id,"
        " amount_cents, period, status, note, decided_by,"
        " decided_at, created_by, created_at, updated_by,"
        " updated_at) VALUES (?, ?, ?, ?, 'planned', ?, '', '',"
        " ?, ?, ?, ?)",
        (fields["plan_id"], fields["employee_id"],
         fields["amount_cents"], fields["period"],
         fields.get("note", ""), actor, now, actor, now))
    payout_id = cur.lastrowid
    _erp_staff_audit(conn, actor, "hr.bonus_payout_created",
                     "hr_bonus_payout", payout_id,
                     "bonus payout for employee #%d under plan #%d"
                     " (%s)" % (fields["employee_id"],
                                fields["plan_id"], fields["period"]))
    conn.commit()
    out = _hr_bonus_payout_payload(
        conn, _hr_get_bonus_payout(conn, payout_id))
    conn.close()
    return jsonify(out), 201


