@app.post("/api/erp/hr/bonus-payouts/<int:payout_id>/update")
def hr_update_bonus_payout(payout_id):
    """Edit a bonus payout (amount, period, note). Allowed while
    planned or approved -- once paid the row is history and no
    longer changes. The status never changes here -- use /approve
    or /mark-paid. The plan and employee never change here."""
    actor, err = _require_erp_admin()
    if err:
        return err
    data = request.get_json(force=True) or {}
    conn = db()
    row = _hr_get_bonus_payout(conn, payout_id)
    if not row:
        conn.close()
        return jsonify(error="bonus payout not found"), 404
    if "status" in data:
        conn.close()
        return jsonify(error="use /approve or /mark-paid to change"
                       " a bonus payout's status"), 400
    if row["status"] == "paid":
        conn.close()
        return jsonify(error="a paid bonus payout can no longer"
                       " be edited"), 400
    fields, error = _hr_bonus_payout_fields(data, conn, partial=True)
    if error:
        conn.close()
        return jsonify(error=error), 400
    fields.pop("plan_id", None)
    fields.pop("employee_id", None)
    if not fields:
        conn.close()
        return jsonify(_hr_bonus_payout_payload(conn, row))
    if "period" in fields:
        dup = conn.execute(
            "SELECT id FROM erp_hr_bonus_payouts WHERE plan_id = ?"
            " AND employee_id = ? AND period = ? AND id != ?",
            (row["plan_id"], row["employee_id"], fields["period"],
             payout_id)).fetchone()
        if dup:
            conn.close()
            return jsonify(error="this employee already has a payout"
                           " under this plan for this period"), 409
    now = datetime.now(timezone.utc).isoformat()
    sets = ", ".join("%s = ?" % k for k in fields)
    params = list(fields.values()) + [actor, now, payout_id]
    conn.execute("UPDATE erp_hr_bonus_payouts SET %s, updated_by = ?,"
                 " updated_at = ? WHERE id = ?" % sets, params)
    _erp_staff_audit(conn, actor, "hr.bonus_payout_updated",
                     "hr_bonus_payout", payout_id,
                     "bonus payout #%d updated" % payout_id)
    conn.commit()
    out = _hr_bonus_payout_payload(
        conn, _hr_get_bonus_payout(conn, payout_id))
    conn.close()
    return jsonify(out)


@app.post("/api/erp/hr/bonus-payouts/<int:payout_id>/approve")
def hr_approve_bonus_payout(payout_id):
    """Approve a planned payout: planned -> approved. The approver
    and time are stored on the row. Approving never moves money --
    the payout is still only a recorded decision."""
    actor, err = _require_erp_admin()
    if err:
        return err
    conn = db()
    row = _hr_get_bonus_payout(conn, payout_id)
    if not row:
        conn.close()
        return jsonify(error="bonus payout not found"), 404
    if row["status"] != "planned":
        conn.close()
        return jsonify(error="only a planned bonus payout can be"
                       " approved (it is %s)" % row["status"]), 400
    now = datetime.now(timezone.utc).isoformat()
    conn.execute("UPDATE erp_hr_bonus_payouts SET status = 'approved',"
                 " decided_by = ?, decided_at = ?, updated_by = ?,"
                 " updated_at = ? WHERE id = ?",
                 (actor, now, actor, now, payout_id))
    _erp_staff_audit(conn, actor, "hr.bonus_payout_approved",
                     "hr_bonus_payout", payout_id,
                     "bonus payout #%d approved" % payout_id)
    conn.commit()
    out = _hr_bonus_payout_payload(
        conn, _hr_get_bonus_payout(conn, payout_id))
    conn.close()
    return jsonify(out)


@app.post("/api/erp/hr/bonus-payouts/<int:payout_id>/mark-paid")
def hr_mark_paid_bonus_payout(payout_id):
    """Mark an approved payout paid: approved -> paid. The admin
    confirms the money was paid outside the ERP (payroll actuals
    are out of this ERP) -- this endpoint itself never moves money
    and never writes payroll. A paid payout is history: it can
    never be edited or deleted afterwards."""
    actor, err = _require_erp_admin()
    if err:
        return err
    conn = db()
    row = _hr_get_bonus_payout(conn, payout_id)
    if not row:
        conn.close()
        return jsonify(error="bonus payout not found"), 404
    if row["status"] != "approved":
        conn.close()
        return jsonify(error="only an approved bonus payout can be"
                       " marked paid (it is %s)" % row["status"]), 400
    now = datetime.now(timezone.utc).isoformat()
    conn.execute("UPDATE erp_hr_bonus_payouts SET status = 'paid',"
                 " updated_by = ?, updated_at = ? WHERE id = ?",
                 (actor, now, payout_id))
    _erp_staff_audit(conn, actor, "hr.bonus_payout_paid",
                     "hr_bonus_payout", payout_id,
                     "bonus payout #%d marked paid -- money paid"
                     " outside the ERP" % payout_id)
    conn.commit()
    out = _hr_bonus_payout_payload(
        conn, _hr_get_bonus_payout(conn, payout_id))
    conn.close()
    return jsonify(out)


@app.delete("/api/erp/hr/bonus-payouts/<int:payout_id>")
def hr_delete_bonus_payout(payout_id):
    """Delete a bonus payout, permanently -- only while planned or
    approved. A paid payout is history and delete is refused (409).
    Two-tap confirm on the frontend; no window.confirm."""
    actor, err = _require_erp_admin()
    if err:
        return err
    conn = db()
    row = _hr_get_bonus_payout(conn, payout_id)
    if not row:
        conn.close()
        return jsonify(error="bonus payout not found"), 404
    if row["status"] == "paid":
        conn.close()
        return jsonify(error="cannot delete a paid bonus payout --"
                       " paid payouts are history"), 409
    conn.execute("DELETE FROM erp_hr_bonus_payouts WHERE id = ?",
                 (payout_id,))
    _erp_staff_audit(conn, actor, "hr.bonus_payout_deleted",
                     "hr_bonus_payout", payout_id,
                     "deleted bonus payout #%d" % payout_id)
    conn.commit()
    conn.close()
    return jsonify(ok=True)


# Pay grades / salary bands (SOP 12.35, Nov 2026). Admin-only via
# _require_erp_admin() for every read and write -- staff see nothing
# of pay grades, not even in My HR (/me carries no pay-grade data).
# A grade is one admin-entered pay range (min / mid / max, whole
# cents, USD) for one defined job role, with an admin-recorded pay
# basis (salary / hourly) and an active flag. One ACTIVE grade per
# role: creating or activating a second active grade for the same
# role is refused (409); inactive grades are history and may exist
# alongside the active one. The range never writes payroll and never
# computes anyone's pay -- it is a consistency band the admin
# compares pay against by hand (SOP 12.29 compensation reviews hold
# the per-person figures). Deleting a grade is permanent, two-tap in
# the UI, and deletes only the grade. Deleting a job role is refused
# (409) while any grade references it (see hr_delete_role).
HR_PAY_GRADE_BASES = ("salary", "hourly")


def _hr_get_pay_grade(conn, grade_id):
    try:
        grade_id = int(grade_id)
    except (TypeError, ValueError):
        return None
    return conn.execute("SELECT * FROM erp_hr_pay_grades WHERE id = ?",
                        (grade_id,)).fetchone()


def _hr_pay_grade_payload(conn, row):
    role = _hr_role_row(conn, row["role_id"])
    return {
        "id": row["id"], "role_id": row["role_id"],
        "role_title": (role["title"] if role else ""),
        "role_active": bool(role["active"]) if role else False,
        "grade": row["grade"],
        "min_cents": row["min_cents"],
        "mid_cents": row["mid_cents"],
        "max_cents": row["max_cents"],
        "pay_basis": row["pay_basis"],
        "note": row["note"] or "",
        "active": bool(row["active"]),
        "created_by": row["created_by"] or "",
        "created_at": row["created_at"],
        "updated_by": row["updated_by"] or "",
        "updated_at": row["updated_at"] or "",
    }


def _hr_pay_grade_fields(data, conn, partial=False):
    """Validate pay-grade fields. Returns (values, error). On create
    (partial=False) role_id, grade, min/mid/max and pay_basis are
    required; on update only provided fields change. Amounts are
    whole cents (>= 0) -- dollars are converted by the caller. The
    min <= mid <= max ordering and the one-active-grade-per-role
    rule are checked by the caller against the merged row, not
    here."""
    values = {}
    if not partial or "role_id" in data:
        try:
            role_id = int(data.get("role_id"))
        except (TypeError, ValueError):
            return None, "role_id is required"
        role = _hr_role_row(conn, role_id)
        if not role:
            return None, "role not found"
        values["role_id"] = role["id"]
    if not partial or "grade" in data:
        grade = (data.get("grade") or "").strip()
        if not grade:
            return None, "grade is required"
        if len(grade) > 100:
            return None, "grade must be 100 characters or fewer"
        values["grade"] = grade
    for key in ("min_cents", "mid_cents", "max_cents"):
        if key in data:
            amount = _hr_parse_pay_cents(data.get(key))
            if amount is False or amount is None:
                return None, ("%s must be whole cents (>= 0)"
                              % key)
            values[key] = amount
        elif not partial:
            return None, "%s is required" % key
    if "pay_basis" in data:
        basis = (data.get("pay_basis") or "").strip()
        if basis not in HR_PAY_GRADE_BASES:
            return None, "pay_basis must be salary or hourly"
        values["pay_basis"] = basis
    elif not partial:
        return None, "pay_basis is required"
    if "note" in data:
        note = (data.get("note") or "").strip()
        if len(note) > 5000:
            return None, "note must be 5000 characters or fewer"
        values["note"] = note
    if "active" in data:
        active = data.get("active")
        if isinstance(active, bool):
            values["active"] = 1 if active else 0
        elif active in (0, 1, "0", "1"):
            values["active"] = int(active)
        else:
            return None, "active must be true or false"
    return values, None


def _hr_pay_grade_active_conflict(conn, role_id, exclude_id=None):
    """True when another ACTIVE grade already exists for the role."""
    row = conn.execute(
        "SELECT id FROM erp_hr_pay_grades WHERE role_id = ?"
        " AND active = 1 AND id != ?",
        (role_id, exclude_id if exclude_id is not None else -1)
        ).fetchone()
    return row is not None


@app.get("/api/erp/hr/pay-grades")
def hr_list_pay_grades():
    """Admin list: every pay grade, ordered by role title then id,
    with the role title on each row. ?role_id= narrows to one role;
    ?active=1 / 0 lists active / inactive only."""
    _, err = _require_erp_admin()
    if err:
        return err
    conn = db()
    query = ("SELECT g.* FROM erp_hr_pay_grades g"
             " LEFT JOIN erp_hr_roles r ON r.id = g.role_id"
             " WHERE 1 = 1")
    params = []
    role_id = (request.args.get("role_id") or "").strip()
    if role_id:
        try:
            params.append(int(role_id))
        except (TypeError, ValueError):
            conn.close()
            return jsonify(error="role_id must be a number"), 400
        query += " AND g.role_id = ?"
    active = (request.args.get("active") or "").strip()
    if active == "1":
        query += " AND g.active = 1"
    elif active == "0":
        query += " AND g.active = 0"
    elif active:
        conn.close()
        return jsonify(error="active must be 0 or 1"), 400
    query += " ORDER BY lower(r.title), g.id"
    rows = conn.execute(query, params).fetchall()
    out = [_hr_pay_grade_payload(conn, r) for r in rows]
    conn.close()
    return jsonify(pay_grades=out)


@app.post("/api/erp/hr/pay-grades")
def hr_create_pay_grade():
    """Create a pay grade (201). role_id, grade, min/mid/max
    (whole cents, >= 0) and pay_basis are required; the range must
    run min <= mid <= max. A second ACTIVE grade for the same role
    is refused (409) -- deactivate the existing grade first. The
    register starts empty -- nothing is seeded."""
    actor, err = _require_erp_admin()
    if err:
        return err
    data = request.get_json(force=True) or {}
    conn = db()
    fields, error = _hr_pay_grade_fields(data, conn)
    if error:
        status = 404 if error == "role not found" else 400
        conn.close()
        return jsonify(error=error), status
    if not (fields["min_cents"] <= fields["mid_cents"]
            <= fields["max_cents"]):
        conn.close()
        return jsonify(error="pay range must run"
                       " min <= mid <= max"), 400
    if fields.get("active", 1) and _hr_pay_grade_active_conflict(
            conn, fields["role_id"]):
        conn.close()
        return jsonify(error="this role already has an active pay"
                       " grade -- deactivate the existing grade"
                       " first"), 409
    now = datetime.now(timezone.utc).isoformat()
    cur = conn.execute(
        "INSERT INTO erp_hr_pay_grades (role_id, grade, min_cents,"
        " mid_cents, max_cents, pay_basis, note, active, created_by,"
        " created_at, updated_by, updated_at)"
        " VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
        (fields["role_id"], fields["grade"], fields["min_cents"],
         fields["mid_cents"], fields["max_cents"],
         fields["pay_basis"], fields.get("note", ""),
         fields.get("active", 1), actor, now, actor, now))
    grade_id = cur.lastrowid
    _erp_staff_audit(conn, actor, "hr.pay_grade_created",
                     "hr_pay_grade", grade_id,
                     "pay grade %r created for role #%d"
                     % (fields["grade"], fields["role_id"]))
    conn.commit()
    out = _hr_pay_grade_payload(conn, _hr_get_pay_grade(conn, grade_id))
    conn.close()
    return jsonify(out), 201


@app.get("/api/erp/hr/pay-grades/<int:grade_id>")
def hr_get_pay_grade_route(grade_id):
    """One pay grade."""
    _, err = _require_erp_admin()
    if err:
        return err
    conn = db()
    row = _hr_get_pay_grade(conn, grade_id)
    if not row:
        conn.close()
        return jsonify(error="pay grade not found"), 404
    out = _hr_pay_grade_payload(conn, row)
    conn.close()
    return jsonify(out)


@app.post("/api/erp/hr/pay-grades/<int:grade_id>/update")
def hr_update_pay_grade(grade_id):
    """Edit a pay grade (grade label, role, min/mid/max, pay basis,
    note, active flag). Only provided fields change, but the merged
    range is always re-checked (min <= mid <= max) and the merged
    row must not leave two active grades on one role (409)."""
    actor, err = _require_erp_admin()
    if err:
        return err
    data = request.get_json(force=True) or {}
    conn = db()
    row = _hr_get_pay_grade(conn, grade_id)
    if not row:
        conn.close()
        return jsonify(error="pay grade not found"), 404
    fields, error = _hr_pay_grade_fields(data, conn, partial=True)
    if error:
        status = 404 if error == "role not found" else 400
        conn.close()
        return jsonify(error=error), status
    merged = dict(row)
    merged.update(fields)
    if not (merged["min_cents"] <= merged["mid_cents"]
            <= merged["max_cents"]):
        conn.close()
        return jsonify(error="pay range must run"
                       " min <= mid <= max"), 400
    if merged["active"] and _hr_pay_grade_active_conflict(
            conn, merged["role_id"], exclude_id=grade_id):
        conn.close()
        return jsonify(error="this role already has an active pay"
                       " grade -- deactivate the existing grade"
                       " first"), 409
    if not fields:
        conn.close()
        return jsonify(_hr_pay_grade_payload(conn, row))
    now = datetime.now(timezone.utc).isoformat()
    sets = ", ".join("%s = ?" % k for k in fields)
    params = list(fields.values()) + [actor, now, grade_id]
    conn.execute("UPDATE erp_hr_pay_grades SET %s, updated_by = ?,"
                 " updated_at = ? WHERE id = ?" % sets, params)
    _erp_staff_audit(conn, actor, "hr.pay_grade_updated",
                     "hr_pay_grade", grade_id,
                     "pay grade #%d updated" % grade_id)
    conn.commit()
    out = _hr_pay_grade_payload(conn, _hr_get_pay_grade(conn, grade_id))
    conn.close()
    return jsonify(out)


@app.delete("/api/erp/hr/pay-grades/<int:grade_id>")
def hr_delete_pay_grade(grade_id):
    """Delete a pay grade, permanently -- the grade is gone
    everywhere; there is no restore. Two-tap confirm on the
    frontend; no window.confirm. A grade references nothing else,
    so no guard applies here -- the guard runs the other way: a job
    role cannot be deleted while any grade references it."""
    actor, err = _require_erp_admin()
    if err:
        return err
    conn = db()
    row = _hr_get_pay_grade(conn, grade_id)
    if not row:
        conn.close()
        return jsonify(error="pay grade not found"), 404
    conn.execute("DELETE FROM erp_hr_pay_grades WHERE id = ?",
                 (grade_id,))
    _erp_staff_audit(conn, actor, "hr.pay_grade_deleted",
                     "hr_pay_grade", grade_id,
                     "deleted pay grade %r" % row["grade"])
    conn.commit()
    conn.close()
    return jsonify(ok=True)


@app.get("/api/erp/hr/roles/<int:role_id>/pay-grades")
def hr_list_role_pay_grades(role_id):
    """List pay grades for one job role, active first, then by id."""
    _, err = _require_erp_admin()
    if err:
        return err
    conn = db()
    if not _hr_role_row(conn, role_id):
        conn.close()
        return jsonify(error="role not found"), 404
    rows = conn.execute(
        "SELECT * FROM erp_hr_pay_grades WHERE role_id = ?"
        " ORDER BY active DESC, id",
        (role_id,)).fetchall()
    out = [_hr_pay_grade_payload(conn, r) for r in rows]
    conn.close()
    return jsonify(pay_grades=out)


# E-learning lessons + quizzes (SOP 12.33, Nov 2026). Admin-only
# via _require_erp_admin() for every write and every admin read,
# except the one staff path: submitting a quiz attempt, which any
# ERP caller may do but ONLY for themself -- the review-acknowledge
# ownership pattern (_require_erp() + _hr_resolve_caller_employee):
# the caller must resolve to the employee named on the attempt, so
# an admin (or another employee) can never take a quiz on someone
# else's behalf, and nobody's answers are ever visible to anyone
# but the admin and the employee themself (via /me, which carries
# quizzes WITHOUT correct answers and only the caller's own
# attempts). A lesson is linked media only: content_url is a link
# out (vendor course, shared-drive video, PDF -- validated by the
# same helper as a course's content link, SOP 12.28). There is no
# file upload, no BLOB, no video storage, no SCORM. A quiz's score
# is COMPUTED from the submitted answers against the stored
# correct options -- the score is never typed in -- and passed is
# computed from the quiz's passing score. Taking a quiz never
# auto-marks anyone trained: completions are still recorded by
# hand by the admin (SOP 12.21). Attempts are history: there is
# no attempt delete, and deleting a quiz is refused (409) while
# any attempt exists. Deleting a quiz deletes its questions with
# it (they have no life outside the quiz -- the one stated
# cascade here). Deleting a lesson is refused (409) while any
# quiz or any learning-path step references it.
HR_ELEARNING_CONTENT_TYPES = ("video", "document", "link")


def _hr_get_lesson(conn, lesson_id):
    try:
        lesson_id = int(lesson_id)
    except (TypeError, ValueError):
        return None
    return conn.execute("SELECT * FROM erp_hr_lessons WHERE id = ?",
                        (lesson_id,)).fetchone()


def _hr_get_quiz(conn, quiz_id):
    try:
        quiz_id = int(quiz_id)
    except (TypeError, ValueError):
        return None
    return conn.execute("SELECT * FROM erp_hr_quizzes WHERE id = ?",
                        (quiz_id,)).fetchone()


def _hr_get_quiz_question(conn, question_id):
    try:
        question_id = int(question_id)
    except (TypeError, ValueError):
        return None
    return conn.execute(
        "SELECT * FROM erp_hr_quiz_questions WHERE id = ?",
        (question_id,)).fetchone()


def _hr_get_quiz_attempt(conn, attempt_id):
    try:
        attempt_id = int(attempt_id)
    except (TypeError, ValueError):
        return None
    return conn.execute(
        "SELECT * FROM erp_hr_quiz_attempts WHERE id = ?",
        (attempt_id,)).fetchone()


def _hr_lesson_payload(conn, row):
    course_title = ""
    if row["course_id"]:
        course = _training_course_row(conn, row["course_id"])
        course_title = course["title"] if course else ""
    path_title = ""
    if row["learning_path_id"]:
        path = _learning_path_row(conn, row["learning_path_id"])
        path_title = path["title"] if path else ""
    quiz_count = conn.execute(
        "SELECT COUNT(*) FROM erp_hr_quizzes WHERE lesson_id = ?",
        (row["id"],)).fetchone()[0]
    return {
        "id": row["id"], "title": row["title"],
        "description": row["description"] or "",
        "content_url": row["content_url"] or "",
        "content_type": row["content_type"] or "link",
        "duration_minutes": row["duration_minutes"],
        "course_id": row["course_id"],
        "course_title": course_title,
        "learning_path_id": row["learning_path_id"],
        "learning_path_title": path_title,
        "active": bool(row["active"]),
        "quiz_count": int(quiz_count),
        "created_by": row["created_by"] or "",
        "created_at": row["created_at"],
        "updated_by": row["updated_by"] or "",
        "updated_at": row["updated_at"] or "",
    }


def _hr_quiz_question_payload(row, include_answer=True):
    try:
        options = json.loads(row["options"] or "[]")
    except (TypeError, ValueError):
        options = []
    if not isinstance(options, list):
        options = []
    payload = {
        "id": row["id"], "quiz_id": row["quiz_id"],
        "question": row["question"],
        "options": [str(o) for o in options],
        "question_order": row["question_order"],
    }
    if include_answer:
        payload["correct_option"] = row["correct_option"]
    return payload


def _hr_quiz_questions(conn, quiz_id, include_answer=True):
    rows = conn.execute(
        "SELECT * FROM erp_hr_quiz_questions WHERE quiz_id = ?"
        " ORDER BY question_order, id",
        (quiz_id,)).fetchall()
    return [_hr_quiz_question_payload(r, include_answer) for r in rows]


def _hr_quiz_payload(conn, row, include_questions=False,
                     include_answers=True):
    lesson_title = ""
    if row["lesson_id"]:
        lesson = _hr_get_lesson(conn, row["lesson_id"])
        lesson_title = lesson["title"] if lesson else ""
    course_title = ""
    if row["course_id"]:
        course = _training_course_row(conn, row["course_id"])
        course_title = course["title"] if course else ""
    count = conn.execute(
        "SELECT COUNT(*) FROM erp_hr_quiz_questions WHERE quiz_id = ?",
        (row["id"],)).fetchone()[0]
    payload = {
        "id": row["id"], "lesson_id": row["lesson_id"],
        "lesson_title": lesson_title,
        "course_id": row["course_id"],
        "course_title": course_title,
        "title": row["title"],
        "passing_score_percent": row["passing_score_percent"],
        "active": bool(row["active"]),
        "question_count": int(count),
        "created_by": row["created_by"] or "",
        "created_at": row["created_at"],
        "updated_by": row["updated_by"] or "",
        "updated_at": row["updated_at"] or "",
    }
    if include_questions:
        payload["questions"] = _hr_quiz_questions(
            conn, row["id"], include_answers)
    return payload


def _hr_quiz_attempt_payload(conn, row):
    quiz = _hr_get_quiz(conn, row["quiz_id"])
    emp = _hr_get_employee(conn, row["employee_id"])
    try:
        answers = json.loads(row["answers"] or "[]")
    except (TypeError, ValueError):
        answers = []
    if not isinstance(answers, list):
        answers = []
    return {
        "id": row["id"], "quiz_id": row["quiz_id"],
        "quiz_title": (quiz["title"] if quiz else ""),
        "employee_id": row["employee_id"],
        "employee_name": (emp["name"] if emp else ""),
        "employee_active": bool(emp["active"]) if emp else False,
        "score_percent": row["score_percent"],
        "passed": bool(row["passed"]),
        "taken_at": row["taken_at"],
        "answers": answers,
        "created_by": row["created_by"] or "",
        "created_at": row["created_at"],
        "updated_by": row["updated_by"] or "",
        "updated_at": row["updated_at"] or "",
    }


def _hr_lesson_fields(data, conn, partial=False):
    """Validate lesson fields. Returns (values, error). On create
    (partial=False) the title is required; content_type must be one
    of the fixed set; content_url is blank or an http(s) link (the
    course content-link helper); duration is whole minutes 0-10080
    or blank (unknown); course_id / learning_path_id, when given,
    must name an existing course / learning path."""
    values = {}
    if not partial or "title" in data:
        title = (data.get("title") or "").strip()
        if not title:
            return None, "title is required"
        if len(title) > 200:
            return None, "title must be 200 characters or fewer"
        values["title"] = title
    if "description" in data:
        description = (data.get("description") or "").strip()
        if len(description) > 5000:
            return None, "description must be 5000 characters or fewer"
        values["description"] = description
    if "content_url" in data:
        url, error = _training_validate_content_url(data)
        if error:
            return None, error
        values["content_url"] = url
    if "content_type" in data:
        content_type = (data.get("content_type") or "").strip()
        if content_type not in HR_ELEARNING_CONTENT_TYPES:
            return None, ("content_type must be one of: video,"
                          " document, link")
        values["content_type"] = content_type
    if "duration_minutes" in data:
        raw = data.get("duration_minutes")
        if raw in (None, ""):
            values["duration_minutes"] = None
        else:
            if isinstance(raw, bool):
                return None, "duration_minutes must be whole minutes"
            try:
                minutes = int(raw)
            except (TypeError, ValueError):
                return None, "duration_minutes must be whole minutes"
            if minutes < 0 or minutes > 10080:
                return None, ("duration_minutes must be between 0 and"
                              " 10080 minutes")
            values["duration_minutes"] = minutes
    if "course_id" in data:
        raw = data.get("course_id")
        if raw in (None, ""):
            values["course_id"] = None
        else:
            try:
                course_id = int(raw)
            except (TypeError, ValueError):
                return None, "course_id must be a course id"
            if not _training_course_row(conn, course_id):
                return None, "course not found"
            values["course_id"] = course_id
    if "learning_path_id" in data:
        raw = data.get("learning_path_id")
        if raw in (None, ""):
            values["learning_path_id"] = None
        else:
            try:
                path_id = int(raw)
            except (TypeError, ValueError):
                return None, "learning_path_id must be a learning path id"
            if not _learning_path_row(conn, path_id):
                return None, "learning path not found"
            values["learning_path_id"] = path_id
    if "active" in data:
        active = data.get("active")
        if isinstance(active, bool):
            values["active"] = 1 if active else 0
        elif active in (0, 1, "0", "1"):
            values["active"] = int(active)
        else:
            return None, "active must be true or false"
    return values, None


def _hr_quiz_fields(data, conn, partial=False, base=None):
    """Validate quiz fields. Returns (values, error). A quiz must
    link to a lesson or a course (at least one -- a quiz with
    neither has nothing to test); each link, when given, must exist
    and be active. passing_score_percent is a whole percent 0-100
    (default 70). On update, `base` is the existing row, so
    unlinking the last remaining link is refused."""
    values = {}
    merged_lesson = base["lesson_id"] if base else None
    merged_course = base["course_id"] if base else None
    if "lesson_id" in data:
        raw = data.get("lesson_id")
        if raw in (None, ""):
            values["lesson_id"] = None
            merged_lesson = None
        else:
            try:
                lesson_id = int(raw)
            except (TypeError, ValueError):
                return None, "lesson_id must be a lesson id"
            lesson = _hr_get_lesson(conn, lesson_id)
            if not lesson:
                return None, "lesson not found"
            if not lesson["active"]:
                return None, "lesson is inactive"
            values["lesson_id"] = lesson_id
            merged_lesson = lesson_id
    if "course_id" in data:
        raw = data.get("course_id")
        if raw in (None, ""):
            values["course_id"] = None
            merged_course = None
        else:
            try:
                course_id = int(raw)
            except (TypeError, ValueError):
                return None, "course_id must be a course id"
            course = _training_course_row(conn, course_id)
            if not course:
                return None, "course not found"
            if not course["active"]:
                return None, "course is inactive"
            values["course_id"] = course_id
            merged_course = course_id
    if not partial or "lesson_id" in data or "course_id" in data:
        if not merged_lesson and not merged_course:
            return None, ("a quiz must link to a lesson or a course"
                          " -- pick at least one")
    if not partial or "title" in data:
        title = (data.get("title") or "").strip()
        if not title:
            return None, "title is required"
        if len(title) > 200:
            return None, "title must be 200 characters or fewer"
        values["title"] = title
    if "passing_score_percent" in data:
        raw = data.get("passing_score_percent")
        if isinstance(raw, bool):
            return None, "passing_score_percent must be a whole percent"
        try:
            score = int(raw)
        except (TypeError, ValueError):
            return None, "passing_score_percent must be a whole percent"
        if score < 0 or score > 100:
            return None, ("passing_score_percent must be between 0 and"
                          " 100")
        values["passing_score_percent"] = score
    if "active" in data:
        active = data.get("active")
        if isinstance(active, bool):
            values["active"] = 1 if active else 0
        elif active in (0, 1, "0", "1"):
            values["active"] = int(active)
        else:
            return None, "active must be true or false"
    return values, None


def _hr_quiz_question_fields(data, partial=False, base=None):
    """Validate a quiz question. Options are a list of 2-8
    non-empty strings (each 500 chars or fewer); correct_option is
    the 0-based index of the right one. On update, `base` is the
    existing row, so a partial edit is checked against the merged
    options / correct option."""
    merged_options = None
    merged_correct = None
    if base is not None:
        try:
            merged_options = json.loads(base["options"] or "[]")
        except (TypeError, ValueError):
            merged_options = []
        merged_correct = base["correct_option"]
    if not partial:
        if "options" not in data:
            return None, "options are required"
        if "correct_option" not in data:
            return None, "correct_option is required"
    values = {}
    if not partial or "question" in data:
        question = (data.get("question") or "").strip()
        if not question:
            return None, "question is required"
        if len(question) > 2000:
            return None, "question must be 2000 characters or fewer"
        values["question"] = question
    if "options" in data:
        options = data.get("options")
        if not isinstance(options, list):
            return None, "options must be a list of answer choices"
        cleaned = []
        for opt in options:
            if not isinstance(opt, str):
                return None, "options must be a list of answer choices"
            text = opt.strip()
            if not text:
                return None, "options must not contain a blank choice"
            if len(text) > 500:
                return None, ("each option must be 500 characters or"
                              " fewer")
            cleaned.append(text)
        if len(cleaned) < 2 or len(cleaned) > 8:
            return None, "a question needs 2 to 8 options"
        values["options"] = json.dumps(cleaned)
        merged_options = cleaned
    if "correct_option" in data:
        raw = data.get("correct_option")
        if isinstance(raw, bool):
            return None, "correct_option must be an option index"
        try:
            correct = int(raw)
        except (TypeError, ValueError):
            return None, "correct_option must be an option index"
        values["correct_option"] = correct
        merged_correct = correct
    if "question_order" in data:
        raw = data.get("question_order")
        if isinstance(raw, bool):
            return None, "question_order must be a whole number"
        try:
            order = int(raw)
        except (TypeError, ValueError):
            return None, "question_order must be a whole number"
        values["question_order"] = order
    if merged_options is not None and merged_correct is not None:
        if merged_correct < 0 or merged_correct >= len(merged_options):
            return None, ("correct_option must be the index of one of"
                          " the options")
    return values, None


@app.get("/api/erp/hr/lessons")
def hr_list_lessons():
    """Admin list: every lesson, active first, then by id, with its
    linked course / learning path titles and quiz count. Optional
    filters: ?course_id=, ?learning_path_id=, ?active=0/1."""
    _, err = _require_erp_admin()
    if err:
        return err
    conn = db()
    query = "SELECT * FROM erp_hr_lessons WHERE 1 = 1"
    params = []
    for key, col in (("course_id", "course_id"),
                     ("learning_path_id", "learning_path_id")):
        value = request.args.get(key)
        if value not in (None, ""):
            query += " AND %s = ?" % col
            params.append(value)
    active = request.args.get("active")
    if active in ("0", "1"):
        query += " AND active = ?"
        params.append(int(active))
    query += " ORDER BY active DESC, id"
    rows = conn.execute(query, params).fetchall()
    out = [_hr_lesson_payload(conn, r) for r in rows]
    conn.close()
    return jsonify(lessons=out)


@app.post("/api/erp/hr/lessons")
def hr_create_lesson():
    """Create a lesson (201). Title is required; content_type
    defaults to link when omitted; content_url is blank or an
    http(s) link out -- never a file, never hosted video. The
    register starts empty -- nothing is seeded."""
    actor, err = _require_erp_admin()
    if err:
        return err
    data = request.get_json(force=True) or {}
    conn = db()
    fields, error = _hr_lesson_fields(data, conn)
    if error:
        conn.close()
        status = 404 if error in ("course not found",
                                  "learning path not found") else 400
        return jsonify(error=error), status
    now = datetime.now(timezone.utc).isoformat()
    cur = conn.execute(
        "INSERT INTO erp_hr_lessons (title, description, content_url,"
        " content_type, duration_minutes, course_id,"
        " learning_path_id, active, created_by, created_at,"
        " updated_by, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?,"
        " ?, ?, ?)",
        (fields["title"], fields.get("description", ""),
         fields.get("content_url", ""),
         fields.get("content_type", "link"),
         fields.get("duration_minutes"),
         fields.get("course_id"), fields.get("learning_path_id"),
         fields.get("active", 1), actor, now, actor, now))
    lesson_id = cur.lastrowid
    _erp_staff_audit(conn, actor, "hr.lesson_created",
                     "hr_lesson", lesson_id,
                     "lesson %r created" % fields["title"])
    conn.commit()
    out = _hr_lesson_payload(conn, _hr_get_lesson(conn, lesson_id))
    conn.close()
    return jsonify(out), 201


