@app.post("/api/erp/hr/lessons/<int:lesson_id>/update")
def hr_update_lesson(lesson_id):
    """Edit a lesson (title, description, content link / type,
    duration, linked course / learning path, active flag). Editing
    a lesson never touches its quizzes."""
    actor, err = _require_erp_admin()
    if err:
        return err
    data = request.get_json(force=True) or {}
    conn = db()
    row = _hr_get_lesson(conn, lesson_id)
    if not row:
        conn.close()
        return jsonify(error="lesson not found"), 404
    fields, error = _hr_lesson_fields(data, conn, partial=True)
    if error:
        conn.close()
        status = 404 if error in ("course not found",
                                  "learning path not found") else 400
        return jsonify(error=error), status
    if not fields:
        conn.close()
        return jsonify(_hr_lesson_payload(conn, row))
    now = datetime.now(timezone.utc).isoformat()
    sets = ", ".join("%s = ?" % k for k in fields)
    params = list(fields.values()) + [actor, now, lesson_id]
    conn.execute("UPDATE erp_hr_lessons SET %s, updated_by = ?,"
                 " updated_at = ? WHERE id = ?" % sets, params)
