@app.post("/api/erp/hr/projects/tasks/<int:task_id>/status")
def hr_project_task_set_status(task_id):
    """Move one task to a new status. An admin may move any task;
    a staff member may move only a task they own (their employee
    row) -- anyone else gets 403, never another person's task. The
    status is always picked by hand, never derived. Moving a task
    in a complete or cancelled project is refused -- reopen the
    project first."""
    actor, err = _require_erp()
    if err:
        return err
    data = request.get_json(force=True) or {}
    status = (data.get("status") or "").strip().lower()
    if status not in HR_PROJECT_TASK_STATUSES:
        return jsonify(error="status must be to do, in progress,"
                       " done, or cancelled"), 400
    conn = db()
    row = _hr_project_task_get(conn, task_id)
    if not row:
        conn.close()
        return jsonify(error="task not found"), 404
    user = _current_member()
    is_admin = bool(user and _is_admin(user))
    if not is_admin:
        mine = _hr_resolve_caller_employee(conn)
        if not mine or row["owner_employee_id"] != mine["id"]:
            conn.close()
            return jsonify(error="only the task owner can change"
                           " its status"), 403
    project = _hr_project_get(conn, row["project_id"])
    if project and project["status"] in ("complete", "cancelled"):
        conn.close()
        return jsonify(error="project is %s; reopen it before"
                       " changing tasks" % project["status"]), 400
    now = datetime.now(timezone.utc).isoformat()
    conn.execute(
        "UPDATE erp_hr_project_tasks SET status = ?,"
        " updated_by = ?, updated_at = ? WHERE id = ?",
        (status, actor, now, task_id))
    _erp_staff_audit(conn, actor, "hr.project_task_status_changed",
                     "hr_project_task", task_id,
                     "task #%d status -> %s" % (task_id, status))
    conn.commit()
    out = _hr_project_task_payload(
        conn, _hr_project_task_get(conn, task_id), project)
    conn.close()
    return jsonify(out)


@app.get("/api/erp/hr/projects/mine")
def hr_my_projects():
    """The caller's own project work: their tasks (across projects,
    each with its project name) and the projects they own (each with
    all its tasks). A task in someone else's project shows only
    that task -- never the rest of that project. A caller with no
    HR record linked and no admin login gets 404, never another
    employee's work."""
    actor, err = _require_erp()
    if err:
        return err
    conn = db()
    mine = _hr_resolve_caller_employee(conn)
    admin_email = ""
    user = _current_member()
    if user and _is_admin(user):
        admin_email = user["email"] or ""
    if not mine and not admin_email:
        conn.close()
        return jsonify(error="no HR record is linked to your login;"
                       " ask an admin to link one"), 404
    my_tasks, my_projects = _hr_my_projects_data(
        conn, mine["id"] if mine else None, admin_email)
    conn.close()
    return jsonify(my_tasks=my_tasks, my_projects=my_projects)


# HR Additions 1: PTO / time-off tracking. Admin-only via
# _require_erp_admin(), like the rest of HR. Request types are an
# admin-configurable list (erp_hr_pto_types), seeded on first use with
# vacation / sick / personal and no balances anywhere: every balance
# starts at 0 and only an admin grant moves it -- accrual exists only
# as an admin-triggered run (SOP 12.25, M6): there is NO automatic
# accrual rate and nothing accrues on a timer. Days are decimal days as
# REAL: a request's days are the inclusive calendar days from
# start_date to end_date (2026-12-09..2026-12-11 is 3 days); the REAL
# type leaves room for half-days later. Balance is computed live as
# granted - approved days, never stored, so it cannot drift.
# Flow: draft -> pending -> approved/denied. The approver must differ
# from the requester (403, the bill-pay self-approve pattern). Approve
# WARNS (never blocks) when approved time overlaps a scheduled event
# the person is rostered for, and REFUSES a balance below zero unless
# the admin passes override_allowed=true, which is audited. PTO has no
# money in it: nothing here writes erp_acct_* or any payroll table.
# Like the rest of HR, these tables are NOT in _ERP_RESET_TABLES.
HR_PTO_DEFAULT_TYPES = ("vacation", "sick", "personal")
HR_PTO_STATUSES = ("draft", "pending", "approved", "denied")


def _hr_pto_seed_types(conn):
    """Seed the three default request types on first use (fixed list,
    not invented employee data). INSERT OR IGNORE: safe to call on
    every PTO endpoint."""
    now = datetime.now(timezone.utc).isoformat()
    for name in HR_PTO_DEFAULT_TYPES:
        conn.execute(
            "INSERT OR IGNORE INTO erp_hr_pto_types (name, active,"
            " created_by, created_at) VALUES (?, 1, '', ?)",
            (name, now))


def _hr_pto_type_dict(row):
    return {"id": row["id"], "name": row["name"],
            "active": bool(row["active"]),
            "created_by": row["created_by"] or "",
            "created_at": row["created_at"]}


def _hr_pto_resolve_type(conn, data):
    """Resolve a request type from {"type_id": n} or {"type": name}
    (name matched case-insensitively). None when not found."""
    tid = data.get("type_id")
    if tid is not None and tid != "":
        try:
            tid = int(tid)
        except (TypeError, ValueError):
            return None
        return conn.execute("SELECT * FROM erp_hr_pto_types WHERE id = ?",
                            (tid,)).fetchone()
    name = (data.get("type") or "").strip().lower()
    if not name:
        return None
    return conn.execute(
        "SELECT * FROM erp_hr_pto_types WHERE lower(name) = ?",
        (name,)).fetchone()


def _hr_pto_parse_days(value):
    """A grant day count: a real number >= 0. False = invalid.
    Booleans are rejected (True would parse as 1)."""
    if value is None or value == "" or isinstance(value, bool):
        return False
    try:
        days = float(value)
    except (TypeError, ValueError):
        return False
    if days < 0:
        return False
    return days


def _hr_pto_span_days(start_date, end_date):
    """Inclusive calendar days from start to end (same day = 1)."""
    start = datetime.strptime(start_date, "%Y-%m-%d")
    end = datetime.strptime(end_date, "%Y-%m-%d")
    return float((end - start).days + 1)


def _hr_pto_warnings(conn, employee_id, start_date, end_date):
    """Events the person is rostered for whose date falls inside the
    requested span. Warnings only -- callers never block on these."""
    rows = conn.execute(
        "SELECT e.id, e.name, e.date FROM erp_hr_event_staff s"
        " JOIN erp_hr_events e ON e.id = s.event_id"
        " WHERE s.employee_id = ? AND e.date >= ? AND e.date <= ?"
        " ORDER BY e.date, e.name",
        (employee_id, start_date, end_date)).fetchall()
    return [{"event_id": r["id"], "event_name": r["name"] or "",
             "event_date": r["date"] or ""} for r in rows]


def _hr_pto_approved_days(conn, employee_id, type_id):
    row = conn.execute(
        "SELECT COALESCE(SUM(days), 0) AS total FROM erp_hr_pto_requests"
        " WHERE employee_id = ? AND type_id = ? AND status = 'approved'",
        (employee_id, type_id)).fetchone()
    return float(row["total"] or 0)


def _hr_pto_accrued_days(conn, employee_id, type_id):
    """Days accrued for one employee + type: the SUM of the accrual
    ledger (SOP 12.25, M6). Negative rows are carryover removals, so
    they reduce the total. Zero when the ledger has no rows."""
    row = conn.execute(
        "SELECT COALESCE(SUM(days), 0) AS total"
        " FROM erp_hr_pto_accrual_ledger"
        " WHERE employee_id = ? AND type_id = ?",
        (employee_id, type_id)).fetchone()
    return float(row["total"] or 0)


def _hr_pto_balance_for(conn, employee_id, type_row):
    grow = conn.execute(
        "SELECT granted_days FROM erp_hr_pto_balances"
        " WHERE employee_id = ? AND type_id = ?",
        (employee_id, type_row["id"])).fetchone()
    granted = float(grow["granted_days"]) if grow else 0.0
    accrued = _hr_pto_accrued_days(conn, employee_id, type_row["id"])
    approved = _hr_pto_approved_days(conn, employee_id, type_row["id"])
    return {"type_id": type_row["id"], "type": type_row["name"],
            "granted_days": granted, "accrued_days": accrued,
            "approved_days": approved,
            "remaining_days": granted + accrued - approved}


def _hr_pto_request_dict(conn, row):
    return {"id": row["id"], "employee_id": row["employee_id"],
            "type_id": row["type_id"], "type": row["type_name"] or "",
            "start_date": row["start_date"] or "",
            "end_date": row["end_date"] or "",
            "days": float(row["days"]),
            "status": row["status"],
            "notes": row["notes"] or "",
            "requested_by": row["requested_by"] or "",
            "decided_by": row["decided_by"] or "",
            "decided_at": row["decided_at"] or "",
            "override_used": bool(row["override_used"]),
            "created_at": row["created_at"],
            "updated_at": row["updated_at"] or "",
            "warnings": _hr_pto_warnings(
                conn, row["employee_id"], row["start_date"] or "",
                row["end_date"] or "")}


def _hr_pto_get_request(conn, req_id):
    try:
        req_id = int(req_id)
    except (TypeError, ValueError):
        return None
    return conn.execute("SELECT * FROM erp_hr_pto_requests WHERE id = ?",
                        (req_id,)).fetchone()


@app.get("/api/erp/hr/pto-types")
def hr_pto_list_types():
    """The admin-configurable request-type list, seeded on first use
    with vacation / sick / personal. Inactive types stay listed
    (marked inactive) so old requests keep their label."""
    _, err = _require_erp_admin()
    if err:
        return err
    conn = db()
    _hr_pto_seed_types(conn)
    conn.commit()
    rows = conn.execute(
        "SELECT * FROM erp_hr_pto_types ORDER BY name").fetchall()
    out = [_hr_pto_type_dict(r) for r in rows]
    conn.close()
    return jsonify(types=out)


@app.post("/api/erp/hr/pto-types")
def hr_pto_create_type():
    """Add a request type. Names are unique (case-insensitive) -- a
    second add of the same name is a 409, even for an inactive type."""
    actor, err = _require_erp_admin()
    if err:
        return err
    data = request.get_json(force=True) or {}
    name = (data.get("name") or "").strip()
    if not name:
        return jsonify(error="name is required"), 400
    if len(name) > 100:
        return jsonify(error="name must be 100 characters or fewer"), 400
    conn = db()
    _hr_pto_seed_types(conn)
    existing = conn.execute(
        "SELECT * FROM erp_hr_pto_types WHERE lower(name) = ?",
        (name.lower(),)).fetchone()
    if existing:
        conn.close()
        return jsonify(error="a PTO type named '%s' already exists" % name), 409
    now = datetime.now(timezone.utc).isoformat()
    cur = conn.execute(
        "INSERT INTO erp_hr_pto_types (name, active, created_by, created_at)"
        " VALUES (?, 1, ?, ?)", (name, actor, now))
    _erp_staff_audit(conn, actor, "hr.pto_type_created", "hr_pto_type",
                     cur.lastrowid, "PTO type '%s' added" % name)
    conn.commit()
    row = conn.execute("SELECT * FROM erp_hr_pto_types WHERE id = ?",
                       (cur.lastrowid,)).fetchone()
    payload = _hr_pto_type_dict(row)
    conn.close()
    return jsonify(payload), 201


@app.post("/api/erp/hr/pto-types/<int:type_id>/deactivate")
def hr_pto_deactivate_type(type_id):
    """Retire a request type: it stops being offered for new requests
    but stays on old ones. Already-inactive is a 400."""
    actor, err = _require_erp_admin()
    if err:
        return err
    conn = db()
    row = conn.execute("SELECT * FROM erp_hr_pto_types WHERE id = ?",
                       (type_id,)).fetchone()
    if not row:
        conn.close()
        return jsonify(error="PTO type not found"), 404
    if not row["active"]:
        conn.close()
        return jsonify(error="PTO type '%s' is already inactive"
                       % row["name"]), 400
    conn.execute("UPDATE erp_hr_pto_types SET active = 0 WHERE id = ?",
                 (type_id,))
    _erp_staff_audit(conn, actor, "hr.pto_type_deactivated", "hr_pto_type",
                     type_id, "PTO type '%s' deactivated" % row["name"])
    conn.commit()
    row = conn.execute("SELECT * FROM erp_hr_pto_types WHERE id = ?",
                       (type_id,)).fetchone()
    payload = _hr_pto_type_dict(row)
    conn.close()
    return jsonify(payload)


@app.get("/api/erp/hr/employees/<int:employee_id>/pto-balance")
def hr_pto_balance(employee_id):
    """Per-type balances for one employee: granted (admin-set, starts
    at 0) minus approved days, live-computed so it cannot drift."""
    _, err = _require_erp_admin()
    if err:
        return err
    conn = db()
    emp = _hr_get_employee(conn, employee_id)
    if not emp:
        conn.close()
        return jsonify(error="employee not found"), 404
    _hr_pto_seed_types(conn)
    conn.commit()
    types = conn.execute(
        "SELECT * FROM erp_hr_pto_types WHERE active = 1"
        " ORDER BY name").fetchall()
    out = [_hr_pto_balance_for(conn, employee_id, t) for t in types]
    conn.close()
    return jsonify(employee_id=employee_id, balances=out)


@app.post("/api/erp/hr/employees/<int:employee_id>/pto-grant")
def hr_pto_grant(employee_id):
    """Set an employee's annual grant (decimal days, REAL) for one
    type. Admin-only; the hand grant is separate from accrued days
    (SOP 12.25) and there is no default above 0."""
    actor, err = _require_erp_admin()
    if err:
        return err
    data = request.get_json(force=True) or {}
    days = _hr_pto_parse_days(data.get("granted_days"))
    if days is False:
        return jsonify(error="granted_days must be a number, 0 or more"), 400
    conn = db()
    emp = _hr_get_employee(conn, employee_id)
    if not emp:
        conn.close()
        return jsonify(error="employee not found"), 404
    _hr_pto_seed_types(conn)
    type_row = _hr_pto_resolve_type(conn, data)
    if not type_row:
        conn.close()
        return jsonify(error="unknown PTO type"), 400
    if not type_row["active"]:
        conn.close()
        return jsonify(error="PTO type '%s' is inactive"
                       % type_row["name"]), 400
    now = datetime.now(timezone.utc).isoformat()
    conn.execute(
        "INSERT INTO erp_hr_pto_balances (employee_id, type_id,"
        " granted_days, updated_by, updated_at) VALUES (?, ?, ?, ?, ?)"
        " ON CONFLICT(employee_id, type_id) DO UPDATE SET"
        " granted_days = excluded.granted_days,"
        " updated_by = excluded.updated_by,"
        " updated_at = excluded.updated_at",
        (employee_id, type_row["id"], days, actor, now))
    _erp_staff_audit(conn, actor, "hr.pto_grant_set", "hr_pto_balance",
                     employee_id, "PTO grant for %s set to %.2f days for %s"
                     % (type_row["name"], days, emp["name"]))
    conn.commit()
    payload = _hr_pto_balance_for(conn, employee_id, type_row)
    conn.close()
    return jsonify(payload)


@app.get("/api/erp/hr/pto-requests")
def hr_pto_list_requests():
    """All PTO requests, optionally filtered by employee_id / status.
    Each row carries its overlap warnings."""
    _, err = _require_erp_admin()
    if err:
        return err
    status = (request.args.get("status") or "").strip()
    if status and status not in HR_PTO_STATUSES:
        return jsonify(error="status must be draft, pending, approved"
                       " or denied"), 400
    employee_id = request.args.get("employee_id")
    if employee_id is not None and employee_id != "":
        try:
            employee_id = int(employee_id)
        except (TypeError, ValueError):
            return jsonify(error="employee_id must be a number"), 400
    else:
        employee_id = None
    conn = db()
    where = []
    args = []
    if status:
        where.append("status = ?")
        args.append(status)
    if employee_id is not None:
        where.append("employee_id = ?")
        args.append(employee_id)
    rows = conn.execute(
        "SELECT * FROM erp_hr_pto_requests"
        + (" WHERE " + " AND ".join(where) if where else "")
        + " ORDER BY id DESC", args).fetchall()
    out = [_hr_pto_request_dict(conn, r) for r in rows]
    conn.close()
    return jsonify(requests=out)


@app.post("/api/erp/hr/pto-requests")
def hr_pto_create_request():
    """Create a time-off request as a DRAFT. Days are the inclusive
    calendar days of the span. The response carries overlap warnings
    for rostered events inside the span -- warnings only, never a
    block."""
    actor, err = _require_erp_admin()
    if err:
        return err
    data = request.get_json(force=True) or {}
    try:
        employee_id = int(data.get("employee_id"))
    except (TypeError, ValueError):
        return jsonify(error="employee_id must be a number"), 400
    start_date = (data.get("start_date") or "").strip()
    end_date = (data.get("end_date") or "").strip()
    if not start_date or not _hr_valid_hire_date(start_date):
        return jsonify(error="start_date must be YYYY-MM-DD"), 400
    if not end_date or not _hr_valid_hire_date(end_date):
        return jsonify(error="end_date must be YYYY-MM-DD"), 400
    if end_date < start_date:
        return jsonify(error="end_date must be on or after start_date"), 400
    notes = (data.get("notes") or "").strip()
    if len(notes) > 1000:
        return jsonify(error="notes must be 1000 characters or fewer"), 400
    conn = db()
    emp = _hr_get_employee(conn, employee_id)
    if not emp:
        conn.close()
        return jsonify(error="employee not found"), 404
    _hr_pto_seed_types(conn)
    type_row = _hr_pto_resolve_type(conn, data)
    if not type_row:
        conn.close()
        return jsonify(error="unknown PTO type"), 400
    if not type_row["active"]:
        conn.close()
        return jsonify(error="PTO type '%s' is inactive"
                       % type_row["name"]), 400
    days = _hr_pto_span_days(start_date, end_date)
    # SOP 12.25: a leave policy's max_consecutive_days caps the span
    # of a request for that type (400 when exceeded). A policy with
    # no cap, or no policy at all, never blocks a request.
    _policy = conn.execute(
        "SELECT * FROM erp_hr_leave_policies WHERE type_id = ?",
        (type_row["id"],)).fetchone()
    if _policy and _policy["max_consecutive_days"] is not None \
            and days > float(_policy["max_consecutive_days"]):
        conn.close()
        return jsonify(error="this time-off span of %.2f days exceeds"
                       " the maximum consecutive days (%.2f) for %s"
                       % (days, float(_policy["max_consecutive_days"]),
                          type_row["name"])), 400
    now = datetime.now(timezone.utc).isoformat()
    cur = conn.execute(
        "INSERT INTO erp_hr_pto_requests (employee_id, type_id, type_name,"
        " start_date, end_date, days, status, notes, requested_by,"
        " decided_by, decided_at, override_used, created_at, updated_at)"
        " VALUES (?, ?, ?, ?, ?, ?, 'draft', ?, ?, '', '', 0, ?, ?)",
        (employee_id, type_row["id"], type_row["name"], start_date,
         end_date, days, notes, actor, now, now))
    _erp_staff_audit(conn, actor, "hr.pto_request_created", "hr_pto_request",
                     cur.lastrowid, "PTO request #%d: %s %.2f days %s..%s"
                     " for %s (draft)"
                     % (cur.lastrowid, type_row["name"], days, start_date,
                        end_date, emp["name"]))
    conn.commit()
    row = conn.execute("SELECT * FROM erp_hr_pto_requests WHERE id = ?",
                       (cur.lastrowid,)).fetchone()
    payload = _hr_pto_request_dict(conn, row)
    conn.close()
    return jsonify(payload), 201


@app.post("/api/erp/hr/pto-requests/<int:req_id>/submit")
def hr_pto_submit_request(req_id):
    """Move a draft to pending, ready for another admin to decide.
    Any admin may submit; the approver still cannot be the requester."""
    actor, err = _require_erp_admin()
    if err:
        return err
    conn = db()
    req = _hr_pto_get_request(conn, req_id)
    if not req:
        conn.close()
        return jsonify(error="PTO request not found"), 404
    if req["status"] != "draft":
        conn.close()
        return jsonify(error="only a draft request can be submitted"
                       " (status: %s)" % req["status"]), 400
    now = datetime.now(timezone.utc).isoformat()
    conn.execute("UPDATE erp_hr_pto_requests SET status = 'pending',"
                 " updated_at = ? WHERE id = ?", (now, req_id))
    _erp_staff_audit(conn, actor, "hr.pto_request_submitted",
                     "hr_pto_request", req_id,
                     "PTO request #%d submitted for approval (requested by"
                     " %s)" % (req_id, req["requested_by"] or ""))
    conn.commit()
    row = _hr_pto_get_request(conn, req_id)
    payload = _hr_pto_request_dict(conn, row)
    conn.close()
    return jsonify(payload)


@app.post("/api/erp/hr/pto-requests/<int:req_id>/approve")
def hr_pto_approve_request(req_id):
    """Approve a pending request. The approver must differ from the
    requester (403, the bill-pay self-approve pattern). Approval
    refuses a balance below zero unless override_allowed is true --
    an override is recorded on the request and in the audit log.
    Overlap warnings are returned but never block approval."""
    actor, err = _require_erp_admin()
    if err:
        return err
    data = request.get_json(force=True) or {}
    override = bool(data.get("override_allowed"))
    conn = db()
    req = _hr_pto_get_request(conn, req_id)
    if not req:
        conn.close()
        return jsonify(error="PTO request not found"), 404
    if req["status"] != "pending":
        conn.close()
        return jsonify(error="only a pending request can be approved"
                       " (status: %s)" % req["status"]), 400
    if (actor or "") == (req["requested_by"] or ""):
        conn.close()
        return jsonify(error="you cannot approve your own time-off"
                       " request; another admin must approve it"), 403
    type_row = conn.execute(
        "SELECT * FROM erp_hr_pto_types WHERE id = ?",
        (req["type_id"],)).fetchone()
    if not type_row:
        conn.close()
        return jsonify(error="PTO type no longer exists"), 400
    balance = _hr_pto_balance_for(conn, req["employee_id"], type_row)
    remaining_after = balance["remaining_days"] - float(req["days"])
    if remaining_after < 0 and not override:
        warnings = _hr_pto_warnings(
            conn, req["employee_id"], req["start_date"], req["end_date"])
        conn.close()
        return jsonify(error="approving %.2f days would take the %s"
                       " balance to %.2f days below zero; pass"
                       " override_allowed to approve anyway"
                       % (float(req["days"]), type_row["name"],
                          remaining_after),
                       balance=balance, warnings=warnings), 400
    now = datetime.now(timezone.utc).isoformat()
    conn.execute(
        "UPDATE erp_hr_pto_requests SET status = 'approved',"
        " decided_by = ?, decided_at = ?, override_used = ?,"
        " updated_at = ? WHERE id = ?",
        (actor, now, 1 if override else 0, now, req_id))
    _erp_staff_audit(conn, actor, "hr.pto_request_approved",
                     "hr_pto_request", req_id,
                     "PTO request #%d approved by %s (requested by %s)"
                     "%s" % (req_id, actor or "", req["requested_by"] or "",
                             " -- OVERRIDE: balance went negative"
                             if override else ""))
    conn.commit()
    row = _hr_pto_get_request(conn, req_id)
    payload = _hr_pto_request_dict(conn, row)
    payload["balance"] = _hr_pto_balance_for(conn, req["employee_id"],
                                             type_row)
    conn.close()
    return jsonify(payload)


@app.post("/api/erp/hr/pto-requests/<int:req_id>/deny")
def hr_pto_deny_request(req_id):
    """Deny a pending request. Posts nothing; the decision is by an
    admin other than the requester, like approval."""
    actor, err = _require_erp_admin()
    if err:
        return err
    conn = db()
    req = _hr_pto_get_request(conn, req_id)
    if not req:
        conn.close()
        return jsonify(error="PTO request not found"), 404
    if req["status"] != "pending":
        conn.close()
        return jsonify(error="only a pending request can be denied"
                       " (status: %s)" % req["status"]), 400
    if (actor or "") == (req["requested_by"] or ""):
        conn.close()
        return jsonify(error="you cannot deny your own time-off request;"
                       " another admin must decide it"), 403
    now = datetime.now(timezone.utc).isoformat()
    conn.execute(
        "UPDATE erp_hr_pto_requests SET status = 'denied',"
        " decided_by = ?, decided_at = ?, updated_at = ? WHERE id = ?",
        (actor, now, now, req_id))
    _erp_staff_audit(conn, actor, "hr.pto_request_denied",
                     "hr_pto_request", req_id,
                     "PTO request #%d denied by %s (requested by %s)"
                     % (req_id, actor or "", req["requested_by"] or ""))
    conn.commit()
    row = _hr_pto_get_request(conn, req_id)
    payload = _hr_pto_request_dict(conn, row)
    conn.close()
    return jsonify(payload)


# ---------------- PTO accrual, carryover + leave policies (SOP 12.25, M6) ----------------
# Admin-only via _require_erp_admin(), like the rest of HR. Accrual is
# ADMIN-TRIGGERED, never automatic on a timer: an admin runs POST
# /api/erp/hr/pto/accrue and the run writes one ledger row per
# employee per rule for the period. Re-running the same period adds 0
# (idempotent per employee + rule + period). Carryover is likewise an
# explicit admin run with a preview step: the preview computes the
# removals without writing anything, and only the confirmed run writes
# the negative ledger rows. Every grant is a ledger row, so the balance
# (granted + accrued - approved, SOP 12.11 + 12.25) is auditable.
# Event staff (scope_type 'event') and people with no scope set never
# accrue. Leave policies are text + flags per type: the documentation
# flag only shows a reminder on the request form, while
# max_consecutive_days is validated on request creation (400 when the
# span exceeds it). The hand-grant flow (SOP 12.11) stays intact.
# All three tables start empty and are NOT in _ERP_RESET_TABLES.
HR_PTO_ACCRUAL_CADENCES = ("monthly", "annual")
HR_PTO_ACCRUAL_STARTS = ("hire_date", "period_start")


def _hr_pto_accrual_rule(conn, rule_id):
    try:
        rule_id = int(rule_id)
    except (TypeError, ValueError):
        return None
    return conn.execute(
        "SELECT * FROM erp_hr_pto_accrual_rules WHERE id = ?",
        (rule_id,)).fetchone()


def _hr_pto_accrual_rule_dict(conn, row):
    type_row = conn.execute(
        "SELECT * FROM erp_hr_pto_types WHERE id = ?",
        (row["type_id"],)).fetchone()
    return {
        "id": row["id"], "type_id": row["type_id"],
        "pto_type_id": row["type_id"],
        "type": type_row["name"] if type_row else "",
        "type_name": type_row["name"] if type_row else "",
        "days_per_year": float(row["days_per_year"]),
        "accrual_cadence": row["accrual_cadence"] or "monthly",
        "accrual_start": row["accrual_start"] or "hire_date",
        "effective_from": row["effective_from"] or "",
        "max_balance_days": (None if row["max_balance_days"] is None
                             else float(row["max_balance_days"])),
        "carryover_days": (None if row["carryover_days"] is None
                           else float(row["carryover_days"])),
        "carryover_expires_months": row["carryover_expires_months"],
        "active": bool(row["active"]),
        "created_by": row["created_by"] or "",
        "created_at": row["created_at"],
        "updated_by": row["updated_by"] or "",
        "updated_at": row["updated_at"] or "",
    }


def _hr_pto_rule_fields(data, conn, partial=False):
    """Validate accrual-rule fields. Returns (values, error). On
    create (partial=False) a PTO type and days_per_year are required.
    The type accepts a "type_id" or a "pto_type_id" alias. Caps and
    carryover are numbers >= 0 or blank (NULL = no cap / no
    carryover)."""
    values = {}
    if not partial or "type_id" in data or "pto_type_id" in data:
        tid = data.get("type_id", data.get("pto_type_id"))
        type_row = _hr_pto_resolve_type(
            conn, {"type_id": tid} if tid not in (None, "") else {})
        if not type_row:
            return None, "unknown PTO type"
        if not type_row["active"]:
            return None, "PTO type '%s' is inactive" % type_row["name"]
        values["type_id"] = type_row["id"]
    if not partial or "days_per_year" in data:
        days = _hr_pto_parse_days(data.get("days_per_year"))
        if days is False:
            return None, "days_per_year must be a number, 0 or more"
        values["days_per_year"] = days
    if "accrual_cadence" in data:
        cadence = (data.get("accrual_cadence") or "").strip()
        if cadence not in HR_PTO_ACCRUAL_CADENCES:
            return None, "accrual_cadence must be monthly or annual"
        values["accrual_cadence"] = cadence
    if "accrual_start" in data:
        start = (data.get("accrual_start") or "").strip()
        if start not in HR_PTO_ACCRUAL_STARTS:
            return None, "accrual_start must be hire_date or period_start"
        values["accrual_start"] = start
    if "effective_from" in data:
        effective = (data.get("effective_from") or "").strip()
        if effective and not _hr_valid_hire_date(effective):
            return None, "effective_from must be YYYY-MM-DD"
        values["effective_from"] = effective
    for key in ("max_balance_days", "carryover_days"):
        if key in data:
            raw = data.get(key)
            if raw is None or raw == "":
                values[key] = None
            else:
                parsed = _hr_pto_parse_days(raw)
                if parsed is False:
                    return None, ("%s must be a number, 0 or more,"
                                  " or blank") % key
                values[key] = parsed
    if "carryover_expires_months" in data:
        raw = data.get("carryover_expires_months")
        if raw is None or raw == "":
            values["carryover_expires_months"] = None
        elif isinstance(raw, bool):
            return None, ("carryover_expires_months must be a whole"
                          " number of months, 0 or more")
        else:
            try:
                months = int(raw)
            except (TypeError, ValueError):
                return None, ("carryover_expires_months must be a"
                              " whole number of months, 0 or more")
            if months < 0 or float(raw) != float(months):
                return None, ("carryover_expires_months must be a"
                              " whole number of months, 0 or more")
            values["carryover_expires_months"] = months
    if "active" in data:
        values["active"] = 1 if data.get("active") else 0
    return values, None


def _hr_pto_leave_policy(conn, policy_id):
    try:
        policy_id = int(policy_id)
    except (TypeError, ValueError):
        return None
    return conn.execute(
        "SELECT * FROM erp_hr_leave_policies WHERE id = ?",
        (policy_id,)).fetchone()


def _hr_pto_leave_policy_dict(conn, row):
    type_row = conn.execute(
        "SELECT * FROM erp_hr_pto_types WHERE id = ?",
        (row["type_id"],)).fetchone()
    return {
        "id": row["id"], "type_id": row["type_id"],
        "pto_type_id": row["type_id"],
        "type": type_row["name"] if type_row else "",
        "type_name": type_row["name"] if type_row else "",
        "policy_text": row["policy_text"] or "",
        "requires_documentation": bool(row["requires_documentation"]),
        "documentation_required": bool(row["requires_documentation"]),
        "max_consecutive_days": (
            None if row["max_consecutive_days"] is None
            else float(row["max_consecutive_days"])),
        "created_by": row["created_by"] or "",
        "created_at": row["created_at"],
        "updated_by": row["updated_by"] or "",
        "updated_at": row["updated_at"] or "",
    }


def _hr_pto_policy_fields(data, conn, partial=False):
    """Validate leave-policy fields. Returns (values, error). The
    type accepts "type_id" or a "pto_type_id" alias; the
    documentation flag accepts "requires_documentation" or a
    "documentation_required" alias."""
    values = {}
    if not partial or "type_id" in data or "pto_type_id" in data:
        tid = data.get("type_id", data.get("pto_type_id"))
        type_row = _hr_pto_resolve_type(
            conn, {"type_id": tid} if tid not in (None, "") else {})
        if not type_row:
            return None, "unknown PTO type"
        if not type_row["active"]:
            return None, "PTO type '%s' is inactive" % type_row["name"]
        values["type_id"] = type_row["id"]
    if not partial or "policy_text" in data:
        text = (data.get("policy_text") or "").strip()
        if len(text) > 5000:
            return None, "policy_text must be 5000 characters or fewer"
        values["policy_text"] = text
    doc_key = ("requires_documentation" if "requires_documentation" in data
               else "documentation_required" if "documentation_required"
               in data else None)
    if doc_key is not None:
        values["requires_documentation"] = \
            1 if data.get(doc_key) else 0
    if "max_consecutive_days" in data:
        raw = data.get("max_consecutive_days")
        if raw is None or raw == "":
            values["max_consecutive_days"] = None
        elif isinstance(raw, bool):
            return None, ("max_consecutive_days must be a number"
                          " greater than 0, or blank")
        else:
            try:
                days = float(raw)
            except (TypeError, ValueError):
                return None, ("max_consecutive_days must be a number"
                              " greater than 0, or blank")
            if days <= 0:
                return None, ("max_consecutive_days must be a number"
                              " greater than 0, or blank")
            values["max_consecutive_days"] = days
    return values, None


def _hr_pto_ledger_dict(conn, row):
    emp = _hr_get_employee(conn, row["employee_id"])
    type_row = conn.execute(
        "SELECT * FROM erp_hr_pto_types WHERE id = ?",
        (row["type_id"],)).fetchone()
    return {
        "id": row["id"], "employee_id": row["employee_id"],
        "employee_name": emp["name"] if emp else "",
        "rule_id": row["rule_id"], "type_id": row["type_id"],
        "pto_type_id": row["type_id"],
        "type": type_row["name"] if type_row else "",
        "type_name": type_row["name"] if type_row else "",
        "accrual_date": row["accrual_date"] or "",
        "period": row["period"] or "",
        "days": float(row["days"]),
        "reason": row["reason"] or "",
        "expires_at": row["expires_at"] or "",
        "created_by": row["created_by"] or "",
        "created_at": row["created_at"],
    }


@app.get("/api/erp/hr/pto/accrual-rules")
def hr_pto_list_accrual_rules():
    """List accrual rules with their PTO type. Starts empty."""
    _, err = _require_erp_admin()
    if err:
        return err
    conn = db()
    _hr_pto_seed_types(conn)
    conn.commit()
    rows = conn.execute(
        "SELECT * FROM erp_hr_pto_accrual_rules ORDER BY type_id"
        ).fetchall()
    out = [_hr_pto_accrual_rule_dict(conn, r) for r in rows]
    conn.close()
    return jsonify(rules=out)


@app.post("/api/erp/hr/pto/accrual-rules")
def hr_pto_create_accrual_rule():
    """Create one accrual rule per PTO type (201). A second rule for
    the same type is a 409."""
    actor, err = _require_erp_admin()
    if err:
        return err
    data = request.get_json(force=True) or {}
    conn = db()
    _hr_pto_seed_types(conn)
    fields, error = _hr_pto_rule_fields(data, conn)
    if error:
        conn.close()
        return jsonify(error=error), 400
    existing = conn.execute(
        "SELECT * FROM erp_hr_pto_accrual_rules WHERE type_id = ?",
        (fields["type_id"],)).fetchone()
    if existing:
        conn.close()
        return jsonify(error="an accrual rule already exists for this"
                       " PTO type"), 409
    now = datetime.now(timezone.utc).isoformat()
    cur = conn.execute(
        "INSERT INTO erp_hr_pto_accrual_rules (type_id, days_per_year,"
        " accrual_cadence, accrual_start, effective_from,"
        " max_balance_days, carryover_days, carryover_expires_months,"
        " active, created_by, created_at, updated_by, updated_at)"
        " VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
        (fields["type_id"], fields["days_per_year"],
         fields.get("accrual_cadence", "monthly"),
         fields.get("accrual_start", "hire_date"),
         fields.get("effective_from", ""),
         fields.get("max_balance_days"),
         fields.get("carryover_days"),
         fields.get("carryover_expires_months"),
         1, actor, now, actor, now))
    _erp_staff_audit(conn, actor, "hr.pto_accrual_rule_created",
                     "hr_pto_accrual_rule", cur.lastrowid,
                     "accrual rule #%d created for PTO type #%d"
                     " (%.2f days/year, %s)"
                     % (cur.lastrowid, fields["type_id"],
                        fields["days_per_year"],
                        fields.get("accrual_cadence", "monthly")))
    conn.commit()
    row = _hr_pto_accrual_rule(conn, cur.lastrowid)
    payload = _hr_pto_accrual_rule_dict(conn, row)
    conn.close()
    return jsonify(payload), 201


@app.get("/api/erp/hr/pto/accrual-rules/<int:rule_id>")
def hr_pto_get_accrual_rule(rule_id):
    """One accrual rule."""
    _, err = _require_erp_admin()
    if err:
        return err
    conn = db()
    row = _hr_pto_accrual_rule(conn, rule_id)
    if not row:
        conn.close()
        return jsonify(error="accrual rule not found"), 404
    out = _hr_pto_accrual_rule_dict(conn, row)
