@app.delete("/api/erp/hr/pto/accrual-rules/<int:rule_id>")
def hr_pto_delete_accrual_rule(rule_id):
    """Delete an accrual rule, permanently. Ledger rows survive:
    the accrual history is never deleted, so deleting a rule never
    touches the ledger -- its rows keep showing with the rule id and
    type. Two-tap confirm on the frontend; no window.confirm."""
    actor, err = _require_erp_admin()
    if err:
        return err
    conn = db()
    row = _hr_pto_accrual_rule(conn, rule_id)
    if not row:
        conn.close()
        return jsonify(error="accrual rule not found"), 404
    kept = conn.execute(
        "SELECT COUNT(*) FROM erp_hr_pto_accrual_ledger"
        " WHERE rule_id = ?", (rule_id,)).fetchone()[0]
