def _quality_trace_result(conn, lot_code):
    """Run the lot trace over the batch<->order tables and return the
    trace dict, or None when the lot code appears nowhere (no lot row,
    no ingredient use, no finished batch). Shared by the read-only
    trace-lot endpoint and recall execution, so both see the same
    affected orders for a lot."""
    lot = conn.execute("SELECT * FROM erp_lots WHERE lot_code = ?"
                       " ORDER BY id LIMIT 1", (lot_code,)).fetchone()
    consumed = conn.execute(
        "SELECT b.id, b.batch_number, b.recipe_id, b.status, b.lot_code,"
        " SUM(bi.qty_used) AS qty_used, MIN(bi.unit) AS unit"
        " FROM erp_batch_ingredients bi"
        " JOIN erp_production_batches b ON b.id = bi.batch_id"
        " WHERE bi.lot_code = ?"
        " GROUP BY b.id, b.batch_number, b.recipe_id, b.status, b.lot_code"
        " ORDER BY b.id", (lot_code,)).fetchall()
    batches = []
    batch_ids = set()
    for b in consumed:
        recipe = conn.execute("SELECT name FROM erp_recipes WHERE id = ?",
                              (b["recipe_id"],)).fetchone()
        batches.append({"batch_id": b["id"], "batch_number": b["batch_number"],
                        "recipe_name": recipe["name"] if recipe else "",
                        "status": b["status"], "finished_lot_code": b["lot_code"] or "",
                        "qty_used": b["qty_used"], "unit": b["unit"] or ""})
        batch_ids.add(b["id"])
    finished = conn.execute(
        "SELECT * FROM erp_production_batches WHERE lot_code = ?"
        " ORDER BY id LIMIT 1", (lot_code,)).fetchone()
    finished_batch = None
    if finished:
        recipe = conn.execute("SELECT name FROM erp_recipes WHERE id = ?",
                              (finished["recipe_id"],)).fetchone()
        finished_batch = {"batch_id": finished["id"],
                          "batch_number": finished["batch_number"],
                          "recipe_name": recipe["name"] if recipe else "",
                          "status": finished["status"],
                          "finished_lot_code": finished["lot_code"] or ""}
        batch_ids.add(finished["id"])
    if not lot and not batches and not finished_batch:
        return None
    orders = []
    seen_orders = set()
    for bid in sorted(batch_ids):
        for l in conn.execute(
                "SELECT * FROM erp_batch_orders WHERE batch_id = ? ORDER BY id",
                (bid,)).fetchall():
            key = (l["order_source"], l["order_id"])
            if key in seen_orders:
                continue
            seen_orders.add(key)
            o = _erp_order_brief(conn, l["order_source"], l["order_id"])
            orders.append({"order_source": l["order_source"],
                           "order_id": l["order_id"],
                           "order_number": o["number"] if o else "",
                           "customer_name": o["customer_name"] if o else "",
                           "qty_bags": l["qty_bags"]})
    lot_out = _quality_lot_dict(conn, lot) if lot else None
    return {"lot_code": lot_code, "lot": lot_out,
            "batches": batches, "finished_batch": finished_batch,
            "orders": orders}


def _quality_recall_customers(orders):
    """Affected customers for a recall snapshot: one entry per distinct
    customer name across the frozen affected orders, with the order
    numbers that name is attached to. An order with no customer name
    (e.g. a wholesale order with no account) still counts, under ""."""
    by_name = {}
    names = []
    for o in orders:
        name = o.get("customer_name") or ""
        if name not in by_name:
            by_name[name] = {"customer_name": name, "order_numbers": [],
                             "order_count": 0}
            names.append(name)
        by_name[name]["order_numbers"].append(
            o.get("order_number") or ("#" + str(o.get("order_id"))))
        by_name[name]["order_count"] += 1
    return [by_name[n] for n in names]


def _quality_recall_execution_dict(row):
    """An execution row with its frozen JSON snapshots parsed."""
    def _parse(value):
        try:
            parsed = json.loads(value or "[]")
        except (ValueError, TypeError):
            return []
        return parsed if isinstance(parsed, list) else []
    return {"id": row["id"], "lot_code": row["lot_code"] or "",
            "reason": row["reason"] or "", "status": row["status"],
            "affected_orders": _parse(row["affected_orders_json"]),
            "affected_customers": _parse(row["affected_customers_json"]),
            "notified_orders": _parse(row["notified_orders_json"]),
            "opened_by": row["opened_by"] or "",
            "opened_at": row["opened_at"],
            "closed_by": row["closed_by"] or "",
            "closed_at": row["closed_at"]}


@app.get("/api/erp/quality/trace-lot")
def quality_trace_lot():
    """Trace a lot code: the batches that consumed it as an ingredient,
    the batch that produced it as a finished lot (if any), and the
    orders those batches went into. Read-only -- it reuses the existing
    batch<->order trace tables (erp_batch_ingredients,
    erp_batch_orders) and duplicates no trace data. 404 when the lot
    code appears nowhere (no lot row, no ingredient use, no finished
    batch)."""
    _, err = _require_erp_admin()
    if err:
        return err
    lot_code = (request.args.get("lot_code") or "").strip()
    if not lot_code:
        return jsonify(error="lot_code is required"), 400
    conn = db()
    result = _quality_trace_result(conn, lot_code)
    conn.close()
    if result is None:
        return jsonify(error="lot %s not found" % lot_code), 404
    return jsonify(result)


# --- Recall execution (Wave 3 ops item 5, SOP 13.17) ---
# Admin-only via _require_erp_admin(), like the recall plan. Opening an
# execution freezes the trace-lot result at that moment: the affected
# orders/customers snapshot never changes afterwards, even if a batch
# or order is later edited. Status moves open -> notified -> closed
# only; the notified step is enforced server-side (every affected
# order must be marked notified first, vacuous when there are none).
# There is no delete endpoint: closing a recall never deletes it.
@app.post("/api/erp/quality/recall-executions")
def quality_recall_execution_create():
    """Open a recall execution for one lot code. The server runs the
    existing lot trace and freezes its affected orders/customers.
    404 when the lot has no trace."""
    actor, err = _require_erp_admin()
    if err:
        return err
    data = request.get_json(force=True) or {}
    lot_code = (data.get("lot_code") or "").strip()
    if not lot_code:
        return jsonify(error="lot_code is required"), 400
    if len(lot_code) > 200:
        return jsonify(error="lot_code must be 200 characters or fewer"), 400
    reason = data.get("reason") or ""
    if not isinstance(reason, str):
        return jsonify(error="reason must be text"), 400
    reason = reason.strip()
    if len(reason) > 2000:
        return jsonify(error="reason must be 2000 characters or fewer"), 400
    conn = db()
    result = _quality_trace_result(conn, lot_code)
    if result is None:
        conn.close()
        return jsonify(error="lot %s not found" % lot_code), 404
    orders = result["orders"]
    customers = _quality_recall_customers(orders)
    now = datetime.now(timezone.utc).isoformat()
    cur = conn.execute(
        "INSERT INTO erp_quality_recall_executions (lot_code, reason,"
        " status, affected_orders_json, affected_customers_json,"
        " notified_orders_json, opened_by, opened_at)"
        " VALUES (?, ?, 'open', ?, ?, '[]', ?, ?)",
        (lot_code, reason, json.dumps(orders), json.dumps(customers),
         actor, now))
    row = conn.execute(
        "SELECT * FROM erp_quality_recall_executions WHERE id = ?",
        (cur.lastrowid,)).fetchone()
    _erp_staff_audit(conn, actor, "quality.recall_execution_opened",
                     "recall_execution", row["id"],
                     "lot %s, %d affected order(s)"
                     % (lot_code, len(orders)))
    conn.commit()
    conn.close()
    return jsonify(execution=_quality_recall_execution_dict(row)), 201


