@app.get("/api/erp/quality/temperature-log")
def quality_temperature_log():
    """Temperature readings across completed checklists, oldest
    first. Filter by store_id, from / to (checklist_date)."""
    _, err = _require_erp_admin()
    if err:
        return err
    conn = db()
    rows = conn.execute(
        "SELECT * FROM erp_quality_checklists"
        " ORDER BY checklist_date, id").fetchall()
    store_id = request.args.get("store_id")
    frm = request.args.get("from") or ""
    to = request.args.get("to") or ""
    readings = []
    for r in rows:
        d = _quality_checklist_dict(r)
        if store_id not in (None, ""):
            try:
                want = int(store_id)
            except (TypeError, ValueError):
                continue
            if d["store_id"] != want:
                continue
        if frm and d["checklist_date"] < frm:
            continue
        if to and d["checklist_date"] > to:
            continue
        store_name = ""
        if d["store_id"] is not None:
            srow = conn.execute(
                "SELECT name FROM erp_stores WHERE id = ?",
                (d["store_id"],)).fetchone()
            store_name = (srow["name"] if srow else "") or ""
        for item in d["items"]:
            if item.get("kind") == "temperature" and                     item.get("temperature_f") is not None:
                readings.append({
                    "checklist_id": d["id"],
                    "checklist_date": d["checklist_date"],
                    "store_id": d["store_id"], "store_name": store_name,
                    "template_name": d["template_name"],
                    "label": item.get("label") or "",
                    "temperature_f": item.get("temperature_f"),
                    "completed_by": d["completed_by"] or ""})
    conn.close()
    return jsonify(readings=readings)


# ---------------- SOP Library ----------------
# Read copy of the SOP files (files/sops/). List/get are admin-only;
# import is admin OR the cron secret (the automated sync job runs it
# after SOP edits); delete is admin-only. The library never edits SOP
# text -- edits happen in the files and are re-imported.
_QUALITY_SOP_DEPTS = {
    1: "Dashboard", 2: "Inventory", 3: "Purchasing", 4: "Production",
    5: "Order hub", 6: "Wholesale accounts", 7: "Reports",
    8: "Marketing & Service", 9: "Accounting", 10: "Settings",
    11: "Staff & Permissions", 12: "HR", 13: "Quality & Food Safety",
    14: "Legal & Compliance", 15: "Stores",
}


def _quality_sop_dict(row, include_body=False):
    d = {
        "id": row["id"], "dept": row["dept"],
        "dept_name": _QUALITY_SOP_DEPTS.get(row["dept"], ""),
        "number": row["number"], "title": row["title"],
        "status": row["status"], "position": row["position"],
        "imported_by": row["imported_by"],
        "created_at": row["created_at"], "updated_at": row["updated_at"],
    }
    if include_body:
        d["body"] = row["body"]
    return d


def _quality_sop_import_actor():
    """Admin session, or the cron secret for the automated SOP sync.
    Returns (actor, error-response-or-None)."""
    actor, err = _require_erp_admin()
    if err is None:
        return actor, None
    if CRON_SECRET and hmac.compare_digest(request.headers.get("X-Cron-Secret", ""), CRON_SECRET):
        return "cron", None
    return None, err


@app.get("/api/erp/quality/sops")
def quality_sops_list():
    """List SOPs (no bodies -- use the detail endpoint to read one).
    Filter by dept (1-15) and q (matches title or body)."""
    _, err = _require_erp_admin()
    if err:
        return err
    dept = request.args.get("dept")
    q = (request.args.get("q") or "").strip()
    conn = db()
    rows = conn.execute(
        "SELECT * FROM erp_quality_sops ORDER BY dept, position, id"
        ).fetchall()
    conn.close()
    sops = []
    for r in rows:
        if dept not in (None, ""):
            try:
                if r["dept"] != int(dept):
                    continue
            except (TypeError, ValueError):
                continue
        if q:
            ql = q.lower()
            if ql not in (r["title"] or "").lower() and \
                    ql not in (r["body"] or "").lower():
                continue
        sops.append(_quality_sop_dict(r))
    return jsonify(sops=sops, total=len(sops))


@app.get("/api/erp/quality/sops/<int:sop_id>")
def quality_sop_get(sop_id):
    """One SOP, with its markdown body."""
    _, err = _require_erp_admin()
    if err:
        return err
    conn = db()
    row = conn.execute("SELECT * FROM erp_quality_sops WHERE id = ?",
                       (sop_id,)).fetchone()
    conn.close()
    if not row:
        return jsonify(error="sop not found"), 404
    return jsonify(sop=_quality_sop_dict(row, include_body=True))


@app.post("/api/erp/quality/sops/import")
def quality_sops_import():
    """Upsert SOPs from the SOP files. Body: {"sops": [...], "prune":
    true/false}. Each item: dept (1-15), number ("" when unnumbered),
    title, body, status, position. Upsert key is (dept, title).
    With prune true (and a non-empty list), rows not in the import
    set are deleted -- a retired SOP leaves the library."""
    actor, err = _quality_sop_import_actor()
    if err:
        return err
    data = request.get_json(force=True) or {}
    items = data.get("sops")
    if not isinstance(items, list) or len(items) > 1000:
        return jsonify(error="sops must be a list of at most 1000 SOPs"), 400
    prune = bool(data.get("prune"))
    cleaned = []
    for i, item in enumerate(items):
        if not isinstance(item, dict):
            return jsonify(error="sops[%d] must be an object" % i), 400
        dept = item.get("dept")
        if not isinstance(dept, int) or isinstance(dept, bool) \
                or dept not in _QUALITY_SOP_DEPTS:
            return jsonify(error="sops[%d].dept must be 1-15" % i), 400
        number = item.get("number") or ""
        if not isinstance(number, str) or len(number) > 20:
            return jsonify(
                error="sops[%d].number must be text of at most 20 characters"
                % i), 400
        title = item.get("title") or ""
        if not isinstance(title, str) or not title.strip() \
                or len(title) > 500:
            return jsonify(
                error="sops[%d].title must be non-empty text of at most"
                " 500 characters" % i), 400
        body = item.get("body") or ""
        if not isinstance(body, str) or len(body) > 200000:
            return jsonify(
                error="sops[%d].body must be text of at most 200000"
                " characters" % i), 400
        status = item.get("status") or "Live"
        if not isinstance(status, str) or not status.strip() \
                or len(status) > 200:
            return jsonify(
                error="sops[%d].status must be non-empty text of at most"
                " 200 characters" % i), 400
        try:
            position = int(item.get("position") or 0)
        except (TypeError, ValueError):
            return jsonify(error="sops[%d].position must be a number" % i), 400
        cleaned.append((dept, number.strip(), title.strip(), body,
                        status.strip(), position))
    now = datetime.now(timezone.utc).isoformat()
    conn = db()
    imported = updated = 0
    for dept, number, title, body, status, position in cleaned:
        row = conn.execute(
            "SELECT id, number, body, status, position"
            " FROM erp_quality_sops WHERE dept = ? AND title = ?",
            (dept, title)).fetchone()
        if row:
            # Wave 3 B8 (SOP 10.11): a re-import that actually
            # changes the SOP snapshots the previous body first
            # (same transaction). An unchanged re-import records
            # nothing -- the import runs after every SOP edit, and
            # identical rows are not edits.
            if (row["number"], row["body"], row["status"],
                    row["position"]) != (number, body, status, position):
                _doc_version_snapshot(conn, "sop", row["id"],
                                      row["body"], actor)
            conn.execute(
                "UPDATE erp_quality_sops SET number = ?, body = ?,"
                " status = ?, position = ?, imported_by = ?,"
                " updated_at = ? WHERE id = ?",
                (number, body, status, position, actor, now, row["id"]))
            updated += 1
        else:
            conn.execute(
                "INSERT INTO erp_quality_sops (dept, number, title, body,"
                " status, position, imported_by, created_at, updated_at)"
                " VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)",
                (dept, number, title, body, status, position, actor, now,
                 now))
            imported += 1
    pruned = 0
    if prune and cleaned:
        keep = {(dept, title) for dept, _, title, _, _, _ in cleaned}
        rows = conn.execute(
            "SELECT id, dept, title FROM erp_quality_sops").fetchall()
        for r in rows:
            if (r["dept"], r["title"]) not in keep:
                conn.execute("DELETE FROM erp_quality_sops WHERE id = ?",
                             (r["id"],))
                pruned += 1
    conn.commit()
    total = conn.execute(
        "SELECT COUNT(*) FROM erp_quality_sops").fetchone()[0]
    conn.close()
    return jsonify(imported=imported, updated=updated, pruned=pruned,
                   total=total)


@app.post("/api/erp/quality/sops/<int:sop_id>/delete")
def quality_sop_delete(sop_id):
    """Delete one SOP from the library (a retired SOP). The file stays
    the source of truth -- deleting here only removes the read copy;
    re-importing the file brings it back."""
    _, err = _require_erp_admin()
    if err:
        return err
    conn = db()
    row = conn.execute("SELECT id FROM erp_quality_sops WHERE id = ?",
                       (sop_id,)).fetchone()
    if not row:
        conn.close()
        return jsonify(error="sop not found"), 404
    conn.execute("DELETE FROM erp_quality_sops WHERE id = ?", (sop_id,))
    conn.commit()
    conn.close()
    return jsonify(deleted=sop_id)


# ---------------- Document versioning (Wave 3 B8, SOP 10.11) ----------------
# ONE generic append-only table (see the DDL comment in init_db).
# Writes are server-side only: each owning update path snapshots the
# pre-edit state into this table BEFORE the UPDATE, on the same
# connection, so the snapshot and the edit commit (or roll back)
# together. There is deliberately no write endpoint and no restore
# in v1 -- restoring a superseded legal text is a deliberate admin
# re-type, not a one-click revert. Reads are admin-only. The version
# writes themselves get no separate audit action: the owning update
# already audits (hr.document_updated, the SOP import actor, and the
# legal/HACCP updates through their existing paths); the audit log
# covers who/field, this table covers the full text.
_DOC_VERSION_TYPES = ("sop", "agreement", "haccp", "hr_document",
                     "legal_license")


def _doc_version_snapshot(conn, doc_type, doc_id, snapshot, actor):
    """Append version N (the pre-edit state) for one document, in the
    caller's transaction -- the caller commits. Returns the new
    version number. snapshot is the full text (SOP body, photo data
    URI) or a JSON object of the pre-edit text fields, serialised."""
    if not isinstance(snapshot, str):
        snapshot = json.dumps(snapshot, sort_keys=True)
    now = datetime.now(timezone.utc).isoformat()
    nxt = conn.execute(
        "SELECT COALESCE(MAX(version), 0) FROM erp_document_versions"
        " WHERE doc_type = ? AND doc_id = ?",
        (doc_type, doc_id)).fetchone()[0] + 1
    conn.execute(
        "INSERT INTO erp_document_versions (doc_type, doc_id, version,"
        " snapshot, created_by, created_at)"
        " VALUES (?, ?, ?, ?, ?, ?)",
        (doc_type, doc_id, nxt, snapshot, actor, now))
    return nxt


def _doc_version_dict(row, include_snapshot=False):
    d = {"id": row["id"], "doc_type": row["doc_type"],
         "doc_id": row["doc_id"], "version": row["version"],
         "created_by": row["created_by"],
         "created_at": row["created_at"]}
    if include_snapshot:
        d["snapshot"] = row["snapshot"]
    return d


@app.get("/api/erp/documents/versions")
def document_versions_list():
    """List the versions of one document, newest first. The snapshot
    itself is NOT returned here (it can be a 5MB photo) -- use the
    detail endpoint to read one. 400 on an unknown or missing
    doc_type, or a missing / non-numeric doc_id."""
    _, err = _require_erp_admin()
    if err:
        return err
    doc_type = (request.args.get("doc_type") or "").strip()
    if doc_type not in _DOC_VERSION_TYPES:
        return jsonify(error="doc_type must be one of: %s"
                       % ", ".join(_DOC_VERSION_TYPES)), 400
    doc_id_raw = request.args.get("doc_id")
    try:
        doc_id = int(doc_id_raw)
    except (TypeError, ValueError):
        return jsonify(error="doc_id must be a whole number"), 400
    conn = db()
    rows = conn.execute(
        "SELECT * FROM erp_document_versions WHERE doc_type = ?"
        " AND doc_id = ? ORDER BY version DESC",
        (doc_type, doc_id)).fetchall()
    conn.close()
    return jsonify(doc_type=doc_type, doc_id=doc_id,
                   versions=[_doc_version_dict(r) for r in rows],
                   total=len(rows))


@app.get("/api/erp/documents/versions/<int:version_id>")
def document_version_get(version_id):
    """One version, with its full pre-edit snapshot (text or photo)."""
    _, err = _require_erp_admin()
    if err:
        return err
    conn = db()
    row = conn.execute("SELECT * FROM erp_document_versions WHERE id = ?",
                       (version_id,)).fetchone()
    conn.close()
    if not row:
        return jsonify(error="version not found"), 404
    return jsonify(version=_doc_version_dict(row, include_snapshot=True))


# ---------------- Approval workflows beyond bill-pay (Wave 3 B9, SOP 9.33) ----------------
# Generic, multi-step approval engine. The three bespoke approvals
# (bill payment requests SOP 9.6, owner draws SOP 9.18, PTO requests)
# keep working unchanged and are NOT migrated onto this engine in v1.
# No template is seeded: with no enabled template for an object type,
# nothing is gated. The requester can never approve their own request
# (400). The gate lives in the object's own endpoint (journal post, PO
# send/email, credit-note create) -- this module only records the
# request and the decisions. Draws are already gated by their bespoke
# approve step (SOP 9.18), so no second gate is wired for them; refunds
# have no ERP commit endpoint, so there is nothing to gate yet -- both
# are still valid template object types, and an approval for one records
# the decision even though no endpoint enforces it (see SOP 9.33).
_APPROVAL_OBJECT_TYPES = ("journal", "purchase_order", "credit_note",
                          "refund", "draw")


def _approval_validate_steps(raw):
    """Validate a steps_json value. Returns (steps, None) or (None, error).

    v1: exactly one {"role": "admin", "count": 1} dict. A longer
    chain or a count > 1 is schema-ready only -- refused here until a
    second approver role exists, so nobody can set a two-approver step
    (or a second step) that one admin's decision would silently
    satisfy."""
    if raw is None:
        return [{"role": "admin", "count": 1}], None
    if isinstance(raw, str):
        try:
            raw = json.loads(raw)
        except (TypeError, ValueError):
            return None, "steps_json must be a JSON list of steps"
    if not isinstance(raw, list) or not raw:
        return None, "steps_json must be a non-empty list of steps"
    if len(raw) > 1:
        return None, ("v1 supports a single step only -- multi-step"
                      " chains are schema-ready and land with a second"
                      " approver role")
    steps = []
    for step in raw:
        if not isinstance(step, dict):
            return None, "each step must be an object with role and count"
        role = (step.get("role") or "admin").strip()
        if role != "admin":
            return None, "v1 steps only support role 'admin'"
        _raw_count = step.get("count")
        try:
            count = 1 if _raw_count is None else int(_raw_count)
        except (TypeError, ValueError):
            return None, "each step count must be a whole number"
        if count < 1:
            return None, "each step count must be at least 1"
        if count > 1:
            return None, ("count above 1 is schema-ready only in v1 --"
                          " one decision is collected per step until a"
                          " second approver role exists")
        steps.append({"role": role, "count": count})
    return steps, None


def _approval_parse_amount(raw):
    """min_amount_cents / amount_cents: None (all amounts) or int >= 0."""
    if raw is None or raw == "":
        return None, None
    try:
        value = int(raw)
    except (TypeError, ValueError):
        return None, "amount must be whole cents"
    if value < 0:
        return None, "amount cannot be negative"
    return value, None


def _approval_template_dict(row):
    try:
        steps = json.loads(row["steps_json"] or "[]")
    except ValueError:
        steps = []
    return {"id": row["id"], "object_type": row["object_type"],
            "min_amount_cents": row["min_amount_cents"],
            "steps": steps, "enabled": bool(row["enabled"]),
            "created_by": row["created_by"],
            "created_at": row["created_at"],
            "updated_by": row["updated_by"],
            "updated_at": row["updated_at"]}


def _approval_steps_for(conn, approval_id):
    rows = conn.execute(
        "SELECT * FROM erp_approval_steps WHERE approval_id = ?"
        " ORDER BY step_index",
        (approval_id,)).fetchall()
    return [{"id": r["id"], "approval_id": r["approval_id"],
             "step_index": r["step_index"], "approver": r["approver"],
             "decision": r["decision"], "decided_at": r["decided_at"],
             "note": r["note"]} for r in rows]


def _approval_dict(conn, row):
    d = {"id": row["id"], "object_type": row["object_type"],
         "object_id": row["object_id"], "template_id": row["template_id"],
         "status": row["status"], "current_step": row["current_step"],
         "created_by": row["created_by"], "created_at": row["created_at"],
         "updated_by": row["updated_by"], "updated_at": row["updated_at"],
         "steps": _approval_steps_for(conn, row["id"])}
    return d


def _approval_matching_template(conn, object_type, amount_cents=None):
    """The enabled template for this object type and amount, if any.

    NULL min_amount_cents means all amounts. When several templates
    match, the oldest wins -- templates are meant to be one per type
    (a higher-minimum template is the admin's way to scope one type)."""
    rows = conn.execute(
        "SELECT * FROM erp_approval_templates WHERE object_type = ?"
        " AND enabled = 1 ORDER BY id",
        (object_type,)).fetchall()
    for row in rows:
        minimum = row["min_amount_cents"]
        if minimum is None or amount_cents is None \
                or amount_cents >= minimum:
            return row
    return None


def _approval_pending_for(conn, object_type, object_id):
    return conn.execute(
        "SELECT * FROM erp_approvals WHERE object_type = ?"
        " AND object_id = ? AND status = 'pending' ORDER BY id",
        (object_type, object_id)).fetchone()


def _approval_gate(conn, object_type, object_id, amount_cents, actor,
                   approval_id=None):
    """Gate check for an object's own post/send/commit endpoint.

    Returns (error, approved_row): error is None when the object may
    proceed. With no enabled template for the type (and amount),
    nothing is gated. A pending approval blocks with 'awaiting
    approval'. An approved approval for this object lets it through;
    for not-yet-created objects (journal, credit note) the approved
    approval is the placeholder (object_id 0) created by the actor,
    passed as approval_id or found on its own."""
    template = _approval_matching_template(conn, object_type, amount_cents)
    if template is None:
        return None, None
    if approval_id is not None:
        try:
            approval_id = int(approval_id)
        except (TypeError, ValueError):
            approval_id = None
    if approval_id is not None:
        row = conn.execute(
            "SELECT * FROM erp_approvals WHERE id = ?",
            (approval_id,)).fetchone()
        if row and row["object_type"] == object_type \
                and row["status"] == "approved" \
                and (row["object_id"] == object_id
                     or row["object_id"] == 0) \
                and (object_id != 0 or row["created_by"] == actor):
            return None, row
    pending = _approval_pending_for(conn, object_type, object_id)
    if pending:
        return ("awaiting approval (approval #%d, requested by %s) --"
                " the other admin must decide it first"
                % (pending["id"], pending["created_by"] or "an admin")), None
    if object_id == 0:
        approved = conn.execute(
            "SELECT * FROM erp_approvals WHERE object_type = ?"
            " AND object_id = 0 AND status = 'approved'"
            " AND created_by = ? ORDER BY id",
            (object_type, actor or "")).fetchone()
    else:
        approved = conn.execute(
            "SELECT * FROM erp_approvals WHERE object_type = ?"
            " AND object_id = ? AND status = 'approved' ORDER BY id",
            (object_type, object_id)).fetchone()
    if approved:
        return None, approved
    return ("approval required: an enabled approval template covers"
            " %s -- request approval first" % object_type), None


def _approval_consume_placeholder(conn, approved_row, new_object_id):
    """Link a consumed placeholder approval (object_id 0) to the object
    it just approved, so it cannot approve a second posting."""
    if approved_row and approved_row["object_id"] == 0:
        conn.execute(
            "UPDATE erp_approvals SET object_id = ? WHERE id = ?",
            (new_object_id, approved_row["id"]))


@app.get("/api/erp/approvals/templates")
def approval_templates_list():
    """List approval templates (admin-only). Starts empty -- nothing is
    gated until an admin creates one."""
    _, err = _require_erp_admin()
    if err:
        return err
    conn = db()
    rows = conn.execute(
        "SELECT * FROM erp_approval_templates ORDER BY id").fetchall()
    conn.close()
    return jsonify(templates=[_approval_template_dict(r) for r in rows],
                   total=len(rows))


@app.post("/api/erp/approvals/templates")
def approval_template_create():
    """Create an approval template. 400 on an unknown object_type, a
    bad amount, or bad steps."""
    actor, err = _require_erp_admin()
    if err:
        return err
    data = request.get_json(force=True) or {}
    object_type = (data.get("object_type") or "").strip()
    if object_type not in _APPROVAL_OBJECT_TYPES:
        return jsonify(error="object_type must be one of: %s"
                       % ", ".join(_APPROVAL_OBJECT_TYPES)), 400
    minimum, amount_error = _approval_parse_amount(
        data.get("min_amount_cents"))
    if amount_error:
        return jsonify(error="min_amount_cents: %s" % amount_error), 400
    steps, steps_error = _approval_validate_steps(data.get("steps_json"))
    if steps_error:
        return jsonify(error=steps_error), 400
    enabled = data.get("enabled")
    enabled = 1 if enabled is None else (1 if enabled else 0)
    now = datetime.now(timezone.utc).isoformat()
    conn = db()
    cur = conn.execute(
        "INSERT INTO erp_approval_templates (object_type,"
        " min_amount_cents, steps_json, enabled, created_by, created_at,"
        " updated_by, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?)",
        (object_type, minimum, json.dumps(steps), enabled, actor or "",
         now, actor or "", now))
    template_id = cur.lastrowid
    _erp_staff_audit(conn, actor, "approvals.template_created",
                     "approval_template", template_id,
                     "%s min %s, %d step(s), enabled %d"
                     % (object_type, minimum, len(steps), enabled))
    conn.commit()
    row = conn.execute(
        "SELECT * FROM erp_approval_templates WHERE id = ?",
        (template_id,)).fetchone()
    conn.close()
    return jsonify(template=_approval_template_dict(row)), 201


@app.post("/api/erp/approvals/templates/<int:template_id>/update")
def approval_template_update(template_id):
    """Edit a template (object_type, minimum, steps, enabled)."""
    actor, err = _require_erp_admin()
    if err:
        return err
    data = request.get_json(force=True) or {}
    conn = db()
    row = conn.execute(
        "SELECT * FROM erp_approval_templates WHERE id = ?",
        (template_id,)).fetchone()
    if not row:
        conn.close()
        return jsonify(error="template not found"), 404
    object_type = row["object_type"]
    if "object_type" in data:
        object_type = (data.get("object_type") or "").strip()
        if object_type not in _APPROVAL_OBJECT_TYPES:
            conn.close()
            return jsonify(error="object_type must be one of: %s"
                           % ", ".join(_APPROVAL_OBJECT_TYPES)), 400
    minimum = row["min_amount_cents"]
    if "min_amount_cents" in data:
        minimum, amount_error = _approval_parse_amount(
            data.get("min_amount_cents"))
        if amount_error:
            conn.close()
            return jsonify(error="min_amount_cents: %s" % amount_error), 400
    steps = json.loads(row["steps_json"] or "[]")
    if "steps_json" in data:
        steps, steps_error = _approval_validate_steps(
            data.get("steps_json"))
        if steps_error:
            conn.close()
            return jsonify(error=steps_error), 400
    enabled = row["enabled"]
    if "enabled" in data:
        enabled = 1 if data.get("enabled") else 0
    now = datetime.now(timezone.utc).isoformat()
    conn.execute(
        "UPDATE erp_approval_templates SET object_type = ?,"
        " min_amount_cents = ?, steps_json = ?, enabled = ?,"
        " updated_by = ?, updated_at = ? WHERE id = ?",
        (object_type, minimum, json.dumps(steps), enabled, actor or "",
         now, template_id))
    _erp_staff_audit(conn, actor, "approvals.template_updated",
                     "approval_template", template_id,
                     "%s min %s, %d step(s), enabled %d"
                     % (object_type, minimum, len(steps), enabled))
    conn.commit()
    row = conn.execute(
        "SELECT * FROM erp_approval_templates WHERE id = ?",
        (template_id,)).fetchone()
    conn.close()
    return jsonify(template=_approval_template_dict(row))


@app.delete("/api/erp/approvals/templates/<int:template_id>")
def approval_template_delete(template_id):
    """Delete a template permanently (two-tap in the UI). Refused with
    409 while any approval references it -- deleting would orphan the
    record of what was decided under it."""
    actor, err = _require_erp_admin()
    if err:
        return err
    conn = db()
    row = conn.execute(
        "SELECT * FROM erp_approval_templates WHERE id = ?",
        (template_id,)).fetchone()
    if not row:
        conn.close()
        return jsonify(error="template not found"), 404
    refs = conn.execute(
        "SELECT COUNT(*) AS c FROM erp_approvals WHERE template_id = ?",
        (template_id,)).fetchone()["c"]
    if refs:
        conn.close()
        return jsonify(error="template has %d approval(s) and cannot be"
                       " deleted" % refs), 409
    conn.execute(
        "DELETE FROM erp_approval_templates WHERE id = ?", (template_id,))
    _erp_staff_audit(conn, actor, "approvals.template_deleted",
                     "approval_template", template_id,
                     "%s min %s" % (row["object_type"],
                                     row["min_amount_cents"]))
    conn.commit()
    conn.close()
    return jsonify(ok=True, deleted=template_id)


@app.get("/api/erp/approvals")
def approvals_list():
    """Approval inbox: pending by default; ?status= filters (pending /
    approved / rejected), ?object_type= narrows to one object type."""
    _, err = _require_erp_admin()
    if err:
        return err
    status = (request.args.get("status") or "").strip()
    object_type = (request.args.get("object_type") or "").strip()
    if status and status not in ("pending", "approved", "rejected"):
        return jsonify(error="status must be pending, approved or"
                       " rejected"), 400
    if object_type and object_type not in _APPROVAL_OBJECT_TYPES:
        return jsonify(error="object_type must be one of: %s"
                       % ", ".join(_APPROVAL_OBJECT_TYPES)), 400
    conn = db()
    where = []
    params = []
    if status:
        where.append("status = ?")
        params.append(status)
    if object_type:
        where.append("object_type = ?")
        params.append(object_type)
    query = "SELECT * FROM erp_approvals"
    if where:
        query += " WHERE " + " AND ".join(where)
    query += " ORDER BY id DESC"
    rows = conn.execute(query, params).fetchall()
    out = [_approval_dict(conn, r) for r in rows]
    conn.close()
    return jsonify(approvals=out, total=len(out))


@app.post("/api/erp/approvals")
def approval_request():
    """Request approval for one object. Journals and credit notes do
    not exist until they post, so they are requested with object_id 0
    (or omitted) and linked when the post/create consumes the
    approval. A second pending approval for the same object is refused
    (409). The requester can never approve their own request."""
    actor, err = _require_erp_admin()
    if err:
        return err
    data = request.get_json(force=True) or {}
    object_type = (data.get("object_type") or "").strip()
    if object_type not in _APPROVAL_OBJECT_TYPES:
        return jsonify(error="object_type must be one of: %s"
                       % ", ".join(_APPROVAL_OBJECT_TYPES)), 400
    try:
        object_id = int(data.get("object_id") or 0)
    except (TypeError, ValueError):
        return jsonify(error="object_id must be a whole number"), 400
    amount, amount_error = _approval_parse_amount(data.get("amount_cents"))
    if amount_error:
        return jsonify(error="amount_cents: %s" % amount_error), 400
    note = (data.get("note") or "").strip()
    conn = db()
    # The object must exist (except journals / credit notes, which are
    # requested before they exist, and refunds, which have no ERP
    # object table yet -- an approval for one records the decision).
    if object_type == "journal":
        if object_id != 0:
            conn.close()
            return jsonify(error="a journal is requested for approval"
                           " before it posts, with object_id 0"), 400
    elif object_type == "credit_note":
        if object_id != 0:
            conn.close()
            return jsonify(error="a credit note is requested for"
                           " approval before it is created, with"
                           " object_id 0"), 400
    elif object_type == "purchase_order":
        po = conn.execute(
            "SELECT * FROM erp_purchase_orders WHERE id = ?",
            (object_id,)).fetchone()
        if not po:
            conn.close()
            return jsonify(error="purchase order not found"), 404
        if po["status"] != "draft":
            conn.close()
            return jsonify(error="only a draft purchase order can be"
                           " sent for approval (status: %s)"
                           % po["status"]), 400
    elif object_type == "draw":
        draw = conn.execute(
            "SELECT * FROM erp_acct_draws WHERE id = ?", (object_id,)).fetchone()
        if not draw:
            conn.close()
            return jsonify(error="draw not found"), 404
    # Refund: no ERP object table yet -- object_id is recorded as given.
    template = None
    template_id = data.get("template_id")
    if template_id is not None:
        try:
            template_id = int(template_id)
        except (TypeError, ValueError):
            conn.close()
            return jsonify(error="template_id must be a whole number"), 400
        template = conn.execute(
            "SELECT * FROM erp_approval_templates WHERE id = ?",
            (template_id,)).fetchone()
        if not template:
            conn.close()
            return jsonify(error="template not found"), 404
        if template["object_type"] != object_type:
            conn.close()
            return jsonify(error="template is for %s, not %s"
                           % (template["object_type"], object_type)), 400
        if not template["enabled"]:
            conn.close()
            return jsonify(error="template is disabled"), 400
    else:
        template = _approval_matching_template(conn, object_type, amount)
        if template is None:
            conn.close()
            return jsonify(error="no enabled approval template covers"
                           " %s" % object_type), 400
        template_id = template["id"]
    if _approval_pending_for(conn, object_type, object_id):
        conn.close()
        return jsonify(error="a pending approval already exists for"
                       " this %s" % object_type), 409
    try:
        steps = json.loads(template["steps_json"] or "[]")
    except ValueError:
        steps = [{"role": "admin", "count": 1}]
    if not steps:
        steps = [{"role": "admin", "count": 1}]
    now = datetime.now(timezone.utc).isoformat()
    cur = conn.execute(
        "INSERT INTO erp_approvals (object_type, object_id, template_id,"
        " status, current_step, created_by, created_at, updated_by,"
        " updated_at) VALUES (?, ?, ?, 'pending', 0, ?, ?, ?, ?)",
        (object_type, object_id, template_id, actor or "", now,
         actor or "", now))
    approval_id = cur.lastrowid
    for idx, _step in enumerate(steps):
        conn.execute(
            "INSERT INTO erp_approval_steps (approval_id, step_index,"
            " approver, decision, decided_at, note)"
            " VALUES (?, ?, '', '', '', ?)",
            (approval_id, idx, note if idx == 0 else ""))
    _erp_staff_audit(conn, actor, "approvals.requested", "approval",
                     approval_id,
                     "%s #%d under template #%d%s"
                     % (object_type, object_id, template_id,
                        (" -- " + note) if note else ""))
    conn.commit()
    row = conn.execute(
        "SELECT * FROM erp_approvals WHERE id = ?", (approval_id,)).fetchone()
    out = _approval_dict(conn, row)
    conn.close()
    return jsonify(approval=out), 201


@app.get("/api/erp/approvals/<int:approval_id>")
def approval_get(approval_id):
    """One approval with its steps."""
    _, err = _require_erp_admin()
    if err:
        return err
    conn = db()
    row = conn.execute(
        "SELECT * FROM erp_approvals WHERE id = ?", (approval_id,)).fetchone()
    if not row:
        conn.close()
        return jsonify(error="approval not found"), 404
    out = _approval_dict(conn, row)
    conn.close()
    return jsonify(approval=out)


def _approval_decide(approval_id, actor, decision):
    """Shared approve/reject: 404 missing, 409 already decided, 400
    when the requester tries to decide their own request. Approving
    the last step approves the whole request; otherwise the next step
    opens. Rejecting ends it at once. (v1 templates hold exactly one
    step, so the advance branch is the future multi-step path.)"""
    data = request.get_json(force=True) or {}
    note = (data.get("note") or "").strip()
    conn = db()
    row = conn.execute(
        "SELECT * FROM erp_approvals WHERE id = ?", (approval_id,)).fetchone()
    if not row:
        conn.close()
        return (jsonify(error="approval not found"), 404), None
    if row["status"] != "pending":
        conn.close()
        return (jsonify(error="approval was already decided (%s)"
                       % row["status"]), 409), None
    if (actor or "") == (row["created_by"] or ""):
        conn.close()
        return (jsonify(error="you cannot %s your own request -- the"
                       " other admin must decide it"
                       % ("approve" if decision == "approved"
                          else "reject")), 400), None
    steps = _approval_steps_for(conn, approval_id)
    current = row["current_step"]
    if current < 0 or current >= len(steps):
        conn.close()
        return (jsonify(error="approval has no open step"), 409), None
    step = steps[current]
    now = datetime.now(timezone.utc).isoformat()
    conn.execute(
        "UPDATE erp_approval_steps SET approver = ?, decision = ?,"
        " decided_at = ?, note = ? WHERE id = ?",
        (actor or "", decision, now, note, step["id"]))
    if decision == "rejected":
        new_status = "rejected"
        new_step = current
    elif current + 1 >= len(steps):
        new_status = "approved"
        new_step = current
    else:
        new_status = "pending"
        new_step = current + 1
    conn.execute(
        "UPDATE erp_approvals SET status = ?, current_step = ?,"
        " updated_by = ?, updated_at = ? WHERE id = ?",
        (new_status, new_step, actor or "", now, approval_id))
    _erp_staff_audit(conn, actor,
                     "approvals.approved" if decision == "approved"
                     else "approvals.rejected",
                     "approval", approval_id,
                     "%s #%d step %d of %d by %s%s"
                     % (row["object_type"], row["object_id"], current + 1,
                        len(steps), actor or "",
                        (" -- " + note) if note else ""))
    conn.commit()
    row = conn.execute(
        "SELECT * FROM erp_approvals WHERE id = ?", (approval_id,)).fetchone()
    out = _approval_dict(conn, row)
    conn.close()
    return (jsonify(approval=out), 200), out


@app.post("/api/erp/approvals/<int:approval_id>/approve")
def approval_approve(approval_id):
    """Decide the current step: approve. 400 self-approval, 409
    already decided."""
    actor, err = _require_erp_admin()
    if err:
        return err
    resp, _out = _approval_decide(approval_id, actor, "approved")
    return resp


@app.post("/api/erp/approvals/<int:approval_id>/reject")
def approval_reject(approval_id):
    """Decide the current step: reject. 400 self-rejection, 409
    already decided."""
    actor, err = _require_erp_admin()
    if err:
        return err
    resp, _out = _approval_decide(approval_id, actor, "rejected")
    return resp


# ---------------- Data retention / archival (Wave 3 B10, SOP 10.12) ----------------
# Policy first, execution second, dry-run first always. No periods are
# seeded and no policy is created by this module: with no policy,
# nothing is ever archived or deleted. One policy per data type.
# 'archive' copies eligible rows into a dated archive export zip
# (manifest.json + rows.json, the same shape as the backup export,
# SOP 9.25) stored on the run row -- and removes nothing. 'delete'
# removes eligible rows permanently, and is refused (409) unless an
# earlier archive run for the same policy already covers the cutoff,
# so a delete can never run ahead of its archive. Audit logs and the
# backup-export records are archive-only (they are the record);
# legal/quality are not data types at all. Eligibility is narrow by
# design: only resolved/closed tickets (with their replies), only
# matched bank-feed rows, newsletter events by date. The backup zip
# files themselves are never touched here -- the nightly job prunes
# them on its own approved rule (SOP 9.25). Dry runs return counts,
# delete nothing, and record nothing; a second call with
# confirm=true executes (the two-call pattern mirrors the period-lock
# confirm_unreconciled). All writes are admin-only and audited.
_RETENTION_DATA_TYPES = ("backup", "audit_log", "ticket", "bank_feed",
                         "marketing_log")
_RETENTION_ACTIONS = ("archive", "delete")
_RETENTION_ARCHIVE_ONLY = ("backup", "audit_log")
_RETENTION_TYPE_LABELS = {
    "backup": "Backup-export records",
    "audit_log": "Audit logs",
    "ticket": "Support tickets",
    "bank_feed": "Bank-feed rows",
    "marketing_log": "Newsletter events",
}
# (table, date column, extra WHERE) per data type, in archive order.
# audit_log spans all five audit tables; ticket carries its replies
# as a second table (deleted with the ticket -- the one stated
# cascade). Table names here are fixed internals, never user input.
_RETENTION_AUDIT_TABLES = ("erp_settings_audit", "erp_staff_audit",
                           "erp_acct_audit", "erp_mkt_audit",
                           "erp_audit_changes")


def _retention_cutoff(retain_days):
    """Cutoff date (YYYY-MM-DD, UTC): today minus the retain days. A
    row is eligible when its date is before this date."""
    return (datetime.now(timezone.utc).date()
            - timedelta(days=int(retain_days))).isoformat()


def _retention_row_sets(conn, data_type, cutoff_date):
    """{table: [rows]} of eligible rows for one data type at one
    cutoff, ordered by id. Eligibility is the narrow rule in
    SOP 10.12 -- open tickets and unmatched/review bank rows are
    live work and never appear here."""
    out = {}
    if data_type == "backup":
        # The backup-export manifest records only: the audit rows
        # that say a backup was taken. The zip files themselves live
        # outside the ERP and are pruned by the nightly job (SOP 9.25).
        out["erp_acct_audit"] = conn.execute(
            "SELECT * FROM erp_acct_audit WHERE action = 'backup.export'"
            " AND substr(created_at, 1, 10) < ? ORDER BY id",
            (cutoff_date,)).fetchall()
    elif data_type == "audit_log":
        for table in _RETENTION_AUDIT_TABLES:
            out[table] = conn.execute(
                "SELECT * FROM %s WHERE substr(created_at, 1, 10) < ?"
                " ORDER BY id" % table, (cutoff_date,)).fetchall()
    elif data_type == "ticket":
        tickets = conn.execute(
            "SELECT * FROM erp_mkt_tickets"
            " WHERE status IN ('resolved', 'closed')"
            " AND substr(created_at, 1, 10) < ? ORDER BY id",
            (cutoff_date,)).fetchall()
        out["erp_mkt_tickets"] = tickets
        ids = [r["id"] for r in tickets]
        if ids:
            q = ",".join("?" * len(ids))
            out["erp_mkt_ticket_replies"] = conn.execute(
                "SELECT * FROM erp_mkt_ticket_replies WHERE ticket_id"
                " IN (%s) ORDER BY id" % q, ids).fetchall()
        else:
            out["erp_mkt_ticket_replies"] = []
    elif data_type == "bank_feed":
        out["erp_acct_bank_txns"] = conn.execute(
            "SELECT * FROM erp_acct_bank_txns WHERE status = 'matched'"
            " AND substr(date, 1, 10) < ? ORDER BY id",
            (cutoff_date,)).fetchall()
    elif data_type == "marketing_log":
        out["erp_mkt_newsletter_events"] = conn.execute(
            "SELECT * FROM erp_mkt_newsletter_events"
            " WHERE substr(received_at, 1, 10) < ? ORDER BY id",
            (cutoff_date,)).fetchall()
    return out


def _retention_build_archive(policy, cutoff_date, row_sets, ran_at):
    """Build the dated archive export zip for one run. Same shape as
    the backup export (SOP 9.25): a manifest.json (manifest id,
    date, policy, data type, cutoff, per-table row counts with a
    SHA-256) plus the archived rows. Returns (filename, zip bytes,
    sha256)."""
    stamp = datetime.now(timezone.utc).strftime("%Y-%m-%dT%H%M%SZ")
    tables = {}
    payload = {}
    total = 0
    for table, rows in row_sets.items():
        dicts = [dict(r) for r in rows]
        payload[table] = dicts
        blob = json.dumps(dicts, sort_keys=True).encode("utf-8")
        tables[table] = {"rows": len(dicts),
                         "sha256": hashlib.sha256(blob).hexdigest()}
        total += len(dicts)
    manifest = {
        "manifest_id": "retention-%s-%s" % (stamp, policy["id"]),
        "created_at_utc": ran_at,
        "source": "erp.pop-a-licious.com",
        "kind": "retention-archive",
        "policy_id": policy["id"],
        "data_type": policy["data_type"],
        "action": policy["action"],
        "retain_days": policy["retain_days"],
        "cutoff_date": cutoff_date,
        "tables": tables,
        "total_rows": total,
    }
    buf = io.BytesIO()
    with zipfile.ZipFile(buf, "w", zipfile.ZIP_DEFLATED) as zf:
        zf.writestr("manifest.json", json.dumps(manifest, indent=2))
        zf.writestr("rows.json",
                    json.dumps(payload, indent=2, sort_keys=True))
    zip_bytes = buf.getvalue()
    filename = ("retention-%s-%s-%s.zip"
                % (policy["data_type"], cutoff_date, stamp))
    return filename, zip_bytes, hashlib.sha256(zip_bytes).hexdigest()


def _retention_covering_archive(conn, policy_id, cutoff_date):
    """Latest prior run for this policy that archived rows with a
    cutoff_date on or after this run's cutoff_date -- i.e. every row
    this run could delete is already in that archive. Returns the
    run row or None."""
    return conn.execute(
        "SELECT * FROM erp_retention_runs WHERE policy_id = ?"
        " AND rows_archived > 0 AND cutoff_date >= ?"
        " ORDER BY id DESC LIMIT 1",
        (policy_id, cutoff_date)).fetchone()


def _retention_delete_rows(conn, data_type, row_sets):
    """Delete the eligible rows; replies before tickets (children
    first). Returns the count deleted. Table names come from the
    fixed row-set map, never from user input."""
    order = ["erp_mkt_ticket_replies", "erp_mkt_tickets",
             "erp_acct_bank_txns", "erp_mkt_newsletter_events"]
    total = 0
    for table in order:
        for row in row_sets.get(table) or []:
            conn.execute("DELETE FROM %s WHERE id = ?" % table,
                         (row["id"],))
            total += 1
    return total


def _retention_parse_policy(data, current=None):
    """Validate a policy create (current=None) or update (current is
    the existing row; data_type is immutable). Returns (fields, None)
    or (None, error). retain_days is admin-entered and > 0, never
    defaulted; 'delete' on an archive-only type is refused."""
    if current is None:
        data_type = (data.get("data_type") or "").strip()
        if data_type not in _RETENTION_DATA_TYPES:
            return None, ("data_type must be one of: %s"
                          % ", ".join(_RETENTION_DATA_TYPES))
    else:
        data_type = current["data_type"]
    retain_days = current["retain_days"] if current is not None else None
    if current is None or "retain_days" in data:
        raw = data.get("retain_days")
        if isinstance(raw, bool):
            return None, "retain_days must be a whole number above 0"
        try:
            retain_days = int(raw)
        except (TypeError, ValueError):
            return None, "retain_days must be a whole number above 0"
        if retain_days <= 0 or str(raw).strip() != str(retain_days):
            return None, "retain_days must be a whole number above 0"
    action = current["action"] if current is not None else "archive"
    if "action" in data:
        action = (data.get("action") or "").strip()
        if action not in _RETENTION_ACTIONS:
            return None, "action must be archive or delete"
    if action == "delete" and data_type in _RETENTION_ARCHIVE_ONLY:
        return None, ("%s can only be archived, never deleted"
                      % data_type)
    enabled = current["enabled"] if current is not None else 1
    if "enabled" in data:
        enabled = 1 if data.get("enabled") else 0
    return {"data_type": data_type, "retain_days": retain_days,
            "action": action, "enabled": enabled}, None


def _retention_policy_dict(row):
    return {"id": row["id"], "data_type": row["data_type"],
            "type_label": _RETENTION_TYPE_LABELS.get(row["data_type"],
                                                     row["data_type"]),
            "retain_days": row["retain_days"],
            "action": row["action"],
            "enabled": bool(row["enabled"]),
            "created_by": row["created_by"],
            "created_at": row["created_at"],
            "updated_by": row["updated_by"],
            "updated_at": row["updated_at"]}


def _retention_run_dict(row):
    return {"id": row["id"], "policy_id": row["policy_id"],
            "data_type": row["data_type"], "action": row["action"],
            "cutoff_date": row["cutoff_date"], "ran_at": row["ran_at"],
            "ran_by": row["ran_by"],
            "rows_archived": row["rows_archived"],
            "rows_deleted": row["rows_deleted"],
            "note": row["note"],
            "archive_filename": row["archive_filename"],
            "archive_sha256": row["archive_sha256"],
            "has_archive": bool(row["archive_zip_b64"]),
            "prior_archive_run_id": row["prior_archive_run_id"]}


@app.get("/api/erp/settings/retention-policies")
def retention_policies_list():
    """List retention policies (admin-only). Starts empty -- with no
    policy, nothing is ever archived or deleted."""
    _, err = _require_erp_admin()
    if err:
        return err
    conn = db()
    rows = conn.execute(
        "SELECT * FROM erp_retention_policies ORDER BY id").fetchall()
    conn.close()
    return jsonify(policies=[_retention_policy_dict(r) for r in rows],
                   total=len(rows))


@app.post("/api/erp/settings/retention-policies")
def retention_policy_create():
    """Create a retention policy. 400 on an unknown data_type, a bad
    retain_days, or 'delete' on an archive-only type; 409 when a
    policy already exists for that data type."""
    actor, err = _require_erp_admin()
    if err:
        return err
    data = request.get_json(force=True) or {}
    fields, error = _retention_parse_policy(data)
    if error:
        return jsonify(error=error), 400
    conn = db()
    existing = conn.execute(
        "SELECT id FROM erp_retention_policies WHERE data_type = ?",
        (fields["data_type"],)).fetchone()
    if existing:
        conn.close()
        return jsonify(error="a policy already exists for this"
                       " data type"), 409
    now = datetime.now(timezone.utc).isoformat()
    cur = conn.execute(
        "INSERT INTO erp_retention_policies (data_type, retain_days,"
        " action, enabled, created_by, created_at, updated_by,"
        " updated_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?)",
        (fields["data_type"], fields["retain_days"], fields["action"],
         fields["enabled"], actor or "", now, actor or "", now))
    policy_id = cur.lastrowid
    _erp_staff_audit(conn, actor, "settings.retention_policy_created",
                     "retention_policy", policy_id,
                     "%s retain %d days, action %s, enabled %d"
                     % (fields["data_type"], fields["retain_days"],
                        fields["action"], fields["enabled"]))
    conn.commit()
    row = conn.execute(
        "SELECT * FROM erp_retention_policies WHERE id = ?",
        (policy_id,)).fetchone()
    conn.close()
    return jsonify(policy=_retention_policy_dict(row)), 201


@app.post("/api/erp/settings/retention-policies/<int:policy_id>/update")
def retention_policy_update(policy_id):
    """Edit a policy (retain_days, action, enabled). The data type
    never changes after creation."""
    actor, err = _require_erp_admin()
    if err:
        return err
    data = request.get_json(force=True) or {}
    conn = db()
    row = conn.execute(
        "SELECT * FROM erp_retention_policies WHERE id = ?",
        (policy_id,)).fetchone()
    if not row:
        conn.close()
        return jsonify(error="policy not found"), 404
    fields, error = _retention_parse_policy(data, current=row)
    if error:
        conn.close()
        return jsonify(error=error), 400
    now = datetime.now(timezone.utc).isoformat()
    conn.execute(
        "UPDATE erp_retention_policies SET retain_days = ?,"
        " action = ?, enabled = ?, updated_by = ?, updated_at = ?"
        " WHERE id = ?",
        (fields["retain_days"], fields["action"], fields["enabled"],
         actor or "", now, policy_id))
    _erp_staff_audit(conn, actor, "settings.retention_policy_updated",
                     "retention_policy", policy_id,
                     "%s retain %d days, action %s, enabled %d"
                     % (fields["data_type"], fields["retain_days"],
                        fields["action"], fields["enabled"]))
    conn.commit()
    row = conn.execute(
        "SELECT * FROM erp_retention_policies WHERE id = ?",
        (policy_id,)).fetchone()
    conn.close()
    return jsonify(policy=_retention_policy_dict(row))


