@app.get("/api/erp/settings/retention-runs")
def retention_runs_list():
    """Run history, newest first (admin-only). The archive zip
    itself is never in this payload -- use the per-run download
    endpoint. ?policy_id= narrows to one policy."""
    _, err = _require_erp_admin()
    if err:
        return err
    policy_raw = request.args.get("policy_id")
    conn = db()
    if policy_raw is not None:
        try:
            policy_id = int(policy_raw)
        except (TypeError, ValueError):
            conn.close()
            return jsonify(error="policy_id must be a whole number"), 400
        rows = conn.execute(
            "SELECT * FROM erp_retention_runs WHERE policy_id = ?"
            " ORDER BY id DESC", (policy_id,)).fetchall()
