@app.post("/api/erp/settings/webhooks")
def webhook_sub_create():
    """Create a webhook subscription. 400 on a non-https URL, a URL
    whose host fails the SSRF guard, or an unknown event. The raw
    signing secret is returned ONCE in this response and never again."""
    actor, err = _require_erp_admin()
    if err:
        return err
    data = request.get_json(force=True) or {}
    url = (data.get("url") or "").strip()
    url_error = _api_webhook_validate_url(url)
    if url_error:
        return jsonify(error=url_error), 400
    events, error = _api_webhook_parse_events(data)
    if error:
        return jsonify(error=error), 400
    enabled = data.get("enabled", 1)
    enabled = 1 if enabled not in (0, False, "0", "false") else 0
    secret = secrets.token_urlsafe(32)
    now = datetime.now(timezone.utc).isoformat()
    conn = db()
    cur = conn.execute(
        "INSERT INTO erp_webhook_subscriptions (url, events, secret,"
        " enabled, created_by, created_at, updated_by, updated_at)"
        " VALUES (?, ?, ?, ?, ?, ?, ?, ?)",
        (url, ",".join(events), _api_key_hash(secret), enabled,
         actor or "", now, actor or "", now))
    sub_id = cur.lastrowid
    _erp_staff_audit(conn, actor, "settings.webhook_created",
                     "webhook_subscription", sub_id,
                     "%s events %s" % (url, ", ".join(events)))
    conn.commit()
    row = conn.execute(
        "SELECT * FROM erp_webhook_subscriptions WHERE id = ?",
        (sub_id,)).fetchone()
    conn.close()
    out = _webhook_sub_dict(row)
    out["secret"] = secret
    return jsonify(subscription=out), 201


@app.post("/api/erp/settings/webhooks/<int:sub_id>/update")
def webhook_sub_update(sub_id):
    """Edit a subscription (URL, events, enabled). The signing secret
    never changes here -- rotate it with /rotate-secret. 400 on a
    non-https URL, a URL whose host fails the SSRF guard, or an
    unknown event."""
    actor, err = _require_erp_admin()
    if err:
        return err
    data = request.get_json(force=True) or {}
    conn = db()
    row = conn.execute(
        "SELECT * FROM erp_webhook_subscriptions WHERE id = ?",
        (sub_id,)).fetchone()
    if not row:
        conn.close()
        return jsonify(error="webhook subscription not found"), 404
    url = row["url"]
    if "url" in data:
        url = (data.get("url") or "").strip()
        url_error = _api_webhook_validate_url(url)
        if url_error:
            conn.close()
            return jsonify(error=url_error), 400
    events, error = _api_webhook_parse_events(data, current=row)
    if error:
        conn.close()
        return jsonify(error=error), 400
    enabled = data.get("enabled", row["enabled"])
    enabled = 1 if enabled not in (0, False, "0", "false") else 0
    now = datetime.now(timezone.utc).isoformat()
    conn.execute(
        "UPDATE erp_webhook_subscriptions SET url = ?, events = ?,"
        " enabled = ?, updated_by = ?, updated_at = ? WHERE id = ?",
        (url, ",".join(events), enabled, actor or "", now, sub_id))
    _erp_staff_audit(conn, actor, "settings.webhook_updated",
                     "webhook_subscription", sub_id,
                     "%s events %s enabled %d"
                     % (url, ", ".join(events), enabled))
    conn.commit()
    row = conn.execute(
        "SELECT * FROM erp_webhook_subscriptions WHERE id = ?",
        (sub_id,)).fetchone()
    conn.close()
    return jsonify(subscription=_webhook_sub_dict(row))


@app.post("/api/erp/settings/webhooks/<int:sub_id>/rotate-secret")
def webhook_sub_rotate_secret(sub_id):
    """Rotate a subscription's signing secret: the old secret stops
    verifying immediately, the new raw secret is returned once.
    Receivers must update the secret on their side at the same time."""
    actor, err = _require_erp_admin()
    if err:
        return err
    conn = db()
    row = conn.execute(
        "SELECT * FROM erp_webhook_subscriptions WHERE id = ?",
        (sub_id,)).fetchone()
    if not row:
        conn.close()
        return jsonify(error="webhook subscription not found"), 404
    secret = secrets.token_urlsafe(32)
    now = datetime.now(timezone.utc).isoformat()
    conn.execute(
        "UPDATE erp_webhook_subscriptions SET secret = ?,"
        " updated_by = ?, updated_at = ? WHERE id = ?",
        (_api_key_hash(secret), actor or "", now, sub_id))
    _erp_staff_audit(conn, actor, "settings.webhook_secret_rotated",
                     "webhook_subscription", sub_id,
                     "%s secret rotated" % row["url"])
    conn.commit()
    row = conn.execute(
        "SELECT * FROM erp_webhook_subscriptions WHERE id = ?",
        (sub_id,)).fetchone()
    conn.close()
    out = _webhook_sub_dict(row)
    out["secret"] = secret
    return jsonify(subscription=out)


