@app.get("/api/erp/external/inventory")
def external_inventory():
    """Read-only inventory for external callers (key auth, scope
    inventory.read). On-hand is computed live from the stock ledger
    (sum of qty_change), never stored."""
    _, err = _api_key_auth("inventory.read", "external.inventory_list")
    if err:
        return err
    conn = db()
    rows = conn.execute(
        "SELECT i.id, i.sku, i.name, i.type, i.active,"
        " COALESCE(SUM(l.qty_change), 0) AS on_hand"
        " FROM erp_items i LEFT JOIN erp_stock_ledger l"
        " ON l.item_id = i.id GROUP BY i.id ORDER BY i.name").fetchall()
    conn.close()
    items = []
    for r in rows:
        on_hand = r["on_hand"] or 0
        if isinstance(on_hand, float) and on_hand.is_integer():
            on_hand = int(on_hand)
        items.append({"id": r["id"], "sku": r["sku"], "name": r["name"],
                      "type": r["type"], "active": bool(r["active"]),
                      "on_hand": on_hand})
    return jsonify(items=items, total=len(items))


