def _capa_dict(conn, row, nested=False):
    """One CAPA row + derived counts; nested=True adds its actions."""
    d = dict(row)
    d["source_label"] = _CAPA_SOURCE_LABELS.get(row["source_type"],
                                                row["source_type"])
    if nested:
        actions = conn.execute(
            "SELECT * FROM erp_quality_capa_actions WHERE capa_id = ?"
            " ORDER BY due_date, id", (row["id"],)).fetchall()
        d["actions"] = [dict(a) for a in actions]
        d["action_count"] = len(actions)
        d["open_actions"] = sum(1 for a in actions
                                if a["status"] == "open")
    else:
        d["action_count"] = int(conn.execute(
            "SELECT COUNT(*) FROM erp_quality_capa_actions"
            " WHERE capa_id = ?", (row["id"],)).fetchone()[0])
        d["open_actions"] = int(conn.execute(
            "SELECT COUNT(*) FROM erp_quality_capa_actions"
            " WHERE capa_id = ? AND status = 'open'",
            (row["id"],)).fetchone()[0])
    return d


def _capa_valid_source_id(value):
    """source_id is an int or blank (NULL). Returns (int|None, error)."""
    if value is None or value == "":
        return None, None
    try:
        return int(value), None
    except (TypeError, ValueError):
        return None, "source_id must be an integer"


@app.get("/api/erp/quality/capas")
def quality_capas_list():
    """All CAPAs, newest first, with action counts. Filters: status=,
    source_type=. Starts empty; nothing is auto-created."""
    _, err = _require_erp_admin()
    if err:
        return err
    conn = db()
    status = (request.args.get("status") or "").strip().lower()
    if status and status not in _CAPA_STATUSES:
        conn.close()
        return jsonify(error="status must be open, investigating,"
                       " action, verify or closed"), 400
    source_type = (request.args.get("source_type") or "").strip().lower()
    if source_type and source_type not in _CAPA_SOURCE_TYPES:
        conn.close()
        return jsonify(error="source_type must be complaint,"
                       " audit_finding, recall_drill, haccp or other"), 400
    query = "SELECT * FROM erp_quality_capas"
    args = []
    clauses = []
    if status:
        clauses.append("status = ?")
        args.append(status)
    if source_type:
        clauses.append("source_type = ?")
        args.append(source_type)
    if clauses:
        query += " WHERE " + " AND ".join(clauses)
    query += " ORDER BY id DESC"
    rows = conn.execute(query, args).fetchall()
    out = [_capa_dict(conn, r) for r in rows]
    conn.close()
    return jsonify(capas=out)


@app.post("/api/erp/quality/capas")
def quality_capa_create():
    """Open a CAPA by hand. title is required; source_type defaults
    to 'other' (source_id is forced NULL for 'other'); status starts
    open unless given. A CAPA is never auto-created from a complaint,
    finding, drill or HACCP record."""
    actor, err = _require_erp_admin()
    if err:
        return err
    data = request.get_json(force=True) or {}
    conn = db()
    title = (data.get("title") or "").strip()
    if not title:
        conn.close()
        return jsonify(error="title is required"), 400
    if len(title) > 200:
        conn.close()
        return jsonify(error="title must be 200 characters or fewer"), 400
    source_type = (data.get("source_type") or "other").strip().lower()
    if source_type not in _CAPA_SOURCE_TYPES:
        conn.close()
        return jsonify(error="source_type must be complaint,"
                       " audit_finding, recall_drill, haccp or other"), 400
    source_id, s_err = _capa_valid_source_id(data.get("source_id"))
    if s_err:
        conn.close()
        return jsonify(error=s_err), 400
    if source_type == "other":
        source_id = None
    description = (data.get("description") or "").strip()
    if len(description) > 5000:
        conn.close()
        return jsonify(error="description must be 5000 characters or fewer"), 400
    root_cause = (data.get("root_cause") or "").strip()
    if len(root_cause) > 5000:
        conn.close()
        return jsonify(error="root_cause must be 5000 characters or fewer"), 400
    containment = (data.get("containment") or "").strip()
    if len(containment) > 5000:
        conn.close()
        return jsonify(error="containment must be 5000 characters or fewer"), 400
    status = (data.get("status") or "open").strip().lower()
    if status not in _CAPA_STATUSES:
        conn.close()
        return jsonify(error="status must be open, investigating,"
                       " action, verify or closed"), 400
    owner = (data.get("owner") or "").strip()
    if len(owner) > 200:
        conn.close()
        return jsonify(error="owner must be 200 characters or fewer"), 400
    due_date = (data.get("due_date") or "").strip()
    if due_date and not _legal_valid_date(due_date):
        conn.close()
        return jsonify(error="due_date must be YYYY-MM-DD"), 400
    verified_by = (data.get("verified_by") or "").strip()
    if len(verified_by) > 200:
        conn.close()
        return jsonify(error="verified_by must be 200 characters or fewer"), 400
    verified_at = (data.get("verified_at") or "").strip()
    if status == "closed" and not verified_by:
        conn.close()
        return jsonify(error="a closed CAPA requires verified_by"), 400
    now = datetime.now(timezone.utc).isoformat()
    if status == "closed" and not verified_at:
        verified_at = now
    cur = conn.execute(
        "INSERT INTO erp_quality_capas (title, source_type, source_id,"
        " description, root_cause, containment, status, owner, due_date,"
        " verified_by, verified_at, created_by, created_at, updated_by,"
        " updated_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
        (title, source_type, source_id, description, root_cause,
         containment, status, owner, due_date, verified_by, verified_at,
         actor, now, actor, now))
    row = conn.execute("SELECT * FROM erp_quality_capas WHERE id = ?",
                       (cur.lastrowid,)).fetchone()
    out = _capa_dict(conn, row)
    _erp_staff_audit(conn, actor, "quality.capa_created",
                     "quality_capa", row["id"],
                     "opened CAPA '%s' (%s)" % (title, source_type))
    conn.commit()
    conn.close()
    return jsonify(capa=out), 201


@app.get("/api/erp/quality/capas/<int:capa_id>")
def quality_capa_get(capa_id):
    """One CAPA with its actions."""
