@app.post("/api/erp/quality/capas/<int:capa_id>/update")
def quality_capa_update(capa_id):
    """Edit a CAPA (title, source, description, root cause,
    containment, status, owner, due date, verification). Status
    rules: closing requires verified_by (400 otherwise); moving to
    verify requires every action done (409 otherwise). Closing stamps
    verified_at when it is not already set."""
    actor, err = _require_erp_admin()
    if err:
        return err
    data = request.get_json(force=True) or {}
    conn = db()
    row = conn.execute("SELECT * FROM erp_quality_capas WHERE id = ?",
                       (capa_id,)).fetchone()
    if not row:
        conn.close()
        return jsonify(error="capa not found"), 404
    sets, args, changes = [], [], []
    if "title" in data:
        title = (data.get("title") or "").strip()
        if not title:
            conn.close()
            return jsonify(error="title is required"), 400
        if len(title) > 200:
            conn.close()
            return jsonify(error="title must be 200 characters or fewer"), 400
        if title != row["title"]:
            sets.append("title = ?")
            args.append(title)
            changes.append("title updated")
    if "source_type" in data:
        source_type = (data.get("source_type") or "").strip().lower()
        if source_type not in _CAPA_SOURCE_TYPES:
            conn.close()
            return jsonify(error="source_type must be complaint,"
                           " audit_finding, recall_drill, haccp or other"), 400
        if source_type != row["source_type"]:
            sets.append("source_type = ?")
            args.append(source_type)
            changes.append("source_type updated")
    if "source_id" in data:
        source_id, s_err = _capa_valid_source_id(data.get("source_id"))
        if s_err:
            conn.close()
            return jsonify(error=s_err), 400
        new_type = (data.get("source_type") or row["source_type"]).strip().lower()
        if new_type == "other":
            source_id = None
        if source_id != row["source_id"]:
            sets.append("source_id = ?")
            args.append(source_id)
            changes.append("source_id updated")
    if "description" in data:
        description = (data.get("description") or "").strip()
        if len(description) > 5000:
            conn.close()
            return jsonify(error="description must be 5000 characters or fewer"), 400
        if description != (row["description"] or ""):
            sets.append("description = ?")
            args.append(description)
            changes.append("description updated")
    if "root_cause" in data:
        root_cause = (data.get("root_cause") or "").strip()
        if len(root_cause) > 5000:
            conn.close()
            return jsonify(error="root_cause must be 5000 characters or fewer"), 400
        if root_cause != (row["root_cause"] or ""):
            sets.append("root_cause = ?")
            args.append(root_cause)
            changes.append("root_cause updated")
    if "containment" in data:
        containment = (data.get("containment") or "").strip()
        if len(containment) > 5000:
            conn.close()
            return jsonify(error="containment must be 5000 characters or fewer"), 400
        if containment != (row["containment"] or ""):
            sets.append("containment = ?")
            args.append(containment)
            changes.append("containment updated")
    if "owner" in data:
        owner = (data.get("owner") or "").strip()
        if len(owner) > 200:
            conn.close()
            return jsonify(error="owner must be 200 characters or fewer"), 400
        if owner != (row["owner"] or ""):
            sets.append("owner = ?")
            args.append(owner)
            changes.append("owner updated")
    if "due_date" in data:
        due_date = (data.get("due_date") or "").strip()
        if due_date and not _legal_valid_date(due_date):
            conn.close()
            return jsonify(error="due_date must be YYYY-MM-DD"), 400
        if due_date != (row["due_date"] or ""):
            sets.append("due_date = ?")
            args.append(due_date)
            changes.append("due_date updated")
    if "verified_by" in data:
        verified_by = (data.get("verified_by") or "").strip()
        if len(verified_by) > 200:
            conn.close()
            return jsonify(error="verified_by must be 200 characters or fewer"), 400
        if verified_by != (row["verified_by"] or ""):
            sets.append("verified_by = ?")
            args.append(verified_by)
            changes.append("verified_by updated")
    if "verified_at" in data:
        verified_at = (data.get("verified_at") or "").strip()
        if verified_at != (row["verified_at"] or ""):
            sets.append("verified_at = ?")
            args.append(verified_at)
            changes.append("verified_at updated")
    if "status" in data:
        status = (data.get("status") or "").strip().lower()
        if status not in _CAPA_STATUSES:
            conn.close()
            return jsonify(error="status must be open, investigating,"
                           " action, verify or closed"), 400
        if status != row["status"]:
            # Closing requires a verifier: one named in this update,
            # or already on the record.
            new_verified_by = (data.get("verified_by")
                               if "verified_by" in data else None)
            effective_verified_by = (new_verified_by.strip()
                                     if isinstance(new_verified_by, str)
                                     else None)
            if effective_verified_by is None:
                effective_verified_by = row["verified_by"] or ""
            if status == "closed" and not effective_verified_by:
                conn.close()
                return jsonify(error="a closed CAPA requires verified_by"), 400
            if status == "verify":
                open_actions = conn.execute(
                    "SELECT COUNT(*) FROM erp_quality_capa_actions"
                    " WHERE capa_id = ? AND status = 'open'",
                    (capa_id,)).fetchone()[0]
                if open_actions:
                    conn.close()
                    return jsonify(error="cannot move a CAPA to verify"
                                   " with %d open action(s)" % open_actions), 409
            sets.append("status = ?")
            args.append(status)
            changes.append("status: %s -> %s" % (row["status"], status))
            if status == "closed" and not (row["verified_at"] or "") \
                    and "verified_at" not in data:
                sets.append("verified_at = ?")
                args.append(datetime.now(timezone.utc).isoformat())
                changes.append("verified_at stamped")
    if sets:
        now = datetime.now(timezone.utc).isoformat()
        sets.append("updated_by = ?")
        args.append(actor)
        sets.append("updated_at = ?")
        args.append(now)
        args.append(capa_id)
        conn.execute("UPDATE erp_quality_capas SET %s WHERE id = ?"
                     % ", ".join(sets), args)
        _erp_staff_audit(conn, actor, "quality.capa_updated",
                         "quality_capa", capa_id, "; ".join(changes))
        conn.commit()
    row = conn.execute("SELECT * FROM erp_quality_capas WHERE id = ?",
                       (capa_id,)).fetchone()
    out = _capa_dict(conn, row)
    conn.close()
    return jsonify(capa=out)


@app.delete("/api/erp/quality/capas/<int:capa_id>")
def quality_capa_delete(capa_id):
    """Delete a CAPA. Refused (409) while open actions are attached;
    delete or finish those first. Done actions are deleted with the
    CAPA -- they belong to it and nothing else references them.
    Permanent; the frontend confirms with two taps."""
    actor, err = _require_erp_admin()
    if err:
        return err
    conn = db()
    row = conn.execute("SELECT * FROM erp_quality_capas WHERE id = ?",
                       (capa_id,)).fetchone()
    if not row:
        conn.close()
        return jsonify(error="capa not found"), 404
    open_count = conn.execute(
        "SELECT COUNT(*) FROM erp_quality_capa_actions"
        " WHERE capa_id = ? AND status = 'open'",
        (capa_id,)).fetchone()[0]
    if open_count:
        conn.close()
        return jsonify(error="cannot delete a CAPA with open actions"
                       " (%d open action(s) attached)" % open_count), 409
    conn.execute("DELETE FROM erp_quality_capa_actions WHERE capa_id = ?",
                 (capa_id,))
    conn.execute("DELETE FROM erp_quality_capas WHERE id = ?",
                 (capa_id,))
    _erp_staff_audit(conn, actor, "quality.capa_deleted",
                     "quality_capa", capa_id,
                     "deleted CAPA '%s'" % (row["title"] or ""))
    conn.commit()
    conn.close()
    return jsonify(ok=True)


