# ---------------- Supplier quality audits (Wave 3 B4, SOP 13.15) ----------------
# Admin-only. A formal audit of one vendor: date, auditor, scope, an
# admin-entered score (NULL = unscored, else 0-100) and an
# admin-entered outcome (pass | conditional | fail), plus findings.
# Mirrors the internal-audit endpoints deliberately. Scores/outcomes
# are never computed from the OTIF scorecards (delivery, not quality),
# and a 'fail' only flags the vendor row -- it never blocks a purchase
# order. The approved-supplier flag lives in the onboarding
# register (Wave 4 item 9, SOP 3.18) and is admin-granted only --
# never auto-derived from an audit. The audit register starts
# empty; nothing is auto-created.
def _supplier_audit_dict(conn, row, nested=False):
    """One supplier audit + vendor name + derived finding counts;
    nested=True adds its findings."""
    d = dict(row)
    vendor = conn.execute(
        "SELECT name FROM erp_vendors WHERE id = ?",
        (row["vendor_id"],)).fetchone()
    d["vendor_name"] = vendor["name"] if vendor else ""
    if nested:
        findings = conn.execute(
            "SELECT * FROM erp_quality_supplier_audit_findings"
            " WHERE supplier_audit_id = ? ORDER BY id",
            (row["id"],)).fetchall()
        d["findings"] = [dict(f) for f in findings]
        d["finding_count"] = len(findings)
        d["open_findings"] = sum(1 for f in findings
                                 if f["status"] == "open")
    else:
        d["finding_count"] = int(conn.execute(
            "SELECT COUNT(*) FROM erp_quality_supplier_audit_findings"
            " WHERE supplier_audit_id = ?", (row["id"],)).fetchone()[0])
        d["open_findings"] = int(conn.execute(
            "SELECT COUNT(*) FROM erp_quality_supplier_audit_findings"
            " WHERE supplier_audit_id = ? AND status = 'open'",
            (row["id"],)).fetchone()[0])
    return d


def _supplier_audit_valid_score(value):
    """score is NULL (unscored) or an int 0-100. Returns (int|None, error)."""
    if value is None or value == "":
        return None, None
    if isinstance(value, bool):
        return None, "score must be an integer 0-100, or blank for unscored"
    try:
        score = int(value)
    except (TypeError, ValueError):
        return None, "score must be an integer 0-100, or blank for unscored"
    if isinstance(value, float) and not value.is_integer():
        return None, "score must be an integer 0-100, or blank for unscored"
    if str(value).strip() != str(score) and not (
            isinstance(value, int)):
        # Reject "85.5" and the like, which int() would silently floor.
        try:
            if float(value) != score:
                return None, ("score must be an integer 0-100,"
                              " or blank for unscored")
        except (TypeError, ValueError):
            return None, "score must be an integer 0-100, or blank for unscored"
    if score < 0 or score > 100:
        return None, "score must be 0-100, or blank for unscored"
    return score, None


def _supplier_audit_vendor(conn, vendor_id):
    """vendor_id -> vendor row, or None. Accepts int-like values only."""
    try:
        vid = int(vendor_id)
    except (TypeError, ValueError):
        return None
    if str(vendor_id).strip() != str(vid) and not isinstance(vendor_id, int):
        return None
    return conn.execute("SELECT * FROM erp_vendors WHERE id = ?",
                        (vid,)).fetchone()


@app.get("/api/erp/quality/supplier-audits")
def quality_supplier_audits_list():
    """All supplier audits, newest audit date first, with finding
    counts. Filters: outcome=, vendor_id=. Starts empty; nothing is
    auto-created."""
    _, err = _require_erp_admin()
    if err:
        return err
    conn = db()
    outcome = (request.args.get("outcome") or "").strip().lower()
    if outcome and outcome not in _SUPPLIER_AUDIT_OUTCOMES:
        conn.close()
        return jsonify(error="outcome must be pass, conditional or fail"), 400
    vendor_id = (request.args.get("vendor_id") or "").strip()
    vendor = None
    if vendor_id:
        vendor = _supplier_audit_vendor(conn, vendor_id)
        if not vendor:
            conn.close()
            return jsonify(error="vendor not found"), 400
    query = "SELECT * FROM erp_quality_supplier_audits"
    args = []
    clauses = []
    if outcome:
        clauses.append("outcome = ?")
        args.append(outcome)
    if vendor:
        clauses.append("vendor_id = ?")
        args.append(vendor["id"])
    if clauses:
        query += " WHERE " + " AND ".join(clauses)
    query += " ORDER BY audit_date DESC, id DESC"
    rows = conn.execute(query, args).fetchall()
    out = [_supplier_audit_dict(conn, r) for r in rows]
    conn.close()
    return jsonify(supplier_audits=out)


@app.post("/api/erp/quality/supplier-audits")
def quality_supplier_audit_create():
    """Record a supplier audit by hand. vendor_id must be an existing
    vendor; audit_date is required (YYYY-MM-DD); score is NULL
    (unscored) or 0-100; outcome defaults to pass."""
    actor, err = _require_erp_admin()
    if err:
        return err
    data = request.get_json(force=True) or {}
    conn = db()
    vendor = _supplier_audit_vendor(conn, data.get("vendor_id"))
    if not vendor:
        conn.close()
        return jsonify(error="vendor_id must be an existing vendor"), 400
    audit_date = (data.get("audit_date") or "").strip()
    if not audit_date or not _legal_valid_date(audit_date):
        conn.close()
        return jsonify(error="audit_date must be YYYY-MM-DD"), 400
    auditor = (data.get("auditor") or "").strip()
    if len(auditor) > 200:
        conn.close()
        return jsonify(error="auditor must be 200 characters or fewer"), 400
    scope = (data.get("scope") or "").strip()
    if len(scope) > 5000:
        conn.close()
        return jsonify(error="scope must be 5000 characters or fewer"), 400
    score, s_err = _supplier_audit_valid_score(data.get("score"))
    if s_err:
        conn.close()
        return jsonify(error=s_err), 400
    outcome = (data.get("outcome") or "pass").strip().lower()
    if outcome not in _SUPPLIER_AUDIT_OUTCOMES:
        conn.close()
        return jsonify(error="outcome must be pass, conditional or fail"), 400
    next_audit_date = (data.get("next_audit_date") or "").strip()
    if next_audit_date and not _legal_valid_date(next_audit_date):
        conn.close()
        return jsonify(error="next_audit_date must be YYYY-MM-DD"), 400
    notes = (data.get("notes") or "").strip()
    if len(notes) > 5000:
        conn.close()
        return jsonify(error="notes must be 5000 characters or fewer"), 400
    now = datetime.now(timezone.utc).isoformat()
    cur = conn.execute(
        "INSERT INTO erp_quality_supplier_audits (vendor_id, audit_date,"
        " auditor, scope, score, outcome, next_audit_date, notes,"
        " created_by, created_at, updated_by, updated_at)"
        " VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
        (vendor["id"], audit_date, auditor, scope, score, outcome,
         next_audit_date, notes, actor, now, actor, now))
    row = conn.execute(
        "SELECT * FROM erp_quality_supplier_audits WHERE id = ?",
        (cur.lastrowid,)).fetchone()
    out = _supplier_audit_dict(conn, row)
    _erp_staff_audit(conn, actor, "quality.supplier_audit_created",
                     "quality_supplier_audit", row["id"],
                     "supplier audit for vendor %s (%s, %s)"
                     % (vendor["name"], audit_date, outcome))
    conn.commit()
    conn.close()
    return jsonify(supplier_audit=out), 201


