@app.delete("/api/erp/quality/supplier-audits/<int:audit_id>")
def quality_supplier_audit_delete(audit_id):
    """Delete a supplier audit. Refused (409) while open findings are
    attached; finish or delete those first. Done findings are deleted
    with the audit -- they belong to it and nothing else references
    them. Permanent; the frontend confirms with two taps."""
    actor, err = _require_erp_admin()
    if err:
        return err
    conn = db()
    row = conn.execute(
        "SELECT * FROM erp_quality_supplier_audits WHERE id = ?",
        (audit_id,)).fetchone()
    if not row:
        conn.close()
        return jsonify(error="supplier audit not found"), 404
    open_count = conn.execute(
        "SELECT COUNT(*) FROM erp_quality_supplier_audit_findings"
        " WHERE supplier_audit_id = ? AND status = 'open'",
        (audit_id,)).fetchone()[0]
    if open_count:
        conn.close()
        return jsonify(error="cannot delete a supplier audit with open"
                       " findings (%d open finding(s) attached)"
                       % open_count), 409
    conn.execute(
        "DELETE FROM erp_quality_supplier_audit_findings"
        " WHERE supplier_audit_id = ?", (audit_id,))
    conn.execute("DELETE FROM erp_quality_supplier_audits WHERE id = ?",
                 (audit_id,))
    _erp_staff_audit(conn, actor, "quality.supplier_audit_deleted",
                     "quality_supplier_audit", audit_id,
                     "deleted supplier audit for vendor %d" % row["vendor_id"])
    conn.commit()
    conn.close()
    return jsonify(ok=True)


