    """Add a finding to a supplier audit. severity is minor / major /
    critical; status starts open unless given."""
    actor, err = _require_erp_admin()
    if err:
        return err
    data = request.get_json(force=True) or {}
    conn = db()
    if not conn.execute(
            "SELECT id FROM erp_quality_supplier_audits WHERE id = ?",
            (audit_id,)).fetchone():
        conn.close()
        return jsonify(error="supplier audit not found"), 404
    description = (data.get("description") or "").strip()
    if not description:
        conn.close()
        return jsonify(error="description is required"), 400
    if len(description) > 5000:
        conn.close()
        return jsonify(error="description must be 5000 characters or fewer"), 400
    severity = (data.get("severity") or "minor").strip().lower()
