@app.post("/api/erp/purchasing/requisitions/<int:req_id>/submit")
def erp_submit_requisition(req_id):
    """Draft -> submitted. The requester (or an admin) submits; only
    a draft can be submitted."""
    actor, err = _require_erp()
    if err:
        return err
