    posted = _lease_posted_months(conn, lease_id)
    if posted:
        conn.close()
        return jsonify(error="lease has posted months; posted entries are permanent"), 400
    conn.execute("DELETE FROM erp_legal_lease_schedules WHERE id = ?",
                 (lease_id,))
    conn.commit()
    conn.close()
    return jsonify(ok=True)


