def _stores_z_posted(conn, store_id, register, report_date):
    """Ledger tie-out for one Z-report: the posted POS entries behind
    this register/day, from erp_acct_sale_posts (status 'posted')."""
    posted_total = 0
    posted_count = 0
    entry_ids = []
    for sale in conn.execute(
            "SELECT * FROM erp_store_sales WHERE store_id = ?"
            " AND register = ? AND substr(sold_at, 1, 10) = ?",
            (store_id, register, report_date)).fetchall():
        if (sale["sale_kind"] if "sale_kind" in sale.keys()
                else "popcorn") == "gift_card":
            # A gift-card sale posts as a liability under
            # giftcard:<code>, not pos:<key> -- follow the intake row
            # to its real posting so the tie-out still works.
            _gc = conn.execute(
                "SELECT code FROM gift_cards WHERE stripe_session_id = ?",
                ("pos:%d:%s" % (store_id, sale["sale_key"]),)).fetchone()
            _key = "giftcard:%s" % (_gc["code"] if _gc else "")
        else:
            _key = "pos:%d:%s" % (store_id, sale["sale_key"])
        row = conn.execute(
            "SELECT journal_entry_id, amount_cents FROM erp_acct_sale_posts"
            " WHERE source_key = ? AND status = 'posted'",
            (_key,)).fetchone()
        if row:
            posted_total += int(row["amount_cents"] or 0)
            posted_count += 1
            entry_ids.append(row["journal_entry_id"])
    return {"posted_total_cents": posted_total,
            "posted_sale_count": posted_count,
            "posted_entry_ids": entry_ids}


@app.post("/api/erp/stores/<int:store_id>/z-report")
def stores_zreport_create(store_id):
    """Close a register day: totals by tender, the counted cash
    drawer, and the variance (computed here as drawer minus the cash
    total -- never trusted from the payload). One Z-report per
    (store, register, date)."""
    actor, err = _require_erp_admin()
    if err:
        return err
    data = request.get_json(force=True) or {}
    conn = db()
    store = conn.execute(
        "SELECT * FROM erp_stores WHERE id = ?", (store_id,)).fetchone()
    if not store:
        conn.close()
        return jsonify(error="store not found"), 404
    register = (data.get("register") or "").strip()
    if not register:
        conn.close()
        return jsonify(error="register is required"), 400
    report_date = (data.get("date") or data.get("report_date") or "").strip()
    if not report_date or not _legal_valid_date(report_date):
        conn.close()
        return jsonify(error="date must be YYYY-MM-DD"), 400
    totals = data.get("totals_by_tender")
    if not isinstance(totals, dict) or not totals:
        conn.close()
        return jsonify(error="totals_by_tender must be a non-empty object"), 400
    cleaned = {}
    for tender, cents in totals.items():
        value = _stores_int(cents)
        if value is None or value < 0:
            conn.close()
            return jsonify(error="totals_by_tender values must be whole cents, 0 or more"), 400
        cleaned[str(tender).strip() or "other"] = value
    cash_count = _stores_int(data.get("cash_count_cents"))
    if cash_count is None or cash_count < 0:
        conn.close()
        return jsonify(error="cash_count_cents must be a whole number of cents, 0 or more"), 400
    variance = cash_count - int(cleaned.get("cash", 0))
    existing = conn.execute(
        "SELECT id FROM erp_store_zreports WHERE store_id = ?"
        " AND register = ? AND report_date = ?",
        (store_id, register, report_date)).fetchone()
    if existing:
        conn.close()
        return jsonify(error="a Z-report already exists for this register and date"), 409
    now = datetime.now(timezone.utc).isoformat()
    cur = conn.execute(
        "INSERT INTO erp_store_zreports (store_id, register, report_date,"
        " totals_json, cash_count_cents, variance_cents, created_by,"
        " created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?)",
        (store_id, register, report_date, json.dumps(cleaned),
         cash_count, variance, actor, now))
    row = conn.execute(
        "SELECT * FROM erp_store_zreports WHERE id = ?",
        (cur.lastrowid,)).fetchone()
    out = _stores_zreport_dict(row)
    out.update(_stores_z_posted(conn, store_id, register, report_date))
    out["posted_ties"] = out["posted_total_cents"] == out["total_cents"]
    conn.commit()
    conn.close()
    return jsonify(zreport=out), 201


@app.get("/api/erp/stores/<int:store_id>/z-reports")
def stores_zreports_list(store_id):
    """Z-reports for a store, newest date first."""
    _, err = _require_erp_admin()
    if err:
        return err
    conn = db()
    store = conn.execute(
        "SELECT * FROM erp_stores WHERE id = ?", (store_id,)).fetchone()
    if not store:
        conn.close()
        return jsonify(error="store not found"), 404
    rows = conn.execute(
        "SELECT * FROM erp_store_zreports WHERE store_id = ?"
        " ORDER BY report_date DESC, id DESC", (store_id,)).fetchall()
    out = []
    for r in rows:
        d = _stores_zreport_dict(r)
        d.update(_stores_z_posted(conn, store_id, r["register"],
                                  r["report_date"]))
        d["posted_ties"] = d["posted_total_cents"] == d["total_cents"]
        out.append(d)
    conn.close()
    return jsonify(zreports=out)


# ---------------------------------------------------------------- Dept 14 (Stores) Wave B
# Per-store P&L (read-only) + recurring weekly shift templates with a
# timeclock. Nothing here posts to the accounting ledger and nothing
# here creates a payrun: the P&L reads posted sale entries + the POS
# feed, and timeclock hours are only visible to payroll when a run is
# created (follow-up). Unattributed figures are never estimated or
# allocated to a store.

_STORE_WEEKDAYS = ("Monday", "Tuesday", "Wednesday", "Thursday", "Friday",
                   "Saturday", "Sunday")


def _stores_time_minutes(value):
    """HH:MM -> minutes after midnight, or None when malformed."""
    if not isinstance(value, str):
        return None
    m = re.match(r"^(\d{1,2}):(\d{2})$", value.strip())
    if not m:
        return None
    hh, mm = int(m.group(1)), int(m.group(2))
    if hh > 23 or mm > 59:
        return None
    return hh * 60 + mm


def _stores_parse_dt(value):
    """ISO timestamp -> aware datetime, or None. Naive values are UTC."""
    if not isinstance(value, str) or not value.strip():
        return None
    try:
        dt = datetime.fromisoformat(value.strip().replace("Z", "+00:00"))
    except ValueError:
        return None
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=timezone.utc)
    return dt


def _stores_shift_dict(row):
    d = dict(row)
    d["weekday_label"] = (_STORE_WEEKDAYS[d["weekday"]]
                          if 0 <= int(d["weekday"] or 0) <= 6 else "")
    return d


def _stores_shift_row(conn, shift_id):
    return conn.execute(
        "SELECT s.*, e.name AS employee_name"
        " FROM erp_store_shifts s"
        " LEFT JOIN erp_hr_employees e ON e.id = s.employee_id"
        " WHERE s.id = ?", (shift_id,)).fetchone()


def _stores_timeclock_dict(row):
    d = dict(row)
    if d.get("hours") is not None:
        d["hours"] = float(d["hours"])
    return d


def _stores_timeclock_row(conn, row_id):
    return conn.execute(
        "SELECT t.*, e.name AS employee_name, s.weekday AS shift_weekday,"
        " s.start_time AS shift_start, s.end_time AS shift_end,"
        " s.role AS shift_role, s.store_id AS shift_store_id,"
        " l.payrun_id AS payrun_id"
        " FROM erp_store_timeclock t"
        " LEFT JOIN erp_hr_employees e ON e.id = t.employee_id"
        " LEFT JOIN erp_store_shifts s ON s.id = t.shift_id"
        " LEFT JOIN erp_acct_payrun_lines l ON l.id = t.payrun_line_id"
        " WHERE t.id = ?", (row_id,)).fetchone()


def _stores_validate_shift(conn, data, current=None):
    """Validate shift fields. `current` is the existing row on update
    (fields fall back to it). Returns the cleaned dict, or
    (error_response, status) on a bad value."""
    merged = dict(current) if current else {}
    for key in ("employee_id", "weekday", "start_time", "end_time", "role"):
        if key in data:
            merged[key] = data[key]
    try:
        employee_id = int(merged.get("employee_id"))
    except (TypeError, ValueError):
        return jsonify(error="employee_id is required"), 400
    emp = conn.execute(
        "SELECT id, active FROM erp_hr_employees WHERE id = ?",
        (employee_id,)).fetchone()
    if not emp:
        return jsonify(error="employee not found"), 400
    if not int(emp["active"] or 0):
        return jsonify(error="employee is inactive"), 400
    try:
        weekday = int(merged.get("weekday"))
    except (TypeError, ValueError):
        return jsonify(error="weekday must be 0 (Monday) to 6 (Sunday)"), 400
    if weekday < 0 or weekday > 6:
        return jsonify(error="weekday must be 0 (Monday) to 6 (Sunday)"), 400
    start = _stores_time_minutes(merged.get("start_time"))
    end = _stores_time_minutes(merged.get("end_time"))
    if start is None or end is None:
        return jsonify(error="start_time and end_time must be HH:MM"), 400
    if end <= start:
        return jsonify(error="end_time must be after start_time"), 400
    role = (merged.get("role") or "").strip()
    if len(role) > 100:
        return jsonify(error="role must be 100 characters or fewer"), 400
    start_txt = "%02d:%02d" % (start // 60, start % 60)
    end_txt = "%02d:%02d" % (end // 60, end % 60)
    # No overlapping shifts for the same employee on the same weekday.
    # A gap between two shifts is fine; an overlap is not.
    others = conn.execute(
        "SELECT id, start_time, end_time FROM erp_store_shifts"
        " WHERE employee_id = ? AND weekday = ?",
        (employee_id, weekday)).fetchall()
    for o in others:
        if current and int(o["id"]) == int(current["id"]):
            continue
        o_start = _stores_time_minutes(o["start_time"])
        o_end = _stores_time_minutes(o["end_time"])
        if o_start is not None and o_end is not None \
                and start < o_end and o_start < end:
            return jsonify(
                error="employee already has an overlapping shift that day"), 400
    return {"employee_id": employee_id, "weekday": weekday,
            "start_time": start_txt, "end_time": end_txt, "role": role}


def _stores_pl_range(conn, store, date_from, date_to, blended=None):
    """Per-store P&L for one date range. Revenue = posted ledger sale
    entries tagged to this store + the POS sales feed, counting only
    sales with no sale-posts row so nothing is double-counted. COGS =
    bags sold x the blended production cost per bag across completed
    batches (all-time basis); with no completed batches it is None,
    never guessed. Posted entries with no store are reported as
    unattributed and never allocated. Returns the same dict the
    per-store P&L endpoint returns. `blended` is the
    _erp_blended_cost_per_bag() tuple, computed once by callers that
    run many ranges (the period breakdown)."""
    def _range_where(col, params):
        where = ""
        if date_from:
            where += " AND substr(%s, 1, 10) >= ?" % col
            params.append(date_from)
        if date_to:
            where += " AND substr(%s, 1, 10) <= ?" % col
            params.append(date_to)
        return where

    store_id = int(store["id"])
    p_params = [store_id]
    posted = conn.execute(
        "SELECT COALESCE(SUM(amount_cents), 0) AS rev, COUNT(*) AS n"
        " FROM erp_acct_sale_posts WHERE store_id = ? AND status = 'posted'"
        + _range_where("posted_at", p_params), p_params).fetchone()
    pos_params = [store_id]
    pos_rows = conn.execute(
        "SELECT * FROM erp_store_sales WHERE store_id = ?"
        + _range_where("sold_at", pos_params), pos_params).fetchall()
    # Posted sales already count in posted revenue: the POS feed below
    # counts only sales with no sale-posts row at all, so nothing is
    # double-counted. A reversed sale keeps its row (status 'reversed')
    # and stays out: its revenue posted, then reversed to zero. Bags
    # still count every intake sale (COGS is about bags sold, posted
    # or not).
    _posted_keys = set()
    _pk_params = [store_id]
    for _pk in conn.execute(
            "SELECT source_key FROM erp_acct_sale_posts"
            " WHERE store_id = ?"
            + _range_where("posted_at", _pk_params),
            _pk_params).fetchall():
        _prefix = "pos:%d:" % store_id
        if _pk["source_key"].startswith(_prefix):
            _posted_keys.add(_pk["source_key"][len(_prefix):])
    pos_rev = sum(int(r["total_cents"] or 0) for r in pos_rows
                  if r["sale_key"] not in _posted_keys
                  and (r["sale_kind"] if "sale_kind" in r.keys()
                       else "popcorn") != "gift_card")
    bags = 0.0
    for r in pos_rows:
        # A gift-card sale is not a bag sold: its intake item is the
        # card itself, and counting it would inflate COGS.
        if (r["sale_kind"] if "sale_kind" in r.keys()
                else "popcorn") == "gift_card":
            continue
        try:
            items = json.loads(r["items_json"] or "[]") or []
        except (TypeError, ValueError):
            items = []
        for it in items:
            try:
                bags += float(it.get("qty") or 0)
            except (TypeError, ValueError):
                pass
    u_params = []
    unattributed = conn.execute(
        "SELECT COALESCE(SUM(amount_cents), 0) AS rev, COUNT(*) AS n"
        " FROM erp_acct_sale_posts WHERE store_id IS NULL"
        " AND status = 'posted'"
        + _range_where("posted_at", u_params), u_params).fetchone()
    if blended is None:
        blended, n_batches, prod_bags, prod_cost = \
            _erp_blended_cost_per_bag(conn)
    else:
        blended, n_batches, prod_bags, prod_cost = blended
    cogs = round(bags * blended, 2) if blended is not None else None
    revenue = int(posted["rev"] or 0) + pos_rev
    gross = round(revenue - cogs, 2) if cogs is not None else None
    notes = [
        "POS sales post to the ledger on intake; posted revenue "
        "includes them and the POS feed below counts only sales not "
        "yet posted, so no sale is counted twice.",
        ("COGS uses the blended production cost per bag across completed "
         "batches (all-time basis); no per-flavor cost is assumed."
         if blended is not None else
         "No completed production batches yet, so COGS is not estimated."),
        "Unattributed sales are online / wholesale / gift-card sales with "
        "no store tag. They are reported, never allocated to a store, and "
        "their COGS is not estimated.",
    ]
    return {
        "store_id": store_id, "store_name": store["name"],
        "from": date_from or None, "to": date_to or None,
        "posted_revenue_cents": int(posted["rev"] or 0),
        "posted_sale_count": int(posted["n"] or 0),
        "pos_revenue_cents": pos_rev,
        "pos_sale_count": len(pos_rows),
        "revenue_cents": revenue,
        "bags": bags,
        "cogs_cents": cogs,
        "gross_cents": gross,
        "cost_basis": {
            "blended_cost_per_bag_cents":
                round(blended, 2) if blended is not None else None,
            "completed_batches": n_batches,
            "bags_produced": prod_bags,
            "total_cost_cents": prod_cost},
        "unattributed": {
            "revenue_cents": int(unattributed["rev"] or 0),
            "sale_count": int(unattributed["n"] or 0),
            "cogs_cents": None,
            "note": "unattributed \u2014 not estimated"},
        "notes": notes}


def _stores_pl_bucket_list(period, date_from, date_to):
    """(label, from, to) buckets covering date_from..date_to for one
    period view. Day buckets are single dates, month buckets calendar
    months, quarter buckets calendar quarters, year buckets calendar
    years. Buckets are clipped to the requested range."""
    from datetime import date as _date, timedelta as _td

    def _month_last(y, m):
        if m == 12:
            return _date(y + 1, 1, 1) - _td(days=1)
        return _date(y, m + 1, 1) - _td(days=1)

    f = _date.fromisoformat(date_from)
    t = _date.fromisoformat(date_to)
    out = []
    if period == "day":
        d = f
        while d <= t:
            out.append((d.isoformat(), d.isoformat(), d.isoformat()))
            d += _td(days=1)
    elif period == "month":
        y, m = f.year, f.month
        while (y, m) <= (t.year, t.month):
            first = _date(y, m, 1)
            last = _month_last(y, m)
            out.append(("%04d-%02d" % (y, m),
                        max(first, f).isoformat(),
                        min(last, t).isoformat()))
            m += 1
            if m > 12:
                m = 1
                y += 1
    elif period == "quarter":
        q = (f.month - 1) // 3
        y = f.year
        while (y, q) <= (t.year, (t.month - 1) // 3):
            first = _date(y, q * 3 + 1, 1)
            last = _month_last(y, q * 3 + 3)
            out.append(("%04d-Q%d" % (y, q + 1),
                        max(first, f).isoformat(),
                        min(last, t).isoformat()))
            q += 1
            if q > 3:
                q = 0
                y += 1
    else:  # year
        for y in range(f.year, t.year + 1):
            out.append(("%04d" % y,
                        max(_date(y, 1, 1), f).isoformat(),
                        min(_date(y, 12, 31), t).isoformat()))
    return out


@app.get("/api/erp/stores/<int:store_id>/pl")
def stores_pl(store_id):
    """Per-store P&L, read-only. Revenue = posted ledger sale entries
    tagged to this store (none yet -- POS intake is not wired to the
    ledger) + the POS sales feed for the store. COGS = bags sold x the
    blended production cost per bag across completed batches (the same
    basis as the channel-profitability report); with no completed
    batches it is null, never guessed. Posted entries with no store
    (online / wholesale / gift-card) are reported as unattributed and
    never allocated to any store. ?from= / ?to= are YYYY-MM-DD."""
    _, err = _require_erp_admin()
    if err:
        return err
    date_from = (request.args.get("from") or "").strip()
    date_to = (request.args.get("to") or "").strip()
    if (date_from and not _legal_valid_date(date_from)) \
            or (date_to and not _legal_valid_date(date_to)):
        return jsonify(error="from/to must be YYYY-MM-DD"), 400
    conn = db()
    store = conn.execute(
        "SELECT * FROM erp_stores WHERE id = ?", (store_id,)).fetchone()
    if not store:
        conn.close()
        return jsonify(error="store not found"), 404
    _acct_ensure_sale_posts_table(conn)
    result = _stores_pl_range(conn, store, date_from, date_to)
    conn.close()
    return jsonify(result)


@app.get("/api/erp/stores/<int:store_id>/pl-periods")
def stores_pl_periods(store_id):
    """Per-store finance breakdown by period: Day / Month / Quarter /
    Year. Each bucket reuses the per-store P&L computation for its own
    date range (same revenue, COGS, and gross-profit basis; COGS is
    null everywhere until completed batches exist, never guessed).
    ?period= is day, month, quarter, or year. ?from= / ?to= are
    YYYY-MM-DD; with no range the view defaults to the last 30 days
    (day), last 12 months (month), last 8 quarters (quarter), or last
    5 years (year). Ranges wider than 366 days / 60 months /
    40 quarters / 20 years are refused -- a day view over ten years
    would be thousands of buckets."""
    _, err = _require_erp_admin()
    if err:
        return err
    period = (request.args.get("period") or "month").strip().lower()
    if period not in ("day", "month", "quarter", "year"):
        return jsonify(
            error="period must be day, month, quarter, or year"), 400
    date_from = (request.args.get("from") or "").strip()
    date_to = (request.args.get("to") or "").strip()
    if (date_from and not _legal_valid_date(date_from)) \
            or (date_to and not _legal_valid_date(date_to)):
        return jsonify(error="from/to must be YYYY-MM-DD"), 400
    if date_from and date_to and date_from > date_to:
        return jsonify(error="from must be on or before to"), 400
    from datetime import date as _date, timedelta as _td
    today = datetime.now(timezone.utc).date()
    if not date_from or not date_to:
        if period == "day":
            date_from = (today - _td(days=29)).isoformat()
            date_to = today.isoformat()
        elif period == "month":
            y, m = today.year, today.month
            for _ in range(11):
                m -= 1
                if m < 1:
                    m = 12
                    y -= 1
            date_from = _date(y, m, 1).isoformat()
            last = _date(today.year, today.month, 1)
            if today.month == 12:
                last = _date(today.year + 1, 1, 1) - _td(days=1)
            else:
                last = _date(today.year, today.month + 1, 1) - _td(days=1)
            date_to = last.isoformat()
        elif period == "quarter":
            q = (today.month - 1) // 3
            y = today.year
            for _ in range(7):
                q -= 1
                if q < 0:
                    q = 3
                    y -= 1
            date_from = _date(y, q * 3 + 1, 1).isoformat()
            cq = (today.month - 1) // 3
            last_m = cq * 3 + 3
            if last_m == 12:
                last = _date(today.year + 1, 1, 1) - _td(days=1)
            else:
                last = _date(today.year, last_m + 1, 1) - _td(days=1)
            date_to = last.isoformat()
        else:
            date_from = _date(today.year - 4, 1, 1).isoformat()
            date_to = _date(today.year, 12, 31).isoformat()
    caps = {"day": 366, "month": 60, "quarter": 40, "year": 20}
    buckets = _stores_pl_bucket_list(period, date_from, date_to)
    if len(buckets) > caps[period]:
        return jsonify(
            error="range too wide for a %s view (max %d buckets)"
                  % (period, caps[period])), 400
    conn = db()
    store = conn.execute(
        "SELECT * FROM erp_stores WHERE id = ?", (store_id,)).fetchone()
    if not store:
        conn.close()
        return jsonify(error="store not found"), 404
    _acct_ensure_sale_posts_table(conn)
    blended = _erp_blended_cost_per_bag(conn)
    out = []
    for label, b_from, b_to in buckets:
        r = _stores_pl_range(conn, store, b_from, b_to, blended)
        out.append({
            "period": label, "from": b_from, "to": b_to,
            "revenue_cents": r["revenue_cents"],
            "cogs_cents": r["cogs_cents"],
            "gross_cents": r["gross_cents"],
            "bags": r["bags"],
            "posted_sale_count": r["posted_sale_count"],
            "pos_sale_count": r["pos_sale_count"]})
    conn.close()
    tot_rev = sum(b["revenue_cents"] for b in out)
    tot_cogs = (None if any(b["cogs_cents"] is None for b in out)
                else sum(b["cogs_cents"] for b in out))
    tot_gross = (None if tot_cogs is None
                 else round(tot_rev - tot_cogs, 2))
    return jsonify({
        "store_id": store_id, "store_name": store["name"],
        "period": period, "from": date_from, "to": date_to,
        "buckets": out,
        "totals": {"revenue_cents": tot_rev, "cogs_cents": tot_cogs,
                   "gross_cents": tot_gross,
                   "bags": sum(b["bags"] for b in out),
                   "posted_sale_count":
                       sum(b["posted_sale_count"] for b in out),
                   "pos_sale_count":
                       sum(b["pos_sale_count"] for b in out)},
        "notes": [
            "Each bucket reuses the per-store P&L computation for its "
            "own dates; COGS is null until completed batches exist.",
            "Unattributed sales are never allocated to any store."]})



# --- Stores Wave D (Nov 2026): bank deposits, daily open/close
# --- checklists, incident reports, store documents, price
# --- changes, vendor deliveries to a store. All admin-only, all
# --- start empty, all live inside the per-store card.
_STORES_CHECKLIST_TEMPLATES = {
    "open": [("drawer", "Count the drawer"),
             ("safe", "Verify the safe"),
             ("temps", "Check temperatures"),
             ("unlock", "Unlock and open"),
             ("signage", "Signage and displays up")],
    "close": [("drawer", "Count the drawer"),
              ("zreport", "Z-report done"),
              ("safedrop", "Safe drop made"),
              ("lockup", "Lock up"),
              ("alarm", "Alarm set")],
}
_STORES_INCIDENT_TYPES = ("theft", "injury", "customer complaint",
                          "property damage", "other")
_STORES_INCIDENT_STATUSES = ("open", "investigating", "resolved")
_STORES_DOC_TYPES = ("business license", "health permit",
                     "food handler certificate", "insurance certificate",
                     "lease", "other")
_STORES_PRICE_KINDS = ("flavor", "pack3", "pack6", "merch")


def _stores_deposit_dict(row):
    return dict(row)


def _stores_cash_tenders(conn, store_id):
    """Cash-tender cents on non-voided POS sales for a store. A
    voided sale's cash never reached the drawer, so it is out; a
    gift-card purchase paid in cash IS cash in the drawer, so it
    counts. Sales with no tender split fall back to their single
    tender string (same rule as the Z-report totals)."""
    voided = {r["sale_key"] for r in conn.execute(
        "SELECT sale_key FROM erp_store_voids WHERE store_id = ?",
        (store_id,)).fetchall()}
    cash = 0
    for r in conn.execute(
            "SELECT sale_key, tender, tenders_json, total_cents"
            " FROM erp_store_sales WHERE store_id = ?",
            (store_id,)).fetchall():
        if r["sale_key"] in voided:
            continue
        try:
            split = json.loads(r["tenders_json"] or "{}") or {}
        except (TypeError, ValueError):
            split = {}
        if split:
            cash += int(split.get("cash") or 0)
        elif (r["tender"] or "") == "cash":
            cash += int(r["total_cents"] or 0)
    return cash


def _stores_undeposited_cash_cents(conn, store_id):
    """Cash in the drawer that has not been taken to the bank yet:
    cash-tender POS sales minus deposits recorded. Never negative
    in practice; a negative value means deposits exceeded recorded
    cash, and a further deposit is refused until sales catch up."""
    deposited = conn.execute(
        "SELECT COALESCE(SUM(amount_cents), 0) AS t"
        " FROM erp_store_deposits WHERE store_id = ?",
        (store_id,)).fetchone()
    return _stores_cash_tenders(conn, store_id) - int(deposited["t"] or 0)


@app.post("/api/erp/stores/<int:store_id>/deposits")
def stores_deposit_create(store_id):
    """Record cash taken to the bank. This NEVER posts to the
    ledger: register cash sales already post Dr 1010 Checking on
    intake, so a deposit is the physical movement + audit trail, not
    a second posting (posting one would double-count the cash). A
    deposit larger than the undeposited cash is refused."""
    actor, err = _require_erp_admin()
    if err:
        return err
    data = request.get_json(force=True) or {}
    conn = db()
    store = _stores_require_store(conn, store_id)
    if not store:
        conn.close()
        return jsonify(error="store not found"), 404
    dep_date = (data.get("deposit_date") or "").strip()
    if not _legal_valid_date(dep_date):
        conn.close()
        return jsonify(error="deposit_date must be YYYY-MM-DD"), 400
    today = datetime.now(timezone.utc).date().isoformat()
    if dep_date > today:
        conn.close()
        return jsonify(error="deposit_date cannot be in the future"), 400
    amount = _stores_int(data.get("amount_cents"))
    if amount is None or amount <= 0:
        conn.close()
        return jsonify(
            error="amount_cents must be a whole number of cents"
                  " greater than zero"), 400
    undeposited = _stores_undeposited_cash_cents(conn, store_id)
    if amount > undeposited:
        conn.close()
        return jsonify(
            error="deposit of %s exceeds undeposited cash %s"
                  % (erp_money_html(amount),
                     erp_money_html(max(undeposited, 0)))), 400
    counted_by = (data.get("counted_by") or "").strip() or actor
    bank_ref = (data.get("bank_ref") or "").strip()[:200]
    note = (data.get("note") or "").strip()[:1000]
    now = datetime.now(timezone.utc).isoformat()
    cur = conn.execute(
        "INSERT INTO erp_store_deposits (store_id, deposit_date,"
        " amount_cents, counted_by, bank_ref, note, created_by,"
        " created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?)",
        (store_id, dep_date, amount, counted_by, bank_ref, note,
         actor, now))
    row = conn.execute(
        "SELECT * FROM erp_store_deposits WHERE id = ?",
        (cur.lastrowid,)).fetchone()
    conn.commit()
    conn.close()
    return jsonify(
        deposit=_stores_deposit_dict(row),
        undeposited_cash_cents=undeposited - amount), 201


@app.get("/api/erp/stores/<int:store_id>/deposits")
def stores_deposit_list(store_id):
    """Bank deposits for a store, newest first, with the cash
    position: cash-tender sales, deposits recorded, and the
    undeposited cash still in the drawer."""
    _, err = _require_erp_admin()
    if err:
        return err
    conn = db()
    store = _stores_require_store(conn, store_id)
    if not store:
        conn.close()
        return jsonify(error="store not found"), 404
    rows = conn.execute(
        "SELECT * FROM erp_store_deposits WHERE store_id = ?"
        " ORDER BY deposit_date DESC, id DESC",
        (store_id,)).fetchall()
    cash = _stores_cash_tenders(conn, store_id)
    undeposited = _stores_undeposited_cash_cents(conn, store_id)
    conn.close()
    return jsonify(
        deposits=[_stores_deposit_dict(r) for r in rows],
        cash_tender_cents=cash,
        deposited_cents=cash - undeposited,
        undeposited_cash_cents=undeposited)


def _stores_checklist_dict(row):
    d = dict(row)
    try:
        d["items"] = json.loads(d.get("items_json") or "[]") or []
    except (TypeError, ValueError):
        d["items"] = []
    d.pop("items_json", None)
    return d


def _stores_checklist_validate(data, kind):
    """Validate a checklist's items against the fixed template for
    its kind. Every template item must appear exactly once, with a
    true/false checked flag and an optional note. Returns the
    cleaned item list, or (None, error-response-tuple)."""
    template = _STORES_CHECKLIST_TEMPLATES[kind]
    labels = dict(template)
    raw = data.get("items")
    if not isinstance(raw, list) or not raw:
        return None, (jsonify(
            error="items must be a non-empty list"), 400)
    seen = set()
    cleaned = []
    for it in raw:
        if not isinstance(it, dict):
            return None, (jsonify(error="each item must be an object"), 400)
        key = (it.get("key") or "").strip()
        if key not in labels:
            return None, (jsonify(
                error="unknown checklist item '%s' for a %s checklist"
                      % (key, kind)), 400)
        if key in seen:
            return None, (jsonify(
                error="checklist item '%s' appears twice" % key), 400)
        seen.add(key)
        checked = it.get("checked")
        if not isinstance(checked, bool):
            return None, (jsonify(
                error="checklist item '%s' needs a true/false checked"
                      " flag" % key), 400)
        cleaned.append({"key": key, "label": labels[key],
                        "checked": checked,
                        "note": (it.get("note") or "").strip()[:500]})
    missing = [k for k, _ in template if k not in seen]
    if missing:
        return None, (jsonify(
            error="checklist is missing items: %s" % ", ".join(missing)),
            400)
    return cleaned, None


@app.post("/api/erp/stores/<int:store_id>/checklists")
def stores_checklist_create(store_id):
    """Complete one daily checklist: one Open and one Close per store
    per day. The item list is fixed per kind (see the templates);
    each item is checked true/false with an optional note."""
    actor, err = _require_erp_admin()
    if err:
        return err
    data = request.get_json(force=True) or {}
    conn = db()
    store = _stores_require_store(conn, store_id)
    if not store:
        conn.close()
        return jsonify(error="store not found"), 404
    cdate = (data.get("checklist_date") or "").strip()
    if not _legal_valid_date(cdate):
        conn.close()
        return jsonify(error="checklist_date must be YYYY-MM-DD"), 400
    kind = (data.get("kind") or "").strip()
    if kind not in _STORES_CHECKLIST_TEMPLATES:
        conn.close()
        return jsonify(error="kind must be open or close"), 400
    cleaned, verr = _stores_checklist_validate(data, kind)
    if verr:
        conn.close()
        return verr
    completed_by = (data.get("completed_by") or "").strip() or actor
    now = datetime.now(timezone.utc).isoformat()
    try:
        cur = conn.execute(
            "INSERT INTO erp_store_checklists (store_id, checklist_date,"
            " kind, items_json, completed_by, completed_at, created_by,"
            " created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?)",
            (store_id, cdate, kind, json.dumps(cleaned), completed_by,
             now, actor, now))
    except sqlite3.IntegrityError:
        conn.close()
        return jsonify(
            error="a %s checklist already exists for %s"
                  % (kind, cdate)), 409
    row = conn.execute(
        "SELECT * FROM erp_store_checklists WHERE id = ?",
        (cur.lastrowid,)).fetchone()
    conn.commit()
    conn.close()
    return jsonify(checklist=_stores_checklist_dict(row)), 201


@app.get("/api/erp/stores/<int:store_id>/checklists")
def stores_checklist_list(store_id):
    """Daily checklists for a store, newest first. ?date=YYYY-MM-DD
    narrows to one day; ?from= / ?to= narrow to a range. The fixed
    item templates ride along so the form never hardcodes them."""
    _, err = _require_erp_admin()
    if err:
        return err
    conn = db()
    store = _stores_require_store(conn, store_id)
    if not store:
        conn.close()
        return jsonify(error="store not found"), 404
    date = (request.args.get("date") or "").strip()
    date_from = (request.args.get("from") or "").strip()
    date_to = (request.args.get("to") or "").strip()
    for d in (date, date_from, date_to):
        if d and not _legal_valid_date(d):
            conn.close()
            return jsonify(error="dates must be YYYY-MM-DD"), 400
    where = " WHERE store_id = ?"
    params = [store_id]
    if date:
        where += " AND checklist_date = ?"
        params.append(date)
    if date_from:
        where += " AND checklist_date >= ?"
        params.append(date_from)
    if date_to:
        where += " AND checklist_date <= ?"
        params.append(date_to)
    rows = conn.execute(
        "SELECT * FROM erp_store_checklists" + where +
        " ORDER BY checklist_date DESC, kind, id DESC",
        params).fetchall()
    conn.close()
    return jsonify(
        checklists=[_stores_checklist_dict(r) for r in rows],
        templates={k: [{"key": key, "label": label}
                      for key, label in v]
                   for k, v in _STORES_CHECKLIST_TEMPLATES.items()})


@app.post("/api/erp/stores/<int:store_id>/checklists/<int:checklist_id>/update")
def stores_checklist_update(store_id, checklist_id):
    """Correct a completed checklist: re-check items, fix a note, or
    change who completed it. The kind and date never change."""
    actor, err = _require_erp_admin()
    if err:
        return err
    data = request.get_json(force=True) or {}
    conn = db()
    row = conn.execute(
        "SELECT * FROM erp_store_checklists"
        " WHERE id = ? AND store_id = ?", (checklist_id, store_id)
        ).fetchone()
    if not row:
        conn.close()
        return jsonify(error="checklist not found"), 404
    cleaned, verr = _stores_checklist_validate(data, row["kind"])
    if verr:
        conn.close()
        return verr
    completed_by = (data.get("completed_by") or "").strip() \
        or row["completed_by"] or actor
    now = datetime.now(timezone.utc).isoformat()
    conn.execute(
        "UPDATE erp_store_checklists SET items_json = ?,"
        " completed_by = ?, completed_at = ? WHERE id = ?",
        (json.dumps(cleaned), completed_by, now, checklist_id))
    out = conn.execute(
        "SELECT * FROM erp_store_checklists WHERE id = ?",
        (checklist_id,)).fetchone()
    conn.commit()
    conn.close()
    return jsonify(checklist=_stores_checklist_dict(out))


def _stores_incident_dict(row):
    return dict(row)


def _stores_incident_validate(data, current=None):
    """Validate an incident report. Fields fall back to the stored
    row when updating. Returns (fields, None) or (None, error)."""
    current = current or {}
    incident_date = (data.get("incident_date")
                     if "incident_date" in data
                     else current.get("incident_date") or "").strip()
    if not _legal_valid_date(incident_date):
        return None, (jsonify(
            error="incident_date must be YYYY-MM-DD"), 400)
    itype = (data.get("type") if "type" in data
             else current.get("type") or "").strip()
    if itype not in _STORES_INCIDENT_TYPES:
        return None, (jsonify(
            error="type must be one of %s"
                  % ", ".join(_STORES_INCIDENT_TYPES)), 400)
    desc = (data.get("description") if "description" in data
            else current.get("description") or "").strip()
    if not desc:
        return None, (jsonify(error="description is required"), 400)
    people = (data.get("people") if "people" in data
              else current.get("people") or "").strip()[:1000]
    amount = current.get("amount_cents")
    if "amount_cents" in data:
        if data.get("amount_cents") is None:
            amount = None
        else:
            amount = _stores_int(data.get("amount_cents"))
            if amount is None or amount < 0:
                return None, (jsonify(
                    error="amount_cents must be a whole number of cents,"
                          " 0 or more"), 400)
    status = (data.get("status") if "status" in data
              else current.get("status") or "open").strip()
    if status not in _STORES_INCIDENT_STATUSES:
        return None, (jsonify(
            error="status must be one of %s"
                  % ", ".join(_STORES_INCIDENT_STATUSES)), 400)
    reported_by = (data.get("reported_by") if "reported_by" in data
                   else current.get("reported_by") or "").strip()[:200]
    resolution = (data.get("resolution_note")
                  if "resolution_note" in data
                  else current.get("resolution_note") or "").strip()[:2000]
    return {"incident_date": incident_date, "type": itype,
            "description": desc, "people": people, "amount_cents": amount,
            "status": status, "reported_by": reported_by,
            "resolution_note": resolution}, None


