def _stores_doc_status(expiry_date, today=None):
    """A store document's flag from its expiry date, like the
    Quality COA flags: expired when the date has passed, expiring
    within 30 days, current otherwise. No expiry date means current
    (the document does not expire)."""
    if not expiry_date:
        return "current", False, False
    if today is None:
        today = datetime.now(timezone.utc).date().isoformat()
    if expiry_date < today:
        return "expired", True, False
    from datetime import date as _date, timedelta as _td
    if _date.fromisoformat(expiry_date) <= _date.fromisoformat(today) \
            + _td(days=30):
        return "expiring", False, True
    return "current", False, False


def _stores_document_dict(row, today=None):
    d = dict(row)
    status, expired, expiring = _stores_doc_status(
        d.get("expiry_date") or "", today)
    d["status"] = status
    d["is_expired"] = expired
    d["is_expiring"] = expiring
    return d


def _stores_document_validate(data, current=None):
    """Validate a store document. Fields fall back to the stored row
    when updating. Returns (fields, None) or (None, error)."""
    current = current or {}
    doc_type = (data.get("doc_type") if "doc_type" in data
                else current.get("doc_type") or "").strip()
    if doc_type not in _STORES_DOC_TYPES:
        return None, (jsonify(
            error="doc_type must be one of %s"
                  % ", ".join(_STORES_DOC_TYPES)), 400)
    title = (data.get("title") if "title" in data
             else current.get("title") or "").strip()
    if not title:
        return None, (jsonify(error="title is required"), 400)
    reference = (data.get("reference") if "reference" in data
                 else current.get("reference") or "").strip()[:500]
    issued = (data.get("issued_date") if "issued_date" in data
              else current.get("issued_date") or "").strip()
    expiry = (data.get("expiry_date") if "expiry_date" in data
              else current.get("expiry_date") or "").strip()
    if issued and not _legal_valid_date(issued):
        return None, (jsonify(
            error="issued_date must be YYYY-MM-DD"), 400)
    if expiry and not _legal_valid_date(expiry):
        return None, (jsonify(
            error="expiry_date must be YYYY-MM-DD"), 400)
    if issued and expiry and expiry < issued:
        return None, (jsonify(
            error="expiry_date cannot be before issued_date"), 400)
    return {"doc_type": doc_type, "title": title,
            "reference": reference, "issued_date": issued,
            "expiry_date": expiry}, None


