def _stores_price_default(item_kind, item_key):
    """The register's default price for an item kind: $8 a bag,
    $24 for a 3-pack, $48 for a 6-pack. Merch has no register
    default -- a first merch change has no known previous price."""
    if item_kind == "flavor":
        return BAG_PRICE_CENTS
    if item_kind == "pack3":
        return 3 * BAG_PRICE_CENTS
    if item_kind == "pack6":
        return 6 * BAG_PRICE_CENTS
    return None


def _stores_effective_price(conn, store_id, item_kind, item_key,
                            on_date=None):
    """The price the register charges for a store+item on a date:
    the latest price change for that store+item effective on or
    before the date, else the default. A merch item with no change
    has no price (None) -- it is record-only, the register does not
    sell merch."""
    if on_date is None:
        on_date = datetime.now(timezone.utc).date().isoformat()
    row = conn.execute(
        "SELECT new_price_cents FROM erp_store_price_changes"
        " WHERE store_id = ? AND item_kind = ? AND item_key = ?"
        " AND effective_date <= ?"
        " ORDER BY effective_date DESC, id DESC LIMIT 1",
        (store_id, item_kind, item_key, on_date)).fetchone()
    if row is not None:
        return int(row["new_price_cents"])
    return _stores_price_default(item_kind, item_key)


def _stores_price_change_dict(row):
    return dict(row)


@app.post("/api/erp/stores/<int:store_id>/price-changes")
def stores_price_change_create(store_id):
    """Log a price change for a store and make it live: the register
    charges the latest change for a store+item effective on or
    before today. item_kind is flavor (item_key is one of the 25
    live flavors), pack3 (item_key '3-pack'), pack6 (item_key
    '6-pack'), or merch (item_key is the merch name or SKU as typed
    -- record-only, the register does not sell merch). old_price is
    worked out by the backend from the price in effect before this
    change; it is NULL when none is known. A reason is required --
    the log is the audit trail."""
    actor, err = _require_erp_admin()
    if err:
        return err
    data = request.get_json(force=True) or {}
    conn = db()
    store = _stores_require_store(conn, store_id)
    if not store:
        conn.close()
        return jsonify(error="store not found"), 404
    kind = (data.get("item_kind") or "").strip()
    if kind not in _STORES_PRICE_KINDS:
        conn.close()
        return jsonify(
            error="item_kind must be one of %s"
                  % ", ".join(_STORES_PRICE_KINDS)), 400
    key = (data.get("item_key") or "").strip()
    if kind == "flavor":
        if key not in FLAVORS:
            conn.close()
            return jsonify(
                error="item_key must be one of the 25 live flavors"), 400
    elif kind == "pack3":
        if key != "3-pack":
            conn.close()
            return jsonify(error="item_key must be '3-pack'"), 400
    elif kind == "pack6":
        if key != "6-pack":
            conn.close()
            return jsonify(error="item_key must be '6-pack'"), 400
    else:
        if not key or len(key) > 200:
            conn.close()
            return jsonify(
                error="item_key must be the merch name or SKU"), 400
    new_price = _stores_int(data.get("new_price_cents"))
    if new_price is None or new_price < 0:
        conn.close()
        return jsonify(
            error="new_price_cents must be a whole number of cents,"
                  " 0 or more"), 400
    reason = (data.get("reason") or "").strip()
    if not reason:
        conn.close()
        return jsonify(error="reason is required"), 400
    if len(reason) > 500:
        conn.close()
        return jsonify(error="reason is too long"), 400
    eff = (data.get("effective_date") or "").strip()
    if not _legal_valid_date(eff):
        conn.close()
        return jsonify(error="effective_date must be YYYY-MM-DD"), 400
    old_price = _stores_effective_price(
        conn, store_id, kind, key,
        on_date=(datetime.strptime(eff, "%Y-%m-%d").date()
                 - timedelta(days=1)).isoformat())
    now = datetime.now(timezone.utc).isoformat()
    cur = conn.execute(
        "INSERT INTO erp_store_price_changes (store_id, item_kind,"
        " item_key, old_price_cents, new_price_cents, reason,"
        " effective_date, created_by, created_at)"
        " VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)",
        (store_id, kind, key, old_price, new_price, reason, eff,
         actor, now))
    row = conn.execute(
        "SELECT * FROM erp_store_price_changes WHERE id = ?",
        (cur.lastrowid,)).fetchone()
    conn.commit()
    conn.close()
    return jsonify(price_change=_stores_price_change_dict(row)), 201


