@app.get("/api/erp/stores/<int:store_id>/register-catalog")
def stores_register_catalog(store_id):
    """Register catalog: the 25 live flavors with their category and
    the price the register charges today -- the latest price change
    for this store+item effective on or before today, else the $8
    bag price from BAG_PRICE_CENTS. Pack prices are the store's
    effective pack prices, else 3 x $8 / 6 x $8. Each flavor carries
    its own price_cents; bag_price_cents stays the default for the
    headline."""
    _, err = _require_erp_admin()
    if err:
        return err
    conn = db()
    store = conn.execute(
        "SELECT * FROM erp_stores WHERE id = ?", (store_id,)).fetchone()
    if not store:
        conn.close()
        return jsonify(error="store not found"), 404
    cats = {r["flavor_name"]: r["category"] for r in conn.execute(
        "SELECT flavor_name, category FROM erp_flavor_categories"
        ).fetchall()}
    today = datetime.now(timezone.utc).date().isoformat()
    prices = {f: _stores_effective_price(conn, store_id, "flavor", f,
                                         today) for f in FLAVORS}
    pack_3 = _stores_effective_price(conn, store_id, "pack3", "3-pack",
                                     today)
    pack_6 = _stores_effective_price(conn, store_id, "pack6", "6-pack",
                                     today)
    any_override = any(p != BAG_PRICE_CENTS for p in prices.values()) \
        or pack_3 != 3 * BAG_PRICE_CENTS \
        or pack_6 != 6 * BAG_PRICE_CENTS
    conn.close()
    return jsonify(store_id=store_id, store_name=store["name"],
                   bag_price_cents=BAG_PRICE_CENTS,
                   pack_3_cents=pack_3,
                   pack_6_cents=pack_6,
                   has_price_changes=any_override,
                   pack_pricing_note=(
                       "Prices include this store's price changes"
                       " (effective today)."
                       if any_override else
                       "3-packs and 6-packs are priced as"
                       " 3 x $8 and 6 x $8 -- no separate pack price exists"
                       " in the backend."),
                   flavors=[{"name": f, "category": cats.get(f, ""),
                             "price_cents": prices[f]}
                            for f in FLAVORS])


