@app.get("/api/erp/accounting/statements.csv")
def erp_acct_statement_csv():
    actor, err = _erp_check_perm("accounting.read")
    if err:
        return err
    conn = db()
    customer, err = _acct_resolve_statement_customer(conn)
    if err:
        conn.close()
        return err
    params, err = _acct_statement_params()
    if err:
        conn.close()
        return err
    start, end = params
    st = _acct_customer_statement(conn, customer, start, end)
    # Dept 10 Wave A (item 1): the CSV names the company from the profile.
    company = _erp_company_profile(conn)
    conn.close()
    rows = [["Company", company["legal_name"]],
            ["Office address", company["office_address"]],
            ["Customer", st["customer"]["customer_name"]],
            ["Period", "%s to %s" % (start, end)],
            ["Opening balance", _acct_money_csv(st["opening_balance_cents"])],
            [],
            ["Date", "Type", "Reference", "Description", "Amount",
             "Balance"]]
    running = st["opening_balance_cents"]
    for line in st["lines"]:
        running += line["amount_cents"]
        rows.append([line["date"], line["kind"],
                     ("Invoice #%d" % line["invoice_id"]
                      if line["invoice_id"] else ""),
                     line["description"],
                     _acct_money_csv(line["amount_cents"]),
                     _acct_money_csv(running)])
    rows.append([])
    rows.append(["", "", "", "Invoiced",
                 _acct_money_csv(st["invoiced_cents"]), ""])
    rows.append(["", "", "", "Payments",
                 _acct_money_csv(-st["payments_cents"]), ""])
    rows.append(["", "", "", "Credits",
                 _acct_money_csv(-st["credits_cents"]), ""])
    rows.append(["", "", "", "Closing balance",
                 _acct_money_csv(st["balance_cents"]), ""])
    rows.append([])
    for b, label in (("current", "Current"), ("d1_30", "1-30 days"),
                     ("d31_60", "31-60 days"), ("d61_90", "61-90 days"),
                     ("d91_plus", "91+ days")):
        rows.append(["Aging", label, "",
                     _acct_money_csv(st["aging"][b]), "", ""])
    safe = "".join(ch if ch.isalnum() else "_" for ch in
                   st["customer"]["customer_name"])[:40] or "customer"
    return _acct_csv_response(
        "statement-%s-%s-to-%s.csv" % (safe, start, end),
        ["Customer statement"], rows)


@app.get("/api/erp/accounting/snapshot")
def erp_acct_snapshot():
    actor, err = _erp_check_perm("accounting.read")
    if err:
        return err
    as_of = (request.args.get("as_of") or "").strip() \
        or datetime.now(timezone.utc).date().isoformat()
    start = (request.args.get("start") or "").strip()
    end = (request.args.get("end") or "").strip() or as_of
    if not _acct_valid_date(as_of) or not _acct_valid_date(end):
        return jsonify(error="as_of and end must be YYYY-MM-DD"), 400
    if start and not _acct_valid_date(start):
        return jsonify(error="start must be YYYY-MM-DD"), 400
    if not start:
        start = end[:8] + "01"
    if start > end or end > as_of:
        return jsonify(
            error="start must not be after end, and end must not be after as_of"), 400
    conn = db()
    out = _acct_snapshot(conn, as_of, start, end)
    conn.close()
    return jsonify(out)


# ---- Budgets vs actual + treasury cash view (Dept 9, big-company
# package, modules B + K) ----
# Module B: MONTHLY budgets (period YYYY-MM), one row per account per
# month. Monthly matches how this ERP already thinks in months --
# period locks are YYYY-MM, tax filings are monthly, the P&L takes a
# date range -- and a quarter is just the sum of its three months, so
# the variance endpoint rolls months into quarters instead of storing
# a second period shape. Budgets are PLANNING data: they never post to
# the ledger and never touch the trial balance. Only income and expense
# accounts can be budgeted (a balance-sheet account has no P&L
# "actual" to compare against); actuals come from _acct_balances, the
# same source the P&L uses. A period/account with no budget row is
# reported as unbudgeted, never as zero-spent. All four budget
# endpoints and the treasury endpoint are admin-only via
# _require_erp_admin() -- stricter than Dept 9's usual
# accounting.read/write, per the build brief for these two modules.
# Module K: a read-only treasury view over the same data -- cash-account
# GL balances (via _acct_cash_account_ids + _acct_balances, the same
# computation the cash-flow report uses) plus a forecast that is just
# the schedule of open invoices (money in) and open bills (money out)
# by due date. No new tables, no data entry, nothing invented: the
# forecast assumes every open item settles in full on its due date,
# and says so in the response and on screen.
ERP_ACCT_BUDGET_QUARTER_RE = re.compile(r"^\d{4}-Q[1-4]$")


def _acct_budget_month_range(period):
    """(start, end) dates for a YYYY-MM period, or (None, None)."""
    if not _acct_period_valid(period):
        return None, None
    year, month = int(period[:4]), int(period[5:7])
    first = datetime(year, month, 1)
    nxt = datetime(year + (month == 12), month % 12 + 1, 1)
    last = (nxt - timedelta(days=1)).strftime("%Y-%m-%d")
    return first.strftime("%Y-%m-%d"), last


def _acct_budget_quarter_range(quarter):
    """(start, end, [YYYY-MM, ...]) for a YYYY-Qn quarter, or Nones."""
    if not isinstance(quarter, str) or not ERP_ACCT_BUDGET_QUARTER_RE.match(quarter):
        return None, None, []
    year = int(quarter[:4])
    q = int(quarter[6])
    months = ["%04d-%02d" % (year, (q - 1) * 3 + m) for m in (1, 2, 3)]
    start, _ = _acct_budget_month_range(months[0])
    _, end = _acct_budget_month_range(months[2])
    return start, end, months


def _acct_actual_cents(row):
    """Period activity for one _acct_balances row, signed the way the
    P&L reads it: income is credits minus debits, expense is debits
    minus credits. (Budgets only cover income/expense accounts.)"""
    if row["type"] == "income":
        return row["credits"] - row["debits"]
    return row["debits"] - row["credits"]


def _acct_budget_dict(conn, row):
    d = dict(row)
    acct = conn.execute(
        "SELECT code, name, type FROM erp_acct_accounts WHERE id = ?",
        (row["account_id"],)).fetchone()
    d["code"] = acct["code"] if acct else ""
    d["name"] = acct["name"] if acct else ""
    d["type"] = acct["type"] if acct else ""
    return d


def _acct_budget_variance(conn, start, end, periods):
    """Budget vs actual for [start, end]. `periods` is the list of
    YYYY-MM months whose budgets count (one for a month, three for a
    quarter, every month touched by a custom range -- a partial month
    still counts its whole monthly budget; see SOP 9.29). Actuals come
    from _acct_balances, the same source the P&L uses. Only
    income/expense accounts appear: budgeted ones in `rows`, accounts
    with activity but no budget in `unbudgeted` (never as zero-spent).
    Variance is actual minus budget; variance_pct is null when the
    budget is zero (a ratio against zero is meaningless, not 0%)."""
    bals = {r["id"]: r for r in _acct_balances(conn, start, end)}
    budgets = {}
    if periods:
        ph = ",".join("?" * len(periods))
        for b in conn.execute(
                "SELECT account_id, SUM(amount_cents) AS total"
                " FROM erp_acct_budgets WHERE period IN (" + ph + ")"
                " GROUP BY account_id", periods).fetchall():
            budgets[b["account_id"]] = b["total"]
    rows = []
    unbudgeted = []
    for acct in conn.execute(
            "SELECT * FROM erp_acct_accounts"
            " WHERE type IN ('income', 'expense') AND active = 1"
            " ORDER BY code").fetchall():
        bal = bals.get(acct["id"])
        actual = _acct_actual_cents(bal) if bal else 0
        if acct["id"] in budgets:
            budget = budgets[acct["id"]]
            var = actual - budget
            rows.append({"account_id": acct["id"], "code": acct["code"],
                         "name": acct["name"], "type": acct["type"],
                         "budget_cents": budget, "actual_cents": actual,
                         "variance_cents": var,
                         "variance_pct": (round(var * 100.0 / budget, 1)
                                        if budget != 0 else None),
                         "budgeted": True})
        elif actual != 0:
            unbudgeted.append({"account_id": acct["id"],
                               "code": acct["code"], "name": acct["name"],
                               "type": acct["type"], "budget_cents": None,
                               "actual_cents": actual,
                               "variance_cents": None,
                               "variance_pct": None, "budgeted": False})
    total_budget = sum(r["budget_cents"] for r in rows)
    total_actual = sum(r["actual_cents"] for r in rows)
    total_var = total_actual - total_budget
    return {"rows": rows, "unbudgeted": unbudgeted,
            "totals": {"budget_cents": total_budget,
                       "actual_cents": total_actual,
                       "variance_cents": total_var,
                       "variance_pct": (round(total_var * 100.0 / total_budget, 1)
                                      if total_budget != 0 else None),
                       "budgeted_account_count": len(rows),
                       "unbudgeted_account_count": len(unbudgeted),
                       "unbudgeted_actual_cents": sum(
                           u["actual_cents"] for u in unbudgeted)}}


@app.get("/api/erp/accounting/budgets")
def erp_acct_list_budgets():
    actor, err = _require_erp_admin()
    if err:
        return err
    period = (request.args.get("period") or "").strip()
    conn = db()
    if period:
        if not _acct_period_valid(period):
            conn.close()
            return jsonify(error="period must be YYYY-MM"), 400
        rows = conn.execute(
            "SELECT * FROM erp_acct_budgets WHERE period = ?"
            " ORDER BY account_id", (period,)).fetchall()
    else:
        rows = conn.execute(
            "SELECT * FROM erp_acct_budgets ORDER BY period, account_id"
            ).fetchall()
    out = [_acct_budget_dict(conn, r) for r in rows]
    conn.close()
    return jsonify(budgets=out)


@app.post("/api/erp/accounting/budgets")
def erp_acct_create_budget():
    """Upsert one monthly budget. A second save for the same account +
    month replaces the amount (200, created false); a first save
    creates it (201). Period locks do NOT gate budgets: they are
    planning data, not ledger postings, and comparing a locked month
    against its budget is the point of the variance view."""
    actor, err = _require_erp_admin()
    if err:
        return err
    data = request.get_json(force=True) or {}
    try:
        account_id = int(data.get("account_id") or 0)
    except (TypeError, ValueError):
        return jsonify(error="account_id must be a number"), 400
    period = (data.get("period") or "").strip()
    amount = _acct_int_cents(data.get("amount_cents"))
    if not _acct_period_valid(period):
        return jsonify(error="period must be YYYY-MM"), 400
    if amount is None or amount < 0:
        return jsonify(error="amount_cents must be whole cents of at least 0"), 400
    conn = db()
    acct = conn.execute(
        "SELECT * FROM erp_acct_accounts WHERE id = ?",
        (account_id,)).fetchone()
    if not acct:
        conn.close()
        return jsonify(error="unknown account_id %s" % account_id), 400
    if not acct["active"]:
        conn.close()
        return jsonify(error="account %s is inactive" % (acct["code"],)), 400
    if acct["type"] not in ("income", "expense"):
        conn.close()
        return jsonify(error="only income and expense accounts can be budgeted"), 400
    now = datetime.now(timezone.utc).isoformat()
    existing = conn.execute(
        "SELECT * FROM erp_acct_budgets WHERE account_id = ? AND period = ?",
        (account_id, period)).fetchone()
    if existing:
        conn.execute(
            "UPDATE erp_acct_budgets SET amount_cents = ?, updated_at = ?"
            " WHERE id = ?", (amount, now, existing["id"]))
        _acct_audit(conn, actor, "budget.update", "budget", existing["id"],
                    "%s %s %d -> %d" % (acct["code"], period,
                                        existing["amount_cents"], amount))
        budget_id, created = existing["id"], False
    else:
        cur = conn.execute(
            "INSERT INTO erp_acct_budgets (account_id, period, amount_cents,"
            " created_by, created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?)",
            (account_id, period, amount, actor or "", now, now))
        budget_id, created = cur.lastrowid, True
        _acct_audit(conn, actor, "budget.create", "budget", budget_id,
                    "%s %s %d" % (acct["code"], period, amount))
    conn.commit()
    row = conn.execute(
        "SELECT * FROM erp_acct_budgets WHERE id = ?", (budget_id,)).fetchone()
    out = _acct_budget_dict(conn, row)
    conn.close()
    return jsonify(budget=out, created=created), (201 if created else 200)


@app.delete("/api/erp/accounting/budgets/<int:budget_id>")
def erp_acct_delete_budget(budget_id):
    actor, err = _require_erp_admin()
    if err:
        return err
    conn = db()
    row = conn.execute(
        "SELECT * FROM erp_acct_budgets WHERE id = ?", (budget_id,)).fetchone()
    if not row:
        conn.close()
        return jsonify(error="budget not found"), 404
    acct = conn.execute(
        "SELECT code FROM erp_acct_accounts WHERE id = ?",
        (row["account_id"],)).fetchone()
    conn.execute("DELETE FROM erp_acct_budgets WHERE id = ?", (budget_id,))
    _acct_audit(conn, actor, "budget.delete", "budget", budget_id,
                "%s %s %d" % (acct["code"] if acct else "?",
                              row["period"], row["amount_cents"]))
    conn.commit()
    conn.close()
    return jsonify(deleted=budget_id)


# ---- Fixed assets + depreciation (Wave 3 B1, SOP 9.31) ----
# Straight-line only in v1. The monthly amount is computed server-side
# from the asset's own figures, never stored as a rate:
#   base = cost_cents - salvage_cents
#   regular month = base // useful_life_months
#   final month (index useful_life_months - 1) = base - regular * (life - 1)
# so the remainder lands on the final month and the asset depreciates
# to exactly its salvage value. Month index 0 is the placed-in-service
# month. A run posts one balanced journal per asset (Dr depreciation
# expense / Cr accumulated depreciation) through _acct_post_entry, so a
# locked month is refused with 400 exactly like every other posting.
# Source 'depreciation', source_id '<asset_id>:<YYYY-MM>' -- the same
# idempotency shape as the lease postings.


def _acct_fixed_month_index(placed_date, period):
    """0-based month index of `period` (YYYY-MM) after the
    placed-in-service month of `placed_date` (YYYY-MM-DD); negative
    before it."""
    try:
        year, month = int(period[:4]), int(period[5:7])
        py, pm = int(placed_date[:4]), int(placed_date[5:7])
    except (TypeError, ValueError):
        return -1
    return (year - py) * 12 + (month - pm)


def _acct_fixed_monthly_amount(asset, month_index):
    """Depreciation cents for one month index, or None when the asset
    does not depreciate that month (before placed-in-service, or past
    its useful life). The final month takes the remainder."""
    life = int(asset["useful_life_months"] or 0)
    if life <= 0 or month_index < 0 or month_index >= life:
        return None
    base = int(asset["cost_cents"] or 0) - int(asset["salvage_cents"] or 0)
    regular = base // life
    if month_index == life - 1:
        return base - regular * (life - 1)
    return regular


def _acct_fixed_last_day(period):
    """Last calendar day of a YYYY-MM period as YYYY-MM-DD (the
    posting date of that month's depreciation journals)."""
    year, month = int(period[:4]), int(period[5:7])
    if month == 12:
        first_next = datetime(year + 1, 1, 1)
    else:
        first_next = datetime(year, month + 1, 1)
    return (first_next - timedelta(days=1)).date().isoformat()


def _acct_fixed_asset_dict(conn, row):
    """An asset row plus computed figures (all derived, never stored):
    accumulated depreciation over posted runs, book value, the regular
    monthly amount, months posted, and whether it is fully depreciated."""
    d = dict(row)
    posted = conn.execute(
        "SELECT COUNT(*) AS n, COALESCE(SUM(amount_cents), 0) AS total"
        " FROM erp_acct_depreciation_runs"
        " WHERE asset_id = ? AND journal_entry_id IS NOT NULL",
        (row["id"],)).fetchone()
    d["months_posted"] = int(posted["n"])
    d["accumulated_depreciation_cents"] = int(posted["total"])
    d["book_value_cents"] = int(row["cost_cents"]) - int(posted["total"])
    base = int(row["cost_cents"]) - int(row["salvage_cents"] or 0)
    life = int(row["useful_life_months"] or 0)
    d["monthly_depreciation_cents"] = (base // life) if life > 0 else 0
    # Fully depreciated when the final month has posted, or the
    # accumulated total has reached the depreciable base. (A salvage
    # change after $0 months can leave an asset past its useful life
    # with book value above salvage -- the months already run or
    # skipped keep their amounts; only un-run months recompute.)
    d["fully_depreciated"] = bool(
        (life > 0 and int(posted["n"]) >= life)
        or (base > 0 and int(posted["total"]) >= base))
    return d


def _acct_fixed_run_dict(conn, row):
    d = dict(row)
    asset = conn.execute(
        "SELECT name FROM erp_acct_fixed_assets WHERE id = ?",
        (row["asset_id"],)).fetchone()
    d["asset_name"] = asset["name"] if asset else ""
    return d


def _acct_fixed_account_by_code(conn, code):
    return conn.execute(
        "SELECT * FROM erp_acct_accounts WHERE code = ?",
        ((code or "").strip(),)).fetchone()


def _acct_fixed_check_code(conn, code, want_type, label):
    """Error string when a GL code is unusable for `label`, else None:
    the code must exist, be active, and be of the expected type."""
    row = _acct_fixed_account_by_code(conn, code)
    if not row:
        return "unknown account code %s for %s" % (code, label)
    if not row["active"]:
        return "account %s for %s is inactive" % (code, label)
    if row["type"] != want_type:
        return "account %s for %s must be a %s account" % (
            code, label, want_type)
    return None


def _acct_fixed_int(value):
    """Strict whole-number parse (ints and digit strings only; bools
    and floats are rejected, like _acct_int_cents)."""
    if isinstance(value, bool):
        return None
    if isinstance(value, int):
        return value
    if isinstance(value, str) and value.strip().lstrip("-").isdigit():
        return int(value.strip())
    return None


@app.get("/api/erp/accounting/fixed-assets")
def erp_acct_list_fixed_assets():
    actor, err = _erp_check_perm("accounting.read")
    if err:
        return err
    conn = db()
    rows = conn.execute(
        "SELECT * FROM erp_acct_fixed_assets ORDER BY name, id").fetchall()
    out = [_acct_fixed_asset_dict(conn, r) for r in rows]
    conn.close()
    return jsonify(fixed_assets=out)


@app.post("/api/erp/accounting/fixed-assets")
def erp_acct_create_fixed_asset():
    """Create a fixed asset. The depreciation expense account is
    required: it has no invented default, the update endpoint cannot
    change it, and a run cannot post without it -- an asset without
    one could never depreciate. The asset and accumulated-depreciation
    accounts default to 1500 / 1510 when omitted."""
    actor, err = _erp_check_perm("accounting.write")
    if err:
        return err
    data = request.get_json(force=True, silent=True) or {}
    name = data.get("name")
    name = name.strip() if isinstance(name, str) else ""
    if not name:
        return jsonify(error="name is required"), 400
    asset_code = str(data.get("asset_account_code") or "1500").strip() or "1500"
    accum_code = str(data.get("accum_depr_account_code") or "1510").strip() or "1510"
    expense_code = data.get("depr_expense_account_code")
    expense_code = expense_code.strip() if isinstance(expense_code, str) else ""
    if not expense_code:
        return jsonify(
            error="depr_expense_account_code is required: pick the"
            " expense account each month's depreciation posts to"), 400
    cost = _acct_int_cents(data.get("cost_cents"))
    if cost is None or cost < 0:
        return jsonify(
            error="cost_cents must be whole cents of at least 0"), 400
    salvage = _acct_int_cents(data.get("salvage_cents", 0))
    if salvage is None or salvage < 0:
        return jsonify(
            error="salvage_cents must be whole cents of at least 0"), 400
    if salvage > cost:
        return jsonify(
            error="salvage_cents cannot exceed cost_cents"), 400
    life = _acct_fixed_int(data.get("useful_life_months"))
    if life is None or life <= 0:
        return jsonify(
            error="useful_life_months must be a whole number over 0"), 400
    placed = data.get("placed_in_service_date")
    placed = placed.strip() if isinstance(placed, str) else ""
    if not _acct_valid_date(placed):
        return jsonify(
            error="placed_in_service_date must be YYYY-MM-DD"), 400
    conn = db()
    for code, want, label in (
            (asset_code, "asset", "asset account"),
            (accum_code, "asset", "accumulated depreciation account"),
            (expense_code, "expense", "depreciation expense account")):
        error = _acct_fixed_check_code(conn, code, want, label)
        if error:
            conn.close()
            return jsonify(error=error), 400
    now = datetime.now(timezone.utc).isoformat()
    cur = conn.execute(
        "INSERT INTO erp_acct_fixed_assets (name, asset_account_code,"
        " accum_depr_account_code, depr_expense_account_code, cost_cents,"
        " placed_in_service_date, useful_life_months, salvage_cents,"
        " status, disposed_date, created_by, created_at, updated_by,"
        " updated_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, 'active', '',"
        " ?, ?, ?, ?)",
        (name, asset_code, accum_code, expense_code, cost, placed, life,
         salvage, actor or "", now, actor or "", now))
    asset_id = cur.lastrowid
    _acct_audit(conn, actor, "fixed_asset.create", "fixed_asset", asset_id,
                "%s cost %d placed %s life %d months salvage %d" % (
                    name, cost, placed, life, salvage))
    conn.commit()
    row = conn.execute(
        "SELECT * FROM erp_acct_fixed_assets WHERE id = ?",
        (asset_id,)).fetchone()
    out = _acct_fixed_asset_dict(conn, row)
    conn.close()
    return jsonify(asset=out), 201


@app.post("/api/erp/accounting/fixed-assets/<int:asset_id>/update")
def erp_acct_update_fixed_asset(asset_id):
    """Edit name / useful life / salvage only. Cost and the
    placed-in-service date are immutable after creation: a 400 when
    either key is present in the body, even unchanged -- the attempt
    itself is refused, so no caller can silently rewrite history.
    A shorter life may not drop below the months already depreciated,
    and a higher salvage may not exceed cost less depreciation already
    posted (either would leave the remaining schedule negative)."""
    actor, err = _erp_check_perm("accounting.write")
    if err:
        return err
    data = request.get_json(force=True, silent=True) or {}
    conn = db()
    row = conn.execute(
        "SELECT * FROM erp_acct_fixed_assets WHERE id = ?",
        (asset_id,)).fetchone()
    if not row:
        conn.close()
        return jsonify(error="fixed asset not found"), 404
    if "cost_cents" in data or "placed_in_service_date" in data:
        conn.close()
        return jsonify(
            error="cost_cents and placed_in_service_date cannot be"
            " changed after creation"), 400
    posted = conn.execute(
        "SELECT COUNT(*) AS n, COALESCE(SUM(amount_cents), 0) AS total"
        " FROM erp_acct_depreciation_runs"
        " WHERE asset_id = ? AND journal_entry_id IS NOT NULL",
        (asset_id,)).fetchone()
    changes = {}
    if "name" in data:
        name = data.get("name")
        name = name.strip() if isinstance(name, str) else ""
        if not name:
            conn.close()
            return jsonify(error="name is required"), 400
        if name != row["name"]:
            changes["name"] = name
    if "useful_life_months" in data:
        life = _acct_fixed_int(data.get("useful_life_months"))
        if life is None or life <= 0:
            conn.close()
            return jsonify(
                error="useful_life_months must be a whole number over 0"), 400
        if life < int(posted["n"]):
            conn.close()
            return jsonify(
                error="useful_life_months cannot be shorter than the %d"
                " month(s) already depreciated" % int(posted["n"])), 400
        if life != int(row["useful_life_months"]):
            changes["useful_life_months"] = life
    if "salvage_cents" in data:
        salvage = _acct_int_cents(data.get("salvage_cents"))
        if salvage is None or salvage < 0:
            conn.close()
            return jsonify(
                error="salvage_cents must be whole cents of at least 0"), 400
        if salvage > int(row["cost_cents"]) - int(posted["total"]):
            conn.close()
            return jsonify(
                error="salvage_cents cannot exceed cost less depreciation"
                " already posted"), 400
        if salvage != int(row["salvage_cents"]):
            changes["salvage_cents"] = salvage
    if not changes:
        out = _acct_fixed_asset_dict(conn, row)
        conn.close()
        return jsonify(asset=out, changed=False)
    now = datetime.now(timezone.utc).isoformat()
    sets = ", ".join("%s = ?" % k for k in changes)
    conn.execute(
        "UPDATE erp_acct_fixed_assets SET %s, updated_by = ?,"
        " updated_at = ? WHERE id = ?" % sets,
        tuple(changes.values()) + (actor or "", now, asset_id))
    detail = "; ".join(
        "%s: %s -> %s" % (k, row[k], v) for k, v in changes.items())
    audit_id = _acct_audit(conn, actor, "fixed_asset.update",
                           "fixed_asset", asset_id, detail)
    for field, value in changes.items():
        _erp_audit_change(conn, "acct", audit_id, field,
                          row[field], value)
    conn.commit()
    row = conn.execute(
        "SELECT * FROM erp_acct_fixed_assets WHERE id = ?",
        (asset_id,)).fetchone()
    out = _acct_fixed_asset_dict(conn, row)
    conn.close()
    return jsonify(asset=out, changed=True)


@app.delete("/api/erp/accounting/fixed-assets/<int:asset_id>")
def erp_acct_delete_fixed_asset(asset_id):
    """Permanent delete, two-tap in the UI. Refused 409 while any
    depreciation run has posted for the asset -- posted journal
    entries are permanent, so the asset that explains them stays;
    dispose it instead."""
    actor, err = _erp_check_perm("accounting.write")
    if err:
        return err
    conn = db()
    row = conn.execute(
        "SELECT * FROM erp_acct_fixed_assets WHERE id = ?",
        (asset_id,)).fetchone()
    if not row:
        conn.close()
        return jsonify(error="fixed asset not found"), 404
    posted = conn.execute(
        "SELECT COUNT(*) AS n FROM erp_acct_depreciation_runs"
        " WHERE asset_id = ? AND journal_entry_id IS NOT NULL",
        (asset_id,)).fetchone()["n"]
    if posted:
        conn.close()
        return jsonify(
            error="asset has posted depreciation runs; dispose it"
            " instead of deleting it"), 409
    _acct_audit(conn, actor, "fixed_asset.delete", "fixed_asset", asset_id,
                "%s cost %d" % (row["name"], int(row["cost_cents"])))
    conn.execute("DELETE FROM erp_acct_fixed_assets WHERE id = ?",
                 (asset_id,))
    conn.commit()
    conn.close()
    return jsonify(deleted=asset_id)


@app.post("/api/erp/accounting/fixed-assets/<int:asset_id>/dispose")
def erp_acct_dispose_fixed_asset(asset_id):
    """Mark an asset disposed (status + date). Disposed assets stop
    depreciating: future runs skip them. Past runs and their journals
    stay -- disposal never rewrites posted depreciation."""
    actor, err = _erp_check_perm("accounting.write")
    if err:
        return err
    data = request.get_json(force=True, silent=True) or {}
    conn = db()
    row = conn.execute(
        "SELECT * FROM erp_acct_fixed_assets WHERE id = ?",
        (asset_id,)).fetchone()
    if not row:
        conn.close()
        return jsonify(error="fixed asset not found"), 404
    if row["status"] == "disposed":
        conn.close()
        return jsonify(error="asset is already disposed"), 409
    disposed = data.get("disposed_date")
    disposed = disposed.strip() if isinstance(disposed, str) else ""
    if not disposed:
        disposed = datetime.now(timezone.utc).date().isoformat()
    if not _acct_valid_date(disposed):
        conn.close()
        return jsonify(error="disposed_date must be YYYY-MM-DD"), 400
    book = _acct_fixed_asset_dict(conn, row)["book_value_cents"]
    now = datetime.now(timezone.utc).isoformat()
    conn.execute(
        "UPDATE erp_acct_fixed_assets SET status = 'disposed',"
        " disposed_date = ?, updated_by = ?, updated_at = ? WHERE id = ?",
        (disposed, actor or "", now, asset_id))
    _acct_audit(conn, actor, "fixed_asset.dispose", "fixed_asset", asset_id,
                "%s disposed %s, book value %d" % (
                    row["name"], disposed, book))
    conn.commit()
    row = conn.execute(
        "SELECT * FROM erp_acct_fixed_assets WHERE id = ?",
        (asset_id,)).fetchone()
    out = _acct_fixed_asset_dict(conn, row)
    conn.close()
    return jsonify(asset=out)


@app.post("/api/erp/accounting/depreciation/run")
def erp_acct_run_depreciation():
    """Run one month of depreciation (period YYYY-MM). Posts one
    balanced journal per active asset that depreciates that month
    (Dr depreciation expense / Cr accumulated depreciation, dated the
    month's last day). Idempotent: a month with any run row is refused
    409. A locked month is refused 400. An asset that does not
    depreciate that month is skipped, never failed -- not yet in
    service, past its useful life, disposed, a $0 monthly amount, or no
    usable expense account -- and the response lists every skip with
    its reason, so a skipped asset is visible, never silent. If any
    posting fails partway through, the whole month rolls back."""
    actor, err = _erp_check_perm("accounting.write")
    if err:
        return err
    data = request.get_json(force=True, silent=True) or {}
    period = data.get("period")
    period = period.strip() if isinstance(period, str) else ""
    if not _acct_period_valid(period):
        return jsonify(error="period must be YYYY-MM"), 400
    conn = db()
    if _acct_period_locked(conn, period):
        conn.close()
        return jsonify(error="period %s is locked" % period), 400
    existing = conn.execute(
        "SELECT COUNT(*) AS n FROM erp_acct_depreciation_runs"
        " WHERE period = ?",
        (period,)).fetchone()["n"]
    if existing:
        conn.close()
        return jsonify(
            error="depreciation for period %s has already been run"
            % period), 409
    assets = conn.execute(
        "SELECT * FROM erp_acct_fixed_assets WHERE status = 'active'"
        " ORDER BY id").fetchall()
    posted, skipped = [], []
    post_date = _acct_fixed_last_day(period)
    for asset in assets:
        month_index = _acct_fixed_month_index(
            asset["placed_in_service_date"], period)
        if month_index < 0:
            skipped.append({"asset_id": asset["id"], "name": asset["name"],
                            "reason": "not yet in service in %s" % period})
            continue
        if month_index >= int(asset["useful_life_months"] or 0):
            skipped.append({"asset_id": asset["id"], "name": asset["name"],
                            "reason": "past its useful life"})
            continue
        amount = _acct_fixed_monthly_amount(asset, month_index)
        if amount is None or amount == 0:
            skipped.append({"asset_id": asset["id"], "name": asset["name"],
                            "reason": "monthly depreciation is $0.00"})
            continue
        expense_code = (asset["depr_expense_account_code"] or "").strip()
        if not expense_code:
            skipped.append({"asset_id": asset["id"], "name": asset["name"],
                            "reason": "no depreciation expense account set"})
            continue
        expense_id = _acct_account_id_by_code(conn, expense_code)
        accum_id = _acct_account_id_by_code(
            conn, asset["accum_depr_account_code"])
        if not expense_id or not accum_id:
            skipped.append({"asset_id": asset["id"], "name": asset["name"],
                            "reason": "depreciation or accumulated"
                            " depreciation account is unknown or inactive"})
            continue
        memo = "depreciation %s %s" % (asset["name"], period)
        lines = [
            {"account_id": expense_id, "debit_cents": amount,
             "credit_cents": 0, "memo": memo},
            {"account_id": accum_id, "debit_cents": 0,
             "credit_cents": amount, "memo": memo},
        ]
        entry_id, error = _acct_post_entry(
            conn, actor, post_date,
            "Depreciation %s %s" % (asset["name"], period),
            "depreciation", "%d:%s" % (asset["id"], period), lines)
        if error:
            conn.rollback()
            conn.close()
            return jsonify(error=error), 400
        now = datetime.now(timezone.utc).isoformat()
        cur = conn.execute(
            "INSERT INTO erp_acct_depreciation_runs (period, asset_id,"
            " amount_cents, journal_entry_id, created_by, created_at)"
            " VALUES (?, ?, ?, ?, ?, ?)",
            (period, asset["id"], amount, entry_id, actor or "", now))
        _acct_audit(conn, actor, "depreciation.run", "fixed_asset",
                    asset["id"],
                    "%s %s %d entry #%d" % (
                        asset["name"], period, amount, entry_id))
        posted.append(_acct_fixed_run_dict(conn, conn.execute(
            "SELECT * FROM erp_acct_depreciation_runs WHERE id = ?",
            (cur.lastrowid,)).fetchone()))
    conn.commit()
    conn.close()
    return jsonify(period=period, posted=posted, skipped=skipped), 201


@app.get("/api/erp/accounting/depreciation/runs")
def erp_acct_list_depreciation_runs():
    actor, err = _erp_check_perm("accounting.read")
    if err:
        return err
    period = (request.args.get("period") or "").strip()
    if period and not _acct_period_valid(period):
        return jsonify(error="period must be YYYY-MM"), 400
    asset_id = request.args.get("asset_id")
    try:
        asset_id = int(asset_id) if asset_id not in (None, "") else None
    except (TypeError, ValueError):
        return jsonify(error="asset_id must be a number"), 400
    conn = db()
    where, args = [], []
    if period:
        where.append("period = ?")
        args.append(period)
    if asset_id is not None:
        where.append("asset_id = ?")
        args.append(asset_id)
    sql = "SELECT * FROM erp_acct_depreciation_runs"
    if where:
        sql += " WHERE " + " AND ".join(where)
    sql += " ORDER BY period, asset_id"
    rows = conn.execute(sql, args).fetchall()
    out = [_acct_fixed_run_dict(conn, r) for r in rows]
    conn.close()
    return jsonify(runs=out)


# ---- Deferred revenue + revenue recognition (Wave 4 item 13, SOP 9.37) ----
# Recognising subscription and multi-period revenue over time instead
# of at cash receipt, with a deferred-revenue balance. A record is
# one prepay or subscription payment received for a period that
# extends beyond the current month: the admin enters the total
# received, the period it covers (start/end dates, from the real
# payment or subscription), and the revenue account it recognises
# into (default 4000 Sales -- Retail; 4100 Sales -- Wholesale for a
# wholesale prepay). The recognition method is straight-line over
# the covered months, the only method in v1, and it is stored on the
# record so a later method can never silently change figures.
#   schedule: computed at read time from the record's dates and
#   total, never stored. Month count is the calendar months from the
#   start month to the end month inclusive; a regular month is
#   total // month_count and the FINAL month takes the remainder
#   (total - regular * (n - 1)), so the schedule sums exactly to the
#   total and no month ever recognises more than the remaining
#   unrecognised balance.
#   recognising a month posts a real journal entry through
#   _acct_post_entry (Dr 2360 Deferred Revenue / Cr the record's
#   revenue account, dated the month's last day, source
#   "recognition", source_id "<record_id>:<YYYY-MM>"), so a locked
#   month is refused with 400 exactly like every other posting. A
#   month once recognised cannot be recognised twice: the endpoint
#   refuses with 409 while its entry stands. Reversal follows the
#   locked ledger rule -- reverse the journal entry (never delete
#   it); a reversed month frees up and can be recognised again.
#   creating a record posts NO journal entry: the cash receipt was
#   already posted by whatever path took the payment, and posting
#   again would double-count cash. The receipt belongs on 2360 (a
#   manual journal Dr cash / Cr 2360, or a reclass Dr income /
#   Cr 2360 when a receipt was wrongly posted to income). The
#   balance view reconciles the register against the 2360 ledger
#   balance and shows any discrepancy instead of hiding it.
#   gift-card liability is separate and untouched: gift cards live
#   on 2350 (SOP 9.8) and this module never reads or writes 2350 or
#   the gift_cards table. The register starts empty; the deferred
#   balance starts at zero. No subscription, prepay, or revenue is
#   ever invented: every record is admin-entered from a real payment
#   or subscription, and a kind="subscription" record may link an
#   existing ERP subscription by id (validated when given).
ERP_REVREC_KINDS = ("subscription", "general")
ERP_REVREC_METHODS = ("straight_line",)


def _acct_revrec_months(start_date, end_date):
    """Calendar months (YYYY-MM) from the start month to the end month
    inclusive, or [] when either date is not YYYY-MM-DD."""
    try:
        start = datetime.strptime(start_date, "%Y-%m-%d").date()
        end = datetime.strptime(end_date, "%Y-%m-%d").date()
    except (TypeError, ValueError):
        return []
    months = []
    year, month = start.year, start.month
    while (year, month) <= (end.year, end.month):
        months.append("%04d-%02d" % (year, month))
        month += 1
        if month > 12:
            month = 1
            year += 1
    return months


def _acct_revrec_recognitions(conn, deferred_id):
    """Recognition rows for one record, each with whether its journal
    entry still stands (entry_reversed False when the entry is live;
    a recognition whose entry is missing counts as standing -- entries
    are never deleted, so a missing one is a data problem, not a
    reversal)."""
    rows = conn.execute(
        "SELECT r.*, j.reversed_by AS entry_reversed_by"
        " FROM erp_acct_revenue_recognitions r"
        " LEFT JOIN erp_acct_journal j ON j.id = r.journal_entry_id"
        " WHERE r.deferred_id = ? ORDER BY r.period, r.id",
        (deferred_id,)).fetchall()
    out = []
    for r in rows:
        d = dict(r)
        d["entry_reversed"] = bool(r["entry_reversed_by"])
        out.append(d)
    return out


def _acct_revrec_schedule(record, recognitions):
    """The month-by-month schedule for a record dict: each month's
    amount, and whether it is recognised, reversed (recognised once,
    entry since reversed -- can be recognised again), or pending.
    Sums exactly to the record total by construction."""
    months = _acct_revrec_months(record["start_date"],
                                 record["end_date"])
    total = int(record["total_cents"] or 0)
    count = len(months)
    regular = total // count if count else 0
    by_period = {}
    for r in recognitions:
        by_period.setdefault(r["period"], []).append(r)
    schedule = []
    for i, period in enumerate(months):
        amount = (total - regular * (count - 1)) if i == count - 1 \
            else regular
        rows = by_period.get(period, [])
        live = [r for r in rows if not r["entry_reversed"]]
        if live:
            status = "recognised"
            entry_id = live[-1]["journal_entry_id"]
        elif rows:
            status = "reversed"
            entry_id = rows[-1]["journal_entry_id"]
        else:
            status = "pending"
            entry_id = None
        schedule.append({"period": period, "amount_cents": amount,
                         "status": status, "journal_entry_id": entry_id})
    return schedule


def _acct_revrec_recognised_cents(conn, deferred_id):
    """Cents recognised so far on one record: only recognitions whose
    journal entry still stands. A reversed recognition no longer
    counts -- the reversal already put the money back on 2360."""
    row = conn.execute(
        "SELECT COALESCE(SUM(r.amount_cents), 0) AS s"
        " FROM erp_acct_revenue_recognitions r"
        " LEFT JOIN erp_acct_journal j ON j.id = r.journal_entry_id"
        " WHERE r.deferred_id = ?"
        " AND (j.id IS NULL OR j.reversed_by IS NULL)",
        (deferred_id,)).fetchone()
    return int(row["s"] or 0)


def _acct_revrec_record_dict(conn, row):
    """A deferred-revenue row plus everything derived from it at read
    time: schedule, recognised and remaining cents, month count, and
    whether it is fully recognised. Nothing here is stored."""
    d = dict(row)
    recognitions = _acct_revrec_recognitions(conn, row["id"])
    d["schedule"] = _acct_revrec_schedule(d, recognitions)
    d["month_count"] = len(d["schedule"])
    d["recognised_cents"] = _acct_revrec_recognised_cents(conn,
                                                          row["id"])
    d["deferred_cents"] = (int(row["total_cents"] or 0)
                           - d["recognised_cents"])
    d["fully_recognised"] = d["deferred_cents"] <= 0
    d["recognitions"] = recognitions
    return d


def _acct_revrec_gl_balance_cents(conn):
    """The 2360 Deferred Revenue ledger balance (credits minus
    debits) over ALL journal lines on the account. A reversed entry
    and its reversal are both counted and cancel exactly (the
    reversal mirrors the original), so the balance is what the
    ledger actually owes -- including reversed pairs is what the
    trial balance does too. Excluding only the original would
    double-count the reversal."""
    row = conn.execute(
        "SELECT COALESCE(SUM(l.credit_cents - l.debit_cents), 0) AS s"
        " FROM erp_acct_journal_lines l"
        " JOIN erp_acct_journal j ON j.id = l.entry_id"
        " JOIN erp_acct_accounts a ON a.id = l.account_id"
        " WHERE a.code = ?",
        (ERP_ACCT_DEFERRED_REVENUE_CODE,)).fetchone()
    return int(row["s"] or 0)


def _acct_revrec_balance(conn):
    """The deferred-revenue balance view: register totals, the 2360
    ledger balance, and whether they reconcile. A mismatch is
    reported as a discrepancy with both figures, never hidden: it
    means a receipt was posted somewhere other than 2360 (or a
    recognition was posted without a register row), and the admin
    must fix the posting, not the register."""
    rows = conn.execute(
        "SELECT * FROM erp_acct_deferred_revenue ORDER BY id").fetchall()
    records = []
    total_received = 0
    total_recognised = 0
    for row in rows:
        d = _acct_revrec_record_dict(conn, row)
        total_received += int(row["total_cents"] or 0)
        total_recognised += d["recognised_cents"]
        records.append({"id": d["id"], "label": d["label"],
                        "kind": d["kind"],
                        "total_cents": int(row["total_cents"] or 0),
                        "recognised_cents": d["recognised_cents"],
                        "deferred_cents": d["deferred_cents"],
                        "fully_recognised": d["fully_recognised"]})
    register_balance = total_received - total_recognised
    gl_balance = _acct_revrec_gl_balance_cents(conn)
    return {"total_received_cents": total_received,
            "total_recognised_cents": total_recognised,
            "deferred_balance_cents": register_balance,
            "ledger_balance_cents": gl_balance,
            "reconciled": register_balance == gl_balance,
            "discrepancy_cents": register_balance - gl_balance,
            "record_count": len(records),
            "records": records}


