@app.post("/api/erp/accounting/expense-claims/<int:claim_id>/submit")
def erp_acct_submit_expense_claim(claim_id):
    """draft -> submitted, by the employee who filed the claim only.
    An admin cannot submit on the employee's behalf (the
    review-acknowledge ownership pattern)."""
    actor, err = _require_erp()
    if err:
        return err
    conn = db()
    row = _expense_claim_get(conn, claim_id)
    if not row:
        conn.close()
        return jsonify(error="expense claim not found"), 404
    mine = _hr_resolve_caller_employee(conn)
    if not mine or mine["id"] != row["employee_id"]:
        conn.close()
        return jsonify(error="only the employee who filed the claim"
                       " can submit it"), 403
    if row["status"] != "draft":
        conn.close()
        return jsonify(error="only a draft claim can be submitted"
                       " (status: %s)" % row["status"]), 400
    now = datetime.now(timezone.utc).isoformat()
    conn.execute(
        "UPDATE erp_acct_expense_claims SET status = 'submitted',"
        " submitted_by = ?, submitted_at = ?, updated_by = ?,"
        " updated_at = ? WHERE id = ?",
        (actor or "", now, actor or "", now, claim_id))
    _audit_id = _acct_audit(conn, actor, "expense_claim.submit",
                            "expense_claim", claim_id,
                            "claim #%d submitted" % claim_id)
    _erp_audit_change(conn, "acct", _audit_id, "status", "draft",
                      "submitted")
    conn.commit()
    row = _expense_claim_get(conn, claim_id)
    out = _expense_claim_dict(conn, row)
    conn.close()
    return jsonify(claim=out)


@app.post("/api/erp/accounting/expense-claims/<int:claim_id>/approve")
def erp_acct_approve_expense_claim(claim_id):
    """Approve a submitted claim (admin-only) and post it to the
    ledger: Dr expense account / Cr Accounts Payable 2000, dated the
    claim date, source "expense_claim". The expense account is
    admin-chosen per claim from the active expense accounts -- there
    is no default and no category-to-account mapping. A claim dated
    in a locked period is refused (400) and stays submitted."""
    actor, err = _require_erp_admin()
    if err:
        return err
    data = request.get_json(force=True, silent=True) or {}
    try:
        expense_account_id = int(data.get("expense_account_id") or 0)
    except (TypeError, ValueError):
        return jsonify(error="expense_account_id must be a number"), 400
    conn = db()
    row = _expense_claim_get(conn, claim_id)
    if not row:
        conn.close()
        return jsonify(error="expense claim not found"), 404
    if row["status"] != "submitted":
        conn.close()
        return jsonify(error="only a submitted claim can be approved"
                       " (status: %s)" % row["status"]), 400
    acct = conn.execute(
        "SELECT * FROM erp_acct_accounts WHERE id = ?",
        (expense_account_id,)).fetchone()
    if not acct:
        conn.close()
        return jsonify(error="unknown expense account"), 400
    if not acct["active"]:
        conn.close()
        return jsonify(error="account %s is inactive" % (acct["code"],)), 400
    if acct["type"] != "expense":
        conn.close()
        return jsonify(error="account %s is not an expense account"
                       % (acct["code"],)), 400
    ap_id = _acct_account_id_by_code(conn, ERP_ACCT_AP_CODE)
    if not ap_id:
        conn.close()
        return jsonify(error="chart of accounts is missing Accounts"
                       " Payable (2000)"), 500
    amount = row["amount_cents"]
    now = datetime.now(timezone.utc).isoformat()
    conn.execute("SAVEPOINT acct_expclaim_approve")
    memo = "Expense claim #%d -- %s" % (claim_id, row["description"] or "")
    entry_id, error = _acct_post_entry(
        conn, actor, row["date"], memo, "expense_claim", claim_id,
        [{"account_id": expense_account_id, "debit_cents": amount,
          "credit_cents": 0,
          "memo": "Expense claim #%d" % claim_id},
         {"account_id": ap_id, "debit_cents": 0, "credit_cents": amount,
          "memo": "Expense claim #%d" % claim_id}])
    if error:
        conn.execute("ROLLBACK TO SAVEPOINT acct_expclaim_approve")
        conn.execute("RELEASE SAVEPOINT acct_expclaim_approve")
        conn.close()
        return jsonify(error=error), 400
    conn.execute(
        "UPDATE erp_acct_expense_claims SET status = 'approved',"
        " expense_account_id = ?, journal_entry_id = ?,"
        " approved_by = ?, approved_at = ?, updated_by = ?,"
        " updated_at = ? WHERE id = ?",
        (expense_account_id, entry_id, actor or "", now, actor or "",
         now, claim_id))
    _audit_id = _acct_audit(conn, actor, "expense_claim.approve",
                            "expense_claim", claim_id,
                            "claim #%d approved, %d cents to %s, entry #%d"
                            % (claim_id, amount, acct["code"], entry_id))
    _erp_audit_change(conn, "acct", _audit_id, "status", "submitted",
                      "approved")
    conn.execute("RELEASE SAVEPOINT acct_expclaim_approve")
    conn.commit()
    row = _expense_claim_get(conn, claim_id)
    out = _expense_claim_dict(conn, row)
    conn.close()
    return jsonify(claim=out, journal_entry_id=entry_id)


@app.post("/api/erp/accounting/expense-claims/<int:claim_id>/reject")
def erp_acct_reject_expense_claim(claim_id):
    """Reject a submitted claim (admin-only, with a reason). Posts
    nothing to the ledger. A rejected claim can be deleted; it cannot
    be re-submitted -- file a new claim instead."""
    actor, err = _require_erp_admin()
    if err:
        return err
    data = request.get_json(force=True, silent=True) or {}
    reason = data.get("reason")
    reason = reason.strip() if isinstance(reason, str) else ""
    if not reason or len(reason) > 1000:
        return jsonify(error="reason is required and must be 1000"
                       " characters or fewer"), 400
    conn = db()
    row = _expense_claim_get(conn, claim_id)
    if not row:
        conn.close()
        return jsonify(error="expense claim not found"), 404
    if row["status"] != "submitted":
        conn.close()
        return jsonify(error="only a submitted claim can be rejected"
                       " (status: %s)" % row["status"]), 400
    now = datetime.now(timezone.utc).isoformat()
    conn.execute(
        "UPDATE erp_acct_expense_claims SET status = 'rejected',"
        " rejected_reason = ?, rejected_by = ?, rejected_at = ?,"
        " updated_by = ?, updated_at = ? WHERE id = ?",
        (reason, actor or "", now, actor or "", now, claim_id))
    _audit_id = _acct_audit(conn, actor, "expense_claim.reject",
                            "expense_claim", claim_id,
                            "claim #%d rejected: %s" % (claim_id, reason))
    _erp_audit_change(conn, "acct", _audit_id, "status", "submitted",
                      "rejected")
    conn.commit()
    row = _expense_claim_get(conn, claim_id)
    out = _expense_claim_dict(conn, row)
    conn.close()
    return jsonify(claim=out)


@app.post("/api/erp/accounting/expense-claims/<int:claim_id>/pay")
def erp_acct_pay_expense_claim(claim_id):
    """Mark an approved claim paid (admin-only) and post the payment
    to the ledger: Dr Accounts Payable 2000 / Cr cash, the bill
    payment shape -- an erp_acct_payments row (invoice_id and bill_id
    both NULL) plus the journal entry, source "payment". The cash leg
    uses the chosen bank account's GL account, or Checking --
    Operating (1010) when none is given (the same default as bill
    payments). payment_reference (check / transfer reference) is
    required. A claim dated in a locked period is refused (400)
    and stays approved."""
    actor, err = _require_erp_admin()
    if err:
        return err
    data = request.get_json(force=True, silent=True) or {}
    reference = data.get("payment_reference")
    reference = reference.strip() if isinstance(reference, str) else ""
    if not reference or len(reference) > 255:
        return jsonify(error="payment_reference is required and must"
                       " be 255 characters or fewer"), 400
    date = data.get("date")
    date = date.strip() if isinstance(date, str) else ""
    if not date:
        date = datetime.now(timezone.utc).date().isoformat()
    if not _acct_valid_date(date):
        return jsonify(error="date must be YYYY-MM-DD"), 400
    method = data.get("method")
    method = method.strip() if isinstance(method, str) else ""
    method = method or "cash"
    if len(method) > 100:
        return jsonify(error="method must be 100 characters or fewer"), 400
    bank_account_id = None
    if data.get("bank_account_id") not in (None, "", 0):
        try:
            bank_account_id = int(data.get("bank_account_id"))
        except (TypeError, ValueError):
            return jsonify(error="bank_account_id must be a number"), 400
    conn = db()
    row = _expense_claim_get(conn, claim_id)
    if not row:
        conn.close()
        return jsonify(error="expense claim not found"), 404
    if row["status"] != "approved":
        conn.close()
        return jsonify(error="only an approved claim can be paid"
                       " (status: %s)" % row["status"]), 400
    cash_id, bank_err = _acct_cash_account_id(conn, bank_account_id)
    ap_id = _acct_account_id_by_code(conn, ERP_ACCT_AP_CODE)
    if not cash_id or not ap_id or bank_err:
        conn.close()
        return jsonify(error=bank_err or
                       "chart of accounts is missing a required account"), 500
    amount = row["amount_cents"]
    now = datetime.now(timezone.utc).isoformat()
    conn.execute("SAVEPOINT acct_expclaim_pay")
    cur = conn.execute(
        "INSERT INTO erp_acct_payments (invoice_id, bill_id, date,"
        " amount_cents, method, bank_account_id, journal_entry_id,"
        " approval_note, qb_id, created_at)"
        " VALUES (NULL, NULL, ?, ?, ?, ?, NULL, ?, NULL, ?)",
        (date, amount, method, bank_account_id,
         "Expense claim #%d paid by %s (%s)"
         % (claim_id, actor or "", reference), now))
    pay_id = cur.lastrowid
    entry_id, error = _acct_post_entry(
        conn, actor, date, "Payment on expense claim #%d" % claim_id,
        "payment", claim_id,
        [{"account_id": ap_id, "debit_cents": amount, "credit_cents": 0,
          "memo": "Payment on expense claim #%d" % claim_id},
         {"account_id": cash_id, "debit_cents": 0, "credit_cents": amount,
          "memo": "Payment on expense claim #%d" % claim_id}])
    if error:
        conn.execute("ROLLBACK TO SAVEPOINT acct_expclaim_pay")
        conn.execute("RELEASE SAVEPOINT acct_expclaim_pay")
        conn.close()
        return jsonify(error=error), 400
    conn.execute(
        "UPDATE erp_acct_payments SET journal_entry_id = ? WHERE id = ?",
        (entry_id, pay_id))
    conn.execute(
        "UPDATE erp_acct_expense_claims SET status = 'paid',"
        " payment_id = ?, payment_journal_entry_id = ?, paid_date = ?,"
        " paid_by = ?, payment_reference = ?, updated_by = ?,"
        " updated_at = ? WHERE id = ?",
        (pay_id, entry_id, date, actor or "", reference, actor or "",
         now, claim_id))
    _audit_id = _acct_audit(conn, actor, "expense_claim.pay",
                            "expense_claim", claim_id,
                            "claim #%d paid %d cents via %s, payment #%d,"
                            " entry #%d"
                            % (claim_id, amount, method, pay_id, entry_id))
    _erp_audit_change(conn, "acct", _audit_id, "status", "approved",
                      "paid")
    conn.execute("RELEASE SAVEPOINT acct_expclaim_pay")
    conn.commit()
    row = _expense_claim_get(conn, claim_id)
    out = _expense_claim_dict(conn, row)
    conn.close()
    return jsonify(claim=out, journal_entry_id=entry_id, payment_id=pay_id)


@app.delete("/api/erp/accounting/expense-claims/<int:claim_id>")
def erp_acct_delete_expense_claim(claim_id):
    """Delete a claim permanently (admin-only). Draft and rejected
    claims delete; submitted, approved and paid claims are history
    and refuse (409) -- reject a submitted claim first, then delete
    it; an approved or paid claim is corrected with a reversing
    journal, never a delete. Deleting a claim never deletes its
    journal entry."""
    actor, err = _require_erp_admin()
    if err:
        return err
    conn = db()
    row = _expense_claim_get(conn, claim_id)
    if not row:
        conn.close()
        return jsonify(error="expense claim not found"), 404
    if row["status"] in ("submitted", "approved", "paid"):
        conn.close()
        return jsonify(error="a %s claim cannot be deleted"
                       % row["status"]), 409
    conn.execute("DELETE FROM erp_acct_expense_claims WHERE id = ?",
                 (claim_id,))
    _acct_audit(conn, actor, "expense_claim.delete", "expense_claim",
                claim_id, "claim #%d (%s, %d cents) deleted permanently"
                % (claim_id, row["status"], row["amount_cents"]))
    conn.commit()
    conn.close()
    return jsonify(ok=True)


@app.get("/api/erp/accounting/budgets/variance")
def erp_acct_budget_variance():
    actor, err = _require_erp_admin()
    if err:
        return err
    period = (request.args.get("period") or "").strip()
    quarter = (request.args.get("quarter") or "").strip()
    start = (request.args.get("start") or "").strip()
    end = (request.args.get("end") or "").strip()
    conn = db()
    if quarter:
        start, end, periods = _acct_budget_quarter_range(quarter)
        if start is None:
            conn.close()
            return jsonify(error="quarter must be YYYY-Q1 to YYYY-Q4"), 400
        kind, label = "quarter", quarter
    elif period:
        start, end = _acct_budget_month_range(period)
        if start is None:
            conn.close()
            return jsonify(error="period must be YYYY-MM"), 400
        periods, kind, label = [period], "month", period
    elif start or end:
        if not _acct_valid_date(start) or not _acct_valid_date(end) \
                or start > end:
            conn.close()
            return jsonify(
                error="start and end must be YYYY-MM-DD with start not after end"), 400
        periods = []
        cur = start[:7]
        while cur <= end[:7]:
            periods.append(cur)
            y, m = int(cur[:4]), int(cur[5:7])
            cur = "%04d-%02d" % (y + (m == 12), m % 12 + 1)
        kind, label = "range", "%s to %s" % (start, end)
    else:
        period = datetime.now(timezone.utc).strftime("%Y-%m")
        start, end = _acct_budget_month_range(period)
        periods, kind, label = [period], "month", period
    out = _acct_budget_variance(conn, start, end, periods)
    out.update({"kind": kind, "label": label,
                "period": period or None, "quarter": quarter or None,
                "start": start, "end": end})
    conn.close()
    return jsonify(out)


def _acct_treasury(conn, as_of):
    """Cash position + cash-flow forecast as of a date. Cash balances
    come from _acct_balances over _acct_cash_account_ids (the 1000
    hierarchy plus bank-linked GL accounts -- the same computation the
    cash-flow report uses for its ending cash, with the same
    liability-sign rule the snapshot uses for bank book balances).
    The forecast is the schedule of open invoices (money in) and open
    bills (money out) by due date, from the same open-document queries
    the aging endpoint uses. Nothing is invented: no future sales,
    payroll, or other commitments appear. Overdue items are listed at
    their due date and included in the projected balance as if settled
    today; the assumptions list says all of this in plain language."""
    cash_ids = _acct_cash_account_ids(conn)
    accounts = []
    total = 0
    for r in _acct_balances(conn, end=as_of):
        if r["id"] not in cash_ids:
            continue
        bal = (r["credits"] - r["debits"]) if r["type"] == "liability" \
            else (r["debits"] - r["credits"])
        accounts.append({"account_id": r["id"], "code": r["code"],
                         "name": r["name"], "balance_cents": bal})
        total += bal
    schedule = []
    for inv in conn.execute(
            "SELECT * FROM erp_acct_invoices WHERE status = 'open'"
            " AND balance_cents > 0 ORDER BY due_date, id").fetchall():
        schedule.append({"date": inv["due_date"], "kind": "in",
                         "ref": "Invoice #%d" % inv["id"],
                         "name": inv["customer_name"],
                         "amount_cents": inv["balance_cents"],
                         "overdue": inv["due_date"] < as_of})
    for bill in conn.execute(
            "SELECT * FROM erp_acct_bills WHERE status = 'open'"
            " AND balance_cents > 0 ORDER BY due_date, id").fetchall():
        schedule.append({"date": bill["due_date"], "kind": "out",
                         "ref": "Bill #%d" % bill["id"],
                         "name": bill["vendor_name"],
                         "amount_cents": bill["balance_cents"],
                         "overdue": bill["due_date"] < as_of})
    schedule.sort(key=lambda s: (s["date"],
                                 0 if s["kind"] == "in" else 1, s["ref"]))
    running = total
    for s in schedule:
        running += s["amount_cents"] if s["kind"] == "in" \
            else -s["amount_cents"]
        s["running_balance_cents"] = running
    expected_in = sum(s["amount_cents"] for s in schedule
                      if s["kind"] == "in")
    expected_out = sum(s["amount_cents"] for s in schedule
                       if s["kind"] == "out")
    overdue_in = sum(s["amount_cents"] for s in schedule
                     if s["kind"] == "in" and s["overdue"])
    overdue_out = sum(s["amount_cents"] for s in schedule
                      if s["kind"] == "out" and s["overdue"])
    empty = conn.execute(
        "SELECT COUNT(*) FROM erp_acct_journal").fetchone()[0] == 0 \
        and not schedule
    return {"as_of": as_of, "empty": empty,
            "cash": {"accounts": accounts, "total_cents": total},
            "schedule": schedule,
            "totals": {"expected_in_cents": expected_in,
                       "expected_out_cents": expected_out,
                       "overdue_in_cents": overdue_in,
                       "overdue_out_cents": overdue_out,
                       "open_invoice_count": sum(
                           1 for s in schedule if s["kind"] == "in"),
                       "open_bill_count": sum(
                           1 for s in schedule if s["kind"] == "out"),
                       "projected_balance_cents":
                           total + expected_in - expected_out},
            "assumptions": [
                "Assumes every open invoice is collected in full on its due date.",
                "Assumes every open bill is paid in full on its due date.",
                "Overdue items are included in the projected balance as if settled today.",
                "No future sales, payroll, or other commitments are included -- only open invoices and bills already in the ERP."]}


@app.get("/api/erp/accounting/treasury")
def erp_acct_treasury():
    actor, err = _require_erp_admin()
    if err:
        return err
    as_of = (request.args.get("as_of") or "").strip() \
        or datetime.now(timezone.utc).date().isoformat()
    if not _acct_valid_date(as_of):
        return jsonify(error="as_of must be YYYY-MM-DD"), 400
    conn = db()
    out = _acct_treasury(conn, as_of)
    conn.close()
    return jsonify(out)


# ---- 13-week cash-flow forecast (Wave 4 item 12, gap-analysis
# §3.11, SOP 9.36) ----
# Forward-looking, computed at read time from live data: no new
# table, nothing stored, and no projected balance is ever written
# back as a real balance. Opening cash is the Treasury cash total
# (the same computation the cash-flow report uses for its ending
# cash). Each of the 13 weeks runs from as_of: week 1 is as_of ..
# as_of+6, and so on. Inflows are open invoices (balance > 0) on
# their due date; outflows are open bills (balance > 0) on their due
# date plus approved-but-unpaid pay runs at net pay on their pay
# date. Overdue items land in week 1, flagged overdue, never
# silently rescheduled. Draft pay runs are not committed and are
# excluded (counted in the totals so the exclusion is visible);
# paid runs already left cash and sit in the opening balance.
# Recurring costs are $0: the ERP has no recurring-cost records, so
# nothing is projected and none is invented. Items due after the
# 13-week horizon are excluded from the weeks and reported as
# beyond-horizon totals, never dropped silently. Every forecast item
# is operating cash flow under the direct-method categories of the
# cash-flow statement (SOP 9.32): invoice collections, bill
# payments, payroll. A week is a shortfall week when its projected
# closing balance is below $0.00.
ERP_CASH_FORECAST_WEEKS = 13


def _acct_cash_forecast_week(as_of_d, due_d):
    """Week index (0-based) for a due date, or None past the horizon.
    A date before as_of is overdue and lands in week 1 (index 0)."""
    delta = (due_d - as_of_d).days
    if delta < 0:
        return 0
    if delta > ERP_CASH_FORECAST_WEEKS * 7 - 1:
        return None
    return delta // 7


def _acct_cash_forecast_date(text):
    """A YYYY-MM-DD string as a date, or None when it is not one."""
    try:
        return datetime.strptime(text, "%Y-%m-%d").date()
    except (TypeError, ValueError):
        return None


def _acct_cash_forecast(conn, as_of):
    """13-week forward cash projection as of a date. See the module
    comment above for the sources and the rules; the assumptions list
    in the response states them in plain language."""
    as_of_d = _acct_cash_forecast_date(as_of) \
        or datetime.now(timezone.utc).date()
    treasury = _acct_treasury(conn, as_of)
    opening = int(treasury["cash"]["total_cents"] or 0)
    horizon_end = (as_of_d
                   + timedelta(days=ERP_CASH_FORECAST_WEEKS * 7 - 1))
    weeks = []
    for i in range(ERP_CASH_FORECAST_WEEKS):
        start = as_of_d + timedelta(days=7 * i)
        weeks.append({"week": i + 1, "start": start.isoformat(),
                      "end": (start + timedelta(days=6)).isoformat(),
                      "opening_cents": opening, "inflows_cents": 0,
                      "invoices_cents": 0, "outflows_cents": 0,
                      "bills_cents": 0, "payroll_cents": 0,
                      "recurring_cents": 0, "closing_cents": opening,
                      "shortfall": False, "shortfall_cents": 0,
                      "items": []})
    beyond = []
    totals = {"opening_cash_cents": opening, "expected_in_cents": 0,
              "expected_out_cents": 0, "bills_cents": 0,
              "payroll_cents": 0, "recurring_cents": 0,
              "closing_cents": opening, "lowest_closing_cents": None,
              "lowest_closing_week": 1, "shortfall_weeks": [],
              "shortfall_count": 0,
              "open_invoice_count": 0, "open_bill_count": 0,
              "approved_payrun_count": 0, "draft_payrun_count": 0,
              "draft_payrun_cents": 0,
              "beyond_horizon_in_cents": 0,
              "beyond_horizon_out_cents": 0,
              "beyond_horizon_invoice_count": 0,
              "beyond_horizon_bill_count": 0,
              "beyond_horizon_payroll_cents": 0,
              "beyond_horizon_payrun_count": 0,
              "overdue_in_cents": int(
                  treasury["totals"]["overdue_in_cents"] or 0),
              "overdue_out_cents": int(
                  treasury["totals"]["overdue_out_cents"] or 0)}

    def _place(item, idx):
        if idx is None:
            beyond.append(item)
            return
        w = weeks[idx]
        w["items"].append(item)
        if item["kind"] == "in":
            w["inflows_cents"] += item["amount_cents"]
            w["invoices_cents"] += item["amount_cents"]
            totals["expected_in_cents"] += item["amount_cents"]
        else:
            w["outflows_cents"] += item["amount_cents"]
            totals["expected_out_cents"] += item["amount_cents"]
            if item["source"] == "bill":
                w["bills_cents"] += item["amount_cents"]
                totals["bills_cents"] += item["amount_cents"]
            elif item["source"] == "payroll":
                w["payroll_cents"] += item["amount_cents"]
                totals["payroll_cents"] += item["amount_cents"]

    for s in treasury["schedule"]:
        due = _acct_cash_forecast_date(s["date"])
        if due is None:
            continue
        idx = _acct_cash_forecast_week(as_of_d, due)
        item = {"date": s["date"], "kind": s["kind"],
                "source": "invoice" if s["kind"] == "in" else "bill",
                "section": "operating",
                "ref": s["ref"], "name": s["name"],
                "amount_cents": int(s["amount_cents"] or 0),
                "overdue": bool(s["overdue"])}
        if idx is None:
            if s["kind"] == "in":
                totals["beyond_horizon_in_cents"] += item["amount_cents"]
                totals["beyond_horizon_invoice_count"] += 1
            else:
                totals["beyond_horizon_out_cents"] += item["amount_cents"]
                totals["beyond_horizon_bill_count"] += 1
        elif s["kind"] == "in":
            totals["open_invoice_count"] += 1
        else:
            totals["open_bill_count"] += 1
        _place(item, idx)
    for run in conn.execute(
            "SELECT * FROM erp_acct_payruns WHERE status = 'approved'"
            " ORDER BY pay_date, id").fetchall():
        totals["approved_payrun_count"] += 1
        due = _acct_cash_forecast_date(run["pay_date"])
        if due is None:
            continue
        idx = _acct_cash_forecast_week(as_of_d, due)
        item = {"date": run["pay_date"], "kind": "out",
                "source": "payroll", "section": "operating",
                "ref": "Pay run #%d" % run["id"],
                "name": "Payroll %s to %s" % (run["period_start"],
                                              run["period_end"]),
                "amount_cents": int(run["net_cents"] or 0),
                "overdue": due < as_of_d}
        if idx is None:
            totals["beyond_horizon_out_cents"] += item["amount_cents"]
            totals["beyond_horizon_payroll_cents"] += item["amount_cents"]
            totals["beyond_horizon_payrun_count"] += 1
            beyond.append(item)
        else:
            _place(item, idx)
    draft = conn.execute(
        "SELECT COALESCE(SUM(net_cents), 0) AS s, COUNT(*) AS c"
        " FROM erp_acct_payruns WHERE status = 'draft'").fetchone()
    totals["draft_payrun_count"] = draft["c"]
    totals["draft_payrun_cents"] = int(draft["s"] or 0)
    running = opening
    for w in weeks:
        w["items"].sort(key=lambda it: (it["date"],
                                        0 if it["kind"] == "in" else 1,
                                        it["ref"]))
        w["opening_cents"] = running
        w["closing_cents"] = (running + w["inflows_cents"]
                              - w["outflows_cents"])
        w["shortfall"] = w["closing_cents"] < 0
        w["shortfall_cents"] = -w["closing_cents"] if w["shortfall"] \
            else 0
        if w["shortfall"]:
            totals["shortfall_weeks"].append(w["week"])
        if totals["lowest_closing_cents"] is None \
                or w["closing_cents"] < totals["lowest_closing_cents"]:
            totals["lowest_closing_cents"] = w["closing_cents"]
            totals["lowest_closing_week"] = w["week"]
        running = w["closing_cents"]
    totals["closing_cents"] = running
    totals["shortfall_count"] = len(totals["shortfall_weeks"])
    assumptions = [
        "Opening cash is the live GL balance of the cash accounts as"
        " of %s -- the same figure the Treasury tab shows. Projected"
        " balances are forecasts, never real balances." % as_of,
        "Every open invoice is collected in full on its due date."
        " Overdue invoices are expected in week 1, flagged overdue,"
        " not silently rescheduled.",
        "Every open bill is paid in full on its due date. Overdue"
        " bills fall in week 1, flagged overdue.",
        "Payroll is only approved pay runs not yet paid, at net pay"
        " on the pay date. Draft pay runs are not committed and are"
        " excluded (%d draft runs, $%s). Paid runs already left cash"
        " and are in the opening balance. Withheld and employer taxes"
        " leave cash when remitted, not on pay date, and no remittance"
        " is scheduled." % (totals["draft_payrun_count"],
                            _acct_money_csv(
                                totals["draft_payrun_cents"])),
        "Recurring costs are $0.00: the ERP has no recurring-cost"
        " records, so nothing is projected and no recurring cost is"
        " invented.",
        "No future sales, orders, owner draws, tax remittances, or"
        " other commitments are included -- only open invoices, open"
        " bills, and approved pay runs already in the ERP.",
        "A week is a shortfall week when its projected closing"
        " balance is below $0.00.",
        "Items due after the 13-week horizon (%s) are excluded from"
        " the weeks and listed as beyond-horizon totals, not"
        " dropped." % horizon_end.isoformat(),
        "Every forecast item is operating cash flow under the"
        " direct-method categories of the cash-flow statement"
        " (SOP 9.32): invoice collections, bill payments, payroll."
        " No investing or financing items are scheduled in this"
        " window.",
    ]
    return {"as_of": as_of, "week_count": ERP_CASH_FORECAST_WEEKS,
            "horizon_end": horizon_end.isoformat(),
            "cash": treasury["cash"],
            "empty": bool(treasury["empty"])
            and totals["approved_payrun_count"] == 0,
            "weeks": weeks, "beyond_horizon": beyond,
            "totals": totals, "assumptions": assumptions}


@app.get("/api/erp/accounting/cash-forecast")
def erp_acct_cash_forecast():
    actor, err = _require_erp_admin()
    if err:
        return err
    as_of = (request.args.get("as_of") or "").strip() \
        or datetime.now(timezone.utc).date().isoformat()
    if not _acct_valid_date(as_of):
        return jsonify(error="as_of must be YYYY-MM-DD"), 400
    conn = db()
    out = _acct_cash_forecast(conn, as_of)
    conn.close()
    return jsonify(out)


# ---- Accounting banking + reconciliation (Phase 1 step 3) ----
# Plaid amounts are stored as Plaid reports them: positive = money OUT,
# negative = money IN. The bank balance is opening balance minus the sum
# of feed amounts. Posted journal entries are never edited; matching only
# links a feed transaction to an entry.
ERP_ACCT_BANK_TYPES = ("checking", "savings", "credit_card", "loan", "other")
ERP_ACCT_TXN_STATUSES = ("unmatched", "matched", "review")


def _acct_bank_book_balance(conn, bank):
    """GL balance of the bank account's linked account. Asset-linked
    accounts read debit-minus-credit; liability-linked accounts
    (credit cards) read credit-minus-debit, i.e. the balance owed."""
    row = conn.execute(
        "SELECT COALESCE(SUM(debit_cents), 0) AS d,"
        " COALESCE(SUM(credit_cents), 0) AS c"
        " FROM erp_acct_journal_lines WHERE account_id = ?",
        (bank["gl_account_id"],)).fetchone()
    gl = conn.execute(
        "SELECT type FROM erp_acct_accounts WHERE id = ?",
        (bank["gl_account_id"],)).fetchone()
    if gl and gl["type"] == "liability":
        return row["c"] - row["d"]
    return row["d"] - row["c"]


def _acct_bank_bank_balance(conn, bank):
    """Bank balance from the feed: opening balance minus net outflows."""
    row = conn.execute(
        "SELECT COALESCE(SUM(amount_cents), 0) AS s"
        " FROM erp_acct_bank_txns WHERE bank_account_id = ?",
        (bank["id"],)).fetchone()
    return bank["opening_balance_cents"] - row["s"]


def _acct_bank_dict(conn, bank):
    d = dict(bank)
    gl = conn.execute(
        "SELECT id, code, name, type FROM erp_acct_accounts WHERE id = ?",
        (bank["gl_account_id"],)).fetchone()
    d["gl_account"] = dict(gl) if gl else None
    d["book_balance_cents"] = _acct_bank_book_balance(conn, bank)
    d["bank_balance_cents"] = _acct_bank_bank_balance(conn, bank)
    return d


def _acct_cash_account_id(conn, bank_account_id):
    """Resolve the GL account a payment's cash leg posts to.
    Returns (gl_account_id, None) or (None, error). No bank account
    given means the seeded Checking — Operating (1010)."""
    if bank_account_id in (None, "", 0):
        return _acct_account_id_by_code(conn, ERP_ACCT_CASH_CODE), None
    bank = conn.execute(
        "SELECT * FROM erp_acct_bank_accounts WHERE id = ?",
        (bank_account_id,)).fetchone()
    if not bank:
        return None, "unknown bank account"
    if not bank["active"]:
        return None, "bank account is inactive"
    gl = conn.execute(
        "SELECT * FROM erp_acct_accounts WHERE id = ?",
        (bank["gl_account_id"],)).fetchone()
    if not gl:
        return None, "bank account has no linked GL account"
    if not gl["active"]:
        return None, "linked GL account is inactive"
    return gl["id"], None


def _acct_auto_match(conn, bank, txn):
    """Exact amount+date auto-match (spec 2.4): an entry posted to the
    linked GL account on the same date whose net on that account equals
    the feed amount's mirror image (Plaid positive = outflow = a credit
    to the cash account). Skips reversed entries and entries already
    matched to another feed transaction. Returns the entry id or None."""
    net = -txn["amount_cents"]
    rows = conn.execute(
        "SELECT j.id FROM erp_acct_journal j"
        " JOIN erp_acct_journal_lines l ON l.entry_id = j.id"
        " WHERE l.account_id = ? AND j.date = ? AND j.reversed_by IS NULL"
        " GROUP BY j.id"
        " HAVING SUM(l.debit_cents - l.credit_cents) = ?",
        (bank["gl_account_id"], txn["date"], net)).fetchall()
    for r in rows:
        taken = conn.execute(
            "SELECT 1 FROM erp_acct_bank_txns WHERE matched_entry_id = ?",
            (r["id"],)).fetchone()
        if not taken:
            return r["id"]
    return None


def _acct_bank_txn_dict(row):
    return dict(row)


@app.get("/api/erp/accounting/bank-accounts")
def erp_acct_list_bank_accounts():
    actor, err = _erp_check_perm("accounting.read")
    if err:
        return err
    conn = db()
    rows = conn.execute(
        "SELECT * FROM erp_acct_bank_accounts ORDER BY name").fetchall()
    out = [_acct_bank_dict(conn, r) for r in rows]
    conn.close()
    return jsonify(bank_accounts=out)


@app.post("/api/erp/accounting/bank-accounts")
def erp_acct_create_bank_account():
    actor, err = _erp_check_perm("accounting.write")
    if err:
        return err
    data = request.get_json(force=True) or {}
    name = (data.get("name") or "").strip()
    btype = (data.get("type") or "").strip()
    if not name:
        return jsonify(error="name is required"), 400
    if btype not in ERP_ACCT_BANK_TYPES:
        return jsonify(
            error="type must be one of " + ", ".join(ERP_ACCT_BANK_TYPES)), 400
    gl_account_id = data.get("gl_account_id")
    if gl_account_id in (None, "", 0):
        return jsonify(error="gl_account_id is required"), 400
    try:
        gl_account_id = int(gl_account_id)
    except (TypeError, ValueError):
        return jsonify(error="gl_account_id must be a number"), 400
    opening = _acct_int_cents(data.get("opening_balance_cents", 0))
    if opening is None:
        return jsonify(error="opening_balance_cents must be whole cents"), 400
    plaid_account_id = (data.get("plaid_account_id") or "").strip() or None
    conn = db()
    gl = conn.execute(
        "SELECT * FROM erp_acct_accounts WHERE id = ?",
        (gl_account_id,)).fetchone()
    if not gl:
        conn.close()
        return jsonify(error="unknown gl_account_id"), 400
    if not gl["active"]:
        conn.close()
        return jsonify(error="linked GL account is inactive"), 400
    if gl["type"] not in ("asset", "liability"):
        conn.close()
        return jsonify(
            error="linked GL account must be an asset or liability account"), 400
    if plaid_account_id and conn.execute(
            "SELECT 1 FROM erp_acct_bank_accounts WHERE plaid_account_id = ?",
            (plaid_account_id,)).fetchone():
        conn.close()
        return jsonify(error="plaid_account_id is already linked"), 400
    now = datetime.now(timezone.utc).isoformat()
    cur = conn.execute(
        "INSERT INTO erp_acct_bank_accounts (name, type, plaid_account_id,"
        " gl_account_id, qb_id, opening_balance_cents, active,"
        " last_reconciled_at, created_at)"
        " VALUES (?, ?, ?, ?, ?, ?, 1, NULL, ?)",
        (name, btype, plaid_account_id, gl_account_id,
         (data.get("qb_id") or "").strip() or None, opening, now))
    bank_id = cur.lastrowid
    _acct_audit(conn, actor, "bank.create", "bank_account", bank_id,
                "%s %s -> GL %s" % (name, btype, gl["code"]))
    conn.commit()
    row = conn.execute(
        "SELECT * FROM erp_acct_bank_accounts WHERE id = ?",
        (bank_id,)).fetchone()
    out = _acct_bank_dict(conn, row)
    conn.close()
    return jsonify(bank_account=out), 201


@app.get("/api/erp/accounting/bank-accounts/<int:bank_id>/transactions")
def erp_acct_list_bank_txns(bank_id):
    actor, err = _erp_check_perm("accounting.read")
    if err:
        return err
    status = (request.args.get("status") or "").strip()
    if status and status not in ERP_ACCT_TXN_STATUSES:
        return jsonify(error="status must be one of " + ", ".join(
            ERP_ACCT_TXN_STATUSES)), 400
    conn = db()
    bank = conn.execute(
        "SELECT * FROM erp_acct_bank_accounts WHERE id = ?",
        (bank_id,)).fetchone()
    if not bank:
        conn.close()
        return jsonify(error="bank account not found"), 404
    if status:
        rows = conn.execute(
            "SELECT * FROM erp_acct_bank_txns"
            " WHERE bank_account_id = ? AND status = ?"
            " ORDER BY date DESC, id DESC",
            (bank_id, status)).fetchall()
    else:
        rows = conn.execute(
            "SELECT * FROM erp_acct_bank_txns WHERE bank_account_id = ?"
            " ORDER BY date DESC, id DESC",
            (bank_id,)).fetchall()
    conn.close()
    return jsonify(bank_account_id=bank_id,
                   transactions=[_acct_bank_txn_dict(r) for r in rows])


def _acct_ingest_bank_txns(conn, actor, rows):
    """Ingest bank-feed rows into erp_acct_bank_txns. Shared by the
    /bank-sync receiver and the Plaid sync path: idempotent on
    plaid_txn_id (a row already in the feed is skipped, never
    duplicated), exact amount+date auto-match against the linked GL
    account. Returns (inserted, skipped, auto_matched, errors). The
    caller commits and audits the sync summary; per-txn auto-matches
    are audited here. Does NOT post journal entries."""
    inserted = skipped = auto_matched = 0
    errors = []
    now = datetime.now(timezone.utc).isoformat()
    for i, raw in enumerate(rows):
        label = "row %d" % (i + 1)
        if not isinstance(raw, dict):
            errors.append("%s: not an object" % label)
            continue
        plaid_txn_id = (raw.get("plaid_txn_id") or "").strip()
        if not plaid_txn_id:
            errors.append("%s: plaid_txn_id is required" % label)
            continue
        bank = None
        if raw.get("bank_account_id") not in (None, "", 0):
            try:
                bank = conn.execute(
                    "SELECT * FROM erp_acct_bank_accounts WHERE id = ?",
                    (int(raw.get("bank_account_id")),)).fetchone()
            except (TypeError, ValueError):
                bank = None
            if not bank:
                errors.append("%s: unknown bank_account_id" % label)
                continue
        elif (raw.get("plaid_account_id") or "").strip():
            bank = conn.execute(
                "SELECT * FROM erp_acct_bank_accounts"
                " WHERE plaid_account_id = ?",
                ((raw.get("plaid_account_id") or "").strip(),)).fetchone()
            if not bank:
                errors.append(
                    "%s: no bank account linked to that Plaid account" % label)
                continue
        else:
            errors.append(
                "%s: bank_account_id or plaid_account_id is required" % label)
            continue
        date = (raw.get("date") or "").strip()
        if not _acct_valid_date(date):
            errors.append("%s: date must be YYYY-MM-DD" % label)
            continue
        amount = _acct_int_cents(raw.get("amount_cents"))
        if amount is None:
            errors.append("%s: amount_cents must be whole cents" % label)
            continue
        existing = conn.execute(
            "SELECT id FROM erp_acct_bank_txns WHERE plaid_txn_id = ?",
            (plaid_txn_id,)).fetchone()
        if existing:
            skipped += 1
            continue
        cur = conn.execute(
            "INSERT INTO erp_acct_bank_txns (bank_account_id, date,"
            " description, amount_cents, plaid_txn_id, matched_entry_id,"
            " status, created_at) VALUES (?, ?, ?, ?, ?, NULL, 'unmatched', ?)",
            (bank["id"], date, (raw.get("description") or "").strip(),
             amount, plaid_txn_id, now))
        txn_id = cur.lastrowid
        txn = conn.execute(
            "SELECT * FROM erp_acct_bank_txns WHERE id = ?",
            (txn_id,)).fetchone()
        inserted += 1
        entry_id = _acct_auto_match(conn, bank, txn)
        if entry_id:
            conn.execute(
                "UPDATE erp_acct_bank_txns SET matched_entry_id = ?,"
                " status = 'matched' WHERE id = ?",
                (entry_id, txn_id))
            auto_matched += 1
            _acct_audit(conn, actor, "bank.auto_match", "bank_txn", txn_id,
                        "txn #%d %s amount %d date %s auto-matched to entry #%d"
                        % (txn_id, plaid_txn_id, txn["amount_cents"],
                           txn["date"], entry_id))
    return inserted, skipped, auto_matched, errors



@app.post("/api/erp/accounting/bank-sync")
def erp_acct_bank_sync():
    """Ingest bank-feed transactions. The Railway backend holds no Plaid
    credentials and Plaid is not linked yet, so the feed arrives as
    transactions supplied in the request body — the path a Plaid-CLI sync
    job uses (plaid transactions-get, then POST here). Idempotent on
    plaid_txn_id: a row already in the feed is skipped, never duplicated.
    Exact amount+date matches against the linked GL account auto-match.
    Called with no transactions, the sync reports feed=not_configured."""
    actor, err = _erp_check_perm("accounting.write")
    if err:
        return err
    data = request.get_json(force=True) or {}
    rows = data.get("transactions")
    if not isinstance(rows, list) or not rows:
        return jsonify(ok=True, feed="not_configured", inserted=0, skipped=0,
                       auto_matched=0, errors=[],
                       message="No bank feed is linked yet. Link a bank"
                       " account in Plaid, then run a sync to pull"
                       " transactions into the feed.")
    conn = db()
    inserted, skipped, auto_matched, errors = _acct_ingest_bank_txns(
        conn, actor, rows)
    _acct_audit(conn, actor, "bank.sync", "bank_sync", 0,
                "inserted %d skipped %d auto_matched %d errors %d" % (
                    inserted, skipped, auto_matched, len(errors)))
    conn.commit()
    conn.close()
    return jsonify(ok=True, feed="ingested", inserted=inserted,
                   skipped=skipped, auto_matched=auto_matched, errors=errors)


# ---- ERP-vs-QuickBooks diff report + owner draws + Plaid sync ----
# (Dept 9, items 6+7+8, wave D)
# Item 6 reads the QuickBooks migration snapshot AT REQUEST TIME (never
# imported into the ledger) and compares it to the live ERP ledger to
# the cent. The snapshot is incomplete -- 58 of 83 monthly invoice
# windows, no vendor/bill/payment/journal-entry data at all -- so the
# report leads with coverage and marks everything it cannot compare as
# uncompared, never estimated and never zero.
# Item 7 records owner draws (DJ Nailing / Matt Wolberd) as
# request -> approve -> post Dr 3000 / Cr bank, audited at every step.
# Item 8 pulls Plaid transactions through the documented connector CLI
# and ingests them via the bank-sync receiver's own helper.
ERP_ACCT_OWNER_NAMES = ("DJ Nailing", "Matt Wolberd")
ERP_ACCT_EQUITY_CODE = "3000"
ERP_QB_SNAPSHOT_ENV = "ERP_QB_SNAPSHOT_PATH"
ERP_PLAID_CLI_ENV = "ERP_PLAID_CLI"
ERP_PLAID_CLI_DEFAULT = "/opt/hatch/bin/plaid"


ERP_QB_SNAPSHOT_VOLUME_PATH = "/data/qb-migration-snapshot.json"


def _acct_qb_snapshot_candidates():
    """Candidate snapshot locations in read order: the goal's
    hidden_files copy next to build/ (sandbox/dev), the Railway volume
    copy /data/qb-migration-snapshot.json (live -- the same volume
    that holds the database), then one next to app.py. The volume
    copy is checked before the beside-app.py copy so a snapshot
    uploaded live always wins over a stale repo copy."""
    here = os.path.dirname(os.path.abspath(__file__))
    return (os.path.join(here, "..", "hidden_files",
                         "qb-migration-snapshot.json"),
            ERP_QB_SNAPSHOT_VOLUME_PATH,
            os.path.join(here, "qb-migration-snapshot.json"))


def _acct_qb_snapshot_path():
    """Where the QB migration snapshot is read from at request time:
    ERP_QB_SNAPSHOT_PATH wins (tests point it at a fixture), else the
    first existing candidate from _acct_qb_snapshot_candidates().
    Returns the first existing path, or None."""
    env = (os.environ.get(ERP_QB_SNAPSHOT_ENV) or "").strip()
    if env:
        return env if os.path.isfile(env) else None
    for cand in _acct_qb_snapshot_candidates():
        if os.path.isfile(cand):
            return cand
    return None


def _acct_qb_snapshot_write_path():
    """Where an uploaded snapshot is stored: the ERP_QB_SNAPSHOT_PATH
    override when set (tests point it at a fixture), else the Railway
    volume file /data/qb-migration-snapshot.json. Never the repo: the
    snapshot holds QuickBooks financial data and must not be
    committed."""
    env = (os.environ.get(ERP_QB_SNAPSHOT_ENV) or "").strip()
    if env:
        return env
    return ERP_QB_SNAPSHOT_VOLUME_PATH


def _acct_qb_norm_name(name):
    """Match a QuickBooks account name to an ERP chart name: lowercase,
    drop parentheticals (\"Accounts Receivable (A/R)\" -> accounts
    receivable), drop punctuation, collapse whitespace."""
    n = (name or "").lower()
    n = re.sub(r"\([^)]*\)", " ", n)
    n = re.sub(r"[^a-z0-9]+", " ", n)
    return " ".join(n.split())


def _acct_qb_months(first_month, last_month):
    """YYYY-MM strings from first_month through last_month inclusive."""
    out = []
    y, m = int(first_month[:4]), int(first_month[5:7])
    ey, em = int(last_month[:4]), int(last_month[5:7])
    while (y, m) <= (ey, em):
        out.append("%04d-%02d" % (y, m))
        m += 1
        if m == 13:
            y, m = y + 1, 1
    return out


def _acct_qb_normal_balance(row):
    """ERP ledger balance in the account's normal direction, cents:
    assets/expenses debit-minus-credit, liabilities/equity/income
    credit-minus-debit. Matches how QuickBooks reports balances."""
    if row["type"] in ("asset", "expense"):
        return row["debits"] - row["credits"]
    return row["credits"] - row["debits"]


def _acct_qb_diff(conn, snap):
    """Build the diff report from the live ledger + a parsed snapshot.
    All money integer cents; a difference is erp minus qb. Anything
    the snapshot does not contain is status 'uncompared' (AP) or
    'not_available_in_snapshot', with qb values None -- never 0,
    never estimated."""
    meta = snap.get("meta") or {}
    ver = meta.get("verification") or {}
    types = meta.get("types") or {}
    windows_done = meta.get("invoice_windows_done") or []
    done_months = sorted({str(w[0])[:7] for w in windows_done
                          if isinstance(w, (list, tuple)) and w})
    as_of = (meta.get("as_of") or "").strip()
    if done_months and as_of and len(as_of) >= 7:
        expected = _acct_qb_months(done_months[0], as_of[:7])
    else:
        expected = list(done_months)
    missing_months = [m for m in expected if m not in set(done_months)]
    complete = bool(meta.get("complete"))
    coverage = {"windows_done": len(done_months),
                "windows_total": len(expected),
                "windows_missing": missing_months,
                "coverage_pct": (round(100.0 * len(done_months)
                                       / len(expected), 1)
                                 if expected else 0.0),
                "first_window": done_months[0] if done_months else None,
                "last_window": done_months[-1] if done_months else None,
                "as_of": as_of or None,
                "pulled_at": meta.get("pulled_at"),
                "company": meta.get("company"),
                "complete": complete,
                "invoice_count": len(snap.get("invoices") or []),
                "invoice_total_count": meta.get("invoice_total_count"),
                "types": {k: (v or {}).get("status")
                          for k, v in types.items()}}

    # --- chart of accounts: match by normalized name ---
    erp_rows = _acct_balances(conn)
    erp_by_norm = {}
    for r in erp_rows:
        erp_by_norm.setdefault(_acct_qb_norm_name(r["name"]), r)
    qb_accounts = snap.get("accounts") or []
    acct_rows = []
    used_erp = set()
    omitted_zero = 0
    for qa in qb_accounts:
        qname = qa.get("name") or ""
        qbal = qa.get("balance_cents")
        norm = _acct_qb_norm_name(qname)
        er = erp_by_norm.get(norm)
        if qbal is None:
            acct_rows.append(
                {"qb_name": qname, "qb_type": qa.get("type"),
                 "qb_balance_cents": None, "erp_code": er["code"] if er else None,
                 "erp_name": er["name"] if er else None,
                 "erp_balance_cents": (_acct_qb_normal_balance(er)
                                       if er else None),
                 "difference_cents": None, "status": "uncompared",
                 "note": "no balance in the snapshot (subtotal row)"})
            if er:
                used_erp.add(er["id"])
            continue
        if er:
            used_erp.add(er["id"])
            ebal = _acct_qb_normal_balance(er)
            acct_rows.append(
                {"qb_name": qname, "qb_type": qa.get("type"),
                 "qb_balance_cents": qbal, "erp_code": er["code"],
                 "erp_name": er["name"], "erp_balance_cents": ebal,
                 "difference_cents": ebal - qbal,
                 "status": "match" if ebal == qbal else "difference",
                 "note": ("3040 holds the migration residual only; see the"
                          " Net income reconciliation below."
                          if norm == "net income" and ebal != qbal else "")})
        else:
            acct_rows.append(
                {"qb_name": qname, "qb_type": qa.get("type"),
                 "qb_balance_cents": qbal, "erp_code": None,
                 "erp_name": None, "erp_balance_cents": None,
                 "difference_cents": None, "status": "qb_only",
                 "note": "no ERP chart account with this name"})
    for r in erp_rows:
        if r["id"] in used_erp:
            continue
        if _acct_qb_normal_balance(r) == 0:
            omitted_zero += 1
            continue
        acct_rows.append(
            {"qb_name": None, "qb_type": None, "qb_balance_cents": None,
             "erp_code": r["code"], "erp_name": r["name"],
             "erp_balance_cents": _acct_qb_normal_balance(r),
             "difference_cents": None, "status": "erp_only",
             "note": "no QuickBooks account with this name"})
    acct_rows.sort(key=lambda a: (a["qb_name"] or a["erp_name"] or ""))

    # --- AR: open-invoice balances per customer, ERP vs QB ---
    erp_ar = {}
    for inv in conn.execute(
            "SELECT customer_name, COALESCE(SUM(balance_cents), 0) AS bal"
            " FROM erp_acct_invoices WHERE status = 'open'"
            " GROUP BY customer_name").fetchall():
        if inv["bal"]:
            erp_ar[inv["customer_name"]] = inv["bal"]
    qb_ar = dict((ver.get("ar_customers") or {}))
    qb_ar_total = ver.get("ar_total_cents")
    erp_ar_total = sum(erp_ar.values())
    ar_rows = []
    for name in sorted(set(erp_ar) | set(qb_ar)):
        e, q = erp_ar.get(name), qb_ar.get(name)
        if e is not None and q is not None:
            status = "match" if e == q else "difference"
            diff = e - q
        elif e is not None:
            status, diff = "erp_only", None
        else:
            status, diff = "qb_only", None
        ar_rows.append({"customer_name": name, "erp_cents": e,
                        "qb_cents": q, "difference_cents": diff,
                        "status": status})
    ar = {"erp_total_cents": erp_ar_total,
          "qb_total_cents": qb_ar_total,
          "difference_cents": (erp_ar_total - qb_ar_total
                               if qb_ar_total is not None else None),
          "customers": ar_rows}

    # --- AP: the snapshot has no AP data (types.bills not_available,
    # ap_total_cents null) -- ERP vendors are listed uncompared, never
    # as a zero difference. ---
    erp_ap = {}
    for bill in conn.execute(
            "SELECT vendor_name, COALESCE(SUM(balance_cents), 0) AS bal"
            " FROM erp_acct_bills WHERE status = 'open'"
            " GROUP BY vendor_name").fetchall():
        if bill["bal"]:
            erp_ap[bill["vendor_name"]] = bill["bal"]
    ap_available = (types.get("bills", {}) or {}).get("status") == "pulled" \
        or (ver.get("ap_total_cents") is not None)
    qb_ap_total = ver.get("ap_total_cents")
    if qb_ap_total is None and ap_available:
        # Bills were pulled: the QB AP total is the open bills'
        # balances in the snapshot (0 when QuickBooks has no bills).
        qb_ap_total = sum(int(b.get("balance_cents") or 0)
                          for b in snap.get("bills") or []
                          if (b.get("status") or "") == "open")
    ap = {"erp_total_cents": sum(erp_ap.values()),
          "qb_total_cents": qb_ap_total,
          "difference_cents": (sum(erp_ap.values()) - qb_ap_total
                               if ap_available else None),
          "status": ("compared" if ap_available
                     else "not_available_in_snapshot"),
          "vendors": [{"vendor_name": n, "erp_cents": v,
                       "qb_cents": None, "difference_cents": None,
                       "status": "uncompared"}
                      for n, v in sorted(erp_ap.items())]}

    # --- trial balance totals ---
    total_debits = sum(r["debits"] for r in erp_rows)
    total_credits = sum(r["credits"] for r in erp_rows)
    bs = ver.get("balance_sheet") or {}
    qb_assets = bs.get("total_assets_cents")
    qb_liab = bs.get("total_liabilities_cents")
    qb_equity = bs.get("total_equity_cents")
    qb_balanced = (qb_assets is not None and qb_liab is not None
                   and qb_equity is not None
                   and qb_assets == qb_liab + qb_equity)
    trial = {"erp_total_debits_cents": total_debits,
             "erp_total_credits_cents": total_credits,
             "erp_balanced": total_debits == total_credits,
             "erp_difference_cents": total_debits - total_credits,
             "qb_total_assets_cents": qb_assets,
             "qb_total_liabilities_cents": qb_liab,
             "qb_total_equity_cents": qb_equity,
             "qb_balanced": qb_balanced,
             "note": "QuickBooks trial-balance detail is not compared"
                     " in this report; only the balance-sheet totals"
                     " above are shown."}

    # --- sales + net income reconciliation (Phase 1 gap 3) ---
    # ERP income accounts hold only what the migration actually posted:
    # open-invoice income, journal-entry income lines, and post-migration
    # retail sales. Paid invoices never post to ERP income -- their money
    # is in the bank balances and the opening entry -- so all-time
    # QuickBooks sales is NOT comparable; the comparable figure is the
    # income attributable to the posted documents. The old untraced
    # "Sales row" (ERP $24,628.60 vs QB $20,001.40) matches no account,
    # invoice total, or combination in the snapshot or the ledger, and
    # no endpoint ever computed it; this section replaces it with a
    # checkable reconciliation.
    erp_income_cents = sum(_acct_qb_normal_balance(r) for r in erp_rows
                           if r["type"] == "income")
    qb_open_invoice_cents = sum(
        int(i.get("subtotal_cents") or 0)
        for i in (snap.get("invoices") or [])
        if (i.get("status") or "") == "open")
    qb_type_by_norm = {}
    for qa in qb_accounts:
        qb_type_by_norm[_acct_qb_norm_name(qa.get("name") or "")] = qa.get("type")
    for cr in (snap.get("qb_chart") or []):
        qb_type_by_norm.setdefault(
            _acct_qb_norm_name(cr.get("name") or ""), cr.get("type"))
    qb_je_income_cents = 0
    for j in (snap.get("journal_entries") or []):
        for ln in (j.get("lines") or []):
            if qb_type_by_norm.get(
                    _acct_qb_norm_name(ln.get("account_name") or "")) == "income":
                qb_je_income_cents += (int(ln.get("credit_cents") or 0)
                                       - int(ln.get("debit_cents") or 0))
    retail_row = next((r for r in erp_rows
                       if r["code"] == ERP_ACCT_RETAIL_INCOME_CODE), None)
    retail_cents = _acct_qb_normal_balance(retail_row) if retail_row else 0
    qb_all_time_sales_cents = sum(
        int(i.get("subtotal_cents") or 0)
        for i in (snap.get("invoices") or []))
    sales_diff = (erp_income_cents - qb_open_invoice_cents
                  - qb_je_income_cents - retail_cents)
    sales = {"erp_income_cents": erp_income_cents,
             "qb_open_invoice_cents": qb_open_invoice_cents,
             "qb_je_income_cents": qb_je_income_cents,
             "erp_retail_cents": retail_cents,
             "difference_cents": sales_diff,
             "qb_all_time_sales_cents": qb_all_time_sales_cents,
             "status": "match" if sales_diff == 0 else "difference",
             "note": "ERP income is open-invoice income plus journal-entry"
                     " income plus post-migration retail. All-time"
                     " QuickBooks sales is not comparable: paid invoices"
                     " never post to ERP income (their money is in the"
                     " bank balances and the opening entry)."}
    qb_ni_row = next((a for a in qb_accounts
                      if _acct_qb_norm_name(a.get("name") or "") == "net income"),
                     None)
    qb_ni_cents = (qb_ni_row.get("balance_cents")
                   if qb_ni_row else None)
    erp_3040_row = next((r for r in erp_rows
                         if _acct_qb_norm_name(r["name"]) == "net income"),
                        None)
    erp_3040_cents = (_acct_qb_normal_balance(erp_3040_row)
                      if erp_3040_row else None)
    erp_pl_net_cents = _acct_net_income(erp_rows)
    ni_diff = None
    if qb_ni_cents is not None and erp_3040_cents is not None:
        ni_diff = (erp_3040_cents + erp_pl_net_cents - retail_cents
                   - qb_ni_cents)
    net_income = {"qb_net_income_cents": qb_ni_cents,
                  "erp_3040_cents": erp_3040_cents,
                  "erp_pl_net_cents": erp_pl_net_cents,
                  "erp_retail_cents": retail_cents,
                  "difference_cents": ni_diff,
                  "status": ("match" if ni_diff == 0 else
                             "difference" if ni_diff is not None else
                             "not_available_in_snapshot"),
                  "note": "QuickBooks folds all income and expense into"
                          " Net Income. The ERP keeps it split: the 3040"
                          " account holds only the migration residual,"
                          " the rest sits in the income/expense accounts."
                          " 3040 + P&L net income - post-migration retail"
                          " equals QuickBooks Net Income."}
    uncompared = []
    if missing_months:
        uncompared.append(
            "%d monthly invoice windows were not pulled (%s through"
            " %s); invoices, AR and balances from those months are"
            " uncompared" % (len(missing_months), missing_months[0],
                             missing_months[-1]))
    for key in ("vendors", "bills", "payments", "bank_transactions",
                "journal_entries"):
        st = (types.get(key, {}) or {}).get("status")
        if st != "pulled":
            uncompared.append(
                "QuickBooks %s: %s -- not compared"
                % (key, st or "missing from the snapshot"))
    if (types.get("payroll", {}) or {}).get("status") != "pulled":
        uncompared.append("QuickBooks payroll: not pulled -- not compared")
    if not ap_available:
        uncompared.append(
            "QuickBooks AP total is not in the snapshot -- AP is"
            " uncompared, not zero")

    compared = [a for a in acct_rows if a["status"] in ("match", "difference")]
    ar_compared = [c for c in ar_rows
                   if c["status"] in ("match", "difference")]
    all_match = (complete
                 and all(a["status"] == "match" for a in compared)
                 and all(c["status"] == "match" for c in ar_compared)
                 and ar["difference_cents"] == 0
                 and trial["erp_balanced"] and qb_balanced)
    return {"snapshot": coverage,
            "accounts": acct_rows,
            "accounts_erp_zero_balance_unmatched_omitted": omitted_zero,
            "receivables": ar,
            "payables": ap,
            "trial_balance": trial,
            "sales": sales,
            "net_income": net_income,
            "uncompared": uncompared,
            "status": "match" if all_match else (
                "incomplete" if not complete else "differences"),
            "match": all_match}


@app.get("/api/erp/accounting/qb-diff")
def erp_acct_qb_diff():
    """ERP-vs-QuickBooks diff report for the parallel run. Reads the
    migration snapshot at request time (see _acct_qb_snapshot_path);
    nothing is imported into the ledger. 404 when no snapshot file
    exists; the report itself states how partial the snapshot is."""
    actor, err = _erp_check_perm("accounting.read")
    if err:
        return err
    path = _acct_qb_snapshot_path()
    if not path:
        return jsonify(error="QuickBooks migration snapshot not found",
                       snapshot_status="missing"), 404
    try:
        with open(path, encoding="utf-8") as fh:
            snap = json.load(fh)
    except (OSError, ValueError) as exc:
        return jsonify(error="QuickBooks migration snapshot unreadable: %s"
                       % exc, snapshot_status="unreadable"), 500
    if not isinstance(snap, dict):
        return jsonify(error="QuickBooks migration snapshot is not an object",
                       snapshot_status="unreadable"), 500
    conn = db()
    out = _acct_qb_diff(conn, snap)
    conn.close()
    return jsonify(out)


@app.post("/api/erp/accounting/qb-snapshot")
def erp_acct_qb_snapshot_upload():
    """Store a QuickBooks migration snapshot so the qb-diff report can
    read it live. The snapshot lives on the Railway volume
    (/data/qb-migration-snapshot.json -- the same volume that holds
    the database), never in the repo: it holds QuickBooks financial
    data and must not be committed. Admin-only (accounting.write) or
    the cron secret, same pattern as the sales backfill. The body
    must be {"snapshot": {...}} with a meta dict and list-valued
    invoices/customers/accounts; anything else is 400 and writes
    nothing. Written atomically (temp file + os.replace) and audited
    as qb.snapshot_upload. The snapshot contents are never logged --
    the audit detail and the response carry counts only."""
    actor = None
    if CRON_SECRET and hmac.compare_digest(request.headers.get("X-Cron-Secret", ""), CRON_SECRET):
        actor = "cron"
    else:
        actor, err = _erp_check_perm("accounting.write")
        if err:
            return err
    data = request.get_json(silent=True)
    if not isinstance(data, dict) \
            or not isinstance(data.get("snapshot"), dict):
        return jsonify(error="body must be {\"snapshot\": {...}}"), 400
    snap = data["snapshot"]
    if not isinstance(snap.get("meta"), dict):
        return jsonify(error="snapshot.meta must be an object"), 400
    for key in ("invoices", "customers", "accounts"):
        if not isinstance(snap.get(key), list):
            return jsonify(error="snapshot.%s must be a list" % key), 400
    path = _acct_qb_snapshot_write_path()
    try:
        parent = os.path.dirname(path)
        if parent:
            os.makedirs(parent, exist_ok=True)
        fd, tmp = tempfile.mkstemp(prefix=".qb-snapshot-",
                                   dir=parent or ".")
        os.close(fd)
        try:
            with open(tmp, "w", encoding="utf-8") as fh:
                json.dump(snap, fh)
            os.replace(tmp, path)
        except BaseException:
            try:
                os.unlink(tmp)
            except OSError:
                pass
            raise
    except OSError as exc:
        return jsonify(error="could not store snapshot: %s" % exc), 500
    counts = {k: len(snap[k]) for k in ("invoices", "customers", "accounts")}
    conn = db()
    _acct_audit(conn, actor, "qb.snapshot_upload", "qb_snapshot", 0,
                "snapshot stored: %d invoices, %d customers, %d accounts"
                % (counts["invoices"], counts["customers"],
                   counts["accounts"]))
    conn.commit()
    conn.close()
    return jsonify(ok=True, stored=True, path=path,
                   invoices=counts["invoices"],
                   customers=counts["customers"],
                   accounts=counts["accounts"]), 201


@app.get("/api/erp/accounting/qb-snapshot")
def erp_acct_qb_snapshot_download():
    """Return the stored QuickBooks migration snapshot so the parent
    agent can verify it (acct_verify.py) and feed it to the
    migrate/import endpoint. Admin-only (accounting.write) or the cron
    secret, same pattern as the upload. 404 when no snapshot is
    stored. The snapshot holds QuickBooks financial data: it is
    returned only to an admin session or the cron secret, never to
    anonymous or customer callers, and it is never logged."""
    if CRON_SECRET and hmac.compare_digest(request.headers.get("X-Cron-Secret", ""), CRON_SECRET):
        pass
    else:
        actor, err = _erp_check_perm("accounting.write")
        if err:
            return err
    path = _acct_qb_snapshot_path()
    if not path:
        return jsonify(error="no QuickBooks migration snapshot stored"), 404
    try:
        with open(path, encoding="utf-8") as fh:
            snap = json.load(fh)
    except (OSError, ValueError) as exc:
        return jsonify(error="stored snapshot unreadable: %s" % exc), 500
    if not isinstance(snap, dict):
        return jsonify(error="stored snapshot is not an object"), 500
    return jsonify(snap)


# ---- QuickBooks OAuth pull: probe + invoice-window pull ----
# The migration pull (hidden_files/acct_migrate.py) reads QuickBooks
# through a SEPARATE connection (the QuickBooks MCP CLI) and has been
# 429-throttled since Nov 9. The ERP itself is now authorized to the
# same company (FUDGETOPIA LLC, same realm) under its own OAuth tokens,
# so these endpoints pull the remaining invoice windows through the
# ERP's own connection instead. Scope is INVOICES ONLY: accounts, aging,
# customers and items are already marked pulled in the snapshot.
# The snapshot fields are written exactly as acct_migrate.py writes them
# (meta.invoice_windows_done as [start, end] pairs, invoices sorted by
# (date, doc_number), money in integer cents), so acct_verify.py and the
# migrate/import endpoint keep working unchanged. Two deliberate
# deviations from the MCP script, both documented where they happen:
# (1) the MCP running invoice_total_count base (113) is provably wrong
# -- 313 invoices are stored -- so this pull sets it to the exact
# distinct-invoice count after every window; (2) qb_id values here are
# the plain QuickBooks Ids, while the MCP pull stored opaque MCP ids
# ("<base64>:<id>") -- dedup compares the trailing segment, so the same
# invoice is never stored twice under the two spellings.
_QB_PULL_PACE_SECONDS = 0.5
_QB_PULL_PAGE_SIZE = 1000
_QB_PULL_FIRST_MONTH = "2020-01"
_QB_PULL_MAX_MONTHS = 5
_QB_PULL_COMPLETE_TYPES = ("accounts", "customers", "vendors", "items",
                           "invoices", "bills", "payments", "bank_accounts",
                           "bank_transactions", "journal_entries")


def _qb_is_rate_limited(exc):
    """True when a _QBOError is a 429. The real client raises
    _QBOError('QuickBooks error 429: ...') with the default 502 status,
    so both the status and the message are checked; the test double
    raises with status=429."""
    return (getattr(exc, "status", None) == 429
            or re.search(r"\b429\b", str(exc)) is not None)


def _qb_pull_to_cents(value):
    """Decimal string/number -> integer cents (same rules as
    acct_migrate.to_cents). None when unparseable."""
    if value is None or isinstance(value, bool):
        return None
    if isinstance(value, int):
        return value * 100
    if isinstance(value, float):
        return int(Decimal(str(value)) * 100)
    s = str(value).strip().replace("$", "").replace(",", "")
    if s.startswith("(") and s.endswith(")"):
        s = "-" + s[1:-1]
    if not s or s in ("-", "--"):
        return None
    try:
        return int(Decimal(s) * 100)
    except Exception:
        return None


def _qb_pull_norm_id(qb_id):
    """Trailing segment of a QuickBooks id. The MCP pull stored opaque
    ids ('<base64>:<id>'); the OAuth API returns the plain id. Both
    spellings reduce to the real id, so dedup works across pulls."""
    s = str(qb_id or "")
    return s.rsplit(":", 1)[-1] if s else ""


def _qb_pull_month_window(yyyy_mm):
    """(first, last) YYYY-MM-DD dates for a YYYY-MM month."""
    y, m = int(yyyy_mm[:4]), int(yyyy_mm[5:7])
    first = "%04d-%02d-01" % (y, m)
    if m == 12:
        nxt = datetime(y + 1, 1, 1)
    else:
        nxt = datetime(y, m + 1, 1)
    return first, (nxt - timedelta(days=1)).strftime("%Y-%m-%d")


def _qb_pull_invoice_row(inv):
    """A raw QuickBooks Invoice dict -> the snapshot invoice shape
    acct_migrate.py writes. Returns None when the record has no Id.
    Tax comes from TxnTaxDetail.TotalTax when present, else from the
    TaxLineDetail lines; SubTotalLineDetail lines are not products."""
    qid = str(inv.get("Id") or "")
    if not qid:
        return None
    cust = inv.get("CustomerRef") or {}
    email = (inv.get("BillEmail") or {}).get("Address") or ""
    lines = []
    tax_cents = None
    txn_tax = inv.get("TxnTaxDetail") or {}
    if txn_tax.get("TotalTax") is not None:
        tax_cents = _qb_pull_to_cents(txn_tax.get("TotalTax"))
    for ln in inv.get("Line") or []:
        if not isinstance(ln, dict):
            continue
        dtype = ln.get("DetailType")
        if dtype == "TaxLineDetail":
            if txn_tax.get("TotalTax") is None:
                tax_cents = (tax_cents or 0) \
                    + (_qb_pull_to_cents(ln.get("Amount")) or 0)
            continue
        if dtype != "SalesItemLineDetail":
            continue
        detail = ln.get("SalesItemLineDetail") or {}
        item_ref = detail.get("ItemRef") or {}
        tax_ref = detail.get("TaxCodeRef") or {}
        lines.append({
            "description": ln.get("Description")
                           or item_ref.get("name") or "",
            "qty": int(Decimal(str(detail.get("Qty") or 1))),
            "rate_cents": _qb_pull_to_cents(detail.get("UnitPrice")) or 0,
            "amount_cents": _qb_pull_to_cents(ln.get("Amount")) or 0,
            "taxable": tax_ref.get("value") == "TAX",
            "item_qb_id": str(item_ref.get("value") or ""),
        })
    subtotal = sum(l["amount_cents"] for l in lines)
    total = _qb_pull_to_cents(inv.get("TotalAmt"))
    balance = _qb_pull_to_cents(inv.get("Balance"))
    return {
        "qb_id": qid,
        "doc_number": str(inv.get("DocNumber") or ""),
        "customer_qb_id": str(cust.get("value") or ""),
        "customer_name": cust.get("name") or "",
        "customer_email": email,
        "date": inv.get("TxnDate") or "",
        "due_date": inv.get("DueDate") or "",
        "lines": lines,
        "subtotal_cents": subtotal,
        "tax_cents": tax_cents if tax_cents is not None else 0,
        "total_cents": total if total is not None else subtotal,
        "balance_cents": balance if balance is not None else 0,
        "status": "open" if (balance or 0) > 0 else "paid",
        "customer_type": "wholesale",
    }


def _qb_pull_fetch_window(client, frm, to):
    """All invoices in one [frm, to] window via the QBO query API,
    paginated (MAXRESULTS 1000). Returns a list of raw QuickBooks
    invoice dicts. Raises _QBOError on any failure -- including 429,
    which the caller must not retry."""
    out = []
    start = 1
    total = None
    for _page in range(100):
        data = client.query(
            "select * from Invoice where TxnDate >= '%s'"
            " and TxnDate <= '%s' ORDER BY TxnDate"
            " STARTPOSITION %d MAXRESULTS %d"
            % (frm, to, start, _QB_PULL_PAGE_SIZE))
        resp = (data or {}).get("QueryResponse") or {}
        page = resp.get("Invoice") or []
        if total is None:
            total = resp.get("totalCount")
        out.extend(page)
        if len(page) < _QB_PULL_PAGE_SIZE:
            break
        if total is not None and len(out) >= total:
            break
        start += _QB_PULL_PAGE_SIZE
    else:
        raise _QBOError("QuickBooks invoice window %s..%s is too large"
                        " to page" % (frm, to))
    return out


def _qb_pull_load_snapshot():
    """(snapshot dict, read path) or (None, None) when no snapshot
    file exists. A malformed file raises ValueError."""
    path = _acct_qb_snapshot_path()
    if not path:
        return None, None
    with open(path, encoding="utf-8") as fh:
        snap = json.load(fh)
    if not isinstance(snap, dict):
        raise ValueError("snapshot is not an object")
    return snap, path


def _qb_pull_write_path(read_path):
    """Where the pull writes the snapshot back: the
    ERP_QB_SNAPSHOT_PATH override when set (tests point it at a
    fixture), else the same file it was read from -- except a
    beside-app.py copy, which is a stale repo fallback the pull must
    never write into (the volume path wins there instead)."""
    env = (os.environ.get(ERP_QB_SNAPSHOT_ENV) or "").strip()
    if env:
        return env
    here = os.path.dirname(os.path.abspath(__file__))
    beside = os.path.join(here, "qb-migration-snapshot.json")
    if read_path and os.path.abspath(read_path) != os.path.abspath(beside):
        return read_path
    return _acct_qb_snapshot_write_path()


def _qb_pull_save_snapshot(snap, path):
    """Atomic snapshot write (temp file + os.replace), mirroring the
    qb-snapshot upload endpoint. pulled_at is refreshed on every save."""
    snap.setdefault("meta", {})["pulled_at"] = \
        datetime.now(timezone.utc).isoformat()
    parent = os.path.dirname(path)
    if parent:
        os.makedirs(parent, exist_ok=True)
    fd, tmp = tempfile.mkstemp(prefix=".qb-pull-", dir=parent or ".")
    os.close(fd)
    try:
        with open(tmp, "w", encoding="utf-8") as fh:
            json.dump(snap, fh, indent=2)
            fh.write("\n")
        os.replace(tmp, path)
    except BaseException:
        try:
            os.unlink(tmp)
        except OSError:
            pass
        raise


def _qb_pull_remaining_windows(snap):
    """[(month, frm, to)] for every month 2020-01..current month whose
    window is not in meta.invoice_windows_done, oldest first."""
    done = {tuple(w) for w in
            (snap.get("meta") or {}).get("invoice_windows_done", [])}
    now_mm = datetime.now(timezone.utc).strftime("%Y-%m")
    out = []
    for mm in _acct_qb_months(_QB_PULL_FIRST_MONTH, now_mm):
        frm, to = _qb_pull_month_window(mm)
        if (frm, to) not in done:
            out.append((mm, frm, to))
    return out


def _qb_pull_auth():
    """qb.manage admin session OR the cron secret, same pattern as the
    sales backfill / qb-snapshot upload. Returns (actor, None) when
    allowed, else (None, (resp, code))."""
    if CRON_SECRET and hmac.compare_digest(request.headers.get("X-Cron-Secret", ""), CRON_SECRET):
        return "cron", None
    actor, err = _erp_check_perm("qb.manage")
    return actor, err


@app.post("/api/erp/accounting/qb-pull/probe")
def erp_acct_qb_pull_probe():
    """Live probe of the ERP's own QuickBooks OAuth connection: one
    CompanyInfo query plus one small invoice-count query for the first
    missing invoice window. Read-only -- nothing is written. A 429
    from either query returns 429 with rate_limited true and no retry,
    which is the whole point of the probe: it tells the caller whether
    the throttle follows the company or only the MCP connection."""
    actor, err = _qb_pull_auth()
    if err:
        return err
    conn = db()
    try:
        snap, _path = _qb_pull_load_snapshot()
    except (OSError, ValueError):
        snap = None
    remaining = _qb_pull_remaining_windows(snap) if snap else []
    # First missing window, or the current month when everything is
    # already pulled (the probe is a live-read test either way).
    probe_month = (remaining[0][0] if remaining
                   else datetime.now(timezone.utc).strftime("%Y-%m"))
    frm, to = _qb_pull_month_window(probe_month)
    tok = _qb_tokens(conn)
    try:
        info = _qb_call_with_refresh(
            conn, lambda c: c.query("select * from CompanyInfo"))
        company = (((info or {}).get("QueryResponse") or {})
                   .get("CompanyInfo") or [{}])[0].get("CompanyName", "")
        count_data = _qb_call_with_refresh(
            conn, lambda c: c.query(
                "select count(*) from Invoice where TxnDate >= '%s'"
                " and TxnDate <= '%s'" % (frm, to)))
        total = ((count_data or {}).get("QueryResponse") or {}) \
            .get("totalCount")
    except _QBOError as e:
        conn.close()
        if _qb_is_rate_limited(e):
            return jsonify(error="QuickBooks rate-limited (HTTP 429)",
                           rate_limited=True, company_ok=False,
                           invoice_probe={"month": probe_month,
                                          "count": None,
                                          "rate_limited": True}), 429
        return jsonify(error=str(e)), e.status
    conn.close()
    if total is None:
        return jsonify(error="QuickBooks did not return an invoice count",
                       rate_limited=False), 502
    return jsonify({
        "company_name": company,
        "realm_id": (tok["realm_id"] if tok else "") or "",
        "company_ok": bool(company),
        "invoice_probe": {"month": probe_month, "count": int(total),
                          "rate_limited": False},
    })


@app.post("/api/erp/accounting/qb-pull/probe-types")
def erp_acct_qb_pull_probe_types():
    """Live probe: how many records exist for the five export types
    the invoice pull never covered (vendors, bills, customer payments,
    journal entries, bank transactions). One count(*) query per entity
    type through the ERP's own QuickBooks OAuth connection, plus the
    bank-account list (names + ids only). Read-only -- nothing is
    written. Stops on the first 429 and reports the counts gathered
    so far, same rule as the invoice probe."""
    actor, err = _qb_pull_auth()
    if err:
        return err
    conn = db()
    tok = _qb_tokens(conn)
    counts = {}
    bank_accounts = []
    rate_limited = False
    error = None
    error_status = None
    company = ""
    try:
        info = _qb_call_with_refresh(
            conn, lambda c: c.query("select * from CompanyInfo"))
        company = (((info or {}).get("QueryResponse") or {})
                   .get("CompanyInfo") or [{}])[0].get("CompanyName", "")
    except _QBOError as e:
        if _qb_is_rate_limited(e):
            rate_limited = True
        else:
            error = str(e)
            error_status = e.status
    for entity in ("Vendor", "Bill", "Payment", "JournalEntry",
                   "Purchase", "Deposit", "BillPayment", "Transfer"):
        if rate_limited or error is not None:
            break
        try:
            data = _qb_call_with_refresh(
                conn, lambda c, e=entity: c.query(
                    "select count(*) from %s" % e))
        except _QBOError as e:
            if _qb_is_rate_limited(e):
                rate_limited = True
            else:
                error = str(e)
                error_status = e.status
            break
        total = ((data or {}).get("QueryResponse") or {}).get("totalCount")
        counts[entity.lower()] = int(total) if total is not None else None
    if not rate_limited and error is None:
        try:
            data = _qb_call_with_refresh(
                conn, lambda c: c.query(
                    "select Id, Name from Account"
                    " where AccountType = 'Bank'"))
            for acct in (((data or {}).get("QueryResponse") or {})
                         .get("Account") or []):
                bank_accounts.append({
                    "id": str(acct.get("Id") or ""),
                    "name": acct.get("Name") or ""})
        except _QBOError as e:
            if _qb_is_rate_limited(e):
                rate_limited = True
            else:
                error = str(e)
                error_status = e.status
    conn.close()
    if error is not None:
        return jsonify(error=error, counts=counts,
                       bank_accounts=bank_accounts,
                       rate_limited=False), error_status or 502
    if rate_limited:
        return jsonify(error="QuickBooks rate-limited (HTTP 429)",
                       counts=counts, bank_accounts=bank_accounts,
                       rate_limited=True,
                       company_name=company, realm_id=""), 429
    return jsonify({
        "company_name": company,
        "realm_id": (tok["realm_id"] if tok else "") or "",
        "company_ok": bool(company),
        "counts": counts,
        "bank_accounts": bank_accounts,
        "rate_limited": False,
    })


def _qb_pull_fetch_all(client, query_base):
    """All rows for one `select * from <Entity> ...` query, paginated
    (MAXRESULTS 1000). Raises _QBOError on any failure -- including
    429, which the caller must not retry."""
    out = []
    start = 1
    total = None
    for _page in range(100):
        data = client.query(
            "%s STARTPOSITION %d MAXRESULTS %d"
            % (query_base, start, _QB_PULL_PAGE_SIZE))
        resp = (data or {}).get("QueryResponse") or {}
        page = []
        for key, val in resp.items():
            if isinstance(val, list):
                page.extend(val)
        if total is None:
            total = resp.get("totalCount")
        out.extend(page)
        if len(page) < _QB_PULL_PAGE_SIZE:
            break
        if total is not None and len(out) >= total:
            break
        start += _QB_PULL_PAGE_SIZE
    else:
        raise _QBOError("QuickBooks query too large to page: %s"
                        % query_base)
    return out


def _qb_pull_vendor_row(v):
    """A raw QuickBooks Vendor dict -> the snapshot vendor shape the
    migration import reads (name, contact, email, phone)."""
    qid = str(v.get("Id") or "")
    if not qid:
        return None
    email = (v.get("PrimaryEmailAddr") or {}).get("Address") or ""
    phone = (v.get("PrimaryPhone") or {}).get("FreeFormNumber") or ""
    contact = ((v.get("GivenName") or "") + " "
               + (v.get("FamilyName") or "")).strip()
    return {
        "qb_id": qid,
        "name": v.get("DisplayName") or "",
        "contact_name": contact,
        "email": email,
        "phone": phone,
        "payment_terms": "",
        "notes": "",
    }


def _qb_pull_bill_row(b):
    """A raw QuickBooks Bill dict -> the snapshot bill shape the
    migration import reads."""
    qid = str(b.get("Id") or "")
    if not qid:
        return None
    vend = b.get("VendorRef") or {}
    lines = []
    for ln in b.get("Line") or []:
        if not isinstance(ln, dict):
            continue
        detail = ln.get("AccountBasedExpenseLineDetail") or {}
        acct = detail.get("AccountRef") or {}
        lines.append({
            "description": ln.get("Description") or acct.get("name") or "",
            "amount_cents": _qb_pull_to_cents(ln.get("Amount")) or 0,
            "account_name": acct.get("name") or "",
        })
    total = _qb_pull_to_cents(b.get("TotalAmt"))
    if total is None:
        total = sum(l["amount_cents"] for l in lines)
    balance = _qb_pull_to_cents(b.get("Balance"))
    return {
        "qb_id": qid,
        "date": b.get("TxnDate") or "",
        "due_date": b.get("DueDate") or "",
        "vendor_name": vend.get("name") or "",
        "vendor_qb_id": str(vend.get("value") or ""),
        "lines": lines,
        "total_cents": total,
        "balance_cents": balance if balance is not None else 0,
        "status": "open" if (balance or 0) > 0 else "paid",
    }


def _qb_pull_payment_row(p):
    """A raw QuickBooks Payment dict -> the snapshot payment shape the
    migration import reads. The linked invoice (or bill) comes from
    the line's LinkedTxn; the deposit account is DepositToAccountRef
    (usually Undeposited Funds, which the import resolves to the
    default cash account)."""
    qid = str(p.get("Id") or "")
    if not qid:
        return None
    inv_qb = None
    bill_qb = None
    for ln in p.get("Line") or []:
        if not isinstance(ln, dict):
            continue
        for lt in (ln.get("LinkedTxn") or []):
            if not isinstance(lt, dict):
                continue
            if lt.get("TxnType") == "Invoice" and not inv_qb:
                inv_qb = str(lt.get("TxnId") or "")
            elif lt.get("TxnType") == "Bill" and not bill_qb:
                bill_qb = str(lt.get("TxnId") or "")
    dep = p.get("DepositToAccountRef") or {}
    method = ((p.get("PaymentMethodRef") or {}).get("name") or "").strip()
    total = _qb_pull_to_cents(p.get("TotalAmt"))
    return {
        "qb_id": qid,
        "date": p.get("TxnDate") or "",
        "amount_cents": total if total is not None else 0,
        "invoice_qb_id": inv_qb,
        "bill_qb_id": bill_qb,
        "bank_account_qb_id": str(dep.get("value") or ""),
        "method": method or "cash",
    }


def _qb_pull_journal_entry_row(j):
    """A raw QuickBooks JournalEntry dict -> the snapshot journal-entry
    shape the migration import reads. Each line carries the account
    NAME (the import resolves it against the merged chart)."""
    qid = str(j.get("Id") or "")
    if not qid:
        return None
    lines = []
    for ln in j.get("Line") or []:
        if not isinstance(ln, dict):
            continue
        detail = ln.get("JournalEntryLineDetail") or {}
        acct = detail.get("AccountRef") or {}
        amt = _qb_pull_to_cents(ln.get("Amount")) or 0
        ptype = (detail.get("PostingType") or "").strip().lower()
        lines.append({
            "account_name": acct.get("name") or "",
            "debit_cents": amt if ptype == "debit" else 0,
            "credit_cents": amt if ptype == "credit" else 0,
            "memo": ln.get("Description") or "",
        })
    return {
        "qb_id": qid,
        "date": j.get("TxnDate") or "",
        "memo": (j.get("PrivateNote") or "").strip(),
        "lines": lines,
    }


def _qb_pull_bank_txn_row(entity, t, bank_ids):
    """A raw Purchase / Deposit / BillPayment / Transfer dict -> a
    minimal bank-transaction shape (reference only: the migration
    import deliberately does not import bank transactions). Returns
    None when the row touches none of the ERP's bank accounts."""
    qid = str(t.get("Id") or "")
    if not qid:
        return None
    acct_qb = None
    from_qb = None
    to_qb = None
    if entity == "Purchase":
        acct_qb = str(((t.get("AccountRef") or {}).get("value")) or "")
    elif entity == "Deposit":
        acct_qb = str(((t.get("DepositToAccountRef") or {}).get("value"))
                      or "")
    elif entity == "BillPayment":
        check = t.get("CheckPayment") or {}
        card = t.get("CreditCardPayment") or {}
        acct_qb = str(((check.get("BankAccountRef") or {}).get("value"))
                      or ((card.get("CreditCardAccountRef") or {})
                          .get("value")) or "")
    elif entity == "Transfer":
        from_qb = str(((t.get("FromAccountRef") or {}).get("value")) or "")
        to_qb = str(((t.get("ToAccountRef") or {}).get("value")) or "")
        acct_qb = from_qb if from_qb in bank_ids else to_qb
    if acct_qb not in bank_ids:
        return None
    total = _qb_pull_to_cents(t.get("TotalAmt"))
    if total is None:
        total = _qb_pull_to_cents(t.get("Amount"))
    return {
        "qb_id": qid,
        "type": entity.lower(),
        "date": t.get("TxnDate") or "",
        "account_qb_id": acct_qb,
        "from_account_qb_id": from_qb,
        "to_account_qb_id": to_qb,
        "amount_cents": total if total is not None else 0,
        "memo": (t.get("PrivateNote") or "").strip(),
    }


# QuickBooks AccountType -> ERP chart type. Unknown types are skipped
# (never guessed) by _qb_pull_chart_row.
_QB_CHART_TYPE_MAP = {
    "Bank": "asset", "Accounts Receivable": "asset",
    "Other Current Asset": "asset", "Fixed Asset": "asset",
    "Other Asset": "asset", "Accounts Payable": "liability",
    "Credit Card": "liability", "Other Current Liability": "liability",
    "Long Term Liability": "liability", "Equity": "equity",
    "Income": "income", "Other Income": "income",
    "Cost of Goods Sold": "expense", "Expense": "expense",
    "Other Expense": "expense"}


def _qb_pull_chart_row(raw):
    """A raw Account dict -> a chart row shaped exactly as the
    migration import's chart merge reads it (name / type / qb_id /
    parent_name). The name is the FullyQualifiedName, so a child like
    Payroll Expenses:Wages matches the name a journal-entry line
    carries. Balance is reference only -- source is qb_chart, never
    balance_sheet, so it never becomes an opening-entry target.
    Returns None for rows with no id/name or an unmapped type."""
    name = ((raw.get("FullyQualifiedName") or raw.get("Name") or "")
            .strip())
    if not name or not raw.get("Id"):
        return None
    atype = _QB_CHART_TYPE_MAP.get((raw.get("AccountType") or "").strip())
    if atype is None:
        return None
    parent = raw.get("ParentRef") or {}
    balance = None
    if raw.get("CurrentBalance") is not None:
        balance = _qb_pull_to_cents(raw.get("CurrentBalance"))
    return {"qb_id": str(raw["Id"]), "name": name, "type": atype,
            "parent_name": (parent.get("name") or ""),
            "balance_cents": balance, "source": "qb_chart"}


@app.post("/api/erp/accounting/qb-pull/run-types")
def erp_acct_qb_pull_run_types():
    """Pull the five export types the invoice pull never covered --
    vendors, bills, customer payments, journal entries, and bank
    transactions -- through the ERP's own QuickBooks OAuth connection,
    into the migration snapshot, plus the full chart of accounts
    (qb_chart) so journal-entry lines can resolve at import. Rows are
    shaped exactly as the migration import reads them; bank
    transactions are reference only (the import deliberately skips
    them). One entity at a time, saved after each; STOPS on the first
    429 and saves the partial progress first -- no retry, no
    sleep-loop."""
    actor, err = _qb_pull_auth()
    if err:
        return err
    try:
        snap, read_path = _qb_pull_load_snapshot()
    except (OSError, ValueError) as exc:
        return jsonify(error="QuickBooks migration snapshot unreadable: %s"
                       % exc, snapshot_status="unreadable"), 500
    if snap is None:
        return jsonify(error="QuickBooks migration snapshot not found",
                       snapshot_status="missing"), 404
    meta = snap.get("meta")
    if not isinstance(meta, dict):
        return jsonify(error="snapshot.meta must be an object"), 400
    for key in ("vendors", "bills", "payments", "journal_entries",
                "bank_transactions"):
        if not isinstance(snap.get(key), list):
            return jsonify(error="snapshot.%s must be a list" % key), 400
    conn = db()
    bank_ids = {str(b.get("qb_id"))
                for b in snap.get("bank_accounts") or []
                if b.get("qb_id")}
    now = datetime.now(timezone.utc).isoformat()
    counts = {}
    rate_limited = False
    error = None
    error_status = None
    # Full chart of accounts first: the balance-sheet snapshot never
    # carried P&L accounts, so journal-entry lines referencing them
    # (payroll, rent, COGS, income) could not resolve at import.
    # Stored as qb_chart (the diff keeps reading the balance-sheet
    # accounts list, so this changes no report); the import merges
    # it into the chart by name, with the QuickBooks type mapped.
    if not rate_limited and error is None:
        try:
            chart_rows = _qb_call_with_refresh(
                conn, lambda c: _qb_pull_fetch_all(
                    c, "select Id, Name, FullyQualifiedName, AccountType,"
                    " AccountSubType, ParentRef, CurrentBalance"
                    " from Account ORDER BY FullyQualifiedName"))
        except _QBOError as e:
            if _qb_is_rate_limited(e):
                rate_limited = True
            else:
                error = str(e)
                error_status = e.status
            chart_rows = []
        if not rate_limited and error is None:
            chart = []
            for raw in chart_rows:
                row = _qb_pull_chart_row(raw)
                if row is not None:
                    chart.append(row)
            snap["qb_chart"] = chart
            meta.setdefault("types", {})["accounts"] = {
                "status": "pulled", "count": len(chart),
                "pulled_at": now}
            _qb_pull_save_snapshot(snap, _qb_pull_write_path(read_path))
    jobs = [
        ("vendors", "Vendor", "select * from Vendor ORDER BY DisplayName",
         _qb_pull_vendor_row),
        ("bills", "Bill", "select * from Bill ORDER BY TxnDate",
         _qb_pull_bill_row),
        ("payments", "Payment", "select * from Payment ORDER BY TxnDate",
         _qb_pull_payment_row),
        ("journal_entries", "JournalEntry",
         "select * from JournalEntry ORDER BY TxnDate",
         _qb_pull_journal_entry_row),
    ]
    for key, _entity, query_base, shape in jobs:
        time.sleep(_QB_PULL_PACE_SECONDS)
        try:
            rows = _qb_call_with_refresh(
                conn, lambda c, q=query_base: _qb_pull_fetch_all(c, q))
        except _QBOError as e:
            if _qb_is_rate_limited(e):
                rate_limited = True
            else:
                error = str(e)
                error_status = e.status
            break
        seen = {}
        for old in snap[key]:
            if isinstance(old, dict) and old.get("qb_id"):
                seen[_qb_pull_norm_id(old["qb_id"])] = old
        for raw in rows:
            row = shape(raw)
            if row is None:
                continue
            seen[_qb_pull_norm_id(row["qb_id"])] = row
        snap[key] = sorted(
            seen.values(), key=lambda r: (r.get("date") or "",
                                          r.get("qb_id") or ""))
        counts[key] = len(seen)
        meta.setdefault("types", {})[key] = {
            "status": "pulled", "count": len(seen),
            "pulled_at": now,
            "note": "pulled via the ERP QuickBooks OAuth connection"
                    " (qb-pull/run-types)"}
        meta.setdefault("verification", {}) \
            .setdefault("qb_counts", {})[key] = len(seen)
        try:
            _qb_pull_save_snapshot(snap, _qb_pull_write_path(read_path))
        except OSError as exc:
            error = "could not store snapshot: %s" % exc
            error_status = 500
            break
    if not rate_limited and error is None:
        # Bank transactions: one pass over the four bank-touching
        # entity types, kept only when they touch an ERP bank account.
        # The snapshot's bank accounts carry no qb_id (the MCP pull
        # built them from the balance sheet), so the bank ids come from
        # a live Account query, falling back to whatever qb_id the
        # snapshot does have; the snapshot's bank accounts are
        # backfilled from the live list by name.
        try:
            data = _qb_call_with_refresh(
                conn, lambda c: c.query(
                    "select Id, Name from Account"
                    " where AccountType = 'Bank'"))
            for acct in (((data or {}).get("QueryResponse") or {})
                         .get("Account") or []):
                aid = str(acct.get("Id") or "")
                if aid:
                    bank_ids.add(aid)
                    for b in snap.get("bank_accounts") or []:
                        if not b.get("qb_id") and \
                                _acct_qb_norm_name(b.get("name")) == \
                                _acct_qb_norm_name(acct.get("Name")):
                            b["qb_id"] = aid
            _qb_pull_save_snapshot(snap, _qb_pull_write_path(read_path))
        except _QBOError as e:
            if _qb_is_rate_limited(e):
                rate_limited = True
            else:
                error = str(e)
                error_status = e.status
        bank_rows = {}
        for old in snap["bank_transactions"]:
            if isinstance(old, dict) and old.get("qb_id"):
                bank_rows[_qb_pull_norm_id(old["qb_id"])] = old
        if not rate_limited and error is None:
            for entity in ("Purchase", "Deposit", "BillPayment",
                           "Transfer"):
                time.sleep(_QB_PULL_PACE_SECONDS)
                try:
                    rows = _qb_call_with_refresh(
                        conn, lambda c, e=entity: _qb_pull_fetch_all(
                            c, "select * from %s ORDER BY TxnDate" % e))
                except _QBOError as e:
                    if _qb_is_rate_limited(e):
                        rate_limited = True
                    else:
                        error = str(e)
                        error_status = e.status
                    break
                for raw in rows:
                    row = _qb_pull_bank_txn_row(entity, raw, bank_ids)
                    if row is None:
                        continue
                    bank_rows[_qb_pull_norm_id(row["qb_id"])] = row
                if rate_limited or error is not None:
                    break
        if not rate_limited and error is None:
            snap["bank_transactions"] = sorted(
                bank_rows.values(),
                key=lambda r: (r.get("date") or "", r.get("qb_id") or ""))
            counts["bank_transactions"] = len(bank_rows)
            meta.setdefault("types", {})["bank_transactions"] = {
                "status": "pulled", "count": len(bank_rows),
                "pulled_at": now,
                "note": "reference only -- the migration import does not"
                        " import bank transactions; pulled via the ERP"
                        " QuickBooks OAuth connection (qb-pull/run-types)"}
            try:
                _qb_pull_save_snapshot(snap,
                                       _qb_pull_write_path(read_path))
            except OSError as exc:
                error = "could not store snapshot: %s" % exc
                error_status = 500
    if not rate_limited and error is None:
        # Invoices and items were never recorded in meta.types by the
        # invoice pull (qb-pull/run records invoices only on its own
        # complete branch, and items are not migrated at all), so
        # meta.complete could never flip True. Record both here:
        # invoices from the snapshot the pull filled, items as
        # not_pulled by design (the ERP keeps its own item master;
        # QuickBooks items are never imported). The complete rule
        # accepts any recorded status.
        types = meta.setdefault("types", {})
        types["invoices"] = {
            "status": "pulled", "count": len(snap.get("invoices") or []),
            "pulled_at": now,
            "note": "monthly windows through the invoice pull (qb-pull/run)"}
        types.setdefault("items", {
            "status": "not_pulled", "count": 0,
            "note": "QuickBooks items are not migrated; the ERP keeps"
                    " its own item master"})
        meta["complete"] = all(
            (meta.get("types") or {}).get(t, {}).get("status")
            in ("pulled", "not_available", "not_pulled")
            for t in _QB_PULL_COMPLETE_TYPES)
        try:
            _qb_pull_save_snapshot(snap, _qb_pull_write_path(read_path))
        except OSError as exc:
            error = "could not store snapshot: %s" % exc
            error_status = 500
    _acct_audit(conn, actor, "qb.pull_run_types", "qb_snapshot", 0,
                "pulled types %s, rate_limited %s"
                % (counts, rate_limited))
    conn.commit()
    conn.close()
    out = {"ok": True, "counts": counts,
           "complete": bool(meta.get("complete")),
           "rate_limited": rate_limited}
    if rate_limited:
        out["error"] = "QuickBooks rate-limited (HTTP 429)"
        return jsonify(out), 429
    if error is not None:
        out["error"] = error
        return jsonify(out), error_status or 502
    return jsonify(out)


@app.post("/api/erp/accounting/qb-pull/run")
def erp_acct_qb_pull_run():
    """Pull invoice windows through the ERP's own QuickBooks OAuth
    connection. Resume-safe: windows already in
    meta.invoice_windows_done are skipped; invoices dedupe by
    QuickBooks id (trailing segment, so MCP-opaque and plain ids match).
    One month per QBO query, paginated; ~0.5s between calls. STOPS on
    the first 429 and saves the partial progress first -- no retry, no
    sleep-loop. Optional body {"months": N} (1..5, default 1)."""
    actor, err = _qb_pull_auth()
    if err:
        return err
    try:
        months = int((request.get_json(silent=True) or {}).get("months", 1))
    except (TypeError, ValueError):
        months = 1
    months = max(1, min(_QB_PULL_MAX_MONTHS, months))
    try:
        snap, read_path = _qb_pull_load_snapshot()
    except (OSError, ValueError) as exc:
        return jsonify(error="QuickBooks migration snapshot unreadable: %s"
                       % exc, snapshot_status="unreadable"), 500
    if snap is None:
        return jsonify(error="QuickBooks migration snapshot not found",
                       snapshot_status="missing"), 404
    meta = snap.get("meta")
    if not isinstance(meta, dict) or not isinstance(snap.get("invoices"),
                                                    list):
        return jsonify(error="snapshot.meta must be an object and "
                       "snapshot.invoices must be a list"), 400
    conn = db()
    remaining = _qb_pull_remaining_windows(snap)
    if not remaining:
        # Already complete from an earlier run: make sure the types the
        # complete rule needs are recorded (the original run predated
        # the invoices/items recording), then save if anything changed.
        # A save failure here is not fatal -- the in-memory meta is
        # complete and the next run-types call backfills the file.
        _types = meta.setdefault("types", {})
        _changed = False
        if "invoices" not in _types:
            _types["invoices"] = {
                "status": "pulled", "count": len(snap.get("invoices") or []),
                "pulled_at": datetime.now(timezone.utc).isoformat(),
                "note": "monthly windows through the invoice pull (qb-pull/run)"}
            _changed = True
        if "items" not in _types:
            _types["items"] = {
                "status": "not_pulled", "count": 0,
                "note": "QuickBooks items are not migrated; the ERP keeps"
                        " its own item master"}
            _changed = True
        if _changed:
            meta["complete"] = all(
                (meta.get("types") or {}).get(t, {}).get("status")
                in ("pulled", "not_available", "not_pulled")
                for t in _QB_PULL_COMPLETE_TYPES)
            try:
                _qb_pull_save_snapshot(snap, _qb_pull_write_path(read_path))
            except OSError:
                pass
        conn.close()
        return jsonify(ok=True, complete=True, windows_pulled=[],
                       windows_remaining=0,
                       windows_done=len(meta.get("invoice_windows_done",
                                                 [])),
                       invoices=len(snap["invoices"]),
                       rate_limited=False)
    seen = {}
    for _inv in snap["invoices"]:
        if isinstance(_inv, dict) and _inv.get("qb_id"):
            seen[_qb_pull_norm_id(_inv["qb_id"])] = _inv
    pulled = []
    rate_limited = False
    error = None
    error_status = None
    for _mm, frm, to in remaining[:months]:
        time.sleep(_QB_PULL_PACE_SECONDS)
        try:
            rows = _qb_call_with_refresh(
                conn, lambda c, f=frm, t=to: _qb_pull_fetch_window(c, f, t))
        except _QBOError as e:
            if _qb_is_rate_limited(e):
                rate_limited = True
            else:
                error = str(e)
                error_status = e.status
            break
        for raw in rows:
            row = _qb_pull_invoice_row(raw)
            if row is None:
                continue
            key = _qb_pull_norm_id(row["qb_id"])
            if key in seen:
                continue
            seen[key] = row
        done = {tuple(w) for w in meta.get("invoice_windows_done", [])}
        done.add((frm, to))
        meta["invoice_windows_done"] = sorted(done)
        # The MCP running total (113) is provably wrong -- 313 invoices
        # are stored -- so the total is the exact distinct-invoice
        # count, recomputed after every window.
        meta["invoice_total_count"] = len(seen)
        meta.setdefault("oauth_pull_windows", []).append([frm, to])
        meta["oauth_pull_last_at"] = datetime.now(timezone.utc).isoformat()
        snap["invoices"] = sorted(
            seen.values(), key=lambda i: (i.get("date") or "",
                                          i.get("doc_number") or ""))
        try:
            _qb_pull_save_snapshot(snap, _qb_pull_write_path(read_path))
        except OSError as exc:
            error = "could not store snapshot: %s" % exc
            error_status = 500
            break
        pulled.append([frm, to])
    remaining_after = _qb_pull_remaining_windows(snap)
    complete = not remaining_after
    if complete:
        types = meta.setdefault("types", {})
        types["invoices"] = {
            "status": "pulled", "count": len(seen),
            "note": "monthly windows through %s, pulled via the ERP "
                    "QuickBooks OAuth connection"
                    % _qb_pull_month_window(
                        datetime.now(timezone.utc).strftime("%Y-%m"))[1]}
        types["items"] = {
            "status": "not_pulled", "count": 0,
            "note": "QuickBooks items are not migrated; the ERP keeps"
                    " its own item master"}
        meta.setdefault("verification", {}) \
            .setdefault("qb_counts", {})["invoices"] = len(seen)
        meta["complete"] = all(
            (meta.get("types") or {}).get(t, {}).get("status")
            in ("pulled", "not_available", "not_pulled")
            for t in _QB_PULL_COMPLETE_TYPES)
        try:
            _qb_pull_save_snapshot(snap, _qb_pull_write_path(read_path))
        except OSError as exc:
            error = "could not store snapshot: %s" % exc
            error_status = 500
    _acct_audit(conn, actor, "qb.pull_run", "qb_snapshot", 0,
                "pulled %d windows (%s), %d invoices total, "
                "remaining %d, rate_limited %s"
                % (len(pulled),
                   ", ".join("%s..%s" % (f, t) for f, t in pulled) or "none",
                   len(seen), len(remaining_after), rate_limited))
    conn.commit()
    conn.close()
    out = {"ok": True, "complete": complete, "windows_pulled": pulled,
           "windows_remaining": len(remaining_after),
           "windows_done": len(meta.get("invoice_windows_done", [])),
           "invoices": len(seen), "rate_limited": rate_limited}
    if rate_limited:
        out["error"] = "QuickBooks rate-limited (HTTP 429)"
        return jsonify(out), 429
    if error is not None:
        out["error"] = error
        return jsonify(out), error_status or 502
    return jsonify(out)


# ---- Owner draws (item 7) ----
def _acct_draw_dict(row):
    d = dict(row)
    return d


@app.get("/api/erp/accounting/draws")
def erp_acct_list_draws():
    actor, err = _erp_check_perm("accounting.read")
    if err:
        return err
    status = (request.args.get("status") or "").strip()
    conn = db()
    if status:
        rows = conn.execute(
            "SELECT * FROM erp_acct_draws WHERE status = ?"
            " ORDER BY id DESC", (status,)).fetchall()
    else:
        rows = conn.execute(
            "SELECT * FROM erp_acct_draws ORDER BY id DESC").fetchall()
    conn.close()
    return jsonify(draws=[_acct_draw_dict(r) for r in rows])


@app.post("/api/erp/accounting/draws")
def erp_acct_request_draw():
    """Request an owner draw. Records the request only -- no money
    moves until the other founder approves it."""
    actor, err = _erp_check_perm("accounting.write")
    if err:
        return err
    data = request.get_json(force=True) or {}
    owner_raw = (data.get("owner_name") or "").strip()
    owner = next((n for n in ERP_ACCT_OWNER_NAMES
                  if n.lower() == owner_raw.lower()), None)
    if not owner:
        return jsonify(error="owner_name must be one of "
                       + ", ".join(ERP_ACCT_OWNER_NAMES)), 400
    amount = _acct_int_cents(data.get("amount_cents"))
    if amount is None or amount < 1:
        return jsonify(error="amount_cents must be whole cents greater than zero"), 400
    date = (data.get("date") or "").strip() \
        or datetime.now(timezone.utc).date().isoformat()
    if not _acct_valid_date(date):
        return jsonify(error="date must be YYYY-MM-DD"), 400
    memo = (data.get("memo") or "").strip()
    bank_account_id = data.get("bank_account_id")
    conn = db()
    if bank_account_id not in (None, "", 0):
        try:
            bank_account_id = int(bank_account_id)
        except (TypeError, ValueError):
            conn.close()
            return jsonify(error="bank_account_id must be a number"), 400
        bank = conn.execute(
            "SELECT * FROM erp_acct_bank_accounts WHERE id = ?",
            (bank_account_id,)).fetchone()
        if not bank:
            conn.close()
            return jsonify(error="bank account not found"), 404
        if not bank["active"]:
            conn.close()
            return jsonify(error="bank account is inactive"), 400
    else:
        bank_account_id = None
    now = datetime.now(timezone.utc).isoformat()
    cur = conn.execute(
        "INSERT INTO erp_acct_draws (owner_name, date, amount_cents, memo,"
        " bank_account_id, status, requested_by, decided_by,"
        " journal_entry_id, created_at, decided_at)"
        " VALUES (?, ?, ?, ?, ?, 'requested', ?, '', NULL, ?, NULL)",
        (owner, date, amount, memo, bank_account_id, actor or "", now))
    draw_id = cur.lastrowid
    _acct_audit(conn, actor, "draw.request", "draw", draw_id,
                "#%d %s %d cents on %s" % (draw_id, owner, amount, date))
    conn.commit()
    row = conn.execute("SELECT * FROM erp_acct_draws WHERE id = ?",
                       (draw_id,)).fetchone()
    conn.close()
    return jsonify(draw=_acct_draw_dict(row)), 201


def _acct_draw_get(conn, draw_id):
    return conn.execute("SELECT * FROM erp_acct_draws WHERE id = ?",
                        (draw_id,)).fetchone()


@app.post("/api/erp/accounting/draws/<int:draw_id>/approve")
def erp_acct_approve_draw(draw_id):
    """Approve a requested draw and post it: Dr 3000 Owner's Equity /
    Cr bank (1010 Checking -- Operating by default, or the selected
    bank account's GL account). The approver must differ from the
    requester; _acct_post_entry enforces period locks."""
    actor, err = _erp_check_perm("accounting.write")
    if err:
        return err
    conn = db()
    draw = _acct_draw_get(conn, draw_id)
    if not draw:
        conn.close()
        return jsonify(error="draw not found"), 404
    if draw["status"] != "requested":
        conn.close()
        return jsonify(error="only a requested draw can be approved"
                       " (status: %s)" % draw["status"]), 400
    if (actor or "") == (draw["requested_by"] or ""):
        conn.close()
        return jsonify(error="you cannot approve your own draw;"
                       " the other founder must approve it"), 403
    equity_id = _acct_account_id_by_code(conn, ERP_ACCT_EQUITY_CODE)
    bank_gl_id, bank_err = _acct_cash_account_id(conn, draw["bank_account_id"])
    if not equity_id or bank_err or not bank_gl_id:
        conn.close()
        return jsonify(error=bank_err or
                       "chart of accounts is missing a required account"), 500
    now = datetime.now(timezone.utc).isoformat()
    conn.execute("SAVEPOINT acct_draw_approve")
    raw = [{"account_id": equity_id, "debit_cents": draw["amount_cents"],
            "credit_cents": 0,
            "memo": "Owner draw #%d -- %s" % (draw_id, draw["owner_name"])},
           {"account_id": bank_gl_id, "debit_cents": 0,
            "credit_cents": draw["amount_cents"],
            "memo": "Owner draw #%d -- %s" % (draw_id, draw["owner_name"])}]
    entry_id, error = _acct_post_entry(
        conn, actor, draw["date"],
        "Owner draw #%d -- %s" % (draw_id, draw["owner_name"]),
        "draw", draw_id, raw)
    if error:
        conn.execute("ROLLBACK TO SAVEPOINT acct_draw_approve")
        conn.execute("RELEASE SAVEPOINT acct_draw_approve")
        conn.close()
        return jsonify(error=error), 400
    conn.execute("UPDATE erp_acct_draws SET status = 'approved',"
                 " decided_by = ?, journal_entry_id = ?, decided_at = ?"
                 " WHERE id = ?",
                 (actor or "", entry_id, now, draw_id))
    _acct_audit(conn, actor, "draw.approve", "draw", draw_id,
                "#%d %s %d cents entry #%d approved by %s (requested by %s)"
                % (draw_id, draw["owner_name"], draw["amount_cents"],
                   entry_id, actor or "", draw["requested_by"]))
    conn.execute("RELEASE SAVEPOINT acct_draw_approve")
    conn.commit()
    row = _acct_draw_get(conn, draw_id)
    conn.close()
    return jsonify(draw=_acct_draw_dict(row), journal_entry_id=entry_id)


@app.post("/api/erp/accounting/draws/<int:draw_id>/reject")
def erp_acct_reject_draw(draw_id):
    """Reject a requested draw. Posts nothing; the decision is by the
    other founder, like approval."""
    actor, err = _erp_check_perm("accounting.write")
    if err:
        return err
    conn = db()
    draw = _acct_draw_get(conn, draw_id)
    if not draw:
        conn.close()
        return jsonify(error="draw not found"), 404
    if draw["status"] != "requested":
        conn.close()
        return jsonify(error="only a requested draw can be rejected"
                       " (status: %s)" % draw["status"]), 400
    if (actor or "") == (draw["requested_by"] or ""):
        conn.close()
        return jsonify(error="you cannot reject your own draw;"
                       " the other founder must decide it"), 403
    now = datetime.now(timezone.utc).isoformat()
    conn.execute("UPDATE erp_acct_draws SET status = 'rejected',"
                 " decided_by = ?, decided_at = ? WHERE id = ?",
                 (actor or "", now, draw_id))
    _acct_audit(conn, actor, "draw.reject", "draw", draw_id,
                "#%d %s %d cents rejected by %s (requested by %s)"
                % (draw_id, draw["owner_name"], draw["amount_cents"],
                   actor or "", draw["requested_by"]))
    conn.commit()
    row = _acct_draw_get(conn, draw_id)
    conn.close()
    return jsonify(draw=_acct_draw_dict(row))


@app.post("/api/erp/accounting/draws/<int:draw_id>/cancel")
def erp_acct_cancel_draw(draw_id):
    """Withdraw your own requested draw. Posts nothing. Only the
    requester can cancel; the other founder rejects instead."""
    actor, err = _erp_check_perm("accounting.write")
    if err:
        return err
    conn = db()
    draw = _acct_draw_get(conn, draw_id)
    if not draw:
        conn.close()
        return jsonify(error="draw not found"), 404
    if draw["status"] != "requested":
        conn.close()
        return jsonify(error="only a requested draw can be cancelled"
                       " (status: %s)" % draw["status"]), 400
    if (actor or "") != (draw["requested_by"] or ""):
        conn.close()
        return jsonify(error="only the requester can cancel this draw;"
                       " the other founder can reject it"), 403
    now = datetime.now(timezone.utc).isoformat()
    conn.execute("UPDATE erp_acct_draws SET status = 'cancelled',"
                 " decided_by = ?, decided_at = ? WHERE id = ?",
                 (actor or "", now, draw_id))
    _acct_audit(conn, actor, "draw.cancel", "draw", draw_id,
                "#%d %s %d cents cancelled by requester"
                % (draw_id, draw["owner_name"], draw["amount_cents"]))
    conn.commit()
    row = _acct_draw_get(conn, draw_id)
    conn.close()
    return jsonify(draw=_acct_draw_dict(row))


# ---- Plaid bank-feed sync path (item 8) ----
def _acct_plaid_cli():
    return (os.environ.get(ERP_PLAID_CLI_ENV) or "").strip() \
        or ERP_PLAID_CLI_DEFAULT


def _acct_plaid_run(args, timeout=60):
    """Run the Plaid connector CLI and parse its JSON stdout. Returns
    the parsed object, or None when the CLI is missing, times out, or
    returns non-JSON. Never raises; never logs credentials (the CLI
    holds the link, the ERP holds none)."""
    try:
        res = subprocess.run([_acct_plaid_cli()] + list(args),
                             capture_output=True, text=True, timeout=timeout)
    except (OSError, subprocess.TimeoutExpired):
        return None
    try:
        return json.loads(res.stdout or "")
    except ValueError:
        return None


def _acct_plaid_status():
    """Linked-institution status from `plaid status`: connected flag,
    institution names + masked account numbers only, and the exact
    connect / add-account URLs the CLI returns (never invented).
    With no bank linked: connected False, linked_institutions 0."""
    out = _acct_plaid_run(["status"], timeout=30)
    if not isinstance(out, dict):
        return {"connected": False, "linked_institutions": 0,
                "institutions": [], "status": "unavailable",
                "message": "Plaid status could not be read."}
    institutions = []
    for inst in (out.get("institutions") or []):
        if not isinstance(inst, dict):
            continue
        accts = []
        for a in (inst.get("accounts") or []):
            if isinstance(a, dict):
                accts.append({"name": a.get("name"),
                              "type": a.get("type"),
                              "mask": a.get("mask")})
        institutions.append({"name": inst.get("name") or inst.get("institution_name"),
                             "accounts": accts,
                             "needs_reauth": bool(inst.get("needs_reauth"))})
    # The CLI also reports accounts flat in `accounts`; fall back to it
    # when no institutions array is present.
    if not institutions and out.get("accounts"):
        names = {}
        for a in out.get("accounts") or []:
            if isinstance(a, dict):
                names.setdefault(a.get("institution_name") or "Linked bank",
                                 []).append(
                    {"name": a.get("name"), "type": a.get("type"),
                     "mask": a.get("mask")})
        institutions = [{"name": k, "accounts": v, "needs_reauth": False}
                        for k, v in names.items()]
    linked = out.get("linked_institutions")
    if linked is None:
        linked = len(institutions)
    connected = bool(out.get("connected")) and linked > 0
    return {"connected": connected,
            "linked_institutions": int(linked or 0),
            "institutions": institutions,
            "status": out.get("status") or ("connected" if connected
                                            else "not_connected"),
            "connect_url": out.get("connect_url"),
            "add_account_url": out.get("add_account_url"),
            "message": out.get("reason") or (
                "No bank is linked in Plaid yet." if not connected else "")}


def _acct_plaid_map_transactions(body):
    """Map `plaid transactions-get` body.transactions to bank-sync
    receiver rows. Plaid amounts are dollars (positive = outflow,
    negative = inflow) -- the receiver stores Plaid amounts as-is.
    Cents via Decimal so $12.34 is exactly 1234. Rows missing an id,
    date or amount are skipped and counted, never guessed."""
    rows = []
    skipped = 0
    for txn in (body.get("transactions") or []):
        if not isinstance(txn, dict):
            skipped += 1
            continue
        txn_id = (txn.get("transaction_id") or "").strip()
        date = (txn.get("date") or "").strip()
        amount = txn.get("amount")
        if not txn_id or not _acct_valid_date(date) or amount is None:
            skipped += 1
            continue
        try:
            cents = int((Decimal(str(amount)) * 100).quantize(
                Decimal("1"), rounding=ROUND_HALF_UP))
        except Exception:
            skipped += 1
            continue
        desc = (txn.get("merchant_name") or txn.get("name") or "").strip()
        rows.append({"plaid_txn_id": txn_id,
                     "plaid_account_id": (txn.get("account_id") or "").strip(),
                     "date": date, "description": desc,
                     "amount_cents": cents})
    return rows, skipped


@app.get("/api/erp/accounting/plaid-status")
def erp_acct_plaid_status():
    """Plaid link status for the Banking view: whether any bank is
    linked, which institutions (names + masks only), and the exact
    connect/add-account URLs from the CLI. No credentials, no balances
    beyond what the CLI reports, no claim of a live feed."""
    actor, err = _erp_check_perm("accounting.read")
    if err:
        return err
    return jsonify(_acct_plaid_status())


@app.post("/api/erp/accounting/plaid-sync")
def erp_acct_plaid_sync():
    """Pull transactions from the linked Plaid bank(s) into the
    bank-feed receiver. With no bank linked: reports status
    'no_bank_linked' and does nothing. With a bank linked: runs
    `plaid transactions-get` over [start, end] (body, else the last
    30 days), maps to receiver rows, and ingests through the shared
    helper -- run it twice and the second run inserts nothing
    (plaid_txn_id idempotency)."""
    actor, err = _erp_check_perm("accounting.write")
    if err:
        return err
    status = _acct_plaid_status()
    if not status.get("connected"):
        return jsonify(ok=True, status="no_bank_linked",
                       feed="not_configured", inserted=0, skipped=0,
                       auto_matched=0, errors=[],
                       message="No bank is linked in Plaid yet. Link a"
                       " bank account in Plaid, then run a sync to pull"
                       " transactions into the feed.")
    data = request.get_json(force=True) or {}
    today = datetime.now(timezone.utc).date()
    end = (data.get("end") or "").strip() or today.isoformat()
    start = (data.get("start") or "").strip() or \
        (today - timedelta(days=30)).isoformat()
    if not _acct_valid_date(start) or not _acct_valid_date(end) \
            or start > end:
        return jsonify(error="start and end must be YYYY-MM-DD with start <= end"), 400
    out = _acct_plaid_run(["transactions-get", "--start-date", start,
                           "--end-date", end], timeout=120)
    if not isinstance(out, dict):
        return jsonify(ok=True, status="plaid_read_failed",
                       feed="not_configured", inserted=0, skipped=0,
                       auto_matched=0,
                       errors=["Plaid transactions could not be read"],
                       message="Plaid did not return transactions for"
                       " this period."), 502
    body = out.get("body") or out
    rows, map_skipped = _acct_plaid_map_transactions(body)
    conn = db()
    inserted, skipped, auto_matched, errors = _acct_ingest_bank_txns(
        conn, actor, rows)
    skipped += map_skipped
    _acct_audit(conn, actor, "bank.sync", "bank_sync", 0,
                "plaid sync %s to %s inserted %d skipped %d auto_matched"
                " %d errors %d" % (start, end, inserted, skipped,
                                   auto_matched, len(errors)))
    conn.commit()
    conn.close()
    return jsonify(ok=True, status="synced", feed="ingested",
                   start=start, end=end, inserted=inserted,
                   skipped=skipped, auto_matched=auto_matched,
                   errors=errors)


@app.post("/api/erp/accounting/bank-accounts/<int:bank_id>/match")
def erp_acct_match_bank_txn(bank_id):
    actor, err = _erp_check_perm("accounting.write")
    if err:
        return err
    data = request.get_json(force=True) or {}
    txn_id = data.get("txn_id")
    entry_id = data.get("entry_id")
    try:
        txn_id = int(txn_id)
        entry_id = int(entry_id)
    except (TypeError, ValueError):
        return jsonify(error="txn_id and entry_id are required numbers"), 400
    conn = db()
    bank = conn.execute(
        "SELECT * FROM erp_acct_bank_accounts WHERE id = ?",
        (bank_id,)).fetchone()
    if not bank:
        conn.close()
        return jsonify(error="bank account not found"), 404
    txn = conn.execute(
        "SELECT * FROM erp_acct_bank_txns"
        " WHERE id = ? AND bank_account_id = ?",
        (txn_id, bank_id)).fetchone()
    if not txn:
        conn.close()
        return jsonify(error="transaction not found for this bank account"), 404
    if txn["status"] == "matched":
        conn.close()
        return jsonify(
            error="transaction is already matched; unmatch it first"), 400
    entry = conn.execute(
        "SELECT * FROM erp_acct_journal WHERE id = ?", (entry_id,)).fetchone()
    if not entry:
        conn.close()
        return jsonify(error="journal entry not found"), 404
    if entry["reversed_by"]:
        conn.close()
        return jsonify(error="journal entry was reversed"), 400
    taken = conn.execute(
        "SELECT 1 FROM erp_acct_bank_txns WHERE matched_entry_id = ?",
        (entry_id,)).fetchone()
    if taken:
        conn.close()
        return jsonify(
            error="journal entry is already matched to another transaction"), 400
    conn.execute(
        "UPDATE erp_acct_bank_txns SET matched_entry_id = ?,"
        " status = 'matched' WHERE id = ?",
        (entry_id, txn_id))
    _acct_audit(conn, actor, "bank.match", "bank_txn", txn_id,
                "txn #%d amount %d date %s matched to entry #%d"
                % (txn_id, txn["amount_cents"], txn["date"], entry_id))
    conn.commit()
    row = conn.execute(
        "SELECT * FROM erp_acct_bank_txns WHERE id = ?", (txn_id,)).fetchone()
    conn.close()
    return jsonify(transaction=_acct_bank_txn_dict(row))


@app.post("/api/erp/accounting/bank-accounts/<int:bank_id>/unmatch")
def erp_acct_unmatch_bank_txn(bank_id):
    actor, err = _erp_check_perm("accounting.write")
    if err:
        return err
    data = request.get_json(force=True) or {}
    try:
        txn_id = int(data.get("txn_id"))
    except (TypeError, ValueError):
        return jsonify(error="txn_id is required"), 400
    conn = db()
    bank = conn.execute(
        "SELECT * FROM erp_acct_bank_accounts WHERE id = ?",
        (bank_id,)).fetchone()
    if not bank:
        conn.close()
        return jsonify(error="bank account not found"), 404
    txn = conn.execute(
        "SELECT * FROM erp_acct_bank_txns"
        " WHERE id = ? AND bank_account_id = ?",
        (txn_id, bank_id)).fetchone()
    if not txn:
        conn.close()
        return jsonify(error="transaction not found for this bank account"), 404
    if txn["status"] != "matched":
        conn.close()
        return jsonify(error="transaction is not matched"), 400
    conn.execute(
        "UPDATE erp_acct_bank_txns SET matched_entry_id = NULL,"
        " status = 'unmatched' WHERE id = ?",
        (txn_id,))
    _acct_audit(conn, actor, "bank.unmatch", "bank_txn", txn_id,
                "txn #%d unmatched from entry #%d" % (
                    txn_id, txn["matched_entry_id"] or 0))
    conn.commit()
    row = conn.execute(
        "SELECT * FROM erp_acct_bank_txns WHERE id = ?", (txn_id,)).fetchone()
    conn.close()
    return jsonify(transaction=_acct_bank_txn_dict(row))


@app.get("/api/erp/accounting/reconciliation/<int:bank_id>")
def erp_acct_reconciliation(bank_id):
    actor, err = _erp_check_perm("accounting.read")
    if err:
        return err
    conn = db()
    bank = conn.execute(
        "SELECT * FROM erp_acct_bank_accounts WHERE id = ?",
        (bank_id,)).fetchone()
    if not bank:
        conn.close()
        return jsonify(error="bank account not found"), 404
    book = _acct_bank_book_balance(conn, bank)
    bank_bal = _acct_bank_bank_balance(conn, bank)
    counts = {}
    for st in ERP_ACCT_TXN_STATUSES:
        row = conn.execute(
            "SELECT COUNT(*) AS n, COALESCE(SUM(amount_cents), 0) AS s"
            " FROM erp_acct_bank_txns"
            " WHERE bank_account_id = ? AND status = ?",
            (bank_id, st)).fetchone()
        counts[st] = {"count": row["n"], "total_cents": row["s"]}
    unmatched = conn.execute(
        "SELECT * FROM erp_acct_bank_txns"
        " WHERE bank_account_id = ? AND status = 'unmatched'"
        " ORDER BY date, id",
        (bank_id,)).fetchall()
    snap = conn.execute(
        "SELECT * FROM erp_acct_reconciliations WHERE bank_account_id = ?"
        " ORDER BY id DESC LIMIT 1",
        (bank_id,)).fetchone()
    out = _acct_bank_dict(conn, bank)
    conn.close()
    return jsonify(bank_account=out, book_balance_cents=book,
                   bank_balance_cents=bank_bal,
                   difference_cents=book - bank_bal, counts=counts,
                   unmatched=[_acct_bank_txn_dict(r) for r in unmatched],
                   last_snapshot=dict(snap) if snap else None)


@app.post("/api/erp/accounting/bank-accounts/<int:bank_id>/close-period")
def erp_acct_close_period(bank_id):
    actor, err = _erp_check_perm("accounting.write")
    if err:
        return err
    data = request.get_json(force=True) or {}
    force = data.get("force") is True
    reason = (data.get("reason") or "").strip()
    conn = db()
    bank = conn.execute(
        "SELECT * FROM erp_acct_bank_accounts WHERE id = ?",
        (bank_id,)).fetchone()
    if not bank:
        conn.close()
        return jsonify(error="bank account not found"), 404
    unmatched = conn.execute(
        "SELECT COUNT(*) AS n FROM erp_acct_bank_txns"
        " WHERE bank_account_id = ? AND status = 'unmatched'",
        (bank_id,)).fetchone()["n"]
    if unmatched > 0 and not force:
        conn.close()
        return jsonify(
            error="%d unmatched transactions remain; match or review them"
            " before closing, or force-close with a reason" % unmatched,
            unmatched_count=unmatched), 400
    if force and not reason:
        conn.close()
        return jsonify(
            error="a reason is required to force-close with unmatched items"), 400
    book = _acct_bank_book_balance(conn, bank)
    bank_bal = _acct_bank_bank_balance(conn, bank)
    now = datetime.now(timezone.utc).isoformat()
    cur = conn.execute(
        "INSERT INTO erp_acct_reconciliations (bank_account_id, closed_at,"
        " closed_by, book_balance_cents, bank_balance_cents,"
        " difference_cents, unmatched_count, forced, reason, created_at)"
        " VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
        (bank_id, now, actor or "", book, bank_bal, book - bank_bal,
         unmatched, 1 if force else 0, reason if force else "", now))
    snap_id = cur.lastrowid
    conn.execute(
        "UPDATE erp_acct_bank_accounts SET last_reconciled_at = ? WHERE id = ?",
        (now, bank_id))
    _acct_audit(conn, actor, "bank.close", "bank_account", bank_id,
                "closed at %s book %d bank %d diff %d unmatched %d%s" % (
                    now, book, bank_bal, book - bank_bal, unmatched,
                    " FORCED: " + reason if force else ""))
    conn.commit()
    snap = conn.execute(
        "SELECT * FROM erp_acct_reconciliations WHERE id = ?",
        (snap_id,)).fetchone()
    out = _acct_bank_dict(conn, conn.execute(
        "SELECT * FROM erp_acct_bank_accounts WHERE id = ?",
        (bank_id,)).fetchone())
    conn.close()
    return jsonify(reconciliation=dict(snap), bank_account=out)




# ---- Accounting sales tax, Nevada only (Phase 1, step 5) ----
# Rates are data in erp_acct_tax_rates, never hardcoded. The stored value
# is percent x 1000 (8375 = 8.375%) per the spec. Tax is computed per
# invoice on the taxable subtotal, round half up. Retail sales are taxable;
# wholesale/resale-exempt sales are not. Nevada returns are due by the
# 20th of the month after the reporting period.
ERP_ACCT_TAX_DEFAULT_JURISDICTION = "Clark County"


def _acct_tax_rate_bps(conn, jurisdiction, on_date):
    """Rate in effect for `jurisdiction` on `on_date` (YYYY-MM-DD), or
    None when no rate covers that date."""
    row = conn.execute(
        "SELECT rate_bps FROM erp_acct_tax_rates WHERE jurisdiction = ?"
        " AND effective_from <= ? AND (effective_to IS NULL OR effective_to >= ?)"
        " ORDER BY effective_from DESC LIMIT 1",
        (jurisdiction, on_date, on_date)).fetchone()
    return row["rate_bps"] if row else None


def _acct_compute_tax_cents(amount_cents, rate_bps):
    """Sales tax in cents for a taxable amount, round half up. Returns
    None for negative inputs (amounts are validated non-negative first)."""
    if amount_cents < 0 or rate_bps < 0:
        return None
    return (amount_cents * rate_bps + 50000) // 100000


def _acct_compute_tax_inclusive_cents(amount_cents, rate_bps):
    """Tax portion of a tax-INCLUSIVE amount, round half up. Used for
    auto-posted retail sales: checkout collects no separate tax line, so
    the amount the customer paid already includes the tax owed.
    Returns None for negative inputs."""
    if amount_cents < 0 or rate_bps < 0:
        return None
    denom = 100000 + rate_bps
    return (amount_cents * rate_bps + denom // 2) // denom


def _acct_tax_filing_dict(row):
    d = dict(row)
    d["outstanding_cents"] = d["tax_collected_cents"] - d["tax_remitted_cents"]
    # Stored status stays open/filed (older code and tests read it);
    # the label is what the return actually is: prepared (open, nothing
    # remitted yet), remitted (open, fully remitted, not yet filed with
    # the state), or filed.
    if d["status"] == "filed":
        d["status_label"] = "filed"
    elif d["tax_remitted_cents"] > 0 and d["outstanding_cents"] == 0:
        d["status_label"] = "remitted"
    else:
        d["status_label"] = "prepared"
    return d


def _acct_tax_next_due():
    """(due_date, period_label) for the most recently completed calendar
    month. Nevada returns are due by the 20th of the month after the
    reporting period."""
    today = datetime.now(timezone.utc).date()
    last_month_end = today.replace(day=1) - timedelta(days=1)
    return today.replace(day=20).isoformat(), last_month_end.strftime("%B %Y")


def _acct_tax_liability(conn, start, end, jurisdiction=None):
    """Collected/remitted/outstanding for a period. Collected and remitted
    come from invoices and remittances (a voided invoice's reversal is not
    a remittance, so raw 2100 debits would overstate what was remitted),
    PLUS tax auto-posted by retail sales (source='sale' journal entries,
    Clark County only -- those sales never create an invoice); the overall
    outstanding is the 2100 ledger balance, and the per-jurisdiction split
    comes from invoices (which carry a jurisdiction) and remittances (which
    carry their filing's jurisdiction)."""
    balance = conn.execute(
        "SELECT COALESCE(SUM(credit_cents - debit_cents), 0) AS b"
        " FROM erp_acct_journal_lines l"
        " JOIN erp_acct_accounts a ON a.id = l.account_id"
        " WHERE a.code = ?", (ERP_ACCT_TAX_PAYABLE_CODE,)).fetchone()["b"]
    jurs = [r[0] for r in conn.execute(
        "SELECT DISTINCT jurisdiction FROM erp_acct_tax_rates"
        " UNION SELECT DISTINCT tax_jurisdiction FROM erp_acct_invoices"
        " UNION SELECT DISTINCT jurisdiction FROM erp_acct_tax_filings"
        " ORDER BY 1").fetchall()]
    # Dept 9 wave B: auto-posted retail sales credit 2100 through
    # source='sale' journal entries and never create an invoice, so the
    # invoice-only sums above miss them. Fold them into the Clark County
    # bucket (the default jurisdiction for every auto-posted sale).
    _sale_tax = {"period": 0, "period_taxable": 0, "all": 0}
    _tax_id = _acct_account_id_by_code(conn, ERP_ACCT_TAX_PAYABLE_CODE)
    _inc_id = _acct_account_id_by_code(conn, ERP_ACCT_RETAIL_INCOME_CODE)
    if _tax_id and _inc_id:
        for _row in conn.execute(
                "SELECT j.date AS d,"
                " COALESCE(SUM(CASE WHEN l.account_id = ?"
                " THEN l.credit_cents - l.debit_cents ELSE 0 END), 0) AS tax,"
                " COALESCE(SUM(CASE WHEN l.account_id = ?"
                " THEN l.credit_cents - l.debit_cents ELSE 0 END), 0) AS taxable"
                " FROM erp_acct_journal j"
                " JOIN erp_acct_journal_lines l ON l.entry_id = j.id"
                " WHERE j.source = 'sale' AND j.reversed_by IS NULL"
                " GROUP BY j.id",
                (_tax_id, _inc_id)).fetchall():
            if _row["tax"]:
                _sale_tax["all"] += _row["tax"]
                if start <= _row["d"] <= end:
                    _sale_tax["period"] += _row["tax"]
                    _sale_tax["period_taxable"] += _row["taxable"]
    by_jur = []
    for jur in jurs:
        if jurisdiction and jur != jurisdiction:
            continue
        c = conn.execute(
            "SELECT COALESCE(SUM(tax_cents), 0) AS c,"
            " COALESCE(SUM(CASE WHEN tax_cents > 0 THEN subtotal_cents ELSE 0 END), 0) AS s"
            " FROM erp_acct_invoices"
            " WHERE status != 'void' AND date >= ? AND date <= ? AND tax_jurisdiction = ?",
            (start, end, jur)).fetchone()
        r = conn.execute(
            "SELECT COALESCE(SUM(rm.amount_cents), 0) AS r"
            " FROM erp_acct_tax_remittances rm"
            " JOIN erp_acct_tax_filings f ON f.id = rm.filing_id"
            " WHERE rm.date >= ? AND rm.date <= ? AND f.jurisdiction = ?",
            (start, end, jur)).fetchone()
        call = conn.execute(
            "SELECT COALESCE(SUM(tax_cents), 0) AS c"
            " FROM erp_acct_invoices WHERE status != 'void' AND tax_jurisdiction = ?",
            (jur,)).fetchone()["c"]
        rall = conn.execute(
            "SELECT COALESCE(SUM(rm.amount_cents), 0) AS r"
            " FROM erp_acct_tax_remittances rm"
            " JOIN erp_acct_tax_filings f ON f.id = rm.filing_id"
            " WHERE f.jurisdiction = ?", (jur,)).fetchone()["r"]
        if jur == ERP_ACCT_TAX_DEFAULT_JURISDICTION:
            c = {"c": c["c"] + _sale_tax["period"],
                 "s": c["s"] + _sale_tax["period_taxable"]}
            call = call + _sale_tax["all"]
        by_jur.append({"jurisdiction": jur, "collected_cents": c["c"],
                       "taxable_sales_cents": c["s"], "remitted_cents": r["r"],
                       "outstanding_cents": call - rall})
    taxable_sales = sum(b["taxable_sales_cents"] for b in by_jur)
    collected = sum(b["collected_cents"] for b in by_jur)
    remitted = sum(b["remitted_cents"] for b in by_jur)
    # Outstanding is the 2100 ledger balance overall; with a jurisdiction
    # filter it is that jurisdiction's collected-minus-remitted, since the
    # ledger balance cannot be split by jurisdiction.
    outstanding = (by_jur[0]["outstanding_cents"] if jurisdiction and by_jur
                   else balance)
    return {"start": start, "end": end, "jurisdiction": jurisdiction,
            "collected_cents": collected, "remitted_cents": remitted,
            "outstanding_cents": outstanding,
            "taxable_sales_cents": taxable_sales,
            "account_balance_cents": balance, "by_jurisdiction": by_jur}


