@app.post("/api/erp/accounting/tax/nexus")
def erp_acct_create_tax_nexus():
    actor, err = _erp_check_perm("tax.write")
    if err:
        return err
    data = request.get_json(force=True) or {}
    jurisdiction = (data.get("jurisdiction") or "").strip()
    if not jurisdiction:
        return jsonify(error="jurisdiction is required"), 400
    state = (data.get("state") or "").strip()
    locality = (data.get("locality") or "").strip()
    basis = (data.get("nexus_basis") or "").strip()
    if basis not in ERP_ACCT_TAX_NEXUS_BASES:
        return jsonify(error="nexus_basis must be one of "
                       + ", ".join(ERP_ACCT_TAX_NEXUS_BASES)), 400
    eff_from = (data.get("effective_from") or "").strip()
    if not _acct_valid_date(eff_from):
        return jsonify(error="effective_from must be YYYY-MM-DD"), 400
    notes = (data.get("notes") or "").strip()
    conn = db()
    clash = conn.execute(
        "SELECT 1 FROM erp_acct_tax_nexus WHERE jurisdiction = ? LIMIT 1",
        (jurisdiction,)).fetchone()
    if clash:
        conn.close()
        return jsonify(error="nexus is already tracked for %s" % jurisdiction), 400
    now = datetime.now(timezone.utc).isoformat()
    cur = conn.execute(
        "INSERT INTO erp_acct_tax_nexus (jurisdiction, state, locality,"
        " nexus_basis, effective_from, active, notes, created_by,"
        " created_at) VALUES (?, ?, ?, ?, ?, 1, ?, ?, ?)",
        (jurisdiction, state, locality, basis, eff_from, notes,
         actor or "", now))
    nexus_id = cur.lastrowid
    _acct_audit(conn, actor, "tax.nexus.create", "tax_nexus", nexus_id,
                "%s (%s) %s from %s" % (jurisdiction, state or "—",
                                        basis, eff_from))
    conn.commit()
    row = conn.execute("SELECT * FROM erp_acct_tax_nexus WHERE id = ?",
                       (nexus_id,)).fetchone()
    conn.close()
    return jsonify(nexus=dict(row)), 201


@app.post("/api/erp/accounting/tax/nexus/<int:nexus_id>")
def erp_acct_update_tax_nexus(nexus_id):
    """Only the active flag and notes change on a nexus row: the
    jurisdiction, basis, and effective date are the record of when
    nexus began, and are not rewritten. Deactivating keeps the row
    (and its filings) as history."""
    actor, err = _erp_check_perm("tax.write")
    if err:
        return err
    data = request.get_json(force=True) or {}
    if "active" not in data and "notes" not in data:
        return jsonify(error="nothing to update: send active and/or notes"), 400
    conn = db()
    row = conn.execute("SELECT * FROM erp_acct_tax_nexus WHERE id = ?",
                       (nexus_id,)).fetchone()
    if not row:
        conn.close()
        return jsonify(error="nexus not found"), 404
    active = row["active"]
    if "active" in data:
        if data.get("active") not in (True, False, 0, 1):
            conn.close()
            return jsonify(error="active must be true or false"), 400
        active = 1 if data.get("active") else 0
    notes = (data.get("notes") or "").strip() if "notes" in data else row["notes"]
    now = datetime.now(timezone.utc).isoformat()
    conn.execute(
        "UPDATE erp_acct_tax_nexus SET active = ?, notes = ?,"
        " updated_by = ?, updated_at = ? WHERE id = ?",
        (active, notes, actor or "", now, nexus_id))
    _acct_audit(conn, actor, "tax.nexus.update", "tax_nexus", nexus_id,
                "%s active=%d" % (row["jurisdiction"], active))
    conn.commit()
    row = conn.execute("SELECT * FROM erp_acct_tax_nexus WHERE id = ?",
                       (nexus_id,)).fetchone()
    conn.close()
    return jsonify(nexus=dict(row))


@app.delete("/api/erp/accounting/tax/nexus/<int:nexus_id>")
def erp_acct_delete_tax_nexus(nexus_id):
    actor, err = _erp_check_perm("tax.write")
    if err:
        return err
    conn = db()
    row = conn.execute("SELECT * FROM erp_acct_tax_nexus WHERE id = ?",
                       (nexus_id,)).fetchone()
    if not row:
        conn.close()
        return jsonify(error="nexus not found"), 404
    filing = conn.execute(
        "SELECT 1 FROM erp_acct_tax_filings WHERE jurisdiction = ? LIMIT 1",
        (row["jurisdiction"],)).fetchone()
    if filing:
        conn.close()
        return jsonify(error="nexus for %s has filings and cannot be deleted"
                       % row["jurisdiction"]), 409
    conn.execute("DELETE FROM erp_acct_tax_nexus WHERE id = ?", (nexus_id,))
    _acct_audit(conn, actor, "tax.nexus.delete", "tax_nexus", nexus_id,
                "%s deleted" % row["jurisdiction"])
    conn.commit()
    conn.close()
    return jsonify(deleted=True)


@app.get("/api/erp/accounting/tax/filings/<int:filing_id>/remittances")
def erp_acct_tax_filing_remittances(filing_id):
    actor, err = _erp_check_perm("tax.read")
    if err:
        return err
    conn = db()
    filing = conn.execute("SELECT * FROM erp_acct_tax_filings WHERE id = ?",
                          (filing_id,)).fetchone()
    if not filing:
        conn.close()
        return jsonify(error="filing not found"), 404
    rows = conn.execute(
        "SELECT rm.*, b.name AS bank_name FROM erp_acct_tax_remittances rm"
        " LEFT JOIN erp_acct_bank_accounts b ON b.id = rm.bank_account_id"
        " WHERE rm.filing_id = ? ORDER BY rm.date, rm.id",
        (filing_id,)).fetchall()
    conn.close()
    return jsonify(filing_id=filing_id, remittances=[dict(r) for r in rows])


@app.post("/api/erp/accounting/tax/filings/<int:filing_id>/amend")
def erp_acct_amend_tax_filing(filing_id):
    """An amended filing: a NEW filing record for the same period and
    jurisdiction, linked to the filed one it corrects. The filed filing
    is history and is never changed or deleted. The amendment
    re-computes the figures from the sales as they stand now, so a sale
    posted after the original filing (or a corrected invoice) flows
    into the amended packet. Only a filed filing can be amended."""
    actor, err = _erp_check_perm("tax.write")
    if err:
        return err
    conn = db()
    orig = conn.execute("SELECT * FROM erp_acct_tax_filings WHERE id = ?",
                        (filing_id,)).fetchone()
    if not orig:
        conn.close()
        return jsonify(error="filing not found"), 404
    if orig["status"] != "filed":
        conn.close()
        return jsonify(error="only a filed filing can be amended"), 400
    start, end, jurisdiction = orig["period_start"], orig["period_end"], orig["jurisdiction"]
    comp = _acct_tax_filing_compute(conn, start, end, jurisdiction)
    if comp["tax_due_cents"] is None:
        conn.close()
        return jsonify(error="no tax rate in effect for some sales in"
                       " this period for %s" % jurisdiction), 400
    clash = conn.execute(
        "SELECT 1 FROM erp_acct_tax_filings WHERE jurisdiction = ?"
        " AND period_start <= ? AND period_end >= ? AND id != ?"
        " AND status = 'open' LIMIT 1",
        (jurisdiction, end, start, filing_id)).fetchone()
    if clash:
        conn.close()
        return jsonify(error="an open filing already exists for this period"), 400
    now = datetime.now(timezone.utc).isoformat()
    cur = conn.execute(
        "INSERT INTO erp_acct_tax_filings (period_start, period_end,"
        " jurisdiction, taxable_sales_cents, tax_collected_cents,"
        " tax_remitted_cents, exempt_sales_cents, tax_due_cents,"
        " confirmation_number, amended_from_id, status, filed_at,"
        " filed_by, created_at)"
        " VALUES (?, ?, ?, ?, ?, 0, ?, ?, '', ?, 'open', NULL, '', ?)",
        (start, end, jurisdiction, comp["taxable_sales_cents"],
         comp["tax_collected_cents"], comp["exempt_sales_cents"],
         comp["tax_due_cents"], filing_id, now))
    new_id = cur.lastrowid
    _acct_audit(conn, actor, "tax.filing.amend", "tax_filing", new_id,
                "%s %s to %s amends filing #%d taxable %d exempt %d"
                " collected %d due %d" % (
                    jurisdiction, start, end, filing_id,
                    comp["taxable_sales_cents"], comp["exempt_sales_cents"],
                    comp["tax_collected_cents"], comp["tax_due_cents"]))
    conn.commit()
    row = conn.execute("SELECT * FROM erp_acct_tax_filings WHERE id = ?",
                       (new_id,)).fetchone()
    conn.close()
    return jsonify(filing=_acct_tax_filing_dict(row)), 201


@app.delete("/api/erp/accounting/tax/filings/<int:filing_id>")
def erp_acct_delete_tax_filing(filing_id):
    """Delete is permanent, and only for a prepared filing with nothing
    remitted. A filed (or remitted) filing is history: it is refused
    (409) and corrected with an amended filing instead. A prepared
    filing with a remittance posted is refused too -- the remittance
    journal entry is posted history and the filing is its link to it.
    Deleting a prepared filing also removes its checklist rows."""
    actor, err = _erp_check_perm("tax.write")
    if err:
        return err
    conn = db()
    filing = conn.execute("SELECT * FROM erp_acct_tax_filings WHERE id = ?",
                          (filing_id,)).fetchone()
    if not filing:
        conn.close()
        return jsonify(error="filing not found"), 404
    if filing["status"] != "open":
        conn.close()
        return jsonify(error="a filed filing is history and cannot be deleted;"
                       " amend it instead"), 409
    if filing["tax_remitted_cents"] > 0:
        conn.close()
        return jsonify(error="this filing has a remittance posted and cannot"
                       " be deleted"), 409
    n_remit = conn.execute(
        "SELECT COUNT(*) AS c FROM erp_acct_tax_remittances"
        " WHERE filing_id = ?", (filing_id,)).fetchone()["c"]
    if n_remit:
        conn.close()
        return jsonify(error="this filing has a remittance posted and cannot"
                       " be deleted"), 409
    conn.execute("DELETE FROM erp_acct_tax_checklist WHERE filing_id = ?",
                 (filing_id,))
    conn.execute("DELETE FROM erp_acct_tax_filings WHERE id = ?", (filing_id,))
    _acct_audit(conn, actor, "tax.filing.delete", "tax_filing", filing_id,
                "%s %s to %s prepared filing deleted" % (
                    filing["jurisdiction"], filing["period_start"],
                    filing["period_end"]))
    conn.commit()
    conn.close()
    return jsonify(deleted=True)


# ---- Sales-tax filing checklist + reminder (Phase 1 gap 2, Nov 10) ----
# Spec 2.6 wants a filing checklist and a reminder before the due date.
# The checklist is five fixed steps per filing; the reminder is a
# cron-secret endpoint the daily job calls, once per kind per period.
ERP_ACCT_TAX_CHECKLIST_ITEMS = (
    ("verify_liability",
     "Verify the computed liability against invoices plus auto-posted retail tax"),
    ("reconcile_2100",
     "Reconcile account 2100 (Sales Tax Payable) to the computed liability"),
    ("remit_payment", "Remittance posted (Dr 2100 / Cr cash)"),
    ("file_return", "Return filed with the Nevada Department of Taxation"),
    ("save_confirmation", "Filing confirmation saved"),
)
ERP_ACCT_TAX_CHECKLIST_LABELS = dict(ERP_ACCT_TAX_CHECKLIST_ITEMS)


def _acct_tax_checklist_items(conn, filing_id):
    done = {r["item_key"]: r for r in conn.execute(
        "SELECT * FROM erp_acct_tax_checklist"
        " WHERE filing_id = ? AND done = 1",
        (filing_id,)).fetchall()}
    return [{"item_key": k, "label": label,
             "done": k in done,
             "done_by": done[k]["done_by"] if k in done else "",
             "done_at": done[k]["done_at"] if k in done else None}
            for k, label in ERP_ACCT_TAX_CHECKLIST_ITEMS]


@app.get("/api/erp/accounting/tax/filings/<int:filing_id>/checklist")
def erp_acct_tax_checklist(filing_id):
    actor, err = _erp_check_perm("tax.read")
    if err:
        return err
    conn = db()
    filing = conn.execute("SELECT * FROM erp_acct_tax_filings WHERE id = ?",
                          (filing_id,)).fetchone()
    if not filing:
        conn.close()
        return jsonify(error="filing not found"), 404
    items = _acct_tax_checklist_items(conn, filing_id)
    conn.close()
    return jsonify(filing_id=filing_id, items=items)


@app.post("/api/erp/accounting/tax/filings/<int:filing_id>/checklist")
def erp_acct_tax_checklist_set(filing_id):
    actor, err = _erp_check_perm("tax.write")
    if err:
        return err
    data = request.get_json(force=True) or {}
    item_key = (data.get("item_key") or "").strip()
    if item_key not in ERP_ACCT_TAX_CHECKLIST_LABELS:
        return jsonify(error="item_key must be one of "
                       + ", ".join(k for k, _ in ERP_ACCT_TAX_CHECKLIST_ITEMS)), 400
    done = data.get("done")
    if done not in (True, False):
        return jsonify(error="done must be true or false"), 400
    conn = db()
    filing = conn.execute("SELECT * FROM erp_acct_tax_filings WHERE id = ?",
                          (filing_id,)).fetchone()
    if not filing:
        conn.close()
        return jsonify(error="filing not found"), 404
    now = datetime.now(timezone.utc).isoformat()
    if done:
        existing = conn.execute(
            "SELECT id FROM erp_acct_tax_checklist"
            " WHERE filing_id = ? AND item_key = ?",
            (filing_id, item_key)).fetchone()
        if existing:
            conn.execute("UPDATE erp_acct_tax_checklist"
                         " SET done = 1, done_by = ?, done_at = ?"
                         " WHERE id = ?",
                         (actor or "", now, existing["id"]))
        else:
            conn.execute(
                "INSERT INTO erp_acct_tax_checklist (filing_id, item_key,"
                " done, done_by, done_at, created_at)"
                " VALUES (?, ?, 1, ?, ?, ?)",
                (filing_id, item_key, actor or "", now, now))
        _acct_audit(conn, actor, "tax.checklist", "tax_filing", filing_id,
                    "%s checked" % item_key)
    else:
        # No DELETE: permanence -- the row stays with done=0.
        conn.execute("UPDATE erp_acct_tax_checklist SET done = 0"
                     " WHERE filing_id = ? AND item_key = ?",
                     (filing_id, item_key))
        _acct_audit(conn, actor, "tax.checklist", "tax_filing", filing_id,
                    "%s unchecked" % item_key)
    conn.commit()
    items = _acct_tax_checklist_items(conn, filing_id)
    conn.close()
    return jsonify(filing_id=filing_id, items=items)


def _acct_tax_remind_auth():
    if CRON_SECRET and hmac.compare_digest(request.headers.get("X-Cron-Secret", ""), CRON_SECRET):
        return "cron", None
    return _erp_check_perm("tax.write")


@app.post("/api/erp/accounting/tax/remind")
def erp_acct_tax_remind():
    """Send the sales-tax filing reminder for the most recently
    completed month, once per kind per period. 'due_soon' fires in the
    5 days before the 20th; 'overdue' fires after the 20th; both only
    while the filing is not filed (or not created yet). Idempotent on
    erp_acct_tax_reminders. Body {"as_of": "YYYY-MM-DD"} overrides
    today (tests / manual trigger); default is today (UTC)."""
    actor, err = _acct_tax_remind_auth()
    if err:
        return err
    data = request.get_json(silent=True) or {}
    as_of_raw = (data.get("as_of") or "").strip()
    if as_of_raw:
        if not _acct_valid_date(as_of_raw):
            return jsonify(error="as_of must be YYYY-MM-DD"), 400
        today = datetime.strptime(as_of_raw, "%Y-%m-%d").date()
    else:
        today = datetime.now(timezone.utc).date()
    due = today.replace(day=20)
    first_this = today.replace(day=1)
    last_prev = first_this - timedelta(days=1)
    period_start = last_prev.replace(day=1).isoformat()
    period_end = last_prev.isoformat()
    period_label = last_prev.strftime("%B %Y")
    jurisdiction = ERP_ACCT_TAX_DEFAULT_JURISDICTION
    if today > due:
        kind = "overdue"
    elif (due - today).days <= 5:
        kind = "due_soon"
    else:
        return jsonify(reminded=False, kind=None, period_start=period_start,
                       period_end=period_end, due=due.isoformat(),
                       reason="outside the reminder window")
    conn = db()
    filing = conn.execute(
        "SELECT * FROM erp_acct_tax_filings WHERE jurisdiction = ?"
        " AND period_start <= ? AND period_end >= ? LIMIT 1",
        (jurisdiction, period_end, period_start)).fetchone()
    if filing and filing["status"] == "filed":
        conn.close()
        return jsonify(reminded=False, kind=kind, period_start=period_start,
                       period_end=period_end, due=due.isoformat(),
                       reason="filing already filed")
    sent = conn.execute(
        "SELECT * FROM erp_acct_tax_reminders WHERE period_start = ?"
        " AND period_end = ? AND kind = ?",
        (period_start, period_end, kind)).fetchone()
    if sent:
        conn.close()
        return jsonify(reminded=False, kind=kind, period_start=period_start,
                       period_end=period_end, due=due.isoformat(),
                       reason="reminder already sent",
                       sent_at=sent["sent_at"])
    if filing:
        outstanding = filing["tax_collected_cents"] - filing["tax_remitted_cents"]
        detail = ("Collected $%.2f, remitted $%.2f, outstanding $%.2f."
                  % (filing["tax_collected_cents"] / 100.0,
                     filing["tax_remitted_cents"] / 100.0,
                     outstanding / 100.0))
        filing_status = filing["status"]
    else:
        detail = "No filing has been created for this period yet."
        filing_status = "missing"
    subject = ("Sales tax filing %s - %s %s (due %s)"
               % ("overdue" if kind == "overdue" else "due soon",
                  jurisdiction, period_label, due.isoformat()))
    body = ("The %s sales tax return for %s is due %s. %s<br><br>"
            "Open the ERP Accounting tab, Sales Tax, to remit and file it:"
            " https://erp.pop-a-licious.com/#/accounting"
            % (jurisdiction, period_label, due.isoformat(), detail))
    sent_to = []
    try:
        for to in ADMIN_EMAILS:
            send_email(to, subject, body)
            sent_to.append(to)
    except Exception as exc:
        conn.close()
        return jsonify(error="reminder email failed: %s" % exc), 502
    now = datetime.now(timezone.utc).isoformat()
    conn.execute(
        "INSERT INTO erp_acct_tax_reminders (period_start, period_end, kind,"
        " sent_at, sent_to) VALUES (?, ?, ?, ?, ?)",
        (period_start, period_end, kind, now, ", ".join(sent_to)))
    _acct_audit(conn, actor, "tax.remind", "tax_filing",
                filing["id"] if filing else 0,
                "%s %s reminder sent to %s (filing %s)"
                % (period_label, kind, ", ".join(sent_to), filing_status))
    conn.commit()
    conn.close()
    return jsonify(reminded=True, kind=kind, period_start=period_start,
                   period_end=period_end, due=due.isoformat(),
                   filing_status=filing_status, sent_to=sent_to)


@app.get("/api/erp/accounting/tax/reminders")
def erp_acct_tax_reminders_list():
    """Reminder log for the Sales Tax tab: one row per reminder sent,
    newest first. The daily job POSTs /tax/remind; this read shows
    whether it fired."""
    actor, err = _erp_check_perm("tax.read")
    if err:
        return err
    conn = db()
    rows = conn.execute(
        "SELECT * FROM erp_acct_tax_reminders"
        " ORDER BY sent_at DESC LIMIT 50").fetchall()
    conn.close()
    return jsonify(reminders=[dict(r) for r in rows])


# ---- Payroll (Phase 1 step 6) ----
# Nobody is paid yet: no payroll history exists and none migrates. The
# structure is built now so it switches on the day pay starts. All
# withholding is computed server-side from the seeded tables; the client
# never supplies tax amounts. All money is integer cents.
ERP_ACCT_PAYROLL_EXP_CODE = "6500"
ERP_ACCT_PAYROLL_TAX_EXP_CODE = "6600"
ERP_ACCT_PAYROLL_LIAB_CODE = "2200"
ERP_PAYROLL_SCHEDULES = {"weekly": 52, "biweekly": 26, "monthly": 12}
ERP_PAYROLL_PAY_TYPES = ("salary", "hourly")
ERP_PAYROLL_FILING_STATUSES = ("single", "married_jointly",
                               "married_separately", "head_of_household")


def _acct_round_div(n, d):
    """Round n/d to the nearest integer, halves up. n >= 0, d > 0."""
    return (2 * n + d) // (2 * d)


def _acct_payroll_fica(conn, tax_year):
    row = conn.execute(
        "SELECT brackets FROM erp_acct_payroll_tax_tables"
        " WHERE tax_year = ? AND table_name = 'fica'",
        (tax_year,)).fetchone()
    if not row:
        return None
    try:
        params = json.loads(row["brackets"])
    except (ValueError, TypeError):
        return None
    if not isinstance(params, dict):
        return None
    return params


def _acct_payroll_withholding_table(conn, tax_year, filing_status, step2):
    name = "federal-%s-%s" % (filing_status, "step2" if step2 else "standard")
    row = conn.execute(
        "SELECT brackets FROM erp_acct_payroll_tax_tables"
        " WHERE tax_year = ? AND table_name = ?",
        (tax_year, name)).fetchone()
    if not row:
        return None
    try:
        brackets = json.loads(row["brackets"])
    except (ValueError, TypeError):
        return None
    if not isinstance(brackets, list) or not brackets:
        return None
    return brackets


def _acct_federal_withholding_cents(conn, tax_year, filing_status, step2,
                                    periods, adjusted_annual_cents,
                                    step3_credit_cents, step4c_cents):
    """IRS Publication 15-T percentage method (Worksheet 1A): look the
    adjusted annual wage up in the seeded table, divide the annual
    tentative withholding by the pay periods, subtract the Step 3 credit
    per period, add the Step 4(c) additional withholding. Returns
    (cents, None) or (None, error)."""
    brackets = _acct_payroll_withholding_table(conn, tax_year, filing_status,
                                              step2)
    if brackets is None:
        return None, "no federal withholding table for tax year %d" % tax_year
    wage = max(0, adjusted_annual_cents)
    bracket = brackets[0]
    for b in brackets:
        if wage >= b["min_cents"]:
            bracket = b
        else:
            break
    annual = bracket["base_cents"] + _acct_round_div(
        (wage - bracket["min_cents"]) * bracket["rate_bps"], 10000)
    per_period = _acct_round_div(annual, periods)
    credit = _acct_round_div(step3_credit_cents, periods)
    return max(0, per_period - credit) + step4c_cents, None


def _acct_payroll_compute_line(conn, emp, gross_cents, ytd_before_cents,
                               tax_year):
    """Withholding for one pay line. Social Security 6.2% up to the wage
    base (year-to-date from approved/paid runs in the same calendar year);
    Medicare 1.45% on all wages plus 0.9% additional Medicare on wages
    over $200,000 year-to-date (employee only — the employer never matches
    it); federal income tax from the seeded Pub 15-T table. Returns
    (line_dict, None) or (None, error)."""
    periods = ERP_PAYROLL_SCHEDULES[emp["pay_schedule"]]
    fica = _acct_payroll_fica(conn, tax_year)
    if fica is None:
        return None, "no FICA table for tax year %d" % tax_year
    ss_taxable = max(0, min(gross_cents,
                            fica["ss_wage_base_cents"] - ytd_before_cents))
    ss_emp = _acct_round_div(ss_taxable * fica["ss_rate_bps"], 10000)
    ss_er = ss_emp
    med_base = _acct_round_div(gross_cents * fica["medicare_rate_bps"], 10000)
    addl_excess = max(0, ytd_before_cents + gross_cents
                      - fica["addl_medicare_threshold_cents"])
    addl = _acct_round_div(
        min(gross_cents, addl_excess) * fica["addl_medicare_rate_bps"], 10000)
    med_emp = med_base + addl
    med_er = med_base
    if emp["exempt"]:
        federal = 0
    else:
        adjusted_annual = max(
            0, gross_cents * periods + emp["step4a_cents"] - emp["step4b_cents"])
        federal, error = _acct_federal_withholding_cents(
            conn, tax_year, emp["filing_status"], bool(emp["step2_checkbox"]),
            periods, adjusted_annual, emp["step3_credit_cents"],
            emp["step4c_cents"])
        if error:
            return None, error
    net = gross_cents - federal - ss_emp - med_emp
    return {
        "gross_cents": gross_cents, "federal_cents": federal,
        "ss_cents": ss_emp, "medicare_cents": med_emp, "net_cents": net,
        "employer_ss_cents": ss_er, "employer_medicare_cents": med_er,
        "employer_tax_cents": ss_er + med_er,
    }, None


def _acct_employee_dict(row):
    d = dict(row)
    for k in ("step2_checkbox", "exempt", "active"):
        d[k] = bool(d[k])
    # The full SSN is never returned by any endpoint: only whether one
    # is on file and its last 4 digits, for W-2 completeness checks.
    ssn = d.pop("ssn", "") or ""
    d["ssn_on_file"] = bool(ssn)
    d["ssn_last4"] = ssn[-4:] if ssn else ""
    return d


def _acct_payroll_bool(value, default=None):
    if value is None:
        return default
    if isinstance(value, bool):
        return value
    if value in (0, 1):
        return bool(value)
    return None


def _acct_payroll_employee_fields(data, partial=False):
    """Validate an employee pay profile. Returns (fields, None) or
    (None, error). rate_cents is the ANNUAL salary in cents for salary
    employees and cents per HOUR for hourly employees."""
    fields = {}
    if not partial or "first_name" in data:
        v = (data.get("first_name") or "").strip()
        if not v:
            return None, "first_name is required"
        fields["first_name"] = v
    if not partial or "last_name" in data:
        v = (data.get("last_name") or "").strip()
        if not v:
            return None, "last_name is required"
        fields["last_name"] = v
    if not partial or "pay_type" in data:
        v = (data.get("pay_type") or "").strip()
        if v not in ERP_PAYROLL_PAY_TYPES:
            return None, "pay_type must be salary or hourly"
        fields["pay_type"] = v
    if not partial or "rate_cents" in data:
        v = _acct_int_cents(data.get("rate_cents"))
        if v is None or v < 1:
            return None, "rate_cents must be whole cents greater than zero"
        fields["rate_cents"] = v
    if not partial or "pay_schedule" in data:
        v = (data.get("pay_schedule") or "").strip()
        if v not in ERP_PAYROLL_SCHEDULES:
            return None, "pay_schedule must be weekly, biweekly, or monthly"
        fields["pay_schedule"] = v
    if "filing_status" in data:
        v = (data.get("filing_status") or "").strip()
        if v not in ERP_PAYROLL_FILING_STATUSES:
            return None, "filing_status must be single, married_jointly, married_separately, or head_of_household"
        fields["filing_status"] = v
    elif not partial:
        fields["filing_status"] = "single"
    for key in ("step2_checkbox", "exempt"):
        if key in data:
            v = _acct_payroll_bool(data.get(key))
            if v is None:
                return None, key + " must be true or false"
            fields[key] = 1 if v else 0
        elif not partial:
            fields[key] = 0
    if "ssn" in data:
        # Admin-entered only, for W-2s. Digits only are stored; dashes
        # in what the admin types are stripped. Blank clears it. A
        # value that is not 9 digits is refused, never stored partial.
        raw = data.get("ssn")
        if raw is None:
            raw = ""
        if not isinstance(raw, str):
            return None, "ssn must be a string of 9 digits"
        digits = "".join(ch for ch in raw if ch.isdigit())
        if raw.strip() == "":
            fields["ssn"] = ""
        elif len(digits) == 9:
            fields["ssn"] = digits
        else:
            return None, "ssn must be 9 digits"
    for key in ("step3_credit_cents", "step4a_cents", "step4b_cents",
                "step4c_cents"):
        if key in data:
            v = _acct_int_cents(data.get(key))
            if v is None or v < 0:
                return None, key + " must be whole cents of zero or more"
            fields[key] = v
        elif not partial:
            fields[key] = 0
    return fields, None


def _acct_payrun_dict(conn, run):
    d = dict(run)
    lines = conn.execute(
        "SELECT * FROM erp_acct_payrun_lines WHERE payrun_id = ? ORDER BY id",
        (run["id"],)).fetchall()
    out = []
    for line in lines:
        ld = dict(line)
        try:
            ld["pay_stub"] = json.loads(line["pay_stub_json"] or "{}")
        except (ValueError, TypeError):
            ld["pay_stub"] = {}
        try:
            ld["timeclock_ids"] = json.loads(line["timeclock_ids"] or "[]")
        except (ValueError, TypeError):
            ld["timeclock_ids"] = []
        emp = conn.execute(
            "SELECT first_name, last_name FROM erp_acct_employees"
            " WHERE id = ?", (line["employee_id"],)).fetchone()
        ld["employee_name"] = (
            (emp["first_name"] + " " + emp["last_name"]) if emp else "")
        out.append(ld)
    d["lines"] = out
    return d


def _acct_payroll_ytd_cents(conn, employee_id, tax_year):
    row = conn.execute(
        "SELECT COALESCE(SUM(l.gross_cents), 0) AS ytd"
        " FROM erp_acct_payrun_lines l"
        " JOIN erp_acct_payruns r ON r.id = l.payrun_id"
        " WHERE l.employee_id = ? AND r.status IN ('approved', 'paid')"
        " AND substr(r.period_start, 1, 4) = ?",
        (employee_id, str(tax_year))).fetchone()
    return row["ytd"]


