@app.post("/api/erp/accounting/payroll/runs/<int:run_id>/pay")
def erp_acct_pay_payroll_run(run_id):
    actor, err = _erp_check_perm("payroll.write")
    if err:
        return err
    conn = db()
    row = conn.execute("SELECT * FROM erp_acct_payruns WHERE id = ?",
                       (run_id,)).fetchone()
    if not row:
        conn.close()
        return jsonify(error="pay run not found"), 404
    if row["status"] != "approved":
        conn.close()
        return jsonify(error="only an approved pay run can be paid"), 400
    if row["gross_cents"] <= 0:
        conn.close()
        return jsonify(error="pay run has no gross pay to post"), 400
    cash_id = _acct_account_id_by_code(conn, ERP_ACCT_CASH_CODE)
    liab_id = _acct_account_id_by_code(conn, ERP_ACCT_PAYROLL_LIAB_CODE)
    exp_id = _acct_account_id_by_code(conn, ERP_ACCT_PAYROLL_EXP_CODE)
    taxexp_id = _acct_account_id_by_code(conn, ERP_ACCT_PAYROLL_TAX_EXP_CODE)
    if not cash_id or not liab_id or not exp_id or not taxexp_id:
        conn.close()
        return jsonify(error="chart of accounts is missing a required account"), 500
    withheld = (row["federal_withheld_cents"] + row["ss_cents"]
                + row["medicare_cents"])
    memo = "Payroll — %s to %s, pay date %s" % (
        row["period_start"], row["period_end"], row["pay_date"])
    lines = [{"account_id": exp_id, "debit_cents": row["gross_cents"],
              "credit_cents": 0, "memo": memo}]
    if row["employer_tax_cents"] > 0:
        lines.append({"account_id": taxexp_id,
                      "debit_cents": row["employer_tax_cents"],
                      "credit_cents": 0, "memo": memo})
    if row["net_cents"] > 0:
        lines.append({"account_id": cash_id, "debit_cents": 0,
                      "credit_cents": row["net_cents"], "memo": memo})
    if withheld + row["employer_tax_cents"] > 0:
        lines.append({"account_id": liab_id, "debit_cents": 0,
                      "credit_cents": withheld + row["employer_tax_cents"],
                      "memo": memo})
    entry_id, error = _acct_post_entry(conn, actor, row["pay_date"], memo,
                                       "payroll", run_id, lines)
    if error:
        conn.close()
        return jsonify(error=error), 400
    now = datetime.now(timezone.utc).isoformat()
    conn.execute(
        "UPDATE erp_acct_payruns SET status = 'paid', paid_at = ?,"
        " journal_entry_id = ? WHERE id = ?", (now, entry_id, run_id))
    _acct_audit(conn, actor, "payroll.run.pay", "payroll_run", run_id,
                "run #%d paid %s entry #%d gross %d net %d" % (
                    run_id, row["pay_date"], entry_id,
                    row["gross_cents"], row["net_cents"]))
    conn.commit()
    row = conn.execute("SELECT * FROM erp_acct_payruns WHERE id = ?",
                       (run_id,)).fetchone()
    out = _acct_payrun_dict(conn, row)
    conn.close()
    return jsonify(run=out, journal_entry_id=entry_id)


@app.post("/api/erp/accounting/payroll/runs/<int:run_id>/lines/<int:line_id>/unfeed")
def erp_acct_payroll_line_unfeed(run_id, line_id):
    """Un-feed a store-timeclock line: allowed only while the run is
    still draft. The line is deleted, its run totals are recomputed
    from the remaining lines, and its timeclock rows are unlinked so
    they can be fed again. The payroll flow itself (approve -> pay ->
    posting) is unchanged."""
    actor, err = _erp_check_perm("payroll.write")
    if err:
        return err
    conn = db()
    run = conn.execute("SELECT * FROM erp_acct_payruns WHERE id = ?",
                       (run_id,)).fetchone()
    if not run:
        conn.close()
        return jsonify(error="pay run not found"), 404
    if run["status"] != "draft":
        conn.close()
        return jsonify(error="pay run %d is %s, not draft -- only draft runs can be un-fed" % (run_id, run["status"])), 409
    line = conn.execute(
        "SELECT * FROM erp_acct_payrun_lines WHERE id = ? AND payrun_id = ?",
        (line_id, run_id)).fetchone()
    if not line:
        conn.close()
        return jsonify(error="pay run line not found"), 404
    if (line["source"] or "") != "store_timeclock":
        conn.close()
        return jsonify(error="only store-timeclock lines can be un-fed"), 400
    emp = conn.execute(
        "SELECT first_name, last_name FROM erp_acct_employees"
        " WHERE id = ?", (line["employee_id"],)).fetchone()
    emp_name = ((emp["first_name"] + " " + emp["last_name"]) if emp
                else ("employee #%d" % line["employee_id"]))
    try:
        tc_ids = json.loads(line["timeclock_ids"] or "[]") or []
    except (TypeError, ValueError):
        tc_ids = []
    for tc_id in tc_ids:
        conn.execute(
            "UPDATE erp_store_timeclock SET payrun_line_id = NULL"
            " WHERE id = ? AND payrun_line_id = ?",
            (tc_id, line_id))
    conn.execute("DELETE FROM erp_acct_payrun_lines WHERE id = ?",
                 (line_id,))
    # Recompute the run totals from the remaining lines. Employer SS
    # equals employee SS by construction, and employer Medicare is
    # the base 1.45% on gross (the 0.9% additional Medicare is
    # employee-only, never an employer share).
    fica = _acct_payroll_fica(conn, int(run["period_start"][:4]))
    if fica is None:
        conn.close()
        return jsonify(error="no FICA table for tax year %s"
                       % run["period_start"][:4]), 400
    remaining = conn.execute(
        "SELECT * FROM erp_acct_payrun_lines WHERE payrun_id = ?",
        (run_id,)).fetchall()
    totals = {
        "gross_cents": sum(int(l["gross_cents"] or 0) for l in remaining),
        "federal_cents": sum(int(l["federal_cents"] or 0) for l in remaining),
        "ss_cents": sum(int(l["ss_cents"] or 0) for l in remaining),
        "medicare_cents": sum(int(l["medicare_cents"] or 0)
                              for l in remaining),
        "net_cents": sum(int(l["net_cents"] or 0) for l in remaining),
    }
    totals["employer_ss_cents"] = totals["ss_cents"]
    totals["employer_medicare_cents"] = sum(
        _acct_round_div(int(l["gross_cents"] or 0)
                        * fica["medicare_rate_bps"], 10000)
        for l in remaining)
    totals["employer_tax_cents"] = (totals["employer_ss_cents"]
                                    + totals["employer_medicare_cents"])
    conn.execute(
        "UPDATE erp_acct_payruns SET gross_cents = ?,"
        " federal_withheld_cents = ?, ss_cents = ?, medicare_cents = ?,"
        " employer_tax_cents = ?, employer_ss_cents = ?,"
        " employer_medicare_cents = ?, net_cents = ? WHERE id = ?",
        (totals["gross_cents"], totals["federal_cents"],
         totals["ss_cents"], totals["medicare_cents"],
         totals["employer_tax_cents"], totals["employer_ss_cents"],
         totals["employer_medicare_cents"], totals["net_cents"], run_id))
    _acct_audit(conn, actor, "payroll.run.unfeed", "payroll_run", run_id,
                "un-fed line #%d (%s, %d timeclock rows) from draft run #%d"
                % (line_id, emp_name, len(tc_ids), run_id))
    conn.commit()
    row = conn.execute("SELECT * FROM erp_acct_payruns WHERE id = ?",
                       (run_id,)).fetchone()
    out = _acct_payrun_dict(conn, row)
    conn.close()
    return jsonify(run=out, unlinked=len(tc_ids))


@app.get("/api/erp/accounting/payroll/tax-filings")
def erp_acct_payroll_tax_filings():
    actor, err = _erp_check_perm("payroll.read")
    if err:
        return err
    conn = db()
    rows = conn.execute(
        "SELECT * FROM erp_acct_payruns WHERE status = 'paid'"
        " ORDER BY pay_date").fetchall()
    by_quarter = {}
    for r in rows:
        year = int(r["pay_date"][:4])
        month = int(r["pay_date"][5:7])
        quarter = "%d-Q%d" % (year, (month - 1) // 3 + 1)
        q = by_quarter.setdefault(quarter, {
            "quarter": quarter, "gross_cents": 0, "federal_cents": 0,
            "ss_cents": 0, "medicare_cents": 0, "employer_tax_cents": 0,
            "net_cents": 0, "run_count": 0})
        q["gross_cents"] += r["gross_cents"]
        q["federal_cents"] += r["federal_withheld_cents"]
        q["ss_cents"] += r["ss_cents"] + r["employer_ss_cents"]
        q["medicare_cents"] += r["medicare_cents"] + r["employer_medicare_cents"]
        q["employer_tax_cents"] += r["employer_tax_cents"]
        q["net_cents"] += r["net_cents"]
        q["run_count"] += 1
    filed = {r["quarter"]: dict(r) for r in conn.execute(
        "SELECT * FROM erp_acct_payroll_filings").fetchall()}
    conn.close()
    out = []
    for quarter in sorted(by_quarter, reverse=True):
        q = by_quarter[quarter]
        f = filed.get(quarter)
        q["status"] = "filed" if f else "owed"
        q["filed_at"] = f["filed_at"] if f else None
        q["filed_by"] = f["filed_by"] if f else ""
        out.append(q)
    return jsonify(quarters=out)


@app.post("/api/erp/accounting/payroll/tax-filings")
def erp_acct_file_payroll_quarter():
    actor, err = _erp_check_perm("payroll.write")
    if err:
        return err
    data = request.get_json(force=True) or {}
    quarter = (data.get("quarter") or "").strip()
    try:
        year, qnum = quarter.split("-Q")
        year = int(year)
        qnum = int(qnum)
        if qnum < 1 or qnum > 4:
            raise ValueError
    except (ValueError, AttributeError):
        return jsonify(error="quarter must look like 2026-Q4"), 400
    conn = db()
    rows = conn.execute(
        "SELECT * FROM erp_acct_payruns WHERE status = 'paid'").fetchall()
    totals = {"federal_cents": 0, "ss_cents": 0, "medicare_cents": 0,
              "employer_tax_cents": 0}
    for r in rows:
        ryear = int(r["pay_date"][:4])
        rmonth = int(r["pay_date"][5:7])
        rquarter = "%d-Q%d" % (ryear, (rmonth - 1) // 3 + 1)
        if rquarter != quarter:
            continue
        totals["federal_cents"] += r["federal_withheld_cents"]
        totals["ss_cents"] += r["ss_cents"] + r["employer_ss_cents"]
        totals["medicare_cents"] += r["medicare_cents"] + r["employer_medicare_cents"]
        totals["employer_tax_cents"] += r["employer_tax_cents"]
    if not any(totals.values()):
        conn.close()
        return jsonify(error="no paid pay runs in that quarter"), 400
    existing = conn.execute(
        "SELECT 1 FROM erp_acct_payroll_filings WHERE quarter = ?",
        (quarter,)).fetchone()
    if existing:
        conn.close()
        return jsonify(error="quarter %s is already filed" % quarter), 400
    now = datetime.now(timezone.utc).isoformat()
    cur = conn.execute(
        "INSERT INTO erp_acct_payroll_filings (quarter, federal_cents,"
        " ss_cents, medicare_cents, employer_tax_cents, filed_at, filed_by,"
        " created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?)",
        (quarter, totals["federal_cents"], totals["ss_cents"],
         totals["medicare_cents"], totals["employer_tax_cents"], now,
         actor or "", now))
    filing_id = cur.lastrowid
    _acct_audit(conn, actor, "payroll.tax.file", "payroll_filing", filing_id,
                "%s federal %d ss %d medicare %d employer tax %d" % (
                    quarter, totals["federal_cents"], totals["ss_cents"],
                    totals["medicare_cents"], totals["employer_tax_cents"]))
    conn.commit()
    row = conn.execute("SELECT * FROM erp_acct_payroll_filings WHERE id = ?",
                       (filing_id,)).fetchone()
    conn.close()
    return jsonify(filing=dict(row)), 201

# ---- Payroll tax form generation: Form 941 + W-2 (Wave 4 item 14,
# gap-analysis section 3.13, SOP 9.38) ----
# The payroll filings REGISTER (erp_acct_payroll_filings) already records
# filed quarters; this layer GENERATES the forms from paid pay runs and
# stores the generated draft in erp_acct_payroll_tax_forms. Generation
# never marks anything filed: filing stays the separate admin action on
# the register (POST /payroll/tax-filings), and a generated form is a
# draft until that filing is recorded. Every figure is computed from
# real paid pay runs (or is honestly zero / missing): no EIN, wages,
# withholding, SSN, or deposit is ever invented. Deposits are always
# $0.00 -- the ERP holds no deposit records. Direct-deposit (ACH)
# disbursement is NOT built: the ERP has no bank/ACH integration, so
# pay runs record pay as paid and the money movement happens outside
# the ERP. Social Security wages per line are recomputed from the wage
# base and the employee's year-to-date gross (the same inputs the pay
# run used), because pay-run lines store the SS tax, not the wages.


def _acct_payroll_tax_form_quarter(pay_date):
    year = int(pay_date[:4])
    month = int(pay_date[5:7])
    return "%d-Q%d" % (year, (month - 1) // 3 + 1)


def _acct_payroll_tax_form_filing(conn, quarter):
    return conn.execute(
        "SELECT * FROM erp_acct_payroll_filings WHERE quarter = ?",
        (quarter,)).fetchone()


def _acct_payroll_tax_form_compute(conn, form_type, period,
                                   employee_id=None):
    """Compute a 941 or W-2 from PAID pay runs. Returns (figures, None)
    or (None, error). A quarter/year with no paid pay runs computes
    all-zero figures (run_count 0) instead of refusing, so the admin
    can see the empty form -- it is still only a draft, never a filing.
    """
    if form_type == "941":
        try:
            year, qnum = period.split("-Q")
            year = int(year)
            qnum = int(qnum)
            if qnum < 1 or qnum > 4:
                raise ValueError
        except (ValueError, AttributeError):
            return None, "quarter must look like 2026-Q4"
    elif form_type == "W-2":
        try:
            year = int(period)
        except (ValueError, TypeError):
            return None, "tax_year must be a year like 2026"
    else:
        return None, "form_type must be 941 or W-2"
    runs = conn.execute(
        "SELECT * FROM erp_acct_payruns WHERE status = 'paid'"
        " ORDER BY pay_date, id").fetchall()
    scoped = []
    for r in runs:
        if form_type == "941":
            if _acct_payroll_tax_form_quarter(r["pay_date"]) != period:
                continue
        elif int(r["pay_date"][:4]) != year:
            continue
        scoped.append(r)
    run_ids = [int(r["id"]) for r in scoped]
    lines = []
    if run_ids:
        q = ("SELECT * FROM erp_acct_payrun_lines WHERE payrun_id IN (%s)"
             " ORDER BY payrun_id, id" % ",".join("?" * len(run_ids)))
        lines = conn.execute(q, run_ids).fetchall()
    employee_name = ""
    ssn_on_file = False
    if form_type == "W-2":
        emp = conn.execute(
            "SELECT * FROM erp_acct_employees WHERE id = ?",
            (int(employee_id),)).fetchone()
        if not emp:
            return None, "employee not found"
        employee_name = (emp["first_name"] or "") + " " + (emp["last_name"] or "")
        ssn_on_file = bool(dict(emp).get("ssn") or "")
        lines = [l for l in lines if int(l["employee_id"]) == int(employee_id)]
        emp_run_ids = sorted({int(l["payrun_id"]) for l in lines})
        run_ids = emp_run_ids
        scoped = [r for r in scoped if int(r["id"]) in set(emp_run_ids)]
    # A quarter/year with no paid lines needs no FICA table: every
    # figure is honestly zero.
    fica = _acct_payroll_fica(conn, year)
    if fica is None and lines:
        return None, "no FICA table for tax year %d" % year
    # SS taxable wages need the employee's FULL year-to-date gross, not
    # just the scoped quarter's: the wage base is per calendar year, so
    # walk every paid line in the year in pay order and count only the
    # scoped lines' taxable portion. (A Q4 walk that started at zero
    # would overstate SS wages once the base is passed.)
    scoped_ids = {int(l["id"]) for l in lines}
    year_lines = []
    if lines:
        year_lines = conn.execute(
            "SELECT l.* FROM erp_acct_payrun_lines l"
            " JOIN erp_acct_payruns r ON r.id = l.payrun_id"
            " WHERE r.status = 'paid' AND substr(r.pay_date, 1, 4) = ?"
            " ORDER BY r.pay_date, r.id, l.id",
            (str(year),)).fetchall()
        if form_type == "W-2":
            year_lines = [l for l in year_lines
                          if int(l["employee_id"]) == int(employee_id)]
    ytd = {}
    ss_wages = 0
    for l in year_lines:
        eid = int(l["employee_id"])
        gross = int(l["gross_cents"] or 0)
        before = ytd.get(eid, 0)
        if int(l["id"]) in scoped_ids:
            ss_wages += max(0, min(gross, fica["ss_wage_base_cents"] - before))
        ytd[eid] = before + gross
    gross = sum(int(l["gross_cents"] or 0) for l in lines)
    federal = sum(int(l["federal_cents"] or 0) for l in lines)
    ss_emp = sum(int(l["ss_cents"] or 0) for l in lines)
    med_emp = sum(int(l["medicare_cents"] or 0) for l in lines)
    # Employer Medicare is the base 1.45% on gross (the 0.9% additional
    # Medicare is employee-only); employer SS equals employee SS.
    med_base = sum(
        _acct_round_div(int(l["gross_cents"] or 0)
                        * fica["medicare_rate_bps"], 10000)
        for l in lines)
    employer_ss = ss_emp
    employer_medicare = med_base
    addl_medicare = med_emp - med_base
    if form_type == "941":
        # The 941 reports the combined employee + employer tax.
        ss_tax = ss_emp + employer_ss
        medicare_tax = med_emp + employer_medicare
        balance_due = federal + ss_tax + medicare_tax
    else:
        # A W-2 reports the employee's share only (boxes 4 and 5). It
        # is informational, not a payment, so no balance is due on it.
        ss_tax = ss_emp
        medicare_tax = med_emp
        balance_due = 0
    total_tax = federal + ss_tax + medicare_tax
    ein = _erp_company_profile(conn)["ein"]
    complete = bool(ein) and (form_type == "941" or ssn_on_file)
    payload = {
        "runs": [[int(r["id"]), int(r["gross_cents"] or 0),
                  int(r["federal_withheld_cents"] or 0),
                  int(r["ss_cents"] or 0),
                  int(r["medicare_cents"] or 0),
                  int(r["employer_ss_cents"] or 0),
                  int(r["employer_medicare_cents"] or 0),
                  int(r["net_cents"] or 0)] for r in scoped],
        "lines": [[int(l["id"]), int(l["payrun_id"]),
                   int(l["employee_id"]), int(l["gross_cents"] or 0),
                   int(l["federal_cents"] or 0),
                   int(l["ss_cents"] or 0),
                   int(l["medicare_cents"] or 0)] for l in lines],
        "ein": ein,
        "ssn_on_file": ssn_on_file,
    }
    source_hash = hashlib.sha256(
        json.dumps(payload, sort_keys=True,
                   separators=(",", ":")).encode("utf-8")).hexdigest()
    return {
        "gross_cents": gross,
        "federal_cents": federal,
        "ss_wages_cents": ss_wages,
        "ss_tax_cents": ss_tax,
        "medicare_wages_cents": gross,
        "medicare_tax_cents": medicare_tax,
        "employer_ss_cents": employer_ss,
        "employer_medicare_cents": employer_medicare,
        "addl_medicare_cents": addl_medicare,
        "total_tax_cents": total_tax,
        "deposits_cents": 0,
        "balance_due_cents": balance_due,
        "run_count": len(scoped),
        "employee_count": (len({int(l["employee_id"]) for l in lines})
                           if form_type == "941" else 1),
        "run_ids": run_ids,
        "source_hash": source_hash,
        "ein": ein,
        "ssn_on_file": ssn_on_file,
        "complete": complete,
        "employee_name": employee_name,
    }, None


def _acct_payroll_tax_form_dict(conn, row):
    d = dict(row)
    try:
        d["run_ids"] = json.loads(row["run_ids"] or "[]")
    except (ValueError, TypeError):
        d["run_ids"] = []
    for k in ("ssn_on_file", "complete"):
        d[k] = bool(d[k])
    d["ein_present"] = bool(d["ein"])
    # Stale is recomputed on every read from the live paid runs: a pay
    # run added, changed, or un-fed after generation -- or an EIN/SSN
    # change -- makes the stored figures stale instead of silently
    # outdated. The stored figures are never rewritten by a read.
    d["stale"] = True
    try:
        figs, _err = _acct_payroll_tax_form_compute(
            conn, d["form_type"], d["period"],
            d["employee_id"] if d["form_type"] == "W-2" else None)
        d["stale"] = bool(figs is None
                          or figs["source_hash"] != d["source_hash"])
    except Exception:
        d["stale"] = True
    # Filing linkage is read from the register (the source of truth):
    # a filing recorded after generation still shows as filed.
    d["filed"] = False
    d["filed_at"] = None
    d["filed_by"] = ""
    if d["form_type"] == "941":
        f = _acct_payroll_tax_form_filing(conn, d["period"])
        if f:
            d["filed"] = True
            d["filed_at"] = f["filed_at"]
            d["filed_by"] = f["filed_by"]
            d["filing_id"] = f["id"]
    return d


def _acct_payroll_tax_form_store(conn, form_type, period, employee_id,
                                figs, actor):
    """Insert a generated form, or update the existing draft for the
    same form/period/employee in place (stable id). Returns the row id.
    """
    if employee_id is None:
        existing = conn.execute(
            "SELECT id FROM erp_acct_payroll_tax_forms"
            " WHERE form_type = ? AND period = ? AND employee_id IS NULL",
            (form_type, period)).fetchone()
    else:
        existing = conn.execute(
            "SELECT id FROM erp_acct_payroll_tax_forms"
            " WHERE form_type = ? AND period = ? AND employee_id = ?",
            (form_type, period, employee_id)).fetchone()
    now = datetime.now(timezone.utc).isoformat()
    filing_id = None
    if form_type == "941":
        f = _acct_payroll_tax_form_filing(conn, period)
        filing_id = f["id"] if f else None
    values = (
        figs["gross_cents"], figs["federal_cents"],
        figs["ss_wages_cents"], figs["ss_tax_cents"],
        figs["medicare_wages_cents"], figs["medicare_tax_cents"],
        figs["employer_ss_cents"], figs["employer_medicare_cents"],
        figs["addl_medicare_cents"], figs["total_tax_cents"],
        figs["deposits_cents"], figs["balance_due_cents"],
        figs["run_count"], figs["employee_count"],
        json.dumps(figs["run_ids"]), figs["source_hash"], figs["ein"],
        1 if figs["ssn_on_file"] else 0, 1 if figs["complete"] else 0,
        filing_id, now, actor or "")
    if existing:
        conn.execute(
            "UPDATE erp_acct_payroll_tax_forms SET gross_cents = ?,"
            " federal_cents = ?, ss_wages_cents = ?, ss_tax_cents = ?,"
            " medicare_wages_cents = ?, medicare_tax_cents = ?,"
            " employer_ss_cents = ?, employer_medicare_cents = ?,"
            " addl_medicare_cents = ?, total_tax_cents = ?,"
            " deposits_cents = ?, balance_due_cents = ?, run_count = ?,"
            " employee_count = ?, run_ids = ?, source_hash = ?, ein = ?,"
            " ssn_on_file = ?, complete = ?, filing_id = ?,"
            " generated_at = ?, generated_by = ? WHERE id = ?",
            values + (existing["id"],))
        return existing["id"]
    cur = conn.execute(
        "INSERT INTO erp_acct_payroll_tax_forms (form_type, period,"
        " employee_id, employee_name, gross_cents, federal_cents,"
        " ss_wages_cents, ss_tax_cents, medicare_wages_cents,"
        " medicare_tax_cents, employer_ss_cents, employer_medicare_cents,"
        " addl_medicare_cents, total_tax_cents, deposits_cents,"
        " balance_due_cents, run_count, employee_count, run_ids,"
        " source_hash, ein, ssn_on_file, complete, status, filing_id,"
        " generated_at, generated_by, created_at)"
        " VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?,"
        " ?, ?, ?, ?, ?, 'generated', ?, ?, ?, ?)",
        (form_type, period, employee_id, figs["employee_name"])
        + values + (now,))
    return cur.lastrowid


@app.get("/api/erp/accounting/payroll/tax-forms")
def erp_acct_payroll_tax_forms():
    actor, err = _erp_check_perm("payroll.read")
    if err:
        return err
    conn = db()
    rows = conn.execute(
        "SELECT * FROM erp_acct_payroll_tax_forms"
        " ORDER BY form_type, period DESC, employee_name").fetchall()
    out = [_acct_payroll_tax_form_dict(conn, r) for r in rows]
    ein = _erp_company_profile(conn)["ein"]
    conn.close()
    return jsonify(forms=out, ein_present=bool(ein))


@app.get("/api/erp/accounting/payroll/tax-forms/<int:form_id>")
def erp_acct_payroll_tax_form(form_id):
    actor, err = _erp_check_perm("payroll.read")
    if err:
        return err
    conn = db()
    row = conn.execute(
        "SELECT * FROM erp_acct_payroll_tax_forms WHERE id = ?",
        (form_id,)).fetchone()
    if not row:
        conn.close()
        return jsonify(error="tax form not found"), 404
    out = _acct_payroll_tax_form_dict(conn, row)
    conn.close()
    return jsonify(form=out)


@app.post("/api/erp/accounting/payroll/tax-forms/941")
def erp_acct_generate_payroll_941():
    actor, err = _erp_check_perm("payroll.write")
    if err:
        return err
    data = request.get_json(force=True) or {}
    quarter = (data.get("quarter") or "").strip()
    conn = db()
    figs, error = _acct_payroll_tax_form_compute(conn, "941", quarter)
    if error:
        conn.close()
        return jsonify(error=error), 400
    form_id = _acct_payroll_tax_form_store(conn, "941", quarter, None,
                                           figs, actor)
    _acct_audit(conn, actor, "payroll.taxform.generate",
                "payroll_tax_form", form_id,
                "941 %s gross %d federal %d total tax %d (%d runs)" % (
                    quarter, figs["gross_cents"], figs["federal_cents"],
                    figs["total_tax_cents"], figs["run_count"]))
    conn.commit()
    row = conn.execute(
        "SELECT * FROM erp_acct_payroll_tax_forms WHERE id = ?",
        (form_id,)).fetchone()
    out = _acct_payroll_tax_form_dict(conn, row)
    conn.close()
    return jsonify(form=out), 201


@app.post("/api/erp/accounting/payroll/tax-forms/w2")
def erp_acct_generate_payroll_w2s():
    actor, err = _erp_check_perm("payroll.write")
    if err:
        return err
    data = request.get_json(force=True) or {}
    try:
        year = int(data.get("tax_year"))
    except (TypeError, ValueError):
        return jsonify(error="tax_year must be a year like 2026"), 400
    conn = db()
    rows = conn.execute(
        "SELECT DISTINCT l.employee_id FROM erp_acct_payrun_lines l"
        " JOIN erp_acct_payruns r ON r.id = l.payrun_id"
        " WHERE r.status = 'paid' AND substr(r.pay_date, 1, 4) = ?",
        (str(year),)).fetchall()
    forms = []
    for (employee_id,) in rows:
        figs, error = _acct_payroll_tax_form_compute(
            conn, "W-2", str(year), int(employee_id))
        if error:
            conn.close()
            return jsonify(error=error), 400
        form_id = _acct_payroll_tax_form_store(
            conn, "W-2", str(year), int(employee_id), figs, actor)
        _acct_audit(conn, actor, "payroll.taxform.generate",
                    "payroll_tax_form", form_id,
                    "W-2 %d employee #%d gross %d federal %d" % (
                        year, int(employee_id), figs["gross_cents"],
                        figs["federal_cents"]))
        row = conn.execute(
            "SELECT * FROM erp_acct_payroll_tax_forms WHERE id = ?",
            (form_id,)).fetchone()
        forms.append(_acct_payroll_tax_form_dict(conn, row))
    conn.commit()
    conn.close()
    return jsonify(forms=forms), 201


@app.post("/api/erp/accounting/payroll/tax-forms/<int:form_id>/regenerate")
def erp_acct_regenerate_payroll_tax_form(form_id):
    actor, err = _erp_check_perm("payroll.write")
    if err:
        return err
    conn = db()
    row = conn.execute(
        "SELECT * FROM erp_acct_payroll_tax_forms WHERE id = ?",
        (form_id,)).fetchone()
    if not row:
        conn.close()
        return jsonify(error="tax form not found"), 404
    figs, error = _acct_payroll_tax_form_compute(
        conn, row["form_type"], row["period"],
        row["employee_id"] if row["form_type"] == "W-2" else None)
    if error:
        conn.close()
        return jsonify(error=error), 400
    _acct_payroll_tax_form_store(
        conn, row["form_type"], row["period"], row["employee_id"], figs,
        actor)
    _acct_audit(conn, actor, "payroll.taxform.regenerate",
                "payroll_tax_form", form_id,
                "%s %s regenerated gross %d total tax %d" % (
                    row["form_type"], row["period"],
                    figs["gross_cents"], figs["total_tax_cents"]))
    conn.commit()
    row = conn.execute(
        "SELECT * FROM erp_acct_payroll_tax_forms WHERE id = ?",
        (form_id,)).fetchone()
    out = _acct_payroll_tax_form_dict(conn, row)
    conn.close()
    return jsonify(form=out)


@app.delete("/api/erp/accounting/payroll/tax-forms/<int:form_id>")
def erp_acct_delete_payroll_tax_form(form_id):
    actor, err = _erp_check_perm("payroll.write")
    if err:
        return err
    conn = db()
    row = conn.execute(
        "SELECT * FROM erp_acct_payroll_tax_forms WHERE id = ?",
        (form_id,)).fetchone()
    if not row:
        conn.close()
        return jsonify(error="tax form not found"), 404
    conn.execute("DELETE FROM erp_acct_payroll_tax_forms WHERE id = ?",
                 (form_id,))
    _acct_audit(conn, actor, "payroll.taxform.delete",
                "payroll_tax_form", form_id,
                "%s %s deleted (draft only, never filed)" % (
                    row["form_type"], row["period"]))
    conn.commit()
    conn.close()
    return jsonify(deleted=True)


# ---- Payroll garnishments (Wave 4 item 27, SOP 9.40) ----
# A REGISTER only -- see the table comment above. One record per
# garnishment order, tied to the payroll employee it withholds
# from. Reads/writes use payroll.read / payroll.write -- the
# tightest existing payroll permission. Legacy staff hold neither
# (they are not in _ERP_LEGACY_STAFF_PERMS), so in practice this
# is admin-only: a staff member never sees another employee's
# garnishments, and there is no staff self-view path -- the ERP
# has no "my garnishments" view, and the SOP says so. The amount
# is admin-typed from the real order -- nothing is computed, no
# cap and no priority are applied, and recording a garnishment
# never changes a pay run: pay runs have no deduction hook (net
# is gross minus federal / SS / Medicare), so no garnishment is
# ever deducted from a pay run by this build. The detail payload
# still links the employee's pay runs (id, period, pay date,
# status, gross, net) so the admin can see which runs the order
# overlapped -- with deductions_taken_cents 0 on every one.
# There is NO edit endpoint: the order's fields are immutable
# after creation. A wrong live record is deleted and re-recorded;
# only status changes are allowed, and a satisfied / released
# record is history and can never be deleted.
ERP_GARNISHMENT_TYPES = ("child_support", "tax_levy", "creditor",
                         "other")
ERP_GARNISHMENT_TYPE_LABELS = {
    "child_support": "Child support",
    "tax_levy": "Tax levy",
    "creditor": "Creditor garnishment",
    "other": "Other",
}
ERP_GARNISHMENT_AMOUNT_KINDS = ("fixed_total", "per_period",
                                "percent")
ERP_GARNISHMENT_STATUSES = ("active", "suspended", "satisfied",
                            "released")


def _acct_get_garnishment(conn, garnishment_id):
    try:
        garnishment_id = int(garnishment_id)
    except (TypeError, ValueError):
        return None
    return conn.execute(
        "SELECT * FROM erp_acct_payroll_garnishments WHERE id = ?",
        (garnishment_id,)).fetchone()


def _acct_garnishment_employee(conn, employee_id):
    return conn.execute(
        "SELECT id, first_name, last_name, active"
        " FROM erp_acct_employees WHERE id = ?",
        (employee_id,)).fetchone()


def _acct_garnishment_pay_runs(conn, employee_id):
    """The employee's pay runs, newest first: the link from the
    order to payroll. Each run carries its stored gross/net --
    the garnishment changed none of them (no deduction hook)."""
    rows = conn.execute(
        "SELECT r.id, r.period_start, r.period_end, r.pay_date,"
        " r.status, l.gross_cents, l.net_cents"
        " FROM erp_acct_payrun_lines l"
        " JOIN erp_acct_payruns r ON r.id = l.payrun_id"
        " WHERE l.employee_id = ?"
        " ORDER BY r.pay_date DESC, r.id DESC",
        (employee_id,)).fetchall()
    return [{"payrun_id": r["id"], "period_start": r["period_start"],
             "period_end": r["period_end"], "pay_date": r["pay_date"],
             "status": r["status"], "gross_cents": r["gross_cents"],
             "net_cents": r["net_cents"]} for r in rows]


def _acct_garnishment_payload(conn, row, detail=False):
    emp = _acct_garnishment_employee(conn, row["employee_id"]) \
        if row["employee_id"] else None
    if emp:
        name = (emp["first_name"] + " " + emp["last_name"]).strip()
    else:
        name = "Former employee #%d" % row["employee_id"]
    pay_runs = _acct_garnishment_pay_runs(conn, row["employee_id"]) \
        if detail else None
    if pay_runs is not None:
        run_count = len(pay_runs)
    else:
        run_count = conn.execute(
            "SELECT COUNT(*) FROM erp_acct_payrun_lines"
            " WHERE employee_id = ?",
            (row["employee_id"],)).fetchone()[0]
    d = {
        "id": row["id"],
        "employee_id": row["employee_id"],
        "employee_name": name,
        "employee_active": bool(emp["active"]) if emp else False,
        "authority": row["authority"] or "",
        "order_reference": row["order_reference"] or "",
        "type": row["type"],
        "type_label": ERP_GARNISHMENT_TYPE_LABELS.get(
            row["type"], row["type"]),
        "amount_kind": row["amount_kind"],
        "amount_cents": row["amount_cents"],
        "percent_bps": row["percent_bps"],
        "start_date": row["start_date"],
        "end_date": row["end_date"] or "",
        "status": row["status"],
        "suspend_reason": row["suspend_reason"] or "",
        "close_date": row["close_date"] or "",
        "close_reference": row["close_reference"] or "",
        "notes": row["notes"] or "",
        "deductions_taken_cents": row["deductions_taken_cents"],
        "pay_run_count": run_count,
        "created_by": row["created_by"] or "",
        "created_at": row["created_at"],
        "updated_by": row["updated_by"] or "",
        "updated_at": row["updated_at"] or "",
    }
    if detail:
        d["pay_runs"] = pay_runs
    return d


def _acct_garnishment_fields(conn, data):
    """Validate a new garnishment's fields. Returns (values, error).
    Everything comes from the admin, typed from the real order:
    the employee must be a real, active payroll employee; the
    authority and order reference must be typed in; the amount is
    either a fixed/per-period amount in cents or a percent in
    basis points -- never both, never a default, never computed."""
    try:
        employee_id = int(data.get("employee_id"))
    except (TypeError, ValueError):
        return None, "employee_id is required and must be a number"
    emp = _acct_garnishment_employee(conn, employee_id)
    if not emp:
        return None, "unknown payroll employee"
    if not emp["active"]:
        return None, "payroll employee #%d is inactive" % employee_id
    authority = data.get("authority")
    authority = authority.strip() if isinstance(authority, str) else ""
    if not authority or len(authority) > 200:
        return None, ("authority is required and must be 200"
                      " characters or fewer")
    reference = data.get("order_reference")
    reference = reference.strip() if isinstance(reference, str) else ""
    if not reference or len(reference) > 200:
        return None, ("order_reference is required and must be 200"
                      " characters or fewer")
    gtype = data.get("type")
    gtype = gtype.strip() if isinstance(gtype, str) else ""
    if gtype not in ERP_GARNISHMENT_TYPES:
        return None, ("type must be one of: "
                      + ", ".join(ERP_GARNISHMENT_TYPES))
    kind = data.get("amount_kind")
    kind = kind.strip() if isinstance(kind, str) else ""
    if kind not in ERP_GARNISHMENT_AMOUNT_KINDS:
        return None, ("amount_kind must be one of: "
                      + ", ".join(ERP_GARNISHMENT_AMOUNT_KINDS))
    amount_cents = None
    percent_bps = None
    if kind in ("fixed_total", "per_period"):
        amount_cents = _acct_int_cents(data.get("amount_cents"))
        if amount_cents is None or amount_cents <= 0:
            return None, ("amount_cents must be a whole number of"
                          " cents above 0 for a %s amount" % kind)
        if data.get("percent_bps") not in (None, ""):
            return None, ("percent_bps must be empty for a %s"
                          " amount" % kind)
    else:
        percent_bps = _acct_int_cents(data.get("percent_bps"))
        if percent_bps is None or percent_bps <= 0 \
                or percent_bps > 10000:
            return None, ("percent_bps must be a whole number of"
                          " basis points between 1 and 10000")
        if data.get("amount_cents") not in (None, ""):
            return None, ("amount_cents must be empty for a percent"
                          " amount")
    start_date = data.get("start_date")
    start_date = start_date.strip() if isinstance(start_date, str) \
        else ""
    if not start_date or not _acct_valid_date(start_date):
        return None, "start_date is required and must be YYYY-MM-DD"
    end_date = data.get("end_date")
    end_date = end_date.strip() if isinstance(end_date, str) else ""
    if end_date:
        if not _acct_valid_date(end_date):
            return None, "end_date must be YYYY-MM-DD or blank"
        if end_date < start_date:
            return None, "end_date must not be before start_date"
    notes = data.get("notes")
    notes = notes.strip() if isinstance(notes, str) else ""
    if len(notes) > 1000:
        return None, "notes must be 1000 characters or fewer"
    return {"employee_id": employee_id, "authority": authority,
            "order_reference": reference, "type": gtype,
            "amount_kind": kind, "amount_cents": amount_cents,
            "percent_bps": percent_bps, "start_date": start_date,
            "end_date": end_date, "notes": notes}, None


def _acct_garnishment_close_fields(data):
    """Validate a satisfy/release close: a date and the releasing
    document reference, both admin-entered from the real document."""
    date = data.get("date")
    date = date.strip() if isinstance(date, str) else ""
    if not date:
        date = datetime.now(timezone.utc).date().isoformat()
    if not _acct_valid_date(date):
        return None, "date must be YYYY-MM-DD"
    reference = data.get("reference")
    reference = reference.strip() if isinstance(reference, str) else ""
    if not reference or len(reference) > 255:
        return None, ("reference is required and must be 255"
                      " characters or fewer")
    return {"date": date, "reference": reference}, None


@app.get("/api/erp/accounting/payroll/garnishments")
def erp_acct_list_garnishments():
    """List the garnishment register, newest first, optionally
    filtered by status, employee, or a search string over the
    employee name, the ordering authority, and the order
    reference. Starts empty: with no employees and no orders
    there is nothing here, and the SOP says so."""
    _, err = _erp_check_perm("payroll.read")
    if err:
        return err
    status = (request.args.get("status") or "").strip().lower()
    q = (request.args.get("q") or "").strip().lower()
    employee_id = request.args.get("employee_id")
    if status and status not in ERP_GARNISHMENT_STATUSES:
        return jsonify(error="unknown status"), 400
    try:
        employee_id = int(employee_id) if employee_id not in (None, "") \
            else None
    except (TypeError, ValueError):
        return jsonify(error="employee_id must be a number"), 400
    conn = db()
    rows = conn.execute(
        "SELECT * FROM erp_acct_payroll_garnishments"
        " ORDER BY id DESC").fetchall()
    out = []
    for r in rows:
        if status and r["status"] != status:
            continue
        if employee_id is not None and r["employee_id"] != employee_id:
            continue
        d = _acct_garnishment_payload(conn, r)
        if q and q not in d["employee_name"].lower() \
                and q not in d["authority"].lower() \
                and q not in d["order_reference"].lower():
            continue
        out.append(d)
    conn.close()
    return jsonify(garnishments=out)


@app.get("/api/erp/accounting/payroll/garnishments/<int:garnishment_id>")
def erp_acct_get_garnishment(garnishment_id):
    _, err = _erp_check_perm("payroll.read")
    if err:
        return err
    conn = db()
    row = _acct_get_garnishment(conn, garnishment_id)
    if not row:
        conn.close()
        return jsonify(error="garnishment not found"), 404
    out = _acct_garnishment_payload(conn, row, detail=True)
    conn.close()
    return jsonify(garnishment=out)


@app.post("/api/erp/accounting/payroll/garnishments")
def erp_acct_create_garnishment():
    """Record a garnishment order (201). Status starts active.
    Recording it changes no pay run and deducts nothing -- pay
    runs have no deduction hook."""
    actor, err = _erp_check_perm("payroll.write")
    if err:
        return err
    data = request.get_json(force=True, silent=True) or {}
    conn = db()
    fields, error = _acct_garnishment_fields(conn, data)
    if error:
        conn.close()
        return jsonify(error=error), 400
    dup = conn.execute(
        "SELECT id FROM erp_acct_payroll_garnishments"
        " WHERE employee_id = ? AND order_reference = ?"
        " AND status IN ('active', 'suspended')",
        (fields["employee_id"], fields["order_reference"])).fetchone()
    if dup:
        conn.close()
        return jsonify(error="an active garnishment for this employee"
                       " already uses order reference %r"
                       % fields["order_reference"]), 409
    now = datetime.now(timezone.utc).isoformat()
    cur = conn.execute(
        "INSERT INTO erp_acct_payroll_garnishments (employee_id,"
        " authority, order_reference, type, amount_kind,"
        " amount_cents, percent_bps, start_date, end_date, status,"
        " notes, deductions_taken_cents, created_by, created_at,"
        " updated_by, updated_at)"
        " VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, 'active', ?, 0, ?, ?, ?, ?)",
        (fields["employee_id"], fields["authority"],
         fields["order_reference"], fields["type"],
         fields["amount_kind"], fields["amount_cents"],
         fields["percent_bps"], fields["start_date"],
         fields["end_date"], fields["notes"], actor or "", now,
         actor or "", now))
    garnishment_id = cur.lastrowid
    _acct_audit(conn, actor, "payroll.garnishment.create",
                "payroll_garnishment", garnishment_id,
                "garnishment #%d recorded: employee #%d, %s, %s,"
                " %s from %s" % (
                    garnishment_id, fields["employee_id"],
                    fields["authority"], fields["order_reference"],
                    fields["type"], fields["start_date"]))
    conn.commit()
    out = _acct_garnishment_payload(
        conn, _acct_get_garnishment(conn, garnishment_id), detail=True)
    conn.close()
    return jsonify(garnishment=out), 201


def _acct_garnishment_set_status(conn, actor, row, status, extra,
                                 action, detail):
    now = datetime.now(timezone.utc).isoformat()
    sets = "status = ?, updated_by = ?, updated_at = ?"
    vals = [status, actor or "", now]
    for key, value in extra.items():
        sets += ", %s = ?" % key
        vals.append(value)
    conn.execute(
        "UPDATE erp_acct_payroll_garnishments SET %s WHERE id = ?"
        % sets, tuple(vals) + (row["id"],))
    _acct_audit(conn, actor, action, "payroll_garnishment",
                row["id"], detail)
    conn.commit()
    return _acct_garnishment_payload(
        conn, _acct_get_garnishment(conn, row["id"]), detail=True)


@app.post("/api/erp/accounting/payroll/garnishments/<int:garnishment_id>/suspend")
def erp_acct_suspend_garnishment(garnishment_id):
    """Suspend a live garnishment (admin-only, with a reason).
    Suspension stops nothing in a pay run -- there is no
    deduction to stop -- it records that the order is paused
    and why. Only an active garnishment suspends."""
    actor, err = _erp_check_perm("payroll.write")
    if err:
        return err
    data = request.get_json(force=True, silent=True) or {}
    conn = db()
    row = _acct_get_garnishment(conn, garnishment_id)
    if not row:
        conn.close()
        return jsonify(error="garnishment not found"), 404
    reason = data.get("reason")
    reason = reason.strip() if isinstance(reason, str) else ""
    if not reason or len(reason) > 1000:
        conn.close()
        return jsonify(error="reason is required and must be 1000"
                       " characters or fewer"), 400
    if row["status"] != "active":
        conn.close()
        return jsonify(error="only an active garnishment can be"
                       " suspended (status: %s)" % row["status"]), 400
    out = _acct_garnishment_set_status(
        conn, actor, row, "suspended", {"suspend_reason": reason},
        "payroll.garnishment.suspend",
        "garnishment #%d suspended: %s" % (garnishment_id, reason))
    conn.close()
    return jsonify(garnishment=out)


@app.post("/api/erp/accounting/payroll/garnishments/<int:garnishment_id>/resume")
def erp_acct_resume_garnishment(garnishment_id):
    """Resume a suspended garnishment (admin-only). Only a
    suspended garnishment resumes; the suspend reason is cleared."""
    actor, err = _erp_check_perm("payroll.write")
    if err:
        return err
    conn = db()
    row = _acct_get_garnishment(conn, garnishment_id)
    if not row:
        conn.close()
        return jsonify(error="garnishment not found"), 404
    if row["status"] != "suspended":
        conn.close()
        return jsonify(error="only a suspended garnishment can be"
                       " resumed (status: %s)" % row["status"]), 400
    out = _acct_garnishment_set_status(
        conn, actor, row, "active", {"suspend_reason": ""},
        "payroll.garnishment.resume",
        "garnishment #%d resumed" % garnishment_id)
    conn.close()
    return jsonify(garnishment=out)


@app.post("/api/erp/accounting/payroll/garnishments/<int:garnishment_id>/satisfy")
def erp_acct_satisfy_garnishment(garnishment_id):
    """Mark a garnishment satisfied (admin-only): the ordered
    amount has been fully withheld. Date + releasing document
    reference are required, typed from the real document.
    Satisfied is terminal history -- it can never be edited or
    deleted afterwards."""
    actor, err = _erp_check_perm("payroll.write")
    if err:
        return err
    data = request.get_json(force=True, silent=True) or {}
    conn = db()
    row = _acct_get_garnishment(conn, garnishment_id)
    if not row:
        conn.close()
        return jsonify(error="garnishment not found"), 404
    fields, error = _acct_garnishment_close_fields(data)
    if error:
        conn.close()
        return jsonify(error=error), 400
    if row["status"] not in ("active", "suspended"):
        conn.close()
        return jsonify(error="only an active or suspended"
                       " garnishment can be satisfied (status: %s)"
                       % row["status"]), 400
    out = _acct_garnishment_set_status(
        conn, actor, row, "satisfied",
        {"close_date": fields["date"],
         "close_reference": fields["reference"],
         "suspend_reason": ""},
        "payroll.garnishment.satisfy",
        "garnishment #%d satisfied %s, ref %s"
        % (garnishment_id, fields["date"], fields["reference"]))
    conn.close()
    return jsonify(garnishment=out)


@app.post("/api/erp/accounting/payroll/garnishments/<int:garnishment_id>/release")
def erp_acct_release_garnishment(garnishment_id):
    """Mark a garnishment released (admin-only): the ordering
    authority lifted the order. Date + releasing document
    reference are required, typed from the real document.
    Released is terminal history -- it can never be edited or
    deleted afterwards."""
    actor, err = _erp_check_perm("payroll.write")
    if err:
        return err
    data = request.get_json(force=True, silent=True) or {}
    conn = db()
    row = _acct_get_garnishment(conn, garnishment_id)
    if not row:
        conn.close()
        return jsonify(error="garnishment not found"), 404
    fields, error = _acct_garnishment_close_fields(data)
    if error:
        conn.close()
        return jsonify(error=error), 400
    if row["status"] not in ("active", "suspended"):
        conn.close()
        return jsonify(error="only an active or suspended"
                       " garnishment can be released (status: %s)"
                       % row["status"]), 400
    out = _acct_garnishment_set_status(
        conn, actor, row, "released",
        {"close_date": fields["date"],
         "close_reference": fields["reference"],
         "suspend_reason": ""},
        "payroll.garnishment.release",
        "garnishment #%d released %s, ref %s"
        % (garnishment_id, fields["date"], fields["reference"]))
    conn.close()
    return jsonify(garnishment=out)


@app.delete("/api/erp/accounting/payroll/garnishments/<int:garnishment_id>")
def erp_acct_delete_garnishment(garnishment_id):
    """Delete a garnishment, permanently (admin only). Only an
    active or suspended garnishment with no deductions taken
    deletes -- a wrong live record is deleted and re-recorded.
    Satisfied / released garnishments are history and refuse
    delete (409), and a record with deductions taken through pay
    runs refuses too: posted pay-run deductions are never
    deleted silently. Two-tap confirm on the frontend; no
    window.confirm."""
    actor, err = _erp_check_perm("payroll.write")
    if err:
        return err
    conn = db()
    row = _acct_get_garnishment(conn, garnishment_id)
    if not row:
        conn.close()
        return jsonify(error="garnishment not found"), 404
    if row["status"] not in ("active", "suspended"):
        conn.close()
        return jsonify(error="only an active or suspended"
                       " garnishment can be deleted (status: %s) --"
                       " satisfied and released garnishments are"
                       " history" % row["status"]), 409
    if row["deductions_taken_cents"] > 0:
        conn.close()
        return jsonify(error="garnishment #%d has deductions taken"
                       " through pay runs and cannot be deleted"
                       % garnishment_id), 409
    conn.execute("DELETE FROM erp_acct_payroll_garnishments"
                 " WHERE id = ?", (garnishment_id,))
    _acct_audit(conn, actor, "payroll.garnishment.delete",
                "payroll_garnishment", garnishment_id,
                "deleted %s garnishment #%d (%s, %s)"
                % (row["status"], garnishment_id,
                   row["authority"], row["order_reference"]))
    conn.commit()
    conn.close()
    return jsonify(ok=True)


# ---- Accounting migration import (Phase 1) ----
# One-shot admin import of a QuickBooks migration snapshot (produced by
# hidden_files/acct_migrate.py). Read-only on QuickBooks; everything here
# writes the ERP only. Idempotent via erp_acct_migration_links: a record
# whose QuickBooks id is already mapped is skipped, never duplicated.
# Paid/void documents are imported as records only -- their GL effect
# lives in the opening balances. The opening-balance entry is posted
# last: balance-sheet targets minus what the imported documents already
# posted. If it cannot balance, the whole import fails (no commit).
ERP_ACCT_MIGRATION_TYPES = ("account", "customer", "vendor", "item",
                            "bank_account", "bank_transaction", "invoice",
                            "bill", "payment", "journal_entry")
ERP_ACCT_MIGRATION_CODE_RANGES = {
    "asset": (1000, 1999), "liability": (2000, 2999),
    "equity": (3000, 3999), "income": (4000, 4999),
    "expense": (5000, 9999),
}


class _AcctMigrateFail(Exception):
    def __init__(self, message, status=400):
        super().__init__(message)
        self.status = status


def _acct_migrate_norm_name(name):
    s = " ".join((name or "").strip().lower().split())
    for suffix in (" (a/r)", " (a/p)"):
        if s.endswith(suffix):
            s = s[: -len(suffix)]
    return s


def _acct_migrate_link(conn, qb_type, qb_id):
    return conn.execute(
        "SELECT * FROM erp_acct_migration_links"
        " WHERE qb_type = ? AND qb_id = ?",
        (qb_type, qb_id)).fetchone()


def _acct_migrate_record_link(conn, qb_type, qb_id, erp_type, erp_id):
    conn.execute(
        "INSERT OR IGNORE INTO erp_acct_migration_links"
        " (qb_type, qb_id, erp_type, erp_id, imported_at)"
        " VALUES (?, ?, ?, ?, ?)",
        (qb_type, qb_id, erp_type, erp_id,
         datetime.now(timezone.utc).isoformat()))


def _acct_migrate_repair_lines(raw):
    """Repair quantities the QuickBooks MCP pull dropped on old invoices.

    The pull recorded qty 0 on some lines while amount_cents and
    rate_cents survived intact. When the amount is an exact whole
    multiple of the rate, the quantity is exactly recoverable as
    amount / rate (e.g. 3 cases at 4188 = 12564) -- no guessing, and
    the import's footing check still enforces the totals. Lines that
    do not repair exactly are left untouched and the invoice is
    skipped by the validator/footing check, as before. Returns a new
    list; the snapshot is never mutated."""
    if not isinstance(raw, list):
        return raw
    out = []
    for entry in raw:
        if not isinstance(entry, dict):
            out.append(entry)
            continue
        entry = dict(entry)
        qty = _acct_int_cents(entry.get("qty"))
        rate = _acct_int_cents(entry.get("rate_cents", 0))
        amount = _acct_int_cents(entry.get("amount_cents", 0))
        if (qty == 0 and rate not in (None, 0) and amount not in (None, 0)
                and amount % rate == 0):
            entry["qty"] = amount // rate
        out.append(entry)
    return out


def _acct_migrate_prior_postings(conn):
    """Net debit-credit cents already posted by earlier migration runs,
    split into document postings and prior opening-balance entries.

    The opening entry is a true-up: targets minus everything the
    migration already posted. A re-run that newly imports an invoice
    the first run skipped must NOT double-count it -- the first run's
    opening entry already covered it, so the re-run's opening entry
    corrects exactly that amount back. (Nov 10 live: Baker $1,312.76
    was skipped in run 1, covered by opening #10, then posted by its
    own invoice in run 2 -- without this, GL A/R ran $1,312.76 high.)

    Document postings are read from the migrated rows themselves
    (journal_entry_id IS NOT NULL means the row posted, so a paid
    invoice that never posted is never counted, and a voided invoice
    nets to zero with its reversing entry). A payment or invoice the
    user creates after migration has no QuickBooks id and is never
    counted, so post-migration activity is untouched by the true-up.
    Returns (doc_posted, open_posted), each {erp account id: net_dc}.
    """
    doc = {}
    open_posted = {}

    def add(d, account_id, net_dc):
        if account_id:
            d[account_id] = d.get(account_id, 0) + net_dc

    ar_id = _acct_account_id_by_code(conn, ERP_ACCT_AR_CODE)
    ap_id = _acct_account_id_by_code(conn, ERP_ACCT_AP_CODE)
    tax_id = _acct_account_id_by_code(conn, ERP_ACCT_TAX_PAYABLE_CODE)
    ws_id = _acct_account_id_by_code(conn, ERP_ACCT_WHOLESALE_INCOME_CODE)
    rt_id = _acct_account_id_by_code(conn, ERP_ACCT_RETAIL_INCOME_CODE)

    for row in conn.execute(
            "SELECT total_cents, subtotal_cents, tax_cents, customer_type"
            " FROM erp_acct_invoices WHERE qb_id IS NOT NULL"
            " AND journal_entry_id IS NOT NULL").fetchall():
        add(doc, ar_id, row["total_cents"] or 0)
        income_id = ws_id if row["customer_type"] != "retail" else rt_id
        add(doc, income_id, -(row["subtotal_cents"] or 0))
        if row["tax_cents"]:
            add(doc, tax_id, -(row["tax_cents"] or 0))
    for row in conn.execute(
            "SELECT lines, total_cents FROM erp_acct_bills"
            " WHERE qb_id IS NOT NULL"
            " AND journal_entry_id IS NOT NULL").fetchall():
        try:
            lines = json.loads(row["lines"] or "[]")
        except (ValueError, TypeError):
            lines = []
        for ln in lines:
            if isinstance(ln, dict):
                add(doc, ln.get("account_id"),
                    _acct_int_cents(ln.get("amount_cents")) or 0)
        add(doc, ap_id, -(row["total_cents"] or 0))
    # Migrated payments and journal entries: read their journal lines
    # directly (the payment row carries its entry id; a JE link's
    # erp_id IS its entry id).
    entry_ids = set()
    for row in conn.execute(
            "SELECT journal_entry_id FROM erp_acct_payments"
            " WHERE qb_id IS NOT NULL"
            " AND journal_entry_id IS NOT NULL").fetchall():
        entry_ids.add(row["journal_entry_id"])
    for row in conn.execute(
            "SELECT erp_id FROM erp_acct_migration_links"
            " WHERE qb_type = 'journal_entry'").fetchall():
        entry_ids.add(row["erp_id"])
    if entry_ids:
        for row in conn.execute(
                "SELECT account_id, debit_cents, credit_cents"
                " FROM erp_acct_journal_lines WHERE entry_id IN (%s)"
                % ",".join("?" * len(entry_ids)),
                tuple(entry_ids)).fetchall():
            add(doc, row["account_id"],
                (row["debit_cents"] or 0) - (row["credit_cents"] or 0))
    # Prior opening-balance entries: their lines are the previous
    # true-ups, counted separately so the Net Income residual does
    # not double-count them.
    for row in conn.execute(
            "SELECT jl.account_id, jl.debit_cents, jl.credit_cents"
            " FROM erp_acct_journal_lines jl"
            " JOIN erp_acct_journal j ON j.id = jl.entry_id"
            " WHERE j.source = 'migration'"
            " AND j.source_id = 'opening-balances'").fetchall():
        add(open_posted, row["account_id"],
            (row["debit_cents"] or 0) - (row["credit_cents"] or 0))
    return doc, open_posted


def _acct_migrate_import_run(conn, actor, lists, as_of, snapshot_id=""):
    """Import one snapshot. Returns the summary dict. Raises
    _AcctMigrateFail on any fatal problem; the caller rolls back."""
    now = datetime.now(timezone.utc).isoformat()
    inserted = {t: 0 for t in ERP_ACCT_MIGRATION_TYPES}
    skipped = {t: 0 for t in ERP_ACCT_MIGRATION_TYPES}
    skipped_reasons = []
    omitted = [0]

    def skip(qb_type, reason):
        skipped[qb_type] += 1
        if len(skipped_reasons) < 50:
            skipped_reasons.append(reason)
        else:
            omitted[0] += 1

    def qb_key(rec, name):
        qb_id = rec.get("qb_id")
        if qb_id not in (None, ""):
            return str(qb_id)
        return "name:" + _acct_migrate_norm_name(name or "")

    posted = {}   # erp account id -> net debit-credit cents posted here
    targets = {}  # erp account id -> target debit-credit cents (balance sheet)
    # True-up base: what earlier migration runs already posted, so a
    # re-run corrects the opening entry instead of double-counting.
    prior_doc, open_posted = _acct_migrate_prior_postings(conn)
    posted.update(prior_doc)

    def track(account_id, net_dc):
        if account_id:
            posted[account_id] = posted.get(account_id, 0) + net_dc

    acct_by_norm = {}
    acct_by_id = {}
    for r in conn.execute("SELECT * FROM erp_acct_accounts").fetchall():
        acct_by_norm[_acct_migrate_norm_name(r["name"])] = dict(r)
        acct_by_id[r["id"]] = dict(r)
    used_codes = {r["code"] for r in conn.execute(
        "SELECT code FROM erp_acct_accounts").fetchall()}

    # --- chart merge: match by normalized name, create missing accounts ---
    pending_parents = []
    for rec in lists["accounts"]:
        name = (rec.get("name") or "").strip()
        atype = (rec.get("type") or "").strip()
        if not name:
            skip("account", "account with no name")
            continue
        if atype not in ERP_ACCT_TYPES:
            skip("account", "%s: unknown type %r" % (name, atype))
            continue
        if rec.get("source") == "qb_chart" and atype in (
                "asset", "liability", "equity"):
            # Balance-sheet accounts come only from the balance-sheet
            # snapshot (consolidated parents with targets). A qb_chart
            # child would double-count against its parent's target,
            # and its balance is already inside the parent; the
            # journal-entry import falls back to the recorded name
            # instead (see below).
            skip("account",
                 "%s: balance-sheet account from qb_chart -- not created"
                 % name)
            continue
        key = _acct_migrate_norm_name(name)
        if _acct_migrate_link(conn, "account", qb_key(rec, name)):
            skipped["account"] += 1
            continue
        existing = acct_by_norm.get(key)
        if existing:
            erp_id = existing["id"]
            if not existing["qb_id"] and rec.get("qb_id"):
                conn.execute(
                    "UPDATE erp_acct_accounts SET qb_id = ? WHERE id = ?",
                    (str(rec["qb_id"]), erp_id))
                existing["qb_id"] = str(rec["qb_id"])
        else:
            lo, hi = ERP_ACCT_MIGRATION_CODE_RANGES[atype]
            code = None
            n = lo
            while n <= hi:
                if str(n) not in used_codes:
                    code = str(n)
                    break
                n += 10
            if code is None:
                skip("account", "%s: no free code in %s range" % (name, atype))
                continue
            cur = conn.execute(
                "INSERT INTO erp_acct_accounts (code, name, type, parent_id,"
                " qb_id, active, created_at) VALUES (?, ?, ?, NULL, ?, 1, ?)",
                (code, name, atype,
                 (str(rec["qb_id"]) if rec.get("qb_id") else None), now))
            erp_id = cur.lastrowid
            used_codes.add(code)
            row = {"id": erp_id, "code": code, "name": name, "type": atype,
                   "parent_id": None, "active": 1}
            acct_by_norm[key] = row
            acct_by_id[erp_id] = row
            _acct_audit(conn, actor, "account.create", "account", erp_id,
                        "%s %s (migration)" % (code, name))
        parent_name = (rec.get("parent_name") or "").strip()
        if parent_name:
            pending_parents.append((erp_id, parent_name))
        if (rec.get("source") == "balance_sheet"
                and rec.get("balance_cents") is not None):
            bal = _acct_int_cents(rec.get("balance_cents"))
            if bal is None:
                raise _AcctMigrateFail(
                    "account %s has a non-integer balance" % name, 400)
            targets[erp_id] = bal if atype in ("asset", "expense") else -bal
        _acct_migrate_record_link(conn, "account", qb_key(rec, name),
                                  "account", erp_id)
        inserted["account"] += 1
    for erp_id, parent_name in pending_parents:
        parent = acct_by_norm.get(_acct_migrate_norm_name(parent_name))
        if parent and parent["id"] != erp_id:
            conn.execute(
                "UPDATE erp_acct_accounts SET parent_id = ? WHERE id = ?",
                (parent["id"], erp_id))
            acct_by_id[erp_id]["parent_id"] = parent["id"]

    # Targets for balance-sheet accounts the merge skipped as already
    # linked (a re-run): the opening entry is a true-up against the
    # CURRENT snapshot, so every balance-sheet account in it needs a
    # target whether or not this run (re)created it.
    for rec in lists["accounts"]:
        name = (rec.get("name") or "").strip()
        atype = (rec.get("type") or "").strip()
        if not name or atype not in ERP_ACCT_TYPES:
            continue
        if (rec.get("source") != "balance_sheet"
                or rec.get("balance_cents") is None):
            continue
        link = _acct_migrate_link(conn, "account", qb_key(rec, name))
        erp_id = link["erp_id"] if link else None
        if erp_id is None:
            existing = acct_by_norm.get(_acct_migrate_norm_name(name))
            erp_id = existing["id"] if existing else None
        if erp_id is not None and erp_id not in targets:
            bal = _acct_int_cents(rec.get("balance_cents"))
            if bal is None:
                continue
            targets[erp_id] = bal if atype in ("asset", "expense") else -bal

    # --- customers -> wholesale accounts ---
    ws_by_norm = {}
    for r in conn.execute("SELECT * FROM erp_wholesale_accounts").fetchall():
        ws_by_norm[_acct_migrate_norm_name(r["name"])] = dict(r)
    for rec in lists["customers"]:
        name = ((rec.get("display_name") or rec.get("name") or "").strip())
        if not name:
            skip("customer", "customer with no name")
            continue
        if _acct_migrate_link(conn, "customer", qb_key(rec, name)):
            skipped["customer"] += 1
            continue
        existing = ws_by_norm.get(_acct_migrate_norm_name(name))
        if existing:
            erp_id = existing["id"]
        else:
            cur = conn.execute(
                "INSERT INTO erp_wholesale_accounts (name, contact_name,"
                " email, phone, address, price_per_bag_cents, payment_terms,"
                " notes, active, created_by, created_at, contact_person,"
                " savory_price_cents, sweet_price_cents, default_po,"
                " pricing_mode, staff_managed, account_status)"
                " VALUES (?, ?, ?, ?, ?, ?, ?, ?, 1, ?, ?, ?, ?, ?, ?, ?, ?, 'active')",
                (name, (rec.get("contact_name") or "").strip(),
                 (rec.get("email") or "").strip(),
                 (rec.get("phone") or "").strip(), "", 400, "", "", actor, now,
                 "", 400, 400, "", "bag", 1))
            erp_id = cur.lastrowid
            ws_by_norm[_acct_migrate_norm_name(name)] = {
                "id": erp_id, "name": name}
        _acct_migrate_record_link(conn, "customer", qb_key(rec, name),
                                  "wholesale_account", erp_id)
        inserted["customer"] += 1

    # --- vendors ---
    vendor_by_norm = {}
    for r in conn.execute("SELECT * FROM erp_vendors").fetchall():
        vendor_by_norm[_acct_migrate_norm_name(r["name"])] = dict(r)
    for rec in lists["vendors"]:
        name = (rec.get("name") or "").strip()
        if not name:
            skip("vendor", "vendor with no name")
            continue
        if _acct_migrate_link(conn, "vendor", qb_key(rec, name)):
            skipped["vendor"] += 1
            continue
        existing = vendor_by_norm.get(_acct_migrate_norm_name(name))
        if existing:
            erp_id = existing["id"]
        else:
            cur = conn.execute(
                "INSERT INTO erp_vendors (name, contact_name, email, phone,"
                " payment_terms, lead_time_days, notes, active, created_at)"
                " VALUES (?, ?, ?, ?, ?, ?, ?, 1, ?)",
                (name, (rec.get("contact_name") or "").strip(),
                 (rec.get("email") or "").strip(),
                 (rec.get("phone") or "").strip(),
                 (rec.get("payment_terms") or "").strip(), 0,
                 (rec.get("notes") or "").strip(), now))
            erp_id = cur.lastrowid
            vendor_by_norm[_acct_migrate_norm_name(name)] = {
                "id": erp_id, "name": name}
        _acct_migrate_record_link(conn, "vendor", qb_key(rec, name),
                                  "vendor", erp_id)
        inserted["vendor"] += 1

    # --- items: no ERP inventory home; invoice lines carry descriptions ---
    for rec in lists["items"]:
        skip("item", "%s: no ERP inventory home for QuickBooks items"
             % ((rec.get("name") or "item").strip() or "item"))

    # --- bank accounts ---
    bank_by_qb = {}
    bank_by_norm = {}
    for r in conn.execute("SELECT * FROM erp_acct_bank_accounts").fetchall():
        bank_by_norm[_acct_migrate_norm_name(r["name"])] = dict(r)
        if r["qb_id"]:
            bank_by_qb[str(r["qb_id"])] = r["id"]
    for rec in lists["bank_accounts"]:
        name = (rec.get("name") or "").strip()
        if not name:
            skip("bank_account", "bank account with no name")
            continue
        if _acct_migrate_link(conn, "bank_account", qb_key(rec, name)):
            skipped["bank_account"] += 1
            continue
        gl_name = (rec.get("gl_account_name") or name)
        gl = acct_by_norm.get(_acct_migrate_norm_name(gl_name))
        if not gl:
            skip("bank_account", "%s: no GL account %r" % (name, gl_name))
            continue
        existing = bank_by_norm.get(_acct_migrate_norm_name(name))
        if existing:
            erp_id = existing["id"]
        else:
            btype = (rec.get("type") or "checking").strip()
            if btype not in ERP_ACCT_BANK_TYPES:
                btype = "checking"
            opening = _acct_int_cents(rec.get("balance_cents"))
            if opening is None:
                opening = 0
            cur = conn.execute(
                "INSERT INTO erp_acct_bank_accounts (name, type,"
                " plaid_account_id, gl_account_id, qb_id,"
                " opening_balance_cents, active, last_reconciled_at,"
                " created_at) VALUES (?, ?, NULL, ?, ?, ?, 1, NULL, ?)",
                (name, btype, gl["id"],
                 (str(rec["qb_id"]) if rec.get("qb_id") else None),
                 opening, now))
            erp_id = cur.lastrowid
            bank_by_norm[_acct_migrate_norm_name(name)] = {
                "id": erp_id, "name": name}
            _acct_audit(conn, actor, "bank.create", "bank_account", erp_id,
                        "%s %s -> GL %s (migration)"
                        % (name, btype, gl["code"]))
        if rec.get("qb_id"):
            bank_by_qb[str(rec["qb_id"])] = erp_id
        _acct_migrate_record_link(conn, "bank_account", qb_key(rec, name),
                                  "bank_account", erp_id)
        inserted["bank_account"] += 1

    ar_id = _acct_account_id_by_code(conn, ERP_ACCT_AR_CODE)
    ap_id = _acct_account_id_by_code(conn, ERP_ACCT_AP_CODE)
    tax_id = _acct_account_id_by_code(conn, ERP_ACCT_TAX_PAYABLE_CODE)
    if not ar_id or not ap_id:
        raise _AcctMigrateFail(
            "chart of accounts is missing a required account", 500)

    # --- invoices (open invoices post; paid/void are records only) ---
    for rec in lists["invoices"]:
        qb_id = rec.get("qb_id")
        if qb_id in (None, ""):
            skip("invoice", "invoice with no QuickBooks id")
            continue
        qb_id = str(qb_id)
        if _acct_migrate_link(conn, "invoice", qb_id):
            skipped["invoice"] += 1
            continue
        date = (rec.get("date") or "").strip()
        if not _acct_valid_date(date):
            skip("invoice", "%s: bad date %r" % (qb_id, date))
            continue
        due_date = (rec.get("due_date") or "").strip()
        if not _acct_valid_date(due_date):
            due_date = date
        customer_type = (rec.get("customer_type") or "wholesale").strip()
        if customer_type not in ("wholesale", "retail"):
            customer_type = "wholesale"
        lines, subtotal, error = _acct_validate_invoice_lines(
            _acct_migrate_repair_lines(rec.get("lines")),
            default_taxable=(customer_type == "retail"),
            allow_credits=True)
        if error:
            skip("invoice", "%s: %s" % (qb_id, error))
            continue
        snap_subtotal = _acct_int_cents(rec.get("subtotal_cents"))
        if snap_subtotal is None or subtotal != snap_subtotal:
            skip("invoice", "%s: lines do not foot to QuickBooks subtotal"
                 % qb_id)
            continue
        tax = _acct_int_cents(rec.get("tax_cents"))
        if tax is None or tax < 0:
            skip("invoice", "%s: bad tax_cents" % qb_id)
            continue
        total = subtotal + tax
        snap_total = _acct_int_cents(rec.get("total_cents"))
        if snap_total is None or total != snap_total:
            skip("invoice", "%s: total != subtotal + tax" % qb_id)
            continue
        balance = _acct_int_cents(rec.get("balance_cents"))
        if balance is None or balance < 0 or balance > total:
            skip("invoice", "%s: bad balance_cents" % qb_id)
            continue
        status = (rec.get("status") or "").strip()
        if status not in ERP_ACCT_DOC_STATUSES:
            status = "open" if balance > 0 else "paid"
        customer_id = None
        customer_name = (rec.get("customer_name") or "").strip()
        cust_qb = rec.get("customer_qb_id")
        if cust_qb not in (None, ""):
            link = _acct_migrate_link(conn, "customer", str(cust_qb))
            if link:
                customer_id = link["erp_id"]
        if customer_id is None and customer_name:
            ws = ws_by_norm.get(_acct_migrate_norm_name(customer_name))
            if ws:
                customer_id = ws["id"]
                customer_name = ws["name"]
        if not customer_name:
            customer_name = "QuickBooks customer %s" % qb_id
        income_code = (ERP_ACCT_WHOLESALE_INCOME_CODE
                       if customer_type == "wholesale"
                       else ERP_ACCT_RETAIL_INCOME_CODE)
        income_id = _acct_account_id_by_code(conn, income_code)
        if not income_id or (tax and not tax_id):
            raise _AcctMigrateFail(
                "chart of accounts is missing a required account", 500)
        cur = conn.execute(
            "INSERT INTO erp_acct_invoices (customer_name, customer_id,"
            " customer_type, date, due_date, lines, subtotal_cents,"
            " tax_cents, total_cents, balance_cents, status,"
            " journal_entry_id, qb_id, tax_jurisdiction, created_at)"
            " VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, NULL, ?, ?, ?)",
            (customer_name, customer_id, customer_type, date, due_date,
             json.dumps(lines), subtotal, tax, total, balance, status,
             qb_id, ERP_ACCT_TAX_DEFAULT_JURISDICTION, now))
        inv_id = cur.lastrowid
        if status == "open":
            raw = [{"account_id": ar_id, "debit_cents": total,
                    "credit_cents": 0, "memo": "Invoice #%d" % inv_id},
                   {"account_id": income_id, "debit_cents": 0,
                    "credit_cents": subtotal,
                    "memo": "Invoice #%d" % inv_id}]
            if tax:
                raw.append({"account_id": tax_id, "debit_cents": 0,
                            "credit_cents": tax,
                            "memo": "Sales tax on invoice #%d" % inv_id})
            entry_id, error = _acct_post_entry(
                conn, actor, date, "Invoice #%d — %s (migration)"
                % (inv_id, customer_name), "invoice", inv_id, raw)
            if error:
                raise _AcctMigrateFail(error, 400)
            conn.execute(
                "UPDATE erp_acct_invoices SET journal_entry_id = ?"
                " WHERE id = ?", (entry_id, inv_id))
            track(ar_id, total)
            track(income_id, -subtotal)
            if tax:
                track(tax_id, -tax)
        _acct_audit(conn, actor, "invoice.create", "invoice", inv_id,
                    "#%d %s total %d (migration)"
                    % (inv_id, customer_name, total))
        _acct_migrate_record_link(conn, "invoice", qb_id, "invoice", inv_id)
        inserted["invoice"] += 1

    # --- bills (open bills post; paid/void are records only) ---
    for rec in lists["bills"]:
        qb_id = rec.get("qb_id")
        if qb_id in (None, ""):
            skip("bill", "bill with no QuickBooks id")
            continue
        qb_id = str(qb_id)
        if _acct_migrate_link(conn, "bill", qb_id):
            skipped["bill"] += 1
            continue
        date = (rec.get("date") or "").strip()
        if not _acct_valid_date(date):
            skip("bill", "%s: bad date %r" % (qb_id, date))
            continue
        due_date = (rec.get("due_date") or "").strip()
        if not _acct_valid_date(due_date):
            due_date = date
        vendor_id = None
        vendor_name = (rec.get("vendor_name") or "").strip()
        vend_qb = rec.get("vendor_qb_id")
        if vend_qb not in (None, ""):
            link = _acct_migrate_link(conn, "vendor", str(vend_qb))
            if link:
                vendor_id = link["erp_id"]
        if vendor_id is None and vendor_name:
            vend = vendor_by_norm.get(_acct_migrate_norm_name(vendor_name))
            if vend:
                vendor_id = vend["id"]
                vendor_name = vend["name"]
        if vendor_id is None:
            skip("bill", "%s: vendor %r was not imported"
                 % (qb_id, vendor_name))
            continue
        raw_lines = []
        for ln in (rec.get("lines") or []):
            if not isinstance(ln, dict):
                continue
            entry = {"description": (ln.get("description") or "").strip(),
                     "amount_cents": ln.get("amount_cents")}
            acct_name = (ln.get("account_name") or "").strip()
            if acct_name:
                acct = acct_by_norm.get(_acct_migrate_norm_name(acct_name))
                if acct:
                    if acct["type"] not in ("expense", "asset"):
                        skip("bill", "%s: line account %r is not expense/asset"
                             % (qb_id, acct_name))
                        raw_lines = None
                        break
                    entry["account_id"] = acct["id"]
            raw_lines.append(entry)
        if raw_lines is None:
            continue
        lines, total, error = _acct_validate_bill_lines(conn, raw_lines)
        if error:
            skip("bill", "%s: %s" % (qb_id, error))
            continue
        snap_total = _acct_int_cents(rec.get("total_cents"))
        if snap_total is None or total != snap_total:
            skip("bill", "%s: lines do not foot to QuickBooks total" % qb_id)
            continue
        balance = _acct_int_cents(rec.get("balance_cents"))
        if balance is None or balance < 0 or balance > total:
            skip("bill", "%s: bad balance_cents" % qb_id)
            continue
        status = (rec.get("status") or "").strip()
        if status not in ERP_ACCT_DOC_STATUSES:
            status = "open" if balance > 0 else "paid"
        cur = conn.execute(
            "INSERT INTO erp_acct_bills (vendor_id, vendor_name, date,"
            " due_date, lines, total_cents, balance_cents, status,"
            " journal_entry_id, qb_id, created_at)"
            " VALUES (?, ?, ?, ?, ?, ?, ?, ?, NULL, ?, ?)",
            (vendor_id, vendor_name, date, due_date, json.dumps(lines),
             total, balance, status, qb_id, now))
        bill_id = cur.lastrowid
        if status == "open":
            raw = [{"account_id": l["account_id"],
                    "debit_cents": l["amount_cents"], "credit_cents": 0,
                    "memo": l["description"]} for l in lines]
            raw.append({"account_id": ap_id, "debit_cents": 0,
                        "credit_cents": total,
                        "memo": "Bill #%d" % bill_id})
            entry_id, error = _acct_post_entry(
                conn, actor, date, "Bill #%d — %s (migration)"
                % (bill_id, vendor_name), "bill", bill_id, raw)
            if error:
                raise _AcctMigrateFail(error, 400)
            conn.execute(
                "UPDATE erp_acct_bills SET journal_entry_id = ? WHERE id = ?",
                (entry_id, bill_id))
            for l in lines:
                track(l["account_id"], l["amount_cents"])
            track(ap_id, -total)
        _acct_audit(conn, actor, "bill.create", "bill", bill_id,
                    "#%d %s total %d (migration)"
                    % (bill_id, vendor_name, total))
        _acct_migrate_record_link(conn, "bill", qb_id, "bill", bill_id)
        inserted["bill"] += 1

    # --- payments (applied to imported invoices/bills only) ---
    for rec in lists["payments"]:
        qb_id = rec.get("qb_id")
        if qb_id in (None, ""):
            skip("payment", "payment with no QuickBooks id")
            continue
        qb_id = str(qb_id)
        if _acct_migrate_link(conn, "payment", qb_id):
            skipped["payment"] += 1
            continue
        date = (rec.get("date") or "").strip()
        if not _acct_valid_date(date):
            skip("payment", "%s: bad date %r" % (qb_id, date))
            continue
        amount = _acct_int_cents(rec.get("amount_cents"))
        if amount is None or amount < 1:
            skip("payment", "%s: bad amount_cents" % qb_id)
            continue
        inv_id = None
        bill_id = None
        inv_qb = rec.get("invoice_qb_id")
        bill_qb = rec.get("bill_qb_id")
        if inv_qb not in (None, ""):
            link = _acct_migrate_link(conn, "invoice", str(inv_qb))
            if link:
                inv_id = link["erp_id"]
        elif bill_qb not in (None, ""):
            link = _acct_migrate_link(conn, "bill", str(bill_qb))
            if link:
                bill_id = link["erp_id"]
        if inv_id is None and bill_id is None:
            skip("payment", "%s: linked invoice/bill was not imported"
                 % qb_id)
            continue
        if inv_id is not None:
            inv = conn.execute(
                "SELECT * FROM erp_acct_invoices WHERE id = ?",
                (inv_id,)).fetchone()
            if not inv or inv["status"] != "open" \
                    or amount > inv["balance_cents"]:
                skip("payment", "%s: invoice is not open or amount exceeds"
                     " its balance" % qb_id)
                continue
        else:
            bill = conn.execute(
                "SELECT * FROM erp_acct_bills WHERE id = ?", (bill_id,)).fetchone()
            if not bill or bill["status"] != "open" \
                    or amount > bill["balance_cents"]:
                skip("payment", "%s: bill is not open or amount exceeds"
                     " its balance" % qb_id)
                continue
        bank_id = None
        bank_qb = rec.get("bank_account_qb_id")
        if bank_qb not in (None, ""):
            bank_id = bank_by_qb.get(str(bank_qb))
        cash_id, bank_err = _acct_cash_account_id(conn, bank_id)
        if bank_err or not cash_id:
            skip("payment", "%s: %s" % (qb_id, bank_err or "no cash account"))
            continue
        method = (rec.get("method") or "cash").strip() or "cash"
        note = "Migrated from QuickBooks payment %s" % qb_id
        if inv_id is not None:
            cur = conn.execute(
                "INSERT INTO erp_acct_payments (invoice_id, bill_id, date,"
                " amount_cents, method, bank_account_id, journal_entry_id,"
                " approval_note, qb_id, created_at)"
                " VALUES (?, NULL, ?, ?, ?, ?, NULL, ?, ?, ?)",
                (inv_id, date, amount, method, bank_id, note, qb_id, now))
            pay_id = cur.lastrowid
            entry_id, error = _acct_post_entry(
                conn, actor, date, "Payment on invoice #%d (migration)"
                % inv_id, "payment", inv_id,
                [{"account_id": cash_id, "debit_cents": amount,
                  "credit_cents": 0,
                  "memo": "Payment on invoice #%d" % inv_id},
                 {"account_id": ar_id, "debit_cents": 0,
                  "credit_cents": amount,
                  "memo": "Payment on invoice #%d" % inv_id}])
            if error:
                raise _AcctMigrateFail(error, 400)
            conn.execute(
                "UPDATE erp_acct_payments SET journal_entry_id = ?"
                " WHERE id = ?", (entry_id, pay_id))
            new_balance = inv["balance_cents"] - amount
            conn.execute(
                "UPDATE erp_acct_invoices SET balance_cents = ?, status = ?"
                " WHERE id = ?",
                (new_balance, "paid" if new_balance == 0 else "open", inv_id))
            track(cash_id, amount)
            track(ar_id, -amount)
            _acct_audit(conn, actor, "invoice.pay", "invoice", inv_id,
                        "payment #%d %d cents (migration)" % (pay_id, amount))
        else:
            cur = conn.execute(
                "INSERT INTO erp_acct_payments (invoice_id, bill_id, date,"
                " amount_cents, method, bank_account_id, journal_entry_id,"
                " approval_note, qb_id, created_at)"
                " VALUES (NULL, ?, ?, ?, ?, ?, NULL, ?, ?, ?)",
                (bill_id, date, amount, method, bank_id, note, qb_id, now))
            pay_id = cur.lastrowid
            entry_id, error = _acct_post_entry(
                conn, actor, date, "Payment on bill #%d (migration)"
                % bill_id, "payment", bill_id,
                [{"account_id": ap_id, "debit_cents": amount,
                  "credit_cents": 0,
                  "memo": "Payment on bill #%d" % bill_id},
                 {"account_id": cash_id, "debit_cents": 0,
                  "credit_cents": amount,
                  "memo": "Payment on bill #%d" % bill_id}])
            if error:
                raise _AcctMigrateFail(error, 400)
            conn.execute(
                "UPDATE erp_acct_payments SET journal_entry_id = ?"
                " WHERE id = ?", (entry_id, pay_id))
            new_balance = bill["balance_cents"] - amount
            conn.execute(
                "UPDATE erp_acct_bills SET balance_cents = ?, status = ?"
                " WHERE id = ?",
                (new_balance, "paid" if new_balance == 0 else "open", bill_id))
            track(ap_id, amount)
            track(cash_id, -amount)
            _acct_audit(conn, actor, "bill.pay", "bill", bill_id,
                        "payment #%d %d cents (migration)" % (pay_id, amount))
        _acct_migrate_record_link(conn, "payment", qb_id, "payment", pay_id)
        inserted["payment"] += 1

    # --- journal entries (already posted in QuickBooks; insert directly) ---
    for rec in lists["journal_entries"]:
        qb_id = rec.get("qb_id")
        if qb_id in (None, ""):
            skip("journal_entry", "journal entry with no QuickBooks id")
            continue
        qb_id = str(qb_id)
        if _acct_migrate_link(conn, "journal_entry", qb_id):
            skipped["journal_entry"] += 1
            continue
        date = (rec.get("date") or "").strip()
        if not _acct_valid_date(date):
            skip("journal_entry", "%s: bad date %r" % (qb_id, date))
            continue
        raw = []
        bad = None
        for ln in (rec.get("lines") or []):
            if not isinstance(ln, dict):
                bad = "line is not an object"
                break
            account_id = ln.get("account_id")
            if account_id in (None, "", 0):
                acct_name = (ln.get("account_name") or "").strip()
                acct = acct_by_norm.get(_acct_migrate_norm_name(acct_name)) \
                    if acct_name else None
                if not acct and acct_name:
                    # QuickBooks names a child by its fully qualified
                    # name ("Parent:Child"); the chart may record it
                    # under its short name, a wider suffix, or the
                    # parent -- try those in that order, so a payroll
                    # liability child lands on its own short-named
                    # account rather than the consolidated parent.
                    _parts = acct_name.split(":")
                    _cands = [":".join(_parts[_i:])
                              for _i in range(1, len(_parts))]
                    _cands += [":".join(_parts[:_i])
                               for _i in range(len(_parts) - 1, 0, -1)]
                    for _cand in _cands:
                        acct = acct_by_norm.get(
                            _acct_migrate_norm_name(_cand))
                        if acct:
                            break
                if not acct:
                    bad = "unknown account %r" % acct_name
                    break
                account_id = acct["id"]
            debit = _acct_int_cents(ln.get("debit_cents", 0))
            credit = _acct_int_cents(ln.get("credit_cents", 0))
            if debit is None or credit is None:
                bad = "line amounts must be whole cents"
                break
            raw.append({"account_id": account_id, "debit_cents": debit,
                        "credit_cents": credit,
                        "memo": (ln.get("memo") or "").strip()})
        if bad:
            skip("journal_entry", "%s: %s" % (qb_id, bad))
            continue
        memo = (rec.get("memo") or "").strip() or "QuickBooks journal entry %s" % qb_id
        entry_id, error = _acct_post_entry(
            conn, actor, date, memo + " (migration)", "migration", qb_id, raw)
        if error:
            skip("journal_entry", "%s: %s" % (qb_id, error))
            continue
        for line in raw:
            track(line["account_id"],
                  line["debit_cents"] - line["credit_cents"])
        _acct_migrate_record_link(conn, "journal_entry", qb_id,
                                  "journal_entry", entry_id)
        inserted["journal_entry"] += 1

    # --- bank transactions: not imported (no QuickBooks feed in snapshot) ---
    for rec in lists["bank_transactions"]:
        skip("bank_transaction", "bank transaction: not imported (no feed)")

    # --- opening-balance entry, posted last ---
    # QuickBooks' "Net Income" row already contains the income and
    # expenses the imported documents re-post, so its residual subtracts
    # the net income/expense postings of this import instead of its own.
    ni_id = None
    for erp_id in targets:
        if _acct_migrate_norm_name(acct_by_id[erp_id]["name"]) == "net income":
            ni_id = erp_id
            break
    raw = []
    for erp_id, target_dc in targets.items():
        if erp_id == ni_id:
            continue
        residual = (target_dc - posted.get(erp_id, 0)
                    - open_posted.get(erp_id, 0))
        if residual == 0:
            continue
        raw.append({"account_id": erp_id,
                    "debit_cents": residual if residual > 0 else 0,
                    "credit_cents": -residual if residual < 0 else 0,
                    "memo": "Opening balance — QuickBooks migration"})
    if ni_id is not None:
        ni_posted = sum(posted.get(aid, 0) for aid, a in acct_by_id.items()
                        if a["type"] in ("income", "expense"))
        residual = (targets[ni_id] - ni_posted
                    - open_posted.get(ni_id, 0))
        if residual != 0:
            raw.append({"account_id": ni_id,
                        "debit_cents": residual if residual > 0 else 0,
                        "credit_cents": -residual if residual < 0 else 0,
                        "memo": "Opening balance — QuickBooks migration"})
    opening_entry_id = None
    if raw:
        entry_id, error = _acct_post_entry(
            conn, actor, as_of,
            "Opening balances — QuickBooks migration (as of %s)" % as_of,
            "migration", "opening-balances", raw)
        if error:
            raise _AcctMigrateFail(
                "opening entry would not balance: %s" % error, 400)
        opening_entry_id = entry_id
    _acct_audit(conn, actor, "migration.import", "migration", 0,
                "as of %s snapshot %s inserted %s skipped %s opening entry %s"
                % (as_of, snapshot_id or "none",
                   {k: v for k, v in inserted.items() if v},
                   {k: v for k, v in skipped.items() if v},
                   opening_entry_id))
    return {"snapshot_id": snapshot_id, "inserted": inserted, "skipped": skipped,
            "skipped_reasons": skipped_reasons,
            "skipped_reasons_omitted": omitted[0],
            "opening_entry_id": opening_entry_id, "as_of": as_of}


@app.post("/api/erp/accounting/migrate/import")
def erp_acct_migrate_import():
    # Nov 10: the cron secret is accepted as well as an admin session
    # (same pattern as the sales backfill and the qb-snapshot
    # endpoints), so the parent agent can run the import from a job
    # without a browser session. The import itself is atomic and
    # idempotent on erp_acct_migration_links, so a cron-triggered
    # import is as safe as an admin-triggered one.
    actor = None
    if CRON_SECRET and hmac.compare_digest(request.headers.get("X-Cron-Secret", ""), CRON_SECRET):
        actor = "cron"
    else:
        actor, err = _erp_check_perm("accounting.write")
        if err:
            return err
    data = request.get_json(force=True, silent=True)
    if not isinstance(data, dict):
        return jsonify(error="snapshot must be a JSON object"), 400
    lists = {}
    for key in ("accounts", "customers", "vendors", "items", "invoices",
                "bills", "payments", "bank_accounts", "bank_transactions",
                "journal_entries"):
        val = data.get(key, [])
        if not isinstance(val, list):
            return jsonify(error="%s must be a list" % key), 400
        for rec in val:
            if not isinstance(rec, dict):
                return jsonify(error="%s entries must be objects" % key), 400
        lists[key] = val
    # QB's full chart (pulled by qb-pull/run-types into qb_chart):
    # P&L accounts the balance-sheet snapshot never carried. Merged
    # into the chart list so journal-entry lines can resolve; they
    # carry no balance target (source is qb_chart, not
    # balance_sheet) and lose to a balance-sheet record of the same
    # name. Rows with an unknown type are dropped, never guessed.
    _seen_chart_names = {_acct_migrate_norm_name((r.get("name") or ""))
                         for r in lists["accounts"]}
    for _rec in (data.get("qb_chart") or []):
        if not isinstance(_rec, dict):
            continue
        _name = (_rec.get("name") or "").strip()
        if not _name:
            continue
        if _acct_migrate_norm_name(_name) in _seen_chart_names:
            continue
        if (_rec.get("type") or "") not in ERP_ACCT_TYPES:
            continue
        _seen_chart_names.add(_acct_migrate_norm_name(_name))
        lists["accounts"].append(_rec)
    meta = data.get("meta") or {}
    if not isinstance(meta, dict):
        return jsonify(error="meta must be an object"), 400
    as_of = (meta.get("as_of") or "").strip()
    if as_of and not _acct_valid_date(as_of):
        return jsonify(error="meta.as_of must be YYYY-MM-DD"), 400
    if not as_of:
        as_of = datetime.now(timezone.utc).date().isoformat()
    # The snapshot format carries no id of its own: prefer an explicit
    # meta.snapshot_id, else the source + pulled_at stamp identifies it.
    snapshot_id = (meta.get("snapshot_id") or "").strip()
    if not snapshot_id:
        snapshot_id = (meta.get("source") or "quickbooks-mcp").strip()
        pulled_at = (meta.get("pulled_at") or "").strip()
        if pulled_at:
            snapshot_id = "%s@%s" % (snapshot_id, pulled_at)
    conn = db()
    try:
        result = _acct_migrate_import_run(conn, actor, lists, as_of,
                                        snapshot_id)
    except _AcctMigrateFail as exc:
        conn.close()
        return jsonify(error=str(exc)), exc.status
    except Exception as exc:  # noqa: BLE001 - import must never half-commit
        conn.close()
        return jsonify(error="migration failed: %s" % exc), 500
    conn.commit()
    conn.close()
    return jsonify(result), 201


@app.get("/api/erp/purchase-orders")
def erp_list_pos():
    actor, err = _erp_check_perm("purchasing.read")
    if err:
        return err
    conn = db()
    status = (request.args.get("status") or "").strip()
    if status and status in ERP_PO_STATUSES:
        rows = conn.execute(
            "SELECT * FROM erp_purchase_orders WHERE status = ? ORDER BY id DESC",
            (status,)).fetchall()
    else:
        rows = conn.execute(
            "SELECT * FROM erp_purchase_orders ORDER BY id DESC").fetchall()
    result = [_erp_po_summary(conn, po) for po in rows]
    conn.close()
    return jsonify(purchase_orders=result)


def _erp_drop_ship_parse_link(conn, data):
    """Validate a drop-ship flag + linked buyer order from a PO payload.

    Returns (is_drop_ship, source, order_id, error). A non-drop-ship PO
    must not carry a link; a drop-ship PO must name a real buyer order
    (stripe / paypal / wholesale) -- the link is validated against the
    order record, never invented. The flag accepts a JSON boolean (or
    1 / "true"); the string "false" is NOT truthy here.
    """
    _flag = data.get("is_drop_ship")
    is_drop_ship = 1 if _flag is True or _flag == 1 \
        or str(_flag or "").strip().lower() in ("1", "true", "yes") else 0
    source = (data.get("drop_ship_order_source") or "").strip()
    order_id = data.get("drop_ship_order_id")
    if order_id is not None and order_id != "":
        try:
            order_id = int(order_id)
        except (TypeError, ValueError):
            return 0, "", None, "drop_ship_order_id must be an order id"
    else:
        order_id = None
    if not is_drop_ship:
        if source or order_id:
            return 0, "", None, \
                "a drop-ship order link needs is_drop_ship set"
        return 0, "", None, None
    if source not in _ERP_ORDER_SOURCES:
        return 0, "", None, \
            "drop_ship_order_source must be stripe, paypal or wholesale"
    if not order_id:
        return 0, "", None, "a drop-ship PO must name its buyer order"
    if not _erp_order_brief(conn, source, order_id):
        return 0, "", None, "drop-ship buyer order not found"
    return 1, source, order_id, None


def _erp_po_is_drop_ship(po):
    """True when a PO row carries the drop-ship flag (migration-safe:
    rows built before the columns existed read as ordinary POs)."""
    return bool(po["is_drop_ship"]) if "is_drop_ship" in po.keys() else False


def _erp_drop_ship_ensure(conn, po_id, actor):
    """Create the shipment row for a sent drop-ship PO (status ordered).

    Idempotent: a row already there is left alone. The row is built
    from the PO's own validated link -- vendor + buyer order -- never
    invented. Returns the row dict, or None when the PO is not a
    drop-ship PO or its link is missing (cannot happen through the API:
    create/edit validate the link, so a missing link means corrupt data
    and no row is faked up for it).
    """
    po = conn.execute(
        "SELECT * FROM erp_purchase_orders WHERE id = ?", (po_id,)).fetchone()
    if not po or not _erp_po_is_drop_ship(po):
        return None
    row = conn.execute(
        "SELECT * FROM erp_drop_ship_shipments WHERE po_id = ?",
        (po_id,)).fetchone()
    if row:
        return dict(row)
    source = (po["drop_ship_order_source"] or "") \
        if "drop_ship_order_source" in po.keys() else ""
    oid = po["drop_ship_order_id"] if "drop_ship_order_id" in po.keys() else None
    if not source or not oid:
        return None
    now = datetime.now(timezone.utc).isoformat()
    cur = conn.execute(
        "INSERT INTO erp_drop_ship_shipments (po_id, order_source, order_id,"
        " status, created_by, updated_by, created_at, updated_at)"
        " VALUES (?, ?, ?, 'ordered', ?, ?, ?, ?)",
        (po_id, source, oid, actor, actor, now, now))
    return dict(conn.execute(
        "SELECT * FROM erp_drop_ship_shipments WHERE id = ?",
        (cur.lastrowid,)).fetchone())


def _erp_drop_ship_ship_to(conn, source, order_id):
    """Ship-to address of a buyer order, for a drop-ship PO email.

    Stripe/PayPal: the checkout shipping address. Wholesale: the
    account address (the same address the Order hub shows as Ship to).
    '' when the order or address is unknown -- the email then omits
    the ship-to line rather than printing a made-up address.
    """
    if source in ("stripe", "paypal"):
        o = _erp_online_order(conn, source, order_id)
        return (o or {}).get("shipping_address") or ""
    if source == "wholesale":
        w = conn.execute(
            "SELECT * FROM erp_wholesale_orders WHERE id = ?",
            (order_id,)).fetchone()
        if not w:
            return ""
        acct = conn.execute(
            "SELECT address FROM erp_wholesale_accounts WHERE id = ?",
            (w["account_id"],)).fetchone()
        return (acct["address"] or "") if acct else ""
    return ""


def _erp_create_po_from_data(conn, actor, data):
    """Validate + insert a purchase order from a plain data dict, the
    single PO creation path. Used by the POST /purchase-orders
    endpoint AND by requisition conversion (Wave 4 item 10, SOP
    3.19) and RFQ award conversion, so a converted requisition goes
    through the exact same validation and the exact same
    approved-supplier gate as a hand-made PO -- never a bypass, never
    a second gate. Returns (po_id, None) on success, (None, error)
    on refusal. Does NOT commit and does NOT close the connection:
    the caller commits (so conversion can record the PO on the
    requisition in the same transaction) and closes."""
    data = data or {}
    try:
        vendor_id = int(data.get("vendor_id") or 0)
    except (TypeError, ValueError):
        vendor_id = 0
    vendor = conn.execute(
        "SELECT * FROM erp_vendors WHERE id = ?", (vendor_id,)).fetchone()
    if not vendor or not vendor["active"]:
        return None, "valid vendor_id is required"
    # Approved-supplier gate (Wave 4 item 9, SOP 3.18): a PO may only
    # be created for an approved supplier. Hard refuse, 400 -- a
    # failed supplier audit (B4) only flags the vendor and never
    # blocks, but this gate is the deliberate new policy: buying only
    # from approved suppliers. No override exists, silent or
    # otherwise; an admin must approve the vendor first. POs that
    # already exist are never touched by the gate.
    if _vendor_onboarding_status(conn, vendor["id"]) != "approved":
        return None, ("vendor is not an approved supplier --"
                      " complete vendor onboarding and approval"
                      " first (Purchasing -> Approved suppliers)")
    raw_lines = data.get("lines") or []
    if not raw_lines:
        return None, "at least one line is required"
    # Drop-ship (SOP 5.34): the flag + linked buyer order. A drop-ship
    # PO is validated here, at creation, so a PO can never point at an
    # order that does not exist.
    _ds_flag, _ds_source, _ds_oid, _ds_err = _erp_drop_ship_parse_link(conn, data)
    if _ds_err:
        return None, _ds_err
    clean = []
    for entry in raw_lines:
        item = _erp_get_item(conn, (entry or {}).get("item_id"))
        if not item or not item["active"]:
            return None, "every line needs a valid item_id"
        # The popcorn-only rule holds for stocking POs. A drop-ship PO
        # never stocks anything (its receive path posts no stock), so
        # its lines may be any active item -- that is the whole point of
        # drop-ship: selling items the company never stocks. The
        # popcorn-only SOP is unchanged for ordinary POs.
        if not _ds_flag and (item["type"] or "") != "popcorn":
            return None, "only popcorn can be added to a purchase order"
        try:
            qty = float(entry.get("qty_ordered") or 0)
        except (TypeError, ValueError):
            qty = 0
        try:
            cost = int(entry.get("unit_cost_cents") or 0)
        except (TypeError, ValueError):
            cost = 0
        if qty <= 0:
            return None, "qty_ordered must be greater than zero"
        if cost < 0:
            return None, "unit_cost_cents cannot be negative"
        clean.append((item["id"], qty, cost))
    try:
        freight = int(data.get("freight_cents") or 0)
        tax = int(data.get("tax_cents") or 0)
    except (TypeError, ValueError):
        return None, "freight_cents and tax_cents must be whole cents"
    if freight < 0 or tax < 0:
        return None, "freight_cents and tax_cents cannot be negative"
    count = conn.execute("SELECT COUNT(*) AS c FROM erp_purchase_orders").fetchone()["c"]
    po_number = "PO-%d" % (1001 + int(count))
    now = datetime.now(timezone.utc).isoformat()
    cur = conn.execute(
        "INSERT INTO erp_purchase_orders (po_number, vendor_id, status, order_date,"
        " expected_date, freight_cents, tax_cents, notes, created_by, created_at,"
        " is_drop_ship, drop_ship_order_source, drop_ship_order_id)"
        " VALUES (?, ?, 'draft', ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
        (po_number, vendor["id"], now[:10],
         (data.get("expected_date") or "").strip(), freight, tax,
         (data.get("notes") or "").strip(), actor, now,
         _ds_flag, _ds_source, _ds_oid),
    )
    po_id = cur.lastrowid
    for item_id, qty, cost in clean:
        conn.execute(
            "INSERT INTO erp_po_lines (po_id, item_id, qty_ordered, qty_received,"
            " unit_cost_cents) VALUES (?, ?, ?, 0, ?)",
            (po_id, item_id, qty, cost),
        )
    return po_id, None


@app.post("/api/erp/purchase-orders")
def erp_create_po():
    actor, err = _erp_check_perm("purchasing.write")
    if err:
        return err
    data = request.get_json(force=True) or {}
    conn = db()
    po_id, po_err = _erp_create_po_from_data(conn, actor, data)
    if po_err:
        conn.close()
        return jsonify(error=po_err), 400
    conn.commit()
    po = conn.execute(
        "SELECT * FROM erp_purchase_orders WHERE id = ?", (po_id,)).fetchone()
    result = _erp_po_summary(conn, po)
    conn.close()
    return jsonify(purchase_order=result), 201


@app.get("/api/erp/purchase-orders/<int:po_id>")
def erp_get_po(po_id):
    actor, err = _erp_check_perm("purchasing.read")
    if err:
        return err
    conn = db()
    po = conn.execute(
        "SELECT * FROM erp_purchase_orders WHERE id = ?", (po_id,)).fetchone()
    if not po:
        conn.close()
        return jsonify(error="purchase order not found"), 404
    vendor = conn.execute(
        "SELECT * FROM erp_vendors WHERE id = ?", (po["vendor_id"],)).fetchone()
    lines = conn.execute(
        "SELECT l.*, i.sku, i.name AS item_name, i.type AS item_type, i.unit AS item_unit"
        " FROM erp_po_lines l JOIN erp_items i ON i.id = l.item_id"
        " WHERE l.po_id = ? ORDER BY l.id", (po_id,)).fetchall()
    summary = _erp_po_summary(conn, po)
    match = _acct_po_match(conn, po_id)
    drop_ship = _erp_drop_ship_dict(conn, po_id)
    conn.close()
    return jsonify(purchase_order=summary, vendor=dict(vendor) if vendor else None,
                   lines=[dict(l) for l in lines], match=match,
                   drop_ship=drop_ship)


@app.get("/api/erp/purchase-orders/<int:po_id>/match")
def erp_get_po_match(po_id):
    actor, err = _erp_check_perm("purchasing.read")
    if err:
        return err
    conn = db()
    match = _acct_po_match(conn, po_id)
    conn.close()
    if match is None:
        return jsonify(error="purchase order not found"), 404
    return jsonify(match=match)


@app.post("/api/erp/purchase-orders/<int:po_id>/receive")
def erp_po_receive(po_id):
    actor, err = _erp_check_perm("inventory.receive")
    if err:
        return err
    data = request.get_json(force=True) or {}
    conn = db()
    po = conn.execute(
        "SELECT * FROM erp_purchase_orders WHERE id = ?", (po_id,)).fetchone()
    if not po:
        conn.close()
        return jsonify(error="purchase order not found"), 404
    if po["status"] not in ("sent", "partial"):
        conn.close()
        return jsonify(
            error="PO must be sent before receiving (status: %s)" % po["status"]), 400
    # Drop-ship (SOP 5.34): the company never holds these goods, so
    # there is nothing to receive into stock -- and receiving MUST NOT
    # post a ledger movement, a lot, or an average-cost change for a
    # drop-ship PO. Refuse outright and point at the shipment endpoint:
    # the vendor's shipment is recorded on the PO, not received here.
    # The refusal happens before any location / line validation, so a
    # refused call writes nothing at all.
    if "is_drop_ship" in po.keys() and po["is_drop_ship"]:
        conn.close()
        return jsonify(
            error="drop-ship purchase orders are never received into stock"
                  " -- record the vendor shipment on the PO instead"
                  " (no stock is posted for drop-ship lines)"), 400
    lines = conn.execute(
        "SELECT * FROM erp_po_lines WHERE po_id = ? ORDER BY id",
        (po_id,)).fetchall()
    by_id = {l["id"]: l for l in lines}
    req_lines = data.get("lines") or []
    if not req_lines:
        conn.close()
        return jsonify(error="lines is required"), 400
    location_id = data.get("location_id")
    if location_id is None:
        hend = _erp_get_location_by_code(conn, "HEND")
        location_id = hend["id"] if hend else None
    loc = _erp_get_location(conn, location_id)
    if not loc or not loc["active"]:
        conn.close()
        return jsonify(error="valid location_id is required"), 400
    lot_code_in = (data.get("lot_code") or "").strip()
    expiry_date = (data.get("expiry_date") or "").strip()
    # WMS depth (Wave 4 item 3): optional bin for the whole receipt --
    # no bin = unassigned, never a default bin.
    bin_code, berr = _erp_validate_bin(conn, data.get("bin_id"), loc["id"])
    if berr:
        conn.close()
        return jsonify(error=berr), 400
    # Validate everything before writing (all-or-nothing).
    todo = []
    for entry in req_lines:
        try:
            line_id = int((entry or {}).get("line_id") or 0)
        except (TypeError, ValueError):
            line_id = 0
        line = by_id.get(line_id)
        if not line:
            conn.close()
            return jsonify(error="PO line not found"), 400
        try:
            qty = float(entry.get("qty_received") or 0)
        except (TypeError, ValueError):
            conn.close()
            return jsonify(error="qty_received must be a number"), 400
        remaining = float(line["qty_ordered"]) - float(line["qty_received"])
        if qty <= 0 or qty > remaining + 1e-9:
            conn.close()
            return jsonify(
                error="qty_received for line %d must be between 0 and %s"
                      % (line["id"], _erp_fmt_qty(remaining))), 400
        todo.append((line, qty))
    total_ordered_value = sum(
        float(l["qty_ordered"]) * int(l["unit_cost_cents"]) for l in lines)
    total_receipt_qty = sum(qty for _, qty in todo)
    freight = int(po["freight_cents"] or 0)
    today = datetime.now(timezone.utc).date().isoformat()
    received = []
    for line, qty in todo:
        unit_cost = int(line["unit_cost_cents"])
        if total_ordered_value > 0:
            alloc = freight * (qty * unit_cost) / total_ordered_value
        elif total_receipt_qty > 0:
            alloc = freight * qty / total_receipt_qty
        else:
            alloc = 0
        landed = unit_cost + int(round(alloc / qty)) if qty else unit_cost
        new_avg = _erp_new_avg_cost(conn, line["item_id"], qty, landed)
        lot_code = lot_code_in or ("%s-L%d" % (po["po_number"], line["id"]))
        _erp_post_movement(conn, line["item_id"], loc["id"], qty, "purchase_receipt",
                           actor, ref_type="po", ref_id=po["po_number"],
                           lot_code=lot_code, unit_cost_cents=landed,
                           note="PO %s receive" % po["po_number"],
                           bin_code=bin_code)
        conn.execute("UPDATE erp_items SET avg_cost_cents = ? WHERE id = ?",
                     (new_avg, line["item_id"]))
        conn.execute("UPDATE erp_po_lines SET qty_received = qty_received + ? WHERE id = ?",
                     (qty, line["id"]))
        if lot_code or expiry_date:
            conn.execute(
                "INSERT INTO erp_lots (lot_code, item_id, supplier_lot, received_date,"
                " expiry_date, location_id) VALUES (?, ?, '', ?, ?, ?)",
                (lot_code, line["item_id"], today, expiry_date, loc["id"]),
            )
        received.append({"line_id": line["id"], "qty_received": qty,
                         "landed_unit_cost_cents": landed,
                         "new_avg_cost_cents": new_avg})
    remaining_total = conn.execute(
        "SELECT COALESCE(SUM(qty_ordered - qty_received), 0) AS r"
        " FROM erp_po_lines WHERE po_id = ?", (po_id,)).fetchone()["r"]
    new_status = "received" if float(remaining_total or 0) <= 1e-9 else "partial"
    conn.execute("UPDATE erp_purchase_orders SET status = ? WHERE id = ?",
                 (new_status, po_id))
    conn.commit()
    conn.close()
    return jsonify(ok=True, po_id=po_id, status=new_status, received=received)


@app.post("/api/erp/purchase-orders/<int:po_id>/status")
def erp_po_status(po_id):
    actor, err = _erp_check_perm("purchasing.write")
    if err:
        return err
    data = request.get_json(force=True) or {}
    new_status = (data.get("status") or "").strip()
    if new_status not in ERP_PO_STATUSES:
        return jsonify(error="status must be one of: " + ", ".join(ERP_PO_STATUSES)), 400
    conn = db()
    po = conn.execute(
        "SELECT * FROM erp_purchase_orders WHERE id = ?", (po_id,)).fetchone()
    if not po:
        conn.close()
        return jsonify(error="purchase order not found"), 404
    allowed = ERP_PO_TRANSITIONS.get(po["status"], ())
    if new_status not in allowed:
        conn.close()
        return jsonify(error="cannot move PO from %s to %s" % (po["status"], new_status)), 400
    if new_status == "sent":
        # Wave 3 B9 (SOP 9.33): a PO is sent on one admin's say-so
        # unless an enabled approval template covers purchase orders
        # -- then it may not send while a pending approval exists for
        # it, and needs an approved one to go through.
        _po_total = conn.execute(
            "SELECT COALESCE(SUM(qty_ordered * unit_cost_cents), 0) AS t"
            " FROM erp_po_lines WHERE po_id = ?",
            (po_id,)).fetchone()["t"]
        _po_total = int(_po_total or 0) + (po["freight_cents"] or 0) \
            + (po["tax_cents"] or 0)
        _po_gate_error, _po_approved = _approval_gate(
            conn, "purchase_order", po_id, _po_total, actor)
        if _po_gate_error:
            conn.close()
            return jsonify(error=_po_gate_error), 409
    # Drop-ship (SOP 5.34): a shipped / delivered shipment is history.
    # The PO cannot be cancelled once the vendor has shipped the
    # buyer's goods -- cancelling would pretend an in-flight delivery
    # never happened. An unshipped shipment row is removed with the
    # cancel below (it never left the vendor).
    _ds_ship = None
    if _erp_po_is_drop_ship(po):
        _ds_ship = conn.execute(
            "SELECT * FROM erp_drop_ship_shipments WHERE po_id = ?",
            (po_id,)).fetchone()
        if new_status == "cancelled" and _ds_ship \
                and _ds_ship["status"] in ("shipped", "delivered"):
            conn.close()
            return jsonify(
                error="a drop-ship PO cannot be cancelled after the vendor"
                      " has shipped it -- the shipment is history"), 400
    conn.execute("UPDATE erp_purchase_orders SET status = ? WHERE id = ?",
                 (new_status, po_id))
    if new_status == "sent" and _erp_po_is_drop_ship(po):
        # Sending a drop-ship PO orders the shipment: the shipment row
        # is born here, status ordered, from the PO's own link.
        _erp_drop_ship_ensure(conn, po_id, actor)
    if new_status == "cancelled" and _ds_ship \
            and _ds_ship["status"] in ("ordered", "vendor_confirmed"):
        conn.execute(
            "DELETE FROM erp_drop_ship_shipments WHERE id = ?",
            (_ds_ship["id"],))
    conn.commit()
    conn.close()
    return jsonify(ok=True, po_id=po_id, status=new_status)


def _erp_po_last_receipt_date(conn, po_number):
    """Date (YYYY-MM-DD) of the last purchase_receipt ledger row for a PO."""
    row = conn.execute(
        "SELECT MAX(substr(created_at, 1, 10)) AS d FROM erp_stock_ledger"
        " WHERE movement_type = 'purchase_receipt' AND ref_id = ?",
        (po_number,)).fetchone()
    return row["d"] if row and row["d"] else None


def _erp_vendor_performance(conn, vendor_id):
    """On-time %, fill rate, OTIF %, avg lead time, overdue POs for one
    vendor.

    On-time and lead time cover completed POs (received/closed) that have an
    expected date and a receipt row; fill rate covers every ordered PO
    (sent/partial/received/closed) — drafts and cancelled POs are excluded.

    OTIF (Module C, Nov 2026) — the share of deliveries that were BOTH
    on-time AND in-full, per completed PO:
      on-time: last receipt date <= expected date (needs an expected
        date and a receipt row; same rule as the on-time %).
      in-full: total qty received >= total qty ordered across the PO's
        lines (tolerance 1e-9; /receive can never over-receive, but a
        data fix could, and that still counts as full). A PO with no
        lines / zero ordered cannot be scored in-full.
      OTIF denominator: completed POs with an expected date, a receipt
        row, AND ordered qty > 0 -- the POs where both halves can be
        judged. Draft/sent/partial/cancelled POs are never scored: a PO
        still in transit has no delivery to judge yet.
    in-full % on its own covers every completed PO with ordered qty > 0
    (no expected date needed). Vendors with no completed POs get nulls
    for every percentage -- "no data", never a zero score. The per-PO
    rows ("pos") make every score auditable back to the PO.
    """
    pos = conn.execute(
        "SELECT * FROM erp_purchase_orders WHERE vendor_id = ? ORDER BY id",
        (vendor_id,)).fetchall()
    today = datetime.now(timezone.utc).date().isoformat()
    completed = [p for p in pos if p["status"] in ("received", "closed")]
    open_pos = [p for p in pos if p["status"] in ("draft", "sent", "partial")]
    on_time = 0
    on_time_denom = 0
    lead_days = []
    for p in completed:
        if not (p["expected_date"] or ""):
            continue
        last = _erp_po_last_receipt_date(conn, p["po_number"])
        if not last:
            continue
        on_time_denom += 1
        if last <= p["expected_date"]:
            on_time += 1
        try:
            lead_days.append(
                (datetime.strptime(last, "%Y-%m-%d").date()
                 - datetime.strptime((p["order_date"] or "")[:10],
                                    "%Y-%m-%d").date()).days)
        except (ValueError, TypeError):
            pass
    ordered = 0.0
    received = 0.0
    for p in pos:
        if p["status"] in ("draft", "cancelled"):
            continue
        for l in conn.execute(
                "SELECT qty_ordered, qty_received FROM erp_po_lines WHERE po_id = ?",
                (p["id"],)).fetchall():
            ordered += float(l["qty_ordered"] or 0)
            received += float(l["qty_received"] or 0)
    # Per-PO OTIF rows (see the docstring for the definitions).
    po_rows = []
    otif_count = 0
    otif_denom = 0
    in_full_count = 0
    in_full_denom = 0
    for p in completed:
        lines = conn.execute(
            "SELECT qty_ordered, qty_received FROM erp_po_lines WHERE po_id = ?",
            (p["id"],)).fetchall()
        po_ordered = sum(float(l["qty_ordered"] or 0) for l in lines)
        po_received = sum(float(l["qty_received"] or 0) for l in lines)
        last = _erp_po_last_receipt_date(conn, p["po_number"])
        expected = (p["expected_date"] or "")
        on_time_po = (last <= expected) if (expected and last) else None
        in_full_po = ((po_received >= po_ordered - 1e-9)
                      if po_ordered > 1e-9 else None)
        if in_full_po is not None:
            in_full_denom += 1
            if in_full_po:
                in_full_count += 1
        otif_po = None
        if on_time_po is not None and in_full_po is not None:
            otif_denom += 1
            otif_po = bool(on_time_po and in_full_po)
            if otif_po:
                otif_count += 1
        po_rows.append({
            "po_id": p["id"], "po_number": p["po_number"],
            "status": p["status"],
            "order_date": (p["order_date"] or "")[:10],
            "expected_date": expected, "last_receipt_date": last,
            "qty_ordered": po_ordered, "qty_received": po_received,
            "on_time": on_time_po, "in_full": in_full_po,
            "otif": otif_po})
    overdue = []
    for p in pos:
        if (p["status"] in ("sent", "partial") and (p["expected_date"] or "")
                and p["expected_date"] < today):
            try:
                days = (datetime.strptime(today, "%Y-%m-%d").date()
                        - datetime.strptime(p["expected_date"],
                                            "%Y-%m-%d").date()).days
            except ValueError:
                days = 0
            overdue.append({"po_id": p["id"], "po_number": p["po_number"],
                            "status": p["status"],
                            "expected_date": p["expected_date"],
                            "days_overdue": days})
    return {
        "po_count": len(pos),
        "open_count": len(open_pos),
        "completed_count": len(completed),
        "on_time_pct": (round(100.0 * on_time / on_time_denom, 1)
                        if on_time_denom else None),
        "on_time_count": on_time,
        "on_time_denominator": on_time_denom,
        "fill_rate_pct": (round(100.0 * received / ordered, 1)
                          if ordered > 0 else None),
        "otif_pct": (round(100.0 * otif_count / otif_denom, 1)
                     if otif_denom else None),
        "otif_count": otif_count,
        "otif_denominator": otif_denom,
        "in_full_pct": (round(100.0 * in_full_count / in_full_denom, 1)
                        if in_full_denom else None),
        "in_full_count": in_full_count,
        "in_full_denominator": in_full_denom,
        "pos": po_rows,
        "avg_lead_days": (round(sum(lead_days) / len(lead_days), 1)
                          if lead_days else None),
        "overdue": overdue,
    }


def _erp_po_email_html(po, vendor, lines, ship_to=""):
    """Plain HTML body for a PO email: the PO is the order.

    ship_to is the drop-ship buyer's address (SOP 5.34): when set, the
    vendor is told to ship straight to the buyer, not to Pop-A-Licious.
    """
    import html as _html
    dollars = lambda c: "$%s" % format((c or 0) / 100, ",.2f")
    rows = ""
    lines_total = 0
    for l in lines:
        lt = int(round(float(l["qty_ordered"]) * int(l["unit_cost_cents"])))
        lines_total += lt
        rows += ("<tr><td>%s &mdash; %s</td><td>%s</td><td>%s</td><td>%s</td></tr>"
                 % (_html.escape(l["sku"] or ""),
                    _html.escape(l["item_name"] or ""),
                    _erp_fmt_qty(l["qty_ordered"]),
                    dollars(l["unit_cost_cents"]), dollars(lt)))
    freight = int(po["freight_cents"] or 0)
    tax = int(po["tax_cents"] or 0)
    grand = lines_total + freight + tax
    notes = ""
    if (po["notes"] or "").strip():
        notes = "<p><strong>Notes:</strong> %s</p>" % _html.escape(po["notes"])
    drop_ship = ""
    if (ship_to or "").strip():
        drop_ship = ("<p><strong>Drop-ship &mdash; ship directly to the buyer,"
                     " not to us:</strong><br>%s</p>"
                     % _html.escape(ship_to))
    return """\
<html><body style="font-family: Arial, sans-serif; line-height: 1.6;">
<p>Hi %s,</p>
<p>Please supply the following order from Pop-A-Licious:</p>
<p><strong>Purchase order %s</strong><br>
Order date: %s<br>
Expected delivery: %s</p>
<table border="1" cellpadding="6" cellspacing="0">
<tr><th>Item</th><th>Qty</th><th>Unit cost</th><th>Line total</th></tr>
%s
</table>
<p>Goods: %s<br>Freight: %s<br>Tax: %s<br><strong>Total: %s</strong></p>
%s
%s
<p>Please confirm receipt of this order and the expected delivery date.</p>
<p>Thanks,<br>Pop-A-Licious</p>
</body></html>""" % (
        _html.escape(vendor["contact_name"] or vendor["name"] or "there"),
        _html.escape(po["po_number"]),
        (po["order_date"] or "")[:10],
        _html.escape(po["expected_date"] or "—"),
        rows,
        dollars(lines_total), dollars(freight), dollars(tax), dollars(grand),
        drop_ship, notes)


@app.put("/api/erp/purchase-orders/<int:po_id>")
def erp_update_po(po_id):
    actor, err = _erp_check_perm("purchasing.write")
    if err:
        return err
    data = request.get_json(force=True) or {}
    conn = db()
    po = conn.execute(
        "SELECT * FROM erp_purchase_orders WHERE id = ?", (po_id,)).fetchone()
    if not po:
        conn.close()
        return jsonify(error="purchase order not found"), 404
    if po["status"] != "draft":
        conn.close()
        return jsonify(
            error="only draft purchase orders can be edited (status: %s)"
                  % po["status"]), 400
    vendor_id = po["vendor_id"]
    if "vendor_id" in data:
        try:
            vendor_id = int(data.get("vendor_id") or 0)
        except (TypeError, ValueError):
            conn.close()
            return jsonify(error="vendor_id must be a number"), 400
        vendor = conn.execute(
            "SELECT * FROM erp_vendors WHERE id = ?", (vendor_id,)).fetchone()
        if not vendor or not vendor["active"]:
            conn.close()
            return jsonify(error="valid vendor_id is required"), 400
    # Drop-ship (SOP 5.34): a draft PO can gain or lose the flag and its
    # buyer-order link. Turning the flag off without naming a link clears
    # the old link; any link given is validated against the real order.
    _ds_flag = int(po["is_drop_ship"] or 0) if "is_drop_ship" in po.keys() else 0
    _ds_source = (po["drop_ship_order_source"] or "") \
        if "drop_ship_order_source" in po.keys() else ""
    _ds_oid = po["drop_ship_order_id"] \
        if "drop_ship_order_id" in po.keys() else None
    if "is_drop_ship" in data or "drop_ship_order_source" in data \
            or "drop_ship_order_id" in data:
        _merged = {
            "is_drop_ship": data.get("is_drop_ship", bool(_ds_flag)),
            "drop_ship_order_source": data.get("drop_ship_order_source", _ds_source),
            "drop_ship_order_id": data.get("drop_ship_order_id", _ds_oid),
        }
        _flag_off = _merged["is_drop_ship"] is False or _merged["is_drop_ship"] == 0 \
            or str(_merged["is_drop_ship"] or "").strip().lower() \
            in ("0", "false", "no", "")
        if _flag_off and "drop_ship_order_source" not in data \
                and "drop_ship_order_id" not in data:
            _merged["drop_ship_order_source"] = ""
            _merged["drop_ship_order_id"] = None
        _ds_flag, _ds_source, _ds_oid, _ds_err = \
            _erp_drop_ship_parse_link(conn, _merged)
        if _ds_err:
            conn.close()
            return jsonify(error=_ds_err), 400
    try:
        freight = int(data.get("freight_cents", po["freight_cents"]) or 0)
        tax = int(data.get("tax_cents", po["tax_cents"]) or 0)
    except (TypeError, ValueError):
        conn.close()
        return jsonify(error="freight_cents and tax_cents must be whole cents"), 400
    if freight < 0 or tax < 0:
        conn.close()
        return jsonify(error="freight_cents and tax_cents cannot be negative"), 400
    expected = (data.get("expected_date", po["expected_date"]) or "").strip()
    notes = (data.get("notes", po["notes"]) or "").strip()
    clean = None
    if "lines" in data:
        raw_lines = data.get("lines") or []
        if not raw_lines:
            conn.close()
            return jsonify(error="at least one line is required"), 400
        already = conn.execute(
            "SELECT COALESCE(SUM(qty_received), 0) AS r"
            " FROM erp_po_lines WHERE po_id = ?", (po_id,)).fetchone()["r"]
        if float(already or 0) > 0:
            conn.close()
            return jsonify(
                error="cannot edit lines after receiving has started"), 400
        clean = []
        for entry in raw_lines:
            item = _erp_get_item(conn, (entry or {}).get("item_id"))
            if not item or not item["active"]:
                conn.close()
                return jsonify(error="every line needs a valid item_id"), 400
            if not _ds_flag and (item["type"] or "") != "popcorn":
                conn.close()
                return jsonify(
                    error="only popcorn can be added to a purchase order"), 400
            try:
                qty = float(entry.get("qty_ordered") or 0)
            except (TypeError, ValueError):
                qty = 0
            try:
                cost = int(entry.get("unit_cost_cents") or 0)
            except (TypeError, ValueError):
                cost = 0
            if qty <= 0:
                conn.close()
                return jsonify(
                    error="qty_ordered must be greater than zero"), 400
            if cost < 0:
                conn.close()
                return jsonify(
                    error="unit_cost_cents cannot be negative"), 400
            clean.append((item["id"], qty, cost))
    conn.execute(
        "UPDATE erp_purchase_orders SET vendor_id = ?, expected_date = ?,"
        " freight_cents = ?, tax_cents = ?, notes = ?,"
        " is_drop_ship = ?, drop_ship_order_source = ?,"
        " drop_ship_order_id = ? WHERE id = ?",
        (vendor_id, expected, freight, tax, notes,
         _ds_flag, _ds_source, _ds_oid, po_id))
    if clean is not None:
        conn.execute("DELETE FROM erp_po_lines WHERE po_id = ?", (po_id,))
        for item_id, qty, cost in clean:
            conn.execute(
                "INSERT INTO erp_po_lines (po_id, item_id, qty_ordered,"
                " qty_received, unit_cost_cents) VALUES (?, ?, ?, 0, ?)",
                (po_id, item_id, qty, cost))
    conn.commit()
    po = conn.execute(
        "SELECT * FROM erp_purchase_orders WHERE id = ?", (po_id,)).fetchone()
    vendor = conn.execute(
        "SELECT * FROM erp_vendors WHERE id = ?", (po["vendor_id"],)).fetchone()
    lines = conn.execute(
        "SELECT l.*, i.sku, i.name AS item_name, i.type AS item_type,"
        " i.unit AS item_unit"
        " FROM erp_po_lines l JOIN erp_items i ON i.id = l.item_id"
        " WHERE l.po_id = ? ORDER BY l.id", (po_id,)).fetchall()
    summary = _erp_po_summary(conn, po)
    conn.close()
    return jsonify(purchase_order=summary, vendor=dict(vendor) if vendor else None,
                   lines=[dict(l) for l in lines])


@app.post("/api/erp/purchase-orders/<int:po_id>/email")
def erp_email_po(po_id):
    actor, err = _erp_check_perm("purchasing.write")
    if err:
        return err
    conn = db()
    po = conn.execute(
        "SELECT * FROM erp_purchase_orders WHERE id = ?", (po_id,)).fetchone()
    if not po:
        conn.close()
        return jsonify(error="purchase order not found"), 404
    if po["status"] == "cancelled":
        conn.close()
        return jsonify(error="cancelled purchase orders cannot be emailed"), 400
    if po["status"] == "draft":
        # Wave 3 B9 (SOP 9.33): emailing a draft PO sends it, so the
        # same approval gate as /status to "sent" applies here.
        _po_total = conn.execute(
            "SELECT COALESCE(SUM(qty_ordered * unit_cost_cents), 0) AS t"
            " FROM erp_po_lines WHERE po_id = ?",
            (po_id,)).fetchone()["t"]
        _po_total = int(_po_total or 0) + (po["freight_cents"] or 0) \
            + (po["tax_cents"] or 0)
        _po_gate_error, _po_approved = _approval_gate(
            conn, "purchase_order", po_id, _po_total, actor)
        if _po_gate_error:
            conn.close()
            return jsonify(error=_po_gate_error), 409
    vendor = conn.execute(
        "SELECT * FROM erp_vendors WHERE id = ?", (po["vendor_id"],)).fetchone()
    if not vendor or not (vendor["email"] or "").strip():
        conn.close()
        return jsonify(error="this vendor has no email on file \u2014 add one to send the PO"), 400
    lines = conn.execute(
        "SELECT l.*, i.sku, i.name AS item_name, i.type AS item_type,"
        " i.unit AS item_unit"
        " FROM erp_po_lines l JOIN erp_items i ON i.id = l.item_id"
        " WHERE l.po_id = ? ORDER BY l.id", (po_id,)).fetchall()
    # Drop-ship (SOP 5.34): the emailed PO tells the vendor to ship
    # straight to the buyer, at the buyer's address -- never to us.
    _ship_to = ""
    if _erp_po_is_drop_ship(po):
        _ship_to = _erp_drop_ship_ship_to(
            conn,
            (po["drop_ship_order_source"] or "")
            if "drop_ship_order_source" in po.keys() else "",
            po["drop_ship_order_id"]
            if "drop_ship_order_id" in po.keys() else 0)
    body = _erp_po_email_html(po, vendor, lines, _ship_to)
    try:
        send_email((vendor["email"] or "").strip(),
                   "Purchase order %s from Pop-A-Licious" % po["po_number"],
                   body)
    except Exception as exc:
        conn.close()
        return jsonify(error="couldn't send the email: %s" % exc), 502
    now = datetime.now(timezone.utc).isoformat()
    new_status = "sent" if po["status"] == "draft" else po["status"]
    conn.execute(
        "UPDATE erp_purchase_orders SET emailed_at = ?, status = ? WHERE id = ?",
        (now, new_status, po_id))
    if new_status == "sent":
        # Emailing a draft sends it: same as /status to sent, the
        # drop-ship shipment row is born here (status ordered).
        _erp_drop_ship_ensure(conn, po_id, actor)
    conn.commit()
    po = conn.execute(
        "SELECT * FROM erp_purchase_orders WHERE id = ?", (po_id,)).fetchone()
    summary = _erp_po_summary(conn, po)
    conn.close()
    return jsonify(purchase_order=summary,
                   emailed_to=(vendor["email"] or "").strip(), emailed_at=now)


# ---------------- Supplier portal (Wave 3 §4.2 item 7, Nov 2026) ----------------
# Token-scoped per-PO vendor links -- NOT vendor accounts with
# passwords. Wholesale login was deliberately removed from this ERP
# (sign-in shows Admin and Staff only; no self-service wholesale
# password reset), and the Nov 17 direction is staff-managed vendors:
# a vendor password login would reverse that security decision
# without approval, so it is NOT built here. Full vendor accounts
# would need a reversal of that direction plus a security review.
#
# An admin generates a single-purpose, expiring token link per PO.
# The vendor opens the link with NO login, sees ONLY that PO, can
# confirm it (accept / decline with a note), and can submit an
# invoice against it (invoice number + amount + note). The
# submission creates a DRAFT bill (status 'draft', source 'portal',
# no journal entry, balance 0) for admin review -- it does NOT post
# to the ledger by itself. An admin approves it with an expense
# account (that posts the journal entry and opens the bill) or
# rejects it (the draft bill is voided; nothing was ever posted, so
# no reversal is needed). Tokens expire (default 30 days), are
# revocable, and are single-PO scoped. Only the SHA-256 hash of a
# token is stored, never the raw token; the raw token is shown once,
# at creation, and never again. A wrong, expired, or revoked token
# returns the same generic 404, never a hint about what exists.
ERP_VENDOR_PORTAL_TOKEN_TTL_DAYS = 30
ERP_VENDOR_PORTAL_MAX_EXPIRY_DAYS = 365


def _portal_token_hash(token):
    return hashlib.sha256(token.encode("utf-8")).hexdigest()


def _portal_token_status(row, now_iso):
    if row["revoked"]:
        return "revoked"
    if (row["expires_at"] or "") <= now_iso:
        return "expired"
    return "active"


def _portal_token_public(row):
    now = datetime.now(timezone.utc).isoformat()
    return {
        "id": row["id"], "po_id": row["po_id"],
        "expires_at": row["expires_at"],
        "revoked": bool(row["revoked"]),
        "status": _portal_token_status(row, now),
        "created_by": row["created_by"], "created_at": row["created_at"],
        "last_used_at": row["last_used_at"]}


def _portal_resolve_token(conn, raw):
    """(token_row, po_row) for a live token, else (None, None). Every
    failure looks the same to the caller -- no hint about what exists."""
    if not raw or len(raw) > 200:
        return None, None
    row = conn.execute(
        "SELECT * FROM erp_vendor_portal_tokens WHERE token_hash = ?",
        (_portal_token_hash(raw),)).fetchone()
    if not row:
        return None, None
    now = datetime.now(timezone.utc).isoformat()
    if row["revoked"] or (row["expires_at"] or "") <= now:
        return None, None
    po = conn.execute(
        "SELECT * FROM erp_purchase_orders WHERE id = ?",
        (row["po_id"],)).fetchone()
    if not po:
        return None, None
    return row, po


def _portal_touch_token(conn, token_id):
    conn.execute(
        "UPDATE erp_vendor_portal_tokens SET last_used_at = ? WHERE id = ?",
        (datetime.now(timezone.utc).isoformat(), token_id))


def _portal_po_public(conn, po):
    vendor = conn.execute(
        "SELECT name FROM erp_vendors WHERE id = ?",
        (po["vendor_id"],)).fetchone()
    lines = conn.execute(
        "SELECT l.*, i.sku, i.name AS item_name"
        " FROM erp_po_lines l JOIN erp_items i ON i.id = l.item_id"
        " WHERE l.po_id = ? ORDER BY l.id", (po["id"],)).fetchall()
    lines_total = sum(
        int(round(float(l["qty_ordered"]) * int(l["unit_cost_cents"])))
        for l in lines)
    total = lines_total + int(po["freight_cents"] or 0) \
        + int(po["tax_cents"] or 0)
    return {
        "po_number": po["po_number"],
        "vendor_name": vendor["name"] if vendor else "",
        "status": po["status"],
        "order_date": (po["order_date"] or "")[:10],
        "expected_date": po["expected_date"] or "",
        "freight_cents": int(po["freight_cents"] or 0),
        "tax_cents": int(po["tax_cents"] or 0),
        "total_cents": total,
        "notes": po["notes"] or "",
        "vendor_confirmation": po["vendor_confirmation"] or "",
        "vendor_confirmed_at": po["vendor_confirmed_at"] or "",
        "vendor_confirmation_note": po["vendor_confirmation_note"] or "",
        "lines": [{
            "sku": l["sku"], "item_name": l["item_name"],
            "qty_ordered": l["qty_ordered"],
            "qty_received": l["qty_received"],
            "unit_cost_cents": int(l["unit_cost_cents"])} for l in lines]}


def _portal_submission_public(row):
    return {
        "id": row["id"], "po_id": row["po_id"],
        "vendor_invoice_number": row["vendor_invoice_number"],
        "amount_cents": int(row["amount_cents"] or 0),
        "note": row["note"] or "", "status": row["status"],
        "bill_id": row["bill_id"], "created_at": row["created_at"]}


@app.post("/api/erp/purchase-orders/<int:po_id>/portal-tokens")
def erp_po_create_portal_token(po_id):
    actor, err = _erp_check_perm("purchasing.write")
    if err:
        return err
    data = request.get_json(force=True) or {}
    _raw_days = data.get("expires_in_days")
    if _raw_days in (None, ""):
        days = ERP_VENDOR_PORTAL_TOKEN_TTL_DAYS
    else:
        try:
            days = int(_raw_days)
        except (TypeError, ValueError):
            return jsonify(
                error="expires_in_days must be a whole number of days"), 400
    if days < 1 or days > ERP_VENDOR_PORTAL_MAX_EXPIRY_DAYS:
        return jsonify(
            error="expires_in_days must be between 1 and %d"
                  % ERP_VENDOR_PORTAL_MAX_EXPIRY_DAYS), 400
    conn = db()
    po = conn.execute(
        "SELECT * FROM erp_purchase_orders WHERE id = ?", (po_id,)).fetchone()
    if not po:
        conn.close()
        return jsonify(error="purchase order not found"), 404
    if po["status"] in ("draft", "cancelled"):
        conn.close()
        return jsonify(
            error="portal links can only be created for an ordered purchase"
                  " order (status: %s)" % po["status"]), 400
    raw = secrets.token_urlsafe(32)
    now = datetime.now(timezone.utc)
    expires = (now + timedelta(days=days)).isoformat()
    cur = conn.execute(
        "INSERT INTO erp_vendor_portal_tokens (po_id, token_hash,"
        " expires_at, revoked, created_by, created_at, last_used_at)"
        " VALUES (?, ?, ?, 0, ?, ?, '')",
        (po_id, _portal_token_hash(raw), expires, actor or "",
         now.isoformat()))
    _erp_staff_audit(conn, actor, "portal.token_created", "purchase_order",
                     po_id, "%s portal link created, expires %s"
                     % (po["po_number"], expires[:10]))
    conn.commit()
    row = conn.execute(
        "SELECT * FROM erp_vendor_portal_tokens WHERE id = ?",
        (cur.lastrowid,)).fetchone()
    conn.close()
    # The raw token is returned exactly once, here. It is never stored
    # and never returned again -- the list endpoint carries no token.
    return jsonify(token=_portal_token_public(row), portal_token=raw,
                   portal_url="/vendor-portal/" + raw), 201


@app.get("/api/erp/purchase-orders/<int:po_id>/portal-tokens")
def erp_po_list_portal_tokens(po_id):
    actor, err = _erp_check_perm("purchasing.read")
    if err:
        return err
    conn = db()
    po = conn.execute(
        "SELECT * FROM erp_purchase_orders WHERE id = ?", (po_id,)).fetchone()
    if not po:
        conn.close()
        return jsonify(error="purchase order not found"), 404
    rows = conn.execute(
        "SELECT * FROM erp_vendor_portal_tokens WHERE po_id = ?"
        " ORDER BY id DESC", (po_id,)).fetchall()
    conn.close()
    return jsonify(tokens=[_portal_token_public(r) for r in rows])


@app.post("/api/erp/purchase-orders/<int:po_id>/portal-tokens/<int:token_id>/revoke")
def erp_po_revoke_portal_token(po_id, token_id):
    actor, err = _erp_check_perm("purchasing.write")
    if err:
        return err
    conn = db()
    row = conn.execute(
        "SELECT * FROM erp_vendor_portal_tokens WHERE id = ? AND po_id = ?",
        (token_id, po_id)).fetchone()
    if not row:
        conn.close()
        return jsonify(error="portal token not found"), 404
    if not row["revoked"]:
        conn.execute(
            "UPDATE erp_vendor_portal_tokens SET revoked = 1 WHERE id = ?",
            (token_id,))
        po = conn.execute(
            "SELECT * FROM erp_purchase_orders WHERE id = ?",
            (po_id,)).fetchone()
        _erp_staff_audit(conn, actor, "portal.token_revoked",
                         "purchase_order", po_id,
                         "%s portal link revoked"
                         % (po["po_number"] if po else "PO #%d" % po_id))
        conn.commit()
        row = conn.execute(
            "SELECT * FROM erp_vendor_portal_tokens WHERE id = ?",
            (token_id,)).fetchone()
    conn.close()
    return jsonify(token=_portal_token_public(row))


@app.get("/api/erp/purchase-orders/<int:po_id>/portal-submissions")
def erp_po_list_portal_submissions(po_id):
    actor, err = _erp_check_perm("purchasing.read")
    if err:
        return err
    conn = db()
    po = conn.execute(
        "SELECT * FROM erp_purchase_orders WHERE id = ?", (po_id,)).fetchone()
    if not po:
        conn.close()
        return jsonify(error="purchase order not found"), 404
    rows = conn.execute(
        "SELECT s.*, b.status AS bill_status"
        " FROM erp_vendor_portal_submissions s"
        " LEFT JOIN erp_acct_bills b ON b.id = s.bill_id"
        " WHERE s.po_id = ? ORDER BY s.id DESC", (po_id,)).fetchall()
    conn.close()
    out = []
    for r in rows:
        d = _portal_submission_public(r)
        d["bill_status"] = r["bill_status"] or ""
        out.append(d)
    return jsonify(submissions=out)


def _portal_submission_and_bill(conn, po_id, sub_id):
    sub = conn.execute(
        "SELECT * FROM erp_vendor_portal_submissions"
        " WHERE id = ? AND po_id = ?", (sub_id, po_id)).fetchone()
    if not sub:
        return None, None, "portal submission not found"
    bill = conn.execute(
        "SELECT * FROM erp_acct_bills WHERE id = ?",
        (sub["bill_id"],)).fetchone() if sub["bill_id"] else None
    if not bill:
        return sub, None, "submission has no draft bill"
    return sub, bill, None


@app.post("/api/erp/purchase-orders/<int:po_id>/portal-submissions/<int:sub_id>/approve")
def erp_po_approve_portal_submission(po_id, sub_id):
    # Approving posts to the ledger, so it needs accounting.write --
    # not just purchasing.write.
    actor, err = _erp_check_perm("accounting.write")
    if err:
        return err
    data = request.get_json(force=True) or {}
    conn = db()
    po = conn.execute(
        "SELECT * FROM erp_purchase_orders WHERE id = ?", (po_id,)).fetchone()
    if not po:
        conn.close()
        return jsonify(error="purchase order not found"), 404
    sub, bill, error = _portal_submission_and_bill(conn, po_id, sub_id)
    if error:
        conn.close()
        return jsonify(error=error), 404
    if sub["status"] != "submitted":
        conn.close()
        return jsonify(
            error="only a submitted invoice can be approved (status: %s)"
                  % sub["status"]), 400
    if bill["status"] != "draft" or bill["journal_entry_id"] is not None:
        conn.close()
        return jsonify(error="only an unposted draft bill can be approved"), 400
    total = int(bill["total_cents"] or 0)
    if total < 1:
        conn.close()
        return jsonify(error="draft bill total must be greater than zero"), 400
    try:
        stored_lines = json.loads(bill["lines"] or "[]")
    except (ValueError, TypeError):
        stored_lines = []
    desc = ""
    if stored_lines and isinstance(stored_lines[0], dict):
        desc = (stored_lines[0].get("description") or "").strip()
    if not desc:
        desc = "Vendor invoice %s — %s (portal submission)" % (
            sub["vendor_invoice_number"], po["po_number"])
    account_id = data.get("account_id")
    line = {"description": desc, "amount_cents": total}
    if account_id not in (None, "", 0):
        line["account_id"] = account_id
    elif stored_lines and isinstance(stored_lines[0], dict) \
            and stored_lines[0].get("account_id"):
        line["account_id"] = stored_lines[0]["account_id"]
    clean, clean_total, line_error = _acct_validate_bill_lines(conn, [line])
    if line_error:
        conn.close()
        return jsonify(error=line_error), 400
    if clean_total != total:
        conn.close()
        return jsonify(error="draft bill lines do not add up to its total"), 400
    ap_id = _acct_account_id_by_code(conn, ERP_ACCT_AP_CODE)
    if not ap_id:
        conn.close()
        return jsonify(error="chart of accounts is missing a required account"), 500
    today = datetime.now(timezone.utc).date().isoformat()
    now = datetime.now(timezone.utc).isoformat()
    raw = [{"account_id": clean[0]["account_id"], "debit_cents": total,
            "credit_cents": 0, "memo": desc},
           {"account_id": ap_id, "debit_cents": 0, "credit_cents": total,
            "memo": "Bill #%d" % bill["id"]}]
    entry_id, post_error = _acct_post_entry(
        conn, actor, today,
        "Bill #%d — %s (portal invoice %s)"
        % (bill["id"], bill["vendor_name"], sub["vendor_invoice_number"]),
        "bill", bill["id"], raw)
    if post_error:
        conn.close()
        return jsonify(error=post_error), 400
    conn.execute(
        "UPDATE erp_acct_bills SET lines = ?, status = 'open',"
        " balance_cents = ?, journal_entry_id = ? WHERE id = ?",
        (json.dumps(clean), total, entry_id, bill["id"]))
    conn.execute(
        "UPDATE erp_vendor_portal_submissions SET status = 'approved',"
        " reviewed_by = ?, reviewed_at = ? WHERE id = ?",
        (actor or "", now, sub_id))
    _acct_audit(conn, actor, "bill.portal_approve", "bill", bill["id"],
                "#%d %s total %d entry #%d (portal invoice %s)"
                % (bill["id"], bill["vendor_name"], total, entry_id,
                   sub["vendor_invoice_number"]))
    conn.commit()
    row = conn.execute(
        "SELECT * FROM erp_acct_bills WHERE id = ?", (bill["id"],)).fetchone()
    sub_row = conn.execute(
        "SELECT * FROM erp_vendor_portal_submissions WHERE id = ?",
        (sub_id,)).fetchone()
    conn.close()
    return jsonify(submission=_portal_submission_public(sub_row),
                   bill=_acct_bill_dict(row))


@app.post("/api/erp/purchase-orders/<int:po_id>/portal-submissions/<int:sub_id>/reject")
def erp_po_reject_portal_submission(po_id, sub_id):
    actor, err = _erp_check_perm("accounting.write")
    if err:
        return err
    conn = db()
    po = conn.execute(
        "SELECT * FROM erp_purchase_orders WHERE id = ?", (po_id,)).fetchone()
    if not po:
        conn.close()
        return jsonify(error="purchase order not found"), 404
    sub, bill, error = _portal_submission_and_bill(conn, po_id, sub_id)
    if error:
        conn.close()
        return jsonify(error=error), 404
    if sub["status"] != "submitted":
        conn.close()
        return jsonify(
            error="only a submitted invoice can be rejected (status: %s)"
                  % sub["status"]), 400
    if bill["status"] != "draft" or bill["journal_entry_id"] is not None:
        conn.close()
        return jsonify(error="only an unposted draft bill can be rejected"), 400
    now = datetime.now(timezone.utc).isoformat()
    conn.execute(
        "UPDATE erp_vendor_portal_submissions SET status = 'rejected',"
        " reviewed_by = ?, reviewed_at = ? WHERE id = ?",
        (actor or "", now, sub_id))
    # The draft never posted, so voiding it needs no journal reversal:
    # there is no entry to reverse. Its balance was already 0.
    conn.execute(
        "UPDATE erp_acct_bills SET status = 'void', balance_cents = 0"
        " WHERE id = ?", (bill["id"],))
    _acct_audit(conn, actor, "bill.portal_reject", "bill", bill["id"],
                "#%d %s total %d voided unposted (portal invoice %s)"
                % (bill["id"], bill["vendor_name"],
                   int(bill["total_cents"] or 0),
                   sub["vendor_invoice_number"]))
    conn.commit()
    sub_row = conn.execute(
        "SELECT * FROM erp_vendor_portal_submissions WHERE id = ?",
        (sub_id,)).fetchone()
    row = conn.execute(
        "SELECT * FROM erp_acct_bills WHERE id = ?", (bill["id"],)).fetchone()
    conn.close()
    return jsonify(submission=_portal_submission_public(sub_row),
                   bill=_acct_bill_dict(row))


# ---- Public, token-gated portal endpoints (no login) ----
# Every failure is the same generic 404: a bad token, an expired
# token, and a revoked token are indistinguishable from outside.
_PORTAL_NOT_FOUND = {"error": "portal link not found or expired"}


@app.get("/api/public/vendor-portal/<token>")
def public_vendor_portal(token):
    conn = db()
    trow, po = _portal_resolve_token(conn, token)
    if not trow:
        conn.close()
        return jsonify(_PORTAL_NOT_FOUND), 404
    _portal_touch_token(conn, trow["id"])
    subs = conn.execute(
        "SELECT * FROM erp_vendor_portal_submissions"
        " WHERE token_id = ? ORDER BY id DESC",
        (trow["id"],)).fetchall()
    conn.commit()
    out = _portal_po_public(conn, po)
    conn.close()
    return jsonify(po=out,
                   submissions=[_portal_submission_public(s) for s in subs])


@app.post("/api/public/vendor-portal/<token>/confirm")
def public_vendor_portal_confirm(token):
    err = _auth_throttle_check("vendor-portal-ip", _client_ip(),
                               max_fails=20)
    if err:
        return err
    _auth_throttle_fail("vendor-portal-ip", _client_ip())
    data = request.get_json(force=True) or {}
    decision = (data.get("decision") or "").strip().lower()
    if decision not in ("accepted", "declined"):
        return jsonify(error="decision must be accepted or declined"), 400
    note = (data.get("note") or "").strip()
    if len(note) > 2000:
        return jsonify(error="note is too long"), 400
    conn = db()
    trow, po = _portal_resolve_token(conn, token)
    if not trow:
        conn.close()
        return jsonify(_PORTAL_NOT_FOUND), 404
    if po["status"] in ("cancelled", "closed"):
        conn.close()
        return jsonify(
            error="this purchase order is closed and cannot be confirmed"), 400
    # No new PO status: the confirmation is a timestamp + note on the
    # PO. A decline does NOT cancel the PO -- an admin decides that.
    # Re-confirming overwrites the previous decision (latest wins).
    now = datetime.now(timezone.utc).isoformat()
    conn.execute(
        "UPDATE erp_purchase_orders SET vendor_confirmation = ?,"
        " vendor_confirmed_at = ?, vendor_confirmation_note = ?"
        " WHERE id = ?", (decision, now, note, po["id"]))
    _portal_touch_token(conn, trow["id"])
    _erp_staff_audit(conn, "vendor-portal", "portal.po_confirmed",
                     "purchase_order", po["id"],
                     "%s %s by vendor via portal link"
                     % (po["po_number"], decision))
    conn.commit()
    conn.close()
    return jsonify(po_number=po["po_number"], vendor_confirmation=decision,
                   vendor_confirmed_at=now, vendor_confirmation_note=note)


@app.post("/api/public/vendor-portal/<token>/submit-invoice")
def public_vendor_portal_submit_invoice(token):
    err = _auth_throttle_check("vendor-portal-ip", _client_ip(),
                               max_fails=20)
    if err:
        return err
    _auth_throttle_fail("vendor-portal-ip", _client_ip())
    data = request.get_json(force=True) or {}
    inv = (data.get("vendor_invoice_number") or "").strip()
    if not inv or len(inv) > 100:
        return jsonify(
            error="vendor_invoice_number is required (1-100 characters)"), 400
    amount = _acct_int_cents(data.get("amount_cents"))
    if amount is None or amount < 1:
        return jsonify(
            error="amount_cents must be whole cents greater than zero"), 400
    note = (data.get("note") or "").strip()
    if len(note) > 2000:
        return jsonify(error="note is too long"), 400
    conn = db()
    trow, po = _portal_resolve_token(conn, token)
    if not trow:
        conn.close()
        return jsonify(_PORTAL_NOT_FOUND), 404
    if po["status"] in ("draft", "cancelled"):
        conn.close()
        return jsonify(
            error="invoices cannot be submitted for this purchase order"
                  " (status: %s)" % po["status"]), 400
    dup = conn.execute(
        "SELECT 1 FROM erp_vendor_portal_submissions WHERE po_id = ?"
        " AND lower(vendor_invoice_number) = lower(?) AND status != 'rejected'",
        (po["id"], inv)).fetchone()
    if dup:
        conn.close()
        return jsonify(
            error="an invoice with this number was already submitted"
                  " for this purchase order"), 400
    vendor = conn.execute(
        "SELECT * FROM erp_vendors WHERE id = ?", (po["vendor_id"],)).fetchone()
    desc = "Vendor invoice %s — %s (portal submission)" % (inv, po["po_number"])
    lines, total, line_error = _acct_validate_bill_lines(
        conn, [{"description": desc, "amount_cents": amount}])
    if line_error:
        conn.close()
        return jsonify(error=line_error), 400
    today = datetime.now(timezone.utc).date().isoformat()
    now = datetime.now(timezone.utc).isoformat()
    # Draft bill: status 'draft', source 'portal', NO journal entry,
    # balance 0 -- it owes nothing and touches no ledger total until
    # an admin approves it. The line posts to the default expense
    # account (6900 Other Expenses) unless the admin picks another
    # account at approval.
    cur = conn.execute(
        "INSERT INTO erp_acct_bills (vendor_id, vendor_name, date, due_date,"
        " lines, total_cents, balance_cents, status, journal_entry_id,"
        " qb_id, source, created_at)"
        " VALUES (?, ?, ?, ?, ?, ?, 0, 'draft', NULL, NULL, 'portal', ?)",
        (po["vendor_id"], vendor["name"] if vendor else "", today, today,
         json.dumps(lines), total, now))
    bill_id = cur.lastrowid
    cur = conn.execute(
        "INSERT INTO erp_vendor_portal_submissions (po_id, token_id,"
        " vendor_invoice_number, amount_cents, note, status, bill_id,"
        " reviewed_by, reviewed_at, created_at)"
        " VALUES (?, ?, ?, ?, ?, 'submitted', ?, '', '', ?)",
        (po["id"], trow["id"], inv, amount, note, bill_id, now))
    sub_id = cur.lastrowid
    _portal_touch_token(conn, trow["id"])
    _acct_audit(conn, "vendor-portal", "bill.portal_submit", "bill", bill_id,
                "#%d %s total %d draft (portal invoice %s for %s)"
                % (bill_id, vendor["name"] if vendor else "", total, inv,
                   po["po_number"]))
    conn.commit()
    sub = conn.execute(
        "SELECT * FROM erp_vendor_portal_submissions WHERE id = ?",
        (sub_id,)).fetchone()
    conn.close()
    return jsonify(submission=_portal_submission_public(sub),
                   bill_id=bill_id), 201


# ---------------- Public survey page (Dept 8, SOP 8.33) ----------------
# No login: anyone with a survey's link can answer it. The link key
# is a random token, not a sequential id, and an inactive survey
# answers 404 exactly like an unknown key -- no hint about what
# exists. Submissions are rate-limited per connection (100 per 15
# minutes, a spam guard, not a per-person limit). Nothing is emailed:
# the admin shares the link. Public submissions are not written to
# the staff audit log -- the response row itself is the record.
_SURVEY_NOT_FOUND = {"error": "survey not found"}


def _mkt_survey_public_dict(conn, survey):
    questions = [_mkt_survey_question_dict(r) for r in conn.execute(
        "SELECT * FROM erp_mkt_survey_questions WHERE survey_id = ?"
        " ORDER BY sort_order, id", (survey["id"],)).fetchall()]
    return {"survey": {"title": survey["title"],
                       "description": survey["description"] or ""},
            "questions": questions}


@app.get("/api/public/surveys/<key>")
def public_survey_get(key):
    conn = db()
    row = conn.execute(
        "SELECT * FROM erp_mkt_surveys WHERE public_key = ?",
        (key,)).fetchone()
    if not row or not row["active"]:
        conn.close()
        return jsonify(_SURVEY_NOT_FOUND), 404
    out = _mkt_survey_public_dict(conn, row)
    conn.close()
    return jsonify(out)


@app.post("/api/public/surveys/<key>/responses")
def public_survey_submit(key):
    err = _auth_throttle_check("survey-submit-ip", _client_ip(),
                               max_fails=100)
    if err:
        return err
    _auth_throttle_fail("survey-submit-ip", _client_ip())
    data = request.get_json(force=True) or {}
    conn = db()
    survey = conn.execute(
        "SELECT * FROM erp_mkt_surveys WHERE public_key = ?",
        (key,)).fetchone()
    if not survey or not survey["active"]:
        conn.close()
        return jsonify(_SURVEY_NOT_FOUND), 404
    respondent = data.get("respondent", "")
    if respondent is None:
        respondent = ""
    if not isinstance(respondent, str):
        conn.close()
        return jsonify(error="respondent must be text"), 400
    respondent = respondent.strip()
    if len(respondent) > 200:
        conn.close()
        return jsonify(
            error="respondent is too long (max 200 characters)"), 400
    labels = {}
    for field in ("customer_key", "order_ref"):
        v = data.get(field, "")
        if v is None:
            v = ""
        if not isinstance(v, str):
            conn.close()
            return jsonify(error="%s must be text" % field), 400
        v = v.strip()
        if len(v) > 200:
            conn.close()
            return jsonify(
                error="%s is too long (max 200 characters)" % field), 400
        labels[field] = v
    raw_answers = data.get("answers")
    if not isinstance(raw_answers, list):
        conn.close()
        return jsonify(error="answers must be a list"), 400
    questions = {r["id"]: r for r in conn.execute(
        "SELECT * FROM erp_mkt_survey_questions WHERE survey_id = ?",
        (survey["id"],)).fetchall()}
    seen = set()
    parsed = []
    for item in raw_answers:
        if not isinstance(item, dict):
            conn.close()
            return jsonify(error="each answer must be an object"), 400
        qid = item.get("question_id")
        if isinstance(qid, bool) or not isinstance(qid, int):
            conn.close()
            return jsonify(error="question_id must be a whole number"), 400
        if qid not in questions:
            conn.close()
            return jsonify(error="unknown question"), 400
        if qid in seen:
            conn.close()
            return jsonify(
                error="a question may be answered only once"), 400
        seen.add(qid)
        q = questions[qid]
        value = item.get("value")
        if q["question_type"] in ("nps", "rating"):
            label = ("NPS value" if q["question_type"] == "nps"
                     else "rating value")
            if isinstance(value, bool) or not isinstance(value, int):
                conn.close()
                return jsonify(
                    error="%s must be a whole number" % label), 400
            lo, hi = (0, 10) if q["question_type"] == "nps" else (1, 5)
            if value < lo or value > hi:
                conn.close()
                return jsonify(
                    error="%s must be a whole number %d-%d"
                    % (label, lo, hi)), 400
            parsed.append((qid, float(value), ""))
        else:
            if not isinstance(value, str):
                conn.close()
                return jsonify(error="a text answer must be text"), 400
            if len(value.strip()) > 2000:
                conn.close()
                return jsonify(
                    error="a text answer is too long"
                          " (max 2000 characters)"), 400
            parsed.append((qid, None, value.strip()))
    for qid, q in questions.items():
        if q["required"] and qid not in seen:
            conn.close()
            return jsonify(
                error="answer is required: %s" % q["question_text"]), 400
    now = datetime.now(timezone.utc).isoformat()
    cur = conn.execute(
        "INSERT INTO erp_mkt_survey_responses (survey_id, respondent,"
        " customer_key, order_ref, submitted_at, created_by, created_at)"
        " VALUES (?, ?, ?, ?, ?, 'public', ?)",
        (survey["id"], respondent, labels["customer_key"],
         labels["order_ref"], now, now))
    rid = cur.lastrowid
    for qid, vnum, vtext in parsed:
        conn.execute(
            "INSERT INTO erp_mkt_survey_answers (response_id, question_id,"
            " value_num, value_text) VALUES (?, ?, ?, ?)",
            (rid, qid, vnum, vtext))
    conn.commit()
    conn.close()
    return jsonify(ok=True, response_id=rid), 201


@app.get("/survey/<key>")
def survey_page(key):
    """Minimal public survey page: no ERP login, no sidebar. It reads
    the survey through the key-gated public API above and posts the
    response back through it, so the page itself never sees any other
    survey or any response. A bad link shows the same generic message
    as the API."""
    page = """<!DOCTYPE html>
<html><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Customer survey — Pop-A-Licious</title>
<style>body{font-family:Arial,sans-serif;max-width:640px;margin:40px auto;padding:0 16px;line-height:1.5;color:#1a1a1a}h1{font-size:20px}h2{font-size:16px;margin-top:28px}input,textarea,select{width:100%;box-sizing:border-box;padding:8px;margin:4px 0 12px}button{padding:9px 16px;margin-right:8px;cursor:pointer}.err{color:#9e1b32}.ok{color:#1e6b34}.muted{color:#666}</style>
</head><body>
<h1>Pop-A-Licious — customer survey</h1>
<p id="status" class="muted">Loading the survey…</p>
<div id="survey" style="display:none">
<h2 id="svTitle"></h2>
<p id="svDesc" class="muted"></p>
<p><label>Your name (optional)<br><input id="respondent" maxlength="200"></label></p>
<div id="questions"></div>
<p><button id="submitBtn" type="button">Submit my answers</button></p>
<p id="submitMsg"></p>
</div>
<div id="thanks" style="display:none">
<h2>Thank you!</h2>
<p>Your answers are in. We read every one.</p>
</div>
<script>
(function () {
  var key = decodeURIComponent(window.location.pathname.split("/").pop() || "");
  var api = "/api/public/surveys/" + encodeURIComponent(key);
  var questions = [];
  function show(el, msg, cls) { el.textContent = msg; el.className = cls || ""; }
  function load() {
    fetch(api).then(function (r) { return r.json().then(function (j) { return { ok: r.ok, j: j }; }); }).then(function (res) {
      if (!res.ok) { show(document.getElementById("status"), "This survey link is not valid, or the survey is closed. Ask Pop-A-Licious for a new link.", "err"); return; }
      document.getElementById("status").style.display = "none";
      document.getElementById("survey").style.display = "block";
      document.getElementById("svTitle").textContent = res.j.survey.title;
      document.getElementById("svDesc").textContent = res.j.survey.description || "";
      questions = res.j.questions || [];
      var box = document.getElementById("questions");
      box.innerHTML = "";
      if (!questions.length) {
        var none = document.createElement("p");
        none.className = "muted";
        none.textContent = "This survey has no questions yet — check back later.";
        box.appendChild(none);
      }
      questions.forEach(function (q) {
        var wrap = document.createElement("div");
        var lab = document.createElement("label");
        lab.textContent = q.question_text + (q.required ? " *" : "");
        wrap.appendChild(lab);
        if (q.question_type === "nps") {
          var hint = document.createElement("p");
          hint.className = "muted";
          hint.textContent = "0 = not at all likely, 10 = extremely likely.";
          wrap.appendChild(hint);
          var num = document.createElement("input");
          num.type = "number"; num.min = "0"; num.max = "10"; num.step = "1";
          num.id = "q-" + q.id;
          wrap.appendChild(num);
        } else if (q.question_type === "rating") {
          var sel = document.createElement("select");
          sel.id = "q-" + q.id;
          ["", "1", "2", "3", "4", "5"].forEach(function (v) {
            var opt = document.createElement("option");
            opt.value = v;
            opt.textContent = v === "" ? "Choose a rating…" : v + (v === "1" ? " (poor)" : v === "5" ? " (excellent)" : "");
            sel.appendChild(opt);
          });
          wrap.appendChild(sel);
        } else {
          var ta = document.createElement("textarea");
          ta.rows = 3; ta.maxLength = 2000;
          ta.id = "q-" + q.id;
          wrap.appendChild(ta);
        }
        box.appendChild(wrap);
      });
    }).catch(function () { show(document.getElementById("status"), "Could not load this survey. Try again.", "err"); });
  }
  document.getElementById("submitBtn").addEventListener("click", function () {
    var msg = document.getElementById("submitMsg");
    var answers = [];
    var bad = null;
    questions.forEach(function (q) {
      var el = document.getElementById("q-" + q.id);
      if (!el) return;
      var raw = (el.value || "").trim();
      if (q.question_type === "nps" || q.question_type === "rating") {
        if (raw === "") { if (q.required) bad = "Please answer: " + q.question_text; return; }
        var n = Number(raw);
        if (q.question_type === "nps" && (n < 0 || n > 10 || Math.floor(n) !== n)) { bad = "The recommendation score must be a whole number 0-10."; return; }
        if (q.question_type === "rating" && (n < 1 || n > 5 || Math.floor(n) !== n)) { bad = "The rating must be a whole number 1-5."; return; }
        answers.push({ question_id: q.id, value: n });
      } else {
        if (raw === "") { if (q.required) bad = "Please answer: " + q.question_text; return; }
        answers.push({ question_id: q.id, value: raw });
      }
    });
    if (bad) { show(msg, bad, "err"); return; }
    fetch(api + "/responses", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ respondent: document.getElementById("respondent").value, answers: answers }) })
      .then(function (r) { return r.json().then(function (j) { return { ok: r.ok, j: j }; }); })
      .then(function (res) {
        if (!res.ok) { show(msg, res.j.error || "Could not submit. Try again.", "err"); return; }
        document.getElementById("survey").style.display = "none";
        document.getElementById("thanks").style.display = "block";
      }).catch(function () { show(msg, "Could not submit. Try again.", "err"); });
  });
  load();
})();
</script>
</body></html>"""
    return page


@app.get("/sign/<token>")
def esignature_sign_page(token):
    """Minimal public signing page: no ERP login, no sidebar. It reads
    the agreement through the token-gated public API above and signs
    or declines through it, so the page itself never sees a token
    hash or any other agreement. A bad link shows the same generic
    message as the API. This is the ERP's own signing flow (typed
    name + explicit agreement), not a DocuSign page."""
    page = """<!DOCTYPE html>
<html><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Sign an agreement — Pop-A-Licious</title>
<style>body{font-family:Arial,sans-serif;max-width:640px;margin:40px auto;padding:0 16px;line-height:1.5;color:#1a1a1a}h1{font-size:20px}h2{font-size:16px;margin-top:28px}input,textarea{width:100%;box-sizing:border-box;padding:8px;margin:4px 0 12px}input[type=checkbox]{width:auto}button{padding:9px 16px;margin-right:8px;cursor:pointer}.err{color:#9e1b32}.ok{color:#1e6b34}.muted{color:#666}.doc{border:1px solid #ccc;padding:12px 16px;margin:16px 0}</style>
</head><body>
<h1>Pop-A-Licious — sign an agreement</h1>
<p id="status" class="muted">Loading your agreement…</p>
<div id="doc" style="display:none">
<div class="doc">
<h2 id="docTitle"></h2>
<p id="docMeta" class="muted"></p>
<p id="docNotes"></p>
<p id="docVersion" class="muted"></p>
</div>
<p><label>Your full name, typed as your signature<br><input id="typedName" maxlength="200"></label></p>
<p><label><input id="agreeBox" type="checkbox"> I agree to sign this agreement electronically, using my typed name above as my signature.</label></p>
<p><button id="signBtn" type="button">Sign this agreement</button></p>
<p id="signMsg"></p>
<h2>Decline</h2>
<p><label>Reason (optional)<br><textarea id="declineReason" rows="2" maxlength="2000"></textarea></label></p>
<p><button id="declineBtn" type="button">Decline to sign</button></p>
<p class="muted">This link opens only this agreement. It expires — ask Pop-A-Licious for a new link if it stops working. A signed agreement cannot be unsigned; if the agreement changes after you sign, Pop-A-Licious will send a new link for the new version.</p>
</div>
<div id="done" style="display:none">
<h2>Thank you — signed.</h2>
<p id="doneDetail"></p>
<p>Pop-A-Licious has the signed copy. You do not need to do anything else.</p>
</div>
<div id="declined" style="display:none">
<h2>Declined.</h2>
<p>Pop-A-Licious has been told you declined to sign. If that was a mistake, ask them for a new link.</p>
</div>
<script>
(function () {
  var token = decodeURIComponent(window.location.pathname.split("/").pop() || "");
  var api = "/api/public/sign/" + encodeURIComponent(token);
  function show(el, msg, cls) { el.textContent = msg; el.className = cls || ""; }
  function load() {
    fetch(api).then(function (r) { return r.json().then(function (j) { return { ok: r.ok, j: j }; }); }).then(function (res) {
      if (!res.ok) { show(document.getElementById("status"), "This signing link is not valid, or it has expired. Ask Pop-A-Licious for a new link.", "err"); return; }
      var req = res.j.request;
      var ag = res.j.agreement;
      if (req.status === "signed") {
        document.getElementById("status").style.display = "none";
        document.getElementById("done").style.display = "block";
        document.getElementById("doneDetail").textContent = "Signed by " + (req.signed_name || req.signer_name) + " on " + (req.signed_at || "").slice(0, 10) + ".";
        return;
      }
      if (req.status === "declined") {
        document.getElementById("status").style.display = "none";
        document.getElementById("declined").style.display = "block";
        return;
      }
      if (req.status === "expired") {
        show(document.getElementById("status"), "This signing link has expired. Ask Pop-A-Licious for a new link.", "err");
        return;
      }
      if (req.status === "cancelled") {
        show(document.getElementById("status"), "This signing request was cancelled by Pop-A-Licious. Ask them for a new link if the agreement still needs signing.", "err");
        return;
      }
      document.getElementById("status").style.display = "none";
      document.getElementById("doc").style.display = "block";
      document.getElementById("docTitle").textContent = ag.title;
      document.getElementById("docMeta").textContent = ag.counterparty + " · " + ag.type + (ag.start_date ? " · from " + ag.start_date : "") + (ag.end_date ? " · ends " + ag.end_date : "");
      document.getElementById("docNotes").textContent = ag.notes || "";
      document.getElementById("docVersion").textContent = "You are signing version " + req.document_version + " of this agreement. The signed copy is kept exactly as signed.";
    }).catch(function () { show(document.getElementById("status"), "Could not load this agreement. Try again.", "err"); });
  }
  document.getElementById("signBtn").addEventListener("click", function () {
    var msg = document.getElementById("signMsg");
    var name = (document.getElementById("typedName").value || "").trim();
    if (!name) { show(msg, "Type your full name as your signature.", "err"); return; }
    if (!document.getElementById("agreeBox").checked) { show(msg, "Tick the agreement box to sign electronically.", "err"); return; }
    fetch(api + "/sign", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ typed_name: name, agree: true }) })
      .then(function (r) { return r.json().then(function (j) { return { ok: r.ok, j: j }; }); })
      .then(function (res) {
        if (!res.ok) { show(msg, res.j.error || "Could not sign. Try again.", "err"); return; }
        document.getElementById("doc").style.display = "none";
        document.getElementById("done").style.display = "block";
        document.getElementById("doneDetail").textContent = "Signed by " + res.j.request.signed_name + " on " + (res.j.request.signed_at || "").slice(0, 10) + ".";
      }).catch(function () { show(msg, "Could not sign. Try again.", "err"); });
  });
  document.getElementById("declineBtn").addEventListener("click", function () {
    var msg = document.getElementById("signMsg");
    fetch(api + "/decline", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ reason: document.getElementById("declineReason").value }) })
      .then(function (r) { return r.json().then(function (j) { return { ok: r.ok, j: j }; }); })
      .then(function (res) {
        if (!res.ok) { show(msg, res.j.error || "Could not decline. Try again.", "err"); return; }
        document.getElementById("doc").style.display = "none";
        document.getElementById("declined").style.display = "block";
      }).catch(function () { show(msg, "Could not decline. Try again.", "err"); });
  });
  load();
})();
</script>
</body></html>"""
    return page


