@app.post("/api/erp/production/equipment/<int:equipment_id>/update")
def prod_equipment_update(equipment_id):
    """Edit production equipment. Fields fall back to the stored row.
    Retiring (active -> retired) is an update, never a delete -- the
    maintenance history stays."""
    actor, err = _erp_check_perm("batches.write")
    if err:
        return err
    data = request.get_json(force=True) or {}
    conn = db()
    row = _prod_equipment_row(conn, equipment_id)
    if not row:
        conn.close()
        return jsonify(error="equipment not found"), 404
    fields = _prod_equipment_validate(conn, data, current=dict(row))
    if isinstance(fields, tuple):
        conn.close()
        return fields
    now = datetime.now(timezone.utc).isoformat()
    conn.execute(
        "UPDATE erp_prod_equipment SET name = ?, location_id = ?,"
        " serial_no = ?, installed_date = ?, status = ?,"
        " batches_per_day = ?, changeover_minutes = ?,"
        " warranty_start_date = ?, warranty_end_date = ?,"
        " warranty_provider = ?, warranty_notes = ?,"
        " updated_by = ?, updated_at = ? WHERE id = ?",
        (fields["name"], fields["location_id"], fields["serial_no"],
         fields["installed_date"], fields["status"],
         fields["batches_per_day"], fields["changeover_minutes"],
         fields["warranty_start_date"], fields["warranty_end_date"],
         fields["warranty_provider"], fields["warranty_notes"],
         actor, now, equipment_id))
    # Wave 3 Ops 6: a write that touches either capacity field is
    # audited as production.equipment_capacity_updated; other edits
    # keep the existing updated/retired actions.
    capacity_touched = ("batches_per_day" in data
                        or "changeover_minutes" in data)
    # Wave 4 item 28: a write that touches a warranty field is
    # audited as production.equipment_warranty_updated (a write
    # touching both capacity and warranty keeps the capacity
    # action, as before).
    warranty_touched = ("warranty_start_date" in data
                        or "warranty_end_date" in data
                        or "warranty_provider" in data
                        or "warranty_notes" in data)
    if capacity_touched:
        action = "production.equipment_capacity_updated"
    elif warranty_touched:
        action = "production.equipment_warranty_updated"
    else:
        action = ("production.equipment_retired"
                  if row["status"] == "active" and fields["status"] == "retired"
                  else "production.equipment_updated")
    _erp_staff_audit(conn, actor, action, "prod_equipment",
                     equipment_id,
                     "%s production equipment %s"
                     % ("capacity updated" if capacity_touched
                        else "warranty updated" if warranty_touched
                        else "retired" if action.endswith("_retired")
                        else "updated", fields["name"]))
    out = _prod_equipment_row(conn, equipment_id)
    out = _prod_equipment_dict(conn, out)
    conn.commit()
    conn.close()
    return jsonify(equipment=out)


@app.delete("/api/erp/production/equipment/<int:equipment_id>")
def prod_equipment_delete(equipment_id):
    """Delete production equipment, permanently. Refused (409) while
    any PM schedule references it, or while any open maintenance job
    references it (jobs carry equipment_id directly, so open jobs
    still block after their schedule is deleted -- delete the
    schedules first, close the open jobs, then delete). Done jobs
    never block a delete: they are history, and deleting the
    equipment does not delete them."""
    actor, err = _erp_check_perm("batches.write")
    if err:
        return err
    conn = db()
    row = _prod_equipment_row(conn, equipment_id)
    if not row:
        conn.close()
        return jsonify(error="equipment not found"), 404
    scount = conn.execute(
        "SELECT COUNT(*) FROM erp_store_pm_schedules"
        " WHERE equipment_id = ?", (equipment_id,)).fetchone()[0]
    if scount:
        conn.close()
        return jsonify(error="cannot delete production equipment with"
                       " PM schedules (%d schedule(s) attached)" % scount
                       ), 409
    open_jobs = conn.execute(
        "SELECT COUNT(*) FROM erp_store_maintenance"
        " WHERE equipment_id = ? AND status != 'done'",
        (equipment_id,)).fetchone()[0]
    if open_jobs:
        conn.close()
        return jsonify(error="cannot delete production equipment with"
                       " open maintenance jobs (%d open job(s))" % open_jobs
                       ), 409
    conn.execute("DELETE FROM erp_prod_equipment WHERE id = ?",
                 (equipment_id,))
    _erp_staff_audit(conn, actor, "production.equipment_deleted",
                     "prod_equipment", equipment_id,
                     "deleted production equipment %s"
                     % (row["name"] or ""))
    conn.commit()
    conn.close()
    return jsonify(ok=True)


