@app.post("/api/erp/recipes/<int:recipe_id>/assign-barcode")
def erp_assign_recipe_barcode(recipe_id):
    """Assign the lowest free purchased house barcode to a recipe that
    has none (admin). Nov 23, 2026: the recovery path for a recipe that
    was created while the pool was empty (upc_status 'pool-exhausted'):
    buy more codes, run the intake (Dept 13), then call this — the
    recipe gets the lowest free code and its barcode picture, exactly
    as it would have at creation. A recipe that already has a code is
    rejected (409) — codes are never replaced. With an empty pool the
    call succeeds (200) but assigns nothing and returns the exact
    pool-exhausted flag. Never generates a code."""
    actor, err = _require_erp_admin()
    if err:
        return err
    conn = db()
    recipe = _erp_get_recipe(conn, recipe_id)
    if not recipe or not recipe["active"]:
        conn.close()
        return jsonify(error="recipe not found"), 404
    if recipe["upc_a"]:
        conn.close()
        return jsonify(error="recipe already has a barcode"), 409
    now = datetime.now(timezone.utc).isoformat()
    code, status = _erp_assign_barcode_for_recipe(conn, recipe_id, now)
    conn.commit()
    row = conn.execute("SELECT * FROM erp_recipes WHERE id = ?",
                       (recipe_id,)).fetchone()
    conn.close()
    body = {"recipe": dict(row)}
    if status == "pool-exhausted":
        body["message"] = _ERP_BARCODE_POOL_EXHAUSTED
    return jsonify(body), 200


@app.delete("/api/erp/recipes/<int:recipe_id>")
def erp_delete_recipe(recipe_id):
    """Delete a recipe (admin). Soft delete: it leaves the recipes list and
    can no longer be used for new batches, but batches already made keep
    their recipe lines and history."""
    actor, err = _require_erp_admin()
    if err:
        return err
    conn = db()
    recipe = _erp_get_recipe(conn, recipe_id)
    if not recipe or not recipe["active"]:
        conn.close()
        return jsonify(error="recipe not found"), 404
    conn.execute("UPDATE erp_recipes SET active = 0 WHERE id = ?", (recipe_id,))
    _erp_tombstone(conn, "recipe", recipe["name"], actor)
    conn.commit()
    conn.close()
    return jsonify(deleted=True)


@app.post("/api/erp/recipes/import")
def erp_import_recipes():
    """CSV import of recipes. Columns: recipe_name, batch_size_bags, sku,
    qty_per_batch, unit, notes. One row per recipe line; rows sharing a
    recipe_name belong to the same recipe (first batch_size_bags wins)."""
    import csv
    import io
    actor, err = _require_erp_admin()
    if err:
        return err
    data = request.get_json(force=True) or {}
    text = data.get("csv") or ""
    if not text.strip():
        return jsonify(error="csv text is required"), 400
    conn = db()
    reader = csv.DictReader(io.StringIO(text))
    grouped = {}
    order = []
    for n, row in enumerate(reader, 2):
        row = { (k or "").strip(): (v or "").strip() for k, v in row.items() }
        rname = row.get("recipe_name") or ""
        if not rname:
            conn.close()
            return jsonify(error="row %d: recipe_name is required" % n), 400
        try:
            batch_size = float(row.get("batch_size_bags") or 0)
        except (TypeError, ValueError):
            conn.close()
            return jsonify(error="row %d: batch_size_bags must be a number" % n), 400
        if batch_size <= 0:
            conn.close()
            return jsonify(error="row %d: batch_size_bags must be > 0" % n), 400
        item = conn.execute("SELECT * FROM erp_items WHERE sku = ?",
                            (row.get("sku") or "",)).fetchone()
        if not item or not item["active"]:
            conn.close()
            return jsonify(error="row %d: unknown sku '%s'" % (n, row.get("sku"))), 400
        qty = _erp_parse_qty(row.get("qty_per_batch"))
        if qty is None:
            conn.close()
            return jsonify(error="row %d: qty_per_batch must be a number or fraction (e.g. 1/2)" % n), 400
        if qty <= 0:
            conn.close()
            return jsonify(error="row %d: qty_per_batch must be > 0" % n), 400
        if rname not in grouped:
            grouped[rname] = {"batch_size_bags": batch_size,
                              "notes": row.get("notes") or "", "lines": []}
            order.append(rname)
        grouped[rname]["lines"].append({
            "item_id": item["id"], "qty_per_batch": qty,
            "unit": row.get("unit") or item["unit"] or "each", "notes": ""})
    if not grouped:
        conn.close()
        return jsonify(error="no recipe rows found"), 400
    now = datetime.now(timezone.utc).isoformat()
    created = 0
    created_ids = []
    for rname in order:
        g = grouped[rname]
        clean, err_msg = _erp_validate_recipe_lines(conn, g["lines"])
        if err_msg:
            conn.close()
            return jsonify(error="recipe '%s': %s" % (rname, err_msg)), 400
        cur = conn.execute(
            "INSERT INTO erp_recipes (name, batch_size_bags, version, active,"
            " notes, created_by, created_at) VALUES (?, ?, 1, 1, ?, ?, ?)",
            (rname, g["batch_size_bags"], g["notes"], actor, now))
        rid = cur.lastrowid
        for ln in clean:
            conn.execute(
                "INSERT INTO erp_recipe_lines (recipe_id, recipe_version, item_id,"
                " qty_per_batch, unit, notes) VALUES (?, 1, ?, ?, ?, ?)",
                (rid, ln["item_id"], ln["qty_per_batch"], ln["unit"], ln["notes"]))
        # Nov 23, 2026: imported recipes auto-assign too, lowest-first
        # in file order.
        _erp_assign_barcode_for_recipe(conn, rid, now)
        created += 1
        created_ids.append(rid)
    _erp_settings_audit(conn, actor, "import.recipes", "recipes", 0,
                        "Imported %d recipe(s) from CSV" % created)
    conn.commit()
    for rid in created_ids:
        _erp_apply_auto_serving_grams(conn, rid)
    conn.close()
    return jsonify(ok=True, imported=created)


# ---- Website-flavor staging (Nov 20, 2026; UPC rule revised Nov 23) ----
# A new recipe confirmed for the website ("Add this flavor to the website?"
# YES). The ERP records the pending request only — Railway cannot write
# gs1-qr-data.csv, flavors.json, or the ERP map, so the workspace generator
# finishes QR/CSV/map from the exported JSON. UPC rules (user-confirmed,
# revised Nov 23): EVERY new recipe auto-assigns the LOWEST FREE HOUSE
# code (602581 only) at creation — never auto-assign from other prefixes;
# an already-recorded code is kept, never re-assigned; assignment does
# NOT add the flavor to the website and does NOT imply label approval
# (the health-department gate below still applies). The backend
# re-validates format + check digit + duplicates within its own table;
# the generator re-checks all four sources (CSV, flavors.json/build_gs1.py,
# ERP map, Faire map) before writing.
def _erp_upc_check_digit(upc11):
    """UPC-A check digit for the first 11 digits (same as build_gs1.py)."""
    d = [int(c) for c in upc11]
    s = sum(d[i] for i in range(0, 11, 2)) * 3 + sum(d[i] for i in range(1, 11, 2))
    return (10 - s % 10) % 10


def _erp_website_flavor_slug(name):
    ascii_s = unicodedata.normalize("NFKD", str(name or "")).encode(
        "ascii", "ignore").decode("ascii")
    slug = re.sub(r"[^a-z0-9]+", "-", ascii_s.lower()).strip("-")
    return slug or "flavor"


def _erp_website_flavor_row(row, with_photo=False):
    d = dict(row)
    if not with_photo:
        d["photo_bytes"] = len(d.pop("photo_data") or "")
        d.pop("photo_data", None)
    return d


@app.post("/api/erp/website-flavors")
def erp_create_website_flavor():
    actor, err = _erp_check_perm("recipes.write")
    if err:
        return err
    data = request.get_json(force=True) or {}
    flavor_name = (data.get("flavor_name") or "").strip()
    if not flavor_name:
        return jsonify(error="flavor_name is required"), 400
    category = (data.get("category") or "").strip()
    if category not in ("sweet", "savory", "cheesy"):
        return jsonify(error="category must be sweet, savory, or cheesy"), 400
    description = (data.get("description") or "").strip()
    if not description:
        return jsonify(error="description is required (never invent copy)"), 400
    photo_data = data.get("photo_data") or ""
    if not isinstance(photo_data, str) or not photo_data.startswith("data:image/"):
        return jsonify(error="bag photo is required (image upload)"), 400
    if len(photo_data) > 8000000:
        return jsonify(error="bag photo is too large (8 MB limit)"), 400
    upc = (data.get("upc_a") or "").strip()
    if len(upc) != 12 or not upc.isdigit():
        return jsonify(error="upc_a must be 12 digits"), 400
    if _erp_upc_check_digit(upc[:11]) != int(upc[-1]):
        return jsonify(error="upc_a check digit is invalid"), 400
    upc_source = (data.get("upc_source") or "").strip()
    if upc_source not in ("auto-assigned", "manual override", "existing code kept"):
        return jsonify(error="upc_source must be auto-assigned, manual override, "
                       "or existing code kept"), 400
    if upc_source == "auto-assigned" and not upc.startswith("602581"):
        return jsonify(error="auto-assigned UPCs must be house (602581) codes"), 400
    if (data.get("gtin_14") or "") != "00" + upc:
        return jsonify(error="gtin_14 must be 00 + upc_a"), 400
    if (data.get("digital_link") or "") != "https://pop-a-licious.com/01/" + "00" + upc:
        return jsonify(error="digital_link must be the GS1 Digital Link for the UPC"), 400
    # Health-department label gate (Nov 23, 2026): the flavor's current
    # recipe version must have its nutritional label approved before it
    # can be added to the website. The approval is recorded in the
    # recipe's Label settings by an admin (DJ/Matt).
    recipe_id = data.get("recipe_id")
    if not recipe_id:
        return jsonify(error="recipe_id is required — label approval cannot be verified without the recipe"), 400
    conn = db()
    recipe = _erp_get_recipe(conn, recipe_id)
    if not recipe or not recipe["active"]:
        conn.close()
        return jsonify(error="recipe not found"), 404
    if not _erp_recipe_label_approved(recipe):
        conn.close()
        return jsonify(error="nutritional label must be approved by the health department before this flavor can be added to the website (approve it in the recipe's Label settings)"), 400
    slug = _erp_website_flavor_slug(flavor_name)
    dup = conn.execute(
        "SELECT id FROM erp_website_flavor_requests WHERE flavor_name = ?"
        " AND status IN ('pending', 'staged')", (flavor_name,)).fetchone()
    if dup:
        conn.close()
        return jsonify(error="this flavor already has a staged website request"), 400
    dup_upc = conn.execute(
        "SELECT id FROM erp_website_flavor_requests WHERE upc_a = ?"
        " AND status IN ('pending', 'staged')", (upc,)).fetchone()
    if dup_upc:
        conn.close()
        return jsonify(error="this UPC is already staged for another flavor"), 400
    # Nov 23, 2026: a UPC auto-assigned to a recipe at creation belongs
    # to that recipe — staging it under a DIFFERENT recipe is rejected.
    # Staging a recipe's OWN code is allowed (id == this request's
    # recipe). Assignment alone never stages a flavor for the website.
    other_recipe = conn.execute(
        "SELECT id FROM erp_recipes WHERE upc_a = ? AND active = 1"
        " AND id != ?", (upc, recipe["id"])).fetchone()
    if other_recipe:
        conn.close()
        return jsonify(error="this UPC is already assigned to another recipe"), 400
    now = datetime.now(timezone.utc).isoformat()
    try:
        cur = conn.execute(
            "INSERT INTO erp_website_flavor_requests (recipe_id, flavor_name, slug,"
            " category, description, photo_data, photo_filename, upc_a, upc_source,"
            " gtin_14, digital_link, status, created_by, created_at,"
            " label_approved_version, recipe_version)"
            " VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'pending', ?, ?, ?, ?)",
            (data.get("recipe_id"), flavor_name, slug, category, description,
             photo_data, (data.get("photo_filename") or "").strip(), upc,
             upc_source, "00" + upc,
             "https://pop-a-licious.com/01/" + "00" + upc, actor, now,
             int(recipe["version"]), int(recipe["version"])))
        conn.commit()
    except Exception:
        conn.rollback()
        conn.close()
        return jsonify(error="this UPC is already staged for another flavor"), 400
    row = conn.execute("SELECT * FROM erp_website_flavor_requests WHERE id = ?",
                       (cur.lastrowid,)).fetchone()
    conn.close()
    return jsonify(request=_erp_website_flavor_row(row)), 201


