@app.get("/api/erp/orders/<source>/<int:order_id>")
def erp_order_detail(source, order_id):
    actor, err = _erp_check_perm("orders.read")
    if err:
        return err
    if source not in _ERP_ORDER_SOURCES:
        return jsonify(error="unknown source"), 404
    conn = db()
    if source == "wholesale":
        w = conn.execute("SELECT * FROM erp_wholesale_orders WHERE id = ?",
                         (order_id,)).fetchone()
        if not w:
            conn.close()
            return jsonify(error="order not found"), 404
        order = _erp_wholesale_order_brief(conn, w)
        order["lines"] = [dict(l) for l in conn.execute(
            "SELECT * FROM erp_wholesale_order_lines WHERE order_id = ? ORDER BY id",
            (order_id,)).fetchall()]
        acct = conn.execute("SELECT * FROM erp_wholesale_accounts WHERE id = ?",
                            (w["account_id"],)).fetchone()
        order["account"] = dict(acct) if acct else None
        order["notes"] = w["notes"]
        order["order_date"] = w["order_date"]
        addr_id = w["address_id"] if "address_id" in w.keys() else 0
        ship_addr = None
        if addr_id:
            arow = conn.execute("SELECT * FROM erp_wholesale_addresses WHERE id = ?",
                                (addr_id,)).fetchone()
            if arow:
                ship_addr = dict(arow)
        order["ship_address"] = ship_addr
        order["shippo_label_url"] = w["shippo_label_url"] if "shippo_label_url" in w.keys() else ""
        order["shippo_tracking_number"] = w["shippo_tracking_number"] if "shippo_tracking_number" in w.keys() else ""
        order["shippo_label_created_at"] = w["shippo_label_created_at"] if "shippo_label_created_at" in w.keys() else ""
        order["tracking_number"] = order["shippo_tracking_number"]
        order["shipping_address"] = acct["address"] if acct else ""
        qb_link = _qb_pushed(conn, "wholesale_order", order_id, "invoice")
        order["qb_invoice_id"] = qb_link["qb_id"] if qb_link else None
    else:
        order = _erp_online_order(conn, source, order_id)
        if not order:
            conn.close()
            return jsonify(error="order not found"), 404
        order["due_date"] = ""
        order["via_edi"] = False
        order["account_name"] = ""
        order["account"] = None
        order["lines"] = None
        order["notes"] = ""
        order["order_date"] = ""
    fulf = _erp_fulfillment_dict(conn, source, order_id)
    order["status"] = fulf["status"]
    order["fulfillment"] = fulf
    # BOPIS (SOP 5.33): pickup state of this order, or the empty shape --
    # no row means never a pickup order. Read-side is orders.read, like
    # the rest of this detail; writes are admin-only and gate-refused.
    order["pickup"] = _erp_pickup_dict(conn, source, order_id)
    # Drop-ship (SOP 5.34): the vendor shipment for this order, or the
    # empty shape -- no row means this order was never drop-shipped.
    # Read-side is orders.read, like the rest of this detail.
    order["drop_ship"] = _erp_drop_ship_for_order(conn, source, order_id)
    order["linked_batches"] = _erp_order_links(conn, source, order_id)
    # Retail customer RMA (Dept 8, SOP 8.27): the returns for this
    # order, if any -- retail only, so wholesale orders get [].
    if source in ("stripe", "paypal"):
        order["returns"] = [
            _mkt_return_dict(conn, r) for r in conn.execute(
                "SELECT * FROM erp_mkt_returns WHERE order_source = ?"
                " AND order_id = ? ORDER BY id DESC",
                (source, order_id)).fetchall()]
    else:
        order["returns"] = []
    conn.close()
    return jsonify(order=order)


def _erp_search_match(haystacks, words):
    """AND-match: every word must appear somewhere in the record's text."""
    hay = " ".join(h for h in haystacks if h).lower()
    return all(w in hay for w in words)


def _erp_search_rank(primary, number, words):
    """0 = a word exactly equals the record's number/SKU, 1 = the primary
    field starts with a word, 2 = plain substring match."""
    num = (number or "").lower().lstrip("#")
    for w in words:
        if w.lstrip("#") and w.lstrip("#") == num:
            return 0
    prim = (primary or "").lower()
    for w in words:
        if prim.startswith(w):
            return 1
    return 2


def _erp_search_money(cents):
    return "$%.2f" % ((cents or 0) / 100.0)


@app.get("/api/erp/search")
def erp_search():
    """Find-anything search for Poppy, the ERP chat bot (Nov 17, 2026).

    FIND-ONLY: keyword matching over the caller's own ERP data, no data
    changes, no computed answers, no external service. Each record type is
    queried only when the caller holds that type's read perm (checked with
    the same _erp_check_perm the list endpoint uses); a type the caller
    cannot read is silently omitted. SOPs are admin-only, like their list
    endpoint. Empty q (or under 2 chars) returns {results: []}.
    """
    _, err = _require_erp()
    if err:
        return err
    q_raw = (request.args.get("q") or "").strip()
    if len(q_raw) < 2:
        return jsonify(q=q_raw, results=[])
    try:
        limit = int(request.args.get("limit") or 5)
    except (TypeError, ValueError):
        limit = 5
    limit = max(1, min(limit, 10))
    words = q_raw.lower().split()
    results = []
    conn = db()

    def _add(rows):
        rows.sort(key=lambda r: (r[0], r[1]))
        for _, _, item in rows[:limit]:
            results.append(item)

    # --- orders: wholesale + website (stripe + captured paypal only) ---
    _, oerr = _erp_check_perm("orders.read")
    if oerr is None:
        fulf = {(f["order_source"], f["order_id"]): f["status"]
                for f in conn.execute("SELECT order_source, order_id, status"
                                      " FROM erp_order_fulfillment").fetchall()}
        found = []
        ws_lines = {}
        for l in conn.execute("SELECT order_id, flavor_name FROM erp_wholesale_order_lines").fetchall():
            ws_lines.setdefault(l["order_id"], []).append(l["flavor_name"])
        for w in conn.execute("SELECT * FROM erp_wholesale_orders ORDER BY id DESC").fetchall():
            brief = _erp_wholesale_order_brief(conn, w)
            brief["status"] = fulf.get(("wholesale", w["id"]), brief["status"])
            hay = [w["order_number"], brief["account_name"], brief["status"],
                   w["po_number"] if "po_number" in w.keys() else "",
                   " ".join(ws_lines.get(w["id"], []))]
            if not _erp_search_match(hay, words):
                continue
            found.append((_erp_search_rank(brief["account_name"], w["order_number"], words),
                          -w["id"],
                          {"type": "order", "id": w["id"],
                           "title": "%s — %s" % (w["order_number"], brief["account_name"] or "—"),
                           "subtitle": "Wholesale · %g bags · %s · %s" % (
                               brief["total_qty"], _erp_search_money(brief["total_cents"]),
                               brief["status"]),
                           "route": "#/orders",
                           "open": {"ordersPostMap": {"source": "wholesale", "id": w["id"]}}}))
        for source, table in (("stripe", "orders"), ("paypal", "paypal_orders")):
            if source == "stripe":
                rows = conn.execute(
                    "SELECT * FROM orders WHERE stripe_session_id NOT LIKE 'paypal:%'"
                    " ORDER BY id DESC").fetchall()
            else:
                rows = conn.execute(
                    "SELECT * FROM paypal_orders WHERE status = 'captured'"
                    " ORDER BY id DESC").fetchall()
            for r in rows:
                o = _erp_online_order(conn, source, r["id"])
                if not o:
                    continue
                o["status"] = fulf.get((source, r["id"]), "new")
                hay = [o["number"], o["customer_name"], o["email"], o["items_summary"]]
                if not _erp_search_match(hay, words):
                    continue
                who = o["customer_name"] or o["email"] or "—"
                found.append((_erp_search_rank(who, o["number"], words),
                              -r["id"],
                              {"type": "order", "id": r["id"],
                               "title": "%s — %s" % (o["number"], who),
                               "subtitle": "Website · %s · %s" % (
                                   _erp_search_money(o["total_cents"]), o["status"]),
                               "route": "#/orders",
                               "open": {"ordersPostMap": {"source": source, "id": r["id"]}}}))
        _add(found)

    # --- invoices ---
    _, aerr = _erp_check_perm("accounting.read")
    if aerr is None:
        found = []
        for r in conn.execute("SELECT * FROM erp_acct_invoices"
                              " ORDER BY date DESC, id DESC").fetchall():
            hay = ["#%d" % r["id"], str(r["id"]), r["customer_name"], r["status"]]
            if not _erp_search_match(hay, words):
                continue
            sub = "%s · %s" % (_erp_search_money(r["total_cents"]), r["status"])
            if r["due_date"]:
                sub += " · due %s" % r["due_date"]
            found.append((_erp_search_rank(r["customer_name"], "#%d" % r["id"], words),
                          -r["id"],
                          {"type": "invoice", "id": r["id"],
                           "title": "Invoice #%d — %s" % (r["id"], r["customer_name"]),
                           "subtitle": sub, "route": "#/accounting",
                           "open": {"acctView": "invoices", "highlight": "invoice-%d" % r["id"]}}))
        _add(found)
        # --- bills ---
        found = []
        for r in conn.execute("SELECT * FROM erp_acct_bills"
                              " ORDER BY date DESC, id DESC").fetchall():
            hay = ["#%d" % r["id"], str(r["id"]), r["vendor_name"], r["status"]]
            if not _erp_search_match(hay, words):
                continue
            sub = "%s · %s" % (_erp_search_money(r["total_cents"]), r["status"])
            if r["due_date"]:
                sub += " · due %s" % r["due_date"]
            found.append((_erp_search_rank(r["vendor_name"], "#%d" % r["id"], words),
                          -r["id"],
                          {"type": "bill", "id": r["id"],
                           "title": "Bill #%d — %s" % (r["id"], r["vendor_name"] or "—"),
                           "subtitle": sub, "route": "#/accounting",
                           "open": {"acctView": "bills", "highlight": "bill-%d" % r["id"]}}))
        _add(found)

    # --- vendors ---
    _, perr = _erp_check_perm("purchasing.read")
    if perr is None:
        found = []
        for r in conn.execute("SELECT * FROM erp_vendors WHERE active = 1"
                              " ORDER BY name").fetchall():
            hay = [r["name"], r["contact_name"], r["email"], r["phone"],
                   r["notes"], r["payment_terms"]]
            if not _erp_search_match(hay, words):
                continue
            sub = "Vendor"
            if r["payment_terms"]:
                sub += " · %s" % r["payment_terms"]
            if r["email"]:
                sub += " · %s" % r["email"]
            found.append((_erp_search_rank(r["name"], "", words), r["name"].lower(),
                          {"type": "vendor", "id": r["id"], "title": r["name"],
                           "subtitle": sub, "route": "#/purchasing",
                           "open": {"highlight": "vendor-%d" % r["id"]}}))
        _add(found)
        # --- purchase orders ---
        vendors = {v["id"]: v["name"] for v in conn.execute(
            "SELECT id, name FROM erp_vendors").fetchall()}
        po_totals = {t["po_id"]: t["total"] for t in conn.execute(
            "SELECT po_id, COALESCE(SUM(qty_ordered * unit_cost_cents), 0) AS total"
            " FROM erp_po_lines GROUP BY po_id").fetchall()}
        found = []
        for r in conn.execute("SELECT * FROM erp_purchase_orders"
                              " ORDER BY id DESC").fetchall():
            vname = vendors.get(r["vendor_id"], "")
            hay = [r["po_number"], vname, r["status"]]
            if not _erp_search_match(hay, words):
                continue
            found.append((_erp_search_rank(vname, r["po_number"], words),
                          -r["id"],
                          {"type": "purchase-order", "id": r["id"],
                           "title": "%s — %s" % (r["po_number"], vname or "—"),
                           "subtitle": "Purchase order · %s · %s" % (
                               r["status"], _erp_search_money(po_totals.get(r["id"], 0))),
                           "route": "#/purchasing",
                           "open": {"poPostMap": r["id"]}}))
        _add(found)

    # --- inventory items ---
    _, ierr = _erp_check_perm("inventory.read")
    if ierr is None:
        found = []
        for r in conn.execute("SELECT * FROM erp_items WHERE active = 1"
                              " ORDER BY type, name").fetchall():
            hay = [r["name"], r["sku"], r["type"]]
            if not _erp_search_match(hay, words):
                continue
            found.append((_erp_search_rank(r["name"], r["sku"], words), r["name"].lower(),
                          {"type": "item", "id": r["id"], "title": r["name"],
                           "subtitle": "Item · %s · %s" % (r["sku"], r["type"]),
                           "route": "#/inventory",
                           "open": {"itemPostMap": r["id"]}}))
        _add(found)

    # --- recipes ---
    _, rerr = _erp_check_perm("recipes.read")
    if rerr is None:
        found = []
        for r in conn.execute("SELECT * FROM erp_recipes WHERE active = 1"
                              " ORDER BY name").fetchall():
            if not _erp_search_match([r["name"]], words):
                continue
            found.append((_erp_search_rank(r["name"], "", words), r["name"].lower(),
                          {"type": "recipe", "id": r["id"], "title": r["name"],
                           "subtitle": "Recipe · %s bags per batch" % _erp_fmt_qty(r["batch_size_bags"]),
                           "route": "#/production",
                           "open": {"recipePostMap": r["id"]}}))
        _add(found)

    # --- wholesale accounts ---
    _, cerr = _erp_check_perm("accounts.read")
    if cerr is None:
        found = []
        for r in conn.execute("SELECT * FROM erp_wholesale_accounts"
                              " ORDER BY name").fetchall():
            hay = [r["name"], r["contact_name"], r["email"],
                   r["billing_name"] if "billing_name" in r.keys() else "",
                   r["billing_email"] if "billing_email" in r.keys() else ""]
            if not _erp_search_match(hay, words):
                continue
            sub = "Wholesale account"
            if r["contact_name"]:
                sub += " · %s" % r["contact_name"]
            if r["email"]:
                sub += " · %s" % r["email"]
            found.append((_erp_search_rank(r["name"], "", words), r["name"].lower(),
                          {"type": "account", "id": r["id"], "title": r["name"],
                           "subtitle": sub, "route": "#/orders",
                           "open": {"accountsPostMap": r["id"]}}))
        _add(found)

    # --- SOPs: admin only, like the SOP list endpoint ---
    _, serr = _require_erp_admin()
    if serr is None:
        found = []
        for r in conn.execute("SELECT * FROM erp_quality_sops"
                              " ORDER BY dept, position, id").fetchall():
            if not _erp_search_match([r["title"], r["body"]], words):
                continue
            d = _quality_sop_dict(r)
            found.append((_erp_search_rank(r["title"], "", words),
                          (r["dept"], r["position"], r["id"]),
                          {"type": "sop", "id": r["id"], "title": r["title"],
                           "subtitle": "Dept %d · %s" % (r["dept"], d["dept_name"]),
                           "route": "#/quality",
                           "open": {"sopPostMap": r["id"]}}))
        _add(found)

    conn.close()
    return jsonify(q=q_raw, results=results)


@app.post("/api/erp/orders/<source>/<int:order_id>/status")
def erp_order_set_status(source, order_id):
    actor, err = _erp_check_perm("orders.write")
    if err:
        return err
    if source not in _ERP_ORDER_SOURCES:
        return jsonify(error="unknown source"), 404
    data = request.get_json(force=True) or {}
    status = (data.get("status") or "").strip()
    note = (data.get("note") or "").strip()
    conn = db()
    if not _erp_order_brief(conn, source, order_id):
        conn.close()
        return jsonify(error="order not found"), 404
    if source == "wholesale" and status == "ready":
        # Phase 5: an order with a production checklist can't be marked ready
        # until every flavor is done.
        done, total = _erp_production_progress(conn, order_id)
        if total and done < total:
            conn.close()
            return jsonify(error="all %d flavors must be marked done first (%d of %d done)"
                           % (total, done, total)), 400
    err_msg = _erp_set_fulfillment(conn, source, order_id, status, actor, note)
    if err_msg:
        conn.close()
        return jsonify(error=err_msg), 400
    if source == "wholesale" and status in ("shipped", "picked_up"):
        conn.execute("UPDATE erp_wholesale_order_lines SET qty_shipped = qty_bags"
                     " WHERE order_id = ?", (order_id,))
    if source == "wholesale" and status == "in_production":
        # Phase 5: entering production generates the per-flavor checklist.
        _erp_ensure_production_lines(conn, order_id)
    conn.commit()
    conn.close()
    return jsonify(ok=True, status=status)


# ---------------- BOPIS: buy online, pickup in store — DORMANT ONLY ----------------
# Wave 3 §4.2 item 8, SOP 5.33. User gate (Nov 13, 2026): no pickup until
# a shop exists AND the user lifts the gate. Neither condition is met today
# (0 stores in erp_stores). The gate is a hardcoded server-side constant,
# NOT a settings toggle an admin could flip on: activation requires a code
# change (set BOPIS_ENABLED = True) plus the user's explicit lift of the
# gate. While False, the pickup endpoints below exist and are tested, but
# every state-changing call is refused 409 -- that refusal IS the gate
# working, not a bug. Checkout never offers pickup (see _compute_order),
# no customer-facing surface mentions it, and no order is a pickup order:
# every pickup field starts empty. The transition logic behind the gate is
# written out in full so activation is the constant flip plus frontend
# wiring, not a redesign.
BOPIS_ENABLED = False
_BOPIS_PICKUP_STATUSES = ("requested", "ready_for_pickup", "picked_up", "cancelled")
_BOPIS_GATE_ERROR = ("BOPIS (store pickup) is dormant: no shop exists and the user has not"
                     " lifted the Nov 13 gate. Pickup cannot be marked on any order.")


def _erp_pickup_dict(conn, source, order_id):
    """Pickup state of one order, or the empty (never-a-pickup-order) shape.

    Read through the Order hub detail endpoint, which is gated by the
    caller's own orders.read permission like the rest of the order.
    """
    out = {"enabled": BOPIS_ENABLED, "pickup_status": "", "pickup_store_id": None,
           "store_name": "", "pickup_ready_at": "", "picked_up_at": "",
           "picked_up_by": "", "updated_by": "", "updated_at": "", "note": ""}
    row = conn.execute(
        "SELECT * FROM erp_order_pickup WHERE order_source = ? AND order_id = ?",
        (source, order_id)).fetchone()
    if not row:
        return out
    out.update({"pickup_status": row["pickup_status"],
                "pickup_store_id": row["pickup_store_id"],
                "pickup_ready_at": row["pickup_ready_at"] or "",
                "picked_up_at": row["picked_up_at"] or "",
                "picked_up_by": row["picked_up_by"] or "",
                "updated_by": row["updated_by"] or "",
                "updated_at": row["updated_at"] or "",
                "note": row["note"] or ""})
    if row["pickup_store_id"]:
        s = conn.execute("SELECT name FROM erp_stores WHERE id = ?",
                         (row["pickup_store_id"],)).fetchone()
        out["store_name"] = s["name"] if s else ""
    return out


def _erp_bopis_pickup_transition(source, order_id, target):
    """Shared body for the three pickup endpoints. Admin-only; the dormant
    gate refuses with 409 before any row is written. The live transitions
    behind the gate: ready (no row, or a requested row, becomes
    ready_for_pickup), picked up (only from ready_for_pickup), cancel
    (from requested / ready_for_pickup, never after pickup)."""
    actor, err = _require_erp_admin()
    if err:
        return err
    if target not in _BOPIS_PICKUP_STATUSES:
        return jsonify(error="unknown pickup action"), 400
    if source not in _ERP_ORDER_SOURCES:
        return jsonify(error="unknown source"), 404
    data = request.get_json(force=True) or {}
    note = (data.get("note") or "").strip()
    conn = db()
    if not _erp_order_brief(conn, source, order_id):
        conn.close()
        return jsonify(error="order not found"), 404
    if not BOPIS_ENABLED:
        conn.close()
        return jsonify(error=_BOPIS_GATE_ERROR), 409
    now = datetime.now(timezone.utc).isoformat()
    row = conn.execute(
        "SELECT * FROM erp_order_pickup WHERE order_source = ? AND order_id = ?",
        (source, order_id)).fetchone()
    current = row["pickup_status"] if row else ""
    if target == "ready_for_pickup":
        if current not in ("", "requested"):
            conn.close()
            return jsonify(error="order pickup is already %s" % current), 400
        store_id = None
        if data.get("pickup_store_id") is not None:
            try:
                store_id = int(data.get("pickup_store_id"))
            except (TypeError, ValueError):
                conn.close()
                return jsonify(error="pickup_store_id must be a store id"), 400
            if not conn.execute("SELECT 1 FROM erp_stores WHERE id = ?",
                                (store_id,)).fetchone():
                conn.close()
                return jsonify(error="unknown pickup store"), 400
        elif row:
            store_id = row["pickup_store_id"]
        if row:
            conn.execute(
                "UPDATE erp_order_pickup SET pickup_status = ?, pickup_store_id = ?,"
                " pickup_ready_at = ?, updated_by = ?, updated_at = ?, note = ?"
                " WHERE id = ?",
                (target, store_id, now, actor, now, note, row["id"]))
        else:
            conn.execute(
                "INSERT INTO erp_order_pickup (order_source, order_id, pickup_store_id,"
                " pickup_status, pickup_ready_at, updated_by, updated_at, note)"
                " VALUES (?, ?, ?, ?, ?, ?, ?, ?)",
                (source, order_id, store_id, target, now, actor, now, note))
    elif target == "picked_up":
        if current != "ready_for_pickup":
            conn.close()
            return jsonify(error="order is not ready for pickup"), 400
        picked_up_by = (data.get("picked_up_by") or "").strip() or actor
        conn.execute(
            "UPDATE erp_order_pickup SET pickup_status = ?, picked_up_at = ?,"
            " picked_up_by = ?, updated_by = ?, updated_at = ?, note = ? WHERE id = ?",
            (target, now, picked_up_by, actor, now, note, row["id"]))
    elif target == "cancelled":
        if current not in ("requested", "ready_for_pickup"):
            conn.close()
            return jsonify(error="order pickup cannot be cancelled from %s"
                           % (current or "no pickup")), 400
        conn.execute(
            "UPDATE erp_order_pickup SET pickup_status = ?, updated_by = ?,"
            " updated_at = ?, note = ? WHERE id = ?",
            (target, actor, now, note, row["id"]))
    conn.commit()
    out = _erp_pickup_dict(conn, source, order_id)
    conn.close()
    return jsonify(ok=True, pickup=out)


@app.post("/api/erp/orders/<source>/<int:order_id>/pickup/ready")
def erp_order_pickup_ready(source, order_id):
    """Mark an order ready for store pickup. Dormant: refused 409 (SOP 5.33)."""
    return _erp_bopis_pickup_transition(source, order_id, "ready_for_pickup")


@app.post("/api/erp/orders/<source>/<int:order_id>/pickup/picked-up")
def erp_order_pickup_picked_up(source, order_id):
    """Mark a ready order picked up. Dormant: refused 409 (SOP 5.33)."""
    return _erp_bopis_pickup_transition(source, order_id, "picked_up")


@app.post("/api/erp/orders/<source>/<int:order_id>/pickup/cancel")
def erp_order_pickup_cancel(source, order_id):
    """Cancel a pickup. Dormant: refused 409 (SOP 5.33)."""
    return _erp_bopis_pickup_transition(source, order_id, "cancelled")


# ---------------- Drop-ship handling (Wave 3 §4.2 item 9, SOP 5.34) ----------------
# A vendor ships directly to the buyer: the company never stocks the
# goods, so receiving a drop-ship PO into stock is refused outright
# (see erp_po_receive) and no Shippo label is ever created for one --
# the vendor ships on their own label. One shipment row per drop-ship
# PO at most (a PO fulfills exactly one buyer order, in one shipment),
# keyed by po_id. Status runs ordered -> vendor_confirmed -> shipped
# -> delivered. Marking shipped also marks the PO received (lines are
# marked received for PO / bill matching only -- no ledger movement,
# no lot, no average-cost change) and the buyer order shipped in the
# Order hub, which makes that order undeletable: the shipment is
# history from that point. Delivering records the delivery here only --
# there is no "delivered" fulfillment status.
_DROP_SHIP_STATUSES = ("ordered", "vendor_confirmed", "shipped", "delivered")


def _erp_drop_ship_dict(conn, po_id):
    """Shipment state of one PO, or the empty (never-a-drop-ship-PO) shape.

    Read through the PO detail endpoint, which is gated by the caller's
    own purchasing.read permission like the rest of the PO.
    """
    out = {"po_id": po_id, "order_source": "", "order_id": None,
           "order_number": "", "vendor_name": "", "status": "",
           "carrier": "", "tracking_number": "", "shipped_date": "",
           "delivered_date": "", "note": "", "created_by": "",
           "updated_by": "", "created_at": "", "updated_at": "",
           "ship_to_address": ""}
    row = conn.execute(
        "SELECT * FROM erp_drop_ship_shipments WHERE po_id = ?",
        (po_id,)).fetchone()
    if not row:
        return out
    out.update({"order_source": row["order_source"],
                "order_id": row["order_id"],
                "status": row["status"],
                "carrier": row["carrier"] or "",
                "tracking_number": row["tracking_number"] or "",
                "shipped_date": row["shipped_date"] or "",
                "delivered_date": row["delivered_date"] or "",
                "note": row["note"] or "",
                "created_by": row["created_by"] or "",
                "updated_by": row["updated_by"] or "",
                "created_at": row["created_at"] or "",
                "updated_at": row["updated_at"] or ""})
    po = conn.execute(
        "SELECT vendor_id FROM erp_purchase_orders WHERE id = ?",
        (po_id,)).fetchone()
    if po:
        v = conn.execute("SELECT name FROM erp_vendors WHERE id = ?",
                         (po["vendor_id"],)).fetchone()
        out["vendor_name"] = v["name"] if v else ""
    brief = _erp_order_brief(conn, row["order_source"], row["order_id"])
    out["order_number"] = brief["number"] if brief else ""
    # The buyer's address the vendor ships to (from the linked order).
    out["ship_to_address"] = _erp_drop_ship_ship_to(
        conn, row["order_source"], row["order_id"])
    return out


def _erp_drop_ship_for_order(conn, source, order_id):
    """Shipment state of one buyer order, or the empty shape.

    Read through the Order hub detail endpoint, which is gated by the
    caller's own orders.read permission like the rest of the order. No
    row means this order was never drop-shipped.
    """
    out = {"po_id": None, "po_number": "", "vendor_name": "", "status": "",
           "carrier": "", "tracking_number": "", "shipped_date": "",
           "delivered_date": "", "note": "", "created_by": "",
           "updated_by": "", "created_at": "", "updated_at": ""}
    row = conn.execute(
        "SELECT * FROM erp_drop_ship_shipments"
        " WHERE order_source = ? AND order_id = ? ORDER BY id DESC LIMIT 1",
        (source, order_id)).fetchone()
    if not row:
        return out
    out.update({"po_id": row["po_id"], "status": row["status"],
                "carrier": row["carrier"] or "",
                "tracking_number": row["tracking_number"] or "",
                "shipped_date": row["shipped_date"] or "",
                "delivered_date": row["delivered_date"] or "",
                "note": row["note"] or "",
                "created_by": row["created_by"] or "",
                "updated_by": row["updated_by"] or "",
                "created_at": row["created_at"] or "",
                "updated_at": row["updated_at"] or ""})
    po = conn.execute(
        "SELECT po_number, vendor_id FROM erp_purchase_orders WHERE id = ?",
        (row["po_id"],)).fetchone()
    if po:
        out["po_number"] = po["po_number"] or ""
        v = conn.execute("SELECT name FROM erp_vendors WHERE id = ?",
                         (po["vendor_id"],)).fetchone()
        out["vendor_name"] = v["name"] if v else ""
    return out


def _erp_drop_ship_transition(po_id, target):
    """Shared body for the drop-ship shipment endpoints. purchasing.write
    (the PO-side permission -- recording a vendor's notice is operational,
    like receiving); the shipment DELETE below is admin-only instead,
    like every other delete. Transitions: confirm (ordered only), ship
    (ordered / vendor_confirmed -- needs carrier + tracking from the
    vendor's notice, shipped date defaults to today), deliver (shipped
    only). Shipping marks the PO received and the buyer order shipped;
    delivering records the delivery on the shipment only."""
    actor, err = _erp_check_perm("purchasing.write")
    if err:
        return err
    if target not in _DROP_SHIP_STATUSES:
        return jsonify(error="unknown drop-ship action"), 400
    data = request.get_json(force=True) or {}
    note = (data.get("note") or "").strip()
    conn = db()
    po = conn.execute(
        "SELECT * FROM erp_purchase_orders WHERE id = ?", (po_id,)).fetchone()
    if not po:
        conn.close()
        return jsonify(error="purchase order not found"), 404
    if not _erp_po_is_drop_ship(po):
        conn.close()
        return jsonify(error="not a drop-ship purchase order"), 400
    row = conn.execute(
        "SELECT * FROM erp_drop_ship_shipments WHERE po_id = ?",
        (po_id,)).fetchone()
    if not row:
        conn.close()
        return jsonify(
            error="purchase order must be sent before the shipment can move"), 400
    current = row["status"]
    now = datetime.now(timezone.utc).isoformat()
    today = now[:10]
    if target == "vendor_confirmed":
        if current != "ordered":
            conn.close()
            return jsonify(
                error="drop-ship shipment is already %s" % current), 400
        conn.execute(
            "UPDATE erp_drop_ship_shipments SET status = ?, updated_by = ?,"
            " updated_at = ?, note = ? WHERE id = ?",
            (target, actor, now, note, row["id"]))
    elif target == "shipped":
        if current not in ("ordered", "vendor_confirmed"):
            conn.close()
            return jsonify(
                error="drop-ship shipment is already %s" % current), 400
        carrier = (data.get("carrier") or "").strip()
        tracking = (data.get("tracking_number") or "").strip()
        shipped_date = (data.get("shipped_date") or "").strip() or today
        if not carrier or not tracking:
            conn.close()
            return jsonify(
                error="carrier and tracking_number are required -- they come"
                      " from the vendor's shipping notice"), 400
        conn.execute(
            "UPDATE erp_drop_ship_shipments SET status = ?, carrier = ?,"
            " tracking_number = ?, shipped_date = ?, updated_by = ?,"
            " updated_at = ?, note = ? WHERE id = ?",
            (target, carrier, tracking, shipped_date, actor, now, note,
             row["id"]))
        # The goods left the vendor: the PO is fulfilled. Lines are
        # marked received for PO / bill matching only -- this posts NO
        # ledger movement, NO lot and NO average-cost change (receiving
        # a drop-ship PO is refused for exactly that reason). The buyer
        # order is shipped in the Order hub, which also makes it
        # undeletable -- the shipment is history now.
        conn.execute(
            "UPDATE erp_po_lines SET qty_received = qty_ordered WHERE po_id = ?",
            (po_id,))
        conn.execute(
            "UPDATE erp_purchase_orders SET status = 'received' WHERE id = ?",
            (po_id,))
        _v = conn.execute("SELECT name FROM erp_vendors WHERE id = ?",
                          (po["vendor_id"],)).fetchone()
        _vname = _v["name"] if _v else ""
        _erp_set_fulfillment(conn, row["order_source"], row["order_id"],
                             "shipped", actor,
                             "Drop-shipped by %s -- %s %s"
                             % (_vname, carrier, tracking))
    elif target == "delivered":
        if current != "shipped":
            conn.close()
            return jsonify(
                error="drop-ship shipment is %s, not shipped"
                      % (current or "not started")), 400
        delivered_date = (data.get("delivered_date") or "").strip() or today
        conn.execute(
            "UPDATE erp_drop_ship_shipments SET status = ?, delivered_date = ?,"
            " updated_by = ?, updated_at = ?, note = ? WHERE id = ?",
            (target, delivered_date, actor, now, note, row["id"]))
    conn.commit()
    out = _erp_drop_ship_dict(conn, po_id)
    conn.close()
    return jsonify(ok=True, drop_ship=out)


@app.post("/api/erp/purchase-orders/<int:po_id>/drop-ship/confirm")
def erp_drop_ship_confirm(po_id):
    """Vendor confirmed the drop-ship PO (ordered -> vendor_confirmed)."""
    return _erp_drop_ship_transition(po_id, "vendor_confirmed")


@app.post("/api/erp/purchase-orders/<int:po_id>/drop-ship/ship")
def erp_drop_ship_ship(po_id):
    """Vendor shipped direct to the buyer: carrier + tracking + shipped
    date from the vendor's notice. No Shippo label, no stock posted."""
    return _erp_drop_ship_transition(po_id, "shipped")


@app.post("/api/erp/purchase-orders/<int:po_id>/drop-ship/deliver")
def erp_drop_ship_deliver(po_id):
    """Buyer received the drop-ship delivery (shipped -> delivered)."""
    return _erp_drop_ship_transition(po_id, "delivered")


@app.delete("/api/erp/purchase-orders/<int:po_id>/drop-ship")
def erp_drop_ship_delete(po_id):
    """Delete an UNSHIPPED drop-ship shipment record. Admin-only, like
    every other delete. A shipped / delivered shipment is history and
    cannot be deleted -- and its PO cannot be cancelled either, so the
    record cannot be dropped that way. An unshipped record is removed
    here, or with its PO's cancel."""
    actor, err = _require_erp_admin()
    if err:
        return err
    conn = db()
    po = conn.execute(
        "SELECT * FROM erp_purchase_orders WHERE id = ?", (po_id,)).fetchone()
    if not po:
        conn.close()
        return jsonify(error="purchase order not found"), 404
    if not _erp_po_is_drop_ship(po):
        conn.close()
        return jsonify(error="not a drop-ship purchase order"), 400
    row = conn.execute(
        "SELECT * FROM erp_drop_ship_shipments WHERE po_id = ?",
        (po_id,)).fetchone()
    if not row:
        conn.close()
        return jsonify(error="no drop-ship shipment for this purchase order"), 404
    if row["status"] in ("shipped", "delivered"):
        conn.close()
        return jsonify(
            error="a shipped drop-ship shipment is history and cannot be"
                  " deleted"), 400
    conn.execute(
        "DELETE FROM erp_drop_ship_shipments WHERE id = ?", (row["id"],))
    conn.commit()
    conn.close()
    return jsonify(ok=True, deleted={"po_id": po_id,
                                     "order_source": row["order_source"],
                                     "order_id": row["order_id"],
                                     "status": row["status"]})


@app.delete("/api/erp/orders/<source>/<int:order_id>")
def erp_delete_online_order(source, order_id):
    """Permanently delete an ONLINE (stripe/paypal) order record.

    Admin-only. For removing test orders that were never real. Refuses
    when the order has production batch links or has already shipped /
    been picked up. Fulfillment rows for the order are removed with it.
    Gift-card balances and promo redemptions are NOT touched — this only
    removes the order record, and the deleted row's attached codes are
    returned so the caller can see if anything was attached.
    """
    actor, err = _require_erp_admin()
    if err:
        return err
    if source not in ("stripe", "paypal"):
        return jsonify(error="only online orders can be deleted here"), 400
    conn = db()
    order = _erp_online_order(conn, source, order_id)
    if not order:
        conn.close()
        return jsonify(error="order not found"), 404
    linked = conn.execute(
        "SELECT COUNT(*) AS c FROM erp_batch_orders"
        " WHERE order_source = ? AND order_id = ?",
        (source, order_id)).fetchone()["c"]
    if linked:
        conn.close()
        return jsonify(error="order has production batch links"), 400
    fulf = _erp_fulfillment_dict(conn, source, order_id)
    if fulf["status"] in ("shipped", "picked_up"):
        conn.close()
        return jsonify(error="shipped / picked-up orders cannot be deleted"), 400
    table = "orders" if source == "stripe" else "paypal_orders"
    row = conn.execute(
        "SELECT * FROM %s WHERE id = ?" % table, (order_id,)).fetchone()
    conn.execute("DELETE FROM erp_order_fulfillment"
                 " WHERE order_source = ? AND order_id = ?", (source, order_id))
    conn.execute("DELETE FROM erp_order_pickup"
                 " WHERE order_source = ? AND order_id = ?", (source, order_id))
    # Drop-ship (SOP 5.34): an unshipped shipment row goes with its
    # deleted order, like the pickup row. A shipped order can never
    # reach here -- the delete above refuses shipped orders -- so a
    # shipped shipment record (history) is never deleted this way.
    conn.execute("DELETE FROM erp_drop_ship_shipments"
                 " WHERE order_source = ? AND order_id = ?", (source, order_id))
    conn.execute("DELETE FROM erp_fulfillment_history"
                 " WHERE order_source = ? AND order_id = ?", (source, order_id))
    conn.execute("DELETE FROM %s WHERE id = ?" % table, (order_id,))
    conn.commit()
    conn.close()
    return jsonify(deleted={
        "source": source, "id": order_id, "number": order["number"],
        "email": order["email"], "total_cents": order["total_cents"],
        "gift_card_code": (row["gift_card_code"] if "gift_card_code" in row.keys() else "") or "",
        "promo_code": (row["promo_code"] if "promo_code" in row.keys() else "") or "",
        "reward_code": (row["reward_code"] if "reward_code" in row.keys() else "") or "",
    })


# ---------------- Kit / bundle assembly (Wave 3 §4.2 item 10) ----------------
# Generic mechanism only: build multi-item kits from stock. This does
# NOT launch or price the Pop Lab kit (concept only, not approved,
# launched, or priced) -- no kit definition is seeded, no kit carries
# a price, and no Pop Lab kit is created here or anywhere else in the
# ERP. Reads follow batches.read (Production tab); every write is
# admin-only. Assembling N kits decrements each component's on-hand by
# N x qty-per-kit at one location and increments the output item's
# on-hand by N, posting one ledger line per component plus one for the
# output (movement_type kit_assembly_out / kit_assembly_in, ref_type
# kit_assembly, ref_id = the assembly row id). Disassembly reverses
# it (kit_disassembly_out / kit_disassembly_in). An assembly is
# refused (409) when any component lacks sufficient on-hand at the
# location, and a disassembly when the output on-hand is insufficient
# -- on-hand is never driven negative, and the refusal writes nothing.
# A kit may not contain its own output item, directly or through
# another kit (cycle refused, 400). Deleting a kit definition with
# assemblies recorded is refused (409) -- assemblies are history.


def _kit_get(conn, kit_id):
    try:
        kit_id = int(kit_id)
    except (TypeError, ValueError):
        return None
    return conn.execute(
        "SELECT * FROM erp_kit_definitions WHERE id = ?", (kit_id,)).fetchone()


def _kit_component_rows(conn, kit_id):
    return conn.execute(
        "SELECT c.*, i.sku, i.name AS item_name, i.unit, i.active AS item_active"
        " FROM erp_kit_components c"
        " JOIN erp_items i ON i.id = c.item_id"
        " WHERE c.kit_id = ? ORDER BY i.name", (kit_id,)).fetchall()


def _kit_would_cycle(conn, output_item_id, component_item_id, exclude_kit_id=None):
    """True when making component_item_id a component of a kit whose
    output is output_item_id would close a cycle: the component is
    itself the output of another kit, and that kit (transitively)
    consumes the output item. Walks kit-output -> components edges."""
    seen = set()
    stack = [component_item_id]
    while stack:
        cur = stack.pop()
        if cur == output_item_id:
            return True
        if cur in seen:
            continue
        seen.add(cur)
        rows = conn.execute(
            "SELECT id FROM erp_kit_definitions WHERE output_item_id = ?",
            (cur,)).fetchall()
        for r in rows:
            if exclude_kit_id is not None and r["id"] == exclude_kit_id:
                continue
            for comp in conn.execute(
                    "SELECT item_id FROM erp_kit_components WHERE kit_id = ?",
                    (r["id"],)).fetchall():
                stack.append(comp["item_id"])
    return False


def _kit_validate_components(conn, output_item_id, components, exclude_kit_id=None):
    """Validate a kit's component list. Returns (parsed, None) where
    parsed is [(item_row, qty_per_kit)], or (None, (resp, code))."""
    if not isinstance(components, list) or not components:
        return None, (jsonify(error="a kit needs at least one component"), 400)
    parsed = []
    seen = set()
    for comp in components:
        if not isinstance(comp, dict):
            return None, (jsonify(error="each component needs item_id and qty_per_kit"), 400)
        item = _erp_get_item(conn, comp.get("item_id"))
        if not item or not item["active"]:
            return None, (jsonify(error="component item_id is not a valid active item"), 400)
        try:
            qty = float(comp.get("qty_per_kit") or 0)
        except (TypeError, ValueError):
            return None, (jsonify(error="qty_per_kit must be a number"), 400)
        if qty <= 0:
            return None, (jsonify(error="qty_per_kit must be greater than zero"), 400)
        if item["id"] in seen:
            return None, (jsonify(error="component %s is listed twice" % item["sku"]), 400)
        seen.add(item["id"])
        if item["id"] == output_item_id:
            return None, (jsonify(error="a kit cannot contain its own output item (%s)" % item["sku"]), 400)
        if _kit_would_cycle(conn, output_item_id, item["id"], exclude_kit_id):
            return None, (jsonify(error="component %s would create a kit cycle" % item["sku"]), 400)
        parsed.append((item, qty))
    return parsed, None


def _kit_dict(conn, kit):
    d = dict(kit)
    out_item = _erp_get_item(conn, kit["output_item_id"])
    d["output_sku"] = out_item["sku"] if out_item else ""
    d["output_name"] = out_item["name"] if out_item else ""
    d["output_unit"] = out_item["unit"] if out_item else ""
    d["output_on_hand"] = _erp_on_hand(conn, kit["output_item_id"]) if out_item else 0
    d["output_active"] = bool(out_item["active"]) if out_item else False
    comps = []
    for c in _kit_component_rows(conn, kit["id"]):
        cd = dict(c)
        cd["on_hand"] = _erp_on_hand(conn, c["item_id"])
        cd["by_location"] = [
            {"location_id": r["location_id"], "location_code": r["code"],
             "on_hand": float(r["q"] or 0)}
            for r in conn.execute(
                "SELECT l.location_id, loc.code, SUM(l.qty_change) AS q"
                " FROM erp_stock_ledger l"
                " LEFT JOIN erp_locations loc ON loc.id = l.location_id"
                " WHERE l.item_id = ? GROUP BY l.location_id ORDER BY loc.code",
                (c["item_id"],)).fetchall()]
        comps.append(cd)
    d["components"] = comps
    return d


def _kit_assembly_dict(conn, row):
    d = dict(row)
    kit = _kit_get(conn, row["kit_id"])
    d["kit_name"] = kit["name"] if kit else ""
    loc = conn.execute(
        "SELECT code, name FROM erp_locations WHERE id = ?",
        (row["location_id"],)).fetchone()
    d["location_code"] = loc["code"] if loc else ""
    d["location_name"] = loc["name"] if loc else ""
    return d


@app.get("/api/erp/kits")
def erp_list_kits():
    actor, err = _erp_check_perm("batches.read")
    if err:
        return err
    conn = db()
    rows = conn.execute(
        "SELECT * FROM erp_kit_definitions ORDER BY name").fetchall()
    out = [_kit_dict(conn, r) for r in rows]
    conn.close()
    return jsonify(kits=out)


@app.post("/api/erp/kits")
def erp_create_kit():
    actor, err = _require_erp_admin()
    if err:
        return err
    data = request.get_json(force=True) or {}
    conn = db()
    name = (data.get("name") or "").strip()
    if not name:
        conn.close()
        return jsonify(error="name is required"), 400
    if len(name) > 200:
        conn.close()
        return jsonify(error="name must be 200 characters or fewer"), 400
    description = (data.get("description") or "")
    if not isinstance(description, str):
        description = str(description)
    description = description.strip()
    if len(description) > 2000:
        conn.close()
        return jsonify(error="description must be 2000 characters or fewer"), 400
    out_item = _erp_get_item(conn, data.get("output_item_id"))
    if not out_item or not out_item["active"]:
        conn.close()
        return jsonify(error="output_item_id is not a valid active item"), 400
    parsed, perr = _kit_validate_components(
        conn, out_item["id"], data.get("components"))
    if perr:
        conn.close()
        return perr
    now = datetime.now(timezone.utc).isoformat()
    cur = conn.execute(
        "INSERT INTO erp_kit_definitions (name, description, output_item_id,"
        " active, created_by, created_at, updated_by, updated_at)"
        " VALUES (?, ?, ?, 1, ?, ?, ?, ?)",
        (name, description, out_item["id"], actor, now, actor, now))
    kit_id = cur.lastrowid
    for item, qty in parsed:
        conn.execute(
            "INSERT INTO erp_kit_components (kit_id, item_id, qty_per_kit,"
            " created_by, created_at) VALUES (?, ?, ?, ?, ?)",
            (kit_id, item["id"], qty, actor, now))
    _erp_staff_audit(conn, actor, "production.kit_created", "kit", kit_id,
                     "created kit %s (output %s)" % (name, out_item["sku"]))
    row = _kit_get(conn, kit_id)
    out = _kit_dict(conn, row)
    conn.commit()
    conn.close()
    return jsonify(kit=out), 201


@app.get("/api/erp/kits/<int:kit_id>")
def erp_get_kit(kit_id):
    actor, err = _erp_check_perm("batches.read")
    if err:
        return err
    conn = db()
    kit = _kit_get(conn, kit_id)
    if not kit:
        conn.close()
        return jsonify(error="kit not found"), 404
    out = _kit_dict(conn, kit)
    out["assemblies"] = [_kit_assembly_dict(conn, r) for r in conn.execute(
        "SELECT * FROM erp_kit_assemblies WHERE kit_id = ?"
        " ORDER BY id DESC LIMIT 100", (kit_id,)).fetchall()]
    conn.close()
    return jsonify(kit=out)


@app.put("/api/erp/kits/<int:kit_id>")
def erp_update_kit(kit_id):
    actor, err = _require_erp_admin()
    if err:
        return err
    data = request.get_json(force=True) or {}
    conn = db()
    kit = _kit_get(conn, kit_id)
    if not kit:
        conn.close()
        return jsonify(error="kit not found"), 404
    name = kit["name"]
    if "name" in data:
        name = (data.get("name") or "").strip()
        if not name:
            conn.close()
            return jsonify(error="name is required"), 400
        if len(name) > 200:
            conn.close()
            return jsonify(error="name must be 200 characters or fewer"), 400
    description = kit["description"]
    if "description" in data:
        description = data.get("description") or ""
        if not isinstance(description, str):
            description = str(description)
        description = description.strip()
        if len(description) > 2000:
            conn.close()
            return jsonify(error="description must be 2000 characters or fewer"), 400
    output_item_id = kit["output_item_id"]
    if "output_item_id" in data:
        out_item = _erp_get_item(conn, data.get("output_item_id"))
        if not out_item or not out_item["active"]:
            conn.close()
            return jsonify(error="output_item_id is not a valid active item"), 400
        output_item_id = out_item["id"]
    active = kit["active"]
    if "active" in data:
        active = 1 if data.get("active") else 0
    parsed = None
    if "components" in data:
        parsed, perr = _kit_validate_components(
            conn, output_item_id, data.get("components"), exclude_kit_id=kit_id)
        if perr:
            conn.close()
            return perr
    elif output_item_id != kit["output_item_id"]:
        # Output changed but the component list did not: the existing
        # components must still be valid against the new output.
        existing = [{"item_id": c["item_id"], "qty_per_kit": c["qty_per_kit"]}
                    for c in _kit_component_rows(conn, kit_id)]
        parsed, perr = _kit_validate_components(
            conn, output_item_id, existing, exclude_kit_id=kit_id)
        if perr:
            conn.close()
            return perr
    now = datetime.now(timezone.utc).isoformat()
    conn.execute(
        "UPDATE erp_kit_definitions SET name = ?, description = ?,"
        " output_item_id = ?, active = ?, updated_by = ?, updated_at = ?"
        " WHERE id = ?",
        (name, description, output_item_id, active, actor, now, kit_id))
    if parsed is not None:
        conn.execute("DELETE FROM erp_kit_components WHERE kit_id = ?", (kit_id,))
        for item, qty in parsed:
            conn.execute(
                "INSERT INTO erp_kit_components (kit_id, item_id, qty_per_kit,"
                " created_by, created_at) VALUES (?, ?, ?, ?, ?)",
                (kit_id, item["id"], qty, actor, now))
    _erp_staff_audit(conn, actor, "production.kit_updated", "kit", kit_id,
                     "updated kit %s" % name)
    out = _kit_dict(conn, _kit_get(conn, kit_id))
    conn.commit()
    conn.close()
    return jsonify(kit=out)


@app.delete("/api/erp/kits/<int:kit_id>")
def erp_delete_kit(kit_id):
    actor, err = _require_erp_admin()
    if err:
        return err
    conn = db()
    kit = _kit_get(conn, kit_id)
    if not kit:
        conn.close()
        return jsonify(error="kit not found"), 404
    n = conn.execute(
        "SELECT COUNT(*) AS c FROM erp_kit_assemblies WHERE kit_id = ?",
        (kit_id,)).fetchone()["c"]
    if n:
        conn.close()
        return jsonify(error="kit has %d recorded assembl%s and cannot be"
                       " deleted -- assemblies are history"
                       % (n, "y" if n == 1 else "ies")), 409
    conn.execute("DELETE FROM erp_kit_components WHERE kit_id = ?", (kit_id,))
    conn.execute("DELETE FROM erp_kit_definitions WHERE id = ?", (kit_id,))
    _erp_staff_audit(conn, actor, "production.kit_deleted", "kit", kit_id,
                     "deleted kit %s" % kit["name"])
    conn.commit()
    conn.close()
    return jsonify(ok=True)


def _kit_run_movement(conn, kit, quantity, location, note, direction, actor):
    """Post the ledger lines for one assemble / disassemble run.
    Assumes stock was already validated (all-or-nothing, caller
    checks before writing). Returns (assembly_row_dict, None) or
    (None, (resp, code))."""
    comps = _kit_component_rows(conn, kit["id"])
    if not comps:
        return None, (jsonify(error="kit has no components"), 400)
    if direction == "assemble":
        for c in comps:
            need = float(quantity) * float(c["qty_per_kit"])
            have = _erp_on_hand(conn, c["item_id"], location["id"])
            if have + 1e-9 < need:
                return None, (jsonify(error="insufficient stock of %s at %s"
                               " (have %s %s, need %s %s)"
                               % (c["sku"], location["code"],
                                  _erp_fmt_qty(have), c["unit"],
                                  _erp_fmt_qty(need), c["unit"])), 409)
    else:
        have = _erp_on_hand(conn, kit["output_item_id"], location["id"])
        if have + 1e-9 < float(quantity):
            out_item = _erp_get_item(conn, kit["output_item_id"])
            return None, (jsonify(error="insufficient stock of %s at %s"
                           " (have %s %s, need %s %s)"
                           % (out_item["sku"] if out_item else "output",
                              location["code"], _erp_fmt_qty(have),
                              out_item["unit"] if out_item else "",
                              _erp_fmt_qty(float(quantity)),
                              out_item["unit"] if out_item else "")), 409)
    now = datetime.now(timezone.utc).isoformat()
    cur = conn.execute(
        "INSERT INTO erp_kit_assemblies (kit_id, direction, quantity,"
        " location_id, note, created_by, created_at)"
        " VALUES (?, ?, ?, ?, ?, ?, ?)",
        (kit["id"], direction, float(quantity), location["id"],
         note, actor, now))
    assembly_id = cur.lastrowid
    ref = str(assembly_id)
    # Component cost basis (informational, from real avg costs): the
    # output line carries the summed component cost per assembled kit.
    per_kit_cost = 0
    for c in comps:
        item = _erp_get_item(conn, c["item_id"])
        per_kit_cost += float(c["qty_per_kit"]) * int(item["avg_cost_cents"] or 0)
    if direction == "assemble":
        for c in comps:
            need = float(quantity) * float(c["qty_per_kit"])
            item = _erp_get_item(conn, c["item_id"])
            _erp_post_movement(conn, c["item_id"], location["id"], -need,
                               "kit_assembly_out", actor, ref_type="kit_assembly",
                               ref_id=ref,
                               unit_cost_cents=int(item["avg_cost_cents"] or 0),
                               note="Assembled %s x %s" % (_erp_fmt_qty(quantity), kit["name"]))
        _erp_post_movement(conn, kit["output_item_id"], location["id"],
                           float(quantity), "kit_assembly_in", actor,
                           ref_type="kit_assembly", ref_id=ref,
                           unit_cost_cents=int(round(per_kit_cost)),
                           note="Assembled %s x %s" % (_erp_fmt_qty(quantity), kit["name"]))
    else:
        _erp_post_movement(conn, kit["output_item_id"], location["id"],
                           -float(quantity), "kit_disassembly_out", actor,
                           ref_type="kit_assembly", ref_id=ref,
                           unit_cost_cents=int(round(per_kit_cost)),
                           note="Disassembled %s x %s" % (_erp_fmt_qty(quantity), kit["name"]))
        for c in comps:
            need = float(quantity) * float(c["qty_per_kit"])
            item = _erp_get_item(conn, c["item_id"])
            _erp_post_movement(conn, c["item_id"], location["id"], need,
                               "kit_disassembly_in", actor, ref_type="kit_assembly",
                               ref_id=ref,
                               unit_cost_cents=int(item["avg_cost_cents"] or 0),
                               note="Disassembled %s x %s" % (_erp_fmt_qty(quantity), kit["name"]))
    _erp_staff_audit(conn, actor, "production.kit_%s" % ("assembled" if direction == "assemble" else "disassembled"),
                     "kit", kit["id"],
                     "%s %s x %s at %s" % (direction, _erp_fmt_qty(quantity),
                                            kit["name"], location["code"]))
    row = conn.execute(
        "SELECT * FROM erp_kit_assemblies WHERE id = ?", (assembly_id,)).fetchone()
    return _kit_assembly_dict(conn, row), None


def _kit_run_request(kit_id, direction):
    actor, err = _require_erp_admin()
    if err:
        return err
    data = request.get_json(force=True) or {}
    conn = db()
    kit = _kit_get(conn, kit_id)
    if not kit:
        conn.close()
        return jsonify(error="kit not found"), 404
    if not kit["active"]:
        conn.close()
        return jsonify(error="kit is inactive"), 400
    try:
        quantity = float(data.get("quantity") or 0)
    except (TypeError, ValueError):
        conn.close()
        return jsonify(error="quantity must be a number"), 400
    if quantity <= 0:
        conn.close()
        return jsonify(error="quantity must be greater than zero"), 400
    loc = _erp_get_location(conn, data.get("location_id"))
    if not loc or not loc["active"]:
        conn.close()
        return jsonify(error="valid location_id is required"), 400
    note = data.get("note") or ""
    if not isinstance(note, str):
        note = str(note)
    note = note.strip()
    if len(note) > 500:
        conn.close()
        return jsonify(error="note must be 500 characters or fewer"), 400
    out_item = _erp_get_item(conn, kit["output_item_id"])
    if not out_item or not out_item["active"]:
        conn.close()
        return jsonify(error="kit output item is not active"), 400
    assembly, merr = _kit_run_movement(conn, kit, quantity, loc, note, direction, actor)
    if merr:
        conn.close()
        return merr
    out = _kit_dict(conn, kit)
    conn.commit()
    conn.close()
    return jsonify(assembly=assembly, kit=out)


@app.post("/api/erp/kits/<int:kit_id>/assemble")
def erp_kit_assemble(kit_id):
    return _kit_run_request(kit_id, "assemble")


@app.post("/api/erp/kits/<int:kit_id>/disassemble")
def erp_kit_disassemble(kit_id):
    return _kit_run_request(kit_id, "disassemble")


# ---------------- Work orders + per-step scrap (Wave 4 item 11) ----------------
# MES depth, design §3.10. The batch stays the production run record;
# a work order is the shop-floor execution record for that run: linked
# recipe, optional linked batch (never invented), optional operator (an
# existing erp_hr_employees row, or none -- one kettle, founders on the
# floor), planned quantity, start/stop times, status planned ->
# in_progress -> complete / cancelled. Recipes carry no step structure
# (ingredient lines only), so steps are admin-entered per work order,
# never invented from the recipe. Each step records input, good output,
# and scrap quantities; yield % is computed at read time, never stored.
# Scrap is a work-order record ONLY: no stock-ledger movement is posted
# for scrap -- there is no established scrap/shrinkage ledger path to
# reuse (shrinkage adjustments are a separate manual concept), so scrap
# never moves stock silently. Reads follow batches.read (Production
# tab); every write is admin-only, like kits. Deletes are permanent:
# a work order with steps recorded, or one already complete, is refused
# (409) -- its steps are history. SOP: Dept 4, "Run a work order and
# track yield and scrap step by step".
_WO_STATUSES = ("planned", "in_progress", "complete", "cancelled")
_WO_TRANSITIONS = {
    "planned": ("in_progress", "complete", "cancelled"),
    "in_progress": ("complete", "cancelled"),
    "complete": (),
    "cancelled": (),
}


def _wo_get(conn, wo_id):
    try:
        wo_id = int(wo_id)
    except (TypeError, ValueError):
        return None
    return conn.execute(
        "SELECT * FROM erp_work_orders WHERE id = ?", (wo_id,)).fetchone()


def _wo_step_rows(conn, wo_id):
    return conn.execute(
        "SELECT * FROM erp_work_order_steps WHERE work_order_id = ?"
        " ORDER BY step_no, id", (wo_id,)).fetchall()


def _wo_step_dict(conn, step):
    d = dict(step)
    if step["equipment_id"]:
        eq = conn.execute(
            "SELECT name FROM erp_prod_equipment WHERE id = ?",
            (step["equipment_id"],)).fetchone()
        d["equipment_name"] = eq["name"] if eq else ""
    else:
        d["equipment_name"] = ""
    inp = float(step["input_qty"] or 0)
    good = float(step["good_qty"] or 0)
    scrap = float(step["scrap_qty"] or 0)
    d["yield_pct"] = (good / inp * 100.0) if inp > 0 else None
    d["scrap_pct"] = (scrap / inp * 100.0) if inp > 0 else None
    return d


def _wo_yield_view(conn, wo_id):
    """Yield-loss view: per-step yield/scrap plus the run summary.
    Inputs are NOT summed across steps (step 2's input is step 1's
    output -- summing would double-count), so the summary uses the
    first step's input, the last step's good output, and total scrap."""
    steps = [_wo_step_dict(conn, s) for s in _wo_step_rows(conn, wo_id)]
    total_scrap = sum(float(s["scrap_qty"] or 0) for s in steps)
    first_input = float(steps[0]["input_qty"] or 0) if steps else None
    last_good = float(steps[-1]["good_qty"] or 0) if steps else None
    overall = None
    if steps and first_input is not None and first_input > 0:
        overall = last_good / first_input * 100.0
    return {
        "steps": steps,
        "step_count": len(steps),
        "first_step_input_qty": first_input,
        "last_step_good_qty": last_good,
        "total_scrap_qty": total_scrap,
        "overall_yield_pct": overall,
    }


def _wo_dict(conn, wo):
    d = dict(wo)
    recipe = _erp_get_recipe(conn, wo["recipe_id"])
    d["recipe_name"] = recipe["name"] if recipe else ""
    d["recipe_active"] = bool(recipe["active"]) if recipe else False
    if wo["batch_id"]:
        batch = _erp_get_batch(conn, wo["batch_id"])
        d["batch_number"] = batch["batch_number"] if batch else ""
        d["batch_status"] = batch["status"] if batch else ""
    else:
        d["batch_number"] = ""
        d["batch_status"] = ""
    if wo["operator_employee_id"]:
        op = conn.execute(
            "SELECT name, email, active FROM erp_hr_employees WHERE id = ?",
            (wo["operator_employee_id"],)).fetchone()
        d["operator_name"] = op["name"] if op else ""
        d["operator_email"] = op["email"] if op else ""
        d["operator_active"] = bool(op["active"]) if op else False
    else:
        d["operator_name"] = ""
        d["operator_email"] = ""
        d["operator_active"] = False
    yv = _wo_yield_view(conn, wo["id"])
    d["steps"] = yv["steps"]
    d["step_count"] = yv["step_count"]
    d["total_scrap_qty"] = yv["total_scrap_qty"]
    d["overall_yield_pct"] = yv["overall_yield_pct"]
    return d


def _wo_validate_step(conn, data):
    """Validate one step payload. Returns (parsed, None) where parsed
    is a dict of clean fields, or (None, (resp, code))."""
    if not isinstance(data, dict):
        return None, (jsonify(error="each step needs a name and quantities"), 400)
    name = (data.get("name") or "").strip() if isinstance(
        data.get("name"), str) else ""
    if not name:
        return None, (jsonify(error="step name is required"), 400)
    if len(name) > 200:
        return None, (jsonify(error="step name must be 200 characters or fewer"), 400)
    equipment_id = None
    if data.get("equipment_id") not in (None, "", 0):
        try:
            equipment_id = int(data.get("equipment_id"))
        except (TypeError, ValueError):
            return None, (jsonify(error="equipment_id must be a number"), 400)
        eq = conn.execute(
            "SELECT id FROM erp_prod_equipment WHERE id = ?",
            (equipment_id,)).fetchone()
        if not eq:
            return None, (jsonify(error="equipment_id is not a valid equipment row"), 400)
    qtys = {}
    for key in ("input_qty", "good_qty", "scrap_qty"):
        try:
            qtys[key] = float(data.get(key) or 0)
        except (TypeError, ValueError):
            return None, (jsonify(error="%s must be a number" % key), 400)
        if qtys[key] < 0:
            return None, (jsonify(error="%s cannot be negative" % key), 400)
    reason = data.get("scrap_reason") or ""
    if not isinstance(reason, str):
        reason = str(reason)
    reason = reason.strip()
    if len(reason) > 500:
        return None, (jsonify(error="scrap_reason must be 500 characters or fewer"), 400)
    if qtys["scrap_qty"] > 0 and not reason:
        return None, (jsonify(
            error="a scrap reason is required on any step with scrap greater than zero"), 400)
    return {"name": name, "equipment_id": equipment_id,
            "input_qty": qtys["input_qty"], "good_qty": qtys["good_qty"],
            "scrap_qty": qtys["scrap_qty"], "scrap_reason": reason}, None


def _wo_validate_refs(conn, data, recipe_id):
    """Validate the recipe / batch / operator references for a work
    order. Returns (refs, None) with clean ids, or (None, (resp, code)).
    recipe_id is the already-validated recipe row id."""
    batch_id = None
    if data.get("batch_id") not in (None, "", 0):
        try:
            batch_id = int(data.get("batch_id"))
        except (TypeError, ValueError):
            return None, (jsonify(error="batch_id must be a number"), 400)
        batch = _erp_get_batch(conn, batch_id)
        if not batch:
            return None, (jsonify(error="batch_id is not a valid batch"), 400)
        if int(batch["recipe_id"]) != int(recipe_id):
            return None, (jsonify(
                error="batch %s belongs to a different recipe"
                % batch["batch_number"]), 400)
    operator_id = None
    if data.get("operator_employee_id") not in (None, "", 0):
        try:
            operator_id = int(data.get("operator_employee_id"))
        except (TypeError, ValueError):
            return None, (jsonify(error="operator_employee_id must be a number"), 400)
        op = conn.execute(
            "SELECT id FROM erp_hr_employees WHERE id = ?",
            (operator_id,)).fetchone()
        if not op:
            return None, (jsonify(
                error="operator_employee_id is not a valid employee"), 400)
    return {"batch_id": batch_id, "operator_employee_id": operator_id}, None


@app.get("/api/erp/work-orders")
def erp_list_work_orders():
    actor, err = _erp_check_perm("batches.read")
    if err:
        return err
    conn = db()
    rows = conn.execute(
        "SELECT * FROM erp_work_orders ORDER BY id DESC").fetchall()
    out = [_wo_dict(conn, r) for r in rows]
    conn.close()
    return jsonify(work_orders=out)


@app.post("/api/erp/work-orders")
def erp_create_work_order():
    actor, err = _require_erp_admin()
    if err:
        return err
    data = request.get_json(force=True) or {}
    conn = db()
    recipe = _erp_get_recipe(conn, data.get("recipe_id"))
    if not recipe:
        conn.close()
        return jsonify(error="recipe_id is not a valid recipe"), 400
    refs, rerr = _wo_validate_refs(conn, data, recipe["id"])
    if rerr:
        conn.close()
        return rerr
    try:
        planned = float(data.get("planned_qty") or 0)
    except (TypeError, ValueError):
        conn.close()
        return jsonify(error="planned_qty must be a number"), 400
    if planned <= 0:
        conn.close()
        return jsonify(error="planned_qty must be greater than zero"), 400
    notes = data.get("notes") or ""
    if not isinstance(notes, str):
        notes = str(notes)
    notes = notes.strip()
    if len(notes) > 2000:
        conn.close()
        return jsonify(error="notes must be 2000 characters or fewer"), 400
    steps_in = data.get("steps") or []
    if steps_in is None:
        steps_in = []
    if not isinstance(steps_in, list):
        conn.close()
        return jsonify(error="steps must be a list"), 400
    parsed_steps = []
    for s in steps_in:
        parsed, perr = _wo_validate_step(conn, s)
        if perr:
            conn.close()
            return perr
        parsed_steps.append(parsed)
    now = datetime.now(timezone.utc).isoformat()
    cur = conn.execute(
        "INSERT INTO erp_work_orders (recipe_id, batch_id,"
        " operator_employee_id, planned_qty, status, notes, created_by,"
        " created_at, updated_by, updated_at)"
        " VALUES (?, ?, ?, ?, 'planned', ?, ?, ?, ?, ?)",
        (recipe["id"], refs["batch_id"], refs["operator_employee_id"],
         planned, notes, actor, now, actor, now))
    wo_id = cur.lastrowid
    for i, s in enumerate(parsed_steps):
        conn.execute(
            "INSERT INTO erp_work_order_steps (work_order_id, step_no, name,"
            " equipment_id, input_qty, good_qty, scrap_qty, scrap_reason,"
            " created_by, created_at, updated_by, updated_at)"
            " VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
            (wo_id, i + 1, s["name"], s["equipment_id"], s["input_qty"],
             s["good_qty"], s["scrap_qty"], s["scrap_reason"],
             actor, now, actor, now))
    _erp_staff_audit(conn, actor, "production.work_order_created",
                     "work_order", wo_id,
                     "created work order for recipe %s (planned %s)"
                     % (recipe["name"], planned))
    out = _wo_dict(conn, _wo_get(conn, wo_id))
    conn.commit()
    conn.close()
    return jsonify(work_order=out), 201


