@app.post("/api/erp/wholesale-accounts")
def erp_create_wholesale_account():
    actor, err = _erp_check_perm("accounts.write")
    if err:
        return err
    data = request.get_json(force=True) or {}
    name = (data.get("name") or "").strip()
    if not name:
        conn = None
        return jsonify(error="name is required"), 400
    pricing_mode = (data.get("pricing_mode") or "bag").strip().lower()
    if pricing_mode not in ("bag", "case"):
        return jsonify(error="pricing_mode must be 'bag' or 'case'"), 400
    # Nov 18, 2026: there is no generic bag price anymore — savory and
    # sweet are the only prices that drive orders. An old client or import
    # may still send price_per_bag_cents; accept it if usable, otherwise
    # fall back to the 400 default. It is never a reason to refuse.
    try:
        price = int(data.get("price_per_bag_cents", 400) or 400)
    except (TypeError, ValueError):
        price = 400
    if price <= 0:
        price = 400
    try:
        savory = int(data.get("savory_price_cents", 400) or 400)
        sweet = int(data.get("sweet_price_cents", 400) or 400)
    except (TypeError, ValueError):
        return jsonify(error="savory_price_cents and sweet_price_cents must be numbers"), 400
    if savory <= 0 or sweet <= 0:
        return jsonify(error="category prices must be greater than zero"), 400
    credit_limit = None
    if data.get("credit_limit_cents") is not None:
        try:
            credit_limit = int(data.get("credit_limit_cents"))
        except (TypeError, ValueError):
            return jsonify(error="credit_limit_cents must be a number"), 400
        if credit_limit < 0:
            return jsonify(error="credit_limit_cents cannot be negative"), 400
    case_prices = {}
    for key in ("savory_case_price_cents", "sweet_case_price_cents"):
        if data.get(key) is not None:
            try:
                cp = int(data.get(key))
            except (TypeError, ValueError):
                return jsonify(error="%s must be a number" % key), 400
            if cp <= 0:
                return jsonify(error="%s must be greater than zero" % key), 400
            case_prices[key] = cp
    conn = db()
    # The INSERT itself lives in _erp_insert_wholesale_account (shared
    # with quote acceptance, so a converted prospect gets exactly the
    # same account a member of staff would create by hand).
    _acct_fields = {
        "name": name,
        "contact_name": (data.get("contact_name") or "").strip(),
        "email": (data.get("email") or "").strip(),
        "phone": (data.get("phone") or "").strip(),
        "address": (data.get("address") or "").strip(),
        "price_per_bag_cents": price,
        "payment_terms": (data.get("payment_terms") or "").strip(),
        "notes": (data.get("notes") or "").strip(),
        "contact_person": (data.get("contact_person") or "").strip(),
        "savory_price_cents": savory,
        "sweet_price_cents": sweet,
        "default_po": (data.get("default_po") or "").strip(),
        "billing_name": (data.get("billing_name") or "").strip(),
        "billing_email": (data.get("billing_email") or "").strip(),
        "pricing_mode": pricing_mode,
        "credit_limit_cents": credit_limit,
        "credit_hold": 1 if data.get("credit_hold") else 0,
        "savory_case_price_cents": case_prices.get("savory_case_price_cents"),
        "sweet_case_price_cents": case_prices.get("sweet_case_price_cents"),
        "location": {k: (data.get(k) or "").strip() for k in
                     ("location_name", "street", "city", "state", "zip",
                      "location_contact", "location_email", "location_phone")},
    }
    account_id = _erp_insert_wholesale_account(conn, actor, _acct_fields)
    acct = conn.execute("SELECT * FROM erp_wholesale_accounts WHERE id = ?",
                        (account_id,)).fetchone()
    out = _erp_wholesale_account_dict(conn, acct)
    conn.commit()
    conn.close()
    return jsonify(account=out), 201


@app.get("/api/erp/wholesale-accounts/<int:account_id>")
def erp_get_wholesale_account(account_id):
    actor, err = _erp_check_perm("accounts.read")
    if err:
        return err
    conn = db()
    acct = conn.execute("SELECT * FROM erp_wholesale_accounts WHERE id = ?",
                        (account_id,)).fetchone()
    if not acct:
        conn.close()
        return jsonify(error="account not found"), 404
    orders = [_erp_wholesale_order_brief(conn, w) for w in conn.execute(
        "SELECT * FROM erp_wholesale_orders WHERE account_id = ? ORDER BY id DESC",
        (account_id,)).fetchall()]
    out = _erp_wholesale_account_dict(conn, acct)
    conn.close()
    return jsonify(account=out, orders=orders)


@app.put("/api/erp/wholesale-accounts/<int:account_id>")
def erp_update_wholesale_account(account_id):
    actor, err = _erp_check_perm("accounts.write")
    if err:
        return err
    data = request.get_json(force=True) or {}
    conn = db()
    acct = conn.execute("SELECT * FROM erp_wholesale_accounts WHERE id = ?",
                        (account_id,)).fetchone()
    if not acct:
        conn.close()
        return jsonify(error="account not found"), 404
    fields = {}
    for key in ("name", "contact_name", "email", "phone", "address",
                "payment_terms", "notes", "contact_person", "default_po",
                "billing_name", "billing_email"):
        if key in data:
            fields[key] = (data.get(key) or "").strip()
    # Nov 18, 2026: no generic bag price anymore — an invalid value sent
    # by an old client is ignored (the stored value is left alone) instead
    # of refusing the update.
    if "price_per_bag_cents" in data:
        try:
            price = int(data.get("price_per_bag_cents") or 0)
        except (TypeError, ValueError):
            price = 0
        if price > 0:
            fields["price_per_bag_cents"] = price
    for key in ("savory_price_cents", "sweet_price_cents"):
        if key in data:
            try:
                price = int(data.get(key) or 0)
            except (TypeError, ValueError):
                conn.close()
                return jsonify(error="%s must be a number" % key), 400
            if price <= 0:
                conn.close()
                return jsonify(error="%s must be greater than zero" % key), 400
            fields[key] = price
    if "account_status" in data:
        st = (data.get("account_status") or "").strip()
        if st not in ("invited", "active", "deactivated"):
            conn.close()
            return jsonify(error="account_status must be invited, active, or deactivated"), 400
        fields["account_status"] = st
    if "pricing_mode" in data:
        pm = (data.get("pricing_mode") or "").strip().lower()
        if pm not in ("bag", "case"):
            conn.close()
            return jsonify(error="pricing_mode must be 'bag' or 'case'"), 400
        fields["pricing_mode"] = pm
    if "active" in data:
        fields["active"] = 1 if data.get("active") else 0
    # Nov 17, 2026: every customer is staff-managed — the flag is no longer
    # offered on the form and can never be switched off, so a stale client
    # sending staff_managed=0 must not reopen portal invites.
    fields["staff_managed"] = 1
    if "credit_limit_cents" in data:
        if data.get("credit_limit_cents") is None:
            fields["credit_limit_cents"] = None
        else:
            try:
                cl = int(data.get("credit_limit_cents"))
            except (TypeError, ValueError):
                conn.close()
                return jsonify(error="credit_limit_cents must be a number"), 400
            if cl < 0:
                conn.close()
                return jsonify(error="credit_limit_cents cannot be negative"), 400
            fields["credit_limit_cents"] = cl
    if "credit_hold" in data:
        fields["credit_hold"] = 1 if data.get("credit_hold") else 0
    for key in ("savory_case_price_cents", "sweet_case_price_cents"):
        if key in data:
            if data.get(key) is None:
                fields[key] = None
            else:
                try:
                    cp = int(data.get(key))
                except (TypeError, ValueError):
                    conn.close()
                    return jsonify(error="%s must be a number" % key), 400
                if cp <= 0:
                    conn.close()
                    return jsonify(error="%s must be greater than zero" % key), 400
                fields[key] = cp
    if "name" in fields and not fields["name"]:
        conn.close()
        return jsonify(error="name is required"), 400
    if fields:
        sets = ", ".join("%s = ?" % k for k in fields)
        conn.execute("UPDATE erp_wholesale_accounts SET %s WHERE id = ?" % sets,
                     tuple(fields.values()) + (account_id,))
        conn.commit()
    acct = conn.execute("SELECT * FROM erp_wholesale_accounts WHERE id = ?",
                        (account_id,)).fetchone()
    out = _erp_wholesale_account_dict(conn, acct)
    conn.close()
    return jsonify(account=out)


@app.get("/api/erp/wholesale-accounts/<int:account_id>/tiers")
def erp_list_wholesale_tiers(account_id):
    actor, err = _erp_check_perm("accounts.read")
    if err:
        return err
    conn = db()
    if not conn.execute("SELECT 1 FROM erp_wholesale_accounts WHERE id = ?",
                        (account_id,)).fetchone():
        conn.close()
        return jsonify(error="account not found"), 404
    tiers = [dict(t) for t in conn.execute(
        "SELECT * FROM erp_wholesale_price_tiers WHERE account_id = ?"
        " ORDER BY category, min_bags", (account_id,)).fetchall()]
    conn.close()
    return jsonify(tiers=tiers)


@app.post("/api/erp/wholesale-accounts/<int:account_id>/tiers")
def erp_add_wholesale_tier(account_id):
    actor, err = _erp_check_perm("accounts.write")
    if err:
        return err
    data = request.get_json(force=True) or {}
    category = (data.get("category") or "").strip().lower()
    if category not in ("savory", "sweet"):
        return jsonify(error="category must be 'savory' or 'sweet'"), 400
    try:
        min_bags = int(data.get("min_bags") or 0)
        price = int(data.get("price_per_bag_cents") or 0)
    except (TypeError, ValueError):
        return jsonify(error="min_bags and price_per_bag_cents must be numbers"), 400
    if min_bags < 1:
        return jsonify(error="min_bags must be at least 1"), 400
    if price <= 0:
        return jsonify(error="price_per_bag_cents must be greater than zero"), 400
    conn = db()
    if not conn.execute("SELECT 1 FROM erp_wholesale_accounts WHERE id = ?",
                        (account_id,)).fetchone():
        conn.close()
        return jsonify(error="account not found"), 404
    now = datetime.now(timezone.utc).isoformat()
    conn.execute(
        "INSERT INTO erp_wholesale_price_tiers (account_id, category, min_bags,"
        " price_per_bag_cents, created_at) VALUES (?, ?, ?, ?, ?)"
        " ON CONFLICT(account_id, category, min_bags) DO UPDATE SET"
        " price_per_bag_cents = excluded.price_per_bag_cents",
        (account_id, category, min_bags, price, now))
    conn.commit()
    tier = conn.execute(
        "SELECT * FROM erp_wholesale_price_tiers WHERE account_id = ?"
        " AND category = ? AND min_bags = ?",
        (account_id, category, min_bags)).fetchone()
    conn.close()
    return jsonify(tier=dict(tier)), 201


@app.delete("/api/erp/wholesale-accounts/<int:account_id>/tiers/<int:tier_id>")
def erp_delete_wholesale_tier(account_id, tier_id):
    actor, err = _erp_check_perm("accounts.write")
    if err:
        return err
    conn = db()
    tier = conn.execute(
        "SELECT * FROM erp_wholesale_price_tiers WHERE id = ? AND account_id = ?",
        (tier_id, account_id)).fetchone()
    if not tier:
        conn.close()
        return jsonify(error="tier not found"), 404
    conn.execute("DELETE FROM erp_wholesale_price_tiers WHERE id = ?", (tier_id,))
    conn.commit()
    conn.close()
    return jsonify(deleted=tier_id)


@app.post("/api/erp/wholesale-accounts/import")
def erp_import_wholesale_accounts():
    """CSV import. Columns: name, contact_name, email, phone, address,
    savory_price_cents, sweet_price_cents, payment_terms, notes.
    price_per_bag_cents is still accepted (old files) but no longer
    listed — savory/sweet are the prices that drive orders. Fail-fast
    with row numbers, same pattern as the recipe import."""
    import csv
    import io
    actor, err = _erp_check_perm("accounts.write")
    if err:
        return err
    data = request.get_json(force=True) or {}
    text = data.get("csv") or ""
    if not text.strip():
        return jsonify(error="csv text is required"), 400
    conn = db()
    reader = csv.DictReader(io.StringIO(text))
    rows = []
    for n, row in enumerate(reader, 2):
        row = {(k or "").strip(): (v or "").strip() for k, v in row.items()}
        name = row.get("name") or ""
        if not name:
            conn.close()
            return jsonify(error="row %d: name is required" % n), 400
        try:
            price = int(row.get("price_per_bag_cents") or 400)
        except (TypeError, ValueError):
            conn.close()
            return jsonify(error="row %d: price_per_bag_cents must be a number" % n), 400
        if price <= 0:
            conn.close()
            return jsonify(error="row %d: price_per_bag_cents must be > 0" % n), 400
        try:
            savory = int(row.get("savory_price_cents") or 400)
            sweet = int(row.get("sweet_price_cents") or 400)
        except (TypeError, ValueError):
            conn.close()
            return jsonify(error="row %d: savory_price_cents and sweet_price_cents must be numbers" % n), 400
        if savory <= 0 or sweet <= 0:
            conn.close()
            return jsonify(error="row %d: savory_price_cents and sweet_price_cents must be > 0" % n), 400
        rows.append({"name": name, "contact_name": row.get("contact_name") or "",
                     "email": row.get("email") or "", "phone": row.get("phone") or "",
                     "address": row.get("address") or "", "price_per_bag_cents": price,
                     "savory_price_cents": savory, "sweet_price_cents": sweet,
                     "payment_terms": row.get("payment_terms") or "",
                     "notes": row.get("notes") or ""})
    if not rows:
        conn.close()
        return jsonify(error="no account rows found"), 400
    now = datetime.now(timezone.utc).isoformat()
    for r in rows:
        conn.execute(
            "INSERT INTO erp_wholesale_accounts (name, contact_name, email, phone, address,"
            " price_per_bag_cents, savory_price_cents, sweet_price_cents,"
            " payment_terms, notes, active, staff_managed,"
            " created_by, created_at)"
            " VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 1, 1, ?, ?)",
            (r["name"], r["contact_name"], r["email"], r["phone"], r["address"],
             r["price_per_bag_cents"], r["savory_price_cents"], r["sweet_price_cents"],
             r["payment_terms"], r["notes"], actor, now))
    _erp_settings_audit(conn, actor, "import.wholesale_accounts",
                        "wholesale_accounts", 0,
                        "Imported %d wholesale account(s) from CSV" % len(rows))
    conn.commit()
    conn.close()
    return jsonify(imported=len(rows))


# ---------------- wholesale orders ----------------

# Every ERP data table, children first. Wiping these leaves the site's
# own tables (users, staff, gift cards, store orders, subscriptions)
# untouched, so admin/staff logins keep working.
_ERP_RESET_TABLES = [
    "erp_batch_ingredients",
    "erp_batch_orders",
    "erp_order_production_lines",
    "erp_fulfillment_history",
    "erp_order_fulfillment",
    "erp_order_pickup",
    "erp_drop_ship_shipments",
    # Wave 4 item 21 (Nov 2026, SOP 5.37): delivery routes + stops
    # joined the wipe list, 61 -> 63. Routes are delivery plans
    # (order data), not audit history -- a wipe takes them with the
    # orders they point at.
    "erp_delivery_routes",
    "erp_delivery_route_stops",
    "erp_kit_assemblies",
    "erp_kit_components",
    "erp_kit_definitions",
    "erp_work_order_steps",
    "erp_work_orders",
    "erp_wholesale_order_lines",
    "erp_wholesale_orders",
    "erp_wholesale_addresses",
    "erp_wholesale_users",
    "erp_wholesale_accounts",
    "erp_production_batches",
    "erp_recipe_lines",
    "erp_recipes",
    "erp_barcode_pool",
    "erp_inventory_count_lines",
    "erp_inventory_counts",
    "erp_pick_list_lines",
    "erp_pick_lists",
    "erp_cycle_counts",
    "erp_inventory_bins",
    "erp_po_lines",
    "erp_vendor_portal_tokens",
    "erp_vendor_portal_submissions",
    "erp_purchase_orders",
    "erp_reorder_rules",
    "erp_item_locations",
    "erp_stock_ledger",
    "erp_lots",
    "erp_items",
    "erp_locations",
    "erp_stores",
    "erp_store_transfers",
    "erp_store_sales",
    "erp_pos_returns",
    "erp_store_zreports",
    "erp_store_shifts",
    "erp_store_timeclock",
    "erp_store_maintenance",
    "erp_store_voids",
    "erp_store_cash_audits",
    "erp_store_planograms",
    "erp_store_drawers",
    "erp_store_lp_flags",
    "erp_store_pm_schedules",
    "erp_vendors",
    "erp_edi_documents",
    "erp_edi_partners",
    "erp_edi_as2_messages",
    "erp_qb_links",
    "erp_qb_oauth",
    "erp_qb_config",
    "erp_company_profile",
    "erp_sales_summaries",
    "erp_flavor_categories",
]
# PERMANENCE RULE (Phase 4, section 1.6): _ERP_RESET_TABLES must contain
# zero erp_acct_* tables. Accounting data -- journal, invoices, bills,
# payroll, tax filings, audit log -- is KEPT by a reset; erp_qb_links
# stays (bridge idempotency map, not accounting data) while
# erp_acct_migration_links is never in this list. There is no accounting
# wipe endpoint.
assert not any(t.startswith("erp_acct_") for t in _ERP_RESET_TABLES), \
    "_ERP_RESET_TABLES must not contain accounting tables"
# Wave B: the Settings audit log must survive a wipe -- the pre-wipe row
# is the only record that a wipe was requested (Wave C depends on it).
assert "erp_settings_audit" not in _ERP_RESET_TABLES, \
    "erp_settings_audit must survive the reset (wipe audit rows)"
# Dept 11: the staff audit log survives a wipe too -- the staff rows
# themselves are never wiped, so the record of who changed them must
# not be wiped either.
assert "erp_staff_audit" not in _ERP_RESET_TABLES, \
    "erp_staff_audit must survive the reset (staff audit rows)"
# HR Wave A: HR employee records and onboarding items are people
# records like the staff rows -- a wipe must never erase them.
assert "erp_hr_employees" not in _ERP_RESET_TABLES, \
    "erp_hr_employees must survive the reset (HR records)"
assert "erp_hr_onboarding" not in _ERP_RESET_TABLES, \
    "erp_hr_onboarding must survive the reset (onboarding items)"
# HR Additions 7: hiring applicants and job roles are people records
# like the Wave A tables -- a wipe must never erase them.
assert "erp_hr_applicants" not in _ERP_RESET_TABLES, \
    "erp_hr_applicants must survive the reset (HR applicants)"
assert "erp_hr_roles" not in _ERP_RESET_TABLES, \
    "erp_hr_roles must survive the reset (HR job roles)"
# Headcount planning: periods and targets are admin-entered planning
# records like job roles -- a wipe must never erase the plan. Note
# erp_stores IS wiped, so the forecast must tolerate orphaned store
# targets (a store row deleted while its targets survive).
assert "erp_hr_headcount_periods" not in _ERP_RESET_TABLES, \
    "erp_hr_headcount_periods must survive the reset (headcount plan)"
assert "erp_hr_headcount_targets" not in _ERP_RESET_TABLES, \
    "erp_hr_headcount_targets must survive the reset (headcount plan)"
# Recruiting (SOP 12.22): requisitions, interviews and offers are
# people records like the hiring applicants -- a wipe must never erase
# them.
assert "erp_hr_requisitions" not in _ERP_RESET_TABLES, \
    "erp_hr_requisitions must survive the reset (recruiting)"
assert "erp_hr_interviews" not in _ERP_RESET_TABLES, \
    "erp_hr_interviews must survive the reset (recruiting)"
assert "erp_hr_offers" not in _ERP_RESET_TABLES, \
    "erp_hr_offers must survive the reset (recruiting)"
# Positions + org hierarchy (SOP 12.27): positions are people records
# like job roles -- a wipe must never erase the org structure.
assert "erp_hr_positions" not in _ERP_RESET_TABLES, \
    "erp_hr_positions must survive the reset (HR positions)"
# Succession planning (SOP 12.30): succession plans are people
# records like the positions they name successors for -- a wipe must
# never erase them.
assert "erp_hr_succession" not in _ERP_RESET_TABLES, \
    "erp_hr_succession must survive the reset (HR succession plans)"
# Career paths (SOP 12.31): paths and steps are people records
# like the job roles their rungs point at -- a wipe must never
# erase them.
assert "erp_hr_career_paths" not in _ERP_RESET_TABLES, \
    "erp_hr_career_paths must survive the reset (HR career paths)"
assert "erp_hr_career_path_steps" not in _ERP_RESET_TABLES, \
    "erp_hr_career_path_steps must survive the reset (HR career paths)"
# Structured goals (SOP 12.24): goals are people records like the
# reviews they hang off -- a wipe must never erase them.
assert "erp_hr_goals" not in _ERP_RESET_TABLES, \
    "erp_hr_goals must survive the reset (structured goals)"
# Compensation review cycles (SOP 12.29): comp rows are people
# records like the reviews they hang off -- a wipe must never erase
# a pay decision.
assert "erp_hr_comp_reviews" not in _ERP_RESET_TABLES, \
    "erp_hr_comp_reviews must survive the reset (comp reviews)"
# Bonus plans + payouts (SOP 12.32): plans and payouts are people
# records like the comp reviews they sit beside -- a wipe must
# never erase a recorded bonus decision.
assert "erp_hr_bonus_plans" not in _ERP_RESET_TABLES, \
    "erp_hr_bonus_plans must survive the reset (HR bonus plans)"
assert "erp_hr_bonus_payouts" not in _ERP_RESET_TABLES, \
    "erp_hr_bonus_payouts must survive the reset (HR bonus payouts)"
# Pay grades / salary bands (SOP 12.35): grades are people
# records like the job roles they band -- a wipe must never
# erase them.
assert "erp_hr_pay_grades" not in _ERP_RESET_TABLES, \
    "erp_hr_pay_grades must survive the reset (HR pay grades)"
# Approved supplier list + vendor onboarding (Wave 4 item 9,
# SOP 3.18): onboarding + approval history are evidence records
# like the supplier audits -- a wipe must never erase them. (A
# wipe DOES delete the vendor rows, so the list endpoints JOIN
# vendors and never show an orphaned onboarding row.)
assert "erp_vendor_onboarding" not in _ERP_RESET_TABLES, \
    "erp_vendor_onboarding must survive the reset (approval evidence)"
assert "erp_vendor_approval_history" not in _ERP_RESET_TABLES, \
    "erp_vendor_approval_history must survive the reset (approval evidence)"
# E-learning (SOP 12.33): lessons, quizzes, questions and attempts
# are people records like the training courses they hang off -- a
# wipe must never erase them. Attempts are history: a wipe never
# erases a quiz score, and deleting a quiz is refused while any
