assert "erp_hr_benefit_eligibility" not in _ERP_RESET_TABLES, \
    "erp_hr_benefit_eligibility must survive the reset" \
    " (benefits admin)"
assert "erp_hr_enrollment_windows" not in _ERP_RESET_TABLES, \
    "erp_hr_enrollment_windows must survive the reset" \
    " (benefits admin)"
# HR Wave B: events, roster links and time records are people records
# like the Wave A tables -- a wipe must never erase them.
assert "erp_hr_events" not in _ERP_RESET_TABLES, \
    "erp_hr_events must survive the reset (HR events)"
assert "erp_hr_event_staff" not in _ERP_RESET_TABLES, \
    "erp_hr_event_staff must survive the reset (HR roster)"
assert "erp_hr_time_records" not in _ERP_RESET_TABLES, \
    "erp_hr_time_records must survive the reset (HR time records)"
# HR Additions 1: PTO types, grants and requests are people records
# like the Wave A/B tables -- a wipe must never erase them.
assert "erp_hr_pto_types" not in _ERP_RESET_TABLES, \
    "erp_hr_pto_types must survive the reset (PTO types)"
