@app.post("/api/erp/wholesale-orders/<int:order_id>/pick")
def erp_wholesale_order_pick(order_id):
    actor, err = _erp_check_perm("orders.write")
    if err:
        return err
    data = request.get_json(force=True) or {}
    conn = db()
    w = conn.execute("SELECT * FROM erp_wholesale_orders WHERE id = ?",
                     (order_id,)).fetchone()
    if not w:
        conn.close()
        return jsonify(error="order not found"), 404
    if w["status"] in ("shipped", "picked_up", "cancelled"):
        conn.close()
        return jsonify(error="cannot pick a %s order" % w["status"]), 400
    lines_in = data.get("lines") or []
    if not lines_in:
        conn.close()
        return jsonify(error="at least one line is required"), 400
    lines = {l["id"]: l for l in conn.execute(
        "SELECT * FROM erp_wholesale_order_lines WHERE order_id = ?", (order_id,)).fetchall()}
    for i, entry in enumerate(lines_in, 1):
        try:
            line_id = int((entry or {}).get("line_id") or 0)
        except (TypeError, ValueError):
            conn.close()
            return jsonify(error="line %d: line_id must be a number" % i), 400
        line = lines.get(line_id)
        if not line:
            conn.close()
            return jsonify(error="line %d: unknown line" % i), 400
        try:
            picked = float((entry or {}).get("qty_picked") or 0)
        except (TypeError, ValueError):
            conn.close()
            return jsonify(error="line %d: qty_picked must be a number" % i), 400
        if picked < 0 or picked > float(line["qty_bags"]):
            conn.close()
            return jsonify(error="line %d: qty_picked must be between 0 and %s"
                           % (i, _erp_fmt_qty(line["qty_bags"]))), 400
        conn.execute("UPDATE erp_wholesale_order_lines SET qty_picked = ? WHERE id = ?",
                     (picked, line_id))
    conn.commit()
    out = [dict(l) for l in conn.execute(
        "SELECT * FROM erp_wholesale_order_lines WHERE order_id = ? ORDER BY id",
        (order_id,)).fetchall()]
    conn.close()
    return jsonify(lines=out)


@app.post("/api/erp/wholesale-orders/<int:order_id>/ship")
def erp_wholesale_order_ship(order_id):
    actor, err = _erp_check_perm("orders.write")
    if err:
        return err
    data = request.get_json(force=True) or {}
    conn = db()
    w = conn.execute("SELECT * FROM erp_wholesale_orders WHERE id = ?",
                     (order_id,)).fetchone()
    if not w:
        conn.close()
        return jsonify(error="order not found"), 404
    if w["status"] not in ("ready", "partially_shipped"):
        conn.close()
        return jsonify(error="only ready orders can ship (status: %s)" % w["status"]), 400
    lines_in = data.get("lines") or []
    if not lines_in:
        conn.close()
        return jsonify(error="at least one line is required"), 400
    lines = {l["id"]: l for l in conn.execute(
        "SELECT * FROM erp_wholesale_order_lines WHERE order_id = ?", (order_id,)).fetchall()}
    for i, entry in enumerate(lines_in, 1):
        try:
            line_id = int((entry or {}).get("line_id") or 0)
        except (TypeError, ValueError):
            conn.close()
            return jsonify(error="line %d: line_id must be a number" % i), 400
        line = lines.get(line_id)
        if not line:
            conn.close()
            return jsonify(error="line %d: unknown line" % i), 400
        try:
            qty = float((entry or {}).get("qty") or 0)
        except (TypeError, ValueError):
            conn.close()
            return jsonify(error="line %d: qty must be a number" % i), 400
        if qty <= 0:
            conn.close()
            return jsonify(error="line %d: qty must be greater than zero" % i), 400
        remaining = float(line["qty_bags"]) - float(line["qty_shipped"] or 0)
        if qty > remaining:
            conn.close()
            return jsonify(error="line %d: cannot ship more than the %s remaining"
                           % (i, _erp_fmt_qty(remaining))), 400
        conn.execute("UPDATE erp_wholesale_order_lines SET qty_shipped = qty_shipped + ?"
                     " WHERE id = ?", (qty, line_id))
    after = conn.execute(
        "SELECT qty_bags, qty_shipped FROM erp_wholesale_order_lines WHERE order_id = ?",
        (order_id,)).fetchall()
    all_shipped = all(float(l["qty_shipped"] or 0) >= float(l["qty_bags"]) for l in after)
    new_status = "shipped" if all_shipped else "partially_shipped"
    err_msg = _erp_set_fulfillment(conn, "wholesale", order_id, new_status,
                                   actor, "shipped via Order hub")
    if err_msg:
        conn.rollback()
        conn.close()
        return jsonify(error=err_msg), 400
    conn.commit()
    w = conn.execute("SELECT * FROM erp_wholesale_orders WHERE id = ?",
                     (order_id,)).fetchone()
    out = _erp_wholesale_order_brief(conn, w)
    out["lines"] = [dict(l) for l in conn.execute(
        "SELECT * FROM erp_wholesale_order_lines WHERE order_id = ? ORDER BY id",
        (order_id,)).fetchall()]
    conn.close()
    return jsonify(order=out)


@app.post("/api/erp/wholesale-orders/<int:order_id>/shipping-label")
def erp_wholesale_order_shipping_label(order_id):
    actor, err = _erp_check_perm("orders.write")
    if err:
        return err
    conn = db()
    w = conn.execute("SELECT * FROM erp_wholesale_orders WHERE id = ?",
                     (order_id,)).fetchone()
    if not w:
        conn.close()
        return jsonify(error="order not found"), 404
    if w["shippo_label_url"] if "shippo_label_url" in w.keys() else "":
        conn.close()
        return jsonify(error="shipping label already exists for this order"), 400
    acct = conn.execute("SELECT * FROM erp_wholesale_accounts WHERE id = ?",
                        (w["account_id"],)).fetchone()
    addr_id = w["address_id"] if "address_id" in w.keys() else 0
    addr = None
    if addr_id:
        addr = conn.execute("SELECT * FROM erp_wholesale_addresses WHERE id = ?",
                            (addr_id,)).fetchone()
    if not addr or not (addr["zip"] or "").strip():
        conn.close()
        return jsonify(error="no shippable address on file for this order"), 400
    lines = conn.execute(
        "SELECT qty_bags, qty_shipped FROM erp_wholesale_order_lines WHERE order_id = ?",
        (order_id,)).fetchall()
    shipped = sum(float(l["qty_shipped"] or 0) for l in lines)
    total_qty = int(shipped) if shipped > 0 else int(sum(float(l["qty_bags"]) for l in lines))
    if total_qty <= 0:
        conn.close()
        return jsonify(error="nothing to ship on this order"), 400
    address_to = _shippo_address_to(
        name=acct["name"] if acct else "", street1=addr["street"],
        city=addr["city"], state=addr["state"], zip_code=addr["zip"], country="US")
    label_url, tracking, rate_cents = _create_shippo_label(address_to, total_qty,
                                               order_ref=w["order_number"])
    if not label_url:
        conn.close()
        return jsonify(error="Shippo couldn't create a label \u2014 nothing was stored"), 502
    now = datetime.now(timezone.utc).isoformat()
    conn.execute(
        "UPDATE erp_wholesale_orders SET shippo_label_url = ?, shippo_tracking_number = ?,"
        " shippo_label_created_at = ?, shipping_cents = ? WHERE id = ?",
        (label_url, tracking or "", now, int(rate_cents or 0), order_id))
    conn.commit()
    conn.close()
    return jsonify(label_url=label_url, tracking_number=tracking or "",
                   shipping_cents=int(rate_cents or 0), created_at=now)


def _erp_wholesale_return_item(conn, flavor_name):
    """The POP-* finished-goods item for a return line's flavor, or None.

    Same match as production receipts (_erp_recipe_finished_item):
    '<Flavor> Popcorn' by name, then a flavor-key match over active
    popcorn items. Never invents a SKU: a flavor with no POP-* item
    returns None and the restock is refused with a 400 naming it.
    """
    flavor = (flavor_name or "").strip()
    if not flavor:
        return None
    row = conn.execute(
        "SELECT * FROM erp_items WHERE type = 'popcorn' AND active = 1"
        " AND name = ?", (flavor + " Popcorn",)).fetchone()
    if row:
        return row
    key = _erp_flavor_key(flavor)
    for it in conn.execute(
            "SELECT * FROM erp_items WHERE type = 'popcorn' AND active = 1"
            " ORDER BY name").fetchall():
        if _erp_flavor_key(it["name"]) == key:
            return it
    return None


_ERP_WHOLESALE_RETURN_DISPOSITIONS = ("restock", "destroy", "return_to_vendor")


def _erp_wholesale_return_dict(conn, return_id):
    r = conn.execute("SELECT * FROM erp_wholesale_returns WHERE id = ?",
                     (return_id,)).fetchone()
    if not r:
        return None
    d = dict(r)
    d["lines"] = [dict(l) for l in conn.execute(
        "SELECT * FROM erp_wholesale_return_lines WHERE return_id = ? ORDER BY id",
        (return_id,)).fetchall()]
    return d


@app.post("/api/erp/wholesale-orders/<int:order_id>/returns")
def erp_wholesale_order_create_return(order_id):
    actor, err = _erp_check_perm("orders.write")
    if err:
        return err
    data = request.get_json(force=True) or {}
    conn = db()
    w = conn.execute("SELECT * FROM erp_wholesale_orders WHERE id = ?",
                     (order_id,)).fetchone()
    if not w:
        conn.close()
        return jsonify(error="order not found"), 404
    reason = (data.get("reason") or "").strip()
    lines_in = data.get("lines") or []
    if not lines_in:
        conn.close()
        return jsonify(error="at least one return line is required"), 400
    lines = {l["id"]: l for l in conn.execute(
        "SELECT * FROM erp_wholesale_order_lines WHERE order_id = ?", (order_id,)).fetchall()}
    clean = []
    for i, entry in enumerate(lines_in, 1):
        try:
            line_id = int((entry or {}).get("order_line_id") or 0)
        except (TypeError, ValueError):
            conn.close()
            return jsonify(error="line %d: order_line_id must be a number" % i), 400
        line = lines.get(line_id)
        if not line:
            conn.close()
            return jsonify(error="line %d: unknown order line" % i), 400
        try:
            qty = float((entry or {}).get("qty") or 0)
        except (TypeError, ValueError):
            conn.close()
            return jsonify(error="line %d: qty must be a number" % i), 400
        if qty <= 0:
            conn.close()
            return jsonify(error="line %d: qty must be greater than zero" % i), 400
        already = conn.execute(
            "SELECT COALESCE(SUM(qty_bags), 0) AS q FROM erp_wholesale_return_lines"
            " WHERE order_line_id = ?", (line_id,)).fetchone()["q"]
        if float(already or 0) + qty > float(line["qty_bags"]):
            conn.close()
            return jsonify(error="line %d: cannot return more than the %s ordered"
                           % (i, _erp_fmt_qty(line["qty_bags"]))), 400
        clean.append((line_id, line["flavor_name"], qty))
    now = datetime.now(timezone.utc).isoformat()
    cur = conn.execute(
        "INSERT INTO erp_wholesale_returns (order_id, reason, status, credit_cents,"
        " created_by, created_at) VALUES (?, ?, 'requested', 0, ?, ?)",
        (order_id, reason, actor, now))
    rid = cur.lastrowid
    # W2-N1: the RMA number is the row id, zero-padded ("RMA-000001").
    # Assigned at creation so the response, the list, and the SOP all
    # show the same number from the start.
    conn.execute("UPDATE erp_wholesale_returns SET rma_no = ? WHERE id = ?",
                 ("RMA-%06d" % rid, rid))
    for line_id, flavor, qty in clean:
        conn.execute(
            "INSERT INTO erp_wholesale_return_lines (return_id, order_line_id,"
            " flavor_name, qty_bags) VALUES (?, ?, ?, ?)",
            (rid, line_id, flavor, qty))
    _erp_staff_audit(conn, actor, "wholesale_return.created",
                     "wholesale_return", rid,
                     "RMA-%06d order #%d %s %d line(s)"
                     % (rid, order_id, reason, len(clean)))
    conn.commit()
    ret = _erp_wholesale_return_dict(conn, rid)
    conn.close()
    return jsonify(wholesale_return=ret), 201


@app.get("/api/erp/wholesale-orders/<int:order_id>/returns")
def erp_wholesale_order_list_returns(order_id):
    actor, err = _erp_check_perm("orders.read")
    if err:
        return err
    conn = db()
    if not conn.execute("SELECT 1 FROM erp_wholesale_orders WHERE id = ?",
                        (order_id,)).fetchone():
        conn.close()
        return jsonify(error="order not found"), 404
    rows = conn.execute(
        "SELECT * FROM erp_wholesale_returns WHERE order_id = ? ORDER BY id",
        (order_id,)).fetchall()
    out = [_erp_wholesale_return_dict(conn, r["id"]) for r in rows]
    conn.close()
    return jsonify(returns=out)


# W2-N1: a wrong return is cancelled only from requested (never
# deleted — returns are the audit trail). Cancellation needs no
# disposition and posts no stock movement. No existing flow used a
# cancelled return status, so nothing else needed changing.
_ERP_WHOLESALE_RETURN_NEXT = {"requested": ("received", "credited", "cancelled"),
                              "received": ("credited",),
                              "credited": (),
                              "cancelled": ()}


@app.post("/api/erp/wholesale-returns/<int:return_id>/status")
def erp_wholesale_return_set_status(return_id):
    actor, err = _erp_check_perm("orders.write")
    if err:
        return err
    data = request.get_json(force=True) or {}
    status = (data.get("status") or "").strip()
    conn = db()
    r = conn.execute("SELECT * FROM erp_wholesale_returns WHERE id = ?",
                     (return_id,)).fetchone()
    if not r:
        conn.close()
        return jsonify(error="return not found"), 404
    if status not in _ERP_WHOLESALE_RETURN_NEXT.get(r["status"], ()):
        conn.close()
        return jsonify(error="cannot move a %s return to %s" % (r["status"], status or "''")), 400
    credit = int(r["credit_cents"] or 0)
    if "credit_cents" in data:
        try:
            credit = int(data.get("credit_cents") or 0)
        except (TypeError, ValueError):
            conn.close()
            return jsonify(error="credit_cents must be a number"), 400
        if credit < 0:
            conn.close()
            return jsonify(error="credit_cents cannot be negative"), 400
    # W2-N1: receiving a return decides what happens to the goods, and
    # that decision is required — a received return with no disposition
    # is how returned stock silently vanished before this build.
    disposition = (r["disposition"] or "")
    restocked = int(r["restocked"] or 0)
    restock_lines = []
    if status == "received":
        disposition = (data.get("disposition") or "").strip()
        if disposition not in _ERP_WHOLESALE_RETURN_DISPOSITIONS:
            conn.close()
            return jsonify(error="disposition is required when receiving a return:"
                           " restock, destroy, or return_to_vendor"), 400
        if int(r["restocked"] or 0):
            conn.close()
            return jsonify(error="return was already restocked"), 400
        if disposition == "restock":
            # Restock posts one return_in ledger movement per return
            # line, at the ORDER line's per-bag price — the order's
            # actual unit value for these bags. The item's current
            # average cost is deliberately NOT used: it moves with
            # every receipt, so it would revalue old stock at today's
            # cost. The bags go back to the first active location
            # (the default warehouse); wholesale orders carry no
            # location of their own.
            loc = conn.execute(
                "SELECT id FROM erp_locations WHERE active = 1"
                " ORDER BY id LIMIT 1").fetchone()
            if not loc:
                conn.close()
                return jsonify(error="no active location to restock into"), 400
            order_lines = {l["id"]: l for l in conn.execute(
                "SELECT * FROM erp_wholesale_order_lines WHERE order_id = ?",
                (r["order_id"],)).fetchall()}
            ret_lines = conn.execute(
                "SELECT * FROM erp_wholesale_return_lines WHERE return_id = ?"
                " ORDER BY id", (return_id,)).fetchall()
            for rl in ret_lines:
                ol = order_lines.get(rl["order_line_id"])
                if not ol:
                    conn.close()
                    return jsonify(error="return line %d has no order line"
                                   % rl["id"]), 400
                item = _erp_wholesale_return_item(conn, rl["flavor_name"])
                if not item:
                    conn.close()
                    return jsonify(error="no inventory item for flavor %s;"
                                   " create the %s Popcorn item first"
                                   % (rl["flavor_name"], rl["flavor_name"])), 400
                restock_lines.append((item, rl, ol))
            rma_no = (r["rma_no"] or "") or ("RMA-%06d" % return_id)
            for item, rl, ol in restock_lines:
                _erp_post_movement(
                    conn, item["id"], loc["id"], float(rl["qty_bags"]),
                    "return_in", actor, ref_type="wholesale_return",
                    ref_id=rma_no,
                    unit_cost_cents=int(ol["unit_price_cents"] or 0),
                    note="%s restock %s x %s" % (
                        rma_no, rl["flavor_name"],
                        _erp_fmt_qty(rl["qty_bags"])))
            restocked = 1
    conn.execute("UPDATE erp_wholesale_returns SET status = ?, credit_cents = ?,"
                 " disposition = ?, restocked = ? WHERE id = ?",
                 (status, credit, disposition, restocked, return_id))
    _erp_staff_audit(conn, actor, "wholesale_return.status",
                     "wholesale_return", return_id,
                     "%s %s -> %s%s%s" % (
                         (r["rma_no"] or ("RMA-%06d" % return_id)),
                         r["status"], status,
                         (" disposition " + disposition
                          if status == "received" else ""),
                         (" restocked %d line(s)" % len(restock_lines)
                          if restock_lines else "")))
    conn.commit()
    out = _erp_wholesale_return_dict(conn, return_id)
    conn.close()
    return jsonify(wholesale_return=out)


@app.post("/api/erp/wholesale-returns/<int:return_id>/credit-note")
def erp_wholesale_return_create_credit_note(return_id):
    """W2-N1: create the accounting credit note for a wholesale return.

    One credit note per return (409 on a second attempt). The note is
    the return's credit_cents against the invoice linked to the
    return's order (via erp_acct_sale_posts, kind 'wholesale'), posted
    through the same _acct_insert_credit_note helper as the invoice
    credit-note endpoint — same journal reversal, same balance update.
    Permissions: orders.write for the return side, accounting.write
    for the credit-note side; both are required.
    """
    actor, err = _erp_check_perm("orders.write")
    if err:
        return err
    actor, err = _erp_check_perm("accounting.write")
    if err:
        return err
    conn = db()
    r = conn.execute("SELECT * FROM erp_wholesale_returns WHERE id = ?",
                     (return_id,)).fetchone()
    if not r:
        conn.close()
        return jsonify(error="return not found"), 404
    if r["credit_note_id"]:
        conn.close()
        return jsonify(error="return already has credit note #%d"
                       % r["credit_note_id"]), 409
    amount = int(r["credit_cents"] or 0)
    if amount < 1:
        conn.close()
        return jsonify(error="set a credit amount on the return first"), 400
    post = conn.execute(
        "SELECT invoice_id FROM erp_acct_sale_posts"
        " WHERE kind = 'wholesale' AND ref_id = ? AND invoice_id IS NOT NULL"
        " ORDER BY id DESC LIMIT 1", (r["order_id"],)).fetchone()
    if not post:
        conn.close()
        return jsonify(error="no invoice linked to this order;"
                       " verify the order in Accounting first"), 400
    inv = conn.execute("SELECT * FROM erp_acct_invoices WHERE id = ?",
                       (post["invoice_id"],)).fetchone()
    if not inv:
        conn.close()
        return jsonify(error="linked invoice not found"), 404
    if inv["status"] != "open":
        conn.close()
        return jsonify(error="only an open invoice can be credited (status: %s)"
                       % inv["status"]), 400
    if amount > inv["balance_cents"]:
        conn.close()
        return jsonify(error="credit exceeds the invoice balance"), 400
    date = datetime.now(timezone.utc).date().isoformat()
    lock_error = _acct_lock_error(conn, date)
    if lock_error:
        conn.close()
        return jsonify(error=lock_error), 400
    reason = "Wholesale return %s%s" % (
        (r["rma_no"] or ("RMA-%06d" % return_id)),
        (" — " + r["reason"]) if (r["reason"] or "").strip() else "")
    note_id, error, status_code = _acct_insert_credit_note(
        conn, actor, inv, amount, date, reason)
    if error:
        conn.close()
        return jsonify(error=error), status_code
    conn.execute("UPDATE erp_wholesale_returns SET credit_note_id = ?"
                 " WHERE id = ?", (note_id, return_id))
    _erp_staff_audit(conn, actor, "wholesale_return.credit_note_created",
                     "wholesale_return", return_id,
                     "%s credit note #%d on invoice #%d for %d cents"
                     % ((r["rma_no"] or ("RMA-%06d" % return_id)),
                        note_id, inv["id"], amount))
    conn.commit()
    out = _erp_wholesale_return_dict(conn, return_id)
    note = conn.execute("SELECT * FROM erp_acct_credit_notes WHERE id = ?",
                        (note_id,)).fetchone()
    inv_row = conn.execute("SELECT * FROM erp_acct_invoices WHERE id = ?",
                           (inv["id"],)).fetchone()
    conn.close()
    return jsonify(wholesale_return=out,
                   credit_note=_acct_credit_note_dict(note),
                   invoice=_acct_invoice_dict(inv_row)), 201


