@app.post("/api/erp/batches/<int:batch_id>/orders")
def erp_link_batch_order(batch_id):
    actor, err = _erp_check_perm("batches.write")
    if err:
        return err
    data = request.get_json(force=True) or {}
    source = (data.get("order_source") or "").strip()
    order_id = data.get("order_id")
    if source not in _ERP_ORDER_SOURCES:
        return jsonify(error="valid order_source is required"), 400
    conn = db()
    batch = _erp_get_batch(conn, batch_id)
    if not batch:
        conn.close()
        return jsonify(error="batch not found"), 404
    if batch["status"] in ("completed", "reversed", "cancelled"):
        conn.close()
        return jsonify(error="cannot link orders to a %s batch" % batch["status"]), 400
    order = _erp_order_brief(conn, source, order_id)
    if not order:
        conn.close()
        return jsonify(error="order not found"), 404
    try:
        qty = float(data.get("qty_bags") or 0)
    except (TypeError, ValueError):
        conn.close()
        return jsonify(error="qty_bags must be a number"), 400
    if qty <= 0:
        conn.close()
        return jsonify(error="qty_bags must be greater than zero"), 400
    dup = conn.execute("SELECT id FROM erp_batch_orders WHERE batch_id = ?"
                       " AND order_source = ? AND order_id = ?",
                       (batch_id, source, order_id)).fetchone()
    if dup:
        conn.close()
        return jsonify(error="batch is already linked to this order"), 400
    now = datetime.now(timezone.utc).isoformat()
    cur = conn.execute(
        "INSERT INTO erp_batch_orders (batch_id, order_source, order_id, qty_bags,"
        " created_by, created_at) VALUES (?, ?, ?, ?, ?, ?)",
        (batch_id, source, order_id, qty, actor, now))
    link = conn.execute("SELECT * FROM erp_batch_orders WHERE id = ?",
                        (cur.lastrowid,)).fetchone()
    out = _erp_batch_link_dict(conn, link)
    conn.commit()
    conn.close()
    return jsonify(link=out), 201


@app.delete("/api/erp/batches/<int:batch_id>/orders/<int:link_id>")
def erp_unlink_batch_order(batch_id, link_id):
    actor, err = _erp_check_perm("batches.write")
    if err:
        return err
    conn = db()
    batch = _erp_get_batch(conn, batch_id)
    if not batch:
        conn.close()
        return jsonify(error="batch not found"), 404
    if batch["status"] in ("completed", "reversed", "cancelled"):
        conn.close()
        return jsonify(error="cannot unlink orders from a %s batch;"
                              " post a correcting entry instead" % batch["status"]), 400
    link = conn.execute("SELECT * FROM erp_batch_orders WHERE id = ? AND batch_id = ?",
                        (link_id, batch_id)).fetchone()
    if not link:
        conn.close()
        return jsonify(error="link not found"), 404
    conn.execute("DELETE FROM erp_batch_orders WHERE id = ?", (link_id,))
    conn.commit()
    conn.close()
    return jsonify(ok=True)


@app.get("/api/erp/orders/<source>/<int:order_id>/trace")
def erp_order_trace(source, order_id):
    """Traceability: order -> production batches -> ingredient lots."""
    actor, err = _erp_check_perm("orders.read")
    if err:
        return err
    if source not in _ERP_ORDER_SOURCES:
        return jsonify(error="unknown source"), 404
    conn = db()
    order = _erp_order_brief(conn, source, order_id)
    if not order:
        conn.close()
        return jsonify(error="order not found"), 404
    batches = []
    for l in conn.execute("SELECT * FROM erp_batch_orders WHERE order_source = ?"
                          " AND order_id = ? ORDER BY id",
                          (source, order_id)).fetchall():
        b = conn.execute("SELECT * FROM erp_production_batches WHERE id = ?",
                         (l["batch_id"],)).fetchone()
        if not b:
            continue
        ingredients = [dict(r) for r in conn.execute(
            "SELECT bi.*, i.sku, i.name AS item_name FROM erp_batch_ingredients bi"
            " JOIN erp_items i ON i.id = bi.item_id"
            " WHERE bi.batch_id = ? ORDER BY bi.id", (b["id"],)).fetchall()]
        batches.append({"batch_id": b["id"], "batch_number": b["batch_number"],
                        "lot_code": b["lot_code"], "expiry_date": b["expiry_date"],
                        "batch_status": b["status"], "qty_bags": l["qty_bags"],
                        "ingredients": ingredients})
    conn.close()
    return jsonify(order=order, batches=batches)


# ---------------- ERP Phase 3: EDI module (provider-agnostic) ----------------
# Minimal X12 engine for the grocery subset: parse inbound 850, generate
# outbound 856 + 810, record 997 functional acks. Secrets never touch the DB:
# partner config holds refs only; webhook keys are stored as hashes.

_EDI_TRANSPORTS = ("manual-file", "sftp", "api", "webhook", "as2")
_EDI_DOC_TYPES = ("850", "855", "856", "810", "997")
_EDI_DOC_STATUSES = ("received", "parsed", "mapped", "queued", "sent",
                     "acked", "failed")
_EDI_CONFIG_FORBIDDEN = ("password", "secret", "private_key", "api_key",
                         "passphrase", "webhook_key")


def _edi_sanitize_config(cfg):
    """Drop anything that looks like a secret from partner config before
    storage. Keys ending in _hash (e.g. webhook_key_hash) are digests, not
    secrets, and are kept."""
    if not isinstance(cfg, dict):
        return {}
    clean = {}
    for k, v in cfg.items():
        kl = str(k).lower()
        if kl.endswith("_hash"):
            clean[k] = v
            continue
        if any(frag in kl for frag in _EDI_CONFIG_FORBIDDEN):
            continue
        if isinstance(v, dict):
            clean[k] = _edi_sanitize_config(v)
        else:
            clean[k] = v
    return clean


def _edi_config(conn, partner):
    try:
        cfg = json.loads(partner["config_json"] or "{}")
    except (TypeError, ValueError):
        cfg = {}
    return cfg if isinstance(cfg, dict) else {}


def _edi_as2_id_pair_in_use(conn, our_id, partner_id, exclude_id=None):
    """AS2 inbound routing matches on the (as2_our_id, as2_partner_id) pair,
    so two partners must never share one -- the receiver could not tell
    which partner a message came from (and which verification certificate
    applies). Returns True when another active AS2 partner uses the pair."""
    if not our_id or not partner_id:
        return False
    for p in conn.execute("SELECT * FROM erp_edi_partners WHERE active = 1"
                          " AND transport = 'as2'").fetchall():
        if exclude_id is not None and p["id"] == exclude_id:
            continue
        c = _edi_config(conn, p)
        if (c.get("as2_our_id") or "").strip() == our_id \
                and (c.get("as2_partner_id") or "").strip() == partner_id:
            return True
    return False


def _edi_partner_public(conn, p):
    cfg = _edi_config(conn, p)
    return {"id": p["id"], "name": p["name"], "provider": p["provider"],
            "transport": p["transport"], "active": bool(p["active"]),
            "test_mode": _edi_test_mode(p),
            "has_webhook_key": bool(cfg.get("webhook_key_hash")),
            "has_as2": bool((cfg.get("as2_url") or "").strip()),
            "created_at": p["created_at"]}


def _edi_partner_detail(conn, p):
    d = _edi_partner_public(conn, p)
    cfg = _edi_config(conn, p)
    cfg = dict(cfg)
    cfg.pop("webhook_key_hash", None)
    d["config"] = cfg
    return d


def _edi_new_webhook_key():
    return "edip_" + secrets.token_urlsafe(24)


def _edi_key_hash(key):
    return hashlib.sha256(key.encode("utf-8")).hexdigest()


# ----- X12 parsing -----

def _x12_split_segments(text):
    t = (text or "").strip()
    if not t:
        return []
    if "~" in t:
        parts = t.split("~")
    else:
        parts = re.split(r"[\r\n]+", t)
    return [p.strip() for p in parts if p.strip()]


def _x12_parse_850(text):
    """Parse an X12 850 purchase order (grocery subset).
    Returns (parsed_dict, errors). Non-empty errors => reject the document."""
    errors = []
    segs = _x12_split_segments(text)
    if not segs:
        return None, ["empty document"]
    if not segs[0].startswith("ISA"):
        return None, ["document must start with an ISA segment"]
    sep = segs[0][3:4] or "*"
    isa = segs[0].split(sep)
    if len(isa) < 16:
        return None, ["malformed ISA segment (expected 16 elements)"]

    def is_seg(s, tag):
        return s.startswith(tag + sep)

    idx = {s.split(sep)[0]: i for i, s in enumerate(segs)}
    st_i = next((i for i, s in enumerate(segs) if is_seg(s, "ST")), None)
    if st_i is None:
        return None, ["missing ST segment"]
    st = segs[st_i].split(sep)
    if len(st) < 2 or st[1] != "850":
        return None, ["not an 850 transaction (ST01=%s)" % (st[1] if len(st) > 1 else "?")]
    se_i = next((i for i in range(st_i + 1, len(segs)) if is_seg(segs[i], "SE")), None)
    if se_i is None:
        errors.append("missing SE segment")
    else:
        se = segs[se_i].split(sep)
        try:
            claimed = int(se[1])
        except (IndexError, ValueError):
            claimed = -1
        actual = se_i - st_i + 1
        if claimed != actual:
            errors.append("SE segment count mismatch: claimed %s, actual %s"
                          % (se[1] if len(se) > 1 else "?", actual))
    ge_i = next((i for i, s in enumerate(segs) if is_seg(s, "GE")), None)
    if ge_i is None:
        errors.append("missing GE segment")
    if not any(is_seg(s, "IEA") for s in segs):
        errors.append("missing IEA segment")

    beg = next((s for s in segs if is_seg(s, "BEG")), None)
    if beg is None:
        errors.append("missing BEG segment (purchase order header)")
        po_number, po_date = "", ""
    else:
        be = beg.split(sep)
        po_number = be[3] if len(be) > 3 else ""
        po_date = be[5] if len(be) > 5 else ""
        if not po_number:
            errors.append("BEG03 purchase order number is missing")

    def n1(code):
        for s in segs:
            e = s.split(sep)
            if e[0] == "N1" and len(e) > 1 and e[1] == code:
                return {"qualifier": e[3] if len(e) > 3 else "",
                        "id": e[4] if len(e) > 4 else "",
                        "name": e[2] if len(e) > 2 else ""}
        return {"qualifier": "", "id": "", "name": ""}

    lines = []
    cur = None
    for s in segs:
        e = s.split(sep)
        if e[0] == "PO1":
            if cur:
                lines.append(cur)
            try:
                qty = float(e[2]) if len(e) > 2 and e[2] else 0
            except ValueError:
                qty = -1
            try:
                price_cents = int(round(float(e[4]) * 100)) if len(e) > 4 and e[4] else 0
            except ValueError:
                price_cents = -1
            cur = {"line": int(e[1]) if len(e) > 1 and e[1].isdigit() else len(lines) + 1,
                   "qty": qty, "uom": e[3] if len(e) > 3 else "",
                   "unit_price_cents": price_cents,
                   "product_id": e[7] if len(e) > 7 else "",
                   "description": ""}
            if qty <= 0:
                errors.append("PO1 line %s: quantity must be > 0" % cur["line"])
            if price_cents < 0:
                errors.append("PO1 line %s: unit price is not a number" % cur["line"])
        elif e[0] == "PID" and cur is not None:
            if len(e) > 5 and e[5]:
                cur["description"] = e[5]
    if cur:
        lines.append(cur)
    if not lines:
        errors.append("no PO1 line items found")
    ctt = next((s for s in segs if is_seg(s, "CTT")), None)
    if ctt:
        ce = ctt.split(sep)
        try:
            if int(ce[1]) != len(lines):
                errors.append("CTT line count %s does not match %d PO1 segments"
                              % (ce[1], len(lines)))
        except (IndexError, ValueError):
            errors.append("malformed CTT segment")
    parsed = {"doc_type": "850", "po_number": po_number, "po_date": po_date,
              "ship_to": n1("ST"), "bill_to": n1("BT"), "lines": lines,
              "total_lines": len(lines),
              "control": {"isa13": isa[13] if len(isa) > 13 else "",
                         "sender": (isa[6] if len(isa) > 6 else "").strip(),
                         "receiver": (isa[8] if len(isa) > 8 else "").strip()}}
    return parsed, errors


def _x12_parse_997(text):
    """Parse an inbound 997. Returns ({ack_code, ref_doc_type, ref_st02,
    ref_gs06}, errors). AK2 carries the referenced doc type + ST02; AK9
    carries the outcome (A accepted, E accepted with errors, R rejected)."""
    segs = _x12_split_segments(text)
    sep = segs[0][3:4] if segs and segs[0].startswith("ISA") else "*"
    parsed = {"doc_type": "997", "ack_code": "", "ref_doc_type": "",
              "ref_st02": "", "ref_gs06": ""}
    errors = []
    for sg in segs:
        e = sg.split(sep)
        if e[0] == "AK1" and len(e) > 2:
            parsed["ref_gs06"] = e[2]
        elif e[0] == "AK2" and len(e) > 2:
            parsed["ref_doc_type"] = e[1]
            parsed["ref_st02"] = e[2]
        elif e[0] == "AK9" and len(e) > 1:
            parsed["ack_code"] = e[1]
    if not parsed["ref_doc_type"] or not parsed["ref_st02"]:
        errors.append("997 has no AK2 reference to an outbound document")
    if parsed["ack_code"] not in ("A", "E", "R"):
        errors.append("997 AK9 code '%s' is not A, E or R" % parsed["ack_code"])
    return parsed, errors


def _x12_parse_860(text):
    """Parse an inbound 860 (purchase order change). Returns ({po_number,
    po_date, changes: [{line, change_type, qty, unit_price_cents,
    product_id, description}]}, errors). POC layout: POC01 line,
    POC02 change type (AI add / CA change / DI delete), POC03 quantity
    ordered, POC04 quantity change, POC05 UOM, POC06 unit price,
    POC08 qualifier, POC09 product id (POC07-style layouts fall back to
    element 7 for the id)."""
    segs = _x12_split_segments(text)
    sep = segs[0][3:4] if segs and segs[0].startswith("ISA") else "*"
    parsed = {"doc_type": "860", "po_number": "", "po_date": "", "changes": []}
    errors = []
    cur = None
    for sg in segs:
        e = sg.split(sep)
        if e[0] == "BCH":
            # BCH mirrors BEG: BCH03 purchase order number, BCH05 date.
            parsed["po_number"] = e[3] if len(e) > 3 else ""
            parsed["po_date"] = e[5] if len(e) > 5 else ""
        elif e[0] == "POC":
            try:
                qty = float(e[3]) if len(e) > 3 and e[3] else 0
            except ValueError:
                qty = -1
            try:
                price_cents = int(round(float(e[6]) * 100)) if len(e) > 6 and e[6] else 0
            except ValueError:
                price_cents = -1
            pid = ""
            if len(e) > 9 and e[9]:
                pid = e[9]
            elif len(e) > 7 and e[7]:
                pid = e[7]
            cur = {"line": int(e[1]) if len(e) > 1 and e[1].isdigit() else len(parsed["changes"]) + 1,
                   "change_type": e[2] if len(e) > 2 else "",
                   "qty": qty, "unit_price_cents": price_cents,
                   "product_id": pid, "description": ""}
            if qty < 0:
                errors.append("POC line %s: quantity is not a number" % cur["line"])
            if price_cents < 0:
                errors.append("POC line %s: unit price is not a number" % cur["line"])
            parsed["changes"].append(cur)
        elif e[0] == "PID" and cur is not None:
            if len(e) > 5 and e[5]:
                cur["description"] = e[5]
    if not parsed["po_number"]:
        errors.append("860 has no BCH purchase order number")
    if not parsed["changes"]:
        errors.append("860 has no POC change lines")
    return parsed, errors


# ----- X12 generation -----

def _edi_next_control(conn):
    n = conn.execute("SELECT COALESCE(MAX(id), 0) + 1 AS n"
                     " FROM erp_edi_documents").fetchone()["n"]
    return int(n)


def _x12_pad(s, n):
    s = (s or "")[:n]
    return s + " " * (n - len(s))


def _x12_envelope(doc_type, gs_code, body, sender, receiver, ctrl,
                  test_mode=False):
    """Wrap ST..CTT body segments in ISA/GS/GE/IEA. Returns full X12 string.
    test_mode sets ISA15 to 'T' (test) instead of 'P' (production)."""
    now = datetime.now(timezone.utc)
    ymd = now.strftime("%Y%m%d")
    hm = now.strftime("%H%M")
    isa13 = "%09d" % (ctrl % 1000000000)
    st02 = "%04d" % (ctrl % 10000)
    segs = []
    segs.append("ISA*00*%s*00*%s*ZZ*%s*ZZ*%s*%s*%s*U*00401*%s*0*%s*>"
                % (" " * 10, " " * 10, _x12_pad(sender, 15),
                   _x12_pad(receiver, 15), now.strftime("%y%m%d"), hm, isa13,
                   "T" if test_mode else "P"))
    segs.append("GS*%s*%s*%s*%s*%s*%d*X*004010"
                % (gs_code, sender or "POPALICIOUS", receiver or "PARTNER",
                   ymd, hm, ctrl))
    body = [b if b.startswith("ST*") else b for b in body]
    body[0] = "ST*%s*%s" % (doc_type, st02)
    segs.extend(body)
    segs.append("SE*%d*%s" % (len(body) + 1, st02))
    segs.append("GE*1*%d" % ctrl)
    segs.append("IEA*1*%s" % isa13)
    return "~".join(segs) + "~"


def _x12_build_856(order, cartons, ssccs, partner_cfg, ctrl, test_mode=False):
    """Ship notice with a carton/pallet HL hierarchy and SSCC-18s.
    cartons: list of cartons from _edi_split_cartons; ssccs: one SSCC-18
    per carton, same order. HL levels: S(hipment) -> O(rder) -> P(allet)
    -> I(tem). CTT counts HL segments."""
    sender = _edi_map_value(partner_cfg, "isa_sender", "POPALICIOUS")
    receiver = _edi_map_value(partner_cfg, "isa_receiver", "PARTNER")
    now = datetime.now(timezone.utc)
    ymd = now.strftime("%Y%m%d")
    ship_id = "SHP-%s-%d" % ((order.get("number") or "NA").replace("#", ""), ctrl)
    ship_to = order.get("ship_to") or {}
    body = [
        "ST*856*0001",
        "BSN*00*%s*%s*%s" % (ship_id, ymd, now.strftime("%H%M")),
        "DTM*011*%s" % ymd,
        "N1*ST*%s*%s*%s" % (ship_to.get("name") or "Customer",
                            ship_to.get("qualifier") or "92",
                            ship_to.get("id") or ""),
        "HL*1**S",
    ]
    hl = 2
    body.append("HL*%d**O*1" % hl)
    hl += 1
    body.append("PRF*%s*%s" % (order.get("po_number") or order.get("number") or "",
                               order.get("po_date") or ymd))
    for i, carton in enumerate(cartons):
        pallet_hl = hl
        body.append("HL*%d**P*2" % pallet_hl)
        hl += 1
        body.append("MAN*GM*%s" % (ssccs[i] if i < len(ssccs) else ""))
        for ln in carton:
            body.append("HL*%d**I*%d" % (hl, pallet_hl))
            hl += 1
            body.append("LIN**%s*%s" % (ln.get("id_qualifier") or "VP",
                                        ln.get("product_id") or ""))
            body.append("SN1**%s*EA" % _erp_fmt_qty(ln.get("qty") or 0))
    body.append("CTT*%d" % (hl - 1))
    return _x12_envelope("856", "SH", body, sender, receiver, ctrl,
                         test_mode=test_mode)


def _x12_build_855(order, lines, partner_cfg, ctrl, test_mode=False):
    """PO acknowledgement for a wholesale order (retailers expect an 855
    confirming their 850). BAK*00*AC = original acknowledgement, accepted."""
    sender = _edi_map_value(partner_cfg, "isa_sender", "POPALICIOUS")
    receiver = _edi_map_value(partner_cfg, "isa_receiver", "PARTNER")
    now = datetime.now(timezone.utc)
    ymd = now.strftime("%Y%m%d")
    ship_to = order.get("ship_to") or {}
    body = [
        "ST*855*0001",
        "BAK*00*AC*%s*%s" % (order.get("po_number") or order.get("number") or "", ymd),
        "N1*ST*%s*%s*%s" % (ship_to.get("name") or "Customer",
                            ship_to.get("qualifier") or "92",
                            ship_to.get("id") or ""),
    ]
    for i, ln in enumerate(lines, 1):
        qty = float(ln.get("qty") or 0)
        unit_cents = int(ln.get("unit_price_cents") or 0)
        body.append("PO1*%d*%s*EA*%.2f**%s*%s"
                    % (i, _erp_fmt_qty(qty), unit_cents / 100.0,
                       ln.get("id_qualifier") or "VP", ln.get("product_id") or ""))
    body.append("CTT*%d" % len(lines))
    return _x12_envelope("855", "PR", body, sender, receiver, ctrl,
                         test_mode=test_mode)


def _x12_build_810(order, lines, partner_cfg, ctrl, freight_cents=0,
                     tax_cents=0, test_mode=False):
    """Invoice for a wholesale order. Amounts are integer cents throughout
    (matches the existing TDS convention in this codebase, not X12's usual
    dollars-with-implied-decimals). SAC segments state freight (D240) and
    tax (H850) only when there is something to state; wholesale is
    tax-exempt by default, so the tax SAC is usually omitted."""
    sender = _edi_map_value(partner_cfg, "isa_sender", "POPALICIOUS")
    receiver = _edi_map_value(partner_cfg, "isa_receiver", "PARTNER")
    now = datetime.now(timezone.utc)
    ymd = now.strftime("%Y%m%d")
    inv_num = "INV-%s" % (order.get("number") or ctrl)
    ship_to = order.get("ship_to") or {}
    total_cents = 0
    body = [
        "ST*810*0001",
        "BIG*%s*%s*%s*%s" % (ymd, inv_num, order.get("po_date") or ymd,
                             order.get("po_number") or order.get("number") or ""),
        "N1*ST*%s*%s*%s" % (ship_to.get("name") or "Customer",
                            ship_to.get("qualifier") or "92",
                            ship_to.get("id") or ""),
    ]
    for i, ln in enumerate(lines, 1):
        qty = float(ln.get("qty") or 0)
        unit_cents = int(ln.get("unit_price_cents") or 0)
        total_cents += int(round(qty * unit_cents))
        body.append("IT1*%d*%s*EA*%.2f**%s*%s"
                    % (i, _erp_fmt_qty(qty), unit_cents / 100.0,
                       ln.get("id_qualifier") or "VP", ln.get("product_id") or ""))
    freight_cents = int(freight_cents or 0)
    tax_cents = int(tax_cents or 0)
    if freight_cents > 0:
        body.append("SAC*C*D240***%d" % freight_cents)
    if tax_cents > 0:
        body.append("SAC*C*H850***%d" % tax_cents)
    body.append("TDS*%d" % (total_cents + freight_cents + tax_cents))
    body.append("CTT*%d" % len(lines))
    return _x12_envelope("810", "IN", body, sender, receiver, ctrl,
                         test_mode=test_mode), inv_num


def _x12_build_997(inbound_ctrl, partner_cfg, ctrl, test_mode=False):
    """Functional acknowledgement for a received 850."""
    sender = _edi_map_value(partner_cfg, "isa_sender", "POPALICIOUS")
    receiver = _edi_map_value(partner_cfg, "isa_receiver", "PARTNER")
    body = [
        "ST*997*0001",
        "AK1*PO*%s" % (inbound_ctrl.get("gs06") or "1"),
        "AK2*850*%s" % (inbound_ctrl.get("st02") or "1"),
        "AK5*A",
        "AK9*A*1*1*1",
    ]
    return _x12_envelope("997", "FA", body, sender, receiver, ctrl,
                         test_mode=test_mode)



# SSCC-18 company prefix, derived from the brand's primary UPC range:
# Bacon UPC-A 602581038092 -> 6-digit GS1 company prefix 602581. The brand
# also carries other UPC blocks (794969 for Birthday Cake / Cheddar,
# 766429 for White Cheddar); 602581 is the flagship range. A partner's
# segment_map can override with sscc_company_prefix. Formal GS1 prefix
# confirmation is a follow-up, not a blocker: the SSCCs are structurally
# valid (correct GS1 Mod10 check digit) and stable per carton.
_EDI_SSCC_COMPANY_PREFIX = "602581"
_EDI_SSCC_EXTENSION = "0"
_EDI_SSCC_PER_CARTON = 12


def _edi_map_value(cfg, key, default):
    """Per-partner segment-map override: cfg['segment_map'][key] wins, then
    the top-level cfg key (the historical spot for isa_sender /
    isa_receiver), then the default."""
    sm = (cfg or {}).get("segment_map") or {}
    if isinstance(sm, dict) and sm.get(key) not in (None, ""):
        return sm[key]
    if (cfg or {}).get(key) not in (None, ""):
        return cfg[key]
    return default


def _edi_test_mode(partner):
    """test_mode flag off a partner row (defensive: older rows may lack it)."""
    try:
        return bool(partner["test_mode"]) if "test_mode" in partner.keys() else False
    except (KeyError, TypeError):
        return False


def _gs1_mod10(digits):
    """GS1 Mod10 check digit for the digit string WITHOUT the check digit:
    from the rightmost digit, weights 3, 1, 3, 1, ...; check = (10 - sum % 10) % 10."""
    total = 0
    for i, ch in enumerate(reversed(str(digits))):
        d = int(ch)
        total += d * 3 if i % 2 == 0 else d
    return (10 - (total % 10)) % 10


def _edi_sscc_for(conn, source, order_id, pallet_no, prefix=None):
    """Return the persisted SSCC-18 for a carton (source, order_id, pallet_no),
    generating and storing it on first use so a regenerated ASN reuses the
    same SSCCs (never re-randomize). SSCC-18 = extension (0) + 6-digit
    company prefix + 10-digit serial + Mod10 check digit. The serial is
    deterministic: source code (1 wholesale / 2 retail / 3 other) * 10^8 +
    order_id * 100 + pallet_no, so it is unique while order ids stay under
    1,000,000 and pallets under 100 per order."""
    row = conn.execute("SELECT sscc FROM erp_edi_ssccs WHERE source = ?"
                       " AND order_id = ? AND pallet_no = ?",
                       (source, int(order_id), int(pallet_no))).fetchone()
    if row:
        return row["sscc"]
    pfx = "".join(ch for ch in str(prefix or _EDI_SSCC_COMPANY_PREFIX)
                  if ch.isdigit())[:6].rjust(6, "0")
    src_code = {"wholesale": 1, "retail": 2}.get(source, 3)
    serial = src_code * 100000000 + int(order_id) * 100 + int(pallet_no)
    body17 = _EDI_SSCC_EXTENSION + pfx + ("%010d" % serial)
    sscc = body17 + str(_gs1_mod10(body17))
    now = datetime.now(timezone.utc).isoformat()
    conn.execute("INSERT OR IGNORE INTO erp_edi_ssccs"
                 " (source, order_id, pallet_no, sscc, created_at)"
                 " VALUES (?, ?, ?, ?, ?)",
                 (source, int(order_id), int(pallet_no), sscc, now))
    row = conn.execute("SELECT sscc FROM erp_edi_ssccs WHERE source = ?"
                       " AND order_id = ? AND pallet_no = ?",
                       (source, int(order_id), int(pallet_no))).fetchone()
    return row["sscc"] if row else sscc


def _edi_split_cartons(lines, per_carton=_EDI_SSCC_PER_CARTON):
    """Split order lines into per_carton-bag cartons, filled in line order.
    Returns a list of cartons; each carton is a list of
    {qty, product_id, description} with qty an int bag count."""
    cartons = []
    cur = []
    cur_qty = 0
    for ln in lines:
        remaining = int(round(float(ln.get("qty") or 0)))
        while remaining > 0:
            room = per_carton - cur_qty
            take = min(remaining, room)
            cur.append({"qty": take, "product_id": ln.get("product_id") or "",
                        "description": ln.get("description") or ""})
            cur_qty += take
            remaining -= take
            if cur_qty >= per_carton:
                cartons.append(cur)
                cur = []
                cur_qty = 0
    if cur:
        cartons.append(cur)
    return cartons


# ----- EDI document helpers -----

def _edi_doc_dict(conn, d, include_content=False):
    p = conn.execute("SELECT name FROM erp_edi_partners WHERE id = ?",
                     (d["partner_id"],)).fetchone()
    try:
        parsed = json.loads(d["parsed_json"] or "{}")
    except (TypeError, ValueError):
        parsed = {}
    order_number = ""
    if d["order_source"] and d["order_id"]:
        o = _erp_order_brief(conn, d["order_source"], d["order_id"])
        order_number = o["number"] if o else ""
    out = {"id": d["id"], "partner_id": d["partner_id"],
           "partner_name": p["name"] if p else "",
           "direction": d["direction"], "doc_type": d["doc_type"],
           "status": d["status"], "order_source": d["order_source"],
           "order_id": d["order_id"], "order_number": order_number,
           "retry_count": d["retry_count"] if "retry_count" in d.keys() else 0,
           "error_text": d["error_text"] if "error_text" in d.keys() else "",
           "created_at": d["created_at"]}
    # AS2 MDN state for this document, when it was sent over AS2 (SOP 5.35).
    as2_mdn = ""
    try:
        mrow = conn.execute(
            "SELECT mdn_status FROM erp_edi_as2_messages"
            " WHERE doc_id = ? AND direction = 'outbound'"
            " ORDER BY id DESC LIMIT 1", (d["id"],)).fetchone()
        if mrow:
            as2_mdn = mrow["mdn_status"] or ""
    except Exception:
        as2_mdn = ""
    out["as2_mdn_status"] = as2_mdn
    if include_content:
        out["raw_text"] = d["raw_text"]
        out["x12"] = d["raw_text"]
        out["parsed"] = parsed
    return out


def _edi_match_account(conn, partner, parsed):
    """Match a parsed 850 to a wholesale account via partner config.
    Returns (account_row, match_note, error). error is None on success."""
    cfg = _edi_config(conn, partner)
    ship_to_id = (parsed.get("ship_to") or {}).get("id") or ""
    account_id = None
    note = ""
    ship_map = cfg.get("ship_to_map") or {}
    if ship_to_id and str(ship_to_id) in {str(k) for k in ship_map}:
        for k, v in ship_map.items():
            if str(k) == str(ship_to_id):
                account_id = v
                note = "ship-to %s" % ship_to_id
                break
    elif cfg.get("account_id"):
        account_id = cfg["account_id"]
        note = "partner default account"
    if not account_id:
        return None, "", ("no wholesale account mapped for ship-to '%s'"
                          % (ship_to_id or "?"))
    acct = conn.execute("SELECT * FROM erp_wholesale_accounts WHERE id = ?",
                        (account_id,)).fetchone()
    if not acct:
        return None, "", "mapped account id %s does not exist" % account_id
    if not acct["active"]:
        return None, "", "mapped account '%s' is inactive" % acct["name"]
    return acct, note, None


def _edi_resolve_outbound_by_997(conn, partner_id, ref_doc_type, ref_st02):
    """Find the most recent outbound doc for this partner whose ST02 matches
    the 997's AK2 reference. ST02 is ctrl % 10000, zero-padded 4. Docs
    generated before the EDI 6-pack carry no st02 in parsed_json and never
    resolve (they predate 997 tracking)."""
    st02 = str(ref_st02 or "").strip().zfill(4)
    rows = conn.execute(
        "SELECT * FROM erp_edi_documents WHERE partner_id = ? AND direction = 'outbound'"
        " AND doc_type = ? ORDER BY id DESC", (partner_id, ref_doc_type)).fetchall()
    for d in rows:
        try:
            parsed = json.loads(d["parsed_json"] or "{}")
        except (TypeError, ValueError):
            parsed = {}
        if str(parsed.get("st02") or "").strip().zfill(4) == st02:
            return d
    return None


def _edi_resolve_order_by_po(conn, po_number):
    """Find a wholesale order by its PO number: first by order_number, then
    via the inbound 850 doc that carried that PO number (the usual path —
    ERP order numbers are W- numbers, not the retailer's PO number)."""
    if not po_number:
        return None
    w = conn.execute("SELECT * FROM erp_wholesale_orders WHERE order_number = ?",
                     (po_number,)).fetchone()
    if w:
        return w
    # Oldest first: a re-sent PO maps to a second order, but a change
    # amends the original PO's order, not the duplicate.
    docs = conn.execute(
        "SELECT * FROM erp_edi_documents WHERE direction = 'inbound'"
        " AND doc_type = '850' ORDER BY id ASC").fetchall()
    for d in docs:
        try:
            parsed = json.loads(d["parsed_json"] or "{}")
        except (TypeError, ValueError):
            parsed = {}
        if parsed.get("po_number") == po_number and d["order_id"]:
            return conn.execute("SELECT * FROM erp_wholesale_orders WHERE id = ?",
                                (d["order_id"],)).fetchone()
    return None


def _edi_create_997(conn, partner, parsed, actor):
    cfg = _edi_config(conn, partner)
    ctrl = _edi_next_control(conn)
    x12 = _x12_build_997(parsed.get("control") or {}, cfg, ctrl,
                         test_mode=_edi_test_mode(partner))
    now = datetime.now(timezone.utc).isoformat()
    cur = conn.execute(
        "INSERT INTO erp_edi_documents (partner_id, direction, doc_type, status,"
        " raw_text, parsed_json, created_at)"
        " VALUES (?, 'outbound', '997', 'sent', ?, ?, ?)",
        (partner["id"], x12,
         json.dumps({"ack_for": "850", "ctrl": ctrl,
                     "st02": "%04d" % (ctrl % 10000)}), now))
    return cur.lastrowid


def _edi_map_850_to_order(conn, doc, parsed, partner, actor):
    """Create a wholesale order from a parsed 850. Returns (order_brief, error)."""
    acct, _note, match_err = _edi_match_account(conn, partner, parsed)
    if match_err:
        return None, match_err
    lines = []
    for i, ln in enumerate(parsed.get("lines") or [], 1):
        flavor = (ln.get("description") or ln.get("product_id") or "").strip()
        if not flavor:
            return None, "PO1 line %d: no product id or description" % i
        qty = float(ln.get("qty") or 0)
        if qty <= 0:
            return None, "PO1 line %d: quantity must be > 0" % i
        # Nov 18, 2026: no generic bag price anymore — a PO1 line with no
        # price resolves from the account's savory/sweet price for the
        # flavor's category (unknown flavor defaults to sweet).
        unit = int(ln.get("unit_price_cents") or
                   _wholesale_flavor_price(conn, acct, flavor)[0])
        if unit <= 0:
            return None, "PO1 line %d: unit price must be > 0" % i
        lines.append({"flavor_name": flavor, "qty_bags": qty,
                      "unit_price_cents": unit,
                      "line_total_cents": int(round(qty * unit))})
    if not lines:
        return None, "no order lines in 850"
    now = datetime.now(timezone.utc).isoformat()
    order_number = _erp_next_wholesale_number(conn)
    cur = conn.execute(
        "INSERT INTO erp_wholesale_orders (order_number, account_id, status, order_date,"
        " due_date, notes, via_edi, edi_document_id, created_by, created_at)"
        " VALUES (?, ?, 'new', ?, '', ?, 1, ?, ?, ?)",
        (order_number, acct["id"], parsed.get("po_date") or "",
         "EDI 850 %s" % (parsed.get("po_number") or ""), doc["id"], actor, now))
    order_id = cur.lastrowid
    for li in lines:
        conn.execute(
            "INSERT INTO erp_wholesale_order_lines (order_id, flavor_name, qty_bags,"
            " unit_price_cents, line_total_cents) VALUES (?, ?, ?, ?, ?)",
            (order_id, li["flavor_name"], li["qty_bags"],
             li["unit_price_cents"], li["line_total_cents"]))
    _erp_set_fulfillment(conn, "wholesale", order_id, "new", actor,
                         "created from EDI 850 %s" % parsed.get("po_number"))
    conn.execute("UPDATE erp_edi_documents SET status = 'mapped',"
                 " order_source = 'wholesale', order_id = ? WHERE id = ?",
                 (order_id, doc["id"]))
    w = conn.execute("SELECT * FROM erp_wholesale_orders WHERE id = ?",
                     (order_id,)).fetchone()
    return _erp_wholesale_order_brief(conn, w), None


def _edi_parse_and_store_inbound(conn, partner, content, actor):
    """Shared by upload + webhook: detect type, parse, store, ack."""
    segs = _x12_split_segments(content)
    sep = segs[0][3:4] if segs and segs[0].startswith("ISA") else "*"
    st = next((s for s in segs if s.split(sep)[0] == "ST"), None)
    doc_type = ""
    if st:
        parts = st.split(sep)
        doc_type = parts[1] if len(parts) > 1 else ""
    now = datetime.now(timezone.utc).isoformat()
    if doc_type == "997":
        parsed, errors = _x12_parse_997(content)
        status = "parsed" if not errors else "failed"
        cur = conn.execute(
            "INSERT INTO erp_edi_documents (partner_id, direction, doc_type, status,"
            " raw_text, parsed_json, created_at) VALUES (?, 'inbound', '997', ?, ?, ?, ?)",
            (partner["id"] if partner else 0, status, content,
             json.dumps(parsed or {"errors": errors}), now))
        doc_id = cur.lastrowid
        acked_id = None
        outcome = "no matching outbound document"
        if not errors and partner:
            target = _edi_resolve_outbound_by_997(
                conn, partner["id"], parsed.get("ref_doc_type"),
                parsed.get("ref_st02"))
            if target is not None:
                if parsed.get("ack_code") == "R":
                    conn.execute("UPDATE erp_edi_documents SET status = 'failed',"
                                 " error_text = ? WHERE id = ?",
                                 ("rejected by partner 997 (AK9=R)", target["id"]))
                    outcome = "outbound %s %d marked failed (rejected)" % (
                        target["doc_type"], target["id"])
                else:
                    conn.execute("UPDATE erp_edi_documents SET status = 'acked'"
                                 " WHERE id = ?", (target["id"],))
                    outcome = "outbound %s %d acked" % (target["doc_type"], target["id"])
                acked_id = target["id"]
        doc = conn.execute("SELECT * FROM erp_edi_documents WHERE id = ?",
                           (doc_id,)).fetchone()
        preview = {"ack_code": parsed.get("ack_code", ""),
                   "ref_doc_type": parsed.get("ref_doc_type", ""),
                   "ref_st02": parsed.get("ref_st02", ""),
                   "acked_document_id": acked_id, "outcome": outcome,
                   "errors": errors}
        return doc, preview
    if doc_type == "860":
        parsed, errors = _x12_parse_860(content)
        status = "parsed" if not errors else "failed"
        cur = conn.execute(
            "INSERT INTO erp_edi_documents (partner_id, direction, doc_type, status,"
            " raw_text, parsed_json, created_at) VALUES (?, 'inbound', '860', ?, ?, ?, ?)",
            (partner["id"] if partner else 0, status, content,
             json.dumps(parsed or {"errors": errors}), now))
        doc_id = cur.lastrowid
        change_id = None
        order_id = 0
        order_number = ""
        if not errors:
            w = _edi_resolve_order_by_po(conn, parsed.get("po_number"))
            if w is not None:
                order_id = w["id"]
                order_number = w["order_number"]
            cur2 = conn.execute(
                "INSERT INTO erp_edi_changes (doc_id, order_id, change_json,"
                " status, created_at) VALUES (?, ?, ?, 'pending', ?)",
                (doc_id, order_id, json.dumps(parsed), now))
            change_id = cur2.lastrowid
            if order_id:
                conn.execute("UPDATE erp_edi_documents SET order_source = 'wholesale',"
                             " order_id = ? WHERE id = ?", (order_id, doc_id))
        doc = conn.execute("SELECT * FROM erp_edi_documents WHERE id = ?",
                           (doc_id,)).fetchone()
        preview = {"po_number": parsed.get("po_number", ""),
                   "order_id": order_id, "order_number": order_number,
                   "change_id": change_id,
                   "changes": parsed.get("changes", []), "errors": errors}
        return doc, preview
    if doc_type != "850":
        return None, "unsupported inbound doc_type '%s' (850, 997, 860)" % (doc_type or "?")
    parsed, errors = _x12_parse_850(content)
    status = "parsed" if not errors else "failed"
    cur = conn.execute(
        "INSERT INTO erp_edi_documents (partner_id, direction, doc_type, status,"
        " raw_text, parsed_json, created_at) VALUES (?, 'inbound', '850', ?, ?, ?, ?)",
        (partner["id"] if partner else 0, status, content,
         json.dumps(parsed or {"errors": errors}), now))
    doc_id = cur.lastrowid
    ack_id = None
    if not errors and partner:
        ack_id = _edi_create_997(conn, partner, parsed, actor)
    doc = conn.execute("SELECT * FROM erp_edi_documents WHERE id = ?",
                       (doc_id,)).fetchone()
    preview = {"po_number": (parsed or {}).get("po_number", ""),
               "partner_name": partner["name"] if partner else "",
               "account_name": "", "account_match_note": "",
               "lines": [{"flavor": (l.get("description") or l.get("product_id") or ""),
                          "qty": l.get("qty"), "unit_price_cents": l.get("unit_price_cents")}
                         for l in (parsed or {}).get("lines", [])],
               "errors": errors, "ack_document_id": ack_id}
    if not errors and partner:
        acct, note, match_err = _edi_match_account(conn, partner, parsed)
        if acct:
            preview["account_name"] = acct["name"]
            preview["account_match_note"] = note or ""
        else:
            preview["errors"] = errors + [match_err]
    return doc, preview


# Test double for the HTTP send path: tests set _EDI_HTTP_TEST_DOUBLE to a
# callable(url, data, headers) -> (status_code, text). Same pattern as
# _MAIL_TEST_DOUBLE.
_EDI_HTTP_TEST_DOUBLE = None


def _edi_http_post(url, data, headers=None):
    """POST X12 to a partner URL. Returns (status_code, text)."""
    if _EDI_HTTP_TEST_DOUBLE is not None:
        return _EDI_HTTP_TEST_DOUBLE(url, data, headers or {})
    resp = requests.post(url, data=data, headers=headers or {}, timeout=30)
    return resp.status_code, getattr(resp, "text", "")


def _edi_sftp_send(cfg, x12_text):
    """Send X12 via the system sftp batch CLI. Returns (ok, error).
    No new dependencies: uses the `sftp` binary if present. Fails cleanly
    (ok=False) when the CLI, host, user, remote path, or key is unavailable.
    Never exercised against a real SFTP server in this codebase — only the
    failure paths are covered by tests."""
    host = (cfg.get("sftp_host") or "").strip()
    user = (cfg.get("sftp_user") or "").strip()
    key = (cfg.get("sftp_key_path") or "").strip()
    remote = (cfg.get("sftp_remote_path") or "").strip()
    remote = remote.replace("\n", "").replace("\r", "")
    port = str(cfg.get("sftp_port") or "22").strip()
    if not host:
        return False, "no SFTP host configured for partner"
    if not user:
        return False, "no SFTP user configured for partner"
    if not remote:
        return False, "no SFTP remote path configured for partner"
    if key and not os.path.exists(key):
        return False, "SFTP key not found: %s" % key
    if shutil.which("sftp") is None:
        return False, "sftp command not available on this server"
    try:
        with tempfile.TemporaryDirectory() as td:
            local = os.path.join(td, "edi.x12")
            batch = os.path.join(td, "batch.txt")
            with open(local, "w", encoding="utf-8") as f:
                f.write(x12_text)
            with open(batch, "w", encoding="utf-8") as f:
                f.write("put %s %s\n" % (local, remote))
            cmd = ["sftp", "-b", batch, "-P", port]
            if key:
                cmd += ["-i", key]
            cmd.append("%s@%s" % (user, host))
            res = subprocess.run(cmd, capture_output=True, text=True, timeout=30)
    except FileNotFoundError:
        return False, "sftp command not available on this server"
    except subprocess.TimeoutExpired:
        return False, "SFTP send timed out after 30s"
    if res.returncode != 0:
        return False, "sftp exited %d: %s" % (
            res.returncode, (res.stderr or "").strip()[:300])
    return True, ""


# ----- AS2 transport (SOP 5.35, RFC 4130) -----
# Signing and encryption are real S/MIME via the system `openssl` CLI --
# no new Python dependency, and nothing new in the production
# requirements. What is NOT implemented, stated plainly:
#   * MDN signing: our MDNs are plain multipart/report, never S/MIME-signed.
#   * Async-MDN polling: an async MDN has nowhere to land except a second
#     inbound POST, which is recorded when it arrives; a sent document
#     whose MDN never arrives stays mdn_status "awaiting".
#   * Certificate storage: config holds file PATHS only (the same refs-only
#     rule as sftp_key_path). No private key or certificate material is
#     ever stored in the ERP; the files live on the ERP server and are
#     supplied by the partner at setup time.
#   * Sending is REFUSED -- never silently unsigned -- when signing is on
#     (the default) and no signing certificate/key is configured.
_AS2_MAX_BYTES = 1048576  # 1 MB inbound cap


def _as2_new_message_id():
    return "<%s@pop-a-licious>" % secrets.token_hex(16)


def _as2_split_mime(mime_bytes):
    """Split openssl SMIME output into (headers dict, content_type, body)."""
    for sep in (b"\r\n\r\n", b"\n\n"):
        i = mime_bytes.find(sep)
        if i >= 0:
            head = mime_bytes[:i].decode("utf-8", "ignore")
            body = mime_bytes[i + len(sep):]
            break
    else:
        return {}, "", mime_bytes
    headers = {}
    cur = None
    for line in head.splitlines():
        if line[:1] in (" ", "\t") and cur:
            headers[cur] += " " + line.strip()
        elif ":" in line:
            k, v = line.split(":", 1)
            cur = k.strip().lower()
            headers[cur] = v.strip()
    return headers, headers.get("content-type", ""), body


def _as2_run_openssl(args, in_bytes, trailing=None):
    """Run openssl with stdin bytes. Returns (returncode, stdout, stderr);
    returncode None means openssl is not installed. `trailing` args go
    after -in/-out (the -encrypt subcommand only accepts its recipient
    certificate there)."""
    if shutil.which("openssl") is None:
        return None, b"", "openssl command not available on this server"
    try:
        with tempfile.TemporaryDirectory() as td:
            inf = os.path.join(td, "in")
            outf = os.path.join(td, "out")
            with open(inf, "wb") as f:
                f.write(in_bytes)
            cmd = ["openssl"] + list(args) + ["-in", inf, "-out", outf]
            if trailing:
                cmd += list(trailing)
            res = subprocess.run(cmd, capture_output=True, text=True, timeout=30)
            out = b""
            if os.path.exists(outf):
                with open(outf, "rb") as f:
                    out = f.read()
            return res.returncode, out, (res.stderr or "").strip()
    except subprocess.TimeoutExpired:
        return -1, b"", "openssl timed out after 30s"
    except OSError as e:
        return -1, b"", "openssl failed: %s" % e


def _as2_smime_sign(payload, cert_path, key_path):
    """Detached S/MIME sign (multipart/signed). Returns
    (mime_bytes, content_type, error)."""
    if not os.path.exists(cert_path):
        return None, "", "AS2 signing certificate not found: %s" % cert_path
    if not os.path.exists(key_path):
        return None, "", "AS2 signing key not found: %s" % key_path
    rc, out, err = _as2_run_openssl(
        ["smime", "-sign", "-binary", "-signer", cert_path, "-inkey", key_path,
         "-outform", "SMIME"], payload)
    if rc is None:
        return None, "", err
    if rc != 0:
        return None, "", "openssl smime sign failed: %s" % (err[:200] or "exit %d" % rc)
    _h, ctype, _body = _as2_split_mime(out)
    return out, ctype, ""


def _as2_smime_encrypt(payload, cert_path):
    """S/MIME encrypt (application/pkcs7-mime, AES-256-CBC). Returns
    (mime_bytes, content_type, error)."""
    if not os.path.exists(cert_path):
        return None, "", "AS2 encryption certificate not found: %s" % cert_path
    rc, out, err = _as2_run_openssl(
        ["smime", "-encrypt", "-aes-256-cbc", "-outform", "SMIME"],
        payload, trailing=[cert_path])
    if rc is None:
        return None, "", err
    if rc != 0:
        return None, "", "openssl smime encrypt failed: %s" % (err[:200] or "exit %d" % rc)
    _h, ctype, _body = _as2_split_mime(out)
    return out, ctype, ""


def _as2_smime_verify(mime_bytes, cert_path=None):
    """Verify a signed MIME entity. With a certificate, the signer must
    chain to it (verified=True on success). Without one, the signature is
    integrity-checked only (-noverify: the math checks, the signer is NOT
    authenticated) and verified=False. Returns (ok, payload, verified, err)."""
    if cert_path is not None and not os.path.exists(cert_path):
        return False, b"", False, "AS2 verification certificate not found: %s" % cert_path
    args = ["smime", "-verify", "-binary", "-inform", "SMIME"]
    if cert_path:
        args += ["-CAfile", cert_path]
    else:
        args += ["-noverify"]
    rc, out, err = _as2_run_openssl(args, mime_bytes)
    if rc is None:
        return False, b"", False, err
    if rc != 0:
        return False, b"", False, "AS2 signature verification failed: %s" % (err[:200] or "exit %d" % rc)
    return True, out, bool(cert_path), ""


def _as2_smime_decrypt(mime_bytes, cert_path, key_path):
    """Decrypt an enveloped-data MIME entity. Returns (payload, error)."""
    if not os.path.exists(cert_path):
        return None, "AS2 decryption certificate not found: %s" % cert_path
    if not os.path.exists(key_path):
        return None, "AS2 decryption key not found: %s" % key_path
    rc, out, err = _as2_run_openssl(
        ["smime", "-decrypt", "-inform", "SMIME", "-recip", cert_path,
         "-inkey", key_path], mime_bytes)
    if rc is None:
        return None, err
    if rc != 0:
        return None, "openssl smime decrypt failed: %s" % (err[:200] or "exit %d" % rc)
    return out, ""


def _as2_extract_first_part(body, content_type):
    """First body part of a multipart/signed message, without any signature
    check (only used when openssl is unavailable). Returns (bytes, error)."""
    m = re.search(r"boundary=\"?([^\";\s]+)\"?", content_type or "", re.I)
    if not m:
        return None, "multipart/signed message has no boundary"
    boundary = m.group(1).encode("utf-8", "ignore")
    for part in body.split(b"--" + boundary)[1:]:
        if part.strip() in (b"--", b""):
            continue
        content = part
        ph = b""
        for sep in (b"\r\n\r\n", b"\n\n"):
            i = part.find(sep)
            if i >= 0:
                ph, content = part[:i], part[i + len(sep):]
                break
        content = content.strip()
        if content.endswith(b"--"):
            content = content[:-2].strip()
        if "base64" in ph.decode("utf-8", "ignore").lower():
            try:
                content = base64.b64decode(content)
            except Exception:
                return None, "signed part is not valid base64"
        return content, ""
    return None, "multipart/signed message has no content part"


def _as2_verify_signed(mime_bytes, cfg):
    """Verify a signed MIME entity (multipart/signed or opaque signed-data).
    Returns (payload, verified, error). A bad signature is refused, never
    accepted unverified -- even with no verification certificate configured,
    the integrity check must pass."""
    cert = (cfg.get("as2_verify_cert_path") or "").strip()
    ok, payload, verified, err = _as2_smime_verify(
        mime_bytes, cert if cert else None)
    if not ok:
        if cert:
            return None, False, err
        return None, False, ("AS2 signature does not verify (integrity check"
                             " failed) -- message refused")
    return payload, verified, ""


def _as2_unwrap_inbound(raw, content_type, cfg):
    """Unwrap an inbound AS2 body to its X12 payload. Returns
    (payload_bytes, signed, encrypted, verified, error)."""
    ct = (content_type or "").lower()
    if "pkcs7-mime" in ct:
        smime_type = ""
        m = re.search(r"smime-type\s*=\s*\"?([a-z\-]+)\"?", ct, re.I)
        if m:
            smime_type = m.group(1).lower()
        if smime_type == "enveloped-data":
            cert = (cfg.get("as2_decrypt_cert_path") or "").strip()
            key = (cfg.get("as2_decrypt_key_path") or "").strip()
            if not cert or not key:
                return (None, False, True, False,
                        "encrypted AS2 message cannot be decrypted: no decryption"
                        " certificate/key configured (as2_decrypt_cert_path /"
                        " as2_decrypt_key_path) -- message refused")
            dec, err = _as2_smime_decrypt(raw, cert, key)
            if err:
                return None, False, True, False, err
            _h, inner_ct, _b = _as2_split_mime(dec)
            if "multipart/signed" in inner_ct.lower() or "pkcs7-mime" in inner_ct.lower():
                p, s, _e, v, err2 = _as2_unwrap_inbound(dec, inner_ct, cfg)
                return p, s, True, v, err2
            return dec, False, True, False, ""
        payload, verified, err = _as2_verify_signed(raw, cfg)
        return payload, True, False, verified, err
    if "multipart/signed" in ct:
        payload, verified, err = _as2_verify_signed(raw, cfg)
        return payload, True, False, verified, err
    return raw, False, False, False, ""


def _as2_parse_mdn(body_bytes):
    """Parse an MDN receipt body. Returns (mdn_status, mdn_text):
    processed / failed / received, or ("", "") when the body carries no
    Disposition line at all (a 2xx with no MDN -- async MDN may follow)."""
    text = body_bytes.decode("utf-8", "ignore")
    m = re.search(r"^disposition:\s*(.+)$", text, re.I | re.M)
    if not m:
        return "", ""
    disp = m.group(1).strip()
    low = disp.lower()
    if "failed" in low or "rejected" in low:
        return "failed", disp
    if "processed" in low:
        return "processed", disp
    return "received", disp


def _as2_record(conn, partner_id, doc_id, direction, message_id, as2_from,
                as2_to, signed, encrypted, signature_verified, mdn_requested,
                mdn_status, mdn_text, http_status):
    now = datetime.now(timezone.utc).isoformat()
    cur = conn.execute(
        "INSERT INTO erp_edi_as2_messages (partner_id, doc_id, direction,"
        " message_id, as2_from, as2_to, signed, encrypted, signature_verified,"
        " mdn_requested, mdn_status, mdn_text, http_status, created_at)"
        " VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
        (partner_id, doc_id, direction, message_id, as2_from, as2_to,
         1 if signed else 0, 1 if encrypted else 0,
         1 if signature_verified else 0, 1 if mdn_requested else 0,
         mdn_status or "", mdn_text or "", int(http_status or 0), now))
    return cur.lastrowid


def _as2_message_dict(r):
    return {"id": r["id"], "partner_id": r["partner_id"], "doc_id": r["doc_id"],
            "direction": r["direction"], "message_id": r["message_id"],
            "as2_from": r["as2_from"], "as2_to": r["as2_to"],
            "signed": bool(r["signed"]), "encrypted": bool(r["encrypted"]),
            "signature_verified": bool(r["signature_verified"]),
            "mdn_requested": bool(r["mdn_requested"]),
            "mdn_status": r["mdn_status"], "mdn_text": r["mdn_text"],
            "http_status": r["http_status"], "created_at": r["created_at"]}


def _as2_build_mdn(our_id, partner_id, original_message_id, disposition):
    """Plain (unsigned) MDN, multipart/report. MDN signing is NOT
    implemented -- see SOP 5.35. Returns (body_bytes, content_type, msg_id)."""
    boundary = "mdn-" + secrets.token_hex(8)
    msg_id = _as2_new_message_id()
    body = ("--%s\r\nContent-Type: text/plain\r\n\r\n"
            "Your AS2 message was received.\r\n"
            "--%s\r\nContent-Type: message/disposition-notification\r\n\r\n"
            "Reporting-UA: Pop-A-Licious ERP\r\n"
            "Original-Recipient: rfc822; %s\r\n"
            "Final-Recipient: rfc822; %s\r\n"
            "Original-Message-ID: %s\r\n"
            "Disposition: %s\r\n"
            "--%s--\r\n" % (boundary, boundary, our_id, our_id,
                            original_message_id or "", disposition, boundary))
    ctype = ("multipart/report; report-type=disposition-notification;"
             " boundary=\"%s\"" % boundary)
    return body.encode("utf-8"), ctype, msg_id


def _edi_as2_send(cfg, x12_text, test_mode=False):
    """POST an X12 document as an AS2 message. Returns (ok, error, info)
    where info carries message_id, signed, encrypted, mdn_status, mdn_text
    and http_status. Refuses -- never silently sends unsigned -- when
    signing is on (the default) and no signing certificate/key is
    configured; likewise encryption without a partner certificate."""
    info = {"message_id": _as2_new_message_id(), "signed": False,
            "encrypted": False, "mdn_status": "", "mdn_text": "",
            "http_status": 0}
    url = ""
    if test_mode:
        url = (cfg.get("as2_test_url") or "").strip()
    if not url:
        url = (cfg.get("as2_url") or "").strip()
    if not url:
        return False, "no AS2 URL configured for partner", info
    our_id = (cfg.get("as2_our_id") or "").strip()
    partner_id = (cfg.get("as2_partner_id") or "").strip()
    if not our_id:
        return False, "no AS2 ID configured for this company (as2_our_id)", info
    if not partner_id:
        return False, "no partner AS2 ID configured (as2_partner_id)", info
    sign = cfg.get("as2_sign", True)
    sign = True if sign is None else bool(sign)
    encrypt = bool(cfg.get("as2_encrypt", False))
    mdn_requested = cfg.get("as2_mdn_requested", True)
    mdn_requested = True if mdn_requested is None else bool(mdn_requested)
    if (sign or encrypt) and shutil.which("openssl") is None:
        return False, ("openssl command not available on this server -- AS2"
                       " signing/encryption needs it"), info
    payload = x12_text.encode("utf-8")
    content_type = "application/edi-x12"
    body = payload
    mime = None
    if sign:
        cert = (cfg.get("as2_sign_cert_path") or "").strip()
        key = (cfg.get("as2_sign_key_path") or "").strip()
        if not cert or not key:
            return False, ("AS2 signing is on but no signing certificate/key is"
                           " configured (as2_sign_cert_path / as2_sign_key_path)"
                           " -- sending refused, never silently unsigned"), info
        mime, content_type, err = _as2_smime_sign(payload, cert, key)
        if err:
            return False, err, info
        info["signed"] = True
        _h, _ct, body = _as2_split_mime(mime)
    if encrypt:
        cert = (cfg.get("as2_encrypt_cert_path") or "").strip()
        if not cert:
            return False, ("AS2 encryption is on but no partner encryption"
                           " certificate is configured (as2_encrypt_cert_path)"
                           " -- sending refused"), info
        # Encrypt the full signed MIME entity (headers included) when
        # signing, so the receiver's decrypt yields a verifiable message.
        enc_src = mime if mime is not None else payload
        _mime2, content_type, err = _as2_smime_encrypt(enc_src, cert)
        if err:
            return False, err, info
        _h, _ct, body = _as2_split_mime(_mime2)
        info["encrypted"] = True
    headers = {"AS2-Version": "1.2", "AS2-From": our_id, "AS2-To": partner_id,
               "Message-ID": info["message_id"], "MIME-Version": "1.0",
               "Content-Type": content_type}
    if mdn_requested:
        headers["Disposition-Notification-To"] = (
            (cfg.get("as2_mdn_to") or our_id).strip() or our_id)
        headers["Disposition-Notification-Options"] = (
            "signed-receipt-protocol=optional, pkcs7-signature;"
            " signed-receipt-micalg=optional, sha256")
    try:
        resp = requests.post(url, data=body, headers=headers, timeout=30)
    except Exception as e:
        return False, "AS2 POST failed: %s" % e, info
    info["http_status"] = resp.status_code
    if not (200 <= resp.status_code < 300):
        return False, "AS2 HTTP %s from %s" % (resp.status_code, url), info
    if mdn_requested:
        mdn_status, mdn_text = _as2_parse_mdn(resp.content or b"")
        if mdn_status:
            info["mdn_status"] = mdn_status
            info["mdn_text"] = mdn_text
            if mdn_status == "failed":
                return False, "partner MDN reports failure: %s" % mdn_text, info
        else:
            info["mdn_status"] = "awaiting"
    return True, "", info


