def _faire_money_cents(price):
    """ExternalMoneyV2 {amount_minor, currency} -> integer cents."""
    if isinstance(price, dict):
        try:
            return int(price.get("amount_minor") or 0)
        except (TypeError, ValueError):
            return 0
    return 0


def _faire_match_flavor(conn, sku, product_name, variant_name):
    """Match a Faire line to a Pop-A-Licious flavor name. Returns the flavor
    name or None. Never invents a flavor. Order: exact SKU against POP-*
    item SKUs, exact normalized name, then longest normalized-substring
    (so 'Cheddar Jalapeño' beats 'Cheddar' for a Cheddar Jalapeño line)."""
    sku_norm = (sku or "").strip().upper()
    if sku_norm:
        row = conn.execute(
            "SELECT name FROM erp_items WHERE type = 'popcorn' AND UPPER(sku) = ?",
            (sku_norm,)).fetchone()
        if row:
            name = row["name"] or ""
            if name.endswith(" Popcorn"):
                return name[:-len(" Popcorn")]
            return name
        for fr in conn.execute("SELECT flavor_name FROM erp_flavor_categories").fetchall():
            if _faire_norm_name(fr["flavor_name"]) == _faire_norm_name(sku_norm):
                return fr["flavor_name"]
    candidates = []
    for text in (product_name, variant_name):
        n = _faire_norm_name(text)
        if not n:
            continue
        for fr in conn.execute("SELECT flavor_name FROM erp_flavor_categories").fetchall():
            fn = _faire_norm_name(fr["flavor_name"])
            if n == fn:
                return fr["flavor_name"]
            if fn and fn in n:
                candidates.append((len(fn), fr["flavor_name"]))
    if candidates:
        candidates.sort(reverse=True)
        return candidates[0][1]
    # UPC fallback (secondary only — name matching above wins): the line
    # carried a UPC instead of a POP-* SKU. 766429062677 is not in the map
    # by design (see _FAIRE_UPC_FLAVORS) — it must resolve by name.
    if sku_norm:
        flavor = _FAIRE_UPC_FLAVORS.get(sku_norm)
        if flavor:
            return flavor
    return None


def _faire_format_address(addr):
    """Join a Faire retailer address dict into one address string."""
    if not isinstance(addr, dict):
        return ""
    parts = []
    for key in ("address1", "address2", "street", "street1", "street2"):
        if addr.get(key):
            parts.append(str(addr[key]).strip())
    cityline = ", ".join(str(p) for p in (addr.get("city"), addr.get("state"),
                                          addr.get("postal_code") or addr.get("zip")) if p)
    if cityline:
        parts.append(cityline)
    if addr.get("country"):
        parts.append(str(addr["country"]).strip())
    return ", ".join(p for p in parts if p)


def _faire_payment_terms(raw):
    """NET_30 / NET_60 -> 'Net 30' / 'Net 60'; anything else passes through."""
    raw = (raw or "").strip()
    if raw.upper().startswith("NET_"):
        return "Net " + raw[4:]
    return raw


def _faire_resolve_retailer(order, token, is_oauth):
    """Find a name (and address) for the wholesale account of a Faire order.
    The /orders list payload carries only retailer_id — the retailer
    object itself usually arrives with a name, but live orders Nov 16,
    2026 arrived with retailer={} and no name. Fallback chain:
    retailer.name -> GET /retailers/<retailer_id> -> order ship-to
    address name -> buyer first+last name. Returns (name, address, source)
    with source one of retailer / retailer_lookup / ship_to / customer,
    or (None, {}, None) when nothing names the buyer. A failed retailer
    lookup falls through to the next source instead of failing."""
    retailer = order.get("retailer") or {}
    name = ((retailer.get("name") or "").strip()
            if isinstance(retailer, dict) else "")
    if name:
        return name, ((retailer.get("address") or {})
                      if isinstance(retailer, dict) else {}), "retailer"
    rid = str(order.get("retailer_id") or "").strip()
    if rid:
        status, data = _faire_request("GET", "/retailers/%s" % rid,
                                      access_token=token, is_oauth=is_oauth)
        if status == 200 and isinstance(data, dict):
            r = data.get("retailer") if isinstance(
                data.get("retailer"), dict) else data
            rname = ((r.get("name") or "").strip()
                     if isinstance(r, dict) else "")
            if rname:
                return rname, ((r.get("address") or {})
                               if isinstance(r, dict) else {}), "retailer_lookup"
    ship = order.get("address") or {}
    sname = ((ship.get("name") or "").strip()
             if isinstance(ship, dict) else "")
    if sname:
        return sname, ship, "ship_to"
    customer = order.get("customer") or {}
    if not isinstance(customer, dict):
        customer = {}
    cname = " ".join(p for p in ((customer.get("first_name") or ""),
                                 (customer.get("last_name") or "")) if p).strip()
    if cname:
        return cname, (ship if isinstance(ship, dict) else {}), "customer"
    return None, {}, None


def _faire_match_or_create_account(conn, retailer, customer, payment_terms, actor):
    """Match a Faire retailer to a wholesale account by name (case-insensitive);
    create it with the $4/$4 defaults when new. Returns (account_row, created)."""
    name = ((retailer or {}).get("name") or "").strip()
    if not name:
        return None, False
    acct = conn.execute(
        "SELECT * FROM erp_wholesale_accounts WHERE LOWER(name) = LOWER(?)",
        (name,)).fetchone()
    if acct:
        return acct, False
    contact = " ".join(p for p in (((customer or {}).get("first_name") or ""),
                                    ((customer or {}).get("last_name") or "")) if p).strip()
    now = datetime.now(timezone.utc).isoformat()
    cur = conn.execute(
        "INSERT INTO erp_wholesale_accounts (name, contact_name, email, phone, address,"
        " price_per_bag_cents, savory_price_cents, sweet_price_cents, payment_terms,"
        " notes, active, staff_managed, created_by, created_at)"
        " VALUES (?, ?, '', '', ?, 400, 400, 400, ?, ?, 1, 1, ?, ?)",
        (name, contact, _faire_format_address((retailer or {}).get("address") or {}),
         _faire_payment_terms(payment_terms),
         "Created by Faire auto-import", actor, now))
    acct = conn.execute("SELECT * FROM erp_wholesale_accounts WHERE id = ?",
                        (cur.lastrowid,)).fetchone()
    return acct, True


def _faire_log(conn, faire_order_id, display_id, state, outcome, matched,
               unmatched, qb_status, notes):
    """One import-log row (the Order hub Faire section reads these)."""
    now = datetime.now(timezone.utc).isoformat()
    cur = conn.execute(
        "INSERT INTO erp_faire_import_log (faire_order_id, display_id, state, outcome,"
        " matched_lines, unmatched_lines, qb_status, notes, created_at)"
        " VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)",
        (faire_order_id, display_id, state, outcome,
         json.dumps(matched or []), json.dumps(unmatched or []),
         qb_status or "", notes or "", now))
    return cur.lastrowid


def _faire_backfill_lines(conn, wholesale_order_id, order):
    """Append lines a first import dropped because they did not match a flavor
    then. Returns (added, still_unmatched). Only appends what the ERP order
    does not already cover (by flavor + quantity), never touches lines
    already on the order, and never re-prices them. The caller only runs
    this for an importable Faire state."""
    orow = conn.execute(
        "SELECT * FROM erp_wholesale_orders WHERE id = ?",
        (wholesale_order_id,)).fetchone()
    if not orow:
        return [], []
    acct = conn.execute(
        "SELECT * FROM erp_wholesale_accounts WHERE id = ?",
        (orow["account_id"],)).fetchone()
    if not acct:
        return [], []
    covered = {}
    for r in conn.execute(
            "SELECT flavor_name, qty_bags FROM erp_wholesale_order_lines"
            " WHERE order_id = ?", (wholesale_order_id,)).fetchall():
        covered[r["flavor_name"]] = covered.get(r["flavor_name"], 0) + float(r["qty_bags"] or 0)
    added = []
    still = []
    for it in order.get("items") or []:
        if not isinstance(it, dict) or it.get("excluded"):
            continue
        if str(it.get("state") or "").upper() == "CANCELED":
            continue
        try:
            qty = float(it.get("quantity") or 0)
        except (TypeError, ValueError):
            qty = 0
        if qty <= 0:
            continue
        flavor = _faire_match_flavor(conn, it.get("sku"), it.get("product_name"),
                                     it.get("variant_name"))
        if not flavor:
            still.append({"sku": it.get("sku") or "",
                          "product_name": it.get("product_name") or "",
                          "variant_name": it.get("variant_name") or "",
                          "qty": qty})
            continue
        add_qty = qty - covered.get(flavor, 0)
        if add_qty <= 0:
            continue
        unit, _cat = _wholesale_flavor_price(conn, acct, flavor, add_qty)
        conn.execute(
            "INSERT INTO erp_wholesale_order_lines (order_id, flavor_name, qty_bags,"
            " unit_price_cents, line_total_cents) VALUES (?, ?, ?, ?, ?)",
            (wholesale_order_id, flavor, add_qty, unit, int(round(add_qty * unit))))
        covered[flavor] = covered.get(flavor, 0) + add_qty
        added.append({"flavor_name": flavor, "qty_bags": add_qty,
                      "unit_price_cents": unit,
                      "line_total_cents": int(round(add_qty * unit)),
                      "faire_price_cents": _faire_money_cents(it.get("price"))})
    if added:
        note = "dropped lines backfilled %s: %s" % (
            datetime.now(timezone.utc).strftime("%Y-%m-%d"),
            ", ".join("%s x%s" % (a["flavor_name"], a["qty_bags"]) for a in added))
        conn.execute(
            "UPDATE erp_wholesale_orders SET notes = CASE WHEN notes IS NULL OR notes = ''"
            " THEN ? ELSE notes || '; ' || ? END WHERE id = ?",
            (note, note, wholesale_order_id))
    return added, still


def _faire_import_order(conn, order, actor, token=None, is_oauth=False):
    """Import one Faire order. Returns a result dict for the summary/log.
    Never raises for a bad order — problems are recorded, not fatal."""
    faire_id = str(order.get("id") or "")
    display_id = str(order.get("display_id") or faire_id)
    state = str(order.get("state") or "").upper()
    now = datetime.now(timezone.utc).isoformat()
    existing = None
    if faire_id:
        existing = conn.execute(
            "SELECT * FROM erp_faire_orders WHERE faire_order_id = ?",
            (faire_id,)).fetchone()
    if existing:
        # Already imported: track the Faire state. The ERP order itself is
        # never re-priced or re-named — except for lines the first import
        # dropped because they did not match a flavor then (backfill, Nov 17,
        # 2026: the matcher was fixed after two orders imported short).
        changed = (existing["state"] or "") != state
        conn.execute("UPDATE erp_faire_orders SET state = ?, last_seen_at = ? WHERE id = ?",
                     (state, now, existing["id"]))
        note = ""
        if changed and state == "CANCELED":
            note = "Faire state changed to CANCELED — ERP order left as-is for review"
            conn.execute("UPDATE erp_faire_orders SET needs_review = 1 WHERE id = ?",
                         (existing["id"],))
        backfilled = []
        still_unmatched = []
        if state in _FAIRE_IMPORTABLE_STATES and existing["wholesale_order_id"]:
            backfilled, still_unmatched = _faire_backfill_lines(
                conn, existing["wholesale_order_id"], order)
        if backfilled:
            if still_unmatched:
                conn.execute("UPDATE erp_faire_orders SET needs_review = 1 WHERE id = ?",
                             (existing["id"],))
            _faire_log(conn, faire_id, display_id, state, "backfilled",
                       backfilled, still_unmatched, "",
                       "dropped lines backfilled after matcher fix: %s"
                       % ", ".join("%s x%s" % (b["flavor_name"], b["qty_bags"])
                                   for b in backfilled))
            _onumber = conn.execute(
                "SELECT order_number FROM erp_wholesale_orders WHERE id = ?",
                (existing["wholesale_order_id"],)).fetchone()
            return {"outcome": "backfilled", "faire_order_id": faire_id,
                    "display_id": display_id, "state": state,
                    "order_id": existing["wholesale_order_id"],
                    "order_number": _onumber["order_number"] if _onumber else "",
                    "matched": backfilled, "unmatched": still_unmatched,
                    "needs_review": bool(still_unmatched), "note": note}
        _faire_log(conn, faire_id, display_id, state,
                   "state_updated" if changed else "already_seen",
                   [], [], "", note)
        return {"outcome": "state_updated" if changed else "already_seen",
                "faire_order_id": faire_id, "display_id": display_id,
                "state": state, "order_id": existing["wholesale_order_id"],
                "needs_review": bool(changed and state == "CANCELED"), "note": note}
    if state in _FAIRE_SKIP_STATES:
        _faire_log(conn, faire_id, display_id, state, "skipped", [], [], "",
                   "state %s is not imported" % state)
        return {"outcome": "skipped", "faire_order_id": faire_id,
                "display_id": display_id, "state": state}
    if state not in _FAIRE_IMPORTABLE_STATES:
        _faire_log(conn, faire_id, display_id, state, "skipped", [], [], "",
                   "unknown state %s" % (state or "?"))
        return {"outcome": "skipped", "faire_order_id": faire_id,
                "display_id": display_id, "state": state}
    name, addr, name_source = _faire_resolve_retailer(order, token, is_oauth)
    if not name:
        _faire_log(conn, faire_id, display_id, state, "error", [], [], "",
                   "retailer has no name")
        return {"outcome": "error", "faire_order_id": faire_id,
                "display_id": display_id, "state": state,
                "error": "retailer has no name"}
    acct, created = _faire_match_or_create_account(
        conn, {"name": name, "address": addr}, order.get("customer") or {},
        order.get("payment_terms") or "", actor)
    matched, unmatched = [], []
    for it in order.get("items") or []:
        if not isinstance(it, dict):
            continue
        if it.get("excluded"):
            continue
        if str(it.get("state") or "").upper() == "CANCELED":
            continue
        try:
            qty = float(it.get("quantity") or 0)
        except (TypeError, ValueError):
            qty = 0
        if qty <= 0:
            continue
        flavor = _faire_match_flavor(conn, it.get("sku"), it.get("product_name"),
                                     it.get("variant_name"))
        if not flavor:
            unmatched.append({"sku": it.get("sku") or "",
                              "product_name": it.get("product_name") or "",
                              "variant_name": it.get("variant_name") or "",
                              "qty": qty})
            continue
        unit, _cat = _wholesale_flavor_price(conn, acct, flavor, qty)
        matched.append({"flavor_name": flavor, "qty_bags": qty,
                        "unit_price_cents": unit,
                        "line_total_cents": int(round(qty * unit)),
                        "faire_price_cents": _faire_money_cents(it.get("price"))})
    if not matched:
        _faire_log(conn, faire_id, display_id, state, "no_matched_lines",
                   [], unmatched, "", "no lines matched a flavor")
        return {"outcome": "no_matched_lines", "faire_order_id": faire_id,
                "display_id": display_id, "state": state,
                "unmatched": unmatched, "needs_review": True}
    notes = ["Faire %s" % display_id]
    needs_review = False
    if name_source == "retailer_lookup":
        needs_review = True
        notes.append("retailer name from Faire retailer lookup")
    elif name_source == "ship_to":
        needs_review = True
        notes.append("retailer name missing — account named from ship-to name")
    elif name_source == "customer":
        needs_review = True
        notes.append("retailer name missing — account named from buyer name")
    if unmatched:
        needs_review = True
        notes.append("unmatched lines skipped: %s" % ", ".join(
            (u.get("sku") or u.get("product_name") or "?") for u in unmatched))
    if state == "BACKORDERED":
        needs_review = True
        notes.append("Faire state BACKORDERED — check stock before fulfilling")
    total = sum(li["line_total_cents"] for li in matched)
    refusal = _erp_wholesale_check_credit(conn, acct, total)
    if refusal:
        # Unlike manual entry (which refuses), the import keeps the order and
        # flags it — a Faire order must never vanish silently on credit.
        needs_review = True
        notes.append("credit check: %s" % refusal)
    if not acct["active"]:
        needs_review = True
        notes.append("account is inactive — review before fulfilling")
    order_number = _erp_next_wholesale_number(conn)
    created_at = str(order.get("created_at") or "")
    order_date = created_at[:10] if len(created_at) >= 10 else ""
    ship_date = str(order.get("expected_ship_date") or "")
    cur = conn.execute(
        "INSERT INTO erp_wholesale_orders (order_number, account_id, status, order_date,"
        " due_date, notes, via_faire, faire_order_id, created_by, created_at)"
        " VALUES (?, ?, 'new', ?, ?, ?, 1, ?, ?, ?)",
        (order_number, acct["id"], order_date,
         ship_date[:10] if len(ship_date) >= 10 else "",
         "; ".join(notes), faire_id, actor, now))
    order_id = cur.lastrowid
    for li in matched:
        conn.execute(
            "INSERT INTO erp_wholesale_order_lines (order_id, flavor_name, qty_bags,"
            " unit_price_cents, line_total_cents) VALUES (?, ?, ?, ?, ?)",
            (order_id, li["flavor_name"], li["qty_bags"],
             li["unit_price_cents"], li["line_total_cents"]))
    _erp_set_fulfillment(conn, "wholesale", order_id, "new", actor,
                         "created from Faire %s" % display_id)
    conn.execute(
        "INSERT INTO erp_faire_orders (faire_order_id, wholesale_order_id, display_id,"
        " state, needs_review, last_seen_at, created_at) VALUES (?, ?, ?, ?, ?, ?, ?)",
        (faire_id, order_id, display_id, state, 1 if needs_review else 0, now, now))
    _faire_log(conn, faire_id, display_id, state, "imported", matched, unmatched,
               "", "; ".join(notes))
    return {"outcome": "imported", "faire_order_id": faire_id,
            "display_id": display_id, "state": state, "order_id": order_id,
            "order_number": order_number, "matched": matched,
            "unmatched": unmatched, "needs_review": needs_review,
            "account_created": created}


def _faire_push_unpushed(conn, actor, summary):
    """Attempt the QuickBooks push for Faire orders not yet pushed.
    Returns (pushed, skipped). Never raises — a failed push is recorded
    in the summary and the order stays pushable manually later."""
    pushed = 0
    skipped = 0
    rows = conn.execute(
        "SELECT fo.faire_order_id, fo.display_id, fo.state, fo.wholesale_order_id"
        " FROM erp_faire_orders fo WHERE fo.wholesale_order_id > 0"
        " ORDER BY fo.id").fetchall()
    for r in rows:
        if _qb_pushed(conn, "wholesale_order", r["wholesale_order_id"], "invoice"):
            continue
        status, payload = _qb_push_wholesale_invoice(
            conn, r["wholesale_order_id"], actor)
        if status == 201:
            pushed += 1
            qb_status = "pushed"
        elif status == 409:
            pushed += 1
            qb_status = "pushed"
        elif status == 400 and payload.get("error") in (
                "QuickBooks not connected",
                "configure the QuickBooks wholesale item first"):
            skipped += 1
            qb_status = "skipped"
        else:
            summary["errors"].append(
                "%s: QuickBooks push failed (%s)"
                % (r["display_id"], payload.get("error") or status))
            qb_status = "error"
        conn.execute(
            "UPDATE erp_faire_import_log SET qb_status = ? WHERE id = ("
            "SELECT MAX(id) FROM erp_faire_import_log WHERE faire_order_id = ?)",
            (qb_status, r["faire_order_id"]))
    return pushed, skipped


@app.post("/api/erp/faire/sync")
def erp_faire_sync():
    """Poll Faire for new/updated orders and import them as wholesale orders.
    Cron-secret gated (X-Cron-Secret) or an admin session with orders.write.
    After import, auto-pushes new and previously-unpushed Faire orders to
    QuickBooks through the same push the manual endpoint uses."""
    secret = CRON_SECRET
    header = request.headers.get("X-Cron-Secret")
    if header is not None:
        if not secret:
            return jsonify(error="cron not configured"), 503
        if header != secret:
            return jsonify(error="forbidden"), 403
        actor = "cron"
    else:
        actor, err = _erp_check_perm("orders.write")
        if err:
            return err
    token, auth_err, is_oauth = _faire_authenticate()
    if auth_err:
        return jsonify(error=auth_err), 503
    conn = db()
    row = conn.execute("SELECT * FROM erp_faire_sync WHERE id = 1").fetchone()
    watermark = (row["last_updated_at_min"] if row and row["last_updated_at_min"] else "")
    run_start = datetime.now(timezone.utc)
    if not watermark:
        watermark = (run_start - timedelta(days=7)).isoformat()
    # Admin re-run window: POST {"since": "<ISO 8601>"} to re-pull orders
    # updated at or after that time (the stored watermark is still
    # advanced from what this run actually sees). Used Nov 16, 2026 to
    # re-fetch two orders that errored on a missing retailer name.
    _since = ((request.get_json(silent=True) or {}).get("since") or "")
    if isinstance(_since, str) and _since.strip():
        try:
            datetime.fromisoformat(_since.strip().replace("Z", "+00:00"))
            watermark = _since.strip()
        except (TypeError, ValueError):
            pass
    summary = {"imported": 0, "skipped": 0, "already_seen": 0, "backfilled": 0,
               "qb_pushed": 0,
               "qb_skipped": 0, "errors": [], "stopped_on_429": False,
               "orders": []}
    cursor = None
    max_seen = None
    stopped = False
    while True:
        # Faire caps limit at 50 — limit=100 answers HTTP 400
        # ("limit must be within [10, 50]", found live Nov 16, 2026).
        params = {"updated_at_min": watermark, "sort_by": "UPDATED_AT", "limit": 50}
        if cursor:
            params["cursor"] = cursor
        status, data = _faire_request("GET", "/orders", params=params,
                                      access_token=token, is_oauth=is_oauth)
        if status == 429:
            summary["stopped_on_429"] = True
            summary["errors"].append(
                "Faire rate limited (429) — stopping, will resume next run")
            # Dept 10 Wave A: run-level failures are also written to the
            # import log, so the Settings health page can show them from
            # stored data (a 401 stops the poll before any order is seen,
            # so without this row there would be nothing in the log).
            _faire_log(conn, "", "", "", "error", [], [], "",
                       "Faire rate limited (429) — stopping, will resume next run")
            stopped = True
            break
        if status == 0:
            summary["errors"].append(
                "Faire request failed: %s" % (data.get("error") or "network error"))
            _faire_log(conn, "", "", "", "error", [], [], "",
                       "Faire request failed: %s" % (data.get("error") or "network error"))
            stopped = True
            break
        if status != 200:
            summary["errors"].append(
                "Faire orders request failed (HTTP %s)" % status)
            _faire_log(conn, "", "", "", "error", [], [], "",
                       "Faire orders request failed (HTTP %s)" % status)
            stopped = True
            break
        for o in data.get("orders") or []:
            if not isinstance(o, dict) or not o.get("id"):
                continue
            upd = str(o.get("updated_at") or "")
            if upd and (max_seen is None or upd > max_seen):
                max_seen = upd
            try:
                res = _faire_import_order(conn, o, actor, token, is_oauth)
            except Exception as e:
                res = {"outcome": "error",
                       "faire_order_id": str(o.get("id") or ""),
                       "display_id": str(o.get("display_id") or ""),
                       "state": str(o.get("state") or ""), "error": str(e)}
                _faire_log(conn, res["faire_order_id"], res["display_id"],
                           res["state"], "error", [], [], "",
                           "import failed: %s" % str(e))
            summary["orders"].append({
                "faire_order_id": res.get("faire_order_id", ""),
                "display_id": res.get("display_id", ""),
                "state": res.get("state", ""),
                "outcome": res.get("outcome", ""),
                "order_id": res.get("order_id"),
                "order_number": res.get("order_number", ""),
                "needs_review": bool(res.get("needs_review"))})
            if res["outcome"] == "imported":
                summary["imported"] += 1
            elif res["outcome"] == "backfilled":
                summary["backfilled"] += 1
            elif res["outcome"] in ("already_seen", "state_updated"):
                summary["already_seen"] += 1
            elif res["outcome"] in ("skipped", "no_matched_lines"):
                summary["skipped"] += 1
            else:
                summary["errors"].append(
                    "%s: %s" % (res.get("display_id") or res.get("faire_order_id"),
                                res.get("error") or res.get("outcome")))
        cursor = data.get("cursor") or None
        if not cursor:
            break
    new_watermark = watermark
    if not stopped:
        if max_seen:
            try:
                dt = datetime.fromisoformat(max_seen.replace("Z", "+00:00"))
                new_watermark = (dt - timedelta(seconds=1)).isoformat()
            except (TypeError, ValueError):
                new_watermark = max_seen
        else:
            new_watermark = run_start.isoformat()
    conn.execute(
        "INSERT OR REPLACE INTO erp_faire_sync (id, last_updated_at_min,"
        " last_run_at, last_summary) VALUES (1, ?, ?, ?)",
        (new_watermark, run_start.isoformat(), json.dumps(summary)))
    conn.commit()
    # Auto-push to QuickBooks: new imports + previously-imported unpushed orders.
    pushed, skipped = _faire_push_unpushed(conn, actor, summary)
    summary["qb_pushed"] = pushed
    summary["qb_skipped"] = skipped
    conn.execute("UPDATE erp_faire_sync SET last_summary = ? WHERE id = 1",
                 (json.dumps(summary),))
    conn.commit()
    conn.close()
    return jsonify(summary)


@app.get("/api/erp/faire/status")
def erp_faire_status():
    """Faire sync state for the Order hub section: last run, counts, config."""
    actor, err = _erp_check_perm("orders.read")
    if err:
        return err
    conn = db()
    row = conn.execute("SELECT * FROM erp_faire_sync WHERE id = 1").fetchone()
    orow = _faire_oauth_row(conn)
    imported = conn.execute("SELECT COUNT(*) FROM erp_faire_orders").fetchone()[0]
    pending = conn.execute(
        "SELECT COUNT(*) FROM erp_faire_orders WHERE needs_review = 1").fetchone()[0]
    last = {}
    if row and row["last_summary"]:
        try:
            last = json.loads(row["last_summary"])
        except (TypeError, ValueError):
            last = {}
    conn.close()
    return jsonify({
        "configured": bool(os.environ.get("FAIRE_APP_ID")
                           and os.environ.get("FAIRE_APP_SECRET")
                           and os.environ.get("FAIRE_ACCESS_TOKEN")),
        "oauth_connected": bool(orow and (orow["access_token"] or "")),
        "oauth_connected_at": (orow["obtained_at"] if orow else "") or "",
        "last_run_at": row["last_run_at"] if row else "",
        "last_updated_at_min": row["last_updated_at_min"] if row else "",
        "last_summary": last,
        "orders_imported": imported,
        "pending_review": pending,
    })


@app.get("/api/erp/faire/import-log")
def erp_faire_import_log():
    """Recent Faire import-log rows, newest first (limit 50)."""
    actor, err = _erp_check_perm("orders.read")
    if err:
        return err
    conn = db()
    rows = conn.execute(
        "SELECT * FROM erp_faire_import_log ORDER BY id DESC LIMIT 50").fetchall()
    out = []
    for r in rows:
        d = dict(r)
        for key in ("matched_lines", "unmatched_lines"):
            try:
                d[key] = json.loads(d[key] or "[]")
            except (TypeError, ValueError):
                d[key] = []
        out.append(d)
    conn.close()
    return jsonify(log=out)


@app.get("/api/erp/faire/connect")
def erp_faire_connect():
    """Start the Faire OAuth authorization-code flow: mint a signed,
    time-limited state token and return the Faire authorize URL for the
    admin's browser. Admin session with orders.write."""
    actor, err = _erp_check_perm("orders.write")
    if err:
        return err
    app_id = os.environ.get("FAIRE_APP_ID", "").strip()
    app_secret = os.environ.get("FAIRE_APP_SECRET", "").strip()
    if not app_id or not app_secret:
        return jsonify(error="Faire not configured (FAIRE_APP_ID / FAIRE_APP_SECRET missing)"), 503
    params = {
        "applicationId": app_id,
        "scope": ",".join(_FAIRE_OAUTH_SCOPE),
        "state": _faire_state_token(actor),
        "redirectUrl": _FAIRE_CALLBACK_URL,
    }
    return jsonify({"authorize_url": _FAIRE_AUTHORIZE_URL + "?" + urlencode(params)})


@app.get("/api/erp/faire/callback")
def erp_faire_callback():
    # Browser redirect from Faire; no ERP session. The signed `state`
    # binds this callback to the admin who started the flow, and the
    # authorization code expires within 10 minutes.
    email = _faire_state_email(request.args.get("state") or "")
    if not email:
        return Response("Invalid or expired Faire authorization state",
                        status=400, mimetype="text/plain")
    code = request.args.get("code") or ""
    if not code:
        return Response("Missing Faire authorization code",
                        status=400, mimetype="text/plain")
    app_id = os.environ.get("FAIRE_APP_ID", "").strip()
    app_secret = os.environ.get("FAIRE_APP_SECRET", "").strip()
    if not app_id or not app_secret:
        return Response("Faire not configured (FAIRE_APP_ID / FAIRE_APP_SECRET missing)",
                        status=502, mimetype="text/plain")
    data, err = _faire_exchange_token(code)
    if err or not data or not data.get("access_token"):
        return Response("Faire token exchange failed",
                        status=502, mimetype="text/plain")
    conn = db()
    _faire_store_oauth_token(conn, data.get("access_token", ""),
                             data.get("token_type", ""),
                             ",".join(_FAIRE_OAUTH_SCOPE))
    conn.close()
    return redirect(_FAIRE_FRONTEND_URL + "/#/orders")


@app.post("/api/erp/faire/disconnect")
def erp_faire_disconnect():
    """Disconnect Faire OAuth: best-effort revoke, then delete the stored
    token. Admin session with orders.write."""
    actor, err = _erp_check_perm("orders.write")
    if err:
        return err
    conn = db()
    row = _faire_oauth_row(conn)
    if row and (row["access_token"] or ""):
        _faire_revoke_token(row["access_token"])
    conn.execute("DELETE FROM erp_faire_oauth WHERE id = 1")
    conn.commit()
    conn.close()
    return jsonify({"connected": False})


# Test hook: tests assign backend._QBO_TEST_DOUBLE to a fake implementing
# find_customer / create_customer / create_invoice / create_sales_receipt.
# The suite must NEVER make live Intuit calls.
_QBO_TEST_DOUBLE = None


class _QBOError(Exception):
    def __init__(self, message, status=502):
        super().__init__(message)
        self.status = status


class _QBOUnauthorized(_QBOError):
    pass


class _QBOClient:
    """Minimal QBO REST v3 client. `http` is injectable (tests assert no
    real network by injecting a recording fake)."""

    def __init__(self, access_token, realm_id, http=None):
        self.access_token = access_token
        self.realm_id = realm_id
        self.http = http or requests

    def _url(self, path):
        return "%s/%s/%s" % (_QB_API_BASE, self.realm_id, path)

    def _headers(self):
        return {"Authorization": "Bearer " + self.access_token,
                "Accept": "application/json",
                "Content-Type": "application/json"}

    def _call(self, method, path, params=None, payload=None):
        url = self._url(path)
        try:
            if method == "get":
                r = self.http.get(url, headers=self._headers(),
                                  params=params, timeout=25)
            else:
                r = self.http.post(url, headers=self._headers(), params=params,
                                   data=json.dumps(payload or {}), timeout=25)
        except Exception as e:
            raise _QBOError("QuickBooks request failed: %s" % e)
        if r.status_code == 401:
            raise _QBOUnauthorized("QuickBooks token expired")
        if r.status_code >= 400:
            detail = ""
            try:
                errs = (r.json().get("Fault") or {}).get("Error") or []
                detail = (errs[0] or {}).get("Detail", "") if errs else ""
            except Exception:
                detail = ""
            raise _QBOError("QuickBooks error %s: %s"
                            % (r.status_code, detail or r.text[:200]))
        try:
            return r.json()
        except Exception:
            raise _QBOError("QuickBooks returned a non-JSON response")

    def query(self, qbo_query):
        return self._call("get", "query",
                          params={"query": qbo_query, "minorversion": "65"})

    def find_customer(self, display_name):
        safe = (display_name or "").replace("'", "''")
        data = self.query("select * from Customer where DisplayName = '%s'" % safe)
        custs = ((data.get("QueryResponse") or {}).get("Customer") or [])
        return custs[0] if custs else None

    def create_customer(self, display_name, email=""):
        payload = {"DisplayName": display_name}
        if email:
            payload["PrimaryEmailAddr"] = {"Address": email}
        return self._call("post", "customer",
                          params={"minorversion": "65"}, payload=payload).get("Customer") or {}

    def create_invoice(self, payload):
        return self._call("post", "invoice",
                          params={"minorversion": "65"}, payload=payload).get("Invoice") or {}

    def create_sales_receipt(self, payload):
        return self._call("post", "salesreceipt",
                          params={"minorversion": "65"}, payload=payload).get("SalesReceipt") or {}


def _qb_creds():
    return (os.environ.get("QB_CLIENT_ID") or "",
            os.environ.get("QB_CLIENT_SECRET") or "")


def _qb_redirect_uri():
    return (os.environ.get("QB_REDIRECT_URI") or
            "https://popalicious-gift-cards-production.up.railway.app"
            "/api/erp/quickbooks/callback")


def _qb_frontend_url():
    return os.environ.get("QB_FRONTEND_URL") or "https://erp.pop-a-licious.com"


def _qb_state_token(email):
    s = URLSafeTimedSerializer(AUTH_SECRET, salt="popalicious-qb-oauth")
    return s.dumps({"email": email})


def _qb_state_email(state, max_age=600):
    s = URLSafeTimedSerializer(AUTH_SECRET, salt="popalicious-qb-oauth")
    try:
        return s.loads(state, max_age=max_age).get("email")
    except (BadSignature, SignatureExpired):
        return None


def _qb_tokens(conn):
    return conn.execute("SELECT * FROM erp_qb_oauth WHERE id = 1").fetchone()


def _qb_connected(conn):
    if _QBO_TEST_DOUBLE is not None:
        return True
    tok = _qb_tokens(conn)
    return bool(tok and tok["access_token"] and tok["realm_id"])


def _qb_config(conn, key, default=""):
    row = conn.execute("SELECT value FROM erp_qb_config WHERE key = ?", (key,)).fetchone()
    return row["value"] if row else default


def _qb_pushed(conn, entity_type, entity_id, qb_object):
    return conn.execute(
        "SELECT qb_id FROM erp_qb_links WHERE entity_type = ? AND entity_id = ?"
        " AND qb_object = ?", (entity_type, entity_id, qb_object)).fetchone()


def _qb_store_tokens(conn, access_token, refresh_token, expires_in, realm_id,
                     company_name=""):
    now = datetime.now(timezone.utc)
    conn.execute(
        "INSERT OR REPLACE INTO erp_qb_oauth (id, access_token, refresh_token,"
        " expires_at, realm_id, company_name, updated_at)"
        " VALUES (1, ?, ?, ?, ?, ?, ?)",
        (access_token, refresh_token,
         int(now.timestamp()) + int(expires_in or 3600),
         realm_id, company_name, now.isoformat()))
    conn.commit()


def _qb_refresh_tokens(conn):
    tok = _qb_tokens(conn)
    if not tok or not tok["refresh_token"]:
        return False
    cid, csec = _qb_creds()
    try:
        r = requests.post(_QB_TOKEN_URL,
                          data={"grant_type": "refresh_token",
                                "refresh_token": tok["refresh_token"]},
                          auth=(cid, csec), timeout=25)
    except Exception:
        return False
    if r.status_code != 200:
        return False
    try:
        data = r.json()
    except Exception:
        return False
    _qb_store_tokens(conn, data.get("access_token", ""),
                     data.get("refresh_token", tok["refresh_token"]),
                     data.get("expires_in", 3600), tok["realm_id"],
                     tok["company_name"])
    return True


def _qb_call_with_refresh(conn, fn):
    """Runs fn(client), refreshing the OAuth token once on expiry.

    With the test double set, fn runs against the fake and no network
    is touched. Raises _QBOError on failure; never retries a push.
    """
    if _QBO_TEST_DOUBLE is not None:
        return fn(_QBO_TEST_DOUBLE)
    tok = _qb_tokens(conn)
    if not tok or not tok["access_token"]:
        raise _QBOError("QuickBooks not connected", status=400)
    client = _QBOClient(tok["access_token"], tok["realm_id"])
    try:
        return fn(client)
    except _QBOUnauthorized:
        if _qb_refresh_tokens(conn):
            tok = _qb_tokens(conn)
            return fn(_QBOClient(tok["access_token"], tok["realm_id"]))
        conn.execute("UPDATE erp_qb_oauth SET access_token = '' WHERE id = 1")
        conn.commit()
        raise _QBOError("QuickBooks session expired - please reconnect", status=400)


# ---------- Dept 10 Settings Wave A ----------
# Item 1: company / legal-entity profile (single row, erp_company_profile).
# Item 2: integration health (Settings subview; no live pings, no new
# credentials -- status comes from env/config flags plus stored activity).
_ERP_COMPANY_PROFILE_DEFAULTS = {
    "legal_name": "FUDGETOPIA LLC",
    "facility_address": "6290 McLeod Dr, Suite 120, Las Vegas, NV 89120",
    "office_address": "2013 Angel Falls Dr, Henderson, NV 89074",
    "ein": "",
    "fiscal_year": "",
    "base_currency": "USD",
}


def _erp_company_profile(conn):
    """The company profile as a dict. A missing row (e.g. after a wipe,
    before the next restart re-seeds) falls back to the known defaults,
    so invoices, statements and tax filings never render a blank header.
    EIN / fiscal year stay blank when unknown -- never invented."""
    try:
        row = conn.execute(
            "SELECT * FROM erp_company_profile WHERE id = 1").fetchone()
    except Exception:
        row = None
    out = dict(_ERP_COMPANY_PROFILE_DEFAULTS)
    out["updated_by"] = ""
    out["updated_at"] = ""
    if row:
        d = dict(row)
        for key in _ERP_COMPANY_PROFILE_DEFAULTS:
            out[key] = d.get(key) or ""
        out["updated_by"] = d.get("updated_by") or ""
        out["updated_at"] = d.get("updated_at") or ""
    return out


def _erp_company_profile_validate(data):
    """Validate a profile PUT body. Returns (clean, None) or (None, error).
    Only keys present in the body are updated; unknown keys are ignored.
    EIN and fiscal year may be cleared back to blank ("not provided")."""
    if not isinstance(data, dict):
        return None, "profile must be an object"
    clean = {}
    for key in ("legal_name", "facility_address", "office_address"):
        if key in data:
            val = data[key]
            if not isinstance(val, str) or not val.strip():
                return None, "%s must be a non-empty string" % key
            if len(val.strip()) > 500:
                return None, "%s is too long" % key
            clean[key] = val.strip()
    if "ein" in data:
        val = data["ein"]
        if val is None:
            val = ""
        if not isinstance(val, str):
            return None, "ein must be a string"
        val = val.strip()
        if val and (len(val) > 20 or not re.match(r"^[0-9][0-9\- ]*$", val)):
            return None, "ein must contain only digits and dashes"
        clean["ein"] = val
    if "fiscal_year" in data:
        val = data["fiscal_year"]
        if val is None:
            val = ""
        if not isinstance(val, str):
            return None, "fiscal_year must be a string"
        val = val.strip()
        if len(val) > 64:
            return None, "fiscal_year is too long"
        clean["fiscal_year"] = val
    if "base_currency" in data:
        val = data["base_currency"]
        if not isinstance(val, str) or not re.match(r"^[A-Za-z]{3}$",
                                                    val.strip()):
            return None, "base_currency must be a 3-letter code such as USD"
        clean["base_currency"] = val.strip().upper()
    return clean, None


@app.get("/api/erp/settings/company-profile")
def erp_settings_company_profile():
    # Same gate as the other Settings endpoints (QuickBooks status/config):
    # qb.manage is admin-only and never grantable to staff, so no new
    # permission was invented.
    actor, err = _erp_check_perm("qb.manage")
    if err:
        return err
    conn = db()
    out = _erp_company_profile(conn)
    conn.close()
    return jsonify({"profile": out})


@app.put("/api/erp/settings/company-profile")
def erp_settings_company_profile_put():
    actor, err = _erp_check_perm("qb.manage")
    if err:
        return err
    data = request.get_json(force=True, silent=True)
    clean, error = _erp_company_profile_validate(data)
    if error:
        return jsonify(error=error), 400
    if not clean:
        return jsonify(error="no profile fields provided"), 400
    conn = db()
    before = _erp_company_profile(conn)
    profile = dict(before)
    profile.update(clean)
    now = datetime.now(timezone.utc).isoformat()
    conn.execute(
        "INSERT OR REPLACE INTO erp_company_profile (id, legal_name,"
        " facility_address, office_address, ein, fiscal_year,"
        " base_currency, updated_by, updated_at)"
        " VALUES (1, ?, ?, ?, ?, ?, ?, ?, ?)",
        (profile["legal_name"], profile["facility_address"],
         profile["office_address"], profile["ein"], profile["fiscal_year"],
         profile["base_currency"], actor, now))
    changed = [k for k in sorted(clean)
               if (before.get(k) or "") != (profile.get(k) or "")]
    _audit_prof_id = _erp_settings_audit(
        conn, actor, "company_profile.updated", "company_profile", 0,
        ("Changed: " + ", ".join(changed)) if changed
        else "Saved with no field changes")
    # W2-N3: every changed profile field, before -> after.
    for _k in changed:
        _erp_audit_change(conn, "settings", _audit_prof_id, _k,
                          before.get(_k) or "", profile.get(_k) or "")
    conn.commit()
    out = _erp_company_profile(conn)
    conn.close()
    return jsonify({"profile": out})


def _erp_health_entry(key, name, configured, last_success_at,
                      last_success_detail, last_error_at, last_error,
                      connected=None, check_error=None):
    """One integration's health entry. Statuses are deliberately modest:
    'unconfigured' (no credentials), 'configured' (credentials set --
    NOT a health claim; last success/error are shown as the evidence),
    'error' (a stored failure newer than the last success), 'unknown'
    (the stored evidence itself could not be read). No live pings."""
    if check_error:
        status = "unknown"
        evidence = "Could not check stored activity: %s" % check_error
    elif not configured:
        status = "unconfigured"
        evidence = "Not configured: credentials are not set on the backend."
    elif last_error_at and (not last_success_at
                            or last_error_at > last_success_at):
        status = "error"
        evidence = ("A stored failure is newer than the last successful"
                    " call — see the last error below.")
    else:
        status = "configured"
        if last_success_at:
            evidence = ("Credentials are set; the last successful call"
                        " is shown below.")
        else:
            evidence = ("Configured, but no successful call is recorded"
                        " in the ERP yet.")
    entry = {"key": key, "name": name, "status": status,
             "configured": bool(configured),
             "last_success_at": last_success_at or "",
             "last_success_detail": last_success_detail or "",
             "last_error_at": last_error_at or "",
             "last_error": last_error or "",
             "evidence": evidence}
    if connected is not None:
        entry["connected"] = bool(connected)
    return entry


def _erp_integration_health(conn):
    """Health for the six integrations, from env/config + stored data only.
    Last-success sources: QuickBooks pushes (erp_qb_links), Shippo labels
    (orders / fundraiser_orders), Stripe orders (orders), captured PayPal
    orders (paypal_orders), Printful submissions (orders), Faire imports
    (erp_faire_import_log + erp_faire_sync summary). Last-error sources:
    Faire import log / sync summary only -- the other integrations store
    no error record (failures surface only in server logs), and the entry
    says so rather than claiming a clean bill of health."""
    out = []

    # QuickBooks: reuse the existing status logic (creds + stored tokens).
    try:
        cid, csec = _qb_creds()
        qb_configured = bool(cid and csec)
        tok = _qb_tokens(conn)
        qb_connected = (_QBO_TEST_DOUBLE is not None or bool(
            tok and tok["access_token"] and tok["realm_id"]))
        last_push = conn.execute(
            "SELECT MAX(pushed_at) AS m, COUNT(*) AS c FROM erp_qb_links"
            " WHERE pushed_at LIKE '____-__-__T%'").fetchone()
        qb_success = (last_push["m"] or "") if last_push else ""
        qb_detail = ("Last push to QuickBooks %s (%d pushed)"
                     % (qb_success, int(last_push["c"] or 0))
                     if qb_success else "")
        entry = _erp_health_entry(
            "quickbooks", "QuickBooks", qb_configured, qb_success, qb_detail,
            "", "", connected=qb_connected)
        if qb_configured and not qb_connected:
            entry["evidence"] = ("Configured, but not connected:"
                                 " no active QuickBooks session.")
        out.append(entry)
    except Exception as e:
        out.append(_erp_health_entry(
            "quickbooks", "QuickBooks", False, "", "", "", "",
            check_error=str(e)))

    # Shippo: last label created is the last successful Shippo call.
    # All MAX() timestamps below require an ISO-shaped value: production
    # writers always store ISO timestamps, while seed/test fixtures
    # sometimes store the literal placeholder 'now', which would
    # otherwise sort after every real timestamp.
    try:
        shippo_success, shippo_detail = "", ""
        best = conn.execute(
            "SELECT MAX(shippo_label_created_at) AS m,"
            " COUNT(*) AS c FROM orders"
            " WHERE shippo_label_created_at != ''"
            " AND shippo_label_created_at LIKE '____-__-__T%'").fetchone()
        cands = [(best["m"] or "", int(best["c"] or 0))]
        try:
            has_fund = conn.execute(
                "SELECT 1 FROM sqlite_master WHERE type = 'table'"
                " AND name = 'fundraiser_orders'").fetchone()
            if has_fund:
                fb = conn.execute(
                    "SELECT MAX(shippo_label_created_at) AS m,"
                    " COUNT(*) AS c FROM fundraiser_orders"
                    " WHERE shippo_label_created_at != ''"
                    " AND shippo_label_created_at LIKE '____-__-__T%'").fetchone()
                cands.append((fb["m"] or "", int(fb["c"] or 0)))
        except Exception:
            pass
        for ts, count in cands:
            if ts and (not shippo_success or ts > shippo_success):
                shippo_success = ts
                shippo_detail = "Last Shippo label created %s (%d labels total)" % (ts, count)
        out.append(_erp_health_entry(
            "shippo", "Shippo", bool(SHIPPO_API_KEY), shippo_success,
            shippo_detail, "", "",
            connected=None))
        out[-1]["evidence"] += (" Label failures are not stored;"
                                " they appear only in server logs.")
    except Exception as e:
        out.append(_erp_health_entry(
            "shippo", "Shippo", False, "", "", "", "", check_error=str(e)))

    # Stripe: last order row is the last successful Stripe checkout.
    try:
        row = conn.execute(
            "SELECT MAX(created_at) AS m, COUNT(*) AS c FROM orders"
            " WHERE stripe_session_id != '' AND stripe_session_id IS NOT NULL"
            " AND created_at LIKE '____-__-__T%'").fetchone()
        st_success = row["m"] or ""
        st_detail = ("Last Stripe order %s (%d Stripe orders)"
                     % (st_success, int(row["c"] or 0))) if st_success else ""
        out.append(_erp_health_entry(
            "stripe", "Stripe", bool(os.environ.get("STRIPE_SECRET_KEY")),
            st_success, st_detail, "", ""))
        out[-1]["evidence"] += (" Payment failures are not stored;"
                                " they appear only in server logs.")
    except Exception as e:
        out.append(_erp_health_entry(
            "stripe", "Stripe", False, "", "", "", "", check_error=str(e)))

    # PayPal: last captured order is the last successful PayPal call.
    try:
        row = conn.execute(
            "SELECT MAX(created_at) AS m, COUNT(*) AS c FROM paypal_orders"
            " WHERE status = 'captured'"
            " AND created_at LIKE '____-__-__T%'").fetchone()
        pp_success = row["m"] or ""
        pp_detail = ("Last captured PayPal order %s (%d captured)"
                     % (pp_success, int(row["c"] or 0))) if pp_success else ""
        out.append(_erp_health_entry(
            "paypal", "PayPal",
            bool(PAYPAL_CLIENT_ID and PAYPAL_CLIENT_SECRET),
            pp_success, pp_detail, "", ""))
    except Exception as e:
        out.append(_erp_health_entry(
            "paypal", "PayPal", False, "", "", "", "", check_error=str(e)))

    # Printful: last submitted merch order is the last successful call.
    try:
        row = conn.execute(
            "SELECT MAX(created_at) AS m, COUNT(*) AS c FROM orders"
            " WHERE printful_order_id != ''"
            " AND printful_order_id IS NOT NULL"
            " AND created_at LIKE '____-__-__T%'").fetchone()
        pf_success = row["m"] or ""
        pf_detail = ("Last Printful order submitted %s (%d submitted)"
                     % (pf_success, int(row["c"] or 0))) if pf_success else ""
        out.append(_erp_health_entry(
            "printful", "Printful", bool(PRINTFUL_API_KEY),
            pf_success, pf_detail, "", ""))
        out[-1]["evidence"] += (" Submission failures are not stored;"
                                " they appear only in server logs.")
    except Exception as e:
        out.append(_erp_health_entry(
            "printful", "Printful", False, "", "", "", "",
            check_error=str(e)))

    # Faire: last import-log row + sync summary. A stored failure (e.g. the
    # HTTP 401 auth failure) beats an older success, so an open auth
    # failure shows as an error with its own text, never as healthy.
    try:
        faire_configured = bool(
            os.environ.get("FAIRE_APP_ID")
            and os.environ.get("FAIRE_APP_SECRET")
            and os.environ.get("FAIRE_ACCESS_TOKEN"))
        sync = conn.execute(
            "SELECT * FROM erp_faire_sync WHERE id = 1").fetchone()
        last_run = (sync["last_run_at"] if sync else "") or ""
        summary_errors = []
        if sync and sync["last_summary"]:
            try:
                summary_errors = (json.loads(sync["last_summary"]) or {}
                                  ).get("errors") or []
            except (TypeError, ValueError):
                summary_errors = []
        ok_row = conn.execute(
            "SELECT * FROM erp_faire_import_log WHERE outcome = 'imported'"
            " ORDER BY id DESC LIMIT 1").fetchone()
        err_row = conn.execute(
            "SELECT * FROM erp_faire_import_log WHERE outcome = 'error'"
            " ORDER BY id DESC LIMIT 1").fetchone()
        f_success = (ok_row["created_at"] if ok_row else "") or ""
        f_detail = ("Last imported order %s (%s)"
                    % (f_success, ok_row["display_id"])
                    if ok_row else "")
        if last_run and (not f_success or last_run > f_success):
            f_detail = (f_detail + " " if f_detail else "") + \
                "Last sync run %s." % last_run
        f_error_at, f_error = "", ""
        if err_row:
            f_error_at = err_row["created_at"] or ""
            f_error = err_row["notes"] or "import failed"
        if summary_errors:
            # The sync summary carries run-level failures (e.g. HTTP 401
            # before any order was seen) with the run's timestamp.
            summary_text = "; ".join(str(e) for e in summary_errors)
            if not f_error_at or (last_run and last_run >= f_error_at):
                f_error_at = last_run or f_error_at
                f_error = summary_text
        out.append(_erp_health_entry(
            "faire", "Faire", faire_configured, f_success, f_detail,
            f_error_at, f_error))
    except Exception as e:
        out.append(_erp_health_entry(
            "faire", "Faire", False, "", "", "", "", check_error=str(e)))

    return {"integrations": out}


@app.get("/api/erp/settings/integrations")
def erp_settings_integrations():
    # Same Settings gate as the company profile (qb.manage, admin-only).
    actor, err = _erp_check_perm("qb.manage")
    if err:
        return err
    conn = db()
    out = _erp_integration_health(conn)
    conn.close()
    return jsonify(out)


# ---------- Big-company package, Module A: Systems / IT status view ----------
# One consolidated read-only view for Settings: integration health (the
# same _erp_integration_health data as the Integrations tab), backup
# status (the same _erp_backup_status_data as the Accounting backup
# card), the last post-backup security-check run, and an access review
# (who holds admin + every staff member's grants). Nothing here writes
# anything; each section links out to the screen that owns it.
@app.get("/api/erp/settings/systems")
def erp_settings_systems():
    # Same Settings gate as the integrations endpoint (qb.manage).
    actor, err = _erp_check_perm("qb.manage")
    if err:
        return err
    conn = db()
    health = _erp_integration_health(conn)
    backup = _erp_backup_status_data(conn)
    sec = conn.execute(
        "SELECT * FROM erp_security_check_runs"
        " ORDER BY id DESC LIMIT 1").fetchone()
    security_check = None
    if sec:
        try:
            failures = json.loads(sec["failures_json"] or "[]")
        except (TypeError, ValueError):
            failures = []
        try:
            notes = json.loads(sec["notes_json"] or "[]")
        except (TypeError, ValueError):
            notes = []
        if not isinstance(failures, list):
            failures = [str(failures)]
        if not isinstance(notes, list):
            notes = [str(notes)]
        security_check = {
            "run_at": sec["run_at"],
            "manifest_id": sec["manifest_id"] or "",
            "ok": bool(sec["ok"]),
            "failures": failures,
            "notes": notes,
        }
    admins = []
    for email in ADMIN_EMAILS:
        row = conn.execute(
            "SELECT name FROM users WHERE lower(email) = ?",
            (email,)).fetchone()
        admins.append({"email": email,
                       "name": (row["name"] or "") if row else "",
                       "has_user_row": bool(row)})
    staff_rows = conn.execute(
        "SELECT id, name, email, active FROM staff"
        " ORDER BY name, email").fetchall()
    staff_out = []
    for r in staff_rows:
        perms = [p[0] for p in conn.execute(
            "SELECT perm FROM erp_staff_perms WHERE staff_id = ?"
            " ORDER BY perm", (r["id"],)).fetchall()]
        staff_out.append({"id": r["id"], "name": r["name"],
                          "email": r["email"], "active": bool(r["active"]),
                          "perms": perms})
    # Wave 3 B11 (SOP 10.13): outbound webhook delivery failures
    # surface here (SOP 10.9) -- a failed delivery is never retried
    # silently, so this is where an admin sees it.
    webhook_subs = conn.execute(
        "SELECT COUNT(*) FROM erp_webhook_subscriptions").fetchone()[0]
    webhook_enabled = conn.execute(
        "SELECT COUNT(*) FROM erp_webhook_subscriptions"
        " WHERE enabled = 1").fetchone()[0]
    webhook_failed = conn.execute(
        "SELECT COUNT(*) FROM erp_webhook_deliveries"
        " WHERE status_code IS NULL OR status_code >= 400").fetchone()[0]
    last_fail = conn.execute(
        "SELECT d.id, d.event, d.status_code, d.delivered_at,"
        " d.attempts, s.url FROM erp_webhook_deliveries d"
        " LEFT JOIN erp_webhook_subscriptions s"
        " ON s.id = d.subscription_id"
        " WHERE d.status_code IS NULL OR d.status_code >= 400"
        " ORDER BY d.id DESC LIMIT 1").fetchone()
    webhooks = {"subscriptions": webhook_subs,
                "enabled": webhook_enabled,
                "failed_deliveries": webhook_failed,
                "last_failure": ({"event": last_fail["event"],
                                  "url": last_fail["url"] or "",
                                  "status_code": last_fail["status_code"],
                                  "attempts": last_fail["attempts"],
                                  "delivered_at":
                                      last_fail["delivered_at"]}
                                 if last_fail else None)}
    # Wave 4 item 20 (SOP 10.14): ITSM counts for the read-only
    # Systems card -- open incidents / problems, changes awaiting
    # approval, and assets in use. Counts only; the records themselves
    # live on the IT service tab, which this card links out to.
    itsm = {
        "open_incidents": conn.execute(
            "SELECT COUNT(*) FROM erp_it_incidents"
            " WHERE status IN ('open', 'in progress')").fetchone()[0],
        "open_problems": conn.execute(
            "SELECT COUNT(*) FROM erp_it_problems"
            " WHERE status IN ('open', 'investigating', 'known error')"
            ).fetchone()[0],
        "requested_changes": conn.execute(
            "SELECT COUNT(*) FROM erp_it_changes"
            " WHERE status = 'requested'").fetchone()[0],
        "assets_in_use": conn.execute(
            "SELECT COUNT(*) FROM erp_it_assets"
            " WHERE status = 'in use'").fetchone()[0],
        "assets_total": conn.execute(
            "SELECT COUNT(*) FROM erp_it_assets").fetchone()[0],
    }
    conn.close()
    return jsonify({
        "integrations": health["integrations"],
        "backup": backup,
        "security_check": security_check,
        "webhooks": webhooks,
        "itsm": itsm,
        "security_check_note": (
            "The post-backup security check runs on the VM after each"
            " nightly backup; the backup job records each run here. No"
            " run recorded yet means no backup has posted a result since"
            " this view shipped -- it is not a pass."),
        "access_review": {"admins": admins, "staff": staff_out},
    })


@app.post("/api/erp/settings/security-check")
def erp_settings_record_security_check():
    """Record one post-backup security-check run. Called by the VM
    backup job (acct_backup_job.py) with X-Cron-Secret after each
    backup, once the backup itself is safely stored. Same cron-secret
    pattern as the backup export: 503 when CRON_SECRET is not
    configured, 403 on a wrong or missing secret. Best-effort by
    design: the job never fails a good backup when this record fails.
    Body: {run_at, manifest_id, ok, failures[], notes[]}."""
    if not CRON_SECRET:
        return jsonify(error="cron secret is not configured"), 503
    if not hmac.compare_digest(
            request.headers.get("X-Cron-Secret", ""), CRON_SECRET):
        return jsonify(error="cron secret required"), 403
    data = request.get_json(force=True, silent=True) or {}
    failures = data.get("failures") or []
    notes = data.get("notes") or []
    if not isinstance(failures, list) or not isinstance(notes, list):
        return jsonify(error="failures and notes must be lists"), 400
    run_at = str(data.get("run_at") or "").strip()
    if not run_at:
        run_at = datetime.now(timezone.utc).isoformat()
    manifest_id = str(data.get("manifest_id") or "")
    conn = db()
    cur = conn.execute(
        "INSERT INTO erp_security_check_runs"
        " (run_at, manifest_id, ok, failures_json, notes_json, created_at)"
        " VALUES (?, ?, ?, ?, ?, ?)",
        (run_at, manifest_id, 1 if data.get("ok") else 0,
         json.dumps([str(f) for f in failures]),
         json.dumps([str(n) for n in notes]),
         datetime.now(timezone.utc).isoformat()))
    conn.commit()
    run_id = cur.lastrowid
    conn.close()
    return jsonify(ok=True, id=run_id), 201


# ---------- Dept 10 Settings Wave B ----------
# Item 3: notification / alert preferences. Item 4: Settings audit log.
#
# ALERT MODEL: five categories (low_stock, purchase_order, order,
# failure, kpi). Preferences are stored per category; NO saved row means
# today's behavior exactly -- every wired call site passes its own
# current recipients as the default, so with nothing saved the mail
# goes to precisely the addresses it goes to today. A saved row
# overrides: enabled=false, or an empty saved recipient list, means
# that category sends nothing. Customer-facing mail (order
# confirmations, verification, invites, accepted/declined notices,
# the renewal-failure customer copy) is NEVER gated by these prefs.
# The vendor PO email is the purchase order itself, addressed to the
# vendor from the vendor record: it is deliberately NOT gated, and no
# admin purchase-order alert is sent today, so the purchase_order
# toggle is stored and ready for the first admin PO alert (e.g. an
# overdue-PO digest) in a later wave.
_ERP_ALERT_CATEGORIES = ("low_stock", "purchase_order", "order", "failure",
                         "kpi")
_ERP_ALERT_META = {
    "low_stock": {
        "label": "Low stock",
        "description": ("Reorder-needed emails when an inventory count finds"
                        " items at zero, and the inventory reminder."),
    },
    "purchase_order": {
        "label": "Purchase orders",
        "description": ("Admin alerts about purchase orders. The email sent"
                        " to a vendor IS the purchase order -- it always goes"
                        " to the vendor and is never gated by this setting."
                        " No admin purchase-order alert is sent today."),
    },
    "order": {
        "label": "Orders",
        "description": ("New store orders (merchant inbox), new wholesale"
                        " orders waiting for review, and staff merch"
                        " redemptions."),
    },
    "failure": {
        "label": "Failures",
        "description": ("Subscription renewal failures (merchant copy). The"
                        " customer is always emailed directly -- this setting"
                        " only controls the merchant copy."),
    },
    "kpi": {
        "label": "KPI alerts",
        "description": ("Dashboard KPI threshold breaches (cash below its"
                        " floor, overdue receivables over their limit or"
                        " age, days with no revenue, awaiting payment over"
                        " its limit, the lowest forecast weekly balance"
                        " below its floor). Thresholds are set on the"
                        " Dashboard; with no threshold set, nothing in"
                        " this category ever fires."),
    },
}


def _erp_alert_default_recipients(category):
    """Canonical defaults for one category, for display: where its alerts
    go when no preferences are saved. The live send path uses each call
    site's own current recipients (see _erp_send_alert), which agree
    with these lists."""
    if category == "low_stock":
        return list(_WHOLESALE_ADMIN_EMAILS)
    if category == "purchase_order":
        return list(ADMIN_EMAILS)
    if category == "order":
        out = []
        for e in ([ORDER_NOTIFY_EMAIL] if ORDER_NOTIFY_EMAIL else []) \
                + list(_WHOLESALE_ADMIN_EMAILS) + list(ADMIN_EMAILS):
            if e and e not in out:
                out.append(e)
        return out
    if category == "failure":
        return ([ORDER_NOTIFY_EMAIL] if ORDER_NOTIFY_EMAIL else [])
    if category == "kpi":
        # W2-N2: breach alerts go to the admins by default (Matt + DJ).
        return list(ADMIN_EMAILS)
    return []


def _erp_alert_recipients(conn, category, default_recipients):
    """Recipient list for one alert category. No saved row -> exactly
    default_recipients (today's behavior). Saved + enabled -> the saved
    list. Saved + disabled, or a saved empty list -> no recipients."""
    row = None
    try:
        row = conn.execute(
            "SELECT enabled, recipients FROM erp_notification_prefs"
            " WHERE category = ?", (category,)).fetchone()
    except Exception:
        row = None
    if row is None:
        return list(default_recipients)
    if not row[0]:
        return []
    try:
        saved = json.loads(row[1] or "[]")
    except (TypeError, ValueError):
        saved = []
    out = []
    for e in (saved or []):
        if isinstance(e, str):
            e = e.strip().lower()
            if e and EMAIL_RE.match(e) and e not in out:
                out.append(e)
    return out


def _erp_send_alert(conn, category, default_recipients, subject, html,
                    from_email=None):
    """Send one admin alert to a category's recipients. Returns how many
    mails were sent. Never raises -- a failed or disabled alert must not
    break the operation that triggered it. conn may be None (a fresh
    connection is opened to read the preferences)."""
    own_conn = None
    try:
        if conn is None:
            own_conn = db()
            conn = own_conn
        recipients = _erp_alert_recipients(conn, category, default_recipients)
        sent = 0
        for to_email in recipients:
            try:
                send_email(to_email, subject, html, from_email=from_email)
                sent += 1
            except Exception:
                pass
        return sent
    except Exception:
        return 0
    finally:
        if own_conn is not None:
            try:
                own_conn.close()
            except Exception:
                pass


def _erp_notification_prefs_effective(conn):
    """Effective preferences for all five categories: saved values when
    a row exists, otherwise the defaults (with saved=false)."""
    out = {}
    for cat in _ERP_ALERT_CATEGORIES:
        row = None
        try:
            row = conn.execute(
                "SELECT enabled, recipients FROM erp_notification_prefs"
                " WHERE category = ?", (cat,)).fetchone()
        except Exception:
            row = None
        meta = _ERP_ALERT_META[cat]
        if row is None:
            out[cat] = {"enabled": True,
                        "recipients": _erp_alert_default_recipients(cat),
                        "saved": False,
                        "default_recipients":
                            _erp_alert_default_recipients(cat),
                        "label": meta["label"],
                        "description": meta["description"]}
        else:
            try:
                saved = json.loads(row[1] or "[]")
            except (TypeError, ValueError):
                saved = []
            saved = [str(e).strip().lower() for e in (saved or [])
                     if isinstance(e, str) and e.strip()]
            out[cat] = {"enabled": bool(row[0]),
                        "recipients": saved,
                        "saved": True,
                        "default_recipients":
                            _erp_alert_default_recipients(cat),
                        "label": meta["label"],
                        "description": meta["description"]}
    return out


def _erp_notification_prefs_validate(data):
    """Validate a prefs PUT body. Accepts per-category objects at the top
    level, or under a "preferences" wrapper. Returns (clean, None) or
    (None, error). Only keys present are updated; unknown keys ignored.
    clean: {category: {"enabled": bool|None, "recipients": list|None}}."""
    if not isinstance(data, dict):
        return None, "preferences must be an object"
    body = data.get("preferences") if isinstance(data.get("preferences"),
                                                 dict) else data
    if not isinstance(body, dict):
        return None, "preferences must be an object"
    clean = {}
    for cat, val in body.items():
        if cat not in _ERP_ALERT_CATEGORIES:
            continue
        if not isinstance(val, dict):
            return None, "%s must be an object" % cat
        entry = {}
        if "enabled" in val:
            if not isinstance(val["enabled"], bool):
                return None, "%s.enabled must be true or false" % cat
            entry["enabled"] = val["enabled"]
        if "recipients" in val:
            recips = val["recipients"]
            if not isinstance(recips, list) or \
                    not all(isinstance(e, str) for e in recips):
                return None, "%s.recipients must be a list of emails" % cat
            if len(recips) > 10:
                return None, "%s.recipients allows at most 10 addresses" % cat
            norm = []
            for e in recips:
                e = e.strip().lower()
                if not e:
                    continue
                if len(e) > 254 or not EMAIL_RE.match(e):
                    return None, "%s has an invalid email: %s" % (cat, e)
                if e not in norm:
                    norm.append(e)
            entry["recipients"] = norm
        if entry:
            clean[cat] = entry
    if not clean:
        return None, "no notification preferences provided"
    return clean, None


@app.get("/api/erp/settings/notification-preferences")
def erp_settings_notification_prefs():
    # Same Settings gate as the company profile (qb.manage, admin-only).
    actor, err = _erp_check_perm("qb.manage")
    if err:
        return err
    conn = db()
    out = _erp_notification_prefs_effective(conn)
    conn.close()
    return jsonify({"preferences": out})


@app.put("/api/erp/settings/notification-preferences")
def erp_settings_notification_prefs_put():
    actor, err = _erp_check_perm("qb.manage")
    if err:
        return err
    data = request.get_json(force=True, silent=True)
    clean, error = _erp_notification_prefs_validate(data)
    if error:
        return jsonify(error=error), 400
    conn = db()
    now = datetime.now(timezone.utc).isoformat()
    changed = []
    for cat in _ERP_ALERT_CATEGORIES:
        if cat not in clean:
            continue
        row = conn.execute(
            "SELECT enabled, recipients FROM erp_notification_prefs"
            " WHERE category = ?", (cat,)).fetchone()
        if row is None:
            enabled = clean[cat].get("enabled", True)
            recips = clean[cat].get(
                "recipients", _erp_alert_default_recipients(cat))
        else:
            try:
                prev = json.loads(row[1] or "[]")
            except (TypeError, ValueError):
                prev = []
            enabled = clean[cat].get("enabled", bool(row[0]))
            recips = clean[cat].get("recipients", prev)
        conn.execute(
            "INSERT OR REPLACE INTO erp_notification_prefs (category,"
            " enabled, recipients, updated_by, updated_at)"
            " VALUES (?, ?, ?, ?, ?)",
            (cat, 1 if enabled else 0, json.dumps(recips), actor, now))
        changed.append("%s: %s, recipients=[%s]"
                       % (cat, "enabled" if enabled else "disabled",
                          ", ".join(recips)))
    _erp_settings_audit(conn, actor, "notification_preferences.updated",
                        "notification_preferences", 0,
                        "Notification preferences saved: " + "; ".join(changed))
    conn.commit()
    out = _erp_notification_prefs_effective(conn)
    conn.close()
    return jsonify({"preferences": out})


# ---------- W2-N2: KPI alerts / thresholds (Dept 1) ----------
# Six KPIs, one threshold row each (upsert by kpi, NO seed rows -- no
# threshold means no alert, never a zero default). Money KPIs take
# threshold_cents; day KPIs take threshold_days; a KPI takes exactly
# one of the two. Breach state is COMPUTED at read time from live data
# -- never stored, so a breach can never go stale -- and a threshold
# never gates anything: no threshold blocks any posting, order, or
# payment; alerts only. Breach emails, when sent, reuse the existing
# notification-prefs machinery via _erp_send_alert with category "kpi"
# (default recipients = admins); no new mailer. No send is triggered
# by a read: a GET must stay side-effect free, so nothing here emails
# on dashboard load.
_ERP_DASH_KPI_DEFS = (
    {"kpi": "cash_below", "label": "Cash below",
     "kind": "money", "link": "#/accounting", "view": "treasury",
     "description": "Cash on hand falls below the floor you set."},
    {"kpi": "overdue_over", "label": "Overdue receivables over",
     "kind": "money", "link": "#/accounting", "view": "aging",
     "description": "Overdue receivables pass the amount you set."},
    {"kpi": "overdue_age_days", "label": "Oldest overdue invoice age",
     "kind": "days", "link": "#/accounting", "view": "aging",
     "description": "The oldest overdue invoice reaches the age you set."},
    {"kpi": "revenue_zero_days", "label": "Days with no revenue",
     "kind": "days", "link": "#/reports", "view": None,
     "description": "Revenue is zero for the run of days you set."},
    {"kpi": "awaiting_payment_over", "label": "Awaiting payment over",
     "kind": "money", "link": "#/orders", "view": None,
     "description": "Uncaptured PayPal checkouts pass the amount you set."},
    {"kpi": "forecast_shortfall", "label": "Forecast shortfall",
     "kind": "money", "link": "#/accounting", "view": "treasury",
     "description": "The lowest projected weekly closing balance in the 13-week cash forecast falls below the floor you set."},
)
_ERP_DASH_KPI_BY_KEY = {d["kpi"]: d for d in _ERP_DASH_KPI_DEFS}
# Longest zero-revenue run reported: a ledger that never had a sale
# reads 365, not an unbounded run.
_ERP_DASH_KPI_ZERO_DAY_CAP = 365


def _erp_dash_kpi_current(conn):
    """Live current values for the six KPIs -- read-only math on
    existing data. Cash + overdue receivables come from _acct_treasury
    (the same computation as the Treasury view); awaiting payment is
    the same query as the Dashboard awaiting-payment card (uncaptured
    PayPal only); oldest overdue age reads open invoices; the
    zero-revenue run counts consecutive days ending today with no
    revenue in the orders table (the same source as revenue today);
    the forecast shortfall is the lowest projected weekly closing
    balance of the 13-week cash forecast (SOP 9.36).
    Returns {kpi: {"current_cents": int|None,
    "current_days": int|None}}."""
    as_of = datetime.now(timezone.utc).date().isoformat()
    treasury = _acct_treasury(conn, as_of)
    cash_cents = int(treasury["cash"]["total_cents"] or 0)
    overdue_cents = int(treasury["totals"]["overdue_in_cents"] or 0)
    awaiting = conn.execute(
        "SELECT COALESCE(SUM(amount_total_cents), 0) AS s"
        " FROM paypal_orders WHERE status != 'captured'").fetchone()
    awaiting_cents = int(awaiting["s"] or 0)
    # Oldest overdue open invoice, in days. A bad due date is skipped,
    # never fatal to the read.
    max_age = 0
    as_of_d = datetime.strptime(as_of, "%Y-%m-%d").date()
    for inv in conn.execute(
            "SELECT due_date FROM erp_acct_invoices"
            " WHERE status = 'open' AND balance_cents > 0").fetchall():
        try:
            due = datetime.strptime(inv["due_date"], "%Y-%m-%d").date()
        except (TypeError, ValueError):
            continue
        age = (as_of_d - due).days
        if age > max_age:
            max_age = age
    by_day = {}
    for r in conn.execute(
            "SELECT substr(created_at, 1, 10) AS d,"
            " COALESCE(SUM(amount_total_cents), 0) AS s FROM orders"
            " GROUP BY d").fetchall():
        try:
            by_day[r["d"]] = int(r["s"] or 0)
        except (TypeError, ValueError):
            continue
    zero_days = 0
    day = as_of_d
    while zero_days < _ERP_DASH_KPI_ZERO_DAY_CAP:
        if by_day.get(day.isoformat(), 0) > 0:
            break
        zero_days += 1
        day -= timedelta(days=1)
    forecast = _acct_cash_forecast(conn, as_of)
    lowest_closing = int(forecast["totals"]["lowest_closing_cents"] or 0)
    return {
        "cash_below": {"current_cents": cash_cents, "current_days": None},
        "overdue_over": {"current_cents": overdue_cents,
                         "current_days": None},
        "overdue_age_days": {"current_cents": None,
                             "current_days": max_age},
        "revenue_zero_days": {"current_cents": None,
                              "current_days": zero_days},
        "awaiting_payment_over": {"current_cents": awaiting_cents,
                                  "current_days": None},
        "forecast_shortfall": {"current_cents": lowest_closing,
                               "current_days": None},
    }


def _erp_dash_kpi_is_breached(kpi, current, stored):
    """True when a set, enabled threshold is breached right now.
    cash_below and forecast_shortfall breach below their floor; the
    other money KPIs breach above their limit; day KPIs breach at or
    past their day count.
    stored is the threshold row or None (unset never breaches)."""
    if stored is None or not stored["enabled"]:
        return False
    if kpi in ("cash_below", "forecast_shortfall"):
        return (stored["threshold_cents"] is not None
                and current["current_cents"] < stored["threshold_cents"])
    if kpi in ("overdue_over", "awaiting_payment_over"):
        return (stored["threshold_cents"] is not None
                and current["current_cents"] > stored["threshold_cents"])
    return (stored["threshold_days"] is not None
            and current["current_days"] >= stored["threshold_days"])


def _erp_dash_kpi_entry(defn, stored, current):
    """One KPI as the API returns it: definition + stored threshold
    (or unset) + live current value + computed breach state."""
    entry = {"kpi": defn["kpi"], "label": defn["label"],
             "kind": defn["kind"], "link": defn["link"],
             "view": defn["view"], "description": defn["description"],
             "set": stored is not None,
             "id": stored["id"] if stored else None,
             "threshold_cents": (stored["threshold_cents"]
                                 if stored else None),
             "threshold_days": (stored["threshold_days"]
                                if stored else None),
             "enabled": bool(stored["enabled"]) if stored else True,
             "created_by": stored["created_by"] if stored else "",
             "created_at": stored["created_at"] if stored else "",
             "updated_by": stored["updated_by"] if stored else "",
             "updated_at": stored["updated_at"] if stored else "",
             "current_cents": current["current_cents"],
             "current_days": current["current_days"]}
    entry["breached"] = _erp_dash_kpi_is_breached(defn["kpi"], current,
                                                 stored)
    return entry


def _erp_dash_kpi_entries(conn):
    """All six KPI entries, set or unset, with live values."""
    stored = {r["kpi"]: r for r in conn.execute(
        "SELECT * FROM erp_dash_kpi_thresholds").fetchall()}
    current = _erp_dash_kpi_current(conn)
    return [_erp_dash_kpi_entry(defn, stored.get(defn["kpi"]),
                               current[defn["kpi"]])
            for defn in _ERP_DASH_KPI_DEFS]


def _erp_dash_kpi_validate(data):
    """Validate a threshold POST body. Returns (clean, None) or
    (None, error). clean: {"kpi", "threshold_cents"|None,
    "threshold_days"|None, "enabled"|None}. A KPI takes exactly one
    of money/days: the other field must be absent (null counts as
    absent); a missing required field, a negative value, a non-integer,
    or an unknown kpi is a 400."""
    if not isinstance(data, dict):
        return None, "threshold must be an object"
    kpi = data.get("kpi")
    if not isinstance(kpi, str) or kpi not in _ERP_DASH_KPI_BY_KEY:
        return None, "unknown kpi"
    kind = _ERP_DASH_KPI_BY_KEY[kpi]["kind"]
    cents = data.get("threshold_cents")
    days = data.get("threshold_days")
    if kind == "money":
        if days is not None:
            return None, "%s takes threshold_cents, not threshold_days" % kpi
        if isinstance(cents, bool) or not isinstance(cents, int):
            return None, "threshold_cents must be an integer number of cents"
        if cents < 0:
            return None, "threshold_cents must not be negative"
    else:
        if cents is not None:
            return None, "%s takes threshold_days, not threshold_cents" % kpi
        if isinstance(days, bool) or not isinstance(days, int):
            return None, "threshold_days must be an integer number of days"
        if days < 0:
            return None, "threshold_days must not be negative"
    enabled = data.get("enabled")
    if enabled is not None and not isinstance(enabled, bool):
        return None, "enabled must be true or false"
    return {"kpi": kpi,
            "threshold_cents": cents if kind == "money" else None,
            "threshold_days": days if kind == "days" else None,
            "enabled": enabled}, None


def _erp_dash_kpi_audit_detail(clean, enabled):
    """Human-readable audit detail for a set threshold."""
    if clean["threshold_cents"] is not None:
        value = "$%.2f" % (clean["threshold_cents"] / 100)
    else:
        value = "%d days" % clean["threshold_days"]
    return "%s threshold %s, %s" % (
        clean["kpi"], value, "enabled" if enabled else "disabled")


@app.get("/api/erp/dashboard/kpi-thresholds")
def erp_dash_kpi_thresholds_list():
    """List thresholds: all six KPIs, set or unset, with live current
    values and computed breach state. Admin-only."""
    actor, err = _require_erp_admin()
    if err:
        return err
    conn = db()
    out = _erp_dash_kpi_entries(conn)
    conn.close()
    return jsonify(thresholds=out)


@app.post("/api/erp/dashboard/kpi-thresholds")
def erp_dash_kpi_thresholds_set():
    """Create/update one KPI threshold (upsert by kpi). Admin-only."""
    actor, err = _require_erp_admin()
    if err:
        return err
    data = request.get_json(force=True, silent=True)
    clean, error = _erp_dash_kpi_validate(data)
    if error:
        return jsonify(error=error), 400
    conn = db()
    now = datetime.now(timezone.utc).isoformat()
    row = conn.execute(
        "SELECT * FROM erp_dash_kpi_thresholds WHERE kpi = ?",
        (clean["kpi"],)).fetchone()
    if row is None:
        enabled = clean["enabled"] if clean["enabled"] is not None else True
        cur = conn.execute(
            "INSERT INTO erp_dash_kpi_thresholds (kpi, threshold_cents,"
            " threshold_days, enabled, created_by, created_at, updated_by,"
            " updated_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?)",
            (clean["kpi"], clean["threshold_cents"],
             clean["threshold_days"], 1 if enabled else 0, actor, now,
             actor, now))
        row_id = cur.lastrowid
    else:
        enabled = (clean["enabled"] if clean["enabled"] is not None
                   else bool(row["enabled"]))
        conn.execute(
            "UPDATE erp_dash_kpi_thresholds SET threshold_cents = ?,"
            " threshold_days = ?, enabled = ?, updated_by = ?,"
            " updated_at = ? WHERE id = ?",
            (clean["threshold_cents"], clean["threshold_days"],
             1 if enabled else 0, actor, now, row["id"]))
        row_id = row["id"]
    _erp_staff_audit(conn, actor, "dash.kpi_threshold_set",
                     "dash_kpi_threshold", row_id,
                     _erp_dash_kpi_audit_detail(clean, enabled))
    conn.commit()
    saved = conn.execute(
        "SELECT * FROM erp_dash_kpi_thresholds WHERE id = ?",
        (row_id,)).fetchone()
    current = _erp_dash_kpi_current(conn)
    conn.close()
    return jsonify(threshold=_erp_dash_kpi_entry(
        _ERP_DASH_KPI_BY_KEY[clean["kpi"]], saved,
        current[clean["kpi"]]))


