# ---------- Dept 10 Settings Wave B, item 4: Settings audit log ----------
# Separate from the Phase 4 accounting audit (erp_acct_audit), which
# covers accounting writes only. This log covers Settings actions only:
# QuickBooks connect/disconnect, item-mapping saves, company-profile
# changes, notification-preference changes, wipe requests/completions,
# and ERP import runs. Only actions taken after this ships are logged;
# history is NOT backfilled. The table is excluded from
# _ERP_RESET_TABLES so wipe rows survive the wipe.
_ERP_AUDIT_CHANGE_LOGS = ("acct", "staff", "settings", "mkt")
_ERP_AUDIT_CHANGE_TABLES = {
    "acct": "erp_acct_audit",
    "staff": "erp_staff_audit",
    "settings": "erp_settings_audit",
    "mkt": "erp_mkt_audit",
}


def _erp_audit_change(conn, log, audit_id, field, old, new):
    """Write one structured field-level change row (W2-N3, SOP 10.10).

    Called server-side only, right after the parent audit helper, at
    already-audited write sites. Values are stored as TEXT snapshots:
    cents as integer-cent strings, dates ISO, permission sets as sorted
    comma lists. An empty old_value means the field had no prior value
    (a newly posted entry). Best-effort by design: a write failure is
    logged and never blocks the underlying mutation. Returns the new
    row id, or None when nothing was written (unknown log, or a failed
    write). There is no update/delete path for these rows, ever."""
    if log not in _ERP_AUDIT_CHANGE_LOGS:
        return None
    try:
        audit_id = int(audit_id)
    except (TypeError, ValueError):
        return None
    try:
        cur = conn.execute(
            "INSERT INTO erp_audit_changes (audit_log, audit_id,"
            " field_name, old_value, new_value, created_at)"
            " VALUES (?, ?, ?, ?, ?, ?)",
            (log, audit_id, str(field or ""),
             "" if old is None else str(old),
             "" if new is None else str(new),
             datetime.now(timezone.utc).isoformat()))
        return cur.lastrowid
    except Exception as exc:  # best-effort: never block the mutation
        print("erp_audit_changes write failed: %s" % (exc,),
              file=sys.stderr)
        return None


def _erp_settings_audit(conn, actor, action, target_type="", target_id=0,
                        detail=""):
    cur = conn.execute(
        "INSERT INTO erp_settings_audit (actor, action, target_type,"
        " target_id, detail, created_at) VALUES (?, ?, ?, ?, ?, ?)",
        (actor or "", action, target_type or "", int(target_id or 0),
         detail or "", datetime.now(timezone.utc).isoformat()))
    # W2-N3: the id is the parent key for erp_audit_changes rows.
    return cur.lastrowid


def _erp_staff_audit(conn, actor, action, target_type="staff", target_id=0,
                     detail=""):
    """Write one row to the staff audit log (Dept 11). Same shape as
    _erp_settings_audit; the two logs stay separate on purpose."""
    cur = conn.execute(
        "INSERT INTO erp_staff_audit (actor, action, target_type,"
        " target_id, detail, created_at) VALUES (?, ?, ?, ?, ?, ?)",
        (actor or "", action, target_type or "staff", int(target_id or 0),
         detail or "", datetime.now(timezone.utc).isoformat()))
    # W2-N3: the id is the parent key for erp_audit_changes rows.
    return cur.lastrowid


def _erp_staff_is_self(actor_user, staff_row):
    """True when the staff row is the acting admin's own account.

    Admins log in as members (users table, ADMIN_EMAILS); staff rows are
    a separate table. The email match catches the normal case (DJ:
    dj@fudgetopia.net on both sides). The name fallback covers the known
    mismatch (Matt: admin matt@fudgetopia.net, staff row
    matt@pop-a-licious.com) -- full names are compared case-insensitively.
    A staff row is only "self" by name when the name is non-empty and an
    exact match; two different people sharing a first name do not match.
    """
    if not actor_user or not staff_row:
        return False
    # _current_member() returns a sqlite3.Row (no .get); staff rows are
    # Rows too. Normalize both to plain dicts first.
    actor = dict(actor_user)
    staff = dict(staff_row)
    actor_email = (actor.get("email") or "").strip().lower()
    staff_email = (staff.get("email") or "").strip().lower()
    if actor_email and actor_email == staff_email:
        return True
    actor_name = (actor.get("name") or "").strip().lower()
    staff_name = (staff.get("name") or "").strip().lower()
    return bool(actor_name and actor_name == staff_name)


def _erp_tombstone(conn, kind, key, actor):
    """Record a user deletion so no import can resurrect the row."""
    conn.execute(
        "INSERT OR IGNORE INTO erp_deleted_keys (kind, key, deleted_by,"
        " deleted_at) VALUES (?, ?, ?, ?)",
        ((kind or "").strip().lower(), (key or "").strip().lower(),
         actor or "", datetime.now(timezone.utc).isoformat()))


def _erp_is_deleted(conn, kind, key):
    """True when the natural key was deliberately deleted by the user."""
    row = conn.execute(
        "SELECT 1 FROM erp_deleted_keys WHERE kind = ? AND key = ?",
        ((kind or "").strip().lower(), (key or "").strip().lower())).fetchone()
    return bool(row)


def _erp_settings_audit_day(value):
    """Day-granularity filter value: the YYYY-MM-DD part of a date or
    datetime string, or None when it does not parse as one."""
    s = (value or "").strip()
    if not re.match(r"^\d{4}-\d{2}-\d{2}", s):
        return None
    try:
        datetime.strptime(s[:10], "%Y-%m-%d")
    except ValueError:
        return None
    return s[:10]


@app.get("/api/erp/settings/audit")
def erp_settings_audit_list():
    # Same Settings gate as the company profile (qb.manage, admin-only).
    actor, err = _erp_check_perm("qb.manage")
    if err:
        return err
    try:
        limit = int(request.args.get("limit") or 100)
    except (TypeError, ValueError):
        limit = 100
    limit = max(1, min(limit, 500))
    action = (request.args.get("action") or "").strip()
    actor_f = (request.args.get("actor") or "").strip()
    from_day = _erp_settings_audit_day(request.args.get("from") or "")
    to_day = _erp_settings_audit_day(request.args.get("to") or "")
    conds = []
    args = []
    if action:
        conds.append("action = ?")
        args.append(action)
    if actor_f:
        conds.append("actor = ?")
        args.append(actor_f)
    # Day-granularity, inclusive of the whole day on both ends.
    if from_day:
        conds.append("substr(created_at, 1, 10) >= ?")
        args.append(from_day)
    if to_day:
        conds.append("substr(created_at, 1, 10) <= ?")
        args.append(to_day)
    where = (" WHERE " + " AND ".join(conds)) if conds else ""
    conn = db()
    total = conn.execute(
        "SELECT COUNT(*) AS c FROM erp_settings_audit" + where, args).fetchone()["c"]
    rows = conn.execute(
        "SELECT * FROM erp_settings_audit" + where +
        " ORDER BY id DESC LIMIT ?", args + [limit]).fetchall()
    conn.close()
    return jsonify({"audit": [dict(r) for r in rows], "total": int(total),
                    "limit": limit})


# ---- W2-N3: field-level change history (SOP 10.10) ----
# Read-only, admin-only. A change row is never a substitute for its
# parent audit line: both are returned together, the parent under the
# "audit" key. No write endpoint exists for this table, ever.
def _erp_audit_change_parent(conn, log, audit_id):
    """The parent audit line for one change row, or None."""
    table = _ERP_AUDIT_CHANGE_TABLES.get(log)
    if not table:
        return None
    row = conn.execute(
        "SELECT * FROM %s WHERE id = ?" % table, (audit_id,)).fetchone()
    return dict(row) if row else None


@app.get("/api/erp/audit/changes")
def erp_audit_changes_list():
    """List field-level change rows, newest first. Admin-only.

    Filters (all optional): log (acct|staff|settings|mkt), audit_id (the
    parent audit line's id), target_type + target_id (matched against
    the parent audit line), field (exact field name). 400 on an unknown
    log or a non-integer audit_id/target_id. limit 1-500, default 100.
    Each item is the change row plus its parent audit line."""
    _, err = _require_erp_admin()
    if err:
        return err
    log = (request.args.get("log") or "").strip()
    if log and log not in _ERP_AUDIT_CHANGE_LOGS:
        return jsonify(error="log must be one of acct, staff, settings, mkt"), 400
    try:
        audit_id = (int(request.args.get("audit_id"))
                    if (request.args.get("audit_id") or "").strip() else None)
    except (TypeError, ValueError):
        return jsonify(error="audit_id must be a number"), 400
    try:
        target_id = (int(request.args.get("target_id"))
                     if (request.args.get("target_id") or "").strip() else None)
    except (TypeError, ValueError):
        return jsonify(error="target_id must be a number"), 400
    target_type = (request.args.get("target_type") or "").strip()
    field = (request.args.get("field") or "").strip()
    try:
        limit = int(request.args.get("limit") or 100)
    except (TypeError, ValueError):
        limit = 100
    limit = max(1, min(limit, 500))
    try:
        offset = int(request.args.get("offset") or 0)
    except (TypeError, ValueError):
        offset = 0
    offset = max(offset, 0)
    conds = []
    args = []
    if log:
        conds.append("c.audit_log = ?")
        args.append(log)
    if audit_id is not None:
        conds.append("c.audit_id = ?")
        args.append(audit_id)
    if field:
        conds.append("c.field_name = ?")
        args.append(field)
    if target_type or target_id is not None:
        # Match against the parent audit line, in whichever log(s) apply.
        logs = [log] if log else list(_ERP_AUDIT_CHANGE_LOGS)
        parts = []
        targs = []
        for lg in logs:
            table = _ERP_AUDIT_CHANGE_TABLES[lg]
            tconds = []
            if target_type:
                tconds.append("target_type = ?")
                targs.append(target_type)
            if target_id is not None:
                tconds.append("target_id = ?")
                targs.append(target_id)
            parts.append("SELECT '%s' AS _log, id FROM %s%s"
                         % (lg, table,
                            (" WHERE " + " AND ".join(tconds)) if tconds else ""))
        conds.append("(c.audit_log, c.audit_id) IN (%s)"
                     % " UNION ALL ".join(parts))
        args.extend(targs)
    where = (" WHERE " + " AND ".join(conds)) if conds else ""
    conn = db()
    total = conn.execute(
        "SELECT COUNT(*) AS c FROM erp_audit_changes c" + where,
        args).fetchone()["c"]
    rows = conn.execute(
        "SELECT c.* FROM erp_audit_changes c" + where +
        " ORDER BY c.id DESC LIMIT ? OFFSET ?", args + [limit, offset]).fetchall()
    out = []
    for r in rows:
        d = dict(r)
        d["audit"] = _erp_audit_change_parent(conn, d["audit_log"], d["audit_id"])
        out.append(d)
    conn.close()
    return jsonify(changes=out, total=int(total), limit=limit, offset=offset)


@app.get("/api/erp/audit/changes/<int:change_id>")
def erp_audit_change_get(change_id):
    """One change row with its parent audit line. Admin-only. 404 unknown."""
    _, err = _require_erp_admin()
    if err:
        return err
    conn = db()
    row = conn.execute("SELECT * FROM erp_audit_changes WHERE id = ?",
                       (change_id,)).fetchone()
    if not row:
        conn.close()
        return jsonify(error="change not found"), 404
    d = dict(row)
    parent = _erp_audit_change_parent(conn, d["audit_log"], d["audit_id"])
    conn.close()
    return jsonify(change=d, audit=parent)


