# ---------- report: spend by vendor ----------

def _erp_spend_by_vendor_data(conn, df, dt):
    """Spend-by-vendor computation, shared by the tab endpoint and the
    scheduled-report sender (Wave 3 B6): one computation, so a
    scheduled email can never drift from what the tab shows. Returns
    (vendors, total_cents, po_count)."""
    where, params = _erp_date_where(df, dt, "p.order_date")
    # Ordered POs only: drafts are planned spend, cancelled POs are not spend.
    status_filter = "p.status IN ('sent', 'partial', 'received', 'closed')"
    line_rows = conn.execute(
        "SELECT p.vendor_id, COALESCE(SUM(l.qty_ordered * l.unit_cost_cents), 0)"
        " AS lines_total, COALESCE(SUM(l.qty_ordered), 0) AS bags"
        " FROM erp_po_lines l JOIN erp_purchase_orders p ON p.id = l.po_id"
        + (" WHERE " + status_filter + " AND " + where if where else
           " WHERE " + status_filter)
        + " GROUP BY p.vendor_id",
        params).fetchall()
    po_rows = conn.execute(
        "SELECT vendor_id, COUNT(*) AS po_count,"
        " COALESCE(SUM(freight_cents), 0) AS freight,"
        " COALESCE(SUM(tax_cents), 0) AS tax"
        " FROM erp_purchase_orders p"
        + (" WHERE " + status_filter + " AND " + where if where else
           " WHERE " + status_filter)
        + " GROUP BY vendor_id",
        params).fetchall()
    by_vendor = {}
    for r in line_rows:
        by_vendor[r["vendor_id"]] = {
            "lines_total_cents": int(r["lines_total"] or 0),
            "bags": float(r["bags"] or 0)}
    for r in po_rows:
        d = by_vendor.setdefault(r["vendor_id"], {
            "lines_total_cents": 0, "bags": 0.0})
        d["po_count"] = int(r["po_count"] or 0)
        d["freight_cents"] = int(r["freight"] or 0)
        d["tax_cents"] = int(r["tax"] or 0)
    vendors = []
    total_cents = 0
    total_pos = 0
    for vid in sorted(by_vendor):
        v = conn.execute(
            "SELECT name FROM erp_vendors WHERE id = ?", (vid,)).fetchone()
        d = by_vendor[vid]
        t = (d["lines_total_cents"] + d.get("freight_cents", 0)
             + d.get("tax_cents", 0))
        total_cents += t
        total_pos += d.get("po_count", 0)
        vendors.append({
            "vendor_id": vid, "vendor_name": v["name"] if v else "",
            "po_count": d.get("po_count", 0), "bags": d["bags"],
            "lines_total_cents": d["lines_total_cents"],
            "freight_cents": d.get("freight_cents", 0),
            "tax_cents": d.get("tax_cents", 0), "total_cents": t})
    return vendors, total_cents, total_pos


_SPEND_BY_VENDOR_CSV_HEADER = ["vendor", "purchase_orders", "bags",
                               "lines_total_cents", "freight_cents",
                               "tax_cents", "total_cents"]


def _erp_spend_by_vendor_csv_rows(vendors):
    """Spend-by-vendor CSV rows, shared by the tab endpoint and the
    scheduled-report sender."""
    return [[v["vendor_name"], v["po_count"], v["bags"],
             v["lines_total_cents"], v["freight_cents"], v["tax_cents"],
             v["total_cents"]] for v in vendors]


@app.get("/api/erp/reports/spend-by-vendor")
def erp_report_spend_by_vendor():
    actor, err = _erp_check_perm("reports.read")
    if err:
        return err
    df, dt = _erp_report_dates(request.args)
    if df is None:
        return jsonify(error="from/to must be YYYY-MM-DD"), 400
    fmt = (request.args.get("format") or "json").strip().lower()
    conn = db()
    vendors, total_cents, total_pos = _erp_spend_by_vendor_data(conn, df, dt)
    conn.close()
    if fmt == "csv":
        return _erp_csv_response(
            "erp-spend-by-vendor-%s-%s.csv" % (df or "all", dt or "all"),
            _SPEND_BY_VENDOR_CSV_HEADER,
            _erp_spend_by_vendor_csv_rows(vendors))
    return jsonify({"from": df, "to": dt, "vendors": vendors,
                    "total_cents": total_cents, "po_count": total_pos})


# ---------- Wave 3 B6: scheduled report email delivery (Dept 7) ----------
# Every Dept 7 report is pull-only (open the tab, pick dates, Apply,
# Export CSV). A schedule pushes the same report, as a CSV attachment,
# to admin emails on a weekly/monthly cadence. Execution is a cron/VM
# job hitting POST /api/cron/reports/run-due with X-Cron-Secret (same
# pattern as the marketing send cron) -- there is no in-ERP scheduler,
# and no live cron job is created by this build. Delivery reuses
# send_email (Resend) with a CSV attachment; the CSV is generated
# server-side from the same report function the tab uses, never a
# second computation. Recipients are admin emails only (ADMIN_EMAILS),
# enforced at create/update time AND again at send time. Dept 9
# financial statements are excluded in v1 unless an admin explicitly
# picks profit_loss, which carries accounting.read -- checked at send
# time (admins hold accounting.read, so the check is the same
# ADMIN_EMAILS membership, re-verified because the list can change
# after the schedule was created). A failed send is logged in the
# staff audit log and never retried silently; last_sent_at only moves
# on success, so the next attempt is the next scheduled due run.

_REPORT_SCHEDULE_KEYS = {
    "sales": "Sales",
    "inventory_valuation": "Inventory valuation",
    "spend_by_vendor": "Spend by vendor",
    "profit_loss": "Profit & loss",
}
# day_of_week follows Python's date.weekday(): Monday=0 .. Sunday=6.
_REPORT_SCHEDULE_WEEKDAYS = (
    "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday",
    "Sunday")
_REPORT_SCHEDULE_EMAIL_RE = re.compile(r"^[^@\s]+@[^@\s]+\.[^@\s]+$")


def _erp_report_schedule_dict(row):
    return {
        "id": row["id"], "report_key": row["report_key"],
        "report_label": _REPORT_SCHEDULE_KEYS.get(row["report_key"],
                                                  row["report_key"]),
        "cadence": row["cadence"],
        "day_of_week": row["day_of_week"],
        "day_of_month": row["day_of_month"],
        "recipients": row["recipients"],
        "recipient_list": [e for e in (row["recipients"] or "").split(",")
                           if e.strip()],
        "last_sent_at": row["last_sent_at"] or "",
        "enabled": int(row["enabled"] or 0),
        "created_by": row["created_by"] or "",
        "created_at": row["created_at"] or "",
        "updated_by": row["updated_by"] or "",
        "updated_at": row["updated_at"] or "",
    }


def _erp_report_schedule_validate(data, base=None):
    """Validate a schedule create (base None) or update (base = the
    existing row dict). Returns (clean, None) or (None, error). A
    recipient is only valid when it is a well-formed email AND in
    ADMIN_EMAILS -- staff, customers and vendors never receive a
    scheduled report, even if an admin types the address by hand."""
    merged = {}
    if base:
        for k in ("report_key", "cadence", "day_of_week", "day_of_month",
                  "recipients", "enabled"):
            merged[k] = base.get(k)
    for k in ("report_key", "cadence", "day_of_week", "day_of_month",
              "recipients", "enabled"):
        if k in data:
            merged[k] = data.get(k)
    report_key = (merged.get("report_key") or "").strip()
    if report_key not in _REPORT_SCHEDULE_KEYS:
        return None, ("report_key must be one of: %s"
                      % ", ".join(sorted(_REPORT_SCHEDULE_KEYS)))
    cadence = (merged.get("cadence") or "").strip().lower()
    if cadence not in ("weekly", "monthly"):
        return None, "cadence must be weekly or monthly"
    day_of_week = None
    day_of_month = None
    if cadence == "weekly":
        try:
            day_of_week = int(merged.get("day_of_week"))
        except (TypeError, ValueError):
            return None, "day_of_week must be an integer 0-6 (Monday=0)"
        if day_of_week < 0 or day_of_week > 6:
            return None, "day_of_week must be an integer 0-6 (Monday=0)"
    else:
        try:
            day_of_month = int(merged.get("day_of_month"))
        except (TypeError, ValueError):
            return None, "day_of_month must be an integer 1-28"
        if day_of_month < 1 or day_of_month > 28:
            return None, "day_of_month must be an integer 1-28"
    raw_recipients = merged.get("recipients")
    if raw_recipients is None:
        return None, "recipients is required (admin emails only)"
    if len(str(raw_recipients)) > 2000:
        return None, "recipients must be 2000 characters or fewer"
    addrs = [a.strip().lower() for a in str(raw_recipients).split(",")]
    addrs = [a for a in addrs if a]
    if not addrs:
        return None, "recipients is required (admin emails only)"
    for a in addrs:
        if not _REPORT_SCHEDULE_EMAIL_RE.match(a):
            return None, "recipient %s is not a valid email address" % a
        if a not in ADMIN_EMAILS:
            return None, ("recipient %s is not an admin email -- scheduled"
                          " reports only go to admins" % a)
    seen = set()
    uniq = []
    for a in addrs:
        if a not in seen:
            seen.add(a)
            uniq.append(a)
    try:
        enabled = int(merged.get("enabled", 1))
    except (TypeError, ValueError):
        return None, "enabled must be 0 or 1"
    if enabled not in (0, 1):
        return None, "enabled must be 0 or 1"
    return {"report_key": report_key, "cadence": cadence,
            "day_of_week": day_of_week, "day_of_month": day_of_month,
            "recipients": ", ".join(uniq), "enabled": enabled}, None


def _erp_report_schedule_period(cadence, today):
    """Date window a scheduled send covers. Weekly: the 7 days ending
    today. Monthly: the whole previous calendar month (day_of_month
    is capped at 28 so the send day always exists)."""
    if cadence == "weekly":
        start = today - timedelta(days=6)
        return start.isoformat(), today.isoformat()
    first_this = today.replace(day=1)
    last_prev = first_this - timedelta(days=1)
    return last_prev.replace(day=1).isoformat(), last_prev.isoformat()


def _erp_report_schedule_is_due(sched, today):
    """Due when the schedule is enabled, today is its cadence day, and
    nothing was sent today or later (same-day re-runs are no-ops). A
    missed day is not caught up -- the next attempt is the next
    scheduled due run."""
    if not sched.get("enabled"):
        return False
    last = (sched.get("last_sent_at") or "")[:10]
    if last and last >= today.isoformat():
        return False
    if sched.get("cadence") == "weekly":
        return (sched.get("day_of_week") is not None
                and today.weekday() == sched["day_of_week"])
    if sched.get("cadence") == "monthly":
        return (sched.get("day_of_month") is not None
                and today.day == sched["day_of_month"])
    return False


def _erp_report_schedule_csv(conn, report_key, df, dt):
    """(filename, csv_text) for one scheduled report, built from the
    same report function the tab uses -- never a second computation.
    Inventory valuation ignores dates (a point-in-time snapshot)."""
    if report_key == "sales":
        _o, _w, breakdown, order_rows = _erp_sales_report_data(
            conn, df, dt, "all")
        return ("erp-sales-%s-%s.csv" % (df or "all", dt or "all"),
                _erp_csv_text(_SALES_CSV_HEADER,
                              _erp_sales_csv_rows(breakdown, order_rows)))
    if report_key == "inventory_valuation":
        items, _total = _erp_inventory_valuation(conn)
        return ("erp-inventory-valuation.csv",
                _erp_csv_text(
                    ["sku", "name", "type", "location", "on_hand",
                     "avg_cost_cents", "value_cents"],
                    [[i["sku"], i["name"], i["type"], i["location_code"],
                      i["on_hand"], i["avg_cost_cents"], i["value_cents"]]
                     for i in items]))
    if report_key == "spend_by_vendor":
        vendors, _t, _n = _erp_spend_by_vendor_data(conn, df, dt)
        return ("erp-spend-by-vendor-%s-%s.csv" % (df or "all", dt or "all"),
                _erp_csv_text(_SPEND_BY_VENDOR_CSV_HEADER,
                              _erp_spend_by_vendor_csv_rows(vendors)))
    if report_key == "profit_loss":
        rep = _acct_profit_loss(conn, df, dt)
        return ("profit-loss-%s-to-%s.csv" % (df, dt),
                _erp_csv_text(_PROFIT_LOSS_CSV_HEADER,
                              _acct_profit_loss_csv_rows(rep)))
    raise ValueError("unknown report_key %r" % (report_key,))


def _erp_send_report_schedule(conn, sched):
    """Send one scheduled report: one email per recipient, each with
    the CSV attached. Returns (ok, error, sent_count). The send-time
    permission check re-verifies every recipient is still in
    ADMIN_EMAILS -- for profit_loss that is the accounting.read check
    (admins hold accounting.read). A failure stops at the first
    recipient that fails, leaves last_sent_at untouched, and never
    retries; the caller logs it. On full success last_sent_at moves
    (the caller commits)."""
    recipients = sched.get("recipient_list") or []
    for addr in recipients:
        if addr.lower() not in ADMIN_EMAILS:
            if sched["report_key"] == "profit_loss":
                return False, ("recipient %s is no longer an admin email"
                               " and does not hold accounting.read;"
                               " refusing to send profit & loss" % addr), 0
            return False, ("recipient %s is no longer an admin email;"
                           " refusing to send" % addr), 0
    today = datetime.now(timezone.utc).date()
    df, dt = _erp_report_schedule_period(sched["cadence"], today)
    try:
        filename, csv_text = _erp_report_schedule_csv(
            conn, sched["report_key"], df, dt)
    except Exception as e:
        return False, "could not build the %s report: %s" % (
            sched["report_key"], e), 0
    label = _REPORT_SCHEDULE_KEYS.get(sched["report_key"],
                                      sched["report_key"])
    if sched["report_key"] == "inventory_valuation":
        period_text = "snapshot as of %s" % today.isoformat()
    else:
        period_text = "%s to %s" % (df, dt)
    subject = "Pop-A-Licious report: %s (%s)" % (label, period_text)
    html = ("<p>Hi,</p><p>Your scheduled Pop-A-Licious report is attached:"
            " <strong>%s</strong> (%s).</p>"
            "<p>The CSV is the same export the Reports tab produces for"
            " that period -- no second computation.</p>"
            "<p>Manage scheduled reports in the ERP: Reports &gt;"
            " Scheduled reports.</p>"
            "<p>Stay delicious,<br><strong>The Pop-A-Licious Team</strong></p>"
            % (label, period_text))
    attachments = [{"filename": filename,
                    "content": base64.b64encode(
                        csv_text.encode("utf-8")).decode("ascii")}]
    sent = 0
    for addr in recipients:
        try:
            send_email(addr, subject, html, attachments=attachments)
        except Exception as e:
            return False, ("send to %s failed after %d of %d sent: %s"
                           % (addr, sent, len(recipients), e)), sent
        sent += 1
    conn.execute(
        "UPDATE erp_report_schedules SET last_sent_at = ? WHERE id = ?",
        (datetime.now(timezone.utc).isoformat(), sched["id"]))
    return True, None, sent


