@app.post("/api/erp/reports/schedules")
def erp_report_schedule_create():
    actor, err = _require_erp_admin()
    if err:
        return err
    data = request.get_json(force=True) or {}
    clean, verr = _erp_report_schedule_validate(data)
    if verr:
        return jsonify(error=verr), 400
    now = datetime.now(timezone.utc).isoformat()
    conn = db()
    cur = conn.execute(
        "INSERT INTO erp_report_schedules (report_key, cadence, day_of_week,"
        " day_of_month, recipients, enabled, created_by, created_at)"
        " VALUES (?, ?, ?, ?, ?, ?, ?, ?)",
        (clean["report_key"], clean["cadence"], clean["day_of_week"],
         clean["day_of_month"], clean["recipients"], clean["enabled"],
         actor, now))
    row = conn.execute(
        "SELECT * FROM erp_report_schedules WHERE id = ?",
        (cur.lastrowid,)).fetchone()
    _erp_staff_audit(conn, actor, "reports.schedule_created",
                     "report_schedule", row["id"],
                     "%s %s to %s" % (row["report_key"], row["cadence"],
                                      row["recipients"]))
    conn.commit()
    conn.close()
    return jsonify(schedule=_erp_report_schedule_dict(row)), 201


@app.post("/api/erp/reports/schedules/<int:schedule_id>/update")
def erp_report_schedule_update(schedule_id):
    """Edit cadence / day / recipients / enabled. report_key is
    immutable -- delete the schedule and create a new one to change
    the report. The merged schedule is re-validated end to end, so
    switching weekly -> monthly without a day_of_month is refused."""
    actor, err = _require_erp_admin()
    if err:
        return err
    data = request.get_json(force=True) or {}
    conn = db()
    row = conn.execute(
        "SELECT * FROM erp_report_schedules WHERE id = ?",
        (schedule_id,)).fetchone()
    if not row:
        conn.close()
        return jsonify(error="schedule not found"), 404
    if ("report_key" in data
            and (data.get("report_key") or "").strip() != row["report_key"]):
        conn.close()
        return jsonify(error="report_key cannot be changed; delete the"
                       " schedule and create a new one"), 400
    clean, verr = _erp_report_schedule_validate(
        data, base=_erp_report_schedule_dict(row))
    if verr:
        conn.close()
        return jsonify(error=verr), 400
    now = datetime.now(timezone.utc).isoformat()
    conn.execute(
        "UPDATE erp_report_schedules SET cadence = ?, day_of_week = ?,"
        " day_of_month = ?, recipients = ?, enabled = ?, updated_by = ?,"
        " updated_at = ? WHERE id = ?",
        (clean["cadence"], clean["day_of_week"], clean["day_of_month"],
         clean["recipients"], clean["enabled"], actor, now, schedule_id))
    _erp_staff_audit(conn, actor, "reports.schedule_updated",
                     "report_schedule", schedule_id,
                     "%s %s to %s (enabled=%d)"
                     % (clean["report_key"], clean["cadence"],
                        clean["recipients"], clean["enabled"]))
    conn.commit()
    row = conn.execute(
        "SELECT * FROM erp_report_schedules WHERE id = ?",
        (schedule_id,)).fetchone()
    conn.close()
    return jsonify(schedule=_erp_report_schedule_dict(row))


@app.delete("/api/erp/reports/schedules/<int:schedule_id>")
def erp_report_schedule_delete(schedule_id):
    """Delete one schedule. Permanent; the frontend confirms with two
    taps. No report data is touched -- only the schedule row goes."""
    actor, err = _require_erp_admin()
    if err:
        return err
    conn = db()
    row = conn.execute(
        "SELECT * FROM erp_report_schedules WHERE id = ?",
        (schedule_id,)).fetchone()
